const thread_row_pad: f32 = 14;
const thread_reply_chrome: f32 = thread_row_pad + avatar_size + 5 + 5 + engagement_row_height + thread_row_pad + 1;
const thread_skeleton_extent: f32 = 76;
const meta_scale: f32 = meta_size / 14.5;
