pub const feed_row_chrome: f32 = row_pad_top + avatar_size + 5 + 10 + engagement_row_height + row_pad_bottom + 1;

pub const max_avatar_images = 9;
const max_media_images = 6;

/// A span of feed rows, inclusive at both ends. Named rather than anonymous so
/// the visible span and the warmed span are the same type and one can be built
/// from the other.
pub const RowRange = struct { first: usize, last: usize };

/// How many rows either side of the viewport are warmed into the disk cache.
///
/// Not a registry budget: warming claims no image id, so this is bounded by
/// bandwidth and by the per-tick fetch ceilings, not by the sixteen slots. Eight
/// is about a screen either way at the feed's row height, which is the distance
/// a flick covers before the next tick can react.
const feed_prefetch_rows: usize = 16;
/// The profile banner's own id, taken out of the avatar pool rather than
/// borrowed from either LRU.
///
/// The block above argues for ONE allocator over all sixteen slots, and that is
/// still the right end state. It is not this change. A banner is one image on a
/// screen that occludes the feed: it never scrolls, never competes with a second
/// banner, and is overwritten in place when the reader walks to another person.
/// A reserved id therefore needs no eviction pass at all, and cannot take a
/// picture the feed is using in ANY navigation order, which is exactly what
/// borrowing from the media LRU could do. Unifying here would still be writing
/// the allocator against imagined callers; a single non-scrolling consumer does
/// not exercise one.
///
/// The cost is one avatar id, and it is not observable: ids are lent only to the
/// visible window, and a window this size holds a handful of rows, so the tenth id
/// only ever lengthened the LRU tail. A reclaimed avatar returns from the disk
/// cache, not the network.
const banner_image_id: u64 = max_avatar_images + 1;
comptime {
    // The split may never promise more ids than the registry owns: overshooting
    // shows up as a silent `error.ImageRegistryFull` at the 17th registration,
    // which reads as "this author has no avatar" rather than as a budget bug.
    if (max_avatar_images + 1 + max_media_images > image_registry_slots) {
        @compileError("the image budget oversubscribes the canvas registry");
    }
}
const media_image_id_base: u64 = banner_image_id + 1;
/// What a banner is asked for and bounded to.
///
/// 512 and not a pixel more: `decodeAndRegister` scales the LONG edge to this,
/// so the worst case it can produce is `max_dim` squared, and 512x512x4 is
/// exactly the registry's 1 MiB ceiling. A larger number here would refuse
/// every banner a reader happens to have uploaded square. The band draws 660x132,
/// so this is about 1.7x on the long edge, which is the honest ceiling: 2x would
/// be 1320x264 and 1.33x over the cap.
const banner_target_px: u32 = 512;
// What each image is requested at. Avatars draw at 40pt, so asking for more
// than a couple of hundred pixels is pure waste. Feed images are bounded as a
// BOX, not just a width: the registry's budget is 1 MiB of decoded pixels, so a
// 512-wide image that happens to be tall (512x717 is a real example) still
// blows it. 480x480 leaves honest headroom under the cap.
const avatar_target_px: u32 = 128;
const media_target_px: u32 = 480;
// The largest body we accept from a fetch. The effect caps at 256 KiB anyway;
// stopping a little short keeps the decode budget for images that will fit.
const max_image_bytes = 240 * 1024;
// The registry's own ceiling on one decoded image.
const max_registered_image_bytes = 1024 * 1024;
// Animated GIFs decode every frame up front, so they are bounded twice over: by
// frame count and by total decoded bytes. An animated GIF is asked for at this
// smaller size, since it has to arrive whole inside the fetch cap.
const gif_target_px: u32 = 240;
const max_gif_frames = 64;
const max_gif_total_bytes = 24 * 1024 * 1024;
// How many play at once, and how often the shared animation timer ticks.
const max_playing_gifs = 2;
const animation_interval_ms: u32 = 80;
const animation_timer_key: u64 = 2;

const app_permissions = [_][]const u8{ native_sdk.security.permission_command, native_sdk.security.permission_view, native_sdk.security.permission_clipboard, native_sdk.security.permission_network };
const shell_views = [_]native_sdk.ShellView{
    .{ .label = canvas_label, .kind = .gpu_surface, .fill = true, .role = "Plaza canvas", .accessibility_label = "Plaza", .gpu_backend = .metal, .gpu_pixel_format = .bgra8_unorm, .gpu_present_mode = .timer, .gpu_alpha_mode = .@"opaque", .gpu_color_space = .srgb, .gpu_vsync = true },
};
/// The narrowest the window may be made, read from the manifest that enforces
/// it so there is exactly one copy of the number.
///
/// It is a create-time property, which is why it can only be declared in
/// app.zon; it is repeated on the scene because leaving it at the default here
/// would declare "no floor" for any path that re-applies the window's
/// properties. `zig build test` sweeps every screen from this width.
pub const window_min_width: f32 = @import("window_floor").manifest_min_width;

const shell_windows = [_]native_sdk.ShellWindow{.{
    .label = "main",
    .title = "Plaza",
    .width = window_width,
    .height = window_height,
    .min_width = window_min_width,
    .restore_state = false,
    .views = &shell_views,
}};
const shell_scene: native_sdk.ShellConfig = .{ .windows = &shell_windows };

// ------------------------------------------------- one-process runtime wiring
//
// A native app is a single process and a single instance, so the shared store,
// each relay's connection state, and the wall clock live as process globals,
// the Model stays pure view state (the framework reflects Model/Msg for markup
// checking). Sharing the store across the UI thread and the several ingest
// threads is safe: LMDB serialises its writers (the pool's ingests take the
// write lock one at a time) and hands readers an MVCC snapshot, and every
// `nostr.store` call is a self-contained transaction on its calling thread.

/// A relay slot's connection state.
///
/// `quiet` is the state this app used to be unable to express, and the reason a
/// green dot could be a lie: the socket is open, nothing has come down it for a
/// while, and a ping is out with no answer yet. It is not offline, because
/// nothing has failed; it is not plainly connected either, because the last
/// evidence of that is a minute old. Every shipping client the pool was
/// compared against has exactly two states here and shows the same green dot
/// over a half-open socket, so this is not a bug being fixed so much as a lie
/// being stopped.
const Conn = enum(u8) { connecting = 0, connected = 1, offline = 2, quiet = 3 };

var g_store: ?*nostr.store.Store = null;
// One connection state per relay in the pool, flipped by that relay's ingest
// thread and read by the UI thread to summarise the pool.
var g_relay_status = [_]std.atomic.Value(u8){std.atomic.Value(u8).init(@intFromEnum(Conn.connecting))} ** max_relays;

/// Whether a slot holds a socket, whatever the socket is doing. A relay that has
/// gone quiet has not dropped: nothing has failed, and counting it as offline
/// would put the whole app behind an "offline, reconnecting" banner because the
/// night was slow.
fn connHolds(state: Conn) bool {
    return state == .connected or state == .quiet;
}

/// Arrival order inside a thread level: the build a reply first appeared in, so a
/// late arrival lands after what has already been read instead of jumping into the
/// middle of it. The redesign is explicit about this ("appended, never reordered"),
/// and a reply that arrives late is often OLDER than replies already on screen, so
/// created_at alone would move the ground under the reader.
///
/// One table PER LEVEL, keyed by that level's root: a thread stays mounted while
/// the reader walks into a sub-thread and back, and it has to come back in the
/// order they left it. A single shared table meant opening any reply reshuffled
/// the conversation underneath it.
const ArrivalTable = struct {
    const Entry = struct {
        used: bool = false,
        id: [32]u8 = [_]u8{0} ** 32,
        batch: u32 = 0,
    };
    /// The level's root, so a table found holding a different thread is discarded
    /// rather than trusted.
    root: [32]u8 = [_]u8{0} ** 32,
    entries: [thread_reply_cap]Entry = [_]Entry{.{}} ** thread_reply_cap,
    batch: u32 = 0,
    /// Whether this level's own fetch has settled. Everything collected before it
    /// does is ONE batch, in written order, however the relays interleave it;
    /// only what shows up afterwards is genuinely late.
    settled: bool = false,
};
/// One per mounted level: the back-stack plus the open thread.
var g_arrival: [thread_depth_max + 1]ArrivalTable = [_]ArrivalTable{.{}} ** (thread_depth_max + 1);

/// A fresh arrival table, for a test that drives the real stamping.
pub fn arrivalTableForTest() ArrivalTable {
    return .{};
}

pub fn stampArrivalForTest(table: *ArrivalTable, notes: []Note, settled: bool) void {
    stampArrival(table, notes, settled);
}

/// The arrival table for `level`, reset if it is holding a different thread.
fn arrivalTableFor(level: usize, root: [32]u8) *ArrivalTable {
    const table = &g_arrival[@min(level, g_arrival.len - 1)];
    if (!std.mem.eql(u8, &table.root, &root)) table.* = .{ .root = root };
    return table;
}

/// Stamps each note with the batch it first appeared in and puts the level in
/// reading order. One pass over the notes: an id the level has not shown before
/// opens the next batch (unless the level is still loading, when everything
/// belongs to the first), and every id after it in the same build joins it.
///
/// `settled` is whether this level's own fetch has finished. Until it has, the
/// relays are still streaming the thread's opening state, and treating each
/// 80ms slice of that stream as a batch would pin the conversation into
/// relay-answer order, which is precisely what this exists to prevent.
fn stampArrival(table: *ArrivalTable, notes: []Note, settled: bool) void {
    var opened = false;
    for (notes) |*note| {
        if (arrivalOf(table, note.event_id)) |batch| {
            note.arrival = batch;
            continue;
        }
        if (!opened) {
            if (table.settled) table.batch += 1;
            opened = true;
        }
        note.arrival = claimArrival(table, note.event_id, notes);
    }
    if (settled) table.settled = true;
    sortThreadNotes(notes);
}

/// The batch `id` was first seen in, or null when this level has not shown it.
fn arrivalOf(table: *const ArrivalTable, id: [32]u8) ?u32 {
    for (&table.entries) |*e| {
        if (e.used and std.mem.eql(u8, &e.id, &id)) return e.batch;
    }
    return null;
}

/// Records `id` at the current batch. The table holds exactly as many entries as
/// a level can show, so a full table means it is holding ids that have since left
/// the set (the fetch cap re-cuts as the store grows): those are swept, and the
/// claim retried. Failing that the id takes the current batch unrecorded, which
/// still reads in order for this build.
fn claimArrival(table: *ArrivalTable, id: [32]u8, live: []const Note) u32 {
    for (&table.entries) |*e| {
        if (!e.used) {
            e.* = .{ .used = true, .id = id, .batch = table.batch };
            return e.batch;
        }
    }
    for (&table.entries) |*e| {
        var still_here = false;
        for (live) |*note| {
            if (std.mem.eql(u8, &note.event_id, &e.id)) {
                still_here = true;
                break;
            }
        }
        if (!still_here) e.* = .{};
    }
    for (&table.entries) |*e| {
        if (!e.used) {
            e.* = .{ .used = true, .id = id, .batch = table.batch };
            return e.batch;
        }
    }
    return table.batch;
}

/// A thread level's reading order: the batch a reply arrived in, then when it was
/// written. ONE comparator, called by the open thread and by every level under
/// it, so a level reads the same both ways round.
pub fn sortThreadNotes(notes: []Note) void {
    std.mem.sort(Note, notes, {}, struct {
        fn lt(_: void, a: Note, b: Note) bool {
            // Arrival first, then chronological within a batch: a reply that
            // showed up later sits after the ones already read, even when it was
            // written earlier.
            if (a.arrival != b.arrival) return a.arrival < b.arrival;
            return a.created_at < b.created_at;
        }
    }.lt);
}

/// Sets relay `index`'s live connection state.
fn setRelayStatus(index: usize, state: Conn) void {
    const was: Conn = @enumFromInt(g_relay_status[index].load(.monotonic));
    g_relay_status[index].store(@intFromEnum(state), .monotonic);
    // A relay coming back is the event a queued note has been waiting for. The
    // backoff was only ever reset by editing the relay list, so a note that had
    // widened out to an hourly retry stayed on that schedule even when the
    // network returned a second later.
    //
    // Coming back from QUIET does not count. A relay answering the keepalive it
    // was sent is not news about the network, it is news about that one socket,
    // and treating it as a recovery would let a quiet pool reset the queue's
    // ladder every minute forever.
    if (state == .connected and was != .connected and was != .quiet) wakeOutboxBackoff();
}

// -- Knowing a socket is still there -----------------------------------------
//
// A relay's ingest thread blocks in `receive` until the relay says something.
// If the peer goes away without closing, that thread waits forever and the chip
// stays green: no error, no timeout, no reconnect. Nothing in this app could
// tell that apart from a quiet night.
//
// Nothing can tell it apart from inside that thread either, which is the whole
// difficulty. A thread waiting on a dead peer cannot notice anything. So a
// separate one watches the pool: it sends the ping, and it is the one that can
// still act when no answer comes.
//
// The numbers are Amethyst's, who surveyed 122 relays and found idle timeouts
// clustered at roughly 60, 120, 240, 300 and 600 seconds, and who report that a
// ping only reliably holds a connection open when its interval is at most about
// half the timeout. Thirty seconds sits under half of the shortest tier. Ninety
// is three missed answers, which is the point at which a socket that has not
// said a word to three pings is not coming back.
const relay_ping_after_ms: i64 = 30_000;
const relay_dead_after_ms: i64 = 90_000;
/// How often the keeper looks. Short enough that ninety seconds means ninety,
/// long enough to cost nothing.
const relay_keeper_tick_ms: u64 = 5_000;

/// The live connection for each slot, for the keeper and nothing else.
///
/// Published by the thread that dialled it and cleared by that same thread
/// before the connection is freed, both under the slot's lock, and the keeper
/// holds that lock for as long as it touches the pointer. Without it the keeper
/// can be inside `ping` on a `Relay` whose owner has already returned and run
/// its `deinit`.
var g_relay_live: [max_relays]?*nostr.relay.Relay = @splat(null);
var g_relay_live_lock: [max_relays]std.atomic.Value(bool) = @splat(std.atomic.Value(bool).init(false));
/// When each slot was last pinged, so a socket that stops answering is pinged
/// once per interval rather than once per keeper tick.
var g_relay_pinged_ms: [max_relays]i64 = @splat(0);

fn lockLiveRelay(index: usize) void {
    while (g_relay_live_lock[index].cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockLiveRelay(index: usize) void {
    g_relay_live_lock[index].store(false, .release);
}

/// Offers this slot's connection to the keeper, or withdraws it. The owning
/// thread calls this with the connection on the way in and with null on the way
/// out, BEFORE the connection is freed.
fn publishLiveRelay(index: usize, relay: ?*nostr.relay.Relay) void {
    lockLiveRelay(index);
    defer unlockLiveRelay(index);
    g_relay_live[index] = relay;
    g_relay_pinged_ms[index] = 0;
}

/// What the keeper decides for one slot, given how long that connection has
/// been silent and when it was last pinged. Pulled out so it can be asserted
/// without a socket, a thread or a clock.
const KeeperAction = enum { leave_it, ping, give_up };

fn keeperAction(idle_ms: ?i64, since_ping_ms: ?i64) KeeperAction {
    // Nothing has ever arrived on this connection. That is the window between
    // the handshake and the relay's first word, not a stall, and treating a
    // missing measurement as an infinite one would cut off every relay that
    // took a moment to answer.
    const idle = idle_ms orelse return .leave_it;
    if (idle >= relay_dead_after_ms) return .give_up;
    if (idle < relay_ping_after_ms) return .leave_it;
    // Silent past the interval. Ping, but only once per interval: at a five
    // second tick a socket that has stopped answering would otherwise be pinged
    // twelve more times on its way to being declared dead.
    const since = since_ping_ms orelse return .ping;
    return if (since >= relay_ping_after_ms) .ping else .leave_it;
}

/// Watches every slot's connection for silence: pings one that has gone quiet,
/// and cuts off one that will not answer.
fn relayKeeper(gpa: std.mem.Allocator) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();

    while (true) {
        io.sleep(std.Io.Duration.fromMilliseconds(relay_keeper_tick_ms), .awake) catch {};
        const now = std.Io.Timestamp.now(io, .awake).toMilliseconds();
        for (0..max_relays) |i| {
            lockLiveRelay(i);
            defer unlockLiveRelay(i);
            const relay = g_relay_live[i] orelse continue;
            const idle = relay.idleMs(io);
            const since_ping: ?i64 = if (g_relay_pinged_ms[i] == 0) null else now - g_relay_pinged_ms[i];
            switch (keeperAction(idle, since_ping)) {
                .leave_it => {},
                .ping => {
                    // A failed write is not a verdict on its own; the silence
                    // deadline is. Letting a write error tear the socket down
                    // here would race the owning thread's own error handling.
                    relay.ping(io) catch {};
                    g_relay_pinged_ms[i] = now;
                    setRelayStatus(i, .quiet);
                },
                .give_up => {
                    // Half-close, so the owner's blocked `receive` returns and
                    // it reconnects through its own path. NOT deinit: the owner
                    // still holds this and has to unwind.
                    relay.shutdown(io);
                    g_relay_live[i] = null;
                    g_relay_pinged_ms[i] = 0;
                    setRelayStatus(i, .offline);
                },
            }
        }
    }
}

/// How often a returning relay may pull the queue's backoff back to zero.
///
/// A relay that accepts the handshake and drops the socket reconnects every
/// three seconds, and without this each of those would reset every note to an
/// immediate retry: the widening delay would never widen and a dead relay would
/// be dialled continuously. Amethyst has the same guard for the same reason.
const outbox_wake_min_s: i64 = 60;
var g_outbox_woke_at: std.atomic.Value(i64) = .init(0);
/// Whether a wake has happened at all. A separate flag rather than a zero
/// sentinel, because zero is a real timestamp: `nowSeconds` returns it whenever
/// there is no io, and a rate limit that stops working at a particular clock
/// value is not a rate limit.
var g_outbox_woke_ever = std.atomic.Value(bool).init(false);

/// Puts every unacked note back at the front of the retry ladder.
fn wakeOutboxBackoff() void {
    const now = nowSeconds();
    if (g_outbox_woke_ever.load(.monotonic) and
        now -| g_outbox_woke_at.load(.monotonic) < outbox_wake_min_s) return;
    g_outbox_woke_ever.store(true, .monotonic);
    g_outbox_woke_at.store(now, .monotonic);

    outboxLock();
    defer outboxUnlock();
    var changed = false;
    for (&g_outbox) |*e| {
        if (!e.used or e.acked != 0 or e.rounds == 0) continue;
        e.rounds = 0;
        changed = true;
    }
    if (changed) _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// Whether the reader has paused the pool. Read by every relay thread between
/// reconnect attempts, so a pause takes hold without tearing a socket down
/// mid-message.
var g_relays_paused = std.atomic.Value(bool).init(false);

fn setRelaysPaused(paused: bool) void {
    g_relays_paused.store(paused, .monotonic);
}

pub fn relaysPaused() bool {
    return g_relays_paused.load(.monotonic);
}

/// A relay's round-trip time in milliseconds, sampled REQ to EOSE and kept as a
/// small ring so the bar can show a median rather than the last spike. Zero means
/// no sample yet.
const rtt_samples = 8;
/// The latency probe: a query whose round trip is the number the status bar
/// shows, and how often each relay is asked for it.
const probe_sub = "plaza-ping";
const probe_interval_ms: i64 = 20_000;

/// What the probe asks for: one event id that cannot exist.
///
/// The relay does an index lookup, finds nothing, and answers EOSE. That round
/// trip is the number the bar wants, and it costs one lookup and zero events.
///
/// It used to ask `{"kinds":[1],"limit":1}`: no authors, no since, no until, and
/// nothing ever closed it. A REQ stays live past EOSE, so every relay then
/// pushed Plaza every kind:1 it received, from anyone, for the life of the
/// connection. Each one was parsed, allocated and put through a full Schnorr
/// verify before being dropped for not being a note this reader is watching. It
/// also held a subscription slot on every relay permanently, and an unauthored
/// global request for all text notes is not a thing an ordinary client sends.
///
/// An all-zero id is a value no event can have: the id IS the hash, so having
/// one would mean holding a SHA-256 preimage of thirty-two zero bytes.
const probe_ids = [_][32]u8{[_]u8{0} ** 32};

/// The probe's REQ. One filter, naming only that id, capped at one event so even
/// a relay that answered it somehow could not turn the probe into a stream.
pub fn probeFilters() [1]nostr.filter.Filter {
    return .{.{ .ids = &probe_ids, .limit = 1 }};
}
var g_relay_rtt = [_][rtt_samples]std.atomic.Value(u16){[_]std.atomic.Value(u16){std.atomic.Value(u16).init(0)} ** rtt_samples} ** max_relays;
var g_relay_rtt_at = [_]std.atomic.Value(u8){std.atomic.Value(u8).init(0)} ** max_relays;

/// Records one round trip for relay `index`. Stored as milliseconds PLUS ONE, so
/// a sub-millisecond answer (a warm or local relay, truncated to 0) is a reading
/// rather than an empty slot.
pub fn recordRelayRttForTest(index: usize, ms: u64) void {
    recordRelayRtt(index, ms);
}

pub fn clearRelayRttForTest(index: usize) void {
    clearRelayRtt(index);
}

fn recordRelayRtt(index: usize, ms: u64) void {
    if (index >= max_relays) return;
    const slot = g_relay_rtt_at[index].load(.monotonic) % rtt_samples;
    g_relay_rtt[index][slot].store(@intCast(@min(ms, std.math.maxInt(u16) - 1) + 1), .monotonic);
    g_relay_rtt_at[index].store(slot +% 1, .monotonic);
}

/// Forgets relay `index`'s samples. Called when it drops, so the bar never shows
/// a number measured on a connection that no longer exists.
fn clearRelayRtt(index: usize) void {
    if (index >= max_relays) return;
    for (&g_relay_rtt[index]) |*sample| sample.store(0, .monotonic);
}

/// Relay `index`'s median round trip, or null when it has never answered.
pub fn relayRttMs(index: usize) ?u16 {
    if (index >= max_relays) return null;
    var seen: [rtt_samples]u16 = undefined;
    var n: usize = 0;
    for (&g_relay_rtt[index]) |*sample| {
        const v = sample.load(.monotonic);
        if (v != 0) {
            seen[n] = v - 1;
            n += 1;
        }
    }
    if (n == 0) return null;
    std.mem.sort(u16, seen[0..n], {}, std.sort.asc(u16));
    return median(seen[0..n]);
}

/// The middle of a sorted run, averaging the two middles for an even count so a
/// four-sample reading is not silently the third-fastest.
fn median(sorted: []const u16) u16 {
    const mid = sorted.len / 2;
    if (sorted.len % 2 == 1) return sorted[mid];
    return @intCast((@as(u32, sorted[mid - 1]) + @as(u32, sorted[mid])) / 2);
}

/// The pool's latency: the median across every relay that has answered. The
/// redesign asks for the median WRITE relay, the number that predicts how fast a
/// post lands; until a relay list with read/write markers exists, every relay in// The UI thread's Io, for wall-clock time when rendering relative timestamps
// (set once in `main`, read only on the UI thread).
var g_io: ?std.Io = null;
// The process environment, stashed in `main` so the onboarding "create identity"
// action can resolve `$HOME` and open the store off the UI thread event loop.
var g_environ: ?*const std.process.Environ.Map = null;
// The event count at the last feed rebuild, a cheap "did the store change?"
// signal so a tick that changed nothing skips the query and note rebuild.
var g_last_count: usize = std.math.maxInt(usize);
/// The same, for whichever level is open. Separate from `g_last_count` because
/// the feed consumes that one, and a level opened after a feed rebuild would
/// otherwise see an unchanged count and never fill.
var g_last_level_count: usize = std.math.maxInt(usize);

// -- What just arrived -------------------------------------------------------
//
// The feed used to answer "has anything changed" by asking the store for the
// whole thing again, once a second, on the render thread: a cursor per followed
// author and a linear pick across all of them per note returned. Measured in the
// library's benchmark at 2049 authors, ReleaseFast, best of fifty: 1.46 ms for a
// screenful and 10.8 ms once the reader has paged twenty pages down, against a
// 16.7 ms frame. The cost is set by how many people the reader follows, not by
// how much actually changed, and almost nothing changes between two ticks.
//
// So the ingest threads say what landed instead. No reference client re-reads
// its store on arrival: Notedeck polls note keys ingested since the last poll
// and merges them, Jumble splices the arriving event into a sorted array, and
// Amethyst hands its filter only the new items. This is that, with the ids
// carried across the thread boundary and the events read back by id, which is a
// direct read each rather than a walk of the follow list.

/// Ids of kind:1 events an ingest thread has just added to the store.
///
/// Sized well past a busy second so the common case never overflows. A backfill
/// does overflow it, and that is not a loss: overflow means the list in hand
/// cannot be brought up to date by splicing, so the next rebuild reads the store
/// in full, which is exactly what a backfill wants anyway.
const feed_arrival_cap = 1024;
var g_arrival_lock = std.atomic.Value(bool).init(false);
var g_arrival_ids: [feed_arrival_cap][32]u8 = undefined;
var g_arrival_len: usize = 0;
var g_arrival_overflowed: bool = false;
/// Read on every tick without taking the lock, so a tick with nothing waiting
/// costs one atomic load.
var g_arrival_pending = std.atomic.Value(bool).init(false);
/// The render thread's private copy, drained under the lock.
var g_arrival_taken: [feed_arrival_cap][32]u8 = undefined;

/// The list in hand is no longer a valid starting point: read the store in full
/// on the next rebuild. Safe from any thread.
///
/// Set by everything that changes what the feed is a view OF (the author set,
/// the identity, how deep the reader has paged) and by a deletion, which is the
/// one arrival a splice cannot express: splicing only ever adds.
var g_feed_rebuild_all = std.atomic.Value(bool).init(true);

fn invalidateFeed() void {
    g_feed_rebuild_all.store(true, .release);
}

fn lockArrivals() void {
    while (g_arrival_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockArrivals() void {
    g_arrival_lock.store(false, .release);
}

fn noteFeedArrival(id: [32]u8) void {
    lockArrivals();
    defer unlockArrivals();
    if (g_arrival_len >= g_arrival_ids.len) {
        g_arrival_overflowed = true;
    } else {
        g_arrival_ids[g_arrival_len] = id;
        g_arrival_len += 1;
    }
    g_arrival_pending.store(true, .release);
}

/// Empties the buffer into the render thread's copy and reports whether anything
/// was dropped on the way in.
///
/// Everything, in one locked step, at the top of the rebuild. That is what makes
/// it safe: an event landing while the rebuild is running goes into the emptied
/// buffer and is spliced on the next tick, rather than falling between the query
/// and the clear. Taking the count first and clearing after the query would lose
/// exactly those.
fn takeFeedArrivals() struct { n: usize, lost: bool } {
    lockArrivals();
    defer unlockArrivals();
    const n = g_arrival_len;
    @memcpy(g_arrival_taken[0..n], g_arrival_ids[0..n]);
    const lost = g_arrival_overflowed;
    g_arrival_len = 0;
    g_arrival_overflowed = false;
    g_arrival_pending.store(false, .release);
    return .{ .n = n, .lost = lost };
}

/// Forgets what is waiting. For a reset that is about to rebuild from nothing.
fn clearFeedArrivals() void {
    lockArrivals();
    defer unlockArrivals();
    g_arrival_len = 0;
    g_arrival_overflowed = false;
    g_arrival_pending.store(false, .release);
}

// Plaza's local identity: the keypair that signs composed notes. Loaded in
// `main` (returning user) or created by the onboarding action, both on the UI
// thread, and read only there, so no synchronisation is needed. The signer holds
// a secp256k1 context (not shared across threads); the publish path never signs,
// it forwards an already-signed event, so it needs neither. This is the
// zero-config local signer; connecting an external signer (Notary, over NIP-46,
// so the key never touches the client) is the next onboarding option, and swaps
// in at `signAndPublish` below.
var g_identity_signer: ?nostr.keys.Signer = null;
var g_identity_kp: ?nostr.keys.KeyPair = null;
var g_identity_npub_buf: [24]u8 = undefined;
var g_identity_npub_len: usize = 0;

// How composed notes are signed: with the local key, or remotely over NIP-46 by
// an external signer (Notary) so the secret key never enters Plaza. `submitPost`
// branches on this; it is set once during onboarding.
const SignerKind = enum { local, remote, helper };
var g_signer_kind: SignerKind = .local;

// Remote-signer (NIP-46) connection state, set at connect time and read by the
// background threads. The ephemeral client keypair is Plaza's transport identity
// with the bunker (never the user's key); the user's identity is the bunker's
// own pubkey. Each worker thread makes its own secp256k1 signer, only these
// bytes are shared.
var g_remote_client_kp: ?nostr.keys.KeyPair = null;
var g_remote_pubkey: [32]u8 = undefined;
var g_remote_relay_buf: [256]u8 = undefined;
var g_remote_relay_len: usize = 0;
var g_remote_secret_buf: [128]u8 = undefined;
var g_remote_secret_len: usize = 0;
// 0 idle, 1 connecting, 2 connected, 3 failed. Drives the onboarding status line.
var g_remote_status = std.atomic.Value(u8).init(0);

// ------------------------------------------------- the isolated signer helper
//
// plaza-signer holds the key in a separate PROCESS, reached over loopback HTTP.
// Plaza spawns it at launch, writes it a 0600 bearer token, and (for now)
// health-checks it; routing the actual signing through it comes next. The port
// is Plaza-specific (not notary's 8787), so a standalone Notary and the
// built-in one never collide.
const helper_port: u16 = 8790;
const helper_spawn_key: u64 = 40;
const helper_poll_key: u64 = 41;
// The daemon binary (a sibling of Plaza's own executable) and the shared token,
// resolved once in main and read by boot/tick.
var g_helper_bin_buf: [1024]u8 = undefined;
var g_helper_bin_len: usize = 0;
var g_helper_token_buf: [64]u8 = undefined;
var g_helper_token_len: usize = 0;
var g_helper_state_dir_buf: [512]u8 = undefined;
var g_helper_state_dir_len: usize = 0;
var g_helper_token_path_buf: [512]u8 = undefined;
var g_helper_token_path_len: usize = 0;
// 0 starting, 1 uninitialized (reachable, no key yet), 2 ready (holds a key),
// 3 unreachable. Reachable at all (1 or 2) is what proves the loopback IPC.
var g_helper_state = std.atomic.Value(u8).init(0);
/// When the signed-in health check last ran, and how often it may run. The
/// signed-out poll is every tick (it is waiting for a key to appear); this is the
/// quieter beat that keeps the status bar honest afterwards.
var g_helper_polled_at: i64 = 0;
const helper_health_interval_s: i64 = 5;

fn helperBin() []const u8 {
    return g_helper_bin_buf[0..g_helper_bin_len];
}
fn helperToken() []const u8 {
    return g_helper_token_buf[0..g_helper_token_len];
}

/// Whether the launch probe found the keyholder daemon beside Plaza.
///
/// `.unprobed` is not a third answer, it is "nobody has looked yet", and it
/// reads as present on purpose: the probe runs in `main` before the first view,
/// so the only build that sees this value is the test binary, and a suite that
/// never launches an app should not render every join screen as a broken
/// install.
const KeyholderProbe = enum { unprobed, found, missing };
var g_keyholder: KeyholderProbe = .unprobed;

/// True when the daemon that would hold the key is not installed beside Plaza.
///
/// Worth a separate word from the daemon being unreachable, which is what
/// `g_helper_state` tracks. Unreachable is a moment: the daemon takes a beat to
/// come up, and `g_helper_setup` exists to hold an intent until it answers.
/// Missing is permanent and known at launch, so anything that queues and waits
/// on it is a button that does nothing, forever, with no way for the reader to
/// find out why.
fn keyholderMissing() bool {
    return g_keyholder == .missing;
}

/// Records that there is no keyholder.
///
/// Only the flag. It is tempting to settle `g_helper_state` here as well, since
/// with no daemon the health check never runs and that state is pinned at its
/// initial 0 forever. But every reader of it already treats 0 and "unreachable"
/// alike, so the store would change nothing that any test could tell apart, and
/// a second mechanism nothing can distinguish from its absence is not a
/// safeguard. The one reader that DID read 0 wrongly is `signerStatus`, and it
/// asks this question directly now.
fn markKeyholderMissing() void {
    g_keyholder = .missing;
}

/// `false` restores the unprobed state rather than claiming a keyholder was
/// found, because in a test nothing has looked for one.
pub fn setKeyholderMissingForTest(missing: bool) void {
    g_keyholder = if (missing) .missing else .unprobed;
}

/// The directory holding Plaza's own executable, which is where both helper
/// binaries ship.
///
/// NOT `dirname(argv[0])`. argv[0] is whatever the launcher felt like passing:
/// a PATH lookup hands over a bare name with no directory in it at all, and a
/// symlink hands over the link's directory rather than the bundle's. Both send
/// the probe below looking somewhere the helpers were never installed, and the
/// answer it comes back with is "this install has no keyholder" about an install
/// that is perfectly fine. `executableDirPath` asks the OS where this process
/// actually came from, and follows symlinks to get there.
fn exeDir(io: std.Io, buf: []u8) ?[]const u8 {
    const n = std.process.executableDirPath(io, buf) catch return null;
    return buf[0..n];
}

/// Writes `dir/name` into `out` if that file is there, and returns its length;
/// 0 when it is not.
///
/// The access check is the whole point. Formatting a path is not finding a
/// binary, and a spawn of a file that is not there is reported on stderr and
/// nowhere else, so the app carries on believing it has a helper it does not
/// have. That is precisely how a bundle shipped with no keyholder in it.
fn resolveSibling(io: std.Io, out: []u8, dir: []const u8, name: []const u8) usize {
    const path = std.fmt.bufPrint(out, "{s}/{s}", .{ dir, name }) catch return 0;
    std.Io.Dir.cwd().access(io, path, .{}) catch return 0;
    return path.len;
}

pub fn resolveSiblingForTest(io: std.Io, out: []u8, dir: []const u8, name: []const u8) usize {
    return resolveSibling(io, out, dir, name);
}

pub fn exeDirForTest(io: std.Io, buf: []u8) ?[]const u8 {
    return exeDir(io, buf);
}

/// Adopts the Notary signer kind for the active test identity, so the status
/// line can be asked what it says about a daemon that is not there.
pub fn setSignerKindHelperForTest() void {
    g_signer_kind = .helper;
}

pub fn setSignerKindLocalForTest() void {
    g_signer_kind = .local;
}

pub fn signerStatusLabelForTest() []const u8 {
    return signerStatus().label;
}

/// Resolves the daemon (a sibling of Plaza's own executable, so it works both
/// from the dev tree and a packaged bundle), mints a fresh bearer token, and
/// writes it 0600 under ~/.plaza.
///
/// When the daemon is not there, this returns having set NOTHING: no path, no
/// token, no state dir. Every caller downstream is already guarded on one of
/// those being empty, so a missing keyholder becomes a quiet no-op at the effect
/// layer and a said-out-loud one in the join ladder, rather than a spawn of a
/// path that does not exist.
fn resolveHelper(init: std.process.Init) void {
    // The daemon lives beside Plaza's own executable.
    var dir_buf: [1024]u8 = undefined;
    const dir = exeDir(init.io, &dir_buf) orelse return markKeyholderMissing();
    g_helper_bin_len = resolveSibling(init.io, &g_helper_bin_buf, dir, "plaza-signer");
    if (g_helper_bin_len == 0) return markKeyholderMissing();
    g_keyholder = .found;

    const home = init.environ_map.get("HOME") orelse ".";
    const state_dir = std.fmt.bufPrint(&g_helper_state_dir_buf, "{s}/.plaza", .{home}) catch return;
    g_helper_state_dir_len = state_dir.len;
    const token_path = std.fmt.bufPrint(&g_helper_token_path_buf, "{s}/.plaza/signer.token", .{home}) catch return;
    g_helper_token_path_len = token_path.len;

    // A fresh 32-byte token, hex-encoded, so a stray process on the machine
    // cannot drive the signer even if it guesses the port.
    var raw: [32]u8 = undefined;
    init.io.randomSecure(&raw) catch return;
    var hexbuf: [64]u8 = undefined;
    _ = hexLower(&hexbuf, raw);
    @memcpy(g_helper_token_buf[0..64], &hexbuf);
    g_helper_token_len = 64;

    var d = plazaDir(init.io, init.environ_map) catch return;
    defer d.close(init.io);
    d.writeFile(init.io, .{
        .sub_path = "signer.token",
        .data = &hexbuf,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch return;
}

// The Notary ceremony window binary. In a packaged app it sits beside Plaza in
// Contents/MacOS; in the dev tree it is the sub-project's own build output.
var g_notary_win_buf: [1024]u8 = undefined;
var g_notary_win_len: usize = 0;
const notary_spawn_key: u64 = 44;
const helper_reset_key: u64 = 45;
// Set on logout, so the health-check does not re-adopt the daemon's key before
// the async /reset lands. Cleared when the user explicitly signs in again.
var g_logged_out: bool = false;

/// WHICH key signed out, held until the daemon confirms it no longer has it.
///
/// The bare latch above was the only thing keeping a signed-out key out, and
/// `beginCreate` clears it before any new key exists. `helperReset` is
/// fire-and-forget with no response handler, and the SDK drops a rejected effect
/// with no trace when every slot is busy, which Plaza can reach on a frame that
/// is also fetching avatars, NIP-05 checks and media. So: reset lost, latch
/// dropped by pressing Create, and one second later the poll re-adopted the key
/// the reader had just left. Their create fails with AlreadyInitialized, nothing
/// says so, and the next note goes out under the old identity.
///
/// A pubkey is the precise version of that latch. It is cleared the moment the
/// daemon reports itself uninitialized, which is the only honest evidence the
/// reset actually landed, so re-importing the SAME key deliberately still works.
var g_logged_out_pk: ?[32]u8 = null;
/// How many times a lost reset is re-sent before giving up and staying signed
/// out. Bounded because a daemon that refuses forever must not be asked forever.
const logout_reset_retries = 5;
var g_logout_reset_tries: u8 = 0;
/// A lost reset waiting to be re-sent from the tick, which is where `Effects`
/// is reachable. The health-check that notices only has the response.
var g_logout_reset_due: bool = false;

fn resolveNotaryWindow(init: std.process.Init) void {
    var dir_buf: [1024]u8 = undefined;
    const dir = exeDir(init.io, &dir_buf) orelse return;
    // Packaged: a sibling. Dev: the sub-project's own zig-out, because unlike
    // the daemon it is built by a separate build.zig and never lands in Plaza's
    // bin directory. Sibling first, that being the shipped layout.
    g_notary_win_len = resolveSibling(init.io, &g_notary_win_buf, dir, "notary-window");
    if (g_notary_win_len != 0) return;
    g_notary_win_len = resolveSibling(init.io, &g_notary_win_buf, dir, "../../notary-window/zig-out/bin/notary-window");
}

/// Whether there is a Notary holding this account's key AND a window to show it
/// in. Both halves matter: a remote signer is somebody else's process on
/// somebody else's machine and Notary has nothing to say about it, and an
/// install that arrived without the window would offer a press that opens
/// nothing.
pub fn openNotaryAvailable() bool {
    return g_signer_kind == .helper and g_notary_win_len > 0;
}

/// Whether the ceremony window is the right place to take a pasted key. Not
/// when there is no window, and not when there is no daemon behind it either:
/// handing the paste to the keyholder is the window's entire job, so with no
/// keyholder it is a window that can only fail, over a key the reader typed
/// correctly. The in-Plaza field is the honest destination then.
fn ceremonyCanTakeKey() bool {
    return g_notary_win_len > 0 and !keyholderMissing();
}

pub fn ceremonyCanTakeKeyForTest() bool {
    return ceremonyCanTakeKey();
}

/// Pretends the key is held by Notary, by a remote signer, or by Plaza itself.
/// Pretends this session connected to `pubkey`'s bunker.
pub fn setRemotePubkeyForTest(pubkey: [32]u8) void {
    g_remote_pubkey = pubkey;
}

/// Hands one NIP-46 response event to the listener's handler, as a relay would.
/// The generation is the live one, so only the checks under test can reject it.
pub fn deliverNip46ResponseForTest(
    signer: nostr.keys.Signer,
    client_kp: nostr.keys.KeyPair,
    ev: nostr.event.Event,
) void {
    handleNip46Response(
        std.heap.page_allocator,
        signer,
        client_kp,
        ev,
        g_remote_generation.load(.acquire),
    );
}

pub fn setSignerKindForTest(kind: []const u8) void {
    g_signer_kind = if (std.mem.eql(u8, kind, "helper"))
        .helper
    else if (std.mem.eql(u8, kind, "remote"))
        .remote
    else
        .local;
}

/// Pretends the ceremony window was (or was not) found beside Plaza.
pub fn setNotaryWindowFoundForTest(found: bool) void {
    g_notary_win_len = if (found) "/nonexistent/notary-window".len else 0;
    if (found) @memcpy(g_notary_win_buf[0.."/nonexistent/notary-window".len], "/nonexistent/notary-window");
}

/// Whether a helper setup is sitting queued, waiting for the daemon to answer.
pub fn helperSetupQueuedForTest() bool {
    return g_helper_setup != .none;
}

/// What the Notary window is being opened for. `status` is not a ceremony at
/// all: it makes no key, takes none and resets none, it only asks the daemon
/// what it is holding. It shares the spawn key with the two that are ceremonies,
/// so there is never more than one Notary window on screen.
const Ceremony = enum { import_key, create_key, status };

/// Opens the Notary ceremony window: a separate process, so key material never
/// enters Plaza on either path. The window reads the token itself and talks to
/// the daemon; Plaza adopts the identity when the key appears (see
/// handleHelperPubkey).
///
/// The window OWNS its ceremony, including the create. It would be less code for
/// Plaza to mint the key and let the window merely announce it, but only the side
/// that made the request can tell a key it just minted from a key that was
/// already sitting in the daemon: a window watching /pubkey sees "ready" either
/// way, and would introduce somebody's leftover key as the reader's new identity.
fn spawnNotaryWindow(fx: *Effects, ceremony: Ceremony) void {
    if (g_notary_win_len == 0) return;
    const bin = g_notary_win_buf[0..g_notary_win_len];
    // Two calls rather than one with a computed argv: `&.{...}` over runtime
    // values is a pointer to a temporary, and handing the effect layer one that
    // outlives its scope is the kind of bug that shows up as a garbled argv on
    // somebody else's machine.
    // `on_exit` is not optional here. The SDK REJECTS a spawn whose key already
    // has a live process, and a rejection is reported through this callback and
    // nowhere else: without it, pressing "Create your identity" while a Notary
    // window is already open did nothing at all, silently, and left the reader on
    // the guest feed having pressed the app's primary call to action.
    switch (ceremony) {
        .import_key => fx.spawn(.{
            .key = notary_spawn_key,
            .argv = &.{bin},
            .output = .collect,
            .on_exit = Effects.exitMsg(.notary_exited),
        }),
        .create_key => fx.spawn(.{
            .key = notary_spawn_key,
            .argv = &.{ bin, "--create" },
            .output = .collect,
            .on_exit = Effects.exitMsg(.notary_exited),
        }),
        .status => fx.spawn(.{
            .key = notary_spawn_key,
            .argv = &.{ bin, "--status" },
            .output = .collect,
            .on_exit = Effects.exitMsg(.notary_exited),
        }),
    }
}

/// What the ceremony window did, learned when it goes.
///
/// Every route out of the window lands here: a mint, an import, a cancel, a
/// failure, a crash, and a spawn that never started because one was already
/// running. Only the first arms the name beat.
fn handleNotaryExited(model: *Model, e: native_sdk.EffectExit) void {
    const was_running = g_ceremony;
    g_ceremony = .none;

    if (e.reason == .rejected) {
        // A window is already open. Say so, whatever was being opened: a
        // rejection only ever follows a press, and an unanswered press is the
        // thing this whole list of fixes is about. It used to be said only while
        // a CEREMONY was running, so pressing "Open Notary" twice was silent.
        if (was_running == .running) g_ceremony_adopted = false;
        setToast(model, "A Notary window is already open");
        return;
    }

    const created = e.reason == .exited and e.code == ceremony_created_code;
    if (!created) {
        g_ceremony_adopted = false;
        return;
    }

    // Minted. The flag that lets a contact list be written without reading one
    // back first is set HERE, on the confirmation, and never on the press: a key
    // that was never made cannot have provably no history.
    g_identity_minted_here = true;
    if (g_ceremony_adopted) {
        // The poll already signed the reader in, so the beat is owed now.
        g_ceremony_adopted = false;
        persistSession();
        model.naming = true;
        return;
    }
    g_ceremony = .created;
}

/// What the create ceremony has told us, which is the only thing that decides
/// whether an appearing key is one the reader just made.
///
/// This was a 90-second timer, and a timer is not an answer. It said "a key that
/// turns up soon after the Create press", which is a DIFFERENT statement from "the
/// key the ceremony made", and the gap between them was reachable: press Create,
/// have it fail (the daemon is not up yet, so the window says so and exits), then
/// press "Bring your key" and import a real account. The imported key arrived
/// inside the window, so Plaza treated it as freshly minted, offered "Want a name
/// on it?" over an account that already had one, and publishing that name rewrote
/// the account's kind:0 from an empty local profile. That is the exact shape of
/// the rule this app is built around: never write a replaceable record over data
/// you have not read back.
///
/// So the ceremony reports its own result instead. The window exits with
/// `ceremony_created_code` if and only if it minted a key, and that exit is what
/// arms the beat. A failed create, an import, a cancel and a crash all exit some
/// other way and arm nothing.
const CeremonyState = enum {
    /// No create ceremony has been asked for.
    none,
    /// The window was spawned and has not reported yet.
    running,
    /// The window minted a key and Plaza has not yet adopted it.
    created,
};
var g_ceremony: CeremonyState = .none;
/// A key was adopted while the ceremony was still running, so the beat is owed
/// once the window confirms what it did. The poll usually wins this race: the
/// window holds its result until the reader dismisses it and Plaza polls every
/// second, so in practice the poll always wins. The other branch is still real
/// and still tested: a reader who presses Continue inside the first second gets
/// their name beat from the exit instead.
var g_ceremony_adopted = false;

/// The window's exit code when, and only when, it minted a key.
const ceremony_created_code: i32 = 9;

/// Tells the daemon to forget the key (wipe memory + delete the file), so a
/// logout is not undone when the health-check next reads /pubkey. Fire and
/// forget; the g_logged_out latch covers the window until it lands.
fn helperReset(fx: *Effects) void {
    if (g_helper_token_len == 0) return;
    var url_buf: [48]u8 = undefined;
    const url = std.fmt.bufPrint(&url_buf, "http://127.0.0.1:{d}/reset", .{helper_port}) catch return;
    var auth_buf: [96]u8 = undefined;
    const auth = std.fmt.bufPrint(&auth_buf, "Bearer {s}", .{helperToken()}) catch return;
    fx.fetch(.{
        .key = helper_reset_key,
        .url = url,
        .method = .POST,
        .headers = &.{.{ .name = "Authorization", .value = auth }},
    });
}

/// Spawns the keyholder daemon: keyless, it idles serving /pubkey and /setup.
/// The parent-pid is Plaza's, so the daemon exits when Plaza does.
fn spawnHelper(fx: *Effects) void {
    if (g_helper_bin_len == 0 or g_helper_token_len == 0) return;
    var port_buf: [8]u8 = undefined;
    const port_str = std.fmt.bufPrint(&port_buf, "{d}", .{helper_port}) catch return;
    var pid_buf: [16]u8 = undefined;
    const pid_str = std.fmt.bufPrint(&pid_buf, "{d}", .{std.c.getpid()}) catch return;
    fx.spawn(.{
        .key = helper_spawn_key,
        .argv = &.{
            helperBin(),    "--serve",
            "--port",       port_str,
            "--state-dir",  g_helper_state_dir_buf[0..g_helper_state_dir_len],
            "--token-file", g_helper_token_path_buf[0..g_helper_token_path_len],
            "--parent-pid", pid_str,
        },
        .on_exit = Effects.exitMsg(.helper_exited),
        .output = .collect,
    });
}

/// Health-checks the daemon: GET /pubkey with the bearer token. A 200 (in any
/// state) proves the loopback IPC works; a connection error keeps it at
/// unreachable and the tick tries again.
fn pollHelper(fx: *Effects) void {
    if (g_helper_token_len == 0) return;
    // Signed OUT, this proves the IPC at startup and catches a key appearing
    // later (a terminal or window import), so Plaza adopts it live: poll every
    // tick. Signed IN, the status bar now reports whether Notary can actually
    // sign, and a stale flag there would be a chip that lies, so keep polling,
    // slowly. Only for a Notary identity: a local key or a bunker has nothing on
    // the other end of this socket.
    if (activePubkey() != null) {
        if (g_signer_kind != .helper) return;
        const now = nowSeconds();
        if (now - g_helper_polled_at < helper_health_interval_s) return;
        g_helper_polled_at = now;
    }
    var url_buf: [48]u8 = undefined;
    const url = std.fmt.bufPrint(&url_buf, "http://127.0.0.1:{d}/pubkey", .{helper_port}) catch return;
    var auth_buf: [96]u8 = undefined;
    const auth = std.fmt.bufPrint(&auth_buf, "Bearer {s}", .{helperToken()}) catch return;
    fx.fetch(.{
        .key = helper_poll_key,
        .url = url,
        .headers = &.{.{ .name = "Authorization", .value = auth }},
        .on_response = Effects.responseMsg(.helper_pubkey),
    });
}

/// Records the health-check result. A reachable daemon (200) tells us the IPC
/// works; the body says whether it already holds a key.
fn handleHelperPubkey(model: *Model, response: native_sdk.EffectResponse) void {
    if (response.outcome != .ok or response.status != 200) {
        g_helper_state.store(3, .release); // unreachable, keep retrying
        return;
    }
    const gpa = std.heap.page_allocator;
    var parsed = nostr.signer_ipc.parse(nostr.signer_ipc.Pubkey, gpa, response.body) catch return;
    defer parsed.deinit();
    const ready = std.mem.eql(u8, parsed.value.state, nostr.signer_ipc.state_ready);
    g_helper_state.store(if (ready) 2 else 1, .release);
    if (!ready) {
        // The daemon says it holds nothing, which is the only real evidence the
        // logout's reset landed. Whatever key appears next is a new one.
        g_logged_out_pk = null;
        g_logout_reset_tries = 0;
        return;
    }

    // The daemon holds a key and Plaza is a guest: adopt it. This is how a
    // terminal or window import (which Plaza did not initiate) signs the user
    // in live. A Plaza-initiated setup is left to handleHelperSetup, which owns
    // the name beat and the remembered intent.
    if (g_logged_out) return; // a just-logged-out session must stay out
    // And the key that just left stays gone even after an explicit sign-in drops
    // that latch, until the daemon has said it no longer holds it. Pressing
    // "Create your identity" used to be enough to walk straight back into the
    // account the reader had just signed out of.
    if (g_logged_out_pk) |left| {
        var still: [32]u8 = undefined;
        if (std.fmt.hexToBytes(&still, parsed.value.pubkey)) |_| {
            if (std.mem.eql(u8, &still, &left)) {
                // The reset did not land. Ask again on the tick, which is where
                // the effects live, a bounded number of times.
                if (g_logout_reset_tries < logout_reset_retries) {
                    g_logout_reset_tries += 1;
                    g_logout_reset_due = true;
                }
                return;
            }
        } else |_| {}
    }
    if (activePubkey() != null) return;
    if (g_helper_setup != .none or g_helper_pending_in_flight != .none) return;
    if (!restoreHelperIdentity(parsed.value.pubkey)) return;
    persistSession();
    enterFeed(model);
    switch (g_ceremony) {
        // The window has confirmed a mint, so this key is that key: nothing else
        // can be in a daemon that just accepted a create.
        .created => {
            g_ceremony = .none;
            model.naming = true; // the name beat; replay follows it
            return;
        },
        // A ceremony is open but has not said what it did yet. Sign in, and owe
        // the beat until the window reports. NOT "assume it was a create": that
        // assumption is the bug this replaced.
        .running => g_ceremony_adopted = true,
        .none => {},
    }
    replayPending(model);
}

// The signed-in helper identity: its pubkey lives here (the SECRET lives only in
// the daemon). `.helper` is the built-in local key now; `g_identity_kp` stays
// null for it, so the key is never in this process.
var g_helper_identity_pk: [32]u8 = undefined;
var g_helper_has_identity = false;

// Helper setup is async and can race the daemon coming up, so an intent is
// queued and fired by the tick once the daemon is reachable. `create` mints a
// fresh key (then the name beat); `import_user` adopts a pasted nsec; `migrate`
// moves a legacy in-process key into the daemon and deletes it, silently.
const HelperSetup = enum { none, create, import_user, migrate };
var g_helper_setup: HelperSetup = .none;
var g_helper_setup_secret: [32]u8 = undefined;
const helper_setup_key: u64 = 42;
const helper_sign_key: u64 = 43;

fn helperReachable() bool {
    return g_helper_state.load(.acquire) >= 1;
}

/// Queues a helper setup and fires it now if the daemon is already up (else the
/// tick fires it the moment the health-check confirms reachability).
fn queueHelperSetup(fx: *Effects, kind: HelperSetup, secret: ?[32]u8) void {
    g_logged_out = false; // an explicit sign-in re-enables adopt-on-appear
    g_helper_setup = kind;
    if (secret) |sk| g_helper_setup_secret = sk;
    driveHelperSetup(fx);
}

/// Fires a queued setup once the daemon is reachable. Called on the tick and
/// right after queueing.
fn driveHelperSetup(fx: *Effects) void {
    if (g_helper_setup == .none or !helperReachable()) return;
    const gpa = std.heap.page_allocator;
    switch (g_helper_setup) {
        .none => {},
        .create => helperFetch(fx, helper_setup_key, "/setup", "{\"method\":\"create\"}", Effects.responseMsg(.helper_setup)),
        .import_user, .migrate => {
            const nsec = nostr.nip19.encodeNsec(gpa, g_helper_setup_secret) catch return;
            defer gpa.free(nsec);
            std.crypto.secureZero(u8, &g_helper_setup_secret);
            var body_buf: [128]u8 = undefined;
            const body = std.fmt.bufPrint(&body_buf, "{{\"method\":\"import\",\"secret\":\"{s}\"}}", .{nsec}) catch return;
            defer std.crypto.secureZero(u8, &body_buf);
            helperFetch(fx, helper_setup_key, "/setup", body, Effects.responseMsg(.helper_setup));
        },
    }
    // In flight now; the response either completes it or, on failure, requeues.
    g_helper_pending_in_flight = g_helper_setup;
    g_helper_setup = .none;
}
var g_helper_pending_in_flight: HelperSetup = .none;

/// A POST to the daemon with the bearer token. The body is copied by the effect,
/// so a stack buffer is fine.
fn helperFetch(fx: *Effects, key: u64, comptime path: []const u8, body: []const u8, on_response: @TypeOf(Effects.responseMsg(.helper_setup))) void {
    var url_buf: [48]u8 = undefined;
    const url = std.fmt.bufPrint(&url_buf, "http://127.0.0.1:{d}" ++ path, .{helper_port}) catch return;
    var auth_buf: [96]u8 = undefined;
    const auth = std.fmt.bufPrint(&auth_buf, "Bearer {s}", .{helperToken()}) catch return;
    fx.fetch(.{
        .key = key,
        .url = url,
        .method = .POST,
        .headers = &.{.{ .name = "Authorization", .value = auth }},
        .body = body,
        .on_response = on_response,
    });
}

// A helper sign that has gone out and not come back.
//
// The remote signer has had a pending table, a deadline and a restore since the
// day it shipped. The helper had none of it, and `signAndPublish` dropped the
// `restorable` flag on the way to it, so a Notary sign that failed for any
// reason destroyed the note in silence: `submitPost` clears the composer, the
// press deletes ~/.plaza/draft, the toast says "Posted", and the response
// handler returned on its first line without a Model to restore anything into.
// Nothing was stored and nothing was queued, because the outbox is fed from
// `ingestAndPublish`, which the helper path only reaches AFTER a good signature.
//
// The daemon answers non-200 while perfectly alive: 401 with a stale token, 409
// with no key yet, 400 on a malformed event, 500 on a signing failure. It also
// dies without being respawned, and a dead port answers `connect_failed`.
//
// One slot, because the SDK refuses a second fetch on an occupied key and every
// helper sign uses the same one.
const HelperSign = struct {
    active: bool = false,
    restorable: bool = false,
    failed: bool = false,
    deadline_s: i64 = 0,
    content: ?[]u8 = null,
};
var g_helper_sign: HelperSign = .{};

/// The tag set of the most recent event handed to a signer. Read only by tests,
/// which have no other view of the event that actually goes out.
var g_last_published_tags: []const nostr.event.Tag = &.{};

/// How long a helper sign may be out before the note is handed back. The daemon
/// is on loopback and answers in about a millisecond, so this is not a latency
/// budget: it is the backstop for a response that never arrives at all.
const helper_sign_timeout_s: i64 = 10;

/// Remembers a note handed to the daemon, so a failure has something to give
/// back. Called BEFORE the request is built, because building it can fail too
/// and those paths used to lose the note just as quietly.
fn rememberHelperSign(gpa: std.mem.Allocator, content: []const u8, restorable: bool) void {
    releaseHelperSign();
    g_helper_sign = .{
        .active = true,
        .restorable = restorable,
        .failed = false,
        .deadline_s = nowSeconds() + helper_sign_timeout_s,
        .content = if (restorable) gpa.dupe(u8, content) catch null else null,
    };
}

/// Drops the slot without restoring: the signature came back.
fn releaseHelperSign() void {
    if (g_helper_sign.content) |c| std.heap.page_allocator.free(c);
    g_helper_sign = .{};
}

/// Marks the sign as failed. The restore itself happens on the tick, where a
/// Model is reachable, exactly as the remote path does it.
fn failHelperSign() void {
    if (!g_helper_sign.active) return;
    g_helper_sign.failed = true;
}

/// Hands a failed sign's note back to the composer and says why. The mirror of
/// `scanPendingRemote`, and called from the same tick.
fn scanHelperSign(model: *Model) void {
    if (!g_helper_sign.active) return;
    if (!g_helper_sign.failed and nowSeconds() < g_helper_sign.deadline_s) return;
    const restorable = g_helper_sign.restorable;
    const content = g_helper_sign.content;
    g_helper_sign = .{};
    const gpa = std.heap.page_allocator;
    if (content) |c| {
        // The composer holds one draft. A reader who has started typing again
        // keeps what they are typing; the restored one would overwrite it.
        if (restorable and model.draft_empty()) {
            model.draft_buffer.set(c);
            saveDraft(c);
        }
        gpa.free(c);
    }
    if (restorable) g_helper_sign_notice.store(true, .release);
}

/// A helper sign that failed, surfaced once in the composer so a restored draft
/// is explained rather than silently reappearing. Cleared on the next edit or a
/// later success, the same as the remote signer's.
var g_helper_sign_notice = std.atomic.Value(bool).init(false);

/// Drives one helper sign the way `signAndPublish` does, without needing a live
/// daemon behind it. The fetch itself goes nowhere in a test; what is under test
/// is what happens to the note when it does not come back.
/// Drives the whole post, from the composer down through the signer dispatch.
/// The dispatch is the part that mattered: it forwarded `restorable` to the
/// bunker and dropped it on the way to the built-in signer, so the flag arriving
/// intact is not something a test of `requestHelperSign` alone can see.
pub fn submitPostForTest(model: *Model, fx: *Effects) bool {
    return submitPost(model, fx);
}

/// The tags a body of text implies, for tests. Deliberately takes the finished
/// string: that is exactly what the publish path passes, which is why a pasted
/// note and a typed one cannot diverge.
pub fn resetWantedProfilesForTest() void {
    g_wanted = [_]WantedProfile{.{}} ** wanted_profiles_cap;
}

pub fn wantProfileForTest(pubkey: [32]u8) void {
    wantProfile(pubkey);
}

pub fn wantProfilesAheadForTest(model: *const Model) void {
    wantProfilesAhead(model);
}

pub fn isProfileWantedForTest(pubkey: [32]u8) bool {
    for (&g_wanted) |*w| {
        if (w.used and std.mem.eql(u8, &w.pubkey, &pubkey)) return true;
    }
    return false;
}

pub fn wantedProfileCountForTest() usize {
    var n: usize = 0;
    for (&g_wanted) |*w| {
        if (w.used) n += 1;
    }
    return n;
}

pub fn dupeTagsForTest(gpa: std.mem.Allocator, tags: []const nostr.event.Tag) ?[]const nostr.event.Tag {
    return dupeTags(gpa, tags);
}

pub fn contentTagsForTest(gpa: std.mem.Allocator, content: []const u8) []const nostr.event.Tag {
    return contentTags(gpa, content, &.{}, &.{});
}

/// The tag set of the last event handed to a signer, for tests.
pub fn lastPublishedTagsForTest() []const nostr.event.Tag {
    return g_last_published_tags;
}

pub fn clearLastPublishedTagsForTest() void {
    g_last_published_tags = &.{};
}

pub fn helperSignRestorableForTest() bool {
    return g_helper_sign.active and g_helper_sign.restorable;
}

pub fn requestHelperSignForTest(fx: *Effects, created: i64, kind: u16, content: []const u8, restorable: bool) void {
    requestHelperSign(fx, std.heap.page_allocator, created, kind, &.{}, content, restorable);
}

pub fn handleHelperSignedForTest(response: native_sdk.EffectResponse) void {
    handleHelperSigned(response);
}

pub fn releaseHelperSignForTest() void {
    releaseHelperSign();
}

/// Puts the pending sign past its deadline, for the case where no terminal ever
/// arrives: a daemon that accepts the socket and then says nothing.
pub fn expireHelperSignForTest() void {
    g_helper_sign.deadline_s = 0;
}

pub fn scanHelperSignForTest(model: *Model) void {
    scanHelperSign(model);
}

pub fn helperSignNoticeForTest() bool {
    return g_helper_sign_notice.load(.acquire);
}

/// Whether the signer can be asked for a signature RIGHT NOW.
///
/// Every helper sign goes out on one effect key, and the SDK refuses a second
/// fetch while that key is held. The refusal is delivered as a `.rejected`
/// outcome, which used to be dropped on the first line of the response handler,
/// so the second sign of a pair simply never happened.
///
/// It is not only a race. The tick issues `flushRelayList` and
/// `drivePendingIntent` in the SAME update call, with no drain possible between
/// them, so when both are due the second is rejected every time. The callers
/// had already moved their state by then: the follow set had the new name in it
/// and the UI said "Following" for a list that was never signed.
///
/// So the callers ask first, and a "not now" leaves everything where it was.
/// Every one of them is retried by something: the relay list keeps its pending
/// edit, a press can be pressed again, and the composer keeps its draft.
fn signerReady() bool {
    return switch (g_signer_kind) {
        // One key, one sign. The bunker's table has eight slots keyed by request
        // id, so it does not collide, and a local key signs inline.
        .helper => !g_helper_sign.active,
        .remote, .local => true,
    };
}

pub fn signerReadyForTest() bool {
    return signerReady();
}

/// Whether a note is with a signer right now, waiting for a signature. True for
/// both the bunker's pending table and the built-in signer's slot.
pub fn signInFlight() bool {
    if (g_helper_sign.active and g_helper_sign.restorable) return true;
    pendingLock();
    defer pendingUnlock();
    for (&g_pending) |slot| {
        if (slot.active and slot.restorable) return true;
    }
    return false;
}

/// Puts the built-in signer in the state it is in while a signature is out, so
/// a test can drive the press that lands during one.
pub fn holdHelperSignForTest() void {
    g_signer_kind = .helper;
    g_helper_sign.active = true;
}

pub fn helperSignPendingForTest() bool {
    return g_helper_sign.active;
}

/// Sends one event of `kind` (with `tags`, stamped `created`) to the daemon to
/// be signed. Builds the unsigned event against the helper's own pubkey so the
/// returned id matches, wraps it, and POSTs /sign; the response is the signed
/// event, ingested and published like any other. `content_owned` and `tags` are
/// process-lifetime (the local and remote paths reference them too), so this
/// does not free them.
fn requestHelperSign(fx: *Effects, gpa: std.mem.Allocator, created: i64, kind: u16, tags: []const nostr.event.Tag, content_owned: []const u8, restorable: bool) void {
    const pk = activePubkey() orelse return;
    // Recorded first. Every `catch return` below is a path that used to end with
    // the note gone and the app saying "Posted".
    rememberHelperSign(gpa, content_owned, restorable);
    const id = nostr.event.computeId(gpa, pk, created, kind, tags, content_owned) catch {
        failHelperSign();
        return;
    };
    const unsigned = nostr.event.Event{
        .id = id,
        .pubkey = pk,
        .created_at = created,
        .kind = kind,
        .tags = tags,
        .content = content_owned,
        .sig = [_]u8{0} ** 64,
    };
    const unsigned_json = nostr.event.toJson(gpa, unsigned) catch {
        failHelperSign();
        return;
    };
    defer gpa.free(unsigned_json);
    const body = (nostr.signer_ipc.SignEvent{ .event = unsigned_json }).toJson(gpa) catch {
        failHelperSign();
        return;
    };
    defer gpa.free(body);
    // A test drives what happens to the NOTE, which is everything above and
    // everything the response handler does. It cannot drive the loopback: an
    // `Effects` is not constructible outside a running app, so this call would
    // fault on undefined memory. Comptime, so the shipped binary has no branch.
    if (builtin.is_test) return;
    helperFetch(fx, helper_sign_key, "/sign", body, Effects.responseMsg(.helper_signed));
}

/// Adopts a helper-held identity: only the pubkey lives here, never the secret
/// (that stays in the daemon). Clears any in-UI local key.
fn adoptHelperIdentity(pk: [32]u8) void {
    if (g_identity_signer) |*sig| sig.deinit();
    g_identity_signer = null;
    g_identity_kp = null;
    g_helper_identity_pk = pk;
    g_helper_has_identity = true;
    g_signer_kind = .helper;
    const npub = abbreviateNpub(&g_identity_npub_buf, pk);
    g_identity_npub_len = npub.len;
    invalidateFeed();
}

/// Restores a helper identity from a persisted session pubkey. Synchronous: the
/// daemon independently loads its own key, so Plaza only needs to know who it is.
fn restoreHelperIdentity(pubkey_hex: []const u8) bool {
    if (pubkey_hex.len != 64) return false;
    var pk: [32]u8 = undefined;
    _ = std.fmt.hexToBytes(&pk, pubkey_hex) catch return false;
    adoptHelperIdentity(pk);
    return true;
}

/// Completes an async helper setup. On a fresh create it adopts the minted
/// identity and opens the name beat; a transient failure requeues for the tick.
fn handleHelperSetup(model: *Model, response: native_sdk.EffectResponse) void {
    const purpose = g_helper_pending_in_flight;
    g_helper_pending_in_flight = .none;
    if (response.outcome != .ok) {
        g_helper_setup = purpose; // the daemon was not up; the tick retries
        return;
    }
    if (response.status != 200) {
        // A migration is a silent background upgrade: on failure the in-process
        // key keeps working, so say nothing. Foreground setups report.
        if (purpose != .migrate) setToast(model, "Could not set up your key");
        return;
    }
    const gpa = std.heap.page_allocator;
    var parsed = nostr.signer_ipc.parse(nostr.signer_ipc.Pubkey, gpa, response.body) catch return;
    defer parsed.deinit();
    if (!restoreHelperIdentity(parsed.value.pubkey)) return;
    persistSession();
    switch (purpose) {
        .create => {
            // Confirmed here, for the same reason the ceremony window's mint is
            // confirmed on its exit: the daemon has answered, so a key exists and
            // it is this one.
            g_identity_minted_here = true;
            // Persisted AGAIN, because the write above happened before the flag
            // was set and therefore recorded `minted=0`. A restart then read
            // this key back as an imported one, which is a weaker claim about a
            // key that provably has no history, and it is the difference between
            // the sign-out warning saying the key can be signed in with again
            // and saying it cannot be recovered.
            persistSession();
            enterFeed(model);
            model.naming = true; // the name beat; replay follows it
        },
        .import_user => {
            enterFeed(model);
            replayPending(model);
        },
        // A completed migration: the daemon now holds the key, so delete the
        // in-process file. The user was already signed in; nothing else changes.
        .migrate => deleteIdentityKeyFile(),
        .none => {},
    }
}

/// Starts making a key, in the Notary window when there is one.
///
/// The fallback is not a lesser version of the same thing, it is the path this
/// app shipped with: Plaza asks the daemon directly and the daemon mints. The
/// key never enters Plaza either way. What the window adds is that the reader
/// SEES the separate process that holds their key, once, at the moment it starts
/// holding it. Worth a window; not worth a dead button when the binary is absent
/// (a dev tree with the sub-project unbuilt, a broken bundle).
fn beginCreate(fx: *Effects) void {
    // Nothing can mint a key without the daemon that would hold it: Plaza has
    // not held one itself since the key moved out of this process. The ladder
    // says so in place of the card, but the guard belongs HERE, because this is
    // the one function every create path goes through, and what it prevents is
    // an intent queued against a binary that will never appear. `queueHelperSetup`
    // waits for reachability, and a missing keyholder never becomes reachable,
    // so without this the reader's press is swallowed whole and the sheet closes
    // over nothing.
    if (keyholderMissing()) return;
    if (g_notary_win_len == 0) {
        queueHelperSetup(fx, .create, null);
        return;
    }
    // The ceremony is the other process's now, so what queueHelperSetup would
    // have done has to be done here: re-enable adopt-on-appear, which a logout
    // latches off.
    g_logged_out = false;
    g_ceremony = .running;
    g_ceremony_adopted = false;
    spawnNotaryWindow(fx, .create_key);
}

/// Deletes the legacy in-process key file, once its secret is safe in the daemon.
fn deleteIdentityKeyFile() void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    dir.deleteFile(io, "identity.key") catch {};
}

/// Ingests and publishes a signed event returned by the daemon. Trusted: it
/// came from our own daemon over authenticated loopback. A kind:0 seeds the
/// profile cache so the name shows at once.
fn handleHelperSigned(response: native_sdk.EffectResponse) void {
    // A refusal, a timeout, a rejected effect, or a daemon that is not there.
    // The tick hands the note back; this line used to be where it was dropped.
    if (response.outcome != .ok or response.status != 200) {
        failHelperSign();
        return;
    }
    const gpa = std.heap.page_allocator;
    // Every failure below is the daemon answering with something this app cannot
    // use, which is a failed sign like any other.
    var wrapped = nostr.signer_ipc.parse(nostr.signer_ipc.SignEvent, gpa, response.body) catch {
        failHelperSign();
        return;
    };
    defer wrapped.deinit();
    var parsed = nostr.event.fromJson(gpa, wrapped.value.event) catch {
        failHelperSign();
        return;
    };
    defer parsed.deinit();
    const owned = gpa.dupe(u8, parsed.value.content) catch {
        failHelperSign();
        return;
    };
    var out = parsed.value;
    out.content = owned;
    // Preserve the signed event's tags (a reaction carries e/p/k): forcing them
    // empty would leave the published id not matching its content, so relays
    // would reject it. Deep-copied because `parsed` is freed on return.
    // Whole, or the note is handed back rather than published. Without the
    // signed tags the id no longer matches the event, so a relay rejects it and
    // the reader is told nothing; failing here keeps the note recoverable.
    out.tags = dupeTags(gpa, parsed.value.tags) orelse {
        failHelperSign();
        return;
    };
    if (out.kind == 0) {
        if (upsertProfile(out.pubkey)) |prof| parseMetadataInto(prof, owned);
    }
    // Signed. The note is the store's and the outbox's problem now, so the copy
    // held for a restore is dropped and any earlier failure notice retired.
    releaseHelperSign();
    g_helper_sign_notice.store(false, .release);
    ingestAndPublish(gpa, out, null);
}
// The listener runs for one connection generation. A logout or a reconnect
// bumps this; the detached listener and the in-flight workers see the change
// and stop, so an old bunker's listener never processes into a new session (or
// a dead one). Correlating this into every pending request is the teardown fix.
var g_remote_generation = std.atomic.Value(u64).init(0);
// A remote sign that never came back, surfaced once in the composer identity
// line so a restored draft is explained rather than silently reappearing.
// Set by the timeout scan, cleared on the next edit or a later success.
var g_remote_sign_notice = std.atomic.Value(bool).init(false);

// Pending NIP-46 requests, keyed by id, so a response is correlated to the
// request that asked for it (not guessed from whether `result` parses as an
// event), and a request that never returns times out instead of losing the
// draft. A tiny spinlock guards the table: every critical section is a handful
// of field writes or an 8-slot scan and never touches IO, so a lock this cheap
// is the right tool (std.Io.Mutex would drag a per-thread `io` through every
// access, across threads that deliberately never share one).
const remote_sign_timeout_s: i64 = 30;
const max_pending_remote = 8;
const RemoteMethod = enum { connect, sign_event };
const PendingRemote = struct {
    active: bool = false,
    id_buf: [24]u8 = undefined,
    id_len: usize = 0,
    method: RemoteMethod = .connect,
    deadline_s: i64 = 0,
    generation: u64 = 0,
    // The listener flags a failed response here; the UI tick, which owns the
    // composer, is what actually restores the draft (see `scanPendingRemote`).
    failed: bool = false,
    // sign_event only: the draft text, restored to the composer on failure or
    // timeout. Owned by the slot; freed when the request resolves or is swept.
    content: ?[]const u8 = null,
    // Whether `content` is a composer draft worth restoring on failure. A
    // reaction (kind:7 "+") is not, so its failure is silent, not a stray "+".
    restorable: bool = false,

    fn id(self: *const PendingRemote) []const u8 {
        return self.id_buf[0..self.id_len];
    }
};
var g_pending_lock = std.atomic.Value(bool).init(false);
var g_pending: [max_pending_remote]PendingRemote = [_]PendingRemote{.{}} ** max_pending_remote;

fn pendingLock() void {
    while (g_pending_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
}
fn pendingUnlock() void {
    g_pending_lock.store(false, .release);
}

/// Records a request as awaiting its response, taking ownership of `content`
/// (the draft, for `sign_event`, so a timeout can restore it when `restorable`).
/// Returns false when the table is full or the id does not fit, in which case
/// the caller still owns `content`.
fn registerPending(req_id: []const u8, method: RemoteMethod, content: ?[]const u8, restorable: bool) bool {
    if (req_id.len > 24) return false;
    pendingLock();
    defer pendingUnlock();
    for (&g_pending) |*slot| {
        if (slot.active) continue;
        slot.* = .{
            .active = true,
            .method = method,
            .id_len = req_id.len,
            .deadline_s = nowSeconds() + remote_sign_timeout_s,
            .generation = g_remote_generation.load(.acquire),
            .content = content,
            .restorable = restorable,
        };
        @memcpy(slot.id_buf[0..req_id.len], req_id);
        return true;
    }
    return false;
}

/// Takes the pending request matching `req_id` out of the table, or null when
/// none matches (an unknown id, or one already resolved: dropping it keeps a
/// duplicated response from publishing twice). The caller owns the returned
/// slot's `content`.
fn takePending(req_id: []const u8) ?PendingRemote {
    pendingLock();
    defer pendingUnlock();
    for (&g_pending) |*slot| {
        if (slot.active and std.mem.eql(u8, slot.id(), req_id)) {
            const taken = slot.*;
            slot.* = .{};
            return taken;
        }
    }
    return null;
}

/// Marks the pending request matching `req_id` failed, leaving it in the table
/// for the UI tick to restore the draft and free the content. Returns whether a
/// slot matched.
fn failPending(req_id: []const u8) bool {
    pendingLock();
    defer pendingUnlock();
    for (&g_pending) |*slot| {
        if (slot.active and std.mem.eql(u8, slot.id(), req_id)) {
            slot.failed = true;
            return true;
        }
    }
    return false;
}

// Test seams for the NIP-46 pending-request table (the correlation and teardown
// logic), exercised without threads or a live bunker.
pub const RemoteMethodForTest = RemoteMethod;
pub fn registerPendingForTest(req_id: []const u8, method: RemoteMethod, content: ?[]const u8) bool {
    return registerPending(req_id, method, content, content != null);
}
pub fn takePendingContentForTest(req_id: []const u8) ?struct { method: RemoteMethod, content: ?[]const u8 } {
    const taken = takePending(req_id) orelse return null;
    return .{ .method = taken.method, .content = taken.content };
}
pub fn failPendingForTest(req_id: []const u8) bool {
    return failPending(req_id);
}
pub fn clearPendingForTest() void {
    clearPending();
}
pub fn bumpRemoteGenerationForTest() void {
    _ = g_remote_generation.fetchAdd(1, .monotonic);
}
pub fn scanPendingRemoteForTest(model: *Model) void {
    scanPendingRemote(model);
}
pub fn remoteSignNoticeForTest() bool {
    return g_remote_sign_notice.load(.acquire);
}

/// Empties the pending table, freeing every held draft. For logout, so a new
/// session never inherits the old one's in-flight requests.
fn clearPending() void {
    const gpa = std.heap.page_allocator;
    pendingLock();
    defer pendingUnlock();
    for (&g_pending) |*slot| {
        if (!slot.active) continue;
        if (slot.content) |c| gpa.free(c);
        slot.* = .{};
    }
}

// A synchronous error from the unified login field (nsec / bunker), shown under
// it. `.none` while idle or when the async bunker path is in charge (its state
// comes from `g_remote_status`). See `LoginError` and `Model.login_status`.
const LoginError = enum(u8) { none = 0, format = 1, bad_key = 2 };
var g_login_error = std.atomic.Value(u8).init(0);

/// What the pasted login text is: a secret key to import, a signer to connect,
/// or neither.
pub const LoginTarget = enum { nsec, bunker, invalid };

/// Classifies pasted login text by its prefix. Pure, so it is unit-tested.
pub fn classifyLogin(text: []const u8) LoginTarget {
    const t = std.mem.trim(u8, text, " \t\r\n");
    if (std.mem.startsWith(u8, t, "nsec1")) return .nsec;
    if (std.mem.startsWith(u8, t, "bunker://")) return .bunker;
    return .invalid;
}

// --------------------------------------------------------------- media proxy
//
// The image registry decodes at most a 512x512 image and the fetch effect caps
// bodies at 256 KiB, so a full-size photo can neither be downloaded nor decoded
// as-is. Images are therefore requested at the size they will actually be drawn:
// through a host's own resizer when it has one, otherwise through a
// weserv-compatible proxy (the free public wsrv.nl by default, and any instance
// the user prefers, including their own). Clearing the setting loads originals
// straight from their host, which still works for anything small enough.

const default_media_proxy = "https://wsrv.nl/";
/// Whether the app reaches out for the things a note POINTS AT: its picture, the
/// faces of the people in the feed, the page a link goes to, and the domain a
/// NIP-05 name claims. On by default, because a feed of grey boxes is not the
/// app. Off, none of that leaves the machine until the reader asks for a
/// particular picture, and the only hosts that learn anything are the relays,
/// which are the ones the reader chose.
///
/// It covers every unattended fetch, deliberately: gating only the pictures
/// would leave each author's own domain and every avatar host still learning
/// that you are reading, which is exactly what the switch is for.
var g_media_previews: bool = true;

pub fn mediaPreviews() bool {
    return g_media_previews;
}

pub fn setMediaPreviews(on: bool) void {
    g_media_previews = on;
}
/// Whether notes published from here say so, with NIP-89's `client` tag.
///
/// OFF by default. The tag is a small permanent fact about the reader attached
/// to everything they write: not what they said, but what they said it WITH, and
/// it follows the note to every relay and every client forever. NIP-89 puts the
/// privacy question in the spec itself ("clients SHOULD allow users to opt-out
/// of using this tag"), which is unusual enough to be worth reading as a hint
/// about which way the default should fall.
///
/// The argument the other way is real and lost: this is how anyone discovers a
/// new client exists at all. Sepehr chose the private default (2026-07-31), so
/// Plaza is invisible in other people's clients unless the reader decides
/// otherwise. Reading the tag on OTHER people's notes is unaffected: that is
/// their disclosure, already made.
var g_client_tag: bool = false;

pub fn clientTag() bool {
    return g_client_tag;
}

pub fn setClientTag(on: bool) void {
    g_client_tag = on;
}

/// What Plaza calls itself in that tag. NIP-89's full tuple also carries a
/// `31990:<pubkey>:<d>` handler address and a relay hint, which point at a
/// handler event Plaza does not publish; the name alone is valid, and is what
/// most clients actually emit.
const client_tag_name = "Plaza";

var g_media_proxy_buf: [200]u8 = undefined;
var g_media_proxy_len: usize = 0;

/// The configured proxy base URL, empty when images load directly.
pub fn mediaProxy() []const u8 {
    return g_media_proxy_buf[0..g_media_proxy_len];
}

/// Sets the proxy base URL (trimmed; empty disables proxying).
pub fn setMediaProxy(url: []const u8) void {
    const trimmed = std.mem.trim(u8, url, " \t\r\n");
    const n = @min(trimmed.len, g_media_proxy_buf.len);
    @memcpy(g_media_proxy_buf[0..n], trimmed[0..n]);
    g_media_proxy_len = n;
}

/// Whether the host serves its own resized variants via `?w=`, letting us skip
/// the proxy hop entirely. nostr.build's Blossom hosts do; most others ignore it.
fn hostSupportsWidthParam(src: []const u8) bool {
    return std.mem.indexOf(u8, src, "://blossom.nostr.build/") != null or
        std.mem.indexOf(u8, src, "://blossom.band/") != null or
        std.mem.indexOf(u8, src, ".blossom.band/") != null;
}

/// How an image is fitted when resized.
pub const MediaFit = enum {
    /// Square, cropped to fill: avatars.
    square,
    /// Scaled down to fit inside a square box, aspect preserved: feed images.
    /// Bounding both edges is what keeps a tall image inside the pixel budget.
    inside,
    /// Like `inside`, but every frame is kept and the result stays a GIF, so it
    /// can still animate. Asked for smaller, since the whole animation has to
    /// arrive inside the fetch cap.
    animation,
};

/// Whether `src` points at a GIF, which is fetched keeping its frames.
pub fn isGifUrl(src: []const u8) bool {
    const path_end = std.mem.indexOfScalar(u8, src, '?') orelse src.len;
    return std.ascii.endsWithIgnoreCase(src[0..path_end], ".gif");
}

/// Builds the URL to fetch `src` at roughly `width` pixels, writing into `out`
/// and returning the slice to request. Falls back to `src` itself whenever no
/// resizing route applies or the URL would not fit.
pub fn mediaUrl(out: []u8, src: []const u8, width: u32, fit: MediaFit) []const u8 {
    // A host that resizes for us: cheapest path, no third party involved.
    if (hostSupportsWidthParam(src) and std.mem.indexOfScalar(u8, src, '?') == null) {
        return std.fmt.bufPrint(out, "{s}?w={d}", .{ src, width }) catch src;
    }
    const proxy = mediaProxy();
    if (proxy.len == 0) return src;

    var encoded_buf: [768]u8 = undefined;
    const encoded = percentEncode(&encoded_buf, src) orelse return src;
    const sep: []const u8 = if (std.mem.endsWith(u8, proxy, "/")) "" else "/";
    return switch (fit) {
        .square => std.fmt.bufPrint(out, "{s}{s}?url={s}&w={d}&h={d}&fit=cover&output=webp", .{ proxy, sep, encoded, width, width }) catch src,
        .inside => std.fmt.bufPrint(out, "{s}{s}?url={s}&w={d}&h={d}&fit=inside&output=webp", .{ proxy, sep, encoded, width, width }) catch src,
        // `n=-1` keeps every frame; the output stays a GIF because that is the
        // animated format the vendored decoder can read frame by frame.
        .animation => std.fmt.bufPrint(out, "{s}{s}?url={s}&w={d}&h={d}&fit=inside&n=-1&output=gif", .{ proxy, sep, encoded, width, width }) catch src,
    };
}

/// Percent-encodes `src` into `out` (everything outside the unreserved set), so
/// a source URL survives as one query parameter. Null if it would not fit.
fn percentEncode(out: []u8, src: []const u8) ?[]const u8 {
    const hexdigits = "0123456789ABCDEF";
    var n: usize = 0;
    for (src) |c| {
        const unreserved = (c >= 'A' and c <= 'Z') or (c >= 'a' and c <= 'z') or
            (c >= '0' and c <= '9') or c == '-' or c == '.' or c == '_' or c == '~';
        if (unreserved) {
            if (n + 1 > out.len) return null;
            out[n] = c;
            n += 1;
        } else {
            if (n + 3 > out.len) return null;
            out[n] = '%';
            out[n + 1] = hexdigits[c >> 4];
            out[n + 2] = hexdigits[c & 0x0f];
            n += 3;
        }
    }
    return out[0..n];
}

// ------------------------------------------------------------------ profiles
//
// Kind:0 metadata gives each author a display name and an avatar. The pool
// ingests kind:0 for the feed's authors alongside their notes (the store keeps
// only the newest per author, kind:0 being replaceable); the UI thread parses
// them into this cache during the feed rebuild, keyed by pubkey. The feed reads
// names and avatar image ids from the cache at render time, so a name or a
// just-loaded avatar shows on the next frame without a re-query. Avatars are
// fetched (bounded, cap-aware) and registered as canvas images; the cache is
// UI-thread-only, so no synchronisation is needed.

// Pubkeys a note mentioned that we have no name for. The pool only subscribes
// to the follow set's metadata, so a mention of anyone else would render as a
// bare npub forever; these are fetched separately, once each, and then resolve
// like any other name.
// Sized to the real ceiling rather than to a guess: a full inbox, a full
// thread, and headroom. The old table held 48 and, once full, SILENTLY DROPPED
// every further request: the loop looked for a slot already asked the maximum
// number of times, found none, and fell off the end having queued nothing. With
// 144 notifications that is what it did all day, which is why a name only ever
// arrived after visiting that person's profile, because visiting asks for one.
//
// No shipping client has an author cap here. NDK merges `authors` with no limit
// at all; Amethyst rebuilds one REQ from every name currently on screen.
const wanted_profiles_cap = inbox_cap + thread_reply_cap + 64;
const WantedProfile = struct {
    used: bool = false,
    /// When this pubkey was last actually asked for, and how many times running
    /// it has come back with nothing. Together they gate a retry: wait
    /// `2^attempts` seconds, clamped, before asking again.
    ///
    /// There is no strike limit. The old code wrote a pubkey off permanently
    /// after three rounds and incremented the counter BEFORE checking whether
    /// the network was even allowed, so an app launched offline burned all three
    /// inside forty seconds and showed a raw npub for the rest of the process.
    /// welshman's loader is the shape copied here: a timestamp, exponential
    /// backoff, and nothing ever marked dead.
    last_tried: i64 = 0,
    attempts: u8 = 0,
    pubkey: [32]u8 = [_]u8{0} ** 32,
};
/// The longest a repeatedly silent pubkey waits between asks.
const profile_retry_cap_s: i64 = 300;
var g_wanted = [_]WantedProfile{.{}} ** wanted_profiles_cap;

/// Whether `w` is due another ask.
fn profileRetryDue(w: *const WantedProfile, now: i64) bool {
    if (w.attempts == 0) return true;
    const shift: u6 = @intCast(@min(w.attempts, 8));
    const wait = @min(@as(i64, 1) << shift, profile_retry_cap_s);
    return now - w.last_tried >= wait;
}

/// Notes that `pubkey` was mentioned but has no known name yet.
fn wantProfile(pubkey: [32]u8) void {
    if (lookupProfile(pubkey)) |p| {
        if (p.name_len > 0) return;
    }
    for (&g_wanted) |*w| {
        if (w.used and std.mem.eql(u8, &w.pubkey, &pubkey)) return;
    }
    for (&g_wanted) |*w| {
        if (!w.used) {
            w.* = .{ .used = true, .pubkey = pubkey };
            return;
        }
    }
    // Genuinely full, which the size above is chosen to make impossible in
    // normal use. Take the slot that has gone longest without an answer rather
    // than dropping the request, because dropping it is what the old 48-slot
    // table did and it is the whole reason names never loaded.
    var oldest: ?*WantedProfile = null;
    for (&g_wanted) |*w| {
        if (oldest == null or w.last_tried < oldest.?.last_tried) oldest = w;
    }
    if (oldest) |w| w.* = .{ .used = true, .pubkey = pubkey };
}

/// Whether `pubkey`'s profile is still being fetched: no profile in hand yet, and
/// the wanted-set is still trying (attempts left). This distinguishes "loading"
/// (show a skeleton) from "gave up, or never on the relays" (show nothing), so a
/// handle placeholder does not linger forever for an author with no metadata.
fn profileLoading(pubkey: [32]u8) bool {
    if (lookupProfile(pubkey) != null) return false;
    for (&g_wanted) |*w| {
        // Still being asked for, because nothing is ever written off now.
        if (w.used and std.mem.eql(u8, &w.pubkey, &pubkey)) return true;
    }
    return false;
}

var g_profile_round: u64 = 0;
/// Quote re-ask rounds. Quotes still use a round counter; profiles moved to a
/// per-pubkey backoff, and the two shared this number only by accident.
const quote_rearm_rounds: u64 = 10;

/// Asks the relays for the metadata of everyone mentioned but still unnamed, in
/// one batch on a throwaway connection.
fn requestWantedProfiles() void {
    const now = nowSeconds();
    var batch: [wanted_profiles_cap][32]u8 = undefined;
    var n: usize = 0;
    for (&g_wanted) |*w| {
        if (!w.used) continue;
        // Resolved: free the slot so later mentions can use it.
        if (lookupProfile(w.pubkey)) |p| {
            if (p.name_len > 0) {
                w.* = .{};
                continue;
            }
        }
        if (!profileRetryDue(w, now)) continue;
        batch[n] = w.pubkey;
        n += 1;
        if (n == batch.len) break;
    }
    if (n == 0) return;

    // THE DISK FIRST, always. A notification's author is very often somebody
    // whose kind:0 is already in the store from the feed, a thread, or a
    // previous session, and this path never once looked. Every reference client
    // reads its cache before it opens a socket: NDK's `fetchProfile` returns
    // from the cache adapter before creating a subscription, and Jumble reads
    // IndexedDB and only refreshes past a three day staleness.
    //
    // Exact and cheap here, because the store has a composite author+kind index
    // and keeps at most one kind:0 per pubkey.
    var still_missing: [wanted_profiles_cap][32]u8 = undefined;
    var missing: usize = 0;
    if (g_store) |store| {
        const kinds = [_]u16{0};
        if (store.query(std.heap.page_allocator, .{ .authors = batch[0..n], .kinds = &kinds, .limit = @intCast(n) })) |res| {
            var result = res;
            defer result.deinit();
            for (result.events) |ev| {
                const prof = upsertProfile(ev.pubkey) orelse continue;
                if (std.mem.eql(u8, &prof.meta_id, &ev.id)) continue;
                parseMetadataInto(prof, ev.content);
                prof.meta_id = ev.id;
                g_names_generation +%= 1;
            }
        } else |_| {}
        for (batch[0..n]) |pk| {
            const known = if (lookupProfile(pk)) |prof| prof.name_len > 0 else false;
            if (known) {
                // Answered from disk. Retire the want rather than asking a relay
                // for something already held.
                for (&g_wanted) |*w| {
                    if (w.used and std.mem.eql(u8, &w.pubkey, &pk)) w.* = .{};
                }
                continue;
            }
            still_missing[missing] = pk;
            missing += 1;
        }
    } else {
        @memcpy(still_missing[0..n], batch[0..n]);
        missing = n;
    }
    if (missing == 0) return;

    // Only now, and only for what disk could not answer. The attempt is counted
    // HERE, after the network is known to be allowed, never before: counting it
    // first is what wrote names off during the seconds before the first relay
    // had finished its handshake.
    if (!networkAllowed()) return;
    for (still_missing[0..missing]) |pk| {
        for (&g_wanted) |*w| {
            if (!w.used or !std.mem.eql(u8, &w.pubkey, &pk)) continue;
            w.last_tried = now;
            w.attempts +|= 1;
        }
    }
    const thread = std.Thread.spawn(.{}, fetchProfilesOnce, .{ std.heap.page_allocator, still_missing, missing }) catch return;
    thread.detach();
}

/// Fetches kind:0 for `batch` and ingests it, then closes. Its own io backend
/// and signer, like every other background worker.
fn fetchProfilesOnce(gpa: std.mem.Allocator, batch: [wanted_profiles_cap][32]u8, len: usize) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    const kinds = [_]u16{0};
    const filters = [_]nostr.filter.Filter{.{ .authors = batch[0..len], .kinds = &kinds, .limit = @intCast(len) }};
    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        // A read-only or read-write relay. Asking a write-only relay to answer
        // a filter is asking the wrong question of it.
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();
        relay.subscribe("plaza-mentions", &filters) catch continue;
        while (true) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| _ = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch {},
                // Everything stored has been sent; no need to hold the socket.
                .eose => break,
                else => {},
            }
        }
        // Keep going: no single relay holds everyone's metadata, and the store
        // keeps only the newest copy of each anyway.
    }
}

// ------------------------------------------------------------------ quotes
//
// A note can quote another event (NIP-27 `nostr:nevent`/`note`). The quoted
// event's id is decoded once at parse time (Note.quote); this cache holds the
// resolved quoted note (author + a truncated body) keyed by that id, filled from
// the store as it grows and fetched from the pool when absent, mirroring the
// profile cache. The render side reads it to draw an embedded quote card.
const quote_cache_cap = 64;
/// After this many tries with no answer, a quote stops being asked for EVERY
/// round and starts backing off. It never stops being asked for.
///
/// It used to stop for good. Three unanswered tries and the entry was marked
/// missing, and nothing re-armed it: not a later round, not a reconnect, not the
/// reader opening the thread again. Three tries is nothing, and they can all
/// land while the pool is still dialling, so a note sitting on the reader's own
/// relays could be written off in the first seconds of the session and read
/// "not on your relays yet" for the rest of it. That is what happened to the
/// ancestor above a thread that every other client showed.
const quote_backoff_after = 3;
/// The longest a quote waits between tries, in profile-timer rounds (2s each),
/// so a note nobody has is asked for about once a minute rather than never or
/// constantly.
const quote_backoff_max_rounds: u32 = 30;
const quote_fetch_batch = 16;
/// Enough of a quoted note to fill the four lines 11f gives it (about 75
/// characters a line at the quote's register), so the clamp decides where the
/// text ends rather than the cache. 64 entries, so the whole table is ~20 KiB.
const quote_text_cap = 320;
/// Where a cached quote is in its life: asked for, in flight, in hand, or asked
/// for enough times that no relay has it.
pub const QuoteState = enum { idle, fetching, loaded, missing };

const QuoteEntry = struct {
    used: bool = false,
    id: [32]u8 = [_]u8{0} ** 32,
    state: QuoteState = .idle,
    attempts: u8 = 0,
    /// The round this entry may be asked for again. Zero means "now".
    next_round: u64 = 0,
    requested: bool = false,
    pubkey: [32]u8 = [_]u8{0} ** 32,
    created_at: i64 = 0,
    text_buf: [quote_text_cap]u8 = [_]u8{0} ** quote_text_cap,
    text_len: u16 = 0,
    /// The HOST of the picture the quoted note carries, when it carries one.
    ///
    /// The URL itself is deliberately cut out of `text_buf` (a raw image URL is
    /// not something to read), and nothing recorded that it had ever been there:
    /// a quoted note whose whole content is one picture came out of this cache
    /// with an empty body and drew a card with a name, a time and nothing else,
    /// which reads as a rendering fault rather than as a picture.
    ///
    /// The host and not the URL, because the card cannot show the picture: all
    /// sixteen registry slots are spoken for (nine avatars, a banner, six feed
    /// pictures) and taking one here would mean taking it from those. Pressing
    /// the card opens the quoted note, where the picture draws with a real slot.
    image_host_buf: [48]u8 = [_]u8{0} ** 48,
    image_host_len: u8 = 0,
    /// What the quoted note itself quotes, if anything. Depth stops here (11g):
    /// one hop is a pill saying where it goes, never a third nested body. The
    /// reference is decoded from the event's own content at fill time, because
    /// the stored text is rendered and clamped and can drop the token entirely.
    quote_of: [32]u8 = [_]u8{0} ** 32,
    has_quote_of: bool = false,
    last_used: u64 = 0,
};
var g_quotes = [_]QuoteEntry{.{}} ** quote_cache_cap;
var g_quote_clock: u64 = 0;
/// Ticks once per profile-timer round (2s). The backoff is counted in these.
var g_quote_round: u64 = 0;
/// The pool as the last tick saw it, so a change in it can be noticed.
var g_last_live_relays: usize = std.math.maxInt(usize);
var g_last_relay_count: usize = std.math.maxInt(usize);

/// A link preview: what a page says about itself, for the card 11o draws under a
/// note that links out. Small and fixed, like every other cache here.
const link_title_cap = 96;
const link_desc_cap = 140;
const link_domain_cap = 48;
const link_cache_cap = 32;
/// How many previews may be in flight at once. The SDK has 16 effect slots for
/// everything the app does, so previews take a small, fixed share and wait their
/// turn rather than starving avatars and pictures.
const max_link_fetches = 2;
const max_link_attempts = 2;
/// How far down a thread the link scan reaches. The thread list has no visible
/// range of its own to consult, so it takes the first screenful and stops.
const thread_link_scan_cap: usize = 12;

const LinkPreview = struct {
    used: bool = false,
    /// The URL as written in the note, which is both the key and what a press
    /// opens.
    url_buf: [300]u8 = [_]u8{0} ** 300,
    url_len: u16 = 0,
    state: enum { idle, fetching, loaded, missing } = .idle,
    attempts: u8 = 0,
    requested: bool = false,
    title_buf: [link_title_cap]u8 = [_]u8{0} ** link_title_cap,
    title_len: u8 = 0,
    desc_buf: [link_desc_cap]u8 = [_]u8{0} ** link_desc_cap,
    desc_len: u8 = 0,
    domain_buf: [link_domain_cap]u8 = [_]u8{0} ** link_domain_cap,
    domain_len: u8 = 0,
    last_used: u64 = 0,

    pub fn url(self: *const LinkPreview) []const u8 {
        return self.url_buf[0..self.url_len];
    }
    pub fn title(self: *const LinkPreview) []const u8 {
        return self.title_buf[0..self.title_len];
    }
    pub fn description(self: *const LinkPreview) []const u8 {
        return self.desc_buf[0..self.desc_len];
    }
    pub fn domain(self: *const LinkPreview) []const u8 {
        return self.domain_buf[0..self.domain_len];
    }
};
var g_links = [_]LinkPreview{.{}} ** link_cache_cap;
var g_link_clock: u64 = 0;

/// The host of a URL, without its `www.`: what the card shows above the title,
/// and what a reader actually checks before pressing.
///
/// The userinfo is CUT, at the last `@`, which is the whole point: a browser
/// does the same, because `https://wirth.ch@evil.tld/` is the oldest phishing
/// shape there is and a card that showed `wirth.ch@evil.tld` would be lending
/// its credibility to whoever wrote the note.
pub fn urlDomain(url: []const u8) []const u8 {
    var rest = url;
    if (std.mem.indexOf(u8, rest, "://")) |i| rest = rest[i + 3 ..];
    const end = std.mem.indexOfAny(u8, rest, "/?#") orelse rest.len;
    var authority = rest[0..end];
    if (std.mem.lastIndexOfScalar(u8, authority, '@')) |at| authority = authority[at + 1 ..];
    // The port is not part of the name a reader recognises.
    if (std.mem.lastIndexOfScalar(u8, authority, ':')) |colon| {
        if (std.mem.indexOfScalar(u8, authority, ']') == null) authority = authority[0..colon];
    }
    if (std.mem.startsWith(u8, authority, "www.")) authority = authority["www.".len..];
    return authority;
}

/// Whether a link named in a note may be fetched to preview it.
///
/// This is the one place in the app that reaches out to an address a STRANGER
/// chose, unattended, simply because a note scrolled into view. So it is narrow
/// on purpose:
///
///   - https only. Plaintext would put the reader's IP and the exact URL on the
///     wire for anyone on the path, to fetch something nobody asked for.
///   - No userinfo. `std.http.Client` turns it into an `authorization` header,
///     so `http://admin:admin@10.0.0.1/` would have Plaza posting credentials
///     to a host of the note author's choosing.
///   - No private, loopback or link-local address, and no name without a dot.
///     A note must not be able to make every reader's machine probe their own
///     network. Notary's approval API listens on 127.0.0.1 in this very session.
///   - The default port only, so a note cannot aim the reader at a service.
///
/// It cannot stop a redirect INTO one of those (the runtime follows up to
/// three), which is worth knowing and is why the fetch stays unauthenticated and
/// its body is only ever read for two meta tags.
pub fn previewableUrl(url: []const u8) bool {
    if (!std.mem.startsWith(u8, url, "https://")) return false;
    if (url.len > 300) return false;
    const rest = url["https://".len..];
    const end = std.mem.indexOfAny(u8, rest, "/?#") orelse rest.len;
    const authority = rest[0..end];
    if (authority.len == 0) return false;
    // Userinfo, in any form.
    if (std.mem.indexOfScalar(u8, authority, '@') != null) return false;
    var host = authority;
    if (std.mem.lastIndexOfScalar(u8, host, ':')) |colon| {
        if (std.mem.indexOfScalar(u8, host, ']') == null) {
            // A port at all means a service, not a site.
            if (colon + 1 < host.len) return false;
            host = host[0..colon];
        } else {
            return false; // a bracketed IPv6 literal is never a site to preview
        }
    }
    for (host) |c| {
        if (!std.ascii.isAlphanumeric(c) and c != '.' and c != '-') return false;
    }
    // A bare name (`localhost`, a machine on the LAN) is not a public site.
    const dot = std.mem.lastIndexOfScalar(u8, host, '.') orelse return false;
    if (dot == 0 or dot + 1 >= host.len) return false;
    if (std.ascii.endsWithIgnoreCase(host, ".local") or
        std.ascii.endsWithIgnoreCase(host, ".internal") or
        std.ascii.endsWithIgnoreCase(host, ".localhost")) return false;
    return !isPrivateAddress(host);
}

/// Whether a host is a literal address inside a range that belongs to the
/// reader's own machine or network.
fn isPrivateAddress(host: []const u8) bool {
    var parts: [4]u16 = undefined;
    var n: usize = 0;
    var it = std.mem.splitScalar(u8, host, '.');
    while (it.next()) |part| {
        if (n == 4) return false;
        parts[n] = std.fmt.parseInt(u16, part, 10) catch return false;
        if (parts[n] > 255) return false;
        n += 1;
    }
    if (n != 4) return false; // not an IPv4 literal at all
    return switch (parts[0]) {
        0, 10, 127 => true,
        169 => parts[1] == 254, // link-local
        172 => parts[1] >= 16 and parts[1] <= 31,
        192 => parts[1] == 168,
        100 => parts[1] >= 64 and parts[1] <= 127, // carrier-grade NAT
        else => false,
    };
}

/// The first plain link in a note's content: the one the card previews. An image
/// URL is not one (it is drawn as the picture), and neither is anything inside a
/// `nostr:` token.
pub fn firstLinkUrl(content: []const u8, image_url: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i < content.len) : (i += 1) {
        if (!std.mem.startsWith(u8, content[i..], "https://") and !std.mem.startsWith(u8, content[i..], "http://")) continue;
        if (i > 0 and !std.ascii.isWhitespace(content[i - 1])) continue;
        var j = i;
        while (j < content.len and !std.ascii.isWhitespace(content[j])) j += 1;
        // A trailing sentence mark is punctuation, not part of the address.
        var end = j;
        while (end > i and (content[end - 1] == '.' or content[end - 1] == ',' or content[end - 1] == ')')) end -= 1;
        const candidate = content[i..end];
        if (candidate.len > 300) {
            i = j;
            continue;
        }
        if (image_url.len > 0 and std.mem.eql(u8, candidate, image_url)) {
            i = j;
            continue;
        }
        if (looksLikeImageUrl(candidate)) {
            i = j;
            continue;
        }
        return candidate;
    }
    return null;
}

/// The cache entry for `url`, claimed if it is not already there. Evicts the
/// least recently drawn entry that is not mid-fetch, like the other caches.
fn wantLink(url: []const u8) ?*LinkPreview {
    if (url.len == 0 or url.len > 300) return null;
    for (&g_links) |*l| {
        if (l.used and std.mem.eql(u8, l.url(), url)) return l;
    }
    var victim: ?*LinkPreview = null;
    for (&g_links) |*l| {
        if (!l.used) {
            victim = l;
            break;
        }
        if (l.state == .fetching) continue;
        // Nor one already wanted in THIS pass: a screen with more links than
        // slots would otherwise evict an entry it needs a moment later, reset
        // its state and its attempt count, and re-fetch the same pages from the
        // same strangers' servers on every tick, forever. The media scan learned
        // this the same way.
        if (l.last_used == g_link_clock) continue;
        if (victim == null or l.last_used < victim.?.last_used) victim = l;
    }
    // Nothing free and nothing spare: this link simply goes unpreviewed rather
    // than taking a slot off something on screen.
    const slot = victim orelse return null;
    slot.* = .{ .used = true };
    @memcpy(slot.url_buf[0..url.len], url);
    slot.url_len = @intCast(url.len);
    const host = urlDomain(url);
    const host_len = @min(host.len, slot.domain_buf.len);
    @memcpy(slot.domain_buf[0..host_len], host[0..host_len]);
    slot.domain_len = @intCast(host_len);
    return slot;
}

/// Puts a loaded link preview in the cache, so a view test can render a card
/// without a network round trip. The long-description case is the one that
/// matters: it is what used to run off the side of the window.
/// A feed note carrying `url` as its link, for view tests.
pub fn noteWithLinkForTest(url: []const u8) Note {
    var n = Note{};
    n.id = 1;
    const u = @min(url.len, n.link_url_buf.len);
    @memcpy(n.link_url_buf[0..u], url[0..u]);
    n.link_url_len = @intCast(u);
    return n;
}

pub fn setLinkPreviewForTest(url: []const u8, domain: []const u8, title: []const u8, description: []const u8) void {
    for (&g_links) |*l| {
        if (l.used) continue;
        l.* = .{ .used = true, .state = .loaded };
        const u = @min(url.len, l.url_buf.len);
        @memcpy(l.url_buf[0..u], url[0..u]);
        l.url_len = @intCast(u);
        const d = @min(domain.len, l.domain_buf.len);
        @memcpy(l.domain_buf[0..d], domain[0..d]);
        l.domain_len = @intCast(d);
        const t = @min(title.len, l.title_buf.len);
        @memcpy(l.title_buf[0..t], title[0..t]);
        l.title_len = @intCast(t);
        const c = @min(description.len, l.desc_buf.len);
        @memcpy(l.desc_buf[0..c], description[0..c]);
        l.desc_len = @intCast(c);
        return;
    }
}

pub fn clearLinkPreviewsForTest() void {
    for (&g_links) |*l| l.* = .{};
}

fn linkFor(url: []const u8) ?*LinkPreview {
    for (&g_links) |*l| {
        if (l.used and std.mem.eql(u8, l.url(), url)) return l;
    }
    return null;
}

/// Asks for the pages the reader can actually see. Gated by the previews
/// setting, like pictures: with it off, no page learns it was linked to.
fn scanLinkFetches(fx: *Effects, model: *const Model) void {
    if (!g_media_previews) return;
    g_link_clock += 1;
    var fired: usize = 0;
    if (model.viewing_profile != null) {
        // A person's page occludes the feed. Without this branch the hidden
        // feed keeps reaching out to hosts nobody is looking at, and the page
        // that IS being read gets no link cards at all.
        const shown = @min(model.thread_notes_len, thread_link_scan_cap);
        for (model.thread_notes[0..shown]) |*note| fireLink(fx, note, &fired);
        return;
    }
    if (model.viewing_thread != 0) {
        // The note being read, and the first screenful under it. Walking the
        // whole conversation would reach out to every host linked anywhere in
        // it, including replies the reader never scrolls to.
        fireLink(fx, &model.thread_root, &fired);
        const shown = @min(model.thread_notes_len, thread_link_scan_cap);
        for (model.thread_notes[0..shown]) |*note| fireLink(fx, note, &fired);
        return;
    }
    const range = model.visibleRange();
    var i = range.first;
    while (i <= range.last and i < model.notes_len) : (i += 1) fireLink(fx, &model.notes[i], &fired);
}

fn fireLink(fx: *Effects, note: *const Note, fired: *usize) void {
    if (!note.hasLink()) return;
    if (!previewableUrl(note.linkUrl())) return;
    const slot = wantLink(note.linkUrl()) orelse return;
    // Stamped first, so the eviction guard above counts this entry as wanted in
    // this pass whatever happens next.
    slot.last_used = g_link_clock;
    if (slot.state != .idle) return;
    if (slot.attempts >= max_link_attempts) {
        slot.state = .missing;
        return;
    }
    if (loadCachedLink(slot)) return;
    if (fired.* >= max_link_fetches) return;
    fired.* += 1;
    slot.state = .fetching;
    slot.attempts += 1;
    const index = (@intFromPtr(slot) - @intFromPtr(&g_links[0])) / @sizeOf(LinkPreview);
    fx.fetch(.{
        .key = link_fetch_key_base + index,
        .url = slot.url(),
        .on_response = Effects.responseMsg(.link_fetched),
    });
}

/// Files what a page said about itself. The body is TRUNCATED at 256 KiB by the
/// runtime and that is fine here, unlike an image: `og:` tags live in the head,
/// so a cut tail costs nothing. Every other handler in this app rejects a
/// truncated body, correctly, because half a picture is garbage.
fn handleLinkFetched(response: native_sdk.EffectResponse) void {
    const index = response.key - link_fetch_key_base;
    if (index >= g_links.len) return;
    const slot = &g_links[index];
    if (!slot.used or slot.state != .fetching) return;
    if (response.outcome == .rejected) {
        // Every effect slot was busy. Not a failure of the page: try again.
        slot.state = .idle;
        slot.attempts -|= 1;
        return;
    }
    if (response.outcome != .ok or response.status < 200 or response.status >= 300) {
        slot.state = if (slot.attempts >= max_link_attempts) .missing else .idle;
        return;
    }
    const meta = parsePageMeta(response.body);
    storeLinkMeta(slot, .{ .title = meta.heading(), .description = meta.description });
    slot.state = if (slot.title_len == 0) .missing else .loaded;
    if (slot.state == .loaded) cacheLink(slot);
}

/// Copies what the page said into the entry's own buffers: the response body is
/// recycled the moment this returns.
fn storeLinkMeta(slot: *LinkPreview, meta: PageMeta) void {
    const title = std.mem.trim(u8, meta.title, " \t\r\n");
    const desc = std.mem.trim(u8, meta.description, " \t\r\n");
    const t = @min(utf8SafeLen(title, slot.title_buf.len), slot.title_buf.len);
    @memcpy(slot.title_buf[0..t], title[0..t]);
    slot.title_len = @intCast(t);
    const d = @min(utf8SafeLen(desc, slot.desc_buf.len), slot.desc_buf.len);
    @memcpy(slot.desc_buf[0..d], desc[0..d]);
    slot.desc_len = @intCast(d);
}

/// `$HOME/.plaza/links/<sha256 of the url>`, holding the three lines the card
/// draws. A preview is worth keeping: the page rarely changes, and a feed
/// re-read from disk should not re-ask the whole web what it said.
fn linkCacheDir(io: std.Io, environ: *const std.process.Environ.Map) !std.Io.Dir {
    const home = environ.get("HOME") orelse ".";
    var dir_buf: [512]u8 = undefined;
    const dir_path = try std.fmt.bufPrint(&dir_buf, "{s}/.plaza/links", .{home});
    return std.Io.Dir.cwd().createDirPathOpen(io, dir_path, .{});
}

fn loadCachedLink(slot: *LinkPreview) bool {
    const io = g_io orelse return false;
    const environ = g_environ orelse return false;
    var dir = linkCacheDir(io, environ) catch return false;
    defer dir.close(io);
    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, slot.url());
    const gpa = std.heap.page_allocator;
    const raw = dir.readFileAlloc(io, name, gpa, std.Io.Limit.limited(1024)) catch return false;
    defer gpa.free(raw);

    var lines = std.mem.splitScalar(u8, raw, '\n');
    const title = lines.next() orelse return false;
    const desc = lines.next() orelse "";
    if (title.len == 0) return false;
    storeLinkMeta(slot, .{ .title = title, .description = desc });
    slot.state = .loaded;
    return true;
}

fn cacheLink(slot: *const LinkPreview) void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = linkCacheDir(io, environ) catch return;
    defer dir.close(io);
    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, slot.url());
    var buf: [link_title_cap + link_desc_cap + 4]u8 = undefined;
    const data = std.fmt.bufPrint(&buf, "{s}\n{s}\n", .{ slot.title(), slot.description() }) catch return;
    dir.writeFile(io, .{ .sub_path = name, .data = data }) catch return;
}

/// What a page says about itself, read out of its head. Open Graph first, then
/// the plain HTML fallbacks, which is the order every other reader uses.
pub const PageMeta = struct {
    /// The `<title>` tag, kept separately so an Open Graph title can take
    /// precedence without erasing it when it turns out to be empty.
    title: []const u8 = "",
    og_title: []const u8 = "",
    description: []const u8 = "",

    /// What the card shows: the page's chosen title, else the document's.
    pub fn heading(self: PageMeta) []const u8 {
        return if (self.og_title.len > 0) self.og_title else self.title;
    }
};

/// Pulls `og:title`/`og:description` (falling back to `<title>` and
/// `meta name="description"`) out of `html`.
///
/// A deliberately small parser: it walks tags, and inside a `meta` tag it reads
/// the attributes it knows. It does NOT try to be an HTML parser, because it does
/// not have to be: the body arrives capped at 256 KiB, which is where the head
/// lives, and anything it cannot make sense of simply leaves the card without
/// that line rather than guessing.
pub fn parsePageMeta(html: []const u8) PageMeta {
    var out: PageMeta = .{};
    var i: usize = 0;
    while (i < html.len) : (i += 1) {
        if (html[i] != '<') continue;
        const rest = html[i + 1 ..];
        if (std.ascii.startsWithIgnoreCase(rest, "title>")) {
            const start = i + 1 + "title>".len;
            const end = std.mem.indexOfPos(u8, html, start, "<") orelse html.len;
            if (out.title.len == 0) out.title = std.mem.trim(u8, html[start..end], " \t\r\n");
            i = end;
            continue;
        }
        if (!std.ascii.startsWithIgnoreCase(rest, "meta")) continue;
        const tag_end = std.mem.indexOfScalarPos(u8, html, i, '>') orelse break;
        const tag = html[i..tag_end];
        const key = metaAttr(tag, "property") orelse metaAttr(tag, "name") orelse {
            i = tag_end;
            continue;
        };
        const content = metaAttr(tag, "content") orelse {
            i = tag_end;
            continue;
        };
        // An EMPTY value is not an answer: a template that renders
        // `content=""` when its Open Graph field is unset must not wipe the
        // page's own title. And the FIRST one wins, so a stray tag in the body
        // cannot override the head.
        if (content.len == 0) {
            i = tag_end;
            continue;
        }
        if (std.ascii.eqlIgnoreCase(key, "og:title")) {
            if (out.og_title.len == 0) out.og_title = content;
        } else if (std.ascii.eqlIgnoreCase(key, "og:description")) {
            if (out.description.len == 0) out.description = content;
        } else if (std.ascii.eqlIgnoreCase(key, "description") and out.description.len == 0) {
            out.description = content;
        }
        i = tag_end;
    }
    return out;
}

/// One attribute's value out of a tag, single or double quoted.
fn metaAttr(tag: []const u8, name: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (std.ascii.indexOfIgnoreCasePos(tag, i, name)) |at| {
        i = at + name.len;
        // A whole attribute name, not a suffix of another one.
        if (at > 0 and (std.ascii.isAlphanumeric(tag[at - 1]) or tag[at - 1] == '-' or tag[at - 1] == ':')) continue;
        var j = i;
        while (j < tag.len and (tag[j] == ' ' or tag[j] == '=')) j += 1;
        if (j >= tag.len) return null;
        const quote = tag[j];
        if (quote != '"' and quote != '\'') continue;
        j += 1;
        const end = std.mem.indexOfScalarPos(u8, tag, j, quote) orelse return null;
        return tag[j..end];
    }
    return null;
}

/// Records that a quoted event `id` needs resolving, deduping and (when full)
/// evicting the least-recently-drawn entry that is not mid-fetch.
fn wantQuote(id: [32]u8) void {
    for (&g_quotes) |*q| {
        if (q.used and std.mem.eql(u8, &q.id, &id)) return;
    }
    for (&g_quotes) |*q| {
        if (!q.used) {
            q.* = .{ .used = true, .id = id };
            return;
        }
    }
    var victim: ?*QuoteEntry = null;
    for (&g_quotes) |*q| {
        if (q.state == .fetching) continue;
        if (victim == null or q.last_used < victim.?.last_used) victim = q;
    }
    // Every slot mid-fetch: still record the newcomer over the overall LRU. The
    // evicted entry's fetch merely ingests into the store, so nothing is lost by
    // dropping its slot, and the new quote is never silently forgotten.
    if (victim == null) {
        for (&g_quotes) |*q| {
            if (victim == null or q.last_used < victim.?.last_used) victim = q;
        }
    }
    if (victim) |v| v.* = .{ .used = true, .id = id };
}

/// The cache entry for a quoted event `id` (marking it drawn this frame so the
/// LRU keeps it), or null when it is not cached.
fn quoteFor(id: [32]u8) ?*QuoteEntry {
    for (&g_quotes) |*q| {
        if (q.used and std.mem.eql(u8, &q.id, &id)) {
            g_quote_clock += 1;
            q.last_used = g_quote_clock;
            return q;
        }
    }
    return null;
}

/// Fills any unresolved quote from the store (it grew, so the fetch may have
/// landed): copies the quoted author and a truncated body, and asks for the
/// author's name. Gives up (marks missing) once every relay has been tried.
fn refreshQuotes(store: *nostr.store.Store) void {
    // The nested references this pass finds, asked for once it is over (see the
    // note where they are collected).
    var nested: [quote_cache_cap][32]u8 = undefined;
    var nested_count: usize = 0;
    for (&g_quotes) |*q| {
        if (!q.used or q.state == .loaded or q.state == .missing) continue;
        var se = (store.getEvent(std.heap.page_allocator, q.id) catch continue) orelse {
            // `.missing` is what the ROW says, not a decision to stop looking:
            // the card reads "not on your relays yet", which is true, and the
            // backoff keeps asking in case it stops being true.
            if (q.attempts >= quote_backoff_after) q.state = .missing;
            continue;
        };
        defer se.deinit();
        q.pubkey = se.event.pubkey;
        q.created_at = se.event.created_at;
        var tmp: [note_content_cap]u8 = undefined;
        const omit = firstImageUrl(se.event.content) orelse "";
        const host = urlHost(omit);
        const host_len = @min(host.len, q.image_host_buf.len);
        @memcpy(q.image_host_buf[0..host_len], host[0..host_len]);
        q.image_host_len = @intCast(host_len);
        const wrote = renderContent(&tmp, se.event.content, omit);
        const keep = utf8SafeLen(tmp[0..wrote], q.text_buf.len);
        @memcpy(q.text_buf[0..keep], tmp[0..keep]);
        q.text_len = @intCast(keep);
        // Decoded from the ORIGINAL content, not the stored text: the stored
        // text is rendered and capped, so the token can be gone from it.
        var probe = Note{};
        const probe_len = @min(se.event.content.len, probe.content_buf.len);
        @memcpy(probe.content_buf[0..probe_len], se.event.content[0..probe_len]);
        probe.content_len = @intCast(probe_len);
        findQuoteRef(&probe);
        q.has_quote_of = probe.quote.kind == .event;
        if (q.has_quote_of) {
            q.quote_of = probe.quote.id;
            // Asked for AFTER this pass, never during it: `wantQuote` writes over
            // whichever slot it evicts, and the entry being filled here is the
            // one it picks first (it is `.idle` and has never been drawn, so its
            // clock is the minimum). Evicting it mid-fill left the nested id
            // cached as loaded with a zero author and an empty body, permanently,
            // because a loaded entry is never retried.
            if (nested_count < nested.len) {
                nested[nested_count] = q.quote_of;
                nested_count += 1;
            }
        }
        q.state = .loaded;
        wantProfile(q.pubkey);
    }
    for (nested[0..nested_count]) |id| wantQuote(id);
}

/// Lets the still-unresolved quotes be asked for again on the next round.
fn rearmWantedQuotes() void {
    for (&g_quotes) |*q| {
        if (q.used and q.state != .loaded) q.requested = false;
    }
}

/// How long a quote waits before the next try: every round until it has been
/// asked `quote_backoff_after` times, then doubling to a ceiling.
fn quoteBackoffRounds(attempts: u8) u64 {
    if (attempts < quote_backoff_after) return 1;
    const over = attempts - quote_backoff_after;
    const shift: u6 = @intCast(@min(over, 5));
    return @min(@as(u64, 1) << shift, quote_backoff_max_rounds);
}

/// Every unresolved quote may be asked for again, now.
///
/// The pool changed, so the answer may have too: a relay the reader just added,
/// or one that just finished dialling, can hold exactly the note that was
/// written off while nothing was connected.
/// Whether this build may open a socket of its own accord.
///
/// False under `zig build test`, and not as tidiness. The feed's background
/// fetchers are reached from `reconcile`, so every test that reconciles was
/// spawning a thread and completing TLS handshakes against public relays. It
/// made the perf numbers a measurement of the network (a profiler found
/// `relay.dial` and `handshake` at the top of a run that was supposed to be
/// timing a feed rebuild), it made the suite slow and flaky, and it sent
/// traffic from every machine that ran the tests.
///
/// Comptime, so the shipped binary has no branch. Anything that genuinely needs
/// to exercise a fetcher should drive its ingest seam with an event, which is
/// what the tests that care already do.
fn networkAllowed() bool {
    return !builtin.is_test;
}

fn requeueMissingQuotes() void {
    for (&g_quotes) |*q| {
        if (!q.used or q.state == .loaded) continue;
        q.next_round = 0;
        q.requested = false;
    }
}

/// Asks the pool for any quoted events not yet in the store, one batch on a
/// throwaway connection, bounded like the mention fetch.
fn requestWantedQuotes() void {
    var batch: [quote_fetch_batch][32]u8 = undefined;
    var n: usize = 0;
    for (&g_quotes) |*q| {
        if (!q.used or q.state == .loaded) continue;
        if (q.requested or q.next_round > g_quote_round) continue;
        batch[n] = q.id;
        n += 1;
        q.requested = true;
        if (q.attempts < std.math.maxInt(u8)) q.attempts += 1;
        q.next_round = g_quote_round + quoteBackoffRounds(q.attempts);
        // `.fetching` only while it has never been found: an entry already
        // reported missing keeps saying so on the card while the retry is out,
        // rather than flickering back to a skeleton every time it is retried.
        if (q.state != .missing) q.state = .fetching;
        if (n == batch.len) break;
    }
    if (n == 0) return;
    if (!networkAllowed()) return;
    const thread = std.Thread.spawn(.{}, fetchQuotesOnce, .{ std.heap.page_allocator, batch, n }) catch return;
    thread.detach();
}

/// Fetches the quoted events in `batch` by id and ingests them, then closes.
/// The next store-growth tick flips them to `.loaded` via `refreshQuotes`.
fn fetchQuotesOnce(gpa: std.mem.Allocator, batch: [quote_fetch_batch][32]u8, len: usize) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    const filters = [_]nostr.filter.Filter{.{ .ids = batch[0..len], .limit = @intCast(len) }};
    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        // A read-only or read-write relay. Asking a write-only relay to answer
        // a filter is asking the wrong question of it.
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();
        relay.subscribe("plaza-quotes", &filters) catch continue;
        while (true) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| _ = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch {},
                .eose => break,
                else => {},
            }
        }
    }
}

/// Clears the quote cache. For tests, which share the process globals.
pub fn resetQuotesForTest() void {
    g_quotes = [_]QuoteEntry{.{}} ** quote_cache_cap;
    g_quote_clock = 0;
}

/// Builds a Note over `content` and runs the quote-reference scan, so a test can
/// assert what `findQuoteRef` captured (id/off/len) without a live event.
pub fn findQuoteRefForTest(content: []const u8) Note {
    var note = Note{};
    const n = @min(content.len, note.content_buf.len);
    @memcpy(note.content_buf[0..n], content[0..n]);
    note.content_len = @intCast(n);
    findQuoteRef(&note);
    return note;
}

/// Whether the note captured an event quote (for tests).
pub fn noteHasEventQuote(note: *const Note) bool {
    return note.quote.kind == .event;
}

/// A cached author profile.
const Profile = struct {
    used: bool = false,
    pubkey: [32]u8 = [_]u8{0} ** 32,
    name_buf: [64]u8 = [_]u8{0} ** 64,
    /// kind:0 `name`: the username, kept even when `display_name` wins the line
    /// above it, because it is what the handle line shows without a NIP-05.
    username_buf: [64]u8 = [_]u8{0} ** 64,
    username_len: u8 = 0,
    name_len: u8 = 0,
    // The kind:0 `nip05` identifier (`name@domain`), and where its verification
    // stands. The check draws only on `.verified`: a well-known lookup that maps
    // the name back to this pubkey, never on mere presence of the string.
    nip05_buf: [128]u8 = [_]u8{0} ** 128,
    nip05_len: u8 = 0,
    /// kind:0 `website`, kept for the handle line's last fallback before the
    /// npub. Shown as its host, because a full URL under a name is a link the
    /// row has no room for and nobody reads.
    website_buf: [128]u8 = [_]u8{0} ** 128,
    website_len: u8 = 0,
    nip05_state: enum { idle, fetching, verified, failed } = .idle,
    picture_buf: [200]u8 = [_]u8{0} ** 200,
    picture_len: u8 = 0,
    /// The resolved avatar URL, which is also its cache key.
    url_buf: [1024]u8 = [_]u8{0} ** 1024,
    url_len: u16 = 0,
    /// The id of the kind:0 event these fields came from, so an unchanged
    /// event is never parsed twice (the store keeps only the newest per
    /// author, but the feed reconciles every second).
    meta_id: [32]u8 = [_]u8{0} ** 32,
    // The avatar's lifecycle: not yet fetched, in flight, registered, or given
    // up on (initials fallback).
    avatar_state: enum { idle, fetching, loaded, failed } = .idle,
    /// Fetches of this face that came back unusable for a reason worth retrying.
    /// Cleared on a successful load, on a changed picture URL, and by the
    /// Settings retry.
    avatar_attempts: u8 = 0,
    /// Whether this face's BYTES have been pulled into the disk cache ahead of
    /// being needed. Separate from `avatar_state` because that one is about a
    /// registry id and there are only nine of those: warming is what a row just
    /// off the bottom of the viewport can do without one.
    warm_state: enum { idle, fetching, done } = .idle,
    // The registered canvas-image id for this profile's avatar (0 = none). NOT
    // fixed per cache slot: there are only `max_avatar_images` registry ids for
    // far more cached authors, so ids are lent to whoever is on screen now and
    // reclaimed from whoever scrolled away (see `assignAvatarSlots`).
    image_id: u64 = 0,
    // The last avatar pass this author was on screen, so the id LRU evicts the
    // least-recently-seen author when it needs a slot for a new one.
    avatar_clock: u64 = 0,

    fn name(self: *const Profile) []const u8 {
        return self.name_buf[0..self.name_len];
    }
    pub fn username(self: *const Profile) []const u8 {
        return self.username_buf[0..self.username_len];
    }
    fn website(self: *const Profile) []const u8 {
        return self.website_buf[0..self.website_len];
    }
    /// The host on its own: `https://fiatjaf.com/about` reads as `fiatjaf.com`.
    fn websiteHost(self: *const Profile) []const u8 {
        return urlHost(self.website());
    }
    fn nip05(self: *const Profile) []const u8 {
        return self.nip05_buf[0..self.nip05_len];
    }
    fn picture(self: *const Profile) []const u8 {
        return self.picture_buf[0..self.picture_len];
    }
    fn url(self: *const Profile) []const u8 {
        return self.url_buf[0..self.url_len];
    }
};

var g_profiles = [_]Profile{.{}} ** profile_cap;

// The avatar-id LRU clock (see `assignAvatarSlots`): bumped once per avatar
// pass; a profile's `avatar_clock` records the last pass it was on screen.
var g_avatar_clock: u64 = 0;

// Bumped whenever a profile gains or changes a display name. Mention labels are
// baked into note text at parse time, so the feed re-parses (rather than
// reuses) its notes when this moves; author lines resolve live and never need it.
var g_names_generation: u64 = 0;

/// Clears the profile cache. For tests, which share the process globals.
pub fn resetProfilesForTest() void {
    g_profiles = [_]Profile{.{}} ** profile_cap;
    @memset(&g_profile_index, 0);
    g_names_generation = 0;
    g_notes_names_generation = 0;
    g_avatar_clock = 0;
}

/// Drops a cached avatar. `parseMetadataInto` only ever REPLACES a picture URL,
/// which is right for an incoming profile (an absent key is silence, not a
/// removal) and wrong for an edit made here, where clearing the field IS the
/// removal and the old face would otherwise keep being drawn.
fn clearProfilePicture(pubkey: [32]u8) void {
    const profile = lookupProfile(pubkey) orelse return;
    profile.picture_len = 0;
    profile.url_len = 0;
    profile.avatar_state = .idle;
    profile.image_id = 0;
}

/// Marks `pubkey`'s profile as having (or not having) a kind:0 picture, so a
/// test can exercise the avatar-id LRU without a real fetch.
pub fn setProfilePictureForTest(pubkey: [32]u8, present: bool) void {
    const p = upsertProfile(pubkey) orelse return;
    p.picture_len = if (present) 8 else 0;
    if (present) @memcpy(p.picture_buf[0..8], "http://x");
}

/// The registry image id currently lent to `pubkey`'s avatar (0 = none). For
/// tests of the id LRU.
/// Puts a profile in the state the avatar pipeline would leave it in, so a view
/// test can ask what the widget does with it without a network round trip.
pub fn setProfileAvatarForTest(pubkey: [32]u8, image_id: u64, state: enum { idle, fetching, loaded, failed }) void {
    const p = upsertProfile(pubkey) orelse return;
    p.image_id = image_id;
    p.avatar_state = switch (state) {
        .idle => .idle,
        .fetching => .fetching,
        .loaded => .loaded,
        .failed => .failed,
    };
}

pub fn avatarImageIdForTest(pubkey: [32]u8) u64 {
    const p = lookupProfile(pubkey) orelse return 0;
    return p.image_id;
}

/// Runs one avatar-id assignment pass, for tests.
pub fn assignAvatarSlotsForTest(fx: *Effects, model: *const Model) void {
    wantProfilesAhead(model);
    assignAvatarSlots(fx, model);
}

// The notes this session has liked, so the heart renders filled and an un-like
// knows which reaction (kind:7) to delete. In-memory: this is the optimistic
// layer, not the source of truth.
//
// Every entry records WHOSE like it is, and that is not decoration. The key was
// the note id alone, which is identical under every account, and nothing ever
// cleared the table. So a note liked as one account showed a filled red heart
// to the next account signed in on the same machine, who had never touched it,
// and their first press took the UN-like branch: Plaza signed a kind:5 under
// THEIR key naming a reaction the other account authored. That is a public,
// permanent, on-relay link between two identities the reader was keeping apart,
// it destroys the app's only record of the first account's reaction, and their
// intended like never publishes at all.
//
// An owner makes that impossible by construction rather than by remembering to
// clear the table on every door out of an account, which is the version of this
// fix that goes stale the first time somebody adds another door.
const my_likes_cap = 512;
const MyLike = struct {
    used: bool = false,
    owner: [32]u8 = [_]u8{0} ** 32,
    note_id: i64 = 0,
    // The id of our own kind:7 reaction, e-tagged by the kind:5 that un-likes it.
    reaction_id: [32]u8 = [_]u8{0} ** 32,
};
var g_my_likes = [_]MyLike{.{}} ** my_likes_cap;

/// Whether the signed-in account has liked `note_id`.
fn isLiked(note_id: i64) bool {
    return likeEntry(note_id) != null;
}

/// The signed-in account's like record for `note_id`, or null. A guest has no
/// likes, and neither does anyone else's entry.
fn likeEntry(note_id: i64) ?*MyLike {
    const me = activePubkey() orelse return null;
    for (&g_my_likes) |*e| {
        if (e.used and e.note_id == note_id and std.mem.eql(u8, &e.owner, &me)) return e;
    }
    return null;
}

/// Records a like on `note_id` with our reaction's id, so the heart fills and an
/// un-like can find the reaction. Silently drops when the table is full (the
/// like still publishes; only the optimistic bookkeeping is skipped).
fn rememberLike(note_id: i64, reaction_id: [32]u8) void {
    const me = activePubkey() orelse return;
    if (likeEntry(note_id)) |e| {
        e.reaction_id = reaction_id;
        return;
    }
    for (&g_my_likes) |*e| {
        if (!e.used) {
            e.* = .{ .used = true, .owner = me, .note_id = note_id, .reaction_id = reaction_id };
            return;
        }
    }
}

/// Drops the like on `note_id`, returning its reaction id (to e-tag the un-like).
fn forgetLike(note_id: i64) ?[32]u8 {
    if (likeEntry(note_id)) |e| {
        const id = e.reaction_id;
        e.* = .{};
        return id;
    }
    return null;
}

/// Clears the like table. For tests, which share the process globals.
pub fn rememberLikeForTest(note_id: i64, reaction_id: [32]u8) void {
    rememberLike(note_id, reaction_id);
}

pub fn likeReactionIdForTest(note_id: i64) ?[32]u8 {
    const e = likeEntry(note_id) orelse return null;
    return e.reaction_id;
}

pub fn resetLikesForTest() void {
    g_my_likes = [_]MyLike{.{}} ** my_likes_cap;
}

/// Whether this session has liked the note (for tests and the view).
pub fn isLikedForTest(note_id: i64) bool {
    return isLiked(note_id);
}

// ------------------------------------------------------------ engagement counts
//
// Reply / repost / like / zap tallies per feed note, aggregated client-side (no
// NIP-45 COUNT, whose relay support is spotty). Each ingest thread opens a second
// subscription, `{kinds:[1,6,7,9735], "#e":[the notes it loaded]}`, and folds the
// arriving events into this in-memory table, deduped across relays by event id.
// The view reads it at render time. Counts are per session: a relaunch refetches
// them, so nothing here is persisted.

// Above the displayed feed so the union of the relays' watched sets fits with
// room to spare; a full table then only degrades gracefully (see ensureEngagement).
const engagement_cap = 512;
const Counts = struct {
    replies: u32 = 0,
    reposts: u32 = 0,
    likes: u32 = 0,
    zap_msat: u64 = 0,
};
const Engagement = struct {
    used: bool = false,
    note_id: i64 = 0,
    counts: Counts = .{},
    /// Which relays in the pool have delivered this note, one bit each. The
    /// thread's focal line reports the count, so the claim "seen on 4 relays" is
    /// a measurement rather than a guess. A pool wider than the mask simply stops
    /// counting past bit 63, which no configuration reaches today.
    relays_seen: u64 = 0,
};
var g_engagement = [_]Engagement{.{}} ** engagement_cap;

// Cross-relay dedup: a bounded open-addressing set of event-id prefixes (the
// first 8 bytes as a u64; 0 marks an empty slot, so the ~1-in-2^64 all-zero
// prefix is simply never deduped). When it fills, new ids stop being recorded
// and a reaction seen on two relays can double-count; sized far above a starter
// pack feed's traffic so that is only a theoretical tail.
const seen_engagement_cap = 1 << 15;
var g_seen = [_]u64{0} ** seen_engagement_cap;
var g_seen_len: usize = 0;

/// Notes that this relay has now delivered. Called from each relay's ingest
/// thread as the event lands, so the count is of relays that ACTUALLY sent it.
// ------------------------------------------------------------------- the inbox
//
// What other people did that was aimed at this reader: replies, mentions, likes,
// reposts and zaps. It is the first surface in this app where a stranger can put
// something in front of the reader, so what does NOT get in matters as much as
// what does.
//
// One function decides three things at once: whether an event becomes an item,
// which verb it is, and whether it counts toward the bell. Every client that
// split those decisions ended up with a badge that disagreed with its own list.

/// The kinds a relay is asked for on the reader's behalf.
pub const inbox_kinds = [_]u16{ 1, 6, 7, 9735 };

/// How many items are kept. The KV holds one rewritten blob, so this is what
/// bounds it, and the oldest fall off the end.
pub const inbox_cap = 200;

/// How many people may be p-tagged before an event is treated as a broadcast
/// rather than a message. A note naming twenty people is a hellthread, and
/// being one of the twenty is not a notification.
const inbox_hellthread_max = 10;

/// How many items any ONE author may hold at once.
///
/// The hellthread rule refuses a single event naming a crowd. This refuses the
/// mirror image, which is cheaper to send and worse: many events each naming
/// only the reader. Signing two hundred of those costs seconds and nothing else,
/// and without a per-author bound they evict every notification the reader
/// actually wanted, permanently, because `inboxSince` then resumes past them.
pub const inbox_per_author_max = 20;

/// The most a zap may claim before the amount is treated as noise.
///
/// `bolt11` is a string the sender writes, so the number in it is a claim, not a
/// fact. Bitcoin's whole supply is 21e14 sats; anything above that is a parser
/// artefact or a lie, and either way the honest thing to draw is no amount at
/// all rather than eighteen quintillion.
const inbox_max_claimable_msat: u64 = 21_000_000 * 100_000_000 * 1000;

// `created_at` is written by whoever signed the event, so it is not a fact. One
// event dated 2100 would push the read mark past everything that will ever
// arrive and the bell would never light again. Nostur ships that bug with the
// TODO still in the file.
//
// Clamped to NOW, with no skew allowance. An allowance sounds generous and is
// not: marking read would then move the mark that far into the future, and
// everything arriving inside the window would be born already read. A genuine
// event from a slightly fast clock simply sorts as "now", which costs nothing.

pub const InboxVerb = enum { reply, mention, like, repost, zap };

pub const InboxItem = struct {
    used: bool = false,
    id: [32]u8 = [_]u8{0} ** 32,
    author: [32]u8 = [_]u8{0} ** 32,
    /// The note this is about, when it is about one. The WHOLE id, not the feed's
    /// truncated handle: the note a notification points at is usually an old one
    /// of the reader's own, which the follow-scoped feed window does not hold, so
    /// the row has to be able to ask the store for it by name.
    target_id: [32]u8 = [_]u8{0} ** 32,
    created_at: i64 = 0,
    verb: InboxVerb = .mention,
    /// Millisats, for a zap.
    msat: u64 = 0,
    /// The words this row shows, copied in when the item is admitted.
    ///
    /// Never read from the store while drawing. The feed already paid for that
    /// lesson: asking the database who you follow once per card cost 24423us to
    /// rebuild, three whole frames to draw one, and two hundred notification
    /// rows querying per frame would be the same bug wearing a different hat.
    ///
    /// WHICH note this holds depends on the verb, and that is the whole design.
    /// For a reply or a mention it is THEIR note, because the question is what
    /// did they say. For a reaction, a repost or a zap it is YOUR note, because
    /// the question is which of mine did this happen to.
    body_buf: [180]u8 = [_]u8{0} ** 180,
    body_len: u8 = 0,
    /// A reaction's own content: `+`, `-`, an emoji, or a `:shortcode:`. The
    /// gutter draws this instead of a generic heart, which is the difference
    /// between "somebody reacted" and seeing what they actually sent.
    glyph_buf: [16]u8 = [_]u8{0} ** 16,
    glyph_len: u8 = 0,

    pub fn hasTarget(self: InboxItem) bool {
        return !std.mem.allEqual(u8, &self.target_id, 0);
    }

    pub fn body(self: *const InboxItem) []const u8 {
        return self.body_buf[0..self.body_len];
    }

    pub fn reactionGlyph(self: *const InboxItem) []const u8 {
        return self.glyph_buf[0..self.glyph_len];
    }
};

/// Copies `src` into `dst`, clipped to whole codepoints, and returns the length.
fn fillClipped(dst: []u8, src: []const u8) u8 {
    // Whitespace runs collapse to one space, newlines included. A preview is one
    // block: kept as-is, a note with a blank line between paragraphs drew as two
    // separated blocks inside a row, so four notifications filled the screen and
    // the list read as a stack of documents rather than a list of events.
    var flat_buf: [512]u8 = undefined;
    var flat_len: usize = 0;
    var in_space = false;
    for (src) |c| {
        const is_space = c == ' ' or c == '\t' or c == '\r' or c == '\n';
        if (is_space) {
            in_space = true;
            continue;
        }
        if (in_space and flat_len > 0 and flat_len < flat_buf.len) {
            flat_buf[flat_len] = ' ';
            flat_len += 1;
        }
        in_space = false;
        if (flat_len == flat_buf.len) break;
        flat_buf[flat_len] = c;
        flat_len += 1;
    }
    const trimmed = flat_buf[0..flat_len];
    const ellipsis = "\u{2026}";
    // Room kept for the ellipsis before clipping, not after: appending it to a
    // full buffer would either overflow or cut a codepoint in half.
    const room = if (trimmed.len > dst.len) dst.len - ellipsis.len else dst.len;
    const take = clipToChars(trimmed, room, room);
    @memcpy(dst[0..take.len], take);
    if (take.len == trimmed.len) return @intCast(take.len);
    // Cut. Say so, or a sentence that stops mid-word reads as the whole note.
    @memcpy(dst[take.len..][0..ellipsis.len], ellipsis);
    return @intCast(take.len + ellipsis.len);
}

var g_inbox = [_]InboxItem{.{}} ** inbox_cap;
var g_inbox_len: usize = 0;
/// Whose inbox this is. One reader's notifications are never another's.
var g_inbox_owner: ?[32]u8 = null;
/// Everything at or below this stamp has been seen. A single number, because the
/// KV has no cursor and no delete, so a per-item read set could neither be
/// enumerated nor pruned.
var g_inbox_read_through: i64 = 0;
var g_inbox_lock = std.atomic.Value(bool).init(false);
var g_inbox_dirty = false;

fn lockInbox() void {
    while (g_inbox_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockInbox() void {
    g_inbox_lock.store(false, .release);
}

/// A timestamp this app is willing to act on.
fn believableStamp(created_at: i64, now_s: i64) i64 {
    return @min(created_at, now_s);
}

/// Whether `ev` is something the reader should be told about, and what it is.
///
/// The one gate. The bell, the sheet and the badge all read the result of this,
/// so they cannot drift apart.
fn inboxVerbFor(ev: nostr.event.Event, me: [32]u8) ?InboxVerb {
    // Your own actions are not news, except a zap receipt, which is authored by
    // a payment server rather than by the person who paid.
    if (ev.kind != 9735 and std.mem.eql(u8, &ev.pubkey, &me)) return null;

    // The relay is asked for events p-tagging the reader, but a relay may send
    // anything down any subscription, so the claim is checked here.
    var p_tags: usize = 0;
    var names_me = false;
    var hex: [64]u8 = undefined;
    hexLower(&hex, me);
    var last_p_is_me = false;
    for (ev.tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "p")) continue;
        p_tags += 1;
        const mine = std.ascii.eqlIgnoreCase(tag[1], &hex);
        if (mine) names_me = true;
        // Tracked separately: for a reaction or a repost the LAST p tag is the
        // one that means "this is about you".
        last_p_is_me = mine;
    }
    if (!names_me) return null;
    // A note addressed to a crowd is a broadcast. Being one of twenty names on
    // it is the most common way an inbox floods.
    if (p_tags > inbox_hellthread_max) return null;

    return switch (ev.kind) {
        1 => noteVerbFor(ev, me, last_p_is_me),
        // A repost or a reaction copies the p tags of what it is about, and
        // NIP-10 has a reply carry every p tag of its parent plus the parent's
        // author. So the reader's key propagates down every thread they ever
        // touched, and ANY-tag matching then filed somebody reacting to a
        // stranger's reply, three levels below a note of the reader's, as a
        // notification about the reader.
        //
        // NIP-25: "If a client decides to include other `p` tags, which not
        // recommended, the target event `pubkey` should be last the `p` tags."
        // So the last one is the target's author. Jumble enforces exactly this.
        // Where the reacted event is on disk, its author is checked directly,
        // which is better evidence than tag order.
        6, 16 => if (reactionTargetsMe(ev, me, last_p_is_me)) .repost else null,
        // Every reaction except the one that is not good news. The content
        // picks the GLYPH; it does not decide admission. Requiring "+" or empty
        // meant a heart, a fire or any custom shortcode produced no row, no
        // badge and no glyph, so a reader was told nobody had reacted when
        // people had, and the emoji the row is built to show could never reach
        // it. NIP-25 has exactly one negative, and a downvote is still not
        // something to celebrate in a bell.
        7 => if (!isDownvoteReaction(ev.content) and reactionTargetsMe(ev, me, last_p_is_me)) .like else null,
        9735 => .zap,
        else => null,
    };
}

/// NIP-25's one negative reaction: content of exactly "-".
///
/// Everything else, "+" and empty and every emoji and shortcode, is somebody
/// reacting well enough to be told about.
fn isDownvoteReaction(content: []const u8) bool {
    return std.mem.eql(u8, content, "-");
}

/// What a kind:1 naming the reader actually is, or null when it is not about
/// them at all.
///
/// The distinction that matters is whether the note is a REPLY. NIP-10 has a
/// reply carry every `p` tag of its parent plus the parent's author, so once
/// the reader posts a single word into a thread, their key travels down every
/// branch of it forever. Reading any `p` tag as a mention therefore filed every
/// later exchange between two other people, in any conversation the reader once
/// touched, as "X mentioned you in a note". In a busy thread that becomes the
/// commonest row in the inbox: it pushes real notifications out through the
/// item cap and inflates the unread badge on the rail.
///
/// A note that is NOT a reply inherited nothing, so a `p` tag on it is a
/// decision somebody made, and it still counts.
fn noteVerbFor(ev: nostr.event.Event, me: [32]u8, last_p_is_me: bool) ?InboxVerb {
    // Answering a note this app holds and can see is the reader's.
    if (inboxTargetsMyNote(ev, me)) return .reply;
    // Named in the text. A mention is something the writer typed, so a quote of
    // the reader's note counts here too.
    if (contentNames(ev.content, me)) return .mention;
    if (nip10Parent(ev.tags) != null) {
        // A reply whose parent this app does not hold, which is the normal case
        // for a reader who has been away. NIP-25's ordering rule is the same
        // fallback the reaction path leans on: the last `p` tag is the one the
        // event is about. It is what keeps a genuine reply from being dropped
        // along with the thread noise.
        return if (last_p_is_me) .reply else null;
    }
    return .mention;
}

/// Whether a reaction or repost is about a note of the reader's.
///
/// The store is the authority when it holds the target: an author is a fact,
/// where tag order is a convention the sender may not have followed. Falls back
/// to NIP-25's rule that the target's author is the last `p` tag.
fn reactionTargetsMe(ev: nostr.event.Event, me: [32]u8, last_p_is_me: bool) bool {
    if (engagementTarget(ev)) |t| {
        if (t.len == 64) {
            var id: [32]u8 = undefined;
            if (std.fmt.hexToBytes(&id, t)) |_| {
                if (g_store) |store| {
                    if (store.getEvent(std.heap.page_allocator, id) catch null) |found| {
                        var se = found;
                        defer se.deinit();
                        return std.mem.eql(u8, &se.event.pubkey, &me);
                    }
                }
            } else |_| {}
        }
    }
    return last_p_is_me;
}

/// Whether this note replies to something the reader wrote, as opposed to merely
/// naming them. The difference is the difference between a conversation and a
/// stranger putting a link in front of you.
fn inboxTargetsMyNote(ev: nostr.event.Event, me: [32]u8) bool {
    const parent = nip10Parent(ev.tags) orelse return false;
    const store = g_store orelse return false;
    var se = (store.getEvent(std.heap.page_allocator, parent) catch return false) orelse return false;
    defer se.deinit();
    return std.mem.eql(u8, &se.event.pubkey, &me);
}

/// Files an event, if it is one for the reader. Returns whether anything new
/// landed, so a caller can decide whether to save.
fn inboxAdd(ev: nostr.event.Event, now_s: i64) bool {
    const me = activePubkey() orelse return false;
    const verb = inboxVerbFor(ev, me) orelse return false;

    lockInbox();
    defer unlockInbox();
    if (g_inbox_owner) |owner| {
        if (!std.mem.eql(u8, &owner, &me)) resetInboxLocked(me);
    } else {
        resetInboxLocked(me);
    }

    // A zap whose payer cannot be established is not filed at all. Falling back
    // to the receipt's own author would put a payment server's key where a
    // person's name goes, and inventing "someone" for it would give a forgery a
    // row to sit in.
    //
    // A zap's IDENTITY is the request's id, not the receipt's. A receipt is a
    // wrapper anyone may write, and the request inside it is public by
    // construction, so one genuine request from somebody the reader follows is
    // all it takes to mint an unlimited number of receipts carrying it. Keying
    // on the receipt let every one of those become its own row, under that
    // person's real name, and the per-author rule then evicted their real
    // notifications to make room. Keyed on the request, a thousand replays are
    // one payment, which is what they are.
    const claim: ?ZapClaim = if (ev.kind == 9735) (zapClaim(ev, me) orelse return false) else null;
    const author = if (claim) |c| c.payer else ev.pubkey;
    const identity = if (claim) |c| c.id else ev.id;

    // Deduped on that identity, which is why this runs here rather than on the
    // way in: twenty receipts wrapping one request have twenty ids of their own,
    // and comparing those is exactly what let the replay through.
    for (g_inbox[0..g_inbox_len]) |item| {
        if (std.mem.eql(u8, &item.id, &identity)) return false;
    }

    var target: [32]u8 = [_]u8{0} ** 32;
    if (engagementTarget(ev)) |t| {
        // Into scratch, copied only on success: `hexToBytes` decodes as far as it
        // can before returning an error, so writing straight into `target` left a
        // real prefix and a zero tail on a 64-character tag that was not hex, and
        // `hasTarget` then reported that wreckage as a note to open.
        if (t.len == 64) {
            var scratch: [32]u8 = undefined;
            if (std.fmt.hexToBytes(&scratch, t)) |_| {
                target = scratch;
            } else |_| {}
        }
    }

    var item = InboxItem{
        .used = true,
        .id = identity,
        .author = author,
        .target_id = target,
        // A replay carries the original's time as well, so it cannot pose as
        // something that just happened.
        .created_at = believableStamp(if (claim) |c| c.created_at else ev.created_at, now_s),
        .verb = verb,
        .msat = if (claim) |c| c.msat else 0,
    };

    if (!inboxAdmitLocked(item)) return false;
    // And WHO it is from, for the same reason. Nothing else ever asked: the
    // profile round fetches kind:0 for the people the reader follows, the people
    // a note mentions, and the reader themself, and somebody who likes or zaps
    // you is in none of those sets. So the notifications page listed raw npubs
    // for exactly the people it is about, which is the one screen where a name
    // is the entire content of the row.
    wantProfile(author);
    bakeInboxText(&item, ev, verb, target);
    // Fetch what it is about, if this is the first we have heard of it. The row
    // is pressable, so the note behind it should be on its way before the reader
    // ever gets there.
    if (item.hasTarget() and !haveEvent(item.target_id)) wantQuote(item.target_id);
    g_inbox_dirty = true;
    return true;
}

/// Fills the row's words once, when the item is admitted.
///
/// A reply and a mention carry their own text, so those are free. A reaction, a
/// repost and a zap are about a note of the reader's own, which means one store
/// read here. Once per item, never per frame: a row that resolved itself while
/// drawing would put a database query in the scroll path of a two hundred row
/// list.
///
/// A miss is not an error. The note may not have arrived yet, `wantQuote` just
/// asked for it, and a row with a name and no body still says who did what.
fn bakeInboxText(item: *InboxItem, ev: nostr.event.Event, verb: InboxVerb, target: [32]u8) void {
    switch (verb) {
        // Their words, already in hand.
        .reply, .mention => item.body_len = fillClipped(&item.body_buf, ev.content),
        .like => {
            // The reaction as sent. NIP-25 allows `+`, `-`, an empty string and
            // a `:shortcode:`; `+` and empty both mean a like, and the row draws
            // its usual heart for those rather than printing a plus sign.
            const content = std.mem.trim(u8, ev.content, " \t\r\n");
            if (content.len > 0 and !std.mem.eql(u8, content, "+")) {
                item.glyph_len = fillClipped(&item.glyph_buf, content);
            }
            bakeTargetBody(item, target);
        },
        .repost, .zap => bakeTargetBody(item, target),
    }
}

/// The reader's own note, for the rows that are about one.
///
/// Usually a miss, and that is expected. What a notification points at is almost
/// always an older note of the reader's own, which the follow-scoped feed window
/// does not hold, so the line after this one asks the relays for it. That is why
/// the resolve below exists: baking once here and never looking again left every
/// reaction, repost and zap row with no note under it for good.
fn bakeTargetBody(item: *InboxItem, target: [32]u8) void {
    if (std.mem.allEqual(u8, &target, 0)) return;
    const store = g_store orelse return;
    var se = (store.getEvent(std.heap.page_allocator, target) catch return) orelse return;
    defer se.deinit();
    item.body_len = fillClipped(&item.body_buf, se.event.content);
}

/// The rows the notifications window last put on screen. Written by the view,
/// read by the pass that lends avatar ids on the next tick.
var g_inbox_visible: struct { first: usize = 0, last: usize = 0, len: usize = 0 } = .{};

/// The store generation the inbox last tried to fill its missing bodies at.
var g_inbox_body_stamp: usize = std.math.maxInt(usize);

/// Fills in the note behind every row that is still missing one.
///
/// Guarded on the store's event count, so this is one pass per arrival rather
/// than a query per row per frame. The feed already paid for the other version:
/// asking the database once per card cost 24423us to rebuild, three whole frames
/// to draw one.
///
/// A row whose note never arrives keeps an empty body and still says who did
/// what, which is what it did before any of this.
fn resolveInboxBodies() void {
    const store = g_store orelse return;
    const stamp = store.eventCount() catch return;
    if (stamp == g_inbox_body_stamp) return;
    g_inbox_body_stamp = stamp;
    lockInbox();
    defer unlockInbox();
    for (g_inbox[0..g_inbox_len]) |*item| {
        if (!item.used or item.body_len > 0) continue;
        // A reply or a mention IS the event, so its own id holds their words.
        // Skipping these was wrong: `inboxAdd` copies the content as the event
        // arrives, but `loadInbox` rebuilds the inbox from the store at launch
        // and never goes near that path, so every reply restored from a previous
        // session drew a name, a time, and nothing in between.
        const from: [32]u8 = if (item.verb == .reply or item.verb == .mention) item.id else item.target_id;
        bakeTargetBody(item, from);
    }
}

/// Asks for the metadata of everyone the inbox names.
///
/// `inboxAdd` already does this for an event as it arrives, and that is not
/// enough: `loadInbox` rebuilds the whole inbox from the store on launch without
/// going near that path, so every notification from a previous session had
/// nobody asking for its author's name. Those rows showed a raw npub and an
/// initial for as long as the app ran, which is exactly the screen where a name
/// IS the content.
///
/// Cheap to repeat. `wantProfile` returns immediately for anyone already named
/// and never queues a duplicate.
fn wantInboxProfiles(shown: []const InboxItem) void {
    // Only the rows on screen, and this is the third time the same rule has had
    // to be learned on this page. The wanted table holds 48 and evicts to make
    // room, so asking on behalf of 143 notifications thrashed it: the names that
    // actually arrived were whichever ones happened to survive the churn, which
    // is why opening somebody's profile and coming back was what finally loaded
    // them. Visiting the profile asked for one person instead of a hundred.
    const first = @min(g_inbox_visible.first, shown.len);
    const last = @min(g_inbox_visible.last + 1, shown.len);
    if (last <= first) return;
    for (shown[first..last]) |item| wantProfile(item.author);
}

/// Whether the store already holds this event.
fn haveEvent(id: [32]u8) bool {
    const store = g_store orelse return false;
    var se = (store.getEvent(std.heap.page_allocator, id) catch return false) orelse return false;
    se.deinit();
    return true;
}

/// Finds this item a slot, or refuses it. Returns whether it was filed.
///
/// The array is a fixed two hundred, so every arrival past that is a CHOICE about
/// what to delete, and the version this shipped with made that choice before it
/// had looked at the arrival: it shifted every slot down (dropping the oldest),
/// wrote the newcomer at the front, and only then sorted. So a backfilled item
/// from last year displaced an unread reply from this morning, and a stranger who
/// signed two hundred events deleted the reader's whole history of being spoken
/// to. Both are decided here instead, against the item actually arriving.
fn inboxAdmitLocked(item: InboxItem) bool {
    // No one author may own more than their share, however many they send.
    var by_author: usize = 0;
    var oldest_same: ?usize = null;
    for (g_inbox[0..g_inbox_len], 0..) |it, i| {
        if (!std.mem.eql(u8, &it.author, &item.author)) continue;
        by_author += 1;
        if (oldest_same == null or it.created_at < g_inbox[oldest_same.?].created_at) oldest_same = i;
    }
    if (by_author >= inbox_per_author_max) {
        const victim = oldest_same orelse return false;
        // Their own oldest, and only if this one is newer: a flood cannot walk
        // its way through the reader's history one slot at a time either.
        if (g_inbox[victim].created_at >= item.created_at) return false;
        inboxRemoveLocked(victim);
    }

    if (g_inbox_len >= g_inbox.len) {
        const victim = inboxEvictionCandidateLocked() orelse return false;
        const victim_is_stranger = !isInReadGraph(g_inbox[victim].author);
        const mine = isInReadGraph(item.author);
        // Someone the reader follows always outranks someone they do not.
        // Otherwise the newer of the two wins, so nothing already held is ever
        // traded away for something older than it.
        if (!(mine and victim_is_stranger) and g_inbox[victim].created_at >= item.created_at) return false;
        inboxRemoveLocked(victim);
    }

    g_inbox[g_inbox_len] = item;
    g_inbox_len += 1;
    // Newest first, whatever order the relays delivered in.
    sortInboxLocked();
    return true;
}

/// Who is dropped when the inbox is full: the oldest STRANGER, and only when
/// there is no stranger left, the oldest item at all.
///
/// A flood is cheap to send and always arrives from someone the reader has never
/// followed. Spending the reader's last slots on people they chose, rather than
/// on whoever signed most recently, is the difference between an inbox that
/// degrades and one that can be erased on demand.
///
/// Takes the follows lock while the inbox lock is held. That is the same order
/// `inboxItems` already uses, and nothing anywhere takes them the other way
/// round.
fn inboxEvictionCandidateLocked() ?usize {
    var oldest_stranger: ?usize = null;
    var oldest: ?usize = null;
    for (g_inbox[0..g_inbox_len], 0..) |it, i| {
        if (oldest == null or it.created_at < g_inbox[oldest.?].created_at) oldest = i;
        if (isInReadGraph(it.author)) continue;
        if (oldest_stranger == null or it.created_at < g_inbox[oldest_stranger.?].created_at) oldest_stranger = i;
    }
    return oldest_stranger orelse oldest;
}

fn inboxRemoveLocked(index: usize) void {
    if (index >= g_inbox_len) return;
    var i = index;
    while (i + 1 < g_inbox_len) : (i += 1) g_inbox[i] = g_inbox[i + 1];
    g_inbox_len -= 1;
    g_inbox[g_inbox_len] = .{};
}

fn resetInboxLocked(owner: [32]u8) void {
    g_inbox_len = 0;
    g_inbox_owner = owner;
    g_inbox_read_through = 0;
}

fn sortInboxLocked() void {
    const Cmp = struct {
        fn lt(_: void, a: InboxItem, b: InboxItem) bool {
            return a.created_at > b.created_at;
        }
    };
    std.mem.sort(InboxItem, g_inbox[0..g_inbox_len], {}, Cmp.lt);
}

/// Who actually sent a zap, established rather than taken on trust.
///
/// The RECEIPT is authored by a payment server, so its pubkey is not the person:
/// the payer is named inside the embedded zap request. That request arrives as a
/// STRING inside a stranger's tag, and parsing a string does not make its claims
/// true. Reading `pubkey` straight out of it, which is the obvious implementation
/// and the one this shipped with, lets anyone in the world publish a receipt whose
/// embedded request names someone the reader follows: the row then draws that
/// person's real cached name and avatar next to an amount the same stranger chose.
/// A trusted face saying "I sent you money" is the most valuable lie this surface
/// can carry, so it is the one that has to be paid for.
///
/// Three checks, all local and all cheap:
///   the embedded event must be a zap REQUEST (kind 9734), not any event at all,
///   its signature must verify, so the named payer really did sign it, and
///   it must name the reader, so a request signed for somebody else cannot be
///   lifted out of their receipt and replayed into this inbox.
///
/// What this still does NOT prove is that money moved: the full NIP-57 check
/// wants the receipt to come from the recipient's own LNURL server, which means
/// fetching and remembering that server's key. Until then an attacker can invent
/// a zap under THEIR OWN name and any amount they like, which is a stranger
/// talking to the reader rather than a friend impersonated, and is the same
/// weight as any other message from a stranger.
/// What a zap receipt can actually be shown to say.
///
/// Everything here comes from the SIGNED request, never from the receipt around
/// it, and that distinction is the whole of it.
const ZapClaim = struct {
    /// The request's own id. This is the item's identity, so the same payment
    /// cannot appear twice however many receipts carry it.
    id: [32]u8,
    payer: [32]u8,
    msat: u64,
    created_at: i64,
};

fn zapClaim(ev: nostr.event.Event, me: [32]u8) ?ZapClaim {
    for (ev.tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "description")) continue;
        const gpa = std.heap.page_allocator;
        var parsed = nostr.event.fromJson(gpa, tag[1]) catch return null;
        defer parsed.deinit();
        const req = parsed.value;
        if (req.kind != 9734) return null;

        var signer = nostr.keys.Signer.init();
        defer signer.deinit();
        if (!(nostr.event.verify(gpa, signer, req) catch false)) return null;

        // Signed by the payer, but for whom? A receipt is public, so a request
        // naming somebody else can be copied verbatim into a receipt aimed here.
        var hex: [64]u8 = undefined;
        hexLower(&hex, me);
        var names_me = false;
        for (req.tags) |t| {
            if (t.len < 2 or !std.mem.eql(u8, t[0], "p")) continue;
            if (std.ascii.eqlIgnoreCase(t[1], &hex)) names_me = true;
        }
        if (!names_me) return null;
        // Your own zap of your own note is not news, and the gate above cannot
        // catch it: the request names the reader because the reader is the
        // recipient.
        if (std.mem.eql(u8, &req.pubkey, &me)) return null;

        // NIP-57 puts the amount INSIDE the request, where the payer signed it.
        // The receipt's `bolt11` is written by whoever wrote the receipt, so
        // reading the number from there is how a verified name ends up beside an
        // invented figure.
        var msat: u64 = 0;
        for (req.tags) |t| {
            if (t.len < 2 or !std.mem.eql(u8, t[0], "amount")) continue;
            msat = std.fmt.parseInt(u64, t[1], 10) catch 0;
        }
        if (msat > inbox_max_claimable_msat) msat = 0;

        return .{
            .id = req.id,
            .payer = req.pubkey,
            .msat = msat,
            .created_at = req.created_at,
        };
    }
    return null;
}

/// How many items the reader has not seen.
///
/// Replies and mentions only: somebody writing TO the reader is worth a number
/// on a tile, and a like is worth reading without being summoned to. So the bell
/// deliberately counts FEWER things than the sheet lists, never more. That
/// direction matters: a badge that counts things the sheet then declines to show
/// sends the reader to an empty list and teaches them to distrust it, which is
/// exactly what the follows-only default used to do to every stranger's reply.
pub fn inboxUnread() usize {
    lockInbox();
    defer unlockInbox();
    if (!inboxIsOwnedLocked()) return 0;
    var n: usize = 0;
    for (g_inbox[0..g_inbox_len]) |item| {
        // The bell speaks for the things addressed to them personally. A like
        // is worth reading and is not worth a number on a tile.
        if (item.verb != .reply and item.verb != .mention) continue;
        if (item.created_at > g_inbox_read_through) n += 1;
    }
    return n;
}

fn inboxIsOwnedLocked() bool {
    const me = activePubkey() orelse return false;
    const owner = g_inbox_owner orelse return false;
    return std.mem.eql(u8, &owner, &me);
}

/// Marks everything currently in the inbox as seen.
///
/// The mark is the newest stamp actually HELD, never the wall clock. Marking at
/// now() means anything that arrives later carrying an older stamp, which is
/// every backfill and every slow relay, is born already read and never counted.
pub fn inboxMarkAllRead() void {
    lockInbox();
    defer unlockInbox();
    if (!inboxIsOwnedLocked()) return;
    for (g_inbox[0..g_inbox_len]) |item| {
        if (item.created_at > g_inbox_read_through) g_inbox_read_through = item.created_at;
    }
    g_inbox_dirty = true;
}

/// How many pages the sheet has for this tab. The reader's page index is kept
/// inside it, because the set underneath moves on its own: a fresh contact list
/// narrows the follows tab, and an eviction shortens both.
pub fn inboxPageCount(only_follows: bool) usize {
    var buf: [inbox_cap]InboxItem = undefined;
    const shown = inboxItems(&buf, only_follows);
    if (shown.len == 0) return 1;
    return (shown.len + inbox_page - 1) / inbox_page;
}

/// The items to draw, newest first, filtered to a tab.
pub fn inboxItems(out: []InboxItem, only_follows: bool) []const InboxItem {
    lockInbox();
    defer unlockInbox();
    if (!inboxIsOwnedLocked()) return out[0..0];
    var n: usize = 0;
    for (g_inbox[0..g_inbox_len]) |item| {
        if (n >= out.len) break;
        if (only_follows and !isInReadGraph(item.author)) continue;
        out[n] = item;
        n += 1;
    }
    return out[0..n];
}

pub fn inboxReadThrough() i64 {
    lockInbox();
    defer unlockInbox();
    return g_inbox_read_through;
}

/// The newest stamp held, which is where a backfill resumes from.
pub fn inboxNewest() i64 {
    lockInbox();
    defer unlockInbox();
    if (!inboxIsOwnedLocked() or g_inbox_len == 0) return 0;
    return g_inbox[0].created_at;
}

/// Asks this relay for what other people aimed at the reader, or stops asking.
///
/// Called at dial AND whenever the identity changes, because a connection lives
/// as long as the relay keeps it alive: on a healthy socket there is no reconnect
/// to heal a subscription that was never opened.
pub fn subscribeInbox(relay: anytype) void {
    const me = activePubkey() orelse {
        // Signed out. The filter names a person who is no longer here, so it is
        // withdrawn rather than left running: a relay should stop being told
        // which pubkey this connection cares about the moment it stops being
        // true.
        relay.unsubscribe("plaza-inbox") catch {};
        return;
    };
    const hex = inboxMeHex(me);
    const inbox_tags = [_]nostr.filter.TagFilter{.{ .letter = 'p', .values = &.{&hex} }};
    const since = inboxSince();
    const inbox_filters = [_]nostr.filter.Filter{.{
        .kinds = &inbox_kinds,
        .tags = &inbox_tags,
        .limit = inbox_backfill_cap,
        .since = if (since > 0) since else null,
    }};
    relay.subscribe("plaza-inbox", &inbox_filters) catch {};
}

/// The reader's own pubkey as hex, for a filter that names them.
fn inboxMeHex(me: [32]u8) [64]u8 {
    var hex: [64]u8 = undefined;
    hexLower(&hex, me);
    return hex;
}

/// How far back a fresh subscription asks.
///
/// The newest item held, minus an overlap: asking for exactly the newest stamp
/// re-fetches that one event and, worse, a relay whose clock differs by a second
/// silently drops everything in the gap. With nothing held, no `since` at all
/// and the limit does the bounding, which is what relays are good at.
const inbox_backfill_cap: u32 = 200;
const inbox_since_overlap_s: i64 = 60 * 60;

/// The newest kind:1 this app holds, for the feed's `since`.
///
/// Updated by the ingest threads, seeded once from the store at startup so a
/// relaunch does not re-download everything it already has.
var g_feed_newest = std.atomic.Value(i64).init(0);

/// How far back of the newest held note the feed re-asks from.
///
/// The same one hour `inboxSince` uses, and for the same reason: relays differ
/// on whether `since` is inclusive, clocks differ, and an event can be stored
/// with a `created_at` behind the one that arrived before it. An hour of
/// overlap costs a few duplicate events, which the store rejects, and buys not
/// silently missing the notes either side of a reconnect.
const feed_since_overlap_s: i64 = 3600;

fn noteFeedNewest(created_at: i64) void {
    var seen = g_feed_newest.load(.monotonic);
    while (created_at > seen) {
        seen = g_feed_newest.cmpxchgWeak(seen, created_at, .monotonic, .monotonic) orelse break;
    }
}

/// Reads the newest stored kind:1 once, so the first subscription after a
/// launch is bounded too. One cursor on the kind index, not a merge.
fn seedFeedNewest(store: *nostr.store.Store) void {
    if (g_feed_newest.load(.monotonic) != 0) return;
    const kinds = [_]u16{1};
    var result = store.query(std.heap.page_allocator, .{ .kinds = &kinds, .limit = 1 }) catch return;
    defer result.deinit();
    if (result.events.len > 0) noteFeedNewest(result.events[0].created_at);
}

/// What the feed asks relays to start from, or null on a cold store.
///
/// Every reconnect re-asked for the full three hundred per chunk, from every
/// relay, because no feed filter ever carried a `since`. A flapping relay was
/// therefore handed a fifteen-hundred-event question every few seconds, and
/// every one of those events cost a Schnorr verify before the store recognised
/// it as a duplicate. The app already knew the shape: `subscribeInbox` has done
/// exactly this since it was written.
///
/// Null when nothing is held, which is Notedeck's rule: a cold store needs the
/// whole backfill, and bounding it would leave a new install with an empty feed.
fn feedSince() ?i64 {
    const newest = g_feed_newest.load(.monotonic);
    if (newest == 0) return null;
    return @max(0, newest - feed_since_overlap_s);
}

fn inboxSince() i64 {
    const newest = inboxNewest();
    if (newest == 0) return 0;
    return @max(0, newest - inbox_since_overlap_s);
}

/// Marks the index changed, so the tick writes it once rather than every relay
/// writing it on every event.
fn markInboxDirty() void {
    lockInbox();
    defer unlockInbox();
    g_inbox_dirty = true;
}

fn inboxNeedsSave() bool {
    lockInbox();
    defer unlockInbox();
    return g_inbox_dirty;
}

/// Where the inbox index and the read mark live. Per account, because one
/// reader's notifications are not another's and a shared key is how account
/// switching corrupts unread state. One rewritten key, because the KV has no
/// cursor, no prefix scan and no delete.
fn inboxKey(buf: *[96]u8, pubkey: [32]u8) []const u8 {
    var hex: [64]u8 = undefined;
    hexLower(&hex, pubkey);
    return std.fmt.bufPrint(buf, "inbox/{s}", .{hex[0..]}) catch buf[0..0];
}

/// Writes the index. The events themselves are already in the store's event
/// tables, so this holds only what cannot be recomputed: which ids matter, what
/// each one was, and how far the reader has read.
fn saveInbox() void {
    const store = g_store orelse return;
    const me = activePubkey() orelse return;
    var key_buf: [96]u8 = undefined;
    const key = inboxKey(&key_buf, me);
    if (key.len == 0) return;

    const gpa = std.heap.page_allocator;
    var out = std.ArrayList(u8).empty;
    defer out.deinit(gpa);

    lockInbox();
    if (!inboxIsOwnedLocked()) {
        unlockInbox();
        return;
    }
    out.print(gpa, "read {d}\n", .{g_inbox_read_through}) catch {
        unlockInbox();
        return;
    };
    // Only the read marker. The items themselves are NOT serialised here any
    // more: the events are already in the store, indexed by their `p` tag, and
    // writing a second parallel copy of them was both duplication and a bug.
    // The blob carried the id, author, stamp, target, verb and msat, and nothing
    // else, so a restored row had no words and no reaction glyph, which is
    // exactly the "some rows have no content" report. Rebuilding from the store
    // replays the real events through the real gate and cannot drift from it.
    g_inbox_dirty = false;
    unlockInbox();
    // Outside the lock: an LMDB write must never be held under a spinlock that
    // ingest threads are waiting on.
    store.put(key, out.items) catch {};
}

/// Reads the index back at sign-in.
fn loadInbox() void {
    const store = g_store orelse return;
    const me = activePubkey() orelse return;
    const gpa = std.heap.page_allocator;

    lockInbox();
    resetInboxLocked(me);
    unlockInbox();

    // AFTER the reset, which clears it. Reading the marker first and resetting
    // second put the whole inbox back at unread on every launch.
    var key_buf: [96]u8 = undefined;
    const key = inboxKey(&key_buf, me);
    if (key.len > 0) {
        if (store.get(gpa, key) catch null) |raw| {
            defer gpa.free(raw);
            var lines = std.mem.tokenizeScalar(u8, raw, '\n');
            while (lines.next()) |line| {
                var parts = std.mem.tokenizeScalar(u8, line, ' ');
                const first = parts.next() orelse continue;
                if (!std.mem.eql(u8, first, "read")) continue;
                const v = parts.next() orelse continue;
                g_inbox_read_through = std.fmt.parseInt(i64, v, 10) catch 0;
            }
        }
    }

    // The same filter the relay is asked, answered from disk. Jumble does
    // exactly this: it paints the notification list from IndexedDB using the
    // identical filter it is about to send, before opening a socket.
    //
    // Replayed through `inboxAdd`, so restored rows pass the same gate, the same
    // dedup and the same text baking as live ones. The hand-rolled blob this
    // replaces could not: it held six scalar fields and no content, so every row
    // restored from a previous session came back with a name, a time, and
    // nothing in between.
    const hex = inboxMeHex(me);
    const tags = [_]nostr.filter.TagFilter{.{ .letter = 'p', .values = &.{&hex} }};
    var result = store.query(gpa, .{
        .kinds = &inbox_kinds,
        .tags = &tags,
        .limit = inbox_backfill_cap,
    }) catch return;
    defer result.deinit();
    const now = nowSeconds();
    for (result.events) |ev| _ = inboxAdd(ev, now);
}

pub fn saveInboxForTest() void {
    saveInbox();
}

pub fn loadInboxForTest() void {
    loadInbox();
}

pub fn inboxAddForTest(ev: nostr.event.Event, now_s: i64) bool {
    return inboxAdd(ev, now_s);
}

pub fn inboxVerbForTest(ev: nostr.event.Event, me: [32]u8) ?InboxVerb {
    return inboxVerbFor(ev, me);
}

/// Drops the leaving account's notifications. Another reader must never open
/// this app and find somebody else's mail.
fn resetInbox() void {
    lockInbox();
    defer unlockInbox();
    g_inbox_len = 0;
    g_inbox_owner = null;
    g_inbox_read_through = 0;
    g_inbox_dirty = false;
}

/// Files `count` unread notifications, so a view test can ask what the rail's
/// badge does with a number without standing up relays.
pub fn seedInboxUnreadForTest(count: usize) void {
    const me = activePubkey() orelse return;
    lockInbox();
    defer unlockInbox();
    resetInboxLocked(me);
    var i: usize = 0;
    while (i < count and g_inbox_len < g_inbox.len) : (i += 1) {
        var id: [32]u8 = [_]u8{0} ** 32;
        id[0] = @intCast(i % 251 + 1);
        g_inbox[g_inbox_len] = .{
            .used = true,
            .id = id,
            .author = id,
            .target_id = [_]u8{0} ** 32,
            .created_at = 1_800_000_000,
            .verb = .reply,
            .msat = 0,
        };
        g_inbox_len += 1;
    }
}

/// Whether a kind:0 has been asked for on this pubkey's behalf.
pub fn profileWantedForTest(pubkey: [32]u8) bool {
    for (&g_wanted) |*w| {
        if (w.used and std.mem.eql(u8, &w.pubkey, &pubkey)) return true;
    }
    return false;
}

pub fn forgetWantedProfilesForTest() void {
    for (&g_wanted) |*w| w.* = .{};
}

pub fn resetInboxForTest() void {
    lockInbox();
    defer unlockInbox();
    g_inbox_len = 0;
    g_inbox_owner = null;
    g_inbox_read_through = 0;
}

pub fn inboxLenForTest() usize {
    lockInbox();
    defer unlockInbox();
    return g_inbox_len;
}

/// Forgets that a slot ever carried anything. Called when the slot changes
/// hands: "held by 3 relays" must not count a relay that is no longer there.
fn forgetRelaySeen(relay_index: usize) void {
    if (relay_index >= 64) return;
    const bit = @as(u64, 1) << @intCast(relay_index);
    engagementLock();
    defer engagementUnlock();
    for (&g_engagement) |*e| e.relays_seen &= ~bit;
}

fn markRelaySeen(note_id: i64, relay_index: usize) void {
    if (relay_index >= 64) return;
    const bit = @as(u64, 1) << @intCast(relay_index);
    engagementLock();
    defer engagementUnlock();
    // Only a note the table ALREADY tracks. Creating a row here would spend the
    // 512-row budget on every note the pool delivers, crowding out the counts the
    // rows exist for; the engagement subscription creates the rows for the notes
    // on screen, which are the only ones whose spread can be read.
    for (&g_engagement) |*e| {
        if (e.used and e.note_id == note_id) {
            e.relays_seen |= bit;
            return;
        }
    }
}

/// How many relays have delivered `note_id`, or 0 when it has not been tracked
/// (a note read straight from the store on a cold start was delivered by nobody
/// this session, and the focal line says nothing rather than "seen on 0 relays").
pub fn relaysSeenFor(note_id: i64) usize {
    engagementLock();
    defer engagementUnlock();
    for (&g_engagement) |*e| {
        if (e.used and e.note_id == note_id) return @popCount(e.relays_seen);
    }
    return 0;
}

var g_engagement_lock = std.atomic.Value(bool).init(false);
fn engagementLock() void {
    while (g_engagement_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
}
fn engagementUnlock() void {
    g_engagement_lock.store(false, .release);
}

/// The u64 dedup key for an event id (its first 8 bytes, big-endian).
fn idPrefix(id: [32]u8) u64 {
    return std.mem.readInt(u64, id[0..8], .big);
}

/// Whether `prefix` is already in the seen set. Caller holds the lock. The probe
/// count is bounded by the table size so a full table cannot spin.
fn seenContains(prefix: u64) bool {
    if (prefix == 0) return false;
    var i = prefix % seen_engagement_cap;
    var probes: usize = 0;
    while (g_seen[i] != 0 and probes < seen_engagement_cap) : ({
        i = (i + 1) % seen_engagement_cap;
        probes += 1;
    }) {
        if (g_seen[i] == prefix) return true;
    }
    return false;
}

/// Records `prefix` as seen and returns true if it was new (not a cross-relay
/// duplicate). Caller holds the lock. A full set (or the ~1-in-2^64 zero prefix)
/// reports NOT-new, so counting stops rather than double-counting: reporting new
/// there would fold an event into the crowd total that `seenContains` can never
/// confirm, breaking the own-like reconciliation. Sized far above a feed's
/// traffic so this "stop counting" tail is only theoretical.
fn markSeen(prefix: u64) bool {
    if (prefix == 0 or g_seen_len >= seen_engagement_cap) return false;
    var i = prefix % seen_engagement_cap;
    while (g_seen[i] != 0) : (i = (i + 1) % seen_engagement_cap) {
        if (g_seen[i] == prefix) return false;
    }
    g_seen[i] = prefix;
    g_seen_len += 1;
    return true;
}

/// The counts row for `note_id`, creating it if there is room. Caller holds the
/// lock. Null only when the table is full of other notes.
fn ensureEngagement(note_id: i64) ?*Engagement {
    for (&g_engagement) |*e| {
        if (e.used and e.note_id == note_id) return e;
    }
    for (&g_engagement) |*e| {
        if (!e.used) {
            e.* = .{ .used = true, .note_id = note_id };
            return e;
        }
    }
    return null;
}

/// The crowd counts for `note_id` (zeroes if none). Read at render time.
pub fn engagementFor(note_id: i64) Counts {
    engagementLock();
    defer engagementUnlock();
    for (&g_engagement) |*e| {
        if (e.used and e.note_id == note_id) return e.counts;
    }
    return .{};
}

/// The like count to display for a note: the crowd's likes plus this session's
/// own optimistic +1, dropped once our reaction (`my_reaction`) has come back
/// through the subscription and is folded into the crowd total. Both reads
/// happen under one lock hold, so the two never disagree across a concurrent
/// count (which would flicker the number for a frame).
pub fn likeCountFor(note_id: i64, my_reaction: ?[32]u8) u64 {
    engagementLock();
    defer engagementUnlock();
    var crowd: u32 = 0;
    for (&g_engagement) |*e| {
        if (e.used and e.note_id == note_id) {
            crowd = e.counts.likes;
            break;
        }
    }
    const mine: u64 = if (my_reaction) |rid| (if (seenContains(idPrefix(rid))) 0 else 1) else 0;
    return @as(u64, crowd) + mine;
}

/// Whether a kind:7 reaction's content counts as a like: NIP-25 treats "+" and
/// empty as a like, and "-" (a downvote) and emoji/shortcode as something else.
fn isLikeReaction(content: []const u8) bool {
    return content.len == 0 or std.mem.eql(u8, content, "+");
}

/// The millisats a bolt11 invoice encodes, or 0 when it carries no amount. The
/// human-readable part is everything before the bech32 separator (the only '1',
/// since the data charset excludes it); the amount is its digits times the
/// optional multiplier, scaled to msat (1 BTC = 1e11 msat).
pub fn bolt11Msat(invoice: []const u8) u64 {
    if (!std.mem.startsWith(u8, invoice, "ln")) return 0;
    const sep = std.mem.lastIndexOfScalar(u8, invoice, '1') orelse return 0;
    const hrp = invoice[0..sep];
    var i: usize = 2; // past "ln"
    while (i < hrp.len and !std.ascii.isDigit(hrp[i])) i += 1; // past the currency
    const start = i;
    while (i < hrp.len and std.ascii.isDigit(hrp[i])) i += 1;
    if (i == start) return 0; // an amountless "any amount" invoice
    const num = std.fmt.parseInt(u64, hrp[start..i], 10) catch return 0;
    const mult: u8 = if (i < hrp.len) hrp[i] else 0;
    return switch (mult) {
        'm' => num *| 100_000_000,
        'u' => num *| 100_000,
        'n' => num *| 100,
        'p' => num / 10,
        0 => num *| 100_000_000_000,
        else => 0,
    };
}

/// The sats a kind:9735 zap receipt is worth, from its bolt11 tag.
/// The most a single receipt may add to a note's total.
///
/// Not a judgement about generosity: it is a bound on how wrong one forged
/// receipt can make the number. A hundred thousand sats is already an unusual
/// zap, and a card claiming millions is the whole payoff for forging one.
const zap_msat_ceiling: u64 = 100_000_000; // 100k sats
pub const zap_msat_ceiling_for_test = zap_msat_ceiling;

/// What a zap receipt is worth to a note's total, after checking it is real.
///
/// The counting path used to read the receipt's own `bolt11` tag and add it,
/// with nothing checked. A kind:9735 is an ordinary public event that anybody
/// can publish, so a note could be given any total at all by writing a receipt
/// with a large invoice string in it and no payment behind it. `zapClaim`
/// already did this properly for the inbox and this path never called it.
///
/// What is checked here, without a network round trip:
///
///   - the `description` holds a real kind:9734 zap request whose signature
///     verifies, so the receipt carries something the payer actually signed;
///   - that request asks about THIS event, so a genuine receipt for a different
///     note cannot be replayed onto this one;
///   - the amount is the smaller of what the request asked for and what the
///     invoice says, so neither number alone can inflate the total;
///   - the result is clamped.
///
/// Not checked: that the receipt is signed by the recipient's LNURL server
/// (`nostrPubkey`), which the reference clients do verify. That needs the
/// recipient's LNURL, which is a fetch this path cannot make. Its absence means
/// a receipt can still be minted by someone willing to sign a zap request for
/// the reader's note, which is a far higher bar than editing a string.
fn zapMsat(ev: nostr.event.Event) u64 {
    const target = engagementTarget(ev) orelse return 0;

    var invoice_msat: u64 = 0;
    var description: ?[]const u8 = null;
    for (ev.tags) |tag| {
        if (tag.len < 2) continue;
        if (std.mem.eql(u8, tag[0], "bolt11")) invoice_msat = bolt11Msat(tag[1]);
        if (std.mem.eql(u8, tag[0], "description")) description = tag[1];
    }
    const desc = description orelse return 0;

    const gpa = std.heap.page_allocator;
    var parsed = nostr.event.fromJson(gpa, desc) catch return 0;
    defer parsed.deinit();
    const req = parsed.value;
    if (req.kind != 9734) return 0;

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    if (!(nostr.event.verify(gpa, signer, req) catch false)) return 0;

    // The request has to be about the note being credited. Without this a real
    // receipt for a popular note could be re-published against any other note.
    var about_this_note = false;
    var requested_msat: u64 = 0;
    for (req.tags) |t| {
        if (t.len < 2) continue;
        if (t[0].len == 1 and t[0][0] == 'e' and std.ascii.eqlIgnoreCase(t[1], target))
            about_this_note = true;
        if (std.mem.eql(u8, t[0], "amount"))
            requested_msat = std.fmt.parseInt(u64, t[1], 10) catch 0;
    }
    if (!about_this_note) return 0;

    // Both numbers, when both are present: the smaller one. An invoice for a
    // fortune attached to a request for a sat is not worth a fortune, and the
    // reverse is equally untrue.
    const msat = if (requested_msat > 0 and invoice_msat > 0)
        @min(requested_msat, invoice_msat)
    else if (invoice_msat > 0) invoice_msat else requested_msat;

    return @min(msat, zap_msat_ceiling);
}

/// The single note an engagement event is about: its `reply`-marked e tag if it
/// has one (NIP-10), else its last e tag (NIP-25 says a reaction's target is the
/// last e tag; the same positional convention names a reply's direct parent).
/// Counting only this one, rather than every e tag, keeps a threaded reply from
/// crediting the whole ancestor chain and dedupes an id repeated across tags.
fn engagementTarget(ev: nostr.event.Event) ?[]const u8 {
    var last_e: ?[]const u8 = null;
    var reply_e: ?[]const u8 = null;
    for (ev.tags) |tag| {
        if (tag.len < 2 or tag[0].len != 1 or tag[0][0] != 'e') continue;
        last_e = tag[1];
        if (tag.len >= 4 and std.mem.eql(u8, tag[3], "reply")) reply_e = tag[1];
    }
    return reply_e orelse last_e;
}

/// Folds one engagement event into the count of the single note it targets, when
/// that note is in this relay thread's loaded set. The cross-relay dedup
/// (`markSeen`) happens only AFTER the target is confirmed present here and a row
/// is in hand, so an event a thread cannot place does not consume the dedup slot
/// (which would let its true owner drop it) and a full table cannot mark an event
/// seen-but-uncounted (which would break the own-like reconciliation).
fn countEngagement(ev: nostr.event.Event, feed_ids: []const i64) void {
    // A reaction that is not a like ("+") adds nothing.
    if (ev.kind == 7 and !isLikeReaction(ev.content)) return;
    const target_hex = engagementTarget(ev) orelse return;
    const target = noteIdFromHex(target_hex) orelse return;

    engagementLock();
    defer engagementUnlock();
    var in_feed = false;
    for (feed_ids) |fid| {
        if (fid == target) {
            in_feed = true;
            break;
        }
    }
    if (!in_feed) return;
    const row = ensureEngagement(target) orelse return;
    if (!markSeen(idPrefix(ev.id))) return;
    switch (ev.kind) {
        1 => row.counts.replies += 1,
        6, 16 => row.counts.reposts += 1,
        7 => row.counts.likes += 1,
        9735 => row.counts.zap_msat +|= zapMsat(ev),
        else => {},
    }
}

/// Parses a 64-char hex event id's first 8 bytes into the same non-negative i64
/// key `noteIdOf` derives, so an `e` tag maps onto a loaded note. Null when the
/// value is not at least 16 hex digits.
fn noteIdFromHex(hex: []const u8) ?i64 {
    if (hex.len < 16) return null;
    var bytes: [8]u8 = undefined;
    _ = std.fmt.hexToBytes(&bytes, hex[0..16]) catch return null;
    return @intCast(std.mem.readInt(u64, &bytes, .big) & std.math.maxInt(i64));
}

/// Clears the engagement table and dedup set. For tests.
/// Sets a note's zap total directly, for tests about what the RENDER does with
/// a large number. Ingestion cannot produce one in a single step any more, and
/// the two properties are worth testing apart: what is admitted, and what is
/// survivable once admitted.
pub fn setZapMsatForTest(id: i64, msat: u64) void {
    engagementLock();
    defer engagementUnlock();
    if (ensureEngagement(id)) |row| row.counts.zap_msat = msat;
}

pub fn resetEngagementForTest() void {
    g_engagement = [_]Engagement{.{}} ** engagement_cap;
    g_seen = [_]u64{0} ** seen_engagement_cap;
    g_seen_len = 0;
}

/// Folds an event into the counts, for tests (the ingest path without threads).
pub fn countEngagementForTest(ev: nostr.event.Event, feed_ids: []const i64) void {
    countEngagement(ev, feed_ids);
}

/// Finds the cached profile for `pubkey`, or null.
/// An open-addressed index over `g_profiles`, so a lookup is a probe rather
/// than a walk.
///
/// The cache was 160 slots and a linear scan was fine. Sizing it to the real
/// author set (200 notifications plus up to 2048 follows) made that scan 12x
/// longer, and it runs per note per feed rebuild: the 2048-follow rebuild went
/// from inside the frame budget to 17155us against 16000us, a visible stutter
/// every second. The cap and this index are one change, not two.
///
/// Slot values are index+1 so that zero means empty. Rebuilt wholesale on
/// eviction, which is rare and bounded.
const profile_index_slots = 8192;
var g_profile_index = [_]u16{0} ** profile_index_slots;
var g_profile_index_stale: usize = 0;

fn profileSlotFor(pubkey: [32]u8) usize {
    // The pubkey is already a hash, so its low bits are as good as any.
    const h = std.mem.readInt(u64, pubkey[0..8], .little);
    return @intCast(h % profile_index_slots);
}

fn profileIndexInsert(idx: usize) void {
    var slot = profileSlotFor(g_profiles[idx].pubkey);
    var probes: usize = 0;
    while (probes < profile_index_slots) : (probes += 1) {
        if (g_profile_index[slot] == 0) {
            g_profile_index[slot] = @intCast(idx + 1);
            return;
        }
        slot = (slot + 1) % profile_index_slots;
    }
}

fn profileIndexRebuild() void {
    @memset(&g_profile_index, 0);
    g_profile_index_stale = 0;
    for (&g_profiles, 0..) |*p, i| {
        if (p.used) profileIndexInsert(i);
    }
}

fn lookupProfile(pubkey: [32]u8) ?*Profile {
    var slot = profileSlotFor(pubkey);
    var probes: usize = 0;
    while (probes < profile_index_slots) : (probes += 1) {
        const entry = g_profile_index[slot];
        // An empty slot ends the probe: nothing past it can belong to this key.
        if (entry == 0) return null;
        const p = &g_profiles[entry - 1];
        if (p.used and std.mem.eql(u8, &p.pubkey, &pubkey)) return p;
        slot = (slot + 1) % profile_index_slots;
    }
    return null;
}

/// The cache slot for `pubkey`, allocating a free one on first sight, else
/// reusing the least-recently-seen slot. Avatar image ids are NOT tied to the
/// slot here (see `assignAvatarSlots`); a new slot starts with none and earns
/// one only while on screen.
pub fn upsertProfile(pubkey: [32]u8) ?*Profile {
    if (lookupProfile(pubkey)) |p| return p;
    for (&g_profiles, 0..) |*p, i| {
        if (!p.used) {
            p.* = .{ .used = true, .pubkey = pubkey };
            profileIndexInsert(i);
            return p;
        }
    }
    // Cache full: evict the author least-recently on screen. Never evict one
    // marked on screen THIS pass (an over-full pass would otherwise wipe an
    // author it just marked and thrash every tick), nor one with an index-keyed
    // fetch in flight (avatar OR NIP-05): those responses re-derive the profile
    // from its slot, so reusing it would apply a result to the wrong pubkey. An
    // over-full pass simply leaves the newcomer slotless (npub + initials) until
    // a slot frees, rather than churning. A reused id is freed for the newcomer.
    var victim: ?*Profile = null;
    for (&g_profiles) |*p| {
        if (p.avatar_state == .fetching or p.nip05_state == .fetching) continue;
        if (p.avatar_clock == g_avatar_clock) continue;
        if (victim == null or p.avatar_clock < victim.?.avatar_clock) victim = p;
    }
    const v = victim orelse return null;
    v.* = .{ .used = true, .pubkey = pubkey };
    // The evicted key's entry is left pointing at a slot that no longer holds
    // it. That is SAFE, because a lookup compares the pubkey and keeps probing
    // on a mismatch, and it is what keeps eviction O(1). Rebuilding the whole
    // table here instead cost 10ms per feed rebuild at 2048 follows, where the
    // cache is permanently full and every new author evicts.
    profileIndexInsert(idxOf(v));
    g_profile_index_stale += 1;
    // Stale entries lengthen probe chains, so the table is rebuilt occasionally
    // rather than never. Amortised to nothing across 512 evictions.
    if (g_profile_index_stale >= 512) profileIndexRebuild();
    return v;
}

/// The slot number of a profile pointer, for the index.
fn idxOf(p: *const Profile) usize {
    return (@intFromPtr(p) - @intFromPtr(&g_profiles[0])) / @sizeOf(Profile);
}

/// Parses a kind:0 metadata JSON content into `profile`'s name and picture.
/// Tolerant: unknown fields are ignored and a malformed blob leaves the profile
/// unchanged (it just keeps rendering from its npub). Prefers `display_name`
/// (or the legacy `displayName`) over `name`.
pub fn parseMetadataInto(profile: *Profile, content: []const u8) void {
    const Metadata = struct {
        name: ?[]const u8 = null,
        display_name: ?[]const u8 = null,
        displayName: ?[]const u8 = null,
        picture: ?[]const u8 = null,
        nip05: ?[]const u8 = null,
        website: ?[]const u8 = null,
    };
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const md = std.json.parseFromSliceLeaky(Metadata, arena_state.allocator(), content, .{ .ignore_unknown_fields = true }) catch return;

    // The first name that is actually SET wins. Checking presence alone is not
    // enough: plenty of real profiles carry `"display_name": ""` alongside a
    // real `name` (jb55's does), and an empty winner drops the author back to a
    // bare npub.
    for ([_]?[]const u8{ md.displayName, md.display_name, md.name }) |candidate| {
        const raw = candidate orelse continue;
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        if (trimmed.len == 0) continue;
        const n = utf8SafeLen(trimmed, profile.name_buf.len);
        @memcpy(profile.name_buf[0..n], trimmed[0..n]);
        profile.name_len = @intCast(n);
        break;
    }
    // The username is kept separately: it is the handle line under a display
    // name, and collapsing the two fields into one left that line empty for every
    // author without a NIP-05.
    if (md.name) |raw| {
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        if (trimmed.len > 0) {
            const n = utf8SafeLen(trimmed, profile.username_buf.len);
            @memcpy(profile.username_buf[0..n], trimmed[0..n]);
            profile.username_len = @intCast(n);
        }
    }
    if (md.picture) |pic| {
        const trimmed = std.mem.trim(u8, pic, " \t\r\n");
        if (trimmed.len <= profile.picture_buf.len and (std.mem.startsWith(u8, trimmed, "https://") or std.mem.startsWith(u8, trimmed, "http://"))) {
            // A changed picture URL means the old avatar is stale: refetch it
            // into the same image slot.
            if (!std.mem.eql(u8, trimmed, profile.picture())) {
                @memcpy(profile.picture_buf[0..trimmed.len], trimmed);
                profile.picture_len = @intCast(trimmed.len);
                if (profile.avatar_state != .fetching) profile.avatar_state = .idle;
                // A different picture is a different resource, so whatever the
                // last one failed at says nothing about this one.
                profile.avatar_attempts = 0;
            }
        }
    }

    // The website, for the handle line's last fallback before an npub. Stored
    // whole and trimmed to its host at render time, so a profile that changes
    // its path does not have to be re-parsed.
    profile.website_len = 0;
    if (md.website) |raw| {
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        // Gated on the scheme, exactly as `picture` is twelve lines above. This
        // string is a stranger's, it goes on the identity line under their name,
        // and `websiteHost` trims a scheme it recognises: without the gate a
        // `javascript:` or `data:` value would be stored and then rendered whole,
        // because the trimmer would find no `//` to cut at.
        const web = std.mem.startsWith(u8, trimmed, "https://") or std.mem.startsWith(u8, trimmed, "http://");
        if (web and trimmed.len <= profile.website_buf.len) {
            @memcpy(profile.website_buf[0..trimmed.len], trimmed);
            profile.website_len = @intCast(trimmed.len);
        }
    }

    // NIP-05: keep the identifier and (re)arm verification when it is present
    // and changed. Absent or oversized means there is nothing to verify, so no
    // check ever draws.
    if (md.nip05) |raw| {
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        if (trimmed.len > 0 and trimmed.len <= profile.nip05_buf.len and std.mem.indexOfScalar(u8, trimmed, '@') != null) {
            if (!std.mem.eql(u8, trimmed, profile.nip05())) {
                @memcpy(profile.nip05_buf[0..trimmed.len], trimmed);
                profile.nip05_len = @intCast(trimmed.len);
                if (profile.nip05_state != .fetching) profile.nip05_state = .idle;
            }
        } else {
            profile.nip05_len = 0;
            profile.nip05_state = .failed;
        }
    } else {
        profile.nip05_len = 0;
        profile.nip05_state = .failed;
    }
}

/// Wall-clock seconds on the UI thread, or 0 before `main` wires the clock.
fn nowSeconds() i64 {
    const io = g_io orelse return 0;
    return std.Io.Timestamp.now(io, .real).toSeconds();
}

/// The pubkey Plaza posts as: the local key, or the remote signer's, or null
/// before an identity is established. The feed includes it so your own notes
/// show alongside the follows you read.
fn activePubkey() ?[32]u8 {
    return switch (g_signer_kind) {
        .local => if (g_identity_kp) |kp| kp.public_key else null,
        .remote => g_remote_pubkey,
        .helper => if (g_helper_has_identity) g_helper_identity_pk else null,
    };
}

// ------------------------------------------------------------------ model

/// A `nostr:nevent`/`note` quote a note carries: the decoded event id (the
/// fetch, open, and cache key) and the byte span of its raw token within the
/// note's `content_buf`, so the body can be split around it at render time
/// without ever mutating the stored text.
const QuoteRef = struct {
    kind: enum(u8) { none, event } = .none,
    id: [32]u8 = [_]u8{0} ** 32,
    off: u16 = 0,
    len: u16 = 0,
};

/// The verb a guest reached for, held until they have a key.
pub const Intent = union(enum) {
    none,
    post,
    like: i64,
    reply: i64,
    follow: [32]u8,

    pub fn waiting(self: Intent) bool {
        return self != .none;
    }
};

/// One note as the feed renders it: a two-letter avatar, the author's
/// abbreviated npub, a relative timestamp, and the (truncated) content. Strings
/// are copied into fixed buffers so a card never aliases the query arena it was
/// built from.
pub const Note = struct {
    // Non-negative i64: the markup engine holds a `for each` integer key as i64
    // then casts it to u64, so a raw u64 (or negative i64) from the id's high
    // bytes would overflow and panic. Mask off the sign bit.
    id: i64 = 0,
    // The full 32-byte event id, for the reaction's `e` tag and the engagement
    // subscription's `#e` filter. The i64 above is only a render/dedup key.
    event_id: [32]u8 = [_]u8{0} ** 32,
    created_at: i64 = 0,
    // The author's full pubkey, so the view can resolve a display name and an
    // avatar from the profile cache at render time (picking up a name or a
    // just-loaded avatar without rebuilding the note).
    pubkey: [32]u8 = [_]u8{0} ** 32,
    initials_buf: [2]u8 = [_]u8{0} ** 2,
    author_buf: [24]u8 = [_]u8{0} ** 24,
    author_len: u8 = 0,
    time_buf: [12]u8 = [_]u8{0} ** 12,
    time_len: u8 = 0,
    content_buf: [note_content_cap]u8 = [_]u8{0} ** note_content_cap,
    content_len: u16 = 0,
    // The first image URL in the note, lifted out of the text and rendered as a
    // picture instead (see `renderContent`'s `omit`).
    image_url_buf: [300]u8 = [_]u8{0} ** 300,
    image_url_len: u16 = 0,
    // Height divided by width, taken from the note's own NIP-92 `imeta dim`
    // when it carries one. Knowing the shape BEFORE the picture downloads is
    // what lets the card reserve exactly the right space, so nothing shifts
    // when the image arrives (or is evicted and comes back).
    image_aspect: f32 = 0,
    /// What the picture's own chrome says: its pixel dimensions, from the same
    /// `imeta` tag the aspect comes from, and its alt text. Both are the note
    /// author's claim about the file, which is the only thing available before
    /// the bytes are, and the chips read at rest rather than on hover (the
    /// design's hover-expand is not expressible).
    image_w: u16 = 0,
    image_h: u16 = 0,
    image_bytes: u32 = 0,
    /// The picture's blurhash, when the note carries one: its colour before its
    /// bytes. Fixed buffer, because the tag's memory is the event's.
    image_blur_buf: [40]u8 = [_]u8{0} ** 40,
    image_blur_len: u8 = 0,
    /// The first plain link in the note, previewed as a card under the body. One
    /// per note, which is what 11o draws; the URL stays in the text as well.
    link_url_buf: [300]u8 = [_]u8{0} ** 300,
    link_url_len: u16 = 0,
    /// Whether the note described its picture. The chip is the marker the shot
    /// draws, one word: the description itself would need a hover expand, which
    /// is not expressible.
    image_has_alt: bool = false,
    // The first `nostr:nevent`/`note` reference in the content, decoded once at
    // parse time: the quoted event id, and the byte span of its raw token in
    // `content_buf` so the body can split around it and render an embedded quote
    // card. `.none` when the note quotes nothing.
    quote: QuoteRef = .{},
    // The NIP-10 parent this note answers (the `e` tag marked `reply`, or the
    // thread root for a direct reply), extracted once at parse time so a thread
    // can seat each reply under the note it answers. Zero when it answers
    // nothing; the flag disambiguates a genuine all-zero id.
    reply_parent: [32]u8 = [_]u8{0} ** 32,
    has_reply_parent: bool = false,
    /// This note names a parent that is not in the fetched set. It sits at the
    /// top level for want of anywhere better, and says so rather than passing
    /// itself off as an answer to the thread's opening note.
    parent_missing: bool = false,
    /// What the note says it was written with, from NIP-89's `client` tag.
    /// Copied in rather than read at render time because it is foreign text on a
    /// borrowed event: the buffer is the sanitiser's output, bounded here so a
    /// name can never be longer than the row that draws it.
    client_buf: [client_name_bytes]u8 = [_]u8{0} ** client_name_bytes,
    client_len: u8 = 0,
    // Thread placement, stamped by `arrangeThread`: how deep this reply sits
    // under the root (1 = a direct reply). Meaningless outside an arranged
    // thread.
    depth: u8 = 0,
    // Which build of the open thread this reply first appeared in, so a late
    // arrival sorts after what is already on screen instead of jumping into the
    // middle of it. Only meaningful for a thread's replies.
    arrival: u32 = 0,

    pub fn initials(self: *const Note) []const u8 {
        return &self.initials_buf;
    }
    /// The picture's blurhash, empty when the note carries none.
    pub fn imageBlurhash(self: *const Note) []const u8 {
        return self.image_blur_buf[0..self.image_blur_len];
    }
    /// The link this note previews, empty when it has none.
    pub fn linkUrl(self: *const Note) []const u8 {
        return self.link_url_buf[0..self.link_url_len];
    }
    pub fn hasLink(self: *const Note) bool {
        return self.link_url_len > 0;
    }
    /// Whether this note carries an image to render.
    pub fn hasImage(self: *const Note) bool {
        return self.image_url_len > 0;
    }
    /// What the picture's chip says: its dimensions and its weight, as the note
    /// claims them, in the shot's own form (`1600x900 · 240 KB`). Either half may
    /// be missing, and the chip is empty when both are. Never taken from the
    /// decoded bytes, which are the proxy's 480px box and would be a lie about
    /// the file, and never from the response, which carries no headers.
    pub fn imageChipLabel(self: *const Note, arena: std.mem.Allocator) []const u8 {
        const has_dims = self.image_w > 0 and self.image_h > 0;
        if (has_dims and self.image_bytes > 0) {
            return std.fmt.allocPrint(arena, "{d}\u{00d7}{d} · {s}", .{ self.image_w, self.image_h, byteSize(arena, self.image_bytes) }) catch "";
        }
        if (has_dims) return std.fmt.allocPrint(arena, "{d}\u{00d7}{d}", .{ self.image_w, self.image_h }) catch "";
        if (self.image_bytes > 0) return byteSize(arena, self.image_bytes);
        return "";
    }
    /// The note's image URL (empty when it has none).
    pub fn imageUrl(self: *const Note) []const u8 {
        return self.image_url_buf[0..self.image_url_len];
    }
    /// The registered image id for this note's picture, or 0 while it is
    /// loading, unavailable, or absent.
    pub fn media_id(self: *const Note) u64 {
        if (mediaSlotFor(self.id)) |m| {
            if (m.state == .loaded) return m.image_id;
        }
        return 0;
    }
    /// The author's display name from their kind:0 profile, or the abbreviated
    /// npub until (or unless) a profile is known.
    pub fn author(self: *const Note) []const u8 {
        if (lookupProfile(self.pubkey)) |p| {
            if (p.name_len > 0) return p.name();
        }
        return self.author_buf[0..self.author_len];
    }
    /// The registered avatar image id for this author, or 0 to draw initials.
    pub fn avatar_id(self: *const Note) u64 {
        return avatarImageId(self.pubkey);
    }
    /// The @handle for the identity line: the author's NIP-05, shown as `@name`
    /// (or `@domain` for the root `_@domain` form). Empty when they have no
    /// NIP-05 (a bare npub is not a handle, so nothing is shown rather than
    /// `@npub…`. Allocated in the caller's arena for the frame.
    /// Who this is, under their name, and whether it is a NIP-05 identity. There is ALWAYS something here once the
    /// profile has arrived, which is the point of the whole ladder below: the
    /// identity block is pinned to the avatar's height, so an empty second line
    /// is not restraint, it is a hole in the row that reads as a rendering bug.
    /// It stayed empty for anyone with no NIP-05 and no username distinct from
    /// their display name, which is a great many people.
    ///
    /// In order:
    ///
    ///  1. the NIP-05, WHOLE (`dergigi@primal.net`), and just the domain for the
    ///     root `_@domain` form. The domain is the half that says who vouched for
    ///     this name, so dropping it threw away the part worth showing. Reads in
    ///     the identity violet.
    ///  2. the kind:0 username, `@user`, muted. Skipped when it would only echo
    ///     the name line above it, because the same string twice reads as a
    ///     rendering bug rather than as a handle.
    ///  3. the website, as its host. Not attested by anybody, so muted too, but
    ///     it is something the person chose to say about themselves.
    ///  4. a short npub. Last, and skipped when the name line is ALREADY the
    ///     npub, which is what it falls back to for a profile nobody has.
    ///
    /// Only the first is violet. Violet has to keep meaning "attested somewhere"
    /// or it means nothing.
    pub fn handleLabel(self: *const Note, arena: std.mem.Allocator) struct { text: []const u8, nip05: bool } {
        if (lookupProfile(self.pubkey)) |p| {
            const shown = nip05Display(p.nip05());
            if (shown.len > 0) return .{ .text = shown, .nip05 = true };
            const user = p.username();
            if (user.len > 0 and !std.mem.eql(u8, user, p.name())) {
                return .{ .text = std.fmt.allocPrint(arena, "@{s}", .{user}) catch "", .nip05 = false };
            }
            const host = p.websiteHost();
            if (host.len > 0 and !std.mem.eql(u8, host, p.name())) {
                return .{ .text = host, .nip05 = false };
            }
        }
        // The npub the note already carries, not a fresh bech32 encode. This is
        // built once per note in `setAuthor`, and this line runs per row per
        // frame for everyone the ladder falls through to, so encoding here would
        // be a bech32 conversion and an allocation on the feed's hot path for a
        // string sitting in the struct.
        //
        // Using the SAME bytes also makes the check below exact by construction:
        // `author()` returns this buffer when there is no kind:0 name, so a
        // stranger's row cannot end up saying one shortening of their key on the
        // name line and another underneath it.
        const short = self.author_buf[0..self.author_len];
        if (short.len > 0 and !std.mem.eql(u8, short, self.author())) {
            return .{ .text = short, .nip05 = false };
        }
        return .{ .text = "", .nip05 = false };
    }

    /// The compact `@local` form, for naming somebody INLINE in a sentence
    /// ("Replying to @dergigi"). Deliberately not `handleLabel`: that is the
    /// identity line under a name, where the domain is the half worth showing,
    /// and a whole `dergigi@primal.net` mid-sentence reads as an email address.
    /// The one caller that put this on an identity LINE now uses the ladder.
    pub fn handle(self: *const Note, arena: std.mem.Allocator) []const u8 {
        const p = lookupProfile(self.pubkey) orelse return "";
        if (p.nip05_len == 0) return "";
        const id = p.nip05();
        const at = std.mem.indexOfScalar(u8, id, '@') orelse return "";
        const local = id[0..at];
        const domain = id[at + 1 ..];
        const shown = if (std.mem.eql(u8, local, "_")) domain else local;
        if (shown.len == 0) return "";
        return std.fmt.allocPrint(arena, "@{s}", .{shown}) catch "";
    }
    /// Whether this author's NIP-05 has been verified (well-known JSON maps the
    /// name back to their pubkey). Only then does the identity line show a check.
    pub fn verified(self: *const Note) bool {
        if (lookupProfile(self.pubkey)) |p| return p.nip05_state == .verified;
        return false;
    }
    pub fn time(self: *const Note) []const u8 {
        return self.time_buf[0..self.time_len];
    }

    /// What this note says it was written with, empty when it says nothing.
    pub fn client(self: *const Note) []const u8 {
        return self.client_buf[0..self.client_len];
    }
    pub fn content(self: *const Note) []const u8 {
        return self.content_buf[0..self.content_len];
    }

    /// (Re)computes the relative timestamp against `now_s`. Cheap and
    /// allocation-free, so the UI can freshen every tick without a re-query.
    fn setTime(self: *Note, now_s: i64) void {
        const written = ageInto(&self.time_buf, self.created_at, now_s) catch return;
        self.time_len = @intCast(written.len);
    }

    /// How long ago, in the app's one spelling of it.
    pub fn ageInto(buf: []u8, created_at: i64, now_s: i64) ![]const u8 {
        const dt = now_s - created_at;
        if (dt < 60) return std.fmt.bufPrint(buf, "now", .{});
        if (dt < 3600) return std.fmt.bufPrint(buf, "{d}m", .{@divTrunc(dt, 60)});
        if (dt < 86_400) return std.fmt.bufPrint(buf, "{d}h", .{@divTrunc(dt, 3600)});
        if (dt < 604_800) return std.fmt.bufPrint(buf, "{d}d", .{@divTrunc(dt, 86_400)});
        return std.fmt.bufPrint(buf, "{d}w", .{@divTrunc(dt, 604_800)});
    }
};

/// Which top-level screen the app shows.
pub const Stage = enum { onboarding, ready, settings };

pub const Model = struct {
    /// The loaded feed. A SLICE into `g_feed_notes`, which grows as the reader
    /// pages down and is never handed back. It was a fixed array of three
    /// hundred, and that array was the only reason the feed had a bottom.
    ///
    /// Re-pointed by `rebuildNotes` after a growth, so nothing holds this across
    /// one.
    notes: []Note = &.{},
    notes_len: usize = 0,
    live_relays: usize = 0,
    /// How many relays the reader has, sampled on the tick beside the live
    /// count: a frame that mixed a fresh numerator with a stale denominator
    /// would read "4/3 relays".
    relay_count: usize = 0,
    /// Which chrome menu is open, if any. One at a time: opening one closes the
    /// rest, and Escape or a press outside closes whatever is open.
    menu: ChromeMenu = .none,
    /// Notes still owed to the relays, sampled on the tick: the queue itself is
    /// written by the publisher's thread, so the view reads this snapshot rather
    /// than the queue, and one frame never disagrees with itself.
    outbox_pending: usize = 0,
    outbox_stuck: usize = 0,
    /// A note the queue had no room for. It was written to this machine and
    /// offered to nobody, which is the one outcome the queue exists to make
    /// impossible, so it is said out loud instead of left to the flag nobody
    /// reads.
    outbox_overflowed: bool = false,
    /// Whether a level is showing its replies from outside the follow graph, and
    /// how many pages of replies it has revealed. PER LEVEL, indexed like the
    /// back-stack: a level stays mounted while the reader walks into a reply and
    /// back, and it has to come back the size it was. One shared pair of flags
    /// collapsed a parent's revealed pages on the way back, under a scroll offset
    /// restored for the taller list.
    thread_outside_open: [thread_depth_max + 1]bool = [_]bool{false} ** (thread_depth_max + 1),
    thread_page: [thread_depth_max + 1]usize = [_]usize{1} ** (thread_depth_max + 1),
    /// Whether the reader has paused the pool. Reading keeps working: the store
    /// is the app, so a pause stops the sockets, not the feed.
    relays_paused: bool = false,
    offline_relays: usize = 0,
    // The composer's edit state (text + caret + selection). The view binds the
    // text through `draft()`, never the buffer itself, and every edit event is
    // mirrored here in `update`.
    draft_buffer: canvas.TextBuffer(compose_capacity) = .{},
    // Which screen shows. A returning user (session on disk) starts at `.ready`;
    // a newcomer starts at `.onboarding` and moves to `.ready` when they sign in.
    // `.settings` is reached from the feed and returns to it.
    stage: Stage = .onboarding,
    // The onboarding sign-in field: an existing `nsec` to import a key, or a
    // `bunker://` URL to pair with an external NIP-46 signer (Notary).
    login_buffer: canvas.TextBuffer(220) = .{},
    // Settings: whether the "log out" confirmation is showing, and whether the
    // local secret key is revealed for backup.
    logout_pending: bool = false,
    reveal_nsec: bool = false,
    // The media-proxy field in Settings (see `g_media_proxy_buf`).
    proxy_buffer: canvas.TextBuffer(200) = .{},
    proxy_saved: bool = false,
    // The Edit profile sheet: whether it is open, what is in its fields, and
    // whether the app has the reader's current profile to merge into.
    editing_profile: bool = false,
    profile_stage: ProfileStage = .fetching,
    // When the sheet started waiting, so a relay that never answers becomes a
    // stated fact rather than a spinner nobody can leave.
    profile_asked_at: i64 = 0,
    // Which key the name was read from, so the edit rewrites THAT key.
    profile_name_key: ProfileNameKey = .display_name,
    // Whether the sheet has been seeded from the reader's own profile, so the
    // background fetch landing later never overwrites what they have typed.
    profile_seeded: bool = false,
    // A field whose real value did not fit. Left empty and left alone.
    profile_name_long: bool = false,
    profile_about_long: bool = false,
    profile_picture_long: bool = false,
    profile_name_buffer: canvas.TextBuffer(64) = .{},
    profile_about_buffer: canvas.TextBuffer(280) = .{},
    profile_picture_buffer: canvas.TextBuffer(200) = .{},
    // The add-a-relay field, and why the last press did nothing.
    relay_buffer: canvas.TextBuffer(96) = .{},
    relay_error: bool = false,
    relay_full: bool = false,
    // Which note's picture is expanded to fill the window, if any.
    expanded_note: ?i64 = null,
    /// Whether the mention picker has been dismissed for the query now in the
    /// draft. It has no open flag of its own: it shows whenever the draft ends
    /// in a `@word`, so Escape and a press outside had nothing to clear and it
    /// came back on the next rebuild. Cleared by the next edit, because a new
    /// query is a new question.
    mention_dismissed: bool = false,
    /// WHICH note has its menu open, by id, or 0 for none. A bool was enough
    /// while the only menu in the app hung off the thread's focal note; every
    /// post carries one now, and a shared flag would open all of them at once.
    note_menu: i64 = 0,
    // Whether the notifications sheet is up, and which tab it shows.
    notifications_open: bool = false,
    /// Which notifications the sheet shows. EVERYONE by default, because that is
    /// what the bell counts.
    ///
    /// Defaulting to the follows-only view meant a stranger's reply lit the badge
    /// and then opened onto "Nothing from the people you follow yet", and opening
    /// marked it read on the way past, so the reader was told about something,
    /// shown nothing, and never told again. Someone the reader has never followed
    /// replying to them is not an edge case: for an inbox it is the ordinary
    /// case, and it is most of the reason to have one. Narrowing to follows is
    /// still one press away, as a filter the reader chooses rather than one
    /// applied silently underneath a number.
    notifications_everyone: bool = true,
    // How many pages of the inbox are shown. A page replaces rather than
    // appends, the same way a thread's does, because a sheet is a plain column
    // and an unbounded one would refuse the whole view.
    /// Which page of the sheet is showing, counted from zero. Pages REPLACE each
    /// other rather than accumulating, so this is an index, not a depth.
    // Whether the compose sheet is open. Compose is on demand from the "New
    // note" button in the titlebar, not a permanent bar, so the feed fills the
    // window.
    composing: bool = false,
    // Whether the guest dismissed the join strip this session. Dismissal only
    // hides the strip; the join surface stays reachable through every gated
    // verb and the status bar's Guest chip.
    guest_strip_dismissed: bool = false,
    // Whether the first-intent join sheet is up (the ladder: create, bring a
    // key, use a signer). Rises when a guest presses a gated verb, or from the
    // strip and the Guest chip.
    joining: bool = false,
    /// What the reader reached for before they had a key.
    ///
    /// One field, because there is one answer to "what happens after you sign
    /// in". The app used to carry two ad-hoc ones, a bool for the composer and an
    /// id for a like, and every verb added after them either grew a third or
    /// quietly remembered nothing: pressing Follow as a guest opened the sheet,
    /// signed you in, and dropped the follow on the floor, because there was
    /// nowhere to put it. A union makes forgetting a compile error rather than an
    /// omission.
    pending: Intent = .none,
    // The remembered intent: the guest reached for the composer, so composing
    // opens by itself the moment an identity exists. The sheet says so.

    // The other remembered intent: the guest reached for a like. The note id is
    // held here (0 = none) so the like completes the moment an identity exists.

    // Whether the join sheet is on its focused bunker-input step (chose "Use
    // your own signer") rather than the ladder.
    bunker_mode: bool = false,
    // The open thread: the focused note's id (0 = the feed, not a thread). When
    // set, the thread is layered OVER the feed (which stays mounted, so its
    // scroll offset survives) with the note and its replies.
    viewing_thread: i64 = 0,
    // The open thread's root, snapshotted so it survives a store rebuild and a
    // reply can be opened as its own thread. Valid while viewing_thread != 0.
    thread_root: Note = .{},
    // The open thread's replies, cached from the store so they are pressable
    // (open as a sub-thread), get their pictures fetched, and hold across
    // rebuilds. Rebuilt each tick, oldest first.
    thread_notes: [thread_reply_cap]Note = [_]Note{.{}} ** thread_reply_cap,
    thread_notes_len: usize = 0,
    // The back-stack of thread roots: opening a reply as a sub-thread pushes the
    // current root, so Back returns to it, and only the last Back returns to the
    // feed.
    thread_stack: [thread_depth_max]Screen = [_]Screen{.{}} ** thread_depth_max,
    thread_stack_len: usize = 0,
    /// Whose profile the CURRENT level shows, when it shows one. A thread and a
    /// profile are the same kind of thing to the back stack, so Back walks out
    /// of either without knowing which it is leaving.
    viewing_profile: ?[32]u8 = null,
    /// Which of the profile's tabs is showing.
    profile_tab: ProfileTab = .notes,
    // Whether the first reply fetch is still out with nothing in hand, so the
    // thread shows skeleton rows rather than looking empty under the root.
    thread_loading: bool = false,
    // The open thread's fetch generation and when it opened, so the loading
    // skeletons retire the moment THIS thread's fetch reports back (or a grace
    // period elapses), never on a stale earlier thread's completion.
    thread_seq: u64 = 0,
    thread_open_at: i64 = 0,
    // The reply composer's edit state, bound through `reply_draft`.
    reply_buffer: canvas.TextBuffer(compose_capacity) = .{},
    // People the reader has switched off for the draft they are writing. An
    // exclusion set rather than an inclusion one, so it cannot go stale: if the
    // mention is deleted the pubkey stops being derived and the entry is simply
    // never consulted again.
    mentions_off: [max_mention_tags][32]u8 = [_][32]u8{[_]u8{0} ** 32} ** max_mention_tags,
    mentions_off_len: usize = 0,
    /// Whether the level on screen was opened FROM notifications, so closing it
    /// goes back there rather than to the feed. Pressing a row used to drop the
    /// page entirely, and Back then landed on a feed the reader had not been
    /// looking at, with their place in the notifications list gone.
    notifications_return: bool = false,
    // The name beat: after creating an identity, one optional, skippable ask
    // so the account is not blank. Never for imported keys or signers.
    naming: bool = false,
    name_buffer: canvas.TextBuffer(64) = .{},
    // A small confirming toast ("Posted", "Name set"), cleared by the tick.
    toast_buf: [48]u8 = undefined,
    toast_len: usize = 0,
    toast_until: i64 = 0,
    // The backup nudge after the first local-key post this session: calm,
    // dismissible, stakes stated plainly.
    backup_nudge: bool = false,
    backup_nudge_dismissed: bool = false,
    // Where the feed is scrolled, so images load around the viewport instead of
    // only at the top. The windowed list replaces this estimate with the
    // runtime's exact visible range in the next milestone.
    feed_scroll: canvas.ScrollState = .{},
    // How many notes the feed currently asks the store for; grows a page at a
    // time as the reader reaches the end.
    feed_limit: usize = feed_page,

    // These fields reach the view only through methods, `notes`/`notes_len`
    // through `note_list`/`has_notes`/`footer`, the relay counts through the
    // status line, the draft through `draft`/`draft_empty`, the stage through
    // `show_onboarding`/`show_feed`/`show_settings`, the login field through
    // `login_draft`, so the raw fields are never bound by name.
    // Everything the FEED reads is listed here too: that screen is a Zig view
    // now, so markup never binds its state (the welcome and Settings fragments
    // still bind theirs, and are still checked).
    pub const view_unbound = .{
        "notes",                 "notes_len",        "live_relays",            "offline_relays",   "draft_buffer",
        "stage",                 "login_buffer",     "logout_pending",         "reveal_nsec",      "proxy_buffer",
        "proxy_saved",           "feed_scroll",      "feed_limit",             "draft",            "draft_empty",
        "identity",              "has_notes",        "empty",                  "status",           "empty_text",
        "footer",                "note_list",        "expanded_note",          "composing",        "caught_up",
        "relay_health",          "relays_online",    "scope_voices",           "is_guest",         "show_guest_strip",
        "guest_strip_dismissed", "joining",          "pending",                "naming",           "name_buffer",
        "name_draft",            "name_empty",       "toast_buf",              "toast_len",        "toast_until",
        "toast_text",            "backup_nudge",     "backup_nudge_dismissed", "bunker_mode",      "pending_text",
        "viewing_thread",        "reply_buffer",     "reply_draft",            "reply_empty",      "thread_root",
        "thread_notes",          "thread_notes_len", "thread_stack",           "thread_stack_len", "thread_loading",
        "thread_seq",            "thread_open_at",
    };

    /// Why the join sheet is up, in the reader's own terms. Empty when they
    /// opened it themselves rather than being sent there by a verb.
    pub fn pending_text(self: *const Model, ui: *AppUi) []const u8 {
        return pendingText(ui, self);
    }

    /// The name beat's current text.
    pub fn name_draft(self: *const Model) []const u8 {
        return self.name_buffer.text();
    }
    /// Whether the name field is blank, which disables Save.
    pub fn name_empty(self: *const Model) bool {
        return std.mem.trim(u8, self.name_buffer.text(), " \t\r\n").len == 0;
    }
    /// The live toast text, empty when none is showing.
    pub fn toast_text(self: *const Model) []const u8 {
        if (self.toast_until == 0) return "";
        return self.toast_buf[0..self.toast_len];
    }

    /// The composer's current text (what `text="{draft}"` binds).
    pub fn draft(self: *const Model) []const u8 {
        return self.draft_buffer.text();
    }
    /// Whether the draft is blank (only whitespace), which disables Post.
    pub fn draft_empty(self: *const Model) bool {
        return std.mem.trim(u8, self.draft_buffer.text(), " \t\r\n").len == 0;
    }
    /// The reply composer's current text.
    pub fn reply_draft(self: *const Model) []const u8 {
        return self.reply_buffer.text();
    }
    /// Whether the reply is blank, which disables Reply.
    pub fn reply_empty(self: *const Model) bool {
        return std.mem.trim(u8, self.reply_buffer.text(), " \t\r\n").len == 0;
    }
    /// The composer's "posting as" line: the identity's abbreviated npub, marked
    /// when signing is routed through an external signer, or a setup note while
    /// the key is still being prepared.
    pub fn identity(self: *const Model, arena: std.mem.Allocator) []const u8 {
        _ = self;
        // A remote sign that never came back: the draft has been restored to the
        // composer, so say why rather than let it silently reappear.
        if (g_signer_kind == .remote and g_remote_sign_notice.load(.acquire))
            return "Your signer didn't respond. Draft restored, try again.";
        // The built-in signer, which is a separate process on loopback and can
        // refuse, be busy, or not be running at all.
        if (g_signer_kind == .helper and g_helper_sign_notice.load(.acquire))
            return "Notary could not sign that. Draft restored, try again.";
        if (g_identity_npub_len == 0) return "Preparing your key…";
        // Show the user's own display name once their kind:0 is known, else npub.
        var who: []const u8 = g_identity_npub_buf[0..g_identity_npub_len];
        if (activePubkey()) |pk| {
            if (lookupProfile(pk)) |p| {
                if (p.name_len > 0) who = p.name();
            }
        }
        if (g_signer_kind == .remote) {
            // The connection's honest state, not just its happy path: reaching,
            // signing as (which key), or unreachable.
            return switch (g_remote_status.load(.acquire)) {
                1 => std.fmt.allocPrint(arena, "Reaching your signer · {s}", .{who}) catch who,
                2 => std.fmt.allocPrint(arena, "Signing via your signer · {s}", .{who}) catch who,
                3 => "Your signer is unreachable. Posts will not sign.",
                else => std.fmt.allocPrint(arena, "Your signer · {s}", .{who}) catch who,
            };
        }
        return std.fmt.allocPrint(arena, "Posting as {s}", .{who}) catch who;
    }

    /// The onboarding sign-in field text (what `text="{login_draft}"` binds).
    pub fn login_draft(self: *const Model) []const u8 {
        return self.login_buffer.text();
    }
    /// Whether this install can make a key at all, which disables the welcome
    /// screen's create button. The join ladder swaps its whole card out; this
    /// screen is compiled markup with fixed text, so it binds the two things
    /// that can change: whether the button works, and the line under it.
    pub fn no_keyholder(self: *const Model) bool {
        _ = self;
        return keyholderMissing();
    }
    /// The line under the welcome screen's create button.
    pub fn create_hint(self: *const Model) []const u8 {
        _ = self;
        if (keyholderMissing()) return "Notary, the part of Plaza that holds your key, is missing from this install, so Plaza cannot make one. Reinstalling Plaza fixes it, or bring a key you already have.";
        return "A second to set up. No email, no signup.";
    }
    /// The welcome screen's opening line, which normally sells making a key.
    /// With no keyholder it cannot be made, and an invitation printed directly
    /// over a greyed-out button is the screen arguing with itself.
    pub fn welcome_lead(self: *const Model) []const u8 {
        _ = self;
        if (keyholderMissing()) return "Sign in with a key you already have and Plaza sets you up with a starter feed of great accounts. Your notes stay on your device and publish straight to the network.";
        return "Create an identity and Plaza sets you up with a starter feed of great accounts. Your notes stay on your device and publish straight to the network.";
    }
    /// Whether the sign-in field is blank, which disables Continue.
    pub fn login_empty(self: *const Model) bool {
        return std.mem.trim(u8, self.login_buffer.text(), " \t\r\n").len == 0;
    }
    /// The status line under the sign-in field: a synchronous parse error, or
    /// the async bunker-connect state.
    pub fn login_status(self: *const Model) []const u8 {
        _ = self;
        switch (@as(LoginError, @enumFromInt(g_login_error.load(.acquire)))) {
            .format => return "Paste an nsec or a bunker link.",
            .bad_key => return "That doesn't look like a valid key.",
            .none => {},
        }
        return switch (g_remote_status.load(.acquire)) {
            1 => "Connecting to your signer…",
            3 => "Couldn't read that bunker link.",
            else => "",
        };
    }

    // -- Settings ------------------------------------------------------------

    /// The abbreviated npub of the signed-in identity (empty before sign-in).
    pub fn active_npub(self: *const Model) []const u8 {
        _ = self;
        return g_identity_npub_buf[0..g_identity_npub_len];
    }
    /// How the identity signs: a local key on this device, or a remote signer.
    pub fn identity_kind_label(self: *const Model) []const u8 {
        _ = self;
        return switch (g_signer_kind) {
            .local => "Local key",
            .remote => "Remote signer",
            .helper => "Notary",
        };
    }
    /// Whether the identity is a local key (so its secret can be backed up here).
    pub fn is_local_key(self: *const Model) bool {
        _ = self;
        return g_signer_kind == .local;
    }
    /// Whether the local secret key is hidden (the reveal toggle's off state).
    pub fn nsec_hidden(self: *const Model) bool {
        return !self.reveal_nsec;
    }
    /// Whether the secret key is currently revealed.
    pub fn nsec_shown(self: *const Model) bool {
        return self.reveal_nsec;
    }
    /// The revealed nsec (bech32 secret key), or empty when hidden or not local.
    pub fn revealed_nsec(self: *const Model, arena: std.mem.Allocator) []const u8 {
        if (!self.reveal_nsec or g_signer_kind != .local) return "";
        const kp = g_identity_kp orelse return "";
        return nostr.nip19.encodeNsec(arena, kp.secret_key) catch "";
    }
    /// Whether the logout confirmation is not yet showing.
    pub fn logout_idle(self: *const Model) bool {
        return !self.logout_pending;
    }
    /// Whether the logout confirmation is showing.
    pub fn logout_confirming(self: *const Model) bool {
        return self.logout_pending;
    }
    /// The logout confirmation warning, sharper for a local key (it is deleted).
    pub fn logout_warning(self: *const Model) []const u8 {
        _ = self;
        // A note handed to a signer that has not answered exists in exactly one
        // place: the slot the sign-out is about to free. It cannot be parked in
        // the outbox the way a queued note is, because it has no signature and
        // therefore no id, and it cannot be left in the composer, because that
        // is the previous reader's writing sitting in front of the next account.
        // So the reader is told, and the press is theirs to make.
        if (signInFlight()) {
            return "A note you just posted has not been signed yet. Signing out now will lose it.";
        }
        return switch (g_signer_kind) {
            // Followable: the reveal-and-copy card in Settings is right there,
            // and it is gated on exactly this kind.
            .local => "Your secret key will be removed from this device. Copy it first if you want to keep this identity.",
            .remote => "You'll be signed out and returned to the welcome screen. Your signer keeps your key.",
            // Notary held it, and Notary is asked to forget it. The two cases
            // are not the same thing and used to share one sentence that was
            // false for both.
            //
            // The old text said "Back it up first if you want to keep this
            // identity", pointing at a control that does not exist: the reveal
            // card is local-key only, the daemon's route table has no export and
            // its own module doc says no endpoint returns the secret, and the
            // ceremony window tells the reader there is nothing to write down.
            // A key minted here therefore ends here, and since `createLocalIdentity`
            // has no callers, minted here is what every new identity is. Saying
            // so is the least this can do until there is a real way to save one.
            .helper => if (g_identity_minted_here)
                "Notary made this key and it exists nowhere else. Signing out deletes it for good: your notes stay on relays, but nothing will ever be able to post, reply or edit your profile as this account again."
            else
                "Your key will be removed from Notary on this device. You can sign in again with the same key.",
        };
    }
    /// The media-proxy field's text (what `text="{proxy_draft}"` binds).
    pub fn proxy_draft(self: *const Model) []const u8 {
        return self.proxy_buffer.text();
    }
    /// Confirmation under the media-proxy field.
    pub fn proxy_status(self: *const Model) []const u8 {
        if (!self.proxy_saved) return "";
        return if (g_media_proxy_len == 0) "Saved. Loading originals directly." else "Saved.";
    }
    /// What signs for this account, as a sentence rather than a badge.
    pub fn signer_line(self: *const Model) []const u8 {
        _ = self;
        return switch (g_signer_kind) {
            .local => "Signing with a local key",
            .remote => "Signing via a remote signer",
            .helper => "Signing via Notary",
        };
    }
    /// Whether Notary is what holds this account's key, and whether there is a
    /// window to show it in. Both halves matter: a remote signer is somebody
    /// else's process on somebody else's machine and Notary has nothing to say
    /// about it, and an install that arrived without the window would offer a
    /// press that opens nothing.
    pub fn can_open_notary(self: *const Model) bool {
        _ = self;
        return openNotaryAvailable();
    }
    /// Where the key actually is, which is the part worth knowing.
    pub fn signer_sub(self: *const Model) []const u8 {
        _ = self;
        return switch (g_signer_kind) {
            .local => "The key is on this Mac, in this app.",
            .remote => "The key never leaves your signer. Plaza asks it to sign.",
            .helper => "The key is held by Notary on this Mac, not by Plaza.",
        };
    }
    /// Whether the app is allowed to fetch what a note names.
    pub fn previews_on(self: *const Model) bool {
        _ = self;
        return g_media_previews;
    }
    pub fn profile_name(self: *const Model) []const u8 {
        return self.profile_name_buffer.text();
    }
    pub fn profile_about(self: *const Model) []const u8 {
        return self.profile_about_buffer.text();
    }
    pub fn profile_picture(self: *const Model) []const u8 {
        return self.profile_picture_buffer.text();
    }
    /// What the sheet is able to do right now, said in the sheet.
    pub fn profile_status(self: *const Model) []const u8 {
        return switch (self.profile_stage) {
            .fetching => "Reading your current profile from your relays…",
            // Two different states wearing one name. For a key minted here,
            // absent is a fact and the first save is a first profile. For an
            // imported key it is only what the relays this app happens to dial
            // have said, and publishing over it would delete a profile living
            // somewhere they have not been asked.
            .absent => if (g_identity_minted_here)
                "You have no profile yet. Saving publishes your first one."
            else
                "Plaza has not found your profile on the relays it can reach. It will not publish over one it has not read.",
            // Deliberately NOT "you have no profile". Not hearing back is not
            // the same as being told there is nothing, and only one of those is
            // safe to publish over.
            .unread => "Could not read your current profile. Nothing will be published over it until it loads.",
            .have => "",
            .saving => "Signing…",
            .sent => "Saved here and sent to your relays. Other clients will show it as they pass it on.",
            .failed => "Could not sign this. Nothing was published, and your profile is unchanged.",
        };
    }
    pub fn client_tag_on(_: *const Model) bool {
        return clientTag();
    }
    /// Says what turning it on actually publishes, in the terms the reader cares
    /// about: not "adds a tag" but "every note says where it came from, forever".
    pub fn client_tag_explainer(_: *const Model) []const u8 {
        return if (clientTag())
            "On. Every note you post says it was written in Plaza. Anyone reading it in any client can see that."
        else
            "Off. Your notes say nothing about what you wrote them with.";
    }
    /// Whether all three fields are still empty, which is the only state where a
    /// late-arriving profile may fill them in.
    pub fn profile_untouched(self: *const Model) bool {
        return self.profile_name_buffer.text().len == 0 and
            self.profile_about_buffer.text().len == 0 and
            self.profile_picture_buffer.text().len == 0;
    }
    /// Saving is refused until the app HAS the profile it would be merging into.
    /// Publishing a merge of nothing is how a lightning address disappears.
    ///
    /// `.absent` is the case that needed the argument. It means "a relay
    /// answered and did not send a kind:0", which reads as "you have none" and
    /// is the same inference `canWriteFollows` and `canWriteRelayList` both
    /// refuse: on a cold import the relays being asked are the four this app was
    /// born with, and a clean answer from those is not evidence about a profile
    /// living somewhere else. Saving from `.absent` merged into a literal `{}`
    /// and published it, so a reader who typed a display name lost their
    /// lightning address, their NIP-05, their banner, their website and every
    /// NIP-39 proof in one press. A key minted in this app has no profile
    /// anywhere and is the one case where absent really is absent.
    pub fn profile_can_save(self: *const Model) bool {
        // `.sent` stays savable: a reader who spots a typo in the name they just
        // saved must be able to fix it, and a sheet whose Save is dead after one
        // press is a sheet they have to close and reopen to use again.
        return switch (self.profile_stage) {
            .have, .failed, .sent => true,
            .absent => g_identity_minted_here,
            .fetching, .saving, .unread => false,
        };
    }
    /// The add-a-relay field's text.
    pub fn relay_draft(self: *const Model) []const u8 {
        return self.relay_buffer.text();
    }
    /// Why the last Add did nothing, said in the field's own terms.
    pub fn relay_status(self: *const Model) []const u8 {
        if (self.relay_full) return "That's the most relays this app keeps. Remove one first.";
        if (self.relay_error) return "A relay address starts with wss:// and names a host.";
        // Last, because the two above are about the press that just happened
        // and this one is about the account. An edit that will not be published
        // has to say so: silence here would read as "published", which is the
        // one thing it is not.
        if (relayWriteBlockedReason()) |why| return why;
        return "";
    }
    /// What the previews switch is, in the terms that matter: not bandwidth.
    pub fn previews_explainer(self: *const Model) []const u8 {
        _ = self;
        return "Pictures, faces, link previews and NIP-05 checks are fetched from the hosts a note names. " ++
            "Off, none of that is asked for until you press a picture, and only your relays learn you are reading.";
    }
    pub fn previews_state(self: *const Model) []const u8 {
        _ = self;
        return if (g_media_previews) "On" else "Off. Press a picture to load that one.";
    }
    pub fn previews_action(self: *const Model) []const u8 {
        _ = self;
        return if (g_media_previews) "Turn off" else "Turn on";
    }
    /// How many notes are still waiting for their first relay. Read once per
    /// build, because the publisher writes the queue from its own thread and the
    /// view must see one answer for the whole frame.
    pub fn outbox_label(self: *const Model, arena: std.mem.Allocator) []const u8 {
        // First, because it is the worst thing this zone can have to say: a note
        // the reader wrote that was never offered to anybody. `g_outbox_overflow`
        // was set for this and read nowhere, so the promise under the banner,
        // that anything you write is kept until a relay takes it, was quietly
        // untrue in the one case it was written for.
        if (self.outbox_overflowed) return "a note could not be queued";
        // A note that gave up is not "posting". Saying so would be the same lie
        // the queue was built to stop telling.
        if (self.outbox_pending == 0 and self.outbox_stuck > 0) {
            if (self.outbox_stuck == 1) return "1 note did not go out";
            return std.fmt.allocPrint(arena, "{d} notes did not go out", .{self.outbox_stuck}) catch "notes did not go out";
        }
        const n = self.outbox_pending;
        if (n == 1) return "posting 1 note…";
        return std.fmt.allocPrint(arena, "posting {d} notes…", .{n}) catch "posting…";
    }
    /// The app version line for the Settings footer.
    pub fn version_line(self: *const Model) []const u8 {
        _ = self;
        return "Plaza " ++ plaza_version;
    }

    /// The feed, iterated by `<for each="note_list">`, newest first.
    pub fn note_list(self: *const Model, arena: std.mem.Allocator) []const Note {
        _ = arena;
        return self.notes[0..self.notes_len];
    }
    pub fn has_notes(self: *const Model) bool {
        return self.notes_len > 0;
    }
    /// No notes yet, show the centered connecting/offline state (the message
    /// itself, `empty_text`, differentiates dialing from a dropped relay).
    pub fn empty(self: *const Model) bool {
        return self.notes_len == 0;
    }
    /// Header status line: how much of the relay pool is live.
    pub fn status(self: *const Model, arena: std.mem.Allocator) []const u8 {
        if (self.live_relays > 0)
            return std.fmt.allocPrint(arena, "Live · {d}/{d} relays", .{ self.live_relays, self.relay_count }) catch "Live";
        if (self.relay_count > 0 and self.offline_relays >= self.relay_count) return "Offline, reconnecting…";
        return "Connecting…";
    }
    pub fn empty_text(self: *const Model) []const u8 {
        if (self.relay_count > 0 and self.offline_relays >= self.relay_count) return "Can't reach any relay. Retrying…";
        return "Connecting to the relay pool…";
    }
    /// Status-bar summary.
    pub fn footer(self: *const Model, arena: std.mem.Allocator) []const u8 {
        if (self.notes_len == 0) return "";
        return std.fmt.allocPrint(arena, "{d} notes", .{self.notes_len}) catch "";
    }

    /// The status bar's left text, which doubles as the caught-up footer: there
    /// is no separate spinner, the feed renders from disk before the window
    /// finishes opening.
    pub fn caught_up(self: *const Model, arena: std.mem.Allocator) []const u8 {
        const scope = self.scope_name();
        if (self.notes_len == 0) return scope;
        return std.fmt.allocPrint(arena, "Caught up · {s} · {d} notes", .{ lowerScope(scope), self.notes_len }) catch scope;
    }

    /// The status bar's relay health, drawn after the online dot.
    pub fn relay_health(self: *const Model, arena: std.mem.Allocator) []const u8 {
        return std.fmt.allocPrint(arena, "{d}/{d} relays", .{ self.live_relays, self.relay_count }) catch "relays";
    }

    /// Whether at least one relay is connected (drives the status dot color).
    pub fn relays_online(self: *const Model) bool {
        return self.live_relays > 0;
    }

    /// Whether the reader is browsing without an identity. Reading never
    /// needs one; the gated verbs ask at first intent.
    pub fn is_guest(self: *const Model) bool {
        _ = self;
        return activePubkey() == null;
    }

    /// Whether the guest join strip is showing (guest, and not dismissed).
    pub fn show_guest_strip(self: *const Model) bool {
        return self.is_guest() and !self.guest_strip_dismissed;
    }

    /// What the feed is scoped to. It stops being a hand-picked pack the moment
    /// the reader has a follow list of their own, and the line has to stop
    /// saying so: calling somebody's own follows "hand-picked" by this app is
    /// exactly the kind of small lie that makes a reader distrust the big
    /// statements too.
    pub fn scope_name(self: *const Model) []const u8 {
        _ = self;
        return if (followsAreOwned()) "Following" else "Starter pack";
    }

    /// The feed's scope line: how many voices it is scoped to, and whose choice
    /// that was.
    pub fn scope_voices(self: *const Model, arena: std.mem.Allocator) []const u8 {
        _ = self;
        const shown = followSet().len;
        if (!followsAreOwned()) {
            return std.fmt.allocPrint(arena, "{d} voices · hand-picked", .{shown}) catch "hand-picked";
        }
        // One number, because the feed reads the whole list. This used to state
        // two ("128 of 300 accounts") back when it read a slice, and that was
        // worth the clutter then: telling somebody who follows five hundred
        // people that they follow 128 is a lie about their own data.
        if (shown == 1) return "1 account · yours";
        return std.fmt.allocPrint(arena, "{d} accounts · yours", .{shown}) catch "yours";
    }

    /// The note with this id, if it is still in the feed or the open thread. A
    /// thread's root and replies are not in the feed window but are still
    /// pressable (like, image, open-as-thread), so they resolve here too.
    pub fn mentionsOff(self: *const Model) []const [32]u8 {
        return self.mentions_off[0..self.mentions_off_len];
    }

    pub fn noteById(self: *const Model, note_id: i64) ?*const Note {
        for (self.notes[0..self.notes_len]) |*note| {
            if (note.id == note_id) return note;
        }
        // A profile's rows live in the same buffer, so they resolve the same way.
        // Without this every press on a profile row (open, like, expand a
        // picture) is a silent no-op, which is worse than an inert control
        // because it looks live.
        if (self.viewing_thread != 0 or self.viewing_profile != null) {
            if (self.thread_root.id == note_id) return &self.thread_root;
            for (self.thread_notes[0..self.thread_notes_len]) |*note| {
                if (note.id == note_id) return note;
            }
        }
        return null;
    }

    /// Which level of the thread stack is on screen. Every per-level table is
    /// indexed by this, and it is clamped because the stack saturates at
    /// `thread_depth_max` by replacing its top rather than growing.
    pub fn currentLevel(self: *const Model) usize {
        return @min(self.thread_stack_len, thread_depth_max);
    }

    /// The open profile's notes, newest first, read from the local store. The
    /// same shape as the thread's refresh: the store is the app, so the screen
    /// fills from disk before any relay answers and the backfill only widens it.
    fn refreshProfileNotes(self: *Model, now_s: i64) void {
        const pk = self.viewing_profile orelse return;
        const store = g_store orelse return;
        const kinds = [_]u16{1};
        const authors = [_][32]u8{pk};
        var result = store.query(std.heap.page_allocator, .{
            .authors = &authors,
            .kinds = &kinds,
            .limit = thread_reply_cap,
        }) catch return;
        defer result.deinit();
        var n: usize = 0;
        for (result.events) |ev| {
            if (n >= self.thread_notes.len) break;
            self.thread_notes[n] = noteFrom(ev, now_s);
            n += 1;
        }
        self.thread_notes_len = n;
    }

    /// Which of the profile's two tabs a note belongs to. "Notes" is what they
    /// wrote; "Replies" is what they wrote at somebody. A tab that mixed them
    /// would be a tab that lies about what it holds.
    pub fn profileNotesFor(self: *const Model, out: []usize, pubkey: [32]u8) []const usize {
        var n: usize = 0;
        // Only THIS person's notes. `thread_notes` is one buffer shared with the
        // thread screen, so a stacked level that is not the one being read holds
        // somebody else's rows, and counting those would give the retained list
        // a length that does not match what it draws.
        for (self.thread_notes[0..self.thread_notes_len], 0..) |note, i| {
            if (n >= out.len) break;
            if (!std.mem.eql(u8, &note.pubkey, &pubkey)) continue;
            const is_reply = note.has_reply_parent;
            if ((self.profile_tab == .replies) != is_reply) continue;
            out[n] = i;
            n += 1;
        }
        return out[0..n];
    }

    /// Rebuilds the open thread's replies from the store: every kind:1 that
    /// e-tags the root, oldest first, into the `thread_notes` cache. Local-first,
    /// the same path the feed uses; cheap enough to run each tick so
    /// late-arriving replies appear and relative times stay fresh.
    fn refreshThreadNotes(self: *Model, now_s: i64) void {
        if (self.viewing_thread == 0) return;
        const store = g_store orelse return;
        // The whole subtree, not just the direct children: the closure walk is
        // what keeps a SUB-thread's deep replies visible (they tag the true
        // root and their direct parent, never a mid-thread note).
        var ids: [thread_reply_cap][32]u8 = undefined;
        const id_count = collectThreadIds(store, self.thread_root.event_id, &ids);

        var n: usize = 0;
        for (ids[0..id_count]) |id| {
            if (n >= self.thread_notes.len) break;
            var se = (store.getEvent(std.heap.page_allocator, id) catch continue) orelse continue;
            defer se.deinit();
            self.thread_notes[n] = noteFrom(se.event, now_s);
            // Queue the replier's profile so a name, avatar, and handle resolve
            // for a reply from someone outside the follow set.
            wantProfile(se.event.pubkey);
            n += 1;
        }
        // Whether this thread's own fetch has asked every relay and come back, or
        // given up waiting on one that never sends its EOSE. Until then the
        // replies are still streaming in and belong to one batch.
        const done = g_thread_done_seq.load(.acquire) == self.thread_seq;
        const timed_out = now_s - self.thread_open_at > thread_loading_grace_s;
        stampArrival(arrivalTableFor(self.thread_stack_len, self.thread_root.event_id), self.thread_notes[0..n], done or timed_out);
        // In reading order, so seat each reply under the note it answers.
        arrangeThread(self.thread_notes[0..n], self.thread_root.event_id);
        self.thread_notes_len = n;
        // Stop the loading skeletons once replies are in hand, OR once the fetch
        // is done or timed out. Otherwise skeletons would stall forever under a
        // note that simply has no replies.
        if (self.thread_loading and (n > 0 or done or timed_out)) self.thread_loading = false;
    }

    /// The reply count for the thread breadcrumb: the crowd count the feed's
    /// engagement subscription already knows (so it reads right the instant a
    /// thread opens, before the replies are fetched), or the fetched count once
    /// that is higher.
    fn threadReplyCount(self: *const Model) usize {
        const crowd: usize = engagementFor(self.thread_root.id).replies;
        return @max(crowd, self.thread_notes_len);
    }

    /// The span of notes at or near the viewport, which is what gets pictures.
    /// Card heights vary, so this estimates from the average (total content over
    /// note count) and pads generously; being a row or two wide only costs a
    /// prefetch. Before the first scroll event it reports the top of the feed.
    pub fn visibleRange(self: *const Model) RowRange {
        if (self.notes_len == 0) return .{ .first = 0, .last = 0 };
        // The windowed list reports the exact rows it put on screen, so this is
        // no longer an estimate. Before the first build it reports the top.
        const last_row = self.notes_len - 1;
        if (g_visible_last == 0 and g_visible_first == 0) {
            return .{ .first = 0, .last = @min(last_row, max_media_images - 1) };
        }
        return .{ .first = @min(g_visible_first, last_row), .last = @min(g_visible_last, last_row) };
    }

    /// The rows to have READY, which is wider than the rows on screen.
    ///
    /// A face or a picture is fetched only for a row the viewport already holds,
    /// so scrolling meant watching them arrive: the row lands blank, asks the
    /// network, and fills in a moment later, over and over, for as long as you
    /// keep moving. The bytes are what take time, and nothing about fetching them
    /// requires the row to be visible.
    ///
    /// So a band either side of the viewport is warmed into the disk cache
    /// ahead of arriving. Either side on purpose: scrolling back up is as common
    /// as scrolling down, and a cache that only ever looks forward makes the way
    /// back feel broken in a way the way down does not.
    pub fn prefetchRange(self: *const Model) RowRange {
        const w = self.visibleRange();
        if (self.notes_len == 0) return w;
        const last_row = self.notes_len - 1;
        return .{
            .first = w.first -| feed_prefetch_rows,
            .last = @min(last_row, w.last + feed_prefetch_rows),
        };
    }

    /// Reconciles the feed with the store. Updates the connection line every
    /// tick; re-queries and rebuilds the note cards only when the store's event
    /// count changed since the last rebuild; and re-computes relative times for
    /// the notes on screen. `now_s` is the current wall-clock second.
    fn refresh(self: *Model, now_s: i64) void {
        var live: usize = 0;
        var offline: usize = 0;
        // Only slots that hold a relay: a dormant slot's status is whatever it
        // was when its relay was removed, and counting it would report the app
        // offline from a relay the reader deleted.
        for (0..relaySlots()) |i| {
            if (relayAt(i) == null) continue;
            switch (@as(Conn, @enumFromInt(g_relay_status[i].load(.acquire)))) {
                // A quiet relay still holds its socket and nothing has failed,
                // so it counts as live here. Saying otherwise would put the app
                // behind an "offline, reconnecting" banner on a slow night.
                .connected, .quiet => live += 1,
                .offline => offline += 1,
                .connecting => {},
            }
        }
        self.live_relays = live;
        self.offline_relays = offline;
        // Sampled together, so a frame never mixes a fresh numerator with a
        // stale denominator and reads "4/3 relays".
        self.relay_count = relayCount();

        // A relay came up, or the pool changed size: whatever could not be found
        // a moment ago may be findable now, so everything still unresolved goes
        // back in the queue immediately rather than waiting out its backoff. This
        // is the case that produced the report: three tries spent while nothing
        // was connected wrote a note off, and nothing ever asked again.
        if (live != g_last_live_relays or self.relay_count != g_last_relay_count) {
            g_last_live_relays = live;
            g_last_relay_count = self.relay_count;
            requeueMissingQuotes();
        }

        const store = g_store orelse return;

        const count = store.eventCount() catch return;
        // Three ways the view can be behind the store. The count catches
        // anything landing by any route; the other two are the feed's own, and
        // either can be true on a tick where the count has not moved (a
        // deletion cancels an insert, or nothing was stored at all and the
        // reader simply changed who they follow).
        const stale = count != g_last_count or
            g_arrival_pending.load(.acquire) or
            g_feed_rebuild_all.load(.acquire) or
            self.feed_limit != g_notes_feed_limit;
        if (stale) {
            g_last_count = count;
            // Profiles first, so a note's mentions resolve to names as it builds.
            refreshProfiles(store);
            rebuildNotes(self, store, now_s);
            // A grown store may hold quoted events the feed references now.
            refreshQuotes(store);
        }
        for (self.notes[0..self.notes_len]) |*note| note.setTime(now_s);
    }

    fn rebuildNotes(self: *Model, store: *nostr.store.Store, now_s: i64) void {
        const kinds = [_]u16{1};
        // Scope the feed to the follow set (the starter pack) plus the user's own
        // notes, so it reads as a real follow feed, not a firehose. Filtering
        // here (not just at the subscription) also hides notes an earlier,
        // unscoped run may have left in the store.
        var authors: [max_follows + 1][32]u8 = undefined;
        var authors_len: usize = 0;
        for (followSet()) |pk| {
            if (authors_len >= max_follows) break;
            authors[authors_len] = pk;
            authors_len += 1;
        }
        if (activePubkey()) |pk| {
            authors[authors_len] = pk;
            authors_len += 1;
        }
        // Only as much as the reader has paged into, so the rebuild cost stays
        // flat until they actually ask for more.
        // No ceiling. The reader asked for this many, so the storage grows to
        // hold them and the query asks for exactly that.
        const limit = @min(self.feed_limit, ensureFeedCapacity(self.feed_limit));
        // After a growth the old slice is freed, so re-point before using it.
        self.notes = g_feed_notes;

        // Mention labels are baked into content at parse time, so a new display
        // name (the generation) forces one full parse pass to refresh them.
        const reuse_ok = g_names_generation == g_notes_names_generation;
        g_notes_names_generation = g_names_generation;

        // Always, and before deciding anything: whatever is waiting is either
        // spliced now or covered by the full read below, and leaving it in the
        // buffer would splice it a second time on the next tick.
        const arrived = takeFeedArrivals();

        // What the list in hand cannot be brought up to date FROM. Everything
        // else is an addition, and an addition is a merge.
        //
        //   the flag       the author set changed, the reader signed in or out,
        //                  or a deletion landed
        //   lost           more arrived between two ticks than the buffer holds
        //   !reuse_ok      a name moved, so every card's baked text is stale
        //   limit moved    the reader paged down, so notes below the old window
        //                  belong now and no arrival describes them
        const full = g_feed_rebuild_all.swap(false, .acq_rel) or
            arrived.lost or
            !reuse_ok or
            limit != g_notes_limit or
            self.feed_limit != g_notes_feed_limit;
        g_notes_limit = limit;
        g_notes_feed_limit = self.feed_limit;

        if (full) {
            self.rebuildNotesFromStore(store, now_s, authors[0..authors_len], &kinds, limit, reuse_ok);
            return;
        }
        if (arrived.n == 0) return;
        self.spliceArrivals(store, now_s, authors[0..authors_len], &kinds, limit, arrived.n);
    }

    /// Reads the whole window back from the store: a cursor per followed author
    /// and a linear pick across all of them, per note returned. The expensive
    /// one, and the reason for everything above it.
    fn rebuildNotesFromStore(
        self: *Model,
        store: *nostr.store.Store,
        now_s: i64,
        authors: []const [32]u8,
        kinds: []const u16,
        limit: usize,
        reuse_ok: bool,
    ) void {
        var result = store.query(std.heap.page_allocator, .{
            .authors = authors,
            .kinds = kinds,
            .limit = @intCast(limit),
        }) catch return;
        defer result.deinit();
        g_feed_work.full_reads += 1;

        // The old cards, so new positions can take them over by id.
        const old = g_feed_scratch;
        const old_len = self.notes_len;
        @memcpy(old[0..old_len], self.notes[0..old_len]);
        const slots = if (reuse_ok) buildReuseIndex(old[0..old_len]) else &.{};

        var n: usize = 0;
        for (result.events) |ev| {
            if (n >= limit) break;
            self.notes[n] = blk: {
                if (heldIndex(slots, old[0..old_len], ev.id)) |at| break :blk old[at];
                g_feed_work.parses += 1;
                break :blk noteFrom(ev, now_s);
            };
            n += 1;
        }
        self.notes_len = n;
    }

    /// Merges the notes that just landed into the list already on screen.
    ///
    /// The ids come from the ingest threads, so the store is asked for exactly
    /// those and nothing else: a direct read per id, no cursor per follow and no
    /// pick across two thousand streams. Everything already held is carried over
    /// as it is, so no card is re-parsed and no picture is re-fetched.
    fn spliceArrivals(
        self: *Model,
        store: *nostr.store.Store,
        now_s: i64,
        authors: []const [32]u8,
        kinds: []const u16,
        limit: usize,
        arrived: usize,
    ) void {
        var result = store.query(std.heap.page_allocator, .{
            .ids = g_arrival_taken[0..arrived],
            .kinds = kinds,
        }) catch {
            // The ids are gone with the buffer, so the only honest recovery is
            // to read the window back next tick.
            invalidateFeed();
            return;
        };
        defer result.deinit();
        g_feed_work.splices += 1;
        if (result.events.len == 0) return;

        // Which of them this feed is actually about. The store was asked by id,
        // not by author, on purpose: an author list is checked one name at a
        // time, and asking about a handful of arrivals should not walk two
        // thousand follows per arrival. Only the ones that are NOT already held
        // pay that walk, and those are few.
        const held = buildReuseIndex(self.notes[0..self.notes_len]);
        var keep: usize = 0;
        for (result.events, 0..) |ev, i| {
            if (keep >= g_splice_keep.len) break;
            if (ev.kind != 1) continue;
            if (heldIndex(held, self.notes[0..self.notes_len], ev.id) != null) continue;
            if (!authorInSet(authors, ev.pubkey)) continue;
            // The window is full and this is older than everything in it, so it
            // would be dropped by the truncation below. Not worth parsing.
            if (self.notes_len >= limit and self.notes_len > 0 and
                !eventNewerThanNote(ev, self.notes[self.notes_len - 1])) continue;
            g_splice_keep[keep] = @intCast(i);
            keep += 1;
        }
        if (keep == 0) return;

        // Two sorted runs into one. `result.events` is newest-first (the store
        // sorts it) and so is the list on screen, so this is one pass with no
        // sort and no search. Through the scratch copy rather than in place: an
        // in-place merge is only safe in one direction, and which direction
        // depends on whether the window is growing or already full.
        const old = g_feed_scratch;
        const old_len = self.notes_len;
        @memcpy(old[0..old_len], self.notes[0..old_len]);

        const total = @min(old_len + keep, limit);
        var oi: usize = 0;
        var fi: usize = 0;
        for (0..total) |n| {
            const take_new = blk: {
                if (fi >= keep) break :blk false;
                if (oi >= old_len) break :blk true;
                break :blk eventNewerThanNote(result.events[g_splice_keep[fi]], old[oi]);
            };
            if (take_new) {
                self.notes[n] = noteFrom(result.events[g_splice_keep[fi]], now_s);
                g_feed_work.parses += 1;
                fi += 1;
            } else {
                self.notes[n] = old[oi];
                oi += 1;
            }
        }
        self.notes_len = total;
    }
};

/// Whether `pubkey` is one of the feed's authors. A walk, because the set is a
/// plain array; only arrivals that are not already on screen reach it.
fn authorInSet(authors: []const [32]u8, pubkey: [32]u8) bool {
    for (authors) |a| {
        if (std.mem.eql(u8, &a, &pubkey)) return true;
    }
    return false;
}

/// Whether `ev` sorts ahead of `note` in the feed: newer, or the same second and
/// a higher id.
///
/// The tie-break is not decoration. It is the store's own ordering
/// (`created_at` descending, then id descending), and a merge that broke ties
/// differently would put two same-second notes in one order while a full read
/// put them in the other, so the pair would swap places the next time anything
/// forced a full read.
fn eventNewerThanNote(ev: nostr.event.Event, note: Note) bool {
    if (ev.created_at != note.created_at) return ev.created_at > note.created_at;
    return std.mem.order(u8, &ev.id, &note.event_id) == .gt;
}

/// Adopts `secret` as the active local identity. For tests: the feed scopes
/// its queries to the follow set plus the signed-in user, so a test that
/// stores its own events needs to BE somebody.
pub fn setIdentityForTest(secret: [32]u8) void {
    var signer = nostr.keys.Signer.init();
    const kp = signer.keyPairFromSecretKey(secret) catch {
        signer.deinit();
        return;
    };
    g_signer_kind = .local;
    setIdentity(signer, kp);
}

/// Clears the active identity again. For tests.
pub fn clearIdentityForTest() void {
    if (g_identity_signer) |*sgn| sgn.deinit();
    g_identity_signer = null;
    g_identity_kp = null;
    g_identity_npub_len = 0;
    g_signer_kind = .local;
}

/// Forces the next reconcile to do the full work rather than take the
/// unchanged-store fast path, so a benchmark measures a rebuild.
pub fn invalidateFeedForTest() void {
    invalidateFeed();
}

/// Reconciles profiles and notes against `store` directly, bypassing change
/// detection entirely. For tests that drive the store themselves rather than
/// through `plazaIngest`, which is where an arrival announces itself: without
/// the announcement there is nothing to splice, so this asks for the full read.
///
/// Tests of the change-detection layer itself go through `plazaIngestForTest`
/// and `Model.refresh`, which is what the app runs.
pub fn reconcileForTest(model: *Model, store: *nostr.store.Store, now_s: i64) void {
    invalidateFeed();
    refreshProfiles(store);
    model.rebuildNotes(store, now_s);
}

/// How the feed has been brought up to date, counted. Asserted on instead of
/// timed: a stopwatch in a Debug test binary on a shared machine says nothing,
/// and the whole point of this path is which of the two ran.
pub const FeedWork = struct {
    /// Windows read back from the store in full: a cursor per followed author.
    full_reads: usize = 0,
    /// Merges of what the ingest threads announced: a direct read per id.
    splices: usize = 0,
    /// Notes parsed from an event. A reused card costs nothing and is not here.
    parses: usize = 0,
};
var g_feed_work: FeedWork = .{};

pub fn feedWork() FeedWork {
    return g_feed_work;
}
pub fn resetFeedWork() void {
    g_feed_work = .{};
}

/// One tick, exactly as the app's timer runs it: change detection and all. The
/// entry point for tests of how the feed decides what to do, as opposed to what
/// a rebuild produces.
pub fn tickForTest(model: *Model, now_s: i64) void {
    model.refresh(now_s);
}

/// Empties the arrival buffer and asks for a full read next time, so a test
/// starts from a known place rather than from whatever the last one left.
pub fn resetFeedChangeDetectionForTest() void {
    clearFeedArrivals();
    invalidateFeed();
    g_notes_limit = 0;
    g_notes_feed_limit = 0;
    g_last_count = std.math.maxInt(usize);
}

/// Announces an id as newly arrived without storing anything. For the case the
/// app is not supposed to produce and the splice guards against anyway.
pub fn noteFeedArrivalForTest(id: [32]u8) void {
    noteFeedArrival(id);
}

/// Fills the arrival buffer past its capacity, the way a backfill does.
pub fn overflowFeedArrivalsForTest() void {
    for (0..feed_arrival_cap + 1) |i| {
        var id = [_]u8{0} ** 32;
        std.mem.writeInt(u64, id[0..8], i, .big);
        noteFeedArrival(id);
    }
}

/// The feed key derived from an event id: the first eight bytes, sign bit
/// masked so the markup engine's i64 key round-trip never overflows.
pub fn noteIdOf(ev: nostr.event.Event) i64 {
    return feedKeyOf(ev.id);
}

fn feedKeyOf(id: [32]u8) i64 {
    return @intCast(std.mem.readInt(u64, id[0..8], .big) & std.math.maxInt(i64));
}

// The previous feed, kept across one rebuild so unchanged notes carry over
// without being re-parsed. Static rather than stack: three hundred cards of
// fixed buffers are far too big for a frame's stack.
/// The feed's note storage, and the scratch copy a rebuild carries the previous
/// pass in. Both grow together and neither ever shrinks: a reader who has paged
/// down to four thousand notes will do it again next session, and returning the
/// memory only to ask for it back is churn for a number nobody sees.
///
/// Page-allocated rather than static. Three hundred notes was already 900 KB of
/// BSS across the two arrays; sizing a static array for "no limit" is not a
/// thing that can be done.
var g_feed_notes: []Note = &.{};
var g_feed_scratch: []Note = &.{};

/// Makes room for `want` notes, returning what is actually available. A failed
/// growth keeps what it had, so a feed that cannot grow stops growing instead of
/// losing the notes it is already showing.
fn ensureFeedCapacity(want: usize) usize {
    if (g_feed_notes.len >= want) return g_feed_notes.len;
    // Doubling, so paging down a long feed is a handful of allocations rather
    // than one per page.
    var next = @max(g_feed_notes.len, feed_page);
    while (next < want) next *|= 2;
    const grown = std.heap.page_allocator.realloc(g_feed_notes, next) catch return g_feed_notes.len;
    const scratch = std.heap.page_allocator.realloc(g_feed_scratch, next) catch {
        // The two must stay the same length: a rebuild indexes both.
        g_feed_notes = grown;
        return @min(grown.len, g_feed_scratch.len);
    };
    for (grown[g_feed_notes.len..]) |*n| n.* = .{};
    g_feed_notes = grown;
    g_feed_scratch = scratch;
    return g_feed_notes.len;
}

/// An open-addressed id-to-slot table over the previous pass, so a rebuild finds
/// an already-parsed card in constant time.
///
/// This was a linear scan of the previous feed, once per event. That is ninety
/// thousand comparisons at the old three-hundred cap, which was survivable, and
/// quadratic without one: sixteen million at four thousand notes, on a rebuild
/// that runs about once a second. Removing the cap is what made the scan matter.
var g_reuse_slots: []u32 = &.{};
const reuse_empty: u32 = std.math.maxInt(u32);

/// Which of a splice's arrivals belong in the feed, as indices into the query
/// result. Indices rather than parsed cards: a thousand `Note`s is over a
/// megabyte of buffers, and the merge can parse each one straight into its final
/// position instead.
var g_splice_keep: [feed_arrival_cap]u32 = undefined;

/// The window depth the list in hand was built for, as asked for and as it came
/// out after clamping to the storage. A change in either means notes below the
/// old bottom belong now, and no arrival says so.
///
/// Both, because they move for different reasons: the reader raises the ask by
/// paging down, and the clamp lifts on its own when a growth that failed earlier
/// succeeds. The ask is also what the tick's own staleness check reads, so that
/// paging down wakes a tick that would otherwise see an unchanged store and
/// skip the rebuild entirely.
var g_notes_limit: usize = 0;
var g_notes_feed_limit: usize = 0;

fn reuseHash(id: i64, mask: usize) usize {
    // Fibonacci mixing: note ids are the first eight bytes of a hash, so the low
    // bits are already well spread, but the multiply costs nothing and protects
    // against a masked slice of them clustering.
    const mixed = @as(u64, @bitCast(id)) *% 0x9E37_79B9_7F4A_7C15;
    return @as(usize, @intCast(mixed >> 40)) & mask;
}

/// Fills the table for `old` and returns it, or an empty slice if it cannot be
/// sized, in which case the caller reparses rather than reusing. Reparsing is
/// slower, never wrong.
fn buildReuseIndex(old: []const Note) []u32 {
    if (old.len == 0) return &.{};
    // Half load factor, so probes stay short.
    var want: usize = 128;
    while (want < old.len * 2) want *|= 2;
    if (g_reuse_slots.len < want) {
        g_reuse_slots = std.heap.page_allocator.realloc(g_reuse_slots, want) catch return &.{};
    }
    const table = g_reuse_slots[0..want];
    @memset(table, reuse_empty);
    const mask = want - 1;
    for (old, 0..) |note, i| {
        var at = reuseHash(note.id, mask);
        while (table[at] != reuse_empty) at = (at + 1) & mask;
        table[at] = @intCast(i);
    }
    return table;
}

/// Where `event_id` sits in `old`, when it is there at all.
///
/// Compares the full 32 bytes, not the eight-byte feed key the table is hashed
/// on. The key is a render handle and two ids could in principle share one; the
/// splice uses this answer to decide whether an arriving note is already on
/// screen, and getting that wrong would show the same note twice or hide a real
/// one behind a stranger's card.
fn heldIndex(table: []const u32, old: []const Note, event_id: [32]u8) ?usize {
    if (table.len == 0) return null;
    const mask = table.len - 1;
    var at = reuseHash(feedKeyOf(event_id), mask);
    while (table[at] != reuse_empty) : (at = (at + 1) & mask) {
        const i = table[at];
        if (std.mem.eql(u8, &old[i].event_id, &event_id)) return i;
    }
    return null;
}

/// Points a model at the feed storage, growing it to at least one page. Called
/// wherever a Model is made, so `notes[0]` is writable without every caller
/// having to think about it.
pub fn attachFeedStorage(model: *Model) void {
    _ = ensureFeedCapacity(feed_page);
    model.notes = g_feed_notes;
}

/// Makes room for `n` notes and re-points `model` at the grown buffer. For tests
/// that fill the feed by hand rather than through the store: the app grows on
/// its way through `rebuildNotes`, and writing past the end without that is the
/// out-of-bounds it should be.
/// One more page, the way the reader's scroll asks for it. For tests, so they
/// page down through the real path rather than setting the limit by hand.
pub fn loadOlderForTest(model: *Model) void {
    model.feed_limit += feed_page;
}

pub fn reserveFeedForTest(model: *Model, n: usize) void {
    _ = ensureFeedCapacity(n);
    model.notes = g_feed_notes;
}
// The names generation the current cards were parsed under (see
// `g_names_generation`).
var g_notes_names_generation: u64 = 0;

/// Reads kind:0 metadata for the feed's authors from the store and parses each
/// into the profile cache. The store keeps only the newest kind:0 per author, so
/// this always reflects the current metadata.
fn refreshProfiles(store: *nostr.store.Store) void {
    const kinds = [_]u16{0};
    // Bounds-checked at every push. This array used to be sized off the
    // comptime pack with no checks, so the first runtime follow list longer than
    // nine would have written past it: silent stack corruption in a release
    // build, from a feature that has nothing to do with profiles.
    // NOT the follow list. This used to walk every follow, up to 2048 of them,
    // on the feed reconcile path, and ask LMDB for all of their metadata on
    // every rebuild. That is the single reason a bigger profile cache made
    // scrolling slower rather than faster: the query limit was derived from the
    // cache size, so growing the cache grew the query.
    //
    // No reference client does this. Notedeck collects pubkeys from notes that
    // were actually ingested and only on a database MISS, then asks in a
    // debounced batch, with no follow-list pass anywhere. Amethyst has no path
    // at all that requests kind:0 for a whole contact list: each name on screen
    // registers itself. Jumble does walk the follow list, but off the render
    // path entirely, twenty at a time with a one second sleep between batches.
    //
    // What replaces it is already here: a displayed author with no name calls
    // `wantProfile`, so the wanted set IS the on-screen set, which is exactly
    // the input Notedeck uses.
    var authors: [wanted_profiles_cap + 1][32]u8 = undefined;
    var authors_len: usize = 0;
    if (activePubkey()) |pk| {
        if (authors_len < authors.len) {
            authors[authors_len] = pk;
            authors_len += 1;
        }
    }
    // Anyone a note mentioned, so their name resolves once it arrives.
    for (&g_wanted) |*w| {
        if (!w.used) continue;
        if (authors_len >= authors.len) break;
        authors[authors_len] = w.pubkey;
        authors_len += 1;
    }
    if (authors_len == 0) return;
    // The limit is how many records the query can match, which is one kind:0
    // per author. It is not a cache size, and tying it to one was the bug.
    var result = store.query(std.heap.page_allocator, .{ .authors = authors[0..authors_len], .kinds = &kinds, .limit = @intCast(authors_len) }) catch return;
    defer result.deinit();
    for (result.events) |ev| {
        const p = upsertProfile(ev.pubkey) orelse continue;
        // The same event parses to the same fields; skip the JSON work.
        if (std.mem.eql(u8, &p.meta_id, &ev.id)) continue;
        const named_before = p.name_len > 0;
        const name_before = p.name_buf;
        parseMetadataInto(p, ev.content);
        p.meta_id = ev.id;
        if ((p.name_len > 0) != named_before or !std.mem.eql(u8, &p.name_buf, &name_before)) {
            g_names_generation +%= 1;
        }
    }
}

/// Marks `pubkey`'s profile as on screen this pass (creating the slot if new),
/// so the id LRU keeps its avatar and evicts someone off screen instead.
fn markAvatarWanted(pubkey: [32]u8) void {
    if (upsertProfile(pubkey)) |p| p.avatar_clock = g_avatar_clock;
}

/// Lends the `max_avatar_images` registry ids to the authors on screen right
/// now (the feed's visible window, or the open thread), reclaiming ids from
/// authors who scrolled away. There are far more cached authors than ids, so
/// without this only the first handful ever seen could hold a face and a
/// thread of strangers showed initials for everyone. Runs each tick before
/// `scanAvatarFetches`, which then fetches the faces for whoever just gained an
/// id. `fx` is needed to free a reclaimed id's registered image.
/// Asks for the kind:0 of everybody the reader is about to read.
///
/// The wanted set is the app's queue of "whose name do we still need", and it
/// was populated by exactly two callers: the inbox, and quoted notes. The FEED
/// never registered anybody. That was fine only for as long as `refreshProfiles`
/// walked the whole follow list, and when that walk was removed from the render
/// path the feed lost its only source of names: the comment left behind claimed
/// "a displayed author with no name calls `wantProfile`", which was true of the
/// notifications page it was written for and of nothing else.
///
/// What that looked like: real accounts, with profiles sitting on the relays,
/// drawn as a raw npub and a two-character avatar for the whole session. The
/// dial-time subscription asks for kind:0 alongside the notes, so most authors
/// resolve and the gap looks like an occasional glitch rather than a missing
/// mechanism. Anybody that one bounded backfill did not cover was never asked
/// about again.
///
/// Over the PREFETCH band, not just the visible rows, so a name is being fetched
/// while the row is still below the fold. This is the same window the image
/// warmer uses, and it has to be: `warmAvatar` needs `picture_len`, which comes
/// from the kind:0, so a face cannot be warmed ahead for somebody nobody asked
/// about. One missing registration was starving both.
///
/// Cheap to call every tick: `wantProfile` returns at once for anybody already
/// named, which after the first pass is nearly everybody.
fn wantProfilesAhead(model: *const Model) void {
    if (activePubkey()) |pk| wantProfile(pk);
    // The notifications page registers its own authors as rows are admitted,
    // which catches likers and zappers who are in no other set.
    if (model.notifications_open) return;
    if (model.viewing_profile != null or model.viewing_thread != 0) {
        const set = &g_level_visible[@min(g_visible_level, g_level_visible.len - 1)];
        for (set.authors[0..set.author_count]) |pk| wantProfile(pk);
        return;
    }
    const w = model.prefetchRange();
    var i = w.first;
    while (i <= w.last and i < model.notes_len) : (i += 1) wantProfile(model.notes[i].pubkey);
}

fn assignAvatarSlots(fx: *Effects, model: *const Model) void {
    g_avatar_clock += 1;

    // Collect the on-screen authors in READING ORDER (the active user, then the
    // thread's root and replies top-down, or the feed's visible window). Order
    // matters: there are far fewer ids than a long thread has authors, so the
    // ids are lent to the top of what is being read, not to an arbitrary cache
    // slot. Bounded to the largest set a single pass can hold.
    var onscreen: [thread_reply_cap + 4][32]u8 = undefined;
    var n: usize = 0;
    const push = struct {
        fn f(list: [][32]u8, len: *usize, pk: [32]u8) void {
            if (len.* < list.len) {
                list[len.*] = pk;
                len.* += 1;
            }
        }
    }.f;
    if (activePubkey()) |pk| push(&onscreen, &n, pk);
    if (model.notifications_open) {
        // The notifications page occludes everything, and its rows are the only
        // faces on screen. Without this branch its authors were never in the
        // set that lends registry slots, so every row drew initials no matter
        // how long the page stayed open: the ids were all out on loan to a feed
        // nobody could see.
        // Only the rows ON SCREEN, which is the same rule the thread branch
        // below spells out and the same mistake it is warning about. Pushing
        // all of them marked every author wanted, and the claim pass never
        // evicts anything wanted this pass, so nine ids were locked by rows the
        // reader could not see and every visible row kept its initials.
        var buf: [inbox_cap]InboxItem = undefined;
        const shown = inboxItems(&buf, !model.notifications_everyone);
        const first = @min(g_inbox_visible.first, shown.len);
        const last = @min(g_inbox_visible.last + 1, shown.len);
        if (last > first) {
            for (shown[first..last]) |item| push(&onscreen, &n, item.author);
        }
    } else if (model.viewing_profile != null or model.viewing_thread != 0) {
        // A level occludes the feed, so its authors own the ids while it is up,
        // and only the ones ON SCREEN in it. Walking every note in the level
        // instead meant the first nine authors of a long thread took every id
        // and kept it: the claim pass never evicts anything marked wanted this
        // pass, and marking all of them made every id unreclaimable. Everyone
        // below kept initials for as long as the level was open.
        const set = &g_level_visible[@min(g_visible_level, g_level_visible.len - 1)];
        for (set.authors[0..set.author_count]) |pk| push(&onscreen, &n, pk);
    } else {
        const w = model.visibleRange();
        var i = w.first;
        while (i <= w.last and i < model.notes_len) : (i += 1) push(&onscreen, &n, model.notes[i].pubkey);
    }

    // Mark every one wanted FIRST, so the claim pass below never evicts a
    // sibling that is also on screen this pass. Then lend an id to each in order,
    // so the earliest-read authors win the scarce ids.
    for (onscreen[0..n]) |pk| markAvatarWanted(pk);
    for (onscreen[0..n]) |pk| {
        const p = lookupProfile(pk) orelse continue;
        if (p.image_id == 0 and p.picture_len > 0) claimAvatarSlot(fx, p);
    }
}

/// Assigns `p` a free registry id, or the id of the author least-recently on
/// screen (never one mid-fetch, never one on screen this pass, so a just-lent id
/// is safe). A no-op when every id is held by an on-screen author (that author
/// keeps initials this frame). A reclaimed id's old image is unregistered and its
/// former owner reset to reload from cache when it returns.
fn claimAvatarSlot(fx: *Effects, p: *Profile) void {
    var held = [_]bool{false} ** (max_avatar_images + 1);
    for (&g_profiles) |*q| {
        if (q.used and q.image_id >= 1 and q.image_id <= max_avatar_images) held[@intCast(q.image_id)] = true;
    }
    var id: usize = 1;
    while (id <= max_avatar_images) : (id += 1) {
        if (!held[id]) {
            p.image_id = @intCast(id);
            return;
        }
    }
    var victim: ?*Profile = null;
    for (&g_profiles) |*q| {
        if (!q.used or q.image_id == 0) continue;
        if (q.avatar_clock == g_avatar_clock or q.avatar_state == .fetching) continue;
        if (victim == null or q.avatar_clock < victim.?.avatar_clock) victim = q;
    }
    const v = victim orelse return;
    const reclaimed = v.image_id;
    _ = fx.unregisterImage(reclaimed);
    v.image_id = 0;
    v.avatar_state = .idle;
    p.image_id = reclaimed;
}

/// Pulls the bytes for rows NEAR the viewport into the disk cache, without
/// claiming a registry id for any of them.
///
/// The two are separable and were not separated. Fetching was gated on holding
/// one of the nine avatar ids or six picture ids, and those are lent only to rows
/// already on screen, so every row arrived cold: blank, then a request, then a
/// face a moment later. Scroll and it happens again, forever, which is what makes
/// a feed feel like it is dragging even when the frame time is fine.
///
/// Nothing about downloading an image needs a slot. Only DISPLAYING it does. So a
/// band either side of the viewport is fetched and written to `~/.plaza/media`
/// ahead of time, and the local-first path that already exists (`loadCachedImage`
/// on claim, "registered before the first paint") turns that into an instant
/// face when the row does arrive.
fn warmAhead(fx: *Effects, model: *const Model) void {
    if (!g_media_previews) return;
    // Only the feed. A thread or a profile is a bounded level whose rows are all
    // fetched by the pass that owns it, and widening those would spend bandwidth
    // on rows that do not exist.
    if (model.viewing_profile != null or model.viewing_thread != 0) return;

    const warm = model.prefetchRange();
    const seen = model.visibleRange();
    // Budgets of their own, under the ceilings the on-screen passes use: warming
    // must never crowd out the row the reader is looking at. Faces are small and
    // there is one per row, so they get the larger share; a picture can be a
    // megabyte, and warming a stack of them for rows nobody reaches is how a
    // prefetch turns into somebody's data bill.
    const face_per_tick = 8;
    const picture_per_tick = 3;
    var faces: usize = 0;
    var pictures: usize = 0;

    var i = warm.first;
    while (i <= warm.last and i < model.notes_len) : (i += 1) {
        // The rows on screen are the other passes' business; they hold slots and
        // are already being fetched properly.
        if (i >= seen.first and i <= seen.last) continue;
        const note = &model.notes[i];
        if (faces < face_per_tick) {
            if (lookupProfile(note.pubkey)) |p| {
                if (warmAvatar(fx, p)) faces += 1;
            }
        }
        if (pictures < picture_per_tick and note.hasImage()) {
            if (warmPicture(fx, note)) pictures += 1;
        }
    }
}

/// Warms one face. Returns whether a fetch actually went out.
fn warmAvatar(fx: *Effects, p: *Profile) bool {
    if (p.warm_state != .idle or p.picture_len == 0) return false;
    // A face that HOLDS a registry id is the on-screen path's business, and
    // warming it would be a second request for the same bytes. Everything else is
    // warmable: a `.failed` fetch from a previous pass is worth one more try from
    // the cache's side, and `.idle` with no id is the ordinary case this exists
    // for. What is NOT warmable is a face already in the cache, which the check
    // below settles.
    if (p.image_id != 0 or p.avatar_state == .loaded) return false;

    var url_buf: [1024]u8 = undefined;
    const url = mediaUrl(&url_buf, p.picture(), avatar_target_px, .square);
    if (cachedImageExists(url)) {
        p.warm_state = .done;
        return false;
    }
    const index = profileIndexOf(p) orelse return false;
    p.warm_state = .fetching;
    fx.fetch(.{
        .key = avatar_warm_key_base + index,
        .url = url,
        .on_response = Effects.responseMsg(.avatar_warmed),
    });
    return true;
}

/// Warms one picture. Keyed by the note's own id rather than a slot, since the
/// whole point is that it has no slot.
fn warmPicture(fx: *Effects, note: *const Note) bool {
    const raw = note.imageUrl();
    if (raw.len == 0) return false;
    var url_buf: [1024]u8 = undefined;
    const url = feedImageUrl(&url_buf, raw);
    if (warmedAlready(url)) return false;
    if (cachedImageExists(url)) {
        _ = rememberWarmed(url);
        return false;
    }
    // A slot's worth of key space, indexed by the ring position rather than by a
    // media slot, which this deliberately does not hold.
    const index = rememberWarmed(url);
    fx.fetch(.{
        .key = media_warm_key_base + index,
        .url = url,
        .on_response = Effects.responseMsg(.media_warmed),
    });
    return true;
}

/// The URLs warmed recently, so a row hovering just off screen is not re-fetched
/// every tick. A ring rather than a set: it only has to stop a repeat within the
/// few seconds a row spends near the edge, and a cache hit is the backstop for
/// anything it forgets.
const warm_ring_len = 32;
const WarmEntry = struct {
    hash: u64 = 0,
    url_buf: [1024]u8 = [_]u8{0} ** 1024,
    url_len: u16 = 0,

    fn url(self: *const WarmEntry) []const u8 {
        return self.url_buf[0..self.url_len];
    }
};
var g_warm_ring: [warm_ring_len]WarmEntry = [_]WarmEntry{.{}} ** warm_ring_len;
var g_warm_ring_next: u64 = 0;

fn warmedAlready(url: []const u8) bool {
    const h = std.hash.Wyhash.hash(0, url);
    for (&g_warm_ring) |*seen| {
        if (seen.hash == h and seen.url_len != 0) return true;
    }
    return false;
}

/// Records the attempt AND the URL, because the effect response carries a key
/// and a body but not the address it came from, and the cache is keyed by the
/// address.
fn rememberWarmed(url: []const u8) u64 {
    const slot = g_warm_ring_next % warm_ring_len;
    const e = &g_warm_ring[@intCast(slot)];
    e.hash = std.hash.Wyhash.hash(0, url);
    const n = @min(url.len, e.url_buf.len);
    @memcpy(e.url_buf[0..n], url[0..n]);
    e.url_len = @intCast(n);
    g_warm_ring_next +%= 1;
    return slot;
}

/// The index of `p` within the profile table, which is what the avatar fetch
/// keys are built from.
fn profileIndexOf(p: *const Profile) ?u64 {
    for (&g_profiles, 0..) |*q, i| {
        if (q == p) return @intCast(i);
    }
    return null;
}

/// A warmed face's bytes: written to the cache, never registered. The row that
/// eventually shows it claims an id and loads it from disk.
fn handleAvatarWarmed(response: native_sdk.EffectResponse) void {
    if (response.key < avatar_warm_key_base) return;
    const index = response.key - avatar_warm_key_base;
    if (index >= g_profiles.len) return;
    const p = &g_profiles[@intCast(index)];
    if (!p.used) return;
    // A rejection is a busy effect table, not a bad URL: leave it warmable.
    if (response.outcome == .rejected) {
        p.warm_state = .idle;
        return;
    }
    p.warm_state = .done;
    if (response.outcome != .ok or response.status != 200 or response.truncated) return;
    if (response.body.len == 0 or response.body.len > max_image_bytes) return;
    var url_buf: [1024]u8 = undefined;
    const url = mediaUrl(&url_buf, p.picture(), avatar_target_px, .square);
    storeCachedImage(url, response.body);
}

/// The same for a picture. There is no per-note state to update: the ring already
/// recorded the attempt, and the file is the result.
fn handleMediaWarmed(response: native_sdk.EffectResponse) void {
    if (response.key < media_warm_key_base) return;
    const slot = response.key - media_warm_key_base;
    if (slot >= g_warm_ring.len) return;
    if (response.outcome != .ok or response.status != 200 or response.truncated) return;
    if (response.body.len == 0 or response.body.len > max_image_bytes) return;
    // The ring is what remembers the address: a response carries a key and a
    // body, and the cache is keyed by the URL. A slot reused by a later warm
    // before this answer arrived writes the newer URL's name, so the hash is
    // checked rather than assumed.
    const e = &g_warm_ring[@intCast(slot)];
    if (e.url_len == 0) return;
    storeCachedImage(e.url(), response.body);
}

/// Fires avatar fetches for cached profiles that have a picture and an image
/// slot but no avatar yet, a few per tick to stay well inside the effect budget.
/// The response lands on `avatar_fetched`.
fn scanAvatarFetches(fx: *Effects) void {
    // A face is something the note points at, like its picture.
    if (!g_media_previews) return;
    const per_tick = 8;
    var fired: usize = 0;
    for (&g_profiles, 0..) |*p, i| {
        if (!p.used or p.avatar_state != .idle or p.picture_len == 0 or p.image_id == 0) continue;

        var url_buf: [1024]u8 = undefined;
        const url = mediaUrl(&url_buf, p.picture(), avatar_target_px, .square);
        const n = @min(url.len, p.url_buf.len);
        @memcpy(p.url_buf[0..n], url[0..n]);
        p.url_len = @intCast(n);

        // Local-first: a cached avatar is registered before the first paint, so
        // faces arrive with the feed rather than seconds after it.
        if (loadCachedImage(fx, p.image_id, p.url(), avatar_target_px)) |_| {
            p.avatar_state = .loaded;
            continue;
        }
        if (fired >= per_tick) continue;
        p.avatar_state = .fetching;
        fx.fetch(.{
            .key = avatar_fetch_key_base + @as(u64, @intCast(i)),
            .url = p.url(),
            .on_response = Effects.responseMsg(.avatar_fetched),
        });
        fired += 1;
    }
}

/// Handles an avatar fetch response: registers the decoded image on success, or
/// retries a slot-starved rejection and gives up (initials) on anything else.
fn handleAvatarFetched(fx: *Effects, response: native_sdk.EffectResponse) void {
    if (response.key < avatar_fetch_key_base) return;
    const slot = response.key - avatar_fetch_key_base;
    if (slot >= g_profiles.len) return;
    const p = &g_profiles[@intCast(slot)];
    if (!p.used) return;

    // A rejection means every effect slot was busy: try again next tick.
    if (response.outcome == .rejected) {
        p.avatar_state = .idle;
        return;
    }
    // Anything but a clean, whole, OK image body. Which of those is worth asking
    // again is the same question the feed's pictures ask, so it is the same
    // answer: a face used to be given up on for the rest of the session over one
    // 503, one rate limit, or one dropped connection.
    if (response.outcome != .ok or response.status != 200 or response.truncated or response.body.len == 0 or response.body.len > max_image_bytes) {
        p.avatar_state = switch (classifyImageFailure(response.outcome, response.status)) {
            .give_up => .failed,
            .retry => blk: {
                p.avatar_attempts +|= 1;
                break :blk if (p.avatar_attempts >= max_image_attempts) .failed else .idle;
            },
        };
        return;
    }
    // Decode into this profile's fixed image id, downscaling if the platform
    // decoder will not take it as-is. Only a genuinely undecodable body falls
    // back to initials now.
    if (decodeAndRegister(fx, p.image_id, response.body, avatar_target_px)) |_| {
        p.avatar_state = .loaded;
        p.avatar_attempts = 0;
        storeCachedImage(p.url(), response.body);
    } else {
        // Undecodable bytes are a fact about the picture, not about the network.
        p.avatar_state = .failed;
    }
}

/// A NIP-05 local part (`^[a-z0-9-_.]+$`, case-insensitive per the spec), so the
/// name drops straight into the query string without escaping.
pub fn validNip05Name(name: []const u8) bool {
    if (name.len == 0 or name.len > 64) return false;
    for (name) |c| {
        if (!(std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '.')) return false;
    }
    return true;
}

/// A plausible host (optionally `host:port`) for the well-known URL. Guards the
/// fetch against a malformed identifier rather than trusting the kind:0 blob.
pub fn validNip05Domain(domain: []const u8) bool {
    if (domain.len == 0 or domain.len > 253) return false;
    if (std.mem.indexOfScalar(u8, domain, '.') == null) return false;
    for (domain) |c| {
        if (!(std.ascii.isAlphanumeric(c) or c == '.' or c == '-' or c == '_' or c == ':')) return false;
    }
    return true;
}

/// Fires NIP-05 well-known lookups for cached profiles that carry an identifier
/// and have not been checked, a few per tick. The response lands on
/// `nip05_verified`; only a match flips the profile to `.verified`, and only
/// then does the identity line draw its check.
fn scanNip05Fetches(fx: *Effects) void {
    // Verifying a NIP-05 means asking a domain a stranger wrote whether it knows
    // this key, from the reader's own address. That is the same disclosure the
    // switch exists to stop, so it stops here too, and unverified names simply
    // show without a check.
    if (!g_media_previews) return;
    const per_tick = 4;
    var fired: usize = 0;
    for (&g_profiles, 0..) |*p, i| {
        if (!p.used or p.nip05_state != .idle or p.nip05_len == 0) continue;
        const at = std.mem.indexOfScalar(u8, p.nip05(), '@') orelse {
            p.nip05_state = .failed;
            continue;
        };
        const name = p.nip05()[0..at];
        const domain = p.nip05()[at + 1 ..];
        if (!validNip05Name(name) or !validNip05Domain(domain)) {
            p.nip05_state = .failed;
            continue;
        }
        if (fired >= per_tick) continue;
        var url_buf: [320]u8 = undefined;
        const url = std.fmt.bufPrint(&url_buf, "https://{s}/.well-known/nostr.json?name={s}", .{ domain, name }) catch {
            p.nip05_state = .failed;
            continue;
        };
        p.nip05_state = .fetching;
        fx.fetch(.{
            .key = nip05_fetch_key_base + @as(u64, @intCast(i)),
            .url = url,
            .on_response = Effects.responseMsg(.nip05_verified),
        });
        fired += 1;
    }
}

/// True when the well-known JSON maps the identifier's name to `pubkey`. This is
/// the whole trust test: a check is drawn on this and nothing weaker.
pub fn nip05Matches(identifier: []const u8, pubkey: [32]u8, body: []const u8) bool {
    const at = std.mem.indexOfScalar(u8, identifier, '@') orelse return false;
    const name = identifier[0..at];
    if (name.len == 0) return false;

    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const root = std.json.parseFromSliceLeaky(std.json.Value, arena_state.allocator(), body, .{}) catch return false;
    if (root != .object) return false;
    const names = root.object.get("names") orelse return false;
    if (names != .object) return false;
    const entry = names.object.get(name) orelse return false;
    if (entry != .string) return false;

    const want = std.fmt.bytesToHex(pubkey, .lower);
    return std.ascii.eqlIgnoreCase(entry.string, &want);
}

/// Handles a NIP-05 fetch response: verified only on a well-known name→pubkey
/// match; a busy slot retries next tick; anything else fails closed (no check).
fn handleNip05Fetched(response: native_sdk.EffectResponse) void {
    if (response.key < nip05_fetch_key_base) return;
    const slot = response.key - nip05_fetch_key_base;
    if (slot >= g_profiles.len) return;
    const p = &g_profiles[@intCast(slot)];
    if (!p.used or p.nip05_len == 0) return;

    if (response.outcome == .rejected) {
        p.nip05_state = .idle;
        return;
    }
    if (response.outcome != .ok or response.status != 200 or response.truncated or response.body.len == 0) {
        p.nip05_state = .failed;
        return;
    }
    p.nip05_state = if (nip05Matches(p.nip05(), p.pubkey, response.body)) .verified else .failed;
}

// --------------------------------------------------------------- image decode
//
// The canvas image registry decodes through the platform codec and refuses
// anything over 512x512, with no downscaler of its own. Most real avatars and
// nearly every feed photo are larger than that, so Plaza decodes and resizes
// them itself: the platform decoder is tried first (it knows every format the
// OS does, WebP and HEIC included), and stb takes over when it refuses.

extern fn stbi_load_from_memory(buffer: [*]const u8, len: c_int, x: *c_int, y: *c_int, channels_in_file: *c_int, desired_channels: c_int) ?[*]u8;
extern fn stbi_load_gif_from_memory(buffer: [*]const u8, len: c_int, delays: *?[*]c_int, x: *c_int, y: *c_int, z: *c_int, comp: ?*c_int, req_comp: c_int) ?[*]u8;
extern fn stbi_image_free(retval_from_stbi_load: ?*anyopaque) void;
extern fn stbir_resize_uint8_linear(input_pixels: [*]const u8, input_w: c_int, input_h: c_int, input_stride_in_bytes: c_int, output_pixels: [*]u8, output_w: c_int, output_h: c_int, output_stride_in_bytes: c_int, pixel_layout: c_int) ?[*]u8;

/// `STBIR_RGBA`: four channels, alpha not premultiplied, which is what both stb
/// hands back and the registry wants.
const stbir_rgba: c_int = 4;

// The image cache: every image Plaza fetches is written to `$HOME/.plaza/media`
// under a hash of the URL it was fetched from (which encodes the requested
// size), and read back before the network is touched. This is what makes
// avatars and pictures local-first like the notes themselves: on every launch
// after the first they are on screen with the feed, not seconds later.

/// The cache file name for `url`: its SHA-256, hex encoded.
fn cacheName(out: *[64]u8, url: []const u8) []const u8 {
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(url, &digest, .{});
    const hexdigits = "0123456789abcdef";
    for (digest, 0..) |b, i| {
        out[i * 2] = hexdigits[b >> 4];
        out[i * 2 + 1] = hexdigits[b & 0x0f];
    }
    return out[0..];
}

/// Opens (creating if needed) `$HOME/.plaza/media`.
fn mediaCacheDir(io: std.Io, environ: *const std.process.Environ.Map) !std.Io.Dir {
    const home = environ.get("HOME") orelse ".";
    var dir_buf: [512]u8 = undefined;
    const dir_path = try std.fmt.bufPrint(&dir_buf, "{s}/.plaza/media", .{home});
    return std.Io.Dir.cwd().createDirPathOpen(io, dir_path, .{});
}

/// Registers `url`'s image from the on-disk cache, if it is there. Reading a
/// handful of small files is fast enough to do inline, and it is what lets the
/// first painted frame already carry avatars.
fn loadCachedImage(fx: *Effects, id: u64, url: []const u8, max_dim: u32) ?DecodedSize {
    const io = g_io orelse return null;
    const environ = g_environ orelse return null;
    var dir = mediaCacheDir(io, environ) catch return null;
    defer dir.close(io);

    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, url);
    const gpa = std.heap.page_allocator;
    const bytes = dir.readFileAlloc(io, name, gpa, std.Io.Limit.limited(max_image_bytes)) catch return null;
    defer gpa.free(bytes);
    return decodeAndRegister(fx, id, bytes, max_dim);
}

/// Writes a freshly fetched image into the cache. Best-effort: a failure here
/// only costs a re-download next launch.
/// The address a feed picture is fetched from, wherever it is fetched from.
///
/// ONE builder, because the disk cache is keyed by this string and two callers
/// derive it: the row that has a slot, and the warm pass that does not. Ask for
/// a different size, or forget the GIF branch, and the warmed bytes land under a
/// name nothing looks up: the download happens twice and the row still waits. A
/// test could compare two spellings; sharing the function means there are not
/// two to compare.
fn feedImageUrl(buf: []u8, src: []const u8) []const u8 {
    return if (isGifUrl(src))
        mediaUrl(buf, src, gif_target_px, .animation)
    else
        mediaUrl(buf, src, media_target_px, .inside);
}

pub fn feedImageUrlForTest(buf: []u8, src: []const u8) []const u8 {
    return feedImageUrl(buf, src);
}

pub const feed_prefetch_rows_for_test = feed_prefetch_rows;
pub const gif_target_px_for_test = gif_target_px;
pub const media_target_px_for_test = media_target_px;

pub fn mediaUrlForTest(buf: []u8, src: []const u8, px: u32, fit: MediaFit) []const u8 {
    return mediaUrl(buf, src, px, fit);
}

/// The address warming asks for, so a test can hold it against the one the row
/// will look up. They are built in two places and must not drift.
pub fn setVisibleRangeForTest(first: usize, last: usize) void {
    g_visible_first = first;
    g_visible_last = last;
}

/// Whether the disk cache already holds this URL's bytes. Cheaper than loading
/// them: warming only needs to know whether to ask the network, and decoding is
/// the expensive half.
fn cachedImageExists(url: []const u8) bool {
    const io = g_io orelse return false;
    const environ = g_environ orelse return false;
    var dir = mediaCacheDir(io, environ) catch return false;
    defer dir.close(io);
    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, url);
    var file = dir.openFile(io, name, .{}) catch return false;
    file.close(io);
    return true;
}

fn storeCachedImage(url: []const u8, bytes: []const u8) void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = mediaCacheDir(io, environ) catch return;
    defer dir.close(io);

    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, url);
    dir.writeFile(io, .{
        .sub_path = name,
        .data = bytes,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch {};
}

/// The pixel size an image ended up registered at, so the view can lay it out
/// at its real aspect instead of stretching it into whatever box it is given.
const DecodedSize = struct { width: usize, height: usize };

/// Decodes `bytes` and registers the pixels under `id`, downscaling so the long
/// edge is at most `max_dim`. Returns the registered size, or null on failure.
fn decodeAndRegister(fx: *Effects, id: u64, bytes: []const u8, max_dim: u32) ?DecodedSize {
    // Fast path: let the platform decode and register directly. This succeeds
    // whenever the image already fits the registry's budget.
    if (fx.registerImageBytes(id, bytes)) |registered| {
        return .{ .width = registered.width, .height = registered.height };
    } else |_| {}

    var w: c_int = 0;
    var h: c_int = 0;
    var comp: c_int = 0;
    const pixels = stbi_load_from_memory(bytes.ptr, @intCast(bytes.len), &w, &h, &comp, 4) orelse return null;
    defer stbi_image_free(pixels);
    if (w <= 0 or h <= 0) return null;

    const src_w: usize = @intCast(w);
    const src_h: usize = @intCast(h);
    const longest = @max(src_w, src_h);
    if (longest <= max_dim) {
        // The platform refused it for some other reason; the decoded pixels
        // still fit, so register them as they are.
        fx.registerImage(id, src_w, src_h, pixels[0 .. src_w * src_h * 4]) catch return null;
        return .{ .width = src_w, .height = src_h };
    }

    const scale = @as(f64, @floatFromInt(max_dim)) / @as(f64, @floatFromInt(longest));
    const dst_w: usize = @max(1, @as(usize, @intFromFloat(@as(f64, @floatFromInt(src_w)) * scale)));
    const dst_h: usize = @max(1, @as(usize, @intFromFloat(@as(f64, @floatFromInt(src_h)) * scale)));

    const gpa = std.heap.page_allocator;
    const out = gpa.alloc(u8, dst_w * dst_h * 4) catch return null;
    defer gpa.free(out);
    if (stbir_resize_uint8_linear(pixels, w, h, 0, out.ptr, @intCast(dst_w), @intCast(dst_h), 0, stbir_rgba) == null) return null;
    fx.registerImage(id, dst_w, dst_h, out) catch return null;
    return .{ .width = dst_w, .height = dst_h };
}

// ---------------------------------------------------------------- feed media
//
// Feed images take the image ids the avatars do not, through a small LRU keyed
// by note. Only the top of the feed loads for now: that is what the budget
// holds and what is on screen at rest. Windowed visibility (load exactly what
// is in view, evict what leaves) arrives with the virtual list.

const MediaSlot = struct {
    used: bool = false,
    note_id: i64 = 0,
    image_id: u64 = 0,
    state: enum { idle, fetching, loaded, failed } = .idle,
    /// Fetches for this slot's URL that came back unusable for a reason worth
    /// retrying. Reset when the slot is handed to a different note, because
    /// `claimMediaSlot` rebuilds the whole struct.
    attempts: u8 = 0,
    /// Tick counter at the last time this note was still wanted, for eviction.
    last_used: u64 = 0,
    /// The registered pixel size, so the card can lay the picture out at its
    /// own aspect rather than stretching it.
    width: usize = 0,
    height: usize = 0,
    /// The resolved URL this image is fetched from, which is also its cache key.
    url_buf: [1024]u8 = [_]u8{0} ** 1024,
    url_len: u16 = 0,
    /// Every frame of an animated GIF, decoded once and owned by stb (freed on
    /// eviction). Null for a still picture.
    frames: ?[*]u8 = null,
    frame_count: u16 = 0,
    frame_index: u16 = 0,
    /// Milliseconds this GIF holds each frame, and how much of that has elapsed.
    frame_delay_ms: u32 = 100,
    elapsed_ms: u32 = 0,

    fn url(self: *const MediaSlot) []const u8 {
        return self.url_buf[0..self.url_len];
    }
    fn animated(self: *const MediaSlot) bool {
        return self.frames != null and self.frame_count > 1;
    }
    /// Releases the decoded frames, if any. Called before a slot is reused.
    fn releaseFrames(self: *MediaSlot) void {
        if (self.frames) |px| stbi_image_free(px);
        self.frames = null;
        self.frame_count = 0;
        self.frame_index = 0;
    }
};

var g_media = [_]MediaSlot{.{}} ** max_media_images;
var g_media_clock: u64 = 0;

// The rows the windowed list last put on screen. Written by the view (which is
// where the runtime resolves the window) and read by the fetch pass in
// `update`, so the image budget follows the reader exactly.
var g_visible_first: usize = 0;
var g_visible_last: usize = 0;

// What shape each note's picture turned out to be, remembered per note id and
// OUTLIVING both the media slot and the note itself. A slot is evicted as soon
// as the note scrolls out of the window; without this the card would forget how
// tall its picture was, shrink, and shift the feed under the reader, then shift
// it back on the way up. Notes whose `imeta` declared a size never need it.
const aspect_memory_cap = 128;
const AspectEntry = struct { note_id: i64 = 0, aspect: f32 = 0 };
var g_aspects = [_]AspectEntry{.{}} ** aspect_memory_cap;
var g_aspect_next: usize = 0;

/// Records the shape of `note_id`'s picture.
fn rememberAspect(note_id: i64, width: usize, height: usize) void {
    if (width == 0 or height == 0) return;
    const aspect = @as(f32, @floatFromInt(height)) / @as(f32, @floatFromInt(width));
    for (&g_aspects) |*entry| {
        if (entry.note_id == note_id) {
            entry.aspect = aspect;
            return;
        }
    }
    g_aspects[g_aspect_next] = .{ .note_id = note_id, .aspect = aspect };
    g_aspect_next = (g_aspect_next + 1) % aspect_memory_cap;
}

/// The remembered shape of `note_id`'s picture, if it has been seen.
fn recalledAspect(note_id: i64) ?f32 {
    for (&g_aspects) |entry| {
        if (entry.note_id == note_id and entry.aspect > 0) return entry.aspect;
    }
    return null;
}

/// Clears the media cache. For tests, which share the process globals.
/// Whether the slot for `note_id` was marked wanted by the most recent pass.
/// This is the thing the claim pass reads to decide what it may evict, so it is
/// the thing a test about "which pictures the level is spending its slots on"
/// has to ask about.
pub fn mediaSlotWantedForTest(note_id: i64) ?bool {
    const m = mediaSlotFor(note_id) orelse return null;
    return m.last_used == g_media_clock;
}

pub fn scanMediaFetchesForTest(fx: *Effects, model: *const Model) void {
    scanMediaFetches(fx, model);
}

/// Pretends a build put exactly these notes on screen in the front level.
pub fn recordVisibleNotesForTest(ids: []const i64) void {
    const set = &g_level_visible[0];
    set.reset();
    g_visible_level = 0;
    for (ids) |id| set.pushNote(id);
}

/// How many picture slots are currently held, and by which notes.
pub fn mediaSlotNoteIdsForTest(out: []i64) usize {
    var n: usize = 0;
    for (&g_media) |*m| {
        if (!m.used or n == out.len) continue;
        out[n] = m.note_id;
        n += 1;
    }
    return n;
}

pub fn maxMediaImagesForTest() usize {
    return max_media_images;
}

pub fn resetMediaForTest() void {
    g_media = [_]MediaSlot{.{}} ** max_media_images;
    g_media_clock = 0;
}

/// The slot holding `note_id`'s image, if any.
fn mediaSlotFor(note_id: i64) ?*MediaSlot {
    for (&g_media) |*m| {
        if (m.used and m.note_id == note_id) return m;
    }
    return null;
}

/// The slot for `note_id`, claiming a free one or evicting the least recently
/// wanted. Never evicts a slot whose note is still on screen (touched this
/// pass), and never one with a fetch in flight: when more pictures are visible
/// than there are slots, the extras hold their reserved space rather than
/// stealing each other's slot back and forth, which decoded images on the UI
/// thread every pass and made a tall window feel heavy.
/// Whether this note's picture was asked for and could not be had.
pub fn mediaFailed(note_id: i64) bool {
    const m = mediaSlotFor(note_id) orelse return false;
    return m.state == .failed;
}

pub fn markMediaFailedForTest(slot: *MediaSlot) void {
    slot.state = .failed;
}

pub fn mediaAttemptsForTest(note_id: i64) ?u8 {
    const m = mediaSlotFor(note_id) orelse return null;
    return m.attempts;
}

pub fn mediaIdleForTest(note_id: i64) bool {
    const m = mediaSlotFor(note_id) orelse return false;
    return m.state == .idle;
}

/// Delivers one picture-fetch response for `note_id` the way the runtime would,
/// so a test can drive the failure paths rather than the classifier alone.
pub fn deliverMediaResponseForTest(
    fx: *Effects,
    note_id: i64,
    outcome: native_sdk.EffectFetchOutcome,
    status: u16,
    body: []const u8,
) void {
    const m = mediaSlotFor(note_id) orelse return;
    handleMediaFetched(fx, .{
        .key = media_fetch_key_base + (m.image_id - media_image_id_base),
        .outcome = outcome,
        .status = status,
        .body = body,
    });
}

pub fn claimMediaSlotForTest(fx: *Effects, note_id: i64) ?*MediaSlot {
    return claimMediaSlot(fx, note_id);
}

pub fn touchMediaClockForTest() u64 {
    g_media_clock += 1;
    return g_media_clock;
}

fn claimMediaSlot(fx: *Effects, note_id: i64) ?*MediaSlot {
    if (mediaSlotFor(note_id)) |m| return m;
    for (&g_media, 0..) |*m, i| {
        if (!m.used) {
            m.* = .{ .used = true, .note_id = note_id, .image_id = media_image_id_base + i };
            return m;
        }
    }
    var victim: ?*MediaSlot = null;
    for (&g_media) |*m| {
        if (m.state == .fetching) continue;
        if (m.last_used == g_media_clock) continue; // still wanted on screen
        if (victim == null or m.last_used < victim.?.last_used) victim = m;
    }
    const v = victim orelse return null;
    const id = v.image_id;
    // Free the registry slot and any decoded frames before reusing the id.
    _ = fx.unregisterImage(id);
    v.releaseFrames();
    v.* = .{ .used = true, .note_id = note_id, .image_id = id };
    return v;
}

/// Decodes every frame of an animated GIF into `slot` and registers the first,
/// so the shared animation timer can cycle it. Returns false for a still image
/// (including a single-frame GIF), leaving the normal still path to handle it.
fn loadAnimatedGif(fx: *Effects, slot: *MediaSlot, bytes: []const u8) bool {
    if (bytes.len < 3 or !std.mem.eql(u8, bytes[0..3], "GIF")) return false;

    var delays: ?[*]c_int = null;
    var w: c_int = 0;
    var h: c_int = 0;
    var count: c_int = 0;
    var comp: c_int = 0;
    const pixels = stbi_load_gif_from_memory(bytes.ptr, @intCast(bytes.len), &delays, &w, &h, &count, &comp, 4) orelse return false;
    if (count <= 1 or w <= 0 or h <= 0) {
        stbi_image_free(pixels);
        return false;
    }

    const frame_w: usize = @intCast(w);
    const frame_h: usize = @intCast(h);
    const frame_bytes = frame_w * frame_h * 4;
    const frames: usize = @intCast(count);
    // stb decodes every frame up front, so a long or large GIF is the real
    // memory hazard rather than the per-frame cost. Refuse the extremes and let
    // the caller fall back to a still first frame.
    if (frame_bytes > max_registered_image_bytes or frames > max_gif_frames or frame_bytes * frames > max_gif_total_bytes) {
        stbi_image_free(pixels);
        return false;
    }

    fx.registerImage(slot.image_id, frame_w, frame_h, pixels[0..frame_bytes]) catch {
        stbi_image_free(pixels);
        return false;
    };

    slot.releaseFrames();
    slot.frames = pixels;
    slot.frame_count = @intCast(frames);
    slot.frame_index = 0;
    slot.elapsed_ms = 0;
    // GIF delays are centiseconds x10; anything implausibly fast gets the
    // browsers' customary floor.
    slot.frame_delay_ms = if (delays) |d| (if (d[0] >= 20) @intCast(d[0]) else 100) else 100;
    slot.width = frame_w;
    slot.height = frame_h;
    slot.state = .loaded;
    rememberAspect(slot.note_id, frame_w, frame_h);
    return true;
}

/// Registers a feed picture from the on-disk cache, animating it if it is a GIF.
/// Returns whether the slot is now loaded.
fn loadCachedMedia(fx: *Effects, slot: *MediaSlot, gif: bool) bool {
    const io = g_io orelse return false;
    const environ = g_environ orelse return false;
    var dir = mediaCacheDir(io, environ) catch return false;
    defer dir.close(io);

    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, slot.url());
    const gpa = std.heap.page_allocator;
    const bytes = dir.readFileAlloc(io, name, gpa, std.Io.Limit.limited(max_image_bytes)) catch return false;
    defer gpa.free(bytes);

    if (gif and loadAnimatedGif(fx, slot, bytes)) return true;
    if (decodeAndRegister(fx, slot.image_id, bytes, media_target_px)) |size| {
        slot.state = .loaded;
        slot.width = size.width;
        slot.height = size.height;
        rememberAspect(slot.note_id, size.width, size.height);
        return true;
    }
    return false;
}

/// Advances the animated pictures currently in view, one shared timer for all of
/// them (a timer each would exhaust the 16-slot timer table). Only a couple play
/// at once: the rest hold their first frame until they scroll into that budget.
fn advanceAnimations(fx: *Effects, model: *const Model) void {
    const window = model.visibleRange();
    var playing: usize = 0;
    for (&g_media) |*slot| {
        if (!slot.used or !slot.animated() or slot.state != .loaded) continue;
        // In view? The note has to still be one of the ones on screen.
        var visible = false;
        var index = window.first;
        while (index <= window.last and index < model.notes_len) : (index += 1) {
            if (model.notes[index].id == slot.note_id) {
                visible = true;
                break;
            }
        }
        if (!visible) continue;
        if (playing >= max_playing_gifs) break;
        playing += 1;

        slot.elapsed_ms += animation_interval_ms;
        if (slot.elapsed_ms < slot.frame_delay_ms) continue;
        slot.elapsed_ms = 0;
        slot.frame_index = (slot.frame_index + 1) % slot.frame_count;

        const frames = slot.frames orelse continue;
        const frame_bytes = slot.width * slot.height * 4;
        const offset = @as(usize, slot.frame_index) * frame_bytes;
        // Re-registering the same id swaps the pixels everywhere it is drawn.
        fx.registerImage(slot.image_id, slot.width, slot.height, frames[offset..][0..frame_bytes]) catch {};
    }
}

/// Loads the pictures for the notes around the viewport: the cached ones
/// straight from disk, the rest over the network a few per tick. Notes outside
/// the window keep their slot only until something on screen needs it. While a
/// thread is open the feed under it is hidden, so the budget goes to the thread's
/// pictures instead (the feed's reload from the disk cache when it returns).
fn scanMediaFetches(fx: *Effects, model: *const Model) void {
    const per_tick = 6;
    var fired: usize = 0;
    g_media_clock += 1;

    if (model.viewing_profile != null or model.viewing_thread != 0) {
        // A level occludes the feed, so the picture budget goes to the level,
        // and only to the rows ON SCREEN in it. Marking every note in the level
        // wanted meant the first six pictures held all six slots and nothing
        // else could ever be lent one: the claim pass refuses to evict anything
        // wanted this pass, and everything was. Every other picture in a long
        // thread stayed an empty box for as long as the thread was open.
        //
        // Mark, then fetch, as the feed does: marking first means the claim pass
        // can only evict what has scrolled away, never a picture needed later in
        // this same pass.
        const set = &g_level_visible[@min(g_visible_level, g_level_visible.len - 1)];
        for (set.notes[0..set.note_count]) |id| markMediaWanted(id);
        for (set.notes[0..set.note_count]) |id| {
            if (model.noteById(id)) |note| fireMedia(fx, note, &fired, per_tick);
        }
        return;
    }

    const window = model.visibleRange();

    // First mark every slot whose note is on screen as wanted, so the claim
    // pass below can only ever evict pictures that have scrolled away. Without
    // this, a viewport showing more pictures than there are slots would evict
    // a slot needed later in this very pass, endlessly.
    var touch = window.first;
    while (touch <= window.last and touch < model.notes_len) : (touch += 1) {
        markMediaWanted(model.notes[touch].id);
    }

    var index = window.first;
    while (index <= window.last and index < model.notes_len) : (index += 1) {
        fireMedia(fx, &model.notes[index], &fired, per_tick);
    }
}

/// Marks the picture slot for `note_id` wanted this pass (if it has one), so the
/// claim pass does not evict a picture still on screen.
fn markMediaWanted(note_id: i64) void {
    if (mediaSlotFor(note_id)) |m| m.last_used = g_media_clock;
}

/// Loads one note's picture: claims a slot, serves it from the disk cache, or
/// fetches it over the network (up to `per_tick` fetches a pass). A note with no
/// picture, or one whose slot is already loading or done, is a no-op.
fn fireMedia(fx: *Effects, note: *const Note, fired: *usize, per_tick: usize) void {
    if (!note.hasImage()) return;
    // With previews off, nothing leaves the machine until the reader asks for
    // this one picture. That is the point of the setting: not bandwidth, but
    // that reading a feed should not tell every host in it that you did.
    if (!g_media_previews and !isMediaAsked(note.id)) return;
    const slot = claimMediaSlot(fx, note.id) orelse return;
    slot.last_used = g_media_clock;
    if (slot.state != .idle) return;

    var url_buf: [1024]u8 = undefined;
    const gif = isGifUrl(note.imageUrl());
    const url = feedImageUrl(&url_buf, note.imageUrl());
    const n = @min(url.len, slot.url_buf.len);
    @memcpy(slot.url_buf[0..n], url[0..n]);
    slot.url_len = @intCast(n);

    // Local-first: a picture we already have appears with the note, with no
    // network round-trip at all.
    if (loadCachedMedia(fx, slot, gif)) return;
    if (fired.* >= per_tick) return;
    slot.state = .fetching;
    fx.fetch(.{
        .key = media_fetch_key_base + (slot.image_id - media_image_id_base),
        .url = slot.url(),
        .on_response = Effects.responseMsg(.media_fetched),
    });
    fired.* += 1;
}

/// What a fetch that produced no usable image says about trying again.
pub const ImageFailure = enum { retry, give_up };

/// Classifies a picture or avatar fetch that did not produce an image.
///
/// The question is not what the status code was, it is WHAT FAILED. A body that
/// arrived whole, with a 200, and is simply too large for the decoder, or was
/// truncated, or is empty, is a fact about that picture: it will be exactly as
/// large the next time, and every time after that. A timeout, a 5xx or a rate
/// limit is the network or the host having a moment, and those recover.
///
/// Reading only the status conflated the two, in opposite directions on the two
/// paths. The feed asked whether the STATUS was final, and an oversized picture
/// comes back 200, so the slot went back to idle and the same picture was
/// downloaded again on the next tick and again on every scroll event, for as
/// long as the note stayed on screen. The avatar path asked nothing at all, so a
/// single 503 or one dropped connection blanked that face for the rest of the
/// session, on every screen.
pub fn classifyImageFailure(outcome: native_sdk.EffectFetchOutcome, status: u16) ImageFailure {
    // Never reached a host, or the request was cut short on the way.
    if (outcome != .ok) return .retry;
    // The host answered, and the answer was not an image and will not become
    // one: too large to decode, cut off, or empty.
    if (status == 200) return .give_up;
    // The two 4xx that are about timing rather than about the resource.
    if (status == 408 or status == 429) return .retry;
    // Any other 4xx is the host saying no, and it will say no again.
    if (status >= 400 and status < 500) return .give_up;
    // 5xx, and anything unexpected: the host is having a moment.
    return .retry;
}

/// How many times a picture or avatar may come back unusable for a reason worth
/// retrying before Plaza stops asking.
///
/// A backstop, not the mechanism. `classifyImageFailure` is what should decide,
/// and this is here so that no future mistake in it can produce an unbounded
/// download loop again: getting that wrong cost 240 KiB a second, per picture,
/// for as long as the reader looked at it.
const max_image_attempts = 4;

/// Handles a feed-image fetch response, mirroring the avatar path.
fn handleMediaFetched(fx: *Effects, response: native_sdk.EffectResponse) void {
    if (response.key < media_fetch_key_base) return;
    const index = response.key - media_fetch_key_base;
    if (index >= g_media.len) return;
    const slot = &g_media[@intCast(index)];
    if (!slot.used) return;

    if (response.outcome == .rejected) {
        slot.state = .idle;
        return;
    }
    if (response.outcome != .ok or response.status != 200 or response.truncated or response.body.len == 0 or response.body.len > max_image_bytes) {
        // A host that said NO is different from a host that did not answer, and
        // a picture that is simply too big is different again: it will be the
        // same size next time, so asking again is a download with a known
        // answer. Only something that can change goes back to idle.
        slot.state = switch (classifyImageFailure(response.outcome, response.status)) {
            .give_up => .failed,
            .retry => blk: {
                slot.attempts +|= 1;
                break :blk if (slot.attempts >= max_image_attempts) .failed else .idle;
            },
        };
        return;
    }
    // Whatever it took to get here, this URL answers, so the count of tries
    // worth making starts again.
    slot.attempts = 0;
    // An animated GIF keeps all its frames; anything else (including a GIF with
    // only one frame) takes the still path.
    if (loadAnimatedGif(fx, slot, response.body)) {
        storeCachedImage(slot.url(), response.body);
        return;
    }
    if (decodeAndRegister(fx, slot.image_id, response.body, media_target_px)) |size| {
        slot.state = .loaded;
        slot.width = size.width;
        slot.height = size.height;
        rememberAspect(slot.note_id, size.width, size.height);
        // Keep it for next launch: the feed should come back with its pictures.
        storeCachedImage(slot.url(), response.body);
    } else {
        slot.state = .failed;
    }
}

// A pressed link is handed to the OS opener. The URL comes from note content,
// which is untrusted, so it is validated before it ever becomes an argument: it
// must be a plain http(s) URL with no whitespace or control bytes. There is no
// shell involved (argv is passed as a vector), and a leading scheme means the
// opener can never read it as a flag or a local path.
var g_open_url_buf: [1024]u8 = undefined;

/// Whether `url` is safe to hand to the system opener.
pub fn isSafeExternalUrl(url: []const u8) bool {
    if (!std.mem.startsWith(u8, url, "https://") and !std.mem.startsWith(u8, url, "http://")) return false;
    if (url.len > g_open_url_buf.len) return false;
    for (url) |c| {
        if (c <= 0x20 or c == 0x7f) return false;
    }
    return true;
}

/// Opens `url` in the user's browser, if it passes validation.
fn openExternally(fx: *Effects, url: []const u8) void {
    if (!isSafeExternalUrl(url)) return;
    // The link slice lives in the view arena, so copy it before the effect runs.
    @memcpy(g_open_url_buf[0..url.len], url);
    const owned = g_open_url_buf[0..url.len];
    fx.spawn(.{ .key = open_url_key, .argv = &.{ "/usr/bin/open", owned }, .output = .collect });
}

/// Lets everything that failed to load try again, after the media proxy changed.
fn retryFailedImages() void {
    for (&g_profiles) |*p| {
        if (p.used and p.avatar_state == .failed) {
            p.avatar_state = .idle;
            p.avatar_attempts = 0;
        }
    }
    for (&g_media) |*m| {
        if (m.used and m.state == .failed) {
            m.state = .idle;
            m.attempts = 0;
        }
    }
}

/// Builds a `Note` view-model from a stored event.
pub fn noteFrom(ev: nostr.event.Event, now_s: i64) Note {
    var note = Note{
        .created_at = ev.created_at,
        .pubkey = ev.pubkey,
        .id = noteIdOf(ev),
        .event_id = ev.id,
    };

    // Avatar initials fallback: the first pubkey byte as two hex digits, stable
    // and distinct per author, shown until an avatar image loads.
    const hexdigits = "0123456789abcdef";
    note.initials_buf = .{ hexdigits[ev.pubkey[0] >> 4], hexdigits[ev.pubkey[0] & 0x0f] };

    setAuthor(&note, ev.pubkey);

    if (clientOf(ev)) |name| {
        const n = @min(name.len, note.client_buf.len);
        @memcpy(note.client_buf[0..n], name[0..n]);
        note.client_len = @intCast(n);
    }

    // An image link becomes a picture, so lift it out of the text and omit it
    // from the rendered content rather than showing a bare URL beside it.
    var image_url: []const u8 = "";
    if (firstImageUrl(ev.content)) |url| {
        if (url.len <= note.image_url_buf.len) {
            @memcpy(note.image_url_buf[0..url.len], url);
            note.image_url_len = @intCast(url.len);
            image_url = note.imageUrl();
            const meta = imetaFor(ev.tags, url);
            note.image_aspect = meta.aspect();
            note.image_w = meta.width;
            note.image_h = meta.height;
            note.image_bytes = meta.size;
            const blur_len = @min(meta.blurhash.len, note.image_blur_buf.len);
            @memcpy(note.image_blur_buf[0..blur_len], meta.blurhash[0..blur_len]);
            note.image_blur_len = @intCast(blur_len);
            note.image_has_alt = meta.alt.len > 0;
        }
    }

    // Content: `nostr:` mentions rewritten to @name (or a short @npub), copied
    // whole-codepoint so a split multi-byte sequence never reaches the shaper.
    note.content_len = @intCast(renderContent(&note.content_buf, ev.content, image_url));

    // The first plain link, for the preview card. Read from the ORIGINAL content:
    // the rendered copy has mentions rewritten and may be capped.
    if (firstLinkUrl(ev.content, image_url)) |link| {
        if (link.len <= note.link_url_buf.len) {
            @memcpy(note.link_url_buf[0..link.len], link);
            note.link_url_len = @intCast(link.len);
        }
    }

    // The first quoted event (nevent/note), decoded once into a byte span the
    // body splits on, and queued for resolving.
    findQuoteRef(&note);
    if (note.quote.kind == .event) wantQuote(note.quote.id);

    // Which note this one answers, for thread nesting.
    if (nip10Parent(ev.tags)) |parent_id| {
        note.reply_parent = parent_id;
        note.has_reply_parent = true;
    }

    note.setTime(now_s);
    return note;
}

/// The NIP-10 parent of a reply: the `e` tag marked `reply` wins; with only a
/// `root` marker the note answers the root directly; with no markers at all the
/// LAST `e` tag is the parent (the deprecated positional convention, still
/// common in the wild). `mention` tags never make a note a reply; a quote is
/// not an answer. Null for a note that answers nothing.
pub fn nip10Parent(tags: []const nostr.event.Tag) ?[32]u8 {
    var reply: ?[32]u8 = null;
    var root: ?[32]u8 = null;
    var last_plain: ?[32]u8 = null;
    for (tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "e")) continue;
        if (tag[1].len != 64) continue;
        var id: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&id, tag[1]) catch continue;
        const marker = if (tag.len >= 4) tag[3] else "";
        if (std.mem.eql(u8, marker, "reply")) {
            reply = id;
        } else if (std.mem.eql(u8, marker, "root")) {
            root = id;
        } else if (std.mem.eql(u8, marker, "mention")) {
            // A quoted note, not an ancestor.
        } else {
            last_plain = id;
        }
    }
    return reply orelse root orelse last_plain;
}

/// Orders a fetched reply set into conversation order (each reply directly
/// under the note it answers, siblings oldest-first) and stamps every note's
/// nesting depth (1 = a direct reply to the root). Expects `notes` already
/// sorted oldest-first, which is what makes sibling order chronological.
///
/// A reply whose parent is the root, or which answers nothing, sits at the top
/// level in its chronological place.
///
/// A reply whose parent IS named but is not in the set (past the fetch cap,
/// never seen, or gone from every relay) also sits there, because there is
/// nowhere better to put it, but it is marked `parent_missing` so the row can
/// say so. Drawing it as an ordinary first-level reply asserted that it answered
/// the opening note, which is a claim about the conversation that nothing
/// supports: the note says which event it answers and that event is simply not
/// here.
///
/// A parent cycle (malformed events) cannot loop: the visited set admits each
/// note once, and whatever a cycle strands is appended at the top level.
pub fn arrangeThread(notes: []Note, root_event_id: [32]u8) void {
    const n = notes.len;
    if (n < 2) {
        if (n == 1) notes[0].depth = 1;
        return;
    }
    std.debug.assert(n <= thread_reply_cap);
    // Each note's parent INDEX within the set, or `n` for "top level". The
    // scan is O(n^2) over 32-byte compares, which at the 100-reply cap is
    // trivia next to the store query that produced the set.
    var parent: [thread_reply_cap]u16 = undefined;
    for (notes[0..n], 0..) |*note, i| {
        parent[i] = @intCast(n);
        note.parent_missing = false;
        if (!note.has_reply_parent) continue;
        if (std.mem.eql(u8, &note.reply_parent, &root_event_id)) continue;
        var found = false;
        for (notes[0..n], 0..) |*cand, j| {
            if (i != j and std.mem.eql(u8, &cand.event_id, &note.reply_parent)) {
                parent[i] = @intCast(j);
                found = true;
                break;
            }
        }
        // Named a parent, and it is not here. Still top level, but no longer
        // pretending that is where it belongs.
        note.parent_missing = !found;
    }
    // The DFS emits a PERMUTATION (conversation order over current indices),
    // so ordering is one O(n) gather through the scratch below, never a sort,
    // which would move the ~1.5KB Note structs O(n log n) times for an order
    // the walk already knows.
    var visited = [_]bool{false} ** thread_reply_cap;
    var order: [thread_reply_cap]u16 = undefined;
    var count: usize = 0;
    const Dfs = struct {
        notes: []Note,
        parent: []const u16,
        visited: []bool,
        order: []u16,
        count: *usize,
        fn visit(self: *const @This(), i: usize, depth: u8) void {
            if (self.visited[i]) return;
            self.visited[i] = true;
            self.notes[i].depth = depth;
            self.order[self.count.*] = @intCast(i);
            self.count.* += 1;
            for (self.parent, 0..) |p, j| {
                if (p == i) self.visit(j, depth +| 1);
            }
        }
    };
    const dfs = Dfs{ .notes = notes, .parent = parent[0..n], .visited = visited[0..n], .order = order[0..n], .count = &count };
    for (0..n) |i| {
        if (parent[i] == n) dfs.visit(i, 1);
    }
    // A cycle's strands: no member ever reached the top level, so seat them
    // there, still oldest-first.
    for (0..n) |i| {
        if (!visited[i]) {
            notes[i].depth = 1;
            order[count] = @intCast(i);
            count += 1;
        }
    }
    for (order[0..n], 0..) |src, dst| g_arrange_scratch[dst] = notes[src];
    @memcpy(notes[0..n], g_arrange_scratch[0..n]);
}

// The gather scratch for `arrangeThread`'s permutation apply. File-scope (not
// stack: ~150KB of Note at the cap) and safe unsynchronized because every
// caller runs on the UI thread: refreshThreadNotes from `update`, and
// threadRepliesFromStore from the view build.
var g_arrange_scratch: [thread_reply_cap]Note = undefined;

/// The thread root the tags declare: the `e` tag marked `root`, or the FIRST
/// non-mention `e` tag in the positional form (NIP-10's deprecated scheme puts
/// the root first and the immediate parent last). Null when the note answers
/// nothing, which is what a root's own tags look like.
///
/// Used to name what a gap in the ancestor chain is: a missing id that IS this
/// root is the thread's opening note, and the ghost row says so.
pub fn nip10Root(tags: []const nostr.event.Tag) ?[32]u8 {
    var first_plain: ?[32]u8 = null;
    for (tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "e")) continue;
        if (tag[1].len != 64) continue;
        var id: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&id, tag[1]) catch continue;
        const marker = if (tag.len >= 4) tag[3] else "";
        if (std.mem.eql(u8, marker, "root")) return id;
        if (std.mem.eql(u8, marker, "mention") or std.mem.eql(u8, marker, "reply")) continue;
        if (first_plain == null) first_plain = id;
    }
    return first_plain;
}

/// The event ids a thread subscription should name: the note the reader
/// pressed, and the root of the conversation it belongs to when that is a
/// different note. Fills `out` and returns how many are in it.
///
/// Both, not just the root, and not just the note. The root is what the rest of
/// the conversation actually tags, and the pressed note is what keeps this
/// working when a root tag is missing, wrong, or points at something else: its
/// own direct children still match.
pub fn threadQueryIds(focal: [32]u8, tags: []const nostr.event.Tag, out: *[2][32]u8) usize {
    out[0] = focal;
    const root = nip10Root(tags) orelse return 1;
    // A note that names itself as its own root is one id, not two.
    if (std.mem.eql(u8, &root, &focal)) return 1;
    out[1] = root;
    return 2;
}

/// Whether the tags carry a NON-mention `e` reference to `id`: a root, reply,
/// or positional ancestor pointer. A mention-marked tag is a quote, not an
/// ancestor tie.
pub fn nip10References(tags: []const nostr.event.Tag, id: [32]u8) bool {
    for (tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "e")) continue;
        if (tag[1].len != 64) continue;
        var tid: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&tid, tag[1]) catch continue;
        if (!std.mem.eql(u8, &tid, &id)) continue;
        const marker = if (tag.len >= 4) tag[3] else "";
        if (!std.mem.eql(u8, marker, "mention")) return true;
    }
    return false;
}

// How many candidates one walk round asks the store for: a multiple of the
// display cap, so the events the gates reject (quotes, foreign repliers,
// cross-round duplicates) do not consume the window genuine replies needed.
// The store answers newest-first, so a round referenced by MORE events than
// this can still cut old ones; the pool just makes that take four hundred
// referers in one round rather than one hundred.
const thread_walk_limit = thread_reply_cap * 4;

/// Collects the ids of every store-resident reply in `root_event_id`'s thread:
/// a breadth-first walk of the `#e` graph out from the root. The walk is what
/// makes SUB-threads whole: a NIP-10 reply tags only the true thread root and
/// its direct parent, so a single `#e = sub-root` query returns just the
/// direct children of a mid-thread note while its deeper descendants (already
/// ingested by the top level's fetch) go unseen.
///
/// Membership is CONNECTIVITY, not co-mention: a candidate joins only when the
/// note it answers (`nip10Parent`) is the level root or already a member, or
/// when it carries a non-mention `e` reference to the level root itself, which
/// keeps a reply whose interior parent never reached the store visible as a
/// top-level row instead of vanishing. A mere `nip10Parent != null` would
/// admit a foreign thread's reply that only QUOTES ours, and then import that
/// thread's whole subtree through the next round's frontier.
///
/// The breadth-first order collects parents in an earlier round than their
/// children, so overflowing the display cap drops subtree tails rather than
/// interior parents. Within one round the store's newest-first `limit` can
/// still cut old referers (see `thread_walk_limit`).
pub fn collectThreadIds(store: *nostr.store.Store, root_event_id: [32]u8, out: *[thread_reply_cap][32]u8) usize {
    // Hex forms of the frontier ids, referenced by the query's tag filter:
    // slot 0 is the root, slot 1+i mirrors out[i].
    var hexes: [thread_reply_cap + 1][64]u8 = undefined;
    var values: [thread_reply_cap][]const u8 = undefined;
    hexLower(&hexes[0], root_event_id);
    var count: usize = 0;
    var frontier_start: usize = 0;
    var first_round = true;
    while (count < out.len) {
        var nvals: usize = 0;
        if (first_round) {
            values[0] = &hexes[0];
            nvals = 1;
        } else {
            for (frontier_start..count) |i| {
                hexLower(&hexes[1 + i], out[i]);
                values[nvals] = &hexes[1 + i];
                nvals += 1;
            }
        }
        if (nvals == 0) break;
        const round_start = count;
        // A tags-ONLY filter: with a kind in the filter the store's index
        // ladder prefers the kind index and streams every kind:1 ever stored,
        // post-filtering on the tag, which is the whole feed history, per round. The
        // tag index streams just the frontier's referers; the kind gate is
        // cheap and ours.
        const tag_filters = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = values[0..nvals] }};
        var result = store.query(std.heap.page_allocator, .{ .tags = &tag_filters, .limit = thread_walk_limit }) catch break;
        defer result.deinit();
        // Round-local fixpoint, admitting OLDEST first (the store answers
        // newest-first): a parent is older than its children, so oldest-first
        // usually connects everything in one pass, and overflowing the cap
        // keeps the conversation's beginning (the parents everything hangs
        // from) rather than its newest tail. Whatever stays unconnected
        // after the fixpoint does not belong to this thread.
        while (count < out.len) {
            var admitted = false;
            var idx: usize = result.events.len;
            while (idx > 0) {
                idx -= 1;
                const ev = result.events[idx];
                if (count >= out.len) break;
                if (ev.kind != 1) continue;
                if (std.mem.eql(u8, &ev.id, &root_event_id)) continue;
                const parent = nip10Parent(ev.tags) orelse continue;
                var connected = std.mem.eql(u8, &parent, &root_event_id) or nip10References(ev.tags, root_event_id);
                if (!connected) {
                    for (out[0..count]) |*member| {
                        if (std.mem.eql(u8, member, &parent)) {
                            connected = true;
                            break;
                        }
                    }
                }
                if (!connected) continue;
                var dup = false;
                for (out[0..count]) |*seen| {
                    if (std.mem.eql(u8, seen, &ev.id)) {
                        dup = true;
                        break;
                    }
                }
                if (dup) continue;
                out[count] = ev.id;
                count += 1;
                admitted = true;
            }
            if (!admitted) break;
        }
        // The next frontier is exactly this round's finds; none means the
        // closure is complete.
        if (count == round_start) break;
        frontier_start = round_start;
        first_round = false;
    }
    return count;
}

/// One ancestor level's collected reply ids, stamped with the store's event
/// count, so the per-frame render of an OCCLUDED level re-walks the `#e`
/// closure only when the store actually grew, not every frame. UI-thread
/// only, like the arrange scratch above.
const LevelReplies = struct {
    root: [32]u8 = [_]u8{0} ** 32,
    stamp: usize = std.math.maxInt(usize),
    ids: [thread_reply_cap][32]u8 = undefined,
    len: usize = 0,
};
var g_level_replies: [thread_depth_max]LevelReplies = [_]LevelReplies{.{}} ** thread_depth_max;

/// How far up the chain above the focal note is drawn. A thread can be
/// arbitrarily deep, and the walk costs a point read per step, so the chain
/// stops here and SAYS that it stopped (see `AncestorGap.capped`): clicking the
/// topmost ancestor focuses it, and its own chain continues from there.
const thread_ancestor_max = 8;

/// Why the chain above the focal note stops where it does.
pub const AncestorGap = enum {
    /// It does not: the chain reaches the thread's opening note.
    none,
    /// The next note up is not in the store yet. The subscription is out for it.
    missing,
    /// The chain is deeper than `thread_ancestor_max`, so the rest is above what
    /// is drawn.
    capped,
};

/// One ancestor level's chain above the focal note, stamped with the store's
/// event count so the walk (a point read per step) runs when the store grows
/// rather than every frame. UI-thread only, like the reply caches above.
const AncestorChain = struct {
    focal: [32]u8 = [_]u8{0} ** 32,
    stamp: usize = std.math.maxInt(usize),
    /// Oldest first, which is the order they are drawn in.
    ids: [thread_ancestor_max][32]u8 = undefined,
    /// How many body lines each of those notes draws, cached with the walk so an
    /// OCCLUDED level can price its rows without building a single Note. That is
    /// the only thing such a level needs from the chain, and reading eight events
    /// per level per frame to learn it was most of the cost the walk cache set
    /// out to remove.
    lines: [thread_ancestor_max]u8 = [_]u8{0} ** thread_ancestor_max,
    len: usize = 0,
    gap: AncestorGap = .none,
    /// Whether the id the chain stops below is the thread's declared root, which
    /// is the difference between "root note not here yet" and "the note this
    /// answers is not here yet".
    gap_is_root: bool = false,
};
/// One per mounted level: the back-stack plus the open thread.
var g_ancestor_chains: [thread_depth_max + 1]AncestorChain = [_]AncestorChain{.{}} ** (thread_depth_max + 1);

/// Walks from `focal` up its NIP-10 reply chain, collecting the ancestors that
/// are in the store (oldest first) and recording why the walk stopped. Cheap on
/// a repeat call: the result is cached until the store grows or the focal note
/// changes.
fn refreshAncestorChain(chain: *AncestorChain, store: *nostr.store.Store, focal: *const Note, stamp: usize) void {
    chain.* = .{ .focal = focal.event_id, .stamp = stamp };
    if (!focal.has_reply_parent) return;

    // The root the focal note itself declares, so a gap can be named. Read from
    // the store rather than carried on the Note: only this row needs it.
    var declared_root: ?[32]u8 = null;
    if (store.getEvent(std.heap.page_allocator, focal.event_id) catch null) |se| {
        var owned = se;
        defer owned.deinit();
        declared_root = nip10Root(owned.event.tags);
    }

    // Newest first while walking, reversed into the cache at the end.
    var up: [thread_ancestor_max][32]u8 = undefined;
    var up_lines: [thread_ancestor_max]u8 = undefined;
    var n: usize = 0;
    const now = nowSeconds();
    var want = focal.reply_parent;
    // A note that tags ITSELF as its parent would otherwise be walked as its own
    // ancestor and drawn twice in one list, under the same row key.
    if (std.mem.eql(u8, &want, &focal.event_id)) return;
    while (true) {
        if (n == thread_ancestor_max) {
            chain.gap = .capped;
            break;
        }
        var se = (store.getEvent(std.heap.page_allocator, want) catch null) orelse {
            chain.gap = .missing;
            // The ghost row says the relays are being asked for this, so ask
            // them: the thread's own subscription only covers what answers the
            // focal note, never what it answers.
            wantQuote(want);
            break;
        };
        defer se.deinit();
        up[n] = want;
        // Stamped here, where the event is already in hand.
        up_lines[n] = @intFromFloat(ancestorBodyLines(&noteFrom(se.event, now)));
        n += 1;
        if (declared_root == null) declared_root = nip10Root(se.event.tags);
        const parent = nip10Parent(se.event.tags) orelse break;
        // A malformed cycle (a note tagging one of its own descendants, or its
        // own id) would walk forever, so a repeat ends the chain where it
        // repeats. It has NOT reached the thread's opening note, and the row
        // says so rather than claiming the chain is whole.
        if (std.mem.eql(u8, &parent, &focal.event_id)) {
            chain.gap = .missing;
            return finishChain(chain, up[0..n], up_lines[0..n], declared_root, parent);
        }
        for (up[0..n]) |seen| {
            if (std.mem.eql(u8, &seen, &parent)) {
                chain.gap = .missing;
                return finishChain(chain, up[0..n], up_lines[0..n], declared_root, parent);
            }
        }
        want = parent;
    }
    finishChain(chain, up[0..n], up_lines[0..n], declared_root, want);
}

/// Reverses the walk into drawing order and names the gap, if there is one.
fn finishChain(chain: *AncestorChain, up: []const [32]u8, up_lines: []const u8, declared_root: ?[32]u8, stopped_at: [32]u8) void {
    for (up, 0..) |id, i| {
        chain.ids[up.len - 1 - i] = id;
        chain.lines[up.len - 1 - i] = up_lines[i];
    }
    chain.len = up.len;
    chain.gap_is_root = chain.gap == .missing and declared_root != null and
        std.mem.eql(u8, &declared_root.?, &stopped_at);
}

/// One row of the chain above the focal note: an ancestor read from the store,
/// or the gap where the chain stops.
pub const Ancestor = struct {
    note: Note = .{},
    /// How many body lines this row draws. Carried on the row because an
    /// occluded level has no `note` to measure.
    lines: u8 = 0,
    /// `.none` for a real ancestor; anything else makes this row a ghost.
    ghost: AncestorGap = .none,
    /// For a ghost: whether what is missing is the thread's opening note.
    is_root: bool = false,
};

/// Records the FIRST `nostr:nevent`/`note` reference in `note`'s rendered
/// content as a decoded event id plus the byte span of its raw token, so the
/// body can split around it and draw an embedded quote card. A second reference,
/// an `naddr`, or an undecodable token is left as plain text (`.none`).
fn findQuoteRef(note: *Note) void {
    const text = note.content();
    var scratch: [16 * 1024]u8 = undefined;
    var i: usize = 0;
    while (i < text.len) : (i += 1) {
        // The token starts at a `nostr:` prefix, or a bare `nevent1`/`note1`, but
        // only at a word boundary, so one embedded in a URL (`…/nostr:nevent…`)
        // or a longer token is left alone rather than split into a spurious card.
        var body_start = i;
        if (std.mem.startsWith(u8, text[i..], "nostr:")) {
            if (!refPrecededByBoundary(text, i)) continue;
            body_start = i + "nostr:".len;
        } else if (std.mem.startsWith(u8, text[i..], "nevent1") or std.mem.startsWith(u8, text[i..], "note1")) {
            if (!refPrecededByBoundary(text, i)) continue;
        } else continue;

        const rest = text[body_start..];
        if (!std.mem.startsWith(u8, rest, "nevent1") and !std.mem.startsWith(u8, rest, "note1")) continue;
        var j: usize = 0;
        while (j < rest.len and isBech32Char(rest[j])) j += 1;
        const token = rest[0..j];

        var fba = std.heap.FixedBufferAllocator.init(&scratch);
        const arena = fba.allocator();
        const id: ?[32]u8 = if (std.mem.startsWith(u8, token, "nevent1")) blk: {
            const ptr = nostr.nip19.decodeNevent(arena, token) catch break :blk null;
            break :blk ptr.id;
        } else (nostr.nip19.decodeNote(arena, token) catch null);

        if (id) |event_id| {
            note.quote = .{ .kind = .event, .id = event_id, .off = @intCast(i), .len = @intCast((body_start - i) + j) };
            return;
        }
    }
}

/// A byte count as a reader reads it: `240 KB`, `1.4 MB`. Decimal units, because
/// that is what the file's own host quotes and what the note author copied.
fn byteSize(arena: std.mem.Allocator, bytes: u32) []const u8 {
    if (bytes < 1000) return std.fmt.allocPrint(arena, "{d} B", .{bytes}) catch "";
    if (bytes < 1_000_000) return std.fmt.allocPrint(arena, "{d} KB", .{bytes / 1000}) catch "";
    const mb = @as(f32, @floatFromInt(bytes)) / 1_000_000.0;
    return std.fmt.allocPrint(arena, "{d:.1} MB", .{mb}) catch "";
}

/// What a note's NIP-92 `imeta` tag says about `url`: its pixel dimensions, its
/// alt text and its blurhash. One walk, because the picture's chrome wants all
/// three and the tag is one place.
pub const Imeta = struct {
    width: u16 = 0,
    height: u16 = 0,
    /// A slice of the EVENT's memory, so it lives as long as the event does. The
    /// caller copies what it wants to keep.
    alt: []const u8 = "",
    blurhash: []const u8 = "",
    /// The file's size in bytes, as the note claims it. The only source there is:
    /// the SDK's fetch response carries no headers, so there is no Content-Length
    /// to read, and with previews off nothing is fetched at all.
    size: u32 = 0,

    /// Height over width, or 0 when the tag says nothing. Knowing the shape
    /// before the bytes arrive is what lets a row reserve exactly the right
    /// space, so nothing shifts when the picture lands.
    pub fn aspect(self: Imeta) f32 {
        if (self.width == 0 or self.height == 0) return 0;
        return @as(f32, @floatFromInt(self.height)) / @as(f32, @floatFromInt(self.width));
    }
};

pub fn imetaFor(tags: []const nostr.event.Tag, url: []const u8) Imeta {
    for (tags) |tag| {
        if (tag.len == 0 or !std.mem.eql(u8, tag[0], "imeta")) continue;
        var matches_url = false;
        var found: Imeta = .{};
        for (tag[1..]) |field| {
            if (std.mem.startsWith(u8, field, "url ")) {
                matches_url = std.mem.eql(u8, std.mem.trim(u8, field[4..], " "), url);
            } else if (std.mem.startsWith(u8, field, "dim ")) {
                const dim = std.mem.trim(u8, field[4..], " ");
                const x = std.mem.indexOfScalar(u8, dim, 'x') orelse continue;
                // Written as floats by some clients, so parse wide and narrow.
                const w = std.fmt.parseFloat(f32, dim[0..x]) catch continue;
                const h = std.fmt.parseFloat(f32, dim[x + 1 ..]) catch continue;
                if (w > 0 and h > 0 and w < 65536 and h < 65536) {
                    found.width = @intFromFloat(w);
                    found.height = @intFromFloat(h);
                }
            } else if (std.mem.startsWith(u8, field, "alt ")) {
                found.alt = std.mem.trim(u8, field[4..], " ");
            } else if (std.mem.startsWith(u8, field, "size ")) {
                found.size = std.fmt.parseInt(u32, std.mem.trim(u8, field[5..], " "), 10) catch 0;
            } else if (std.mem.startsWith(u8, field, "blurhash ")) {
                found.blurhash = std.mem.trim(u8, field["blurhash ".len..], " ");
            }
        }
        if (matches_url) return found;
    }
    return .{};
}

/// The aspect (height over width) the note's own NIP-92 `imeta` tag declares for
/// `url`, or 0 when it says nothing. An `imeta` tag reads
/// `["imeta", "url https://…", "dim 882x302", …]`; dimensions are sometimes
/// written as floats, so both forms parse.
pub fn imetaAspect(tags: []const nostr.event.Tag, url: []const u8) f32 {
    for (tags) |tag| {
        if (tag.len == 0 or !std.mem.eql(u8, tag[0], "imeta")) continue;
        var matches_url = false;
        var aspect: f32 = 0;
        for (tag[1..]) |field| {
            if (std.mem.startsWith(u8, field, "url ")) {
                matches_url = std.mem.eql(u8, std.mem.trim(u8, field[4..], " "), url);
            } else if (std.mem.startsWith(u8, field, "dim ")) {
                const dim = std.mem.trim(u8, field[4..], " ");
                const x = std.mem.indexOfScalar(u8, dim, 'x') orelse continue;
                const w = std.fmt.parseFloat(f32, dim[0..x]) catch continue;
                const h = std.fmt.parseFloat(f32, dim[x + 1 ..]) catch continue;
                if (w > 0 and h > 0) aspect = h / w;
            }
        }
        if (matches_url and aspect > 0) return aspect;
    }
    return 0;
}

/// Whether a URL names an image file. By extension, which is what Nostr media
/// hosts serve; a link without one is an ordinary link.
pub fn looksLikeImageUrl(url: []const u8) bool {
    const exts = [_][]const u8{ ".jpg", ".jpeg", ".png", ".gif", ".webp", ".avif", ".bmp" };
    const path_end = std.mem.indexOfScalar(u8, url, '?') orelse url.len;
    const path = url[0..path_end];
    for (exts) |ext| {
        if (std.ascii.endsWithIgnoreCase(path, ext)) return true;
    }
    return false;
}

/// The first image URL in `content`, or null. Recognised by extension, which is
/// what Nostr media hosts serve; a link without one stays ordinary text.
/// A URL's host, as a reader says it: no scheme, no `www.`, no path. One
/// spelling, because two of them drift and then two places disagree about what
/// the same address is called.
pub fn urlHost(url: []const u8) []const u8 {
    var rest = url;
    inline for ([_][]const u8{ "https://", "http://" }) |scheme| {
        if (std.mem.startsWith(u8, rest, scheme)) rest = rest[scheme.len..];
    }
    if (std.mem.startsWith(u8, rest, "www.")) rest = rest["www.".len..];
    if (std.mem.indexOfScalar(u8, rest, '/')) |slash| rest = rest[0..slash];
    return rest;
}

pub fn firstImageUrl(content: []const u8) ?[]const u8 {
    const exts = [_][]const u8{ ".jpg", ".jpeg", ".png", ".gif", ".webp", ".avif", ".bmp" };
    var i: usize = 0;
    while (i < content.len) : (i += 1) {
        if (content[i] != 'h') continue;
        if (!std.mem.startsWith(u8, content[i..], "http://") and !std.mem.startsWith(u8, content[i..], "https://")) continue;
        // The URL runs to the first whitespace.
        var j = i;
        while (j < content.len and !std.ascii.isWhitespace(content[j])) j += 1;
        const url = content[i..j];
        // Ignore a trailing bare query string when matching the extension.
        const path_end = std.mem.indexOfScalar(u8, url, '?') orelse url.len;
        const path = url[0..path_end];
        for (exts) |ext| {
            if (std.ascii.endsWithIgnoreCase(path, ext)) return url;
        }
        i = j;
    }
    return null;
}

/// Copies note content into `dst`, rewriting NIP-27 `nostr:npub…`/`nostr:nprofile…`
/// mentions into a readable `@name` (from the profile cache) or a short `@npub`,
/// and dropping `omit` (the URL rendered as a picture) wherever it appears.
/// Plain text is copied one whole codepoint at a time and stops at `dst`'s
/// capacity, so the buffer never ends mid-sequence. Returns the byte length.
pub fn renderContent(dst: []u8, src: []const u8, omit: []const u8) usize {
    // Mention decoding needs an allocator for bech32 scratch; a stack buffer
    // covers it without touching the heap for every note parsed. A pathological
    // mention that will not fit simply stays as its raw token.
    var scratch: [16 * 1024]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&scratch);
    const arena = fba.allocator();

    var out: usize = 0;
    var i: usize = 0;
    while (i < src.len) {
        if (omit.len > 0 and std.mem.startsWith(u8, src[i..], omit)) {
            i += omit.len;
            continue;
        }
        if (parseMentionAt(arena, src, i)) |m| {
            var label_buf: [80]u8 = undefined;
            const label = mentionLabel(m.pubkey, &label_buf);
            if (out + label.len > dst.len) break;
            @memcpy(dst[out..][0..label.len], label);
            out += label.len;
            i = m.end;
            continue;
        }
        const seq_len = std.unicode.utf8ByteSequenceLength(src[i]) catch 1;
        const take = @min(seq_len, src.len - i);
        if (out + take > dst.len) break;
        @memcpy(dst[out..][0..take], src[i..][0..take]);
        out += take;
        i += take;
    }
    // Lifting a URL out can leave whitespace stranded at either edge.
    const trimmed = std.mem.trim(u8, dst[0..out], " \t\r\n");
    if (trimmed.len != out) {
        std.mem.copyForwards(u8, dst[0..trimmed.len], trimmed);
        return trimmed.len;
    }
    return out;
}

/// A parsed `nostr:` mention at `src[i]`: the byte just past its token, and the
/// referenced pubkey. Null when `src[i]` is not the start of one.
fn parseMentionAt(arena: std.mem.Allocator, src: []const u8, i: usize) ?struct { end: usize, pubkey: [32]u8 } {
    const prefix = "nostr:";
    var body_start = i;
    if (std.mem.startsWith(u8, src[i..], prefix)) {
        // The same boundary guard the bare form below has always had. Without
        // it a contrived `https://example.com/nostr:npub1…` parses as a
        // mention, and now that the composer turns mentions into `p` tags that
        // is a notification sent to a real stranger on the strength of a path
        // segment in somebody else's link.
        if (!refPrecededByBoundary(src, i)) return null;
        body_start = i + prefix.len;
    } else {
        // A bare npub/nprofile counts too (plenty of clients write them without
        // the scheme), but only at a word boundary, so one inside a URL or a
        // longer token is left alone.
        const bare = std.mem.startsWith(u8, src[i..], "npub1") or std.mem.startsWith(u8, src[i..], "nprofile1");
        if (!bare) return null;
        if (i > 0 and (isBech32Char(src[i - 1]) or src[i - 1] == '/' or src[i - 1] == ':')) return null;
    }
    const rest = src[body_start..];
    var j: usize = 0;
    while (j < rest.len and isBech32Char(rest[j])) j += 1;
    if (j == 0) return null;
    const token = rest[0..j];
    const end = body_start + j;

    if (std.mem.startsWith(u8, token, "npub1")) {
        const pk = nostr.nip19.decodeNpub(arena, token) catch return null;
        return .{ .end = end, .pubkey = pk };
    }
    if (std.mem.startsWith(u8, token, "nprofile1")) {
        const pp = nostr.nip19.decodeNprofile(arena, token) catch return null;
        return .{ .end = end, .pubkey = pp.pubkey };
    }
    return null;
}

/// Writes `@` + the cached display name (or a short npub) for `pubkey` into
/// `buf`, returning the written slice. `buf` should be at least 80 bytes.
fn mentionLabel(pubkey: [32]u8, buf: []u8) []const u8 {
    buf[0] = '@';
    if (lookupProfile(pubkey)) |p| {
        if (p.name_len > 0) {
            const n = @min(p.name_len, buf.len - 1);
            @memcpy(buf[1..][0..n], p.name_buf[0..n]);
            return buf[0 .. 1 + n];
        }
    }
    // No name for this one: ask for it, so the next rebuild can show it.
    wantProfile(pubkey);
    const npub = abbreviateNpub(buf[1..], pubkey);
    return buf[0 .. 1 + npub.len];
}

/// Whether `c` is a bech32 data character (lowercase letter or digit), the run
/// that follows a `nostr:` prefix.
fn isBech32Char(c: u8) bool {
    return (c >= 'a' and c <= 'z') or (c >= '0' and c <= '9');
}

/// Whether `c` continues a hashtag word: letters, digits, underscore, or any
/// byte of a multi-byte UTF-8 sequence.
///
/// The `>= 0x80` arm is what makes `#café` and `#日本` whole words rather than
/// wreckage. Every continuation and lead byte of a UTF-8 sequence is >= 0x80 and
/// every ASCII byte is below it, so a run that ends on a byte < 0x80 always ends
/// on a codepoint boundary: the predicate cannot cut a character in half. The
/// ASCII-only version returned "caf" for the first of those and nothing at all
/// for the second, and both of those went out as tags once the composer started
/// emitting them.
///
/// It over-accepts emoji and non-ASCII punctuation as word characters. That is
/// the same trade every client here makes, and it fails toward a slightly long
/// tag rather than a truncated one.
fn isHashtagChar(c: u8) bool {
    return std.ascii.isAlphanumeric(c) or c == '_' or c >= 0x80;
}

/// Whether an event reference (`nostr:nevent1…`/`note1…`/`naddr1…`, or a bare one
/// at a word boundary) begins at `text[i]`, so a run can be accent-styled. Only
/// at a word boundary, so a `nostr:` or bare token embedded in a URL is skipped.
fn isEventRefStart(text: []const u8, i: usize) bool {
    if (!refPrecededByBoundary(text, i)) return false;
    var s = text[i..];
    if (std.mem.startsWith(u8, s, "nostr:")) s = s["nostr:".len..];
    return std.mem.startsWith(u8, s, "nevent1") or std.mem.startsWith(u8, s, "note1") or std.mem.startsWith(u8, s, "naddr1");
}

/// Whether `text[i]` sits at a word boundary for a nostr reference: the start, or
/// after a character that could not be part of a URL or bech32 run. Keeps a
/// `nostr:nevent…`/bare token embedded in a URL from being matched.
fn refPrecededByBoundary(text: []const u8, i: usize) bool {
    if (i == 0) return true;
    const c = text[i - 1];
    return !(std.ascii.isAlphanumeric(c) or c == '/' or c == ':' or c == '.' or c == '-' or c == '_' or c == '@');
}

fn setAuthor(note: *Note, pubkey: [32]u8) void {
    const s = abbreviateNpub(&note.author_buf, pubkey);
    note.author_len = @intCast(s.len);
}

/// Writes an abbreviated npub (`npub1p9x8h…7k2q`), the canonical Nostr
/// identifier, for `pubkey` into `out`, returning the written slice; falls back
/// to a short hex prefix if bech32 encoding fails. The result always lives in
/// `out` (never the scratch buffer), so the caller can hold it safely. `out`
/// should be at least 20 bytes for the abbreviated form. bech32's encoder grows
/// an ArrayList and hands back an owned slice, so on a fixed buffer the
/// intermediate reallocations accumulate well past the ~63-char result; 1 KiB of
/// scratch covers that churn without touching the heap.
fn abbreviateNpub(out: []u8, pubkey: [32]u8) []const u8 {
    var buf: [1024]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&buf);
    const npub = nostr.nip19.encodeNpub(fba.allocator(), pubkey) catch {
        const hexdigits = "0123456789abcdef";
        var n: usize = 0;
        while (n < 16 and n + 1 < out.len) : (n += 2) {
            out[n] = hexdigits[pubkey[n / 2] >> 4];
            out[n + 1] = hexdigits[pubkey[n / 2] & 0x0f];
        }
        return out[0..n];
    };
    if (npub.len > 18) {
        if (std.fmt.bufPrint(out, "{s}…{s}", .{ npub[0..12], npub[npub.len - 5 ..] })) |s| return s else |_| {}
    }
    const n = @min(npub.len, out.len);
    @memcpy(out[0..n], npub[0..n]);
    return out[0..n];
}

/// The largest prefix of `s` no longer than `max` that ends on a UTF-8
/// codepoint boundary (never mid-sequence).
fn utf8SafeLen(s: []const u8, max: usize) usize {
    if (s.len <= max) return s.len;
    var n = max;
    while (n > 0 and (s[n] & 0xC0) == 0x80) n -= 1;
    return n;
}

// -------------------------------------------------------------------- msg

/// The chrome's anchored menus. These are floating surfaces positioned against
/// their trigger, so each one is drawn as the trigger's sibling inside a stack
/// and rendered only while it is the open one.
pub const ChromeMenu = enum { none, scope, relays, account, outbox };

pub const Msg = union(enum) {
    /// The repeating refresh timer fired: reconcile the feed with the store.
    tick: native_sdk.EffectTimer,
    /// A text edit in the composer, mirrored into the draft buffer.
    draft_edit: canvas.TextInputEvent,
    /// Post the current draft: sign, store locally, and publish to the pool.
    post,
    /// Open the compose sheet (a guest is routed to the join screen instead).
    open_compose,
    /// Dismiss the compose sheet.
    close_compose,
    /// Open the first-intent join sheet (create / bring a key / use a signer).
    open_join,
    /// Dismiss the join sheet; a remembered intent is forgotten with it.
    close_join,
    /// The sheet's primary: mint a local identity and replay the intent.
    join_create,
    /// The sheet's import path: open the Notary window (a separate process),
    /// so a pasted key never enters Plaza. The remembered intent survives.
    open_notary_import,
    /// Leave the join screen back to the feed; reading never needs an identity.
    keep_browsing,
    /// The join sheet's "Use your own signer": go to the focused bunker input.
    open_bunker,
    /// Back out of the bunker input to the ladder.
    close_bunker,
    /// Hide the guest strip for this session.
    dismiss_guest_strip,
    /// Open one of the chrome's anchored menus (or close it, when it is already
    /// the open one, so a trigger toggles).
    toggle_menu: ChromeMenu,
    /// The bell, and what is behind it.
    toggle_notifications,
    close_notifications,
    notifications_tab: u8,
    notifications_read_all,
    /// The note overflow menu.
    toggle_note_menu: i64,
    close_note_menu,
    /// The one action behind the note menu. The payload says which way: 0 means
    /// a guest reached for it, 1 follow, 2 unfollow.
    follow_author: u8,
    /// Opens a person as a level of their own.
    open_person: [32]u8,
    /// Follow or unfollow the person whose profile is open: 1 follow, 2 unfollow.
    follow_person: u8,
    /// Which of a profile's two tabs: 0 notes, 1 replies.
    profile_tab: u8,
    /// Opens the Edit profile sheet, and the three fields in it.
    open_profile_edit,
    close_profile_edit,
    profile_name_edit: canvas.TextInputEvent,
    profile_about_edit: canvas.TextInputEvent,
    profile_picture_edit: canvas.TextInputEvent,
    profile_save,
    profile_retry,
    /// Walks a relay through what it is for: both, read, write.
    relay_cycle: u8,
    /// Drops a relay from the pool.
    relay_remove: u8,
    /// The relay being typed into the add field.
    relay_edit: canvas.TextInputEvent,
    /// Adds what was typed, or the suggestion pressed.
    relay_add,
    relay_suggest: u8,
    /// Replaces the `@word` being typed with a real reference to this key.
    insert_mention: [32]u8,
    /// Close whatever chrome menu is open (Escape, or a press outside it).
    close_menu,
    /// Stop talking to the relays until resumed, or start again.
    toggle_relays_paused,
    /// Jump the feed to its newest note.
    jump_to_newest,
    go_home,
    /// Reveal the next page of a thread's replies.
    show_more_replies,
    /// Show or re-hide the replies from outside the follow graph.
    toggle_outside_replies,
    /// Sign out, asked for from the account menu: opens Settings with the
    /// confirmation showing, so the menu never signs anyone out on one press.
    open_settings_logout,
    /// Copy a note's nevent address to the clipboard.
    copy_nevent: i64,
    /// Open a note on the web (njump), for sharing it outside nostr.
    open_web: i64,
    /// A text edit in the name beat's field.
    name_edit: canvas.TextInputEvent,
    /// Publish the chosen name as the account's kind:0 and move on.
    name_save,
    /// Skip the name beat; the account stays nameless for now.
    name_skip,
    /// From the backup nudge: open Settings at the backup card.
    backup_now,
    /// Dismiss the backup nudge for this session.
    backup_later,
    /// Onboarding: create a fresh local identity and enter the feed.
    create_identity,
    /// A text edit in the onboarding sign-in field.
    login_edit: canvas.TextInputEvent,
    /// Onboarding: sign in with the pasted nsec or bunker link and enter the feed.
    login_submit,
    /// Open the Settings screen.
    open_settings,
    /// Return from Settings to the feed.
    close_settings,
    /// Reveal (or hide) the local secret key for backup.
    toggle_nsec,
    /// Copy the signed-in npub to the clipboard.
    copy_npub,
    /// Copy the local secret key (nsec) to the clipboard.
    copy_nsec,
    /// Ask to log out: show the confirmation.
    logout_request,
    /// Dismiss the logout confirmation.
    logout_cancel,
    /// Confirm logout: wipe the session (and a local key) and return to onboarding.
    logout_confirm,
    /// The signer daemon exited (logged; the watchdog and respawn are later).
    helper_exited: native_sdk.EffectExit,
    notary_exited: native_sdk.EffectExit,
    /// The signer daemon's /pubkey health-check answered.
    helper_pubkey: native_sdk.EffectResponse,
    /// A /setup (create) answered: adopt the new helper identity.
    helper_setup: native_sdk.EffectResponse,
    /// A /sign answered: ingest and publish the signed event.
    helper_signed: native_sdk.EffectResponse,
    /// An avatar fetch finished: register the image or fall back to initials.
    avatar_fetched: native_sdk.EffectResponse,
    avatar_warmed: native_sdk.EffectResponse,
    media_warmed: native_sdk.EffectResponse,
    banner_fetched: native_sdk.EffectResponse,
    /// A media fetch finished: decode, downscale if needed, and register it.
    media_fetched: native_sdk.EffectResponse,
    /// A NIP-05 well-known lookup finished: mark the author verified on a match.
    nip05_verified: native_sdk.EffectResponse,
    /// A page that was asked what it says about itself.
    link_fetched: native_sdk.EffectResponse,
    /// A text edit in the Settings media-proxy field.
    proxy_edit: canvas.TextInputEvent,
    /// Save the media-proxy setting.
    proxy_save,
    /// Flips whether the app reaches out for what notes point at.
    previews_toggle,
    client_tag_toggle,
    /// The feed scrolled: remember where, so images load around the viewport.
    feed_scrolled: canvas.ScrollState,
    /// A link in a note was pressed: open it in the browser.
    open_url: []const u8,
    /// The animation timer fired: advance any playing GIFs.
    animate: native_sdk.EffectTimer,
    /// The profile-fetch timer: re-ask for wanted metadata, decoupled from the
    /// view refresh (see `profile_timer_key`).
    profiles: native_sdk.EffectTimer,
    /// Expand a note's picture to fill the window.
    expand_image: i64,
    /// One picture, asked for by the reader while previews are off.
    load_image: i64,
    /// Dismiss the expanded picture.
    close_image,
    /// Copy a note's words to the clipboard (by id).
    copy_note_text: i64,
    quote_note: i64,
    toggle_mention_off: [32]u8,
    /// Put the mention picker away without choosing anybody.
    close_mentions,
    /// Open the Notary window on what it is holding, from Settings.
    open_notary_window,
    /// Toggle a like on a note (by id): publish a kind:7 reaction, or a kind:5
    /// deletion to un-like. A guest press is remembered and routed to the join.
    like: i64,
    /// Open a note's thread (by id): the focused note and its replies.
    open_thread: i64,
    /// Open a quoted event as a thread (by its full 32-byte id).
    open_event: [32]u8,
    /// Leave the thread back to the feed.
    close_thread,
    /// A text edit in the thread's reply composer.
    reply_edit: canvas.TextInputEvent,
    /// Publish the reply composer's text as a reply to the open thread's note.
    reply_submit,
    /// Toggle a long note's body (by id) between the collapsed fold and full.
    toggle_expand: i64,
    /// The reader reached the end of the feed: ask the store for another page.
    load_older,
    /// A press that landed on a modal's own card rather than on a control in it.
    ///
    /// It does nothing, and that IS the job. A press does not land where it
    /// hits: the engine hit tests to the deepest widget and then walks UP to the
    /// nearest ancestor that claims presses, and a `.card` claims none, so a
    /// click on a sheet's own background used to walk straight past it to the
    /// full-window dialog behind and close the sheet the reader was using.
    /// Binding this is what makes the card claim the press and stop the walk.
    absorb_press,

    // Dispatched from Zig rather than markup: the effect results, and every
    // action on the feed screen (a Zig view now, not a markup file).
    pub const view_unbound = .{ "tick", "animate", "profiles", "avatar_fetched", "avatar_warmed", "media_warmed", "banner_fetched", "media_fetched", "draft_edit", "post", "open_compose", "close_compose", "open_join", "close_join", "join_create", "open_notary_import", "open_bunker", "close_bunker", "nip05_verified", "link_fetched", "dismiss_guest_strip", "name_edit", "name_save", "name_skip", "backup_now", "backup_later", "helper_exited", "notary_exited", "helper_pubkey", "helper_setup", "helper_signed", "open_settings", "feed_scrolled", "open_url", "expand_image", "load_image", "close_image", "like", "open_thread", "open_event", "close_thread", "reply_edit", "reply_submit", "toggle_expand", "load_older", "absorb_press", "open_notary_window", "copy_note_text", "quote_note", "close_mentions" };
};

// ---------------------------------------------------------------- app + view

pub const AppUi = canvas.Ui(Msg);

// The two static screens stay declarative markup, compiled into the view at
// build time (so their bindings are still checked, now by the compiler). The
// feed is hand-written below: an inline image needs a runtime `ImageId`
// reference, which the markup grammar deliberately does not carry, so a media
// feed has to be a Zig view.
const OnboardingView = canvas.CompiledMarkupView(Model, Msg, @embedFile("onboarding.native"));
/// Settings, built in Zig. It was markup until the relay list needed a row that
/// carries its own index into three different messages, which a binding cannot
/// express: the same wall the feed hit. Cards below read top to bottom the way
/// the screen does.
///
/// It is a SHEET over the feed rather than a screen instead of it. As a screen
/// it had two faults that were really one fault: a 440 column centred on a bare
/// window reads as a modal that forgot to be one, and the grey behind that
/// column was a panel stretched by the scroll viewport, so it stopped dead at
/// the window's height and everything past the fold sat on bare black. A card
/// with the scroll INSIDE it cannot do that: the surface is the card's own, and
/// the scroll is bounded by it rather than the other way round.
fn settingsSheet(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    var sections: [6]AppUi.Node = undefined;
    var n: usize = 0;

    sections[n] = identitySection(ui, model);
    n += 1;
    sections[n] = settingsSection(
        ui,
        "RELAYS",
        "reads & writes route automatically · NIP-65",
        relayCard(ui, model),
    );
    n += 1;
    sections[n] = settingsSection(ui, "APPEARANCE", "", appearanceCard(ui));
    n += 1;
    sections[n] = settingsSection(ui, "FEED", "", feedCard(ui, model));
    n += 1;
    sections[n] = logoutSection(ui, model);
    n += 1;
    sections[n] = ui.row(.{ .cross = .center, .gap = 0 }, .{
        ui.paragraph(.{ .style = .{ .foreground = p.text_dim } }, &.{.{ .text = model.version_line(), .scale = mono_hint_scale }}),
    });
    n += 1;

    // A PAGE, not a modal, and the reason is measured rather than stylistic.
    //
    // A modal is a translucent scrim across the whole window. Anything that
    // changes underneath one has to be repainted along with the scrim over it,
    // so every frame of scrolling inside a sheet repaints the entire window and
    // the cost grows with the window. On a 1600x1000 window, presenting a frame
    // took 117ms with settings open as a sheet and 18ms with a thread open,
    // which is the same screen area drawn as an opaque level. The feed alone was
    // 17ms. Eight frames a second against sixty, for a dimmed backdrop.
    //
    // Threads and profiles have always been opaque full-screen levels and have
    // always scrolled properly. This is settings joining them.
    return ui.column(.{
        .grow = 1,
        .style_tokens = .{ .background = .background },
        .semantics = .{ .label = "Settings" },
    }, .{
        settingsHeader(ui),
        ui.el(.separator, .{ .style = .{ .background = p.divider_chrome } }, .{}),
        ui.scroll(.{ .grow = 1 }, .{
            ui.row(.{ .gap = 0 }, .{
                ui.spacer(1),
                ui.column(.{ .gap = settings_section_gap, .width = settings_column_width }, .{
                    vgap(ui, 16),
                    ui.column(.{ .gap = settings_section_gap, .grow = 1 }, .{sections[0..n]}),
                    vgap(ui, 18),
                }),
                ui.spacer(1),
            }),
        }),
    });
}

/// The 38px header band. "Settings" sits centred in it, with the way out on the
/// left, so the title belongs to the sheet rather than to the column beneath it.
fn settingsHeader(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.row(.{ .cross = .center, .gap = 0, .height = settings_header_height, .padding = 0.01 }, .{
        hgap(ui, 10),
        // "Close", not "Back": this is a sheet over the feed now, and Back is
        // what the thread and profile headers say when there is a place behind
        // to return to. There is nothing behind this but the feed it covers.
        ui.button(.{ .size = .sm, .variant = .ghost, .autofocus = true, .on_press = Msg.close_settings }, "Close"),
        ui.spacer(1),
        ui.paragraph(
            .{ .style = .{ .foreground = p.text_sheet_title } },
            &.{.{ .text = "Settings", .weight = .medium, .scale = settings_title_scale }},
        ),
        ui.spacer(1),
        // The same width the Close button takes, so the title is centred in the
        // band rather than in what is left of it.
        hgap(ui, 62),
    });
}

/// A labelled section: the mono label, an optional caption beside it, then the
/// card. The label is mono per the design; the engine draws mono at one weight,
/// so it carries its emphasis through colour and size rather than through w600.
fn settingsSection(ui: *AppUi, label: []const u8, caption: []const u8, card: AppUi.Node) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            ui.paragraph(.{ .style = .{ .foreground = p.text_label } }, &.{.{ .text = label, .monospace = true, .scale = mono_meta_scale }}),
            if (caption.len > 0) hgap(ui, 8) else ui.spacer(0),
            if (caption.len > 0)
                ui.paragraph(.{ .style = .{ .foreground = p.text_dim } }, &.{.{ .text = caption, .scale = mono_hint_scale }})
            else
                ui.spacer(0),
        }),
        vgap(ui, settings_label_gap),
        card,
    });
}

/// One settings card: the house card chrome, so every section on the screen
/// wears the same edge.
fn settingsCard(ui: *AppUi, children: anytype) AppUi.Node {
    const p = theme.palette;
    // Padding, not scaffolding. This was a row, two columns and four spacers
    // around the children: seven nodes per card to express an inset that the
    // card can state in one. Settings is the heaviest screen in the app and
    // half its nodes were whitespace like this.
    //
    // The inset is uniform 12 where it used to be 12 horizontal and 11
    // vertical, because the builder takes one number. One pixel, against six
    // nodes a card.
    return ui.el(.card, .{ .padding = 12, .style = .{ .background = p.surface_settings_card, .border = p.border_chip, .radius = settings_card_radius, .stroke_width = 1 } }, .{
        ui.column(.{ .gap = 0, .grow = 1 }, children),
    });
}

/// A card's internal rule: what separates who you are from what signs for you.
fn cardDivider(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 10),
        ui.el(.panel, .{ .height = 1, .padding = 0.01, .style = .{ .background = p.divider_card, .radius = 0, .stroke_width = 0 } }, .{}),
        vgap(ui, 10),
    });
}

/// The identity section: who you are, what signs for you, and, when the key is
/// on this machine, how to take a copy of it away with you.
fn identitySection(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    var rows: [5]AppUi.Node = undefined;
    var n: usize = 0;

    rows[n] = ui.row(.{ .cross = .center, .gap = 0 }, .{
        meAvatar(ui, 38),
        hgap(ui, 10),
        ui.column(.{ .gap = 0, .grow = 1 }, .{
            ui.paragraph(.{ .style = .{ .foreground = p.text_primary } }, &.{.{ .text = accountName(), .weight = .medium, .scale = scope_title_scale }}),
            // The npub only when it is not already the line above it: an account
            // with no kind:0 yet would otherwise read its own key twice.
            if (accountHasName()) vgap(ui, 2) else ui.spacer(0),
            if (accountHasName())
                ui.paragraph(.{ .style = .{ .foreground = p.text_muted } }, &.{.{ .text = npubShort(), .monospace = true, .scale = mono_meta_scale }})
            else
                ui.spacer(0),
        }),
        hgap(ui, 8),
        settingsLink(ui, "Copy npub", Msg.copy_npub),
        hgap(ui, 10),
        if (model.is_guest()) ui.spacer(0) else settingsLink(ui, "Edit profile", Msg.open_profile_edit),
    });
    n += 1;

    rows[n] = cardDivider(ui);
    n += 1;

    // What holds the key, said as a fact about this machine rather than as a
    // badge. The dot is green only for a signer that is answering.
    // The dot reports the signer. Painting it green unconditionally would say
    // "this is working" while a dead Notary daemon quietly refused every note.
    const signer_state = signerStatus();
    const signer_healthy = signerIsHealthy();
    rows[n] = ui.row(.{ .cross = .center, .gap = 0 }, .{
        ui.el(.panel, .{ .width = 7, .height = 7, .padding = 0.01, .style = .{
            .background = signer_state.color,
            .radius = 4,
            .stroke_width = 0,
        } }, .{}),
        hgap(ui, 9),
        ui.column(.{ .gap = 0, .grow = 1 }, .{
            // The line says what signs for you; the sub-line says how that is
            // going. When the signer is unhealthy its own words take the
            // sub-line, because "Notary unreachable" is the thing worth reading
            // and a fixed reassurance underneath it would be a lie.
            ui.paragraph(.{ .style = .{ .foreground = p.text_primary } }, &.{.{ .text = model.signer_line(), .weight = .medium, .scale = menu_scale }}),
            vgap(ui, 2),
            ui.paragraph(
                .{ .wrap = true, .style = .{ .foreground = if (signer_healthy) p.text_faint else p.status_warning_text } },
                &.{.{ .text = if (signer_healthy) model.signer_sub() else signer_state.label, .scale = mono_hint_scale }},
            ),
        }),
        // The design puts a "Change…" here. There is no change-signer flow to
        // send it to: changing what signs means signing out and signing back in
        // differently, and the control for that is at the bottom of the screen
        // wearing the word it deserves. A gentler-looking link that opens a
        // confirmation about removing your key is the dishonest option.
        //
        // What DOES belong in that seat is a way to go and look at the thing this
        // row is a sentence about. Notary is a separate process holding the key
        // this account is, and until now the only time a reader ever saw it was
        // the few seconds of the ceremony that made the key.
        if (model.can_open_notary()) settingsLink(ui, "Open Notary", Msg.open_notary_window) else ui.spacer(0),
    });
    n += 1;

    // The backup card has no home in the design, and dropping it would drop the
    // only way off this machine with the key that IS the account. It lives under
    // the signer line, which is exactly the row it qualifies.
    if (model.is_local_key()) {
        rows[n] = ui.column(.{ .gap = 0 }, .{
            cardDivider(ui),
            ui.paragraph(
                .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
                &.{.{ .text = "This key lives only on this Mac. Back it up so losing the Mac is not losing the account. Plaza never sends it anywhere.", .scale = mono_hint_scale }},
            ),
            vgap(ui, 9),
            if (model.nsec_hidden())
                ui.row(.{ .cross = .center, .gap = 0 }, .{
                    ui.button(.{ .size = .sm, .variant = .ghost, .on_press = Msg.toggle_nsec }, "Reveal secret key"),
                    ui.spacer(1),
                })
            else
                ui.column(.{ .gap = 0 }, .{
                    ui.paragraph(
                        .{ .wrap = true, .style = .{ .foreground = p.text_sheet_title } },
                        &.{.{ .text = model.revealed_nsec(ui.arena), .monospace = true, .scale = mono_row_scale }},
                    ),
                    vgap(ui, 9),
                    ui.row(.{ .cross = .center, .gap = 8 }, .{
                        ui.button(.{ .size = .sm, .on_press = Msg.copy_nsec }, "Copy nsec"),
                        ui.spacer(1),
                        ui.button(.{ .size = .sm, .variant = .ghost, .on_press = Msg.toggle_nsec }, "Hide"),
                    }),
                }),
        });
        n += 1;
    }

    return settingsSection(ui, "IDENTITY", "", settingsCard(ui, .{rows[0..n]}));
}

/// A quiet inline action: the design's "Copy npub", "Edit profile", "Change…".
/// Text, not a button, because a card full of buttons reads as a form.
fn settingsLink(ui: *AppUi, label: []const u8, msg: Msg) AppUi.Node {
    const p = theme.palette;
    return ui.el(.list_item, .{
        .padding = 0.01,
        .height = 18,
        .cross = .center,
        .on_press = msg,
        .style = .{ .radius = 4 },
        .semantics = .{ .role = .button, .label = label, .focusable = true },
    }, .{
        ui.paragraph(.{ .style = .{ .foreground = p.text_muted_alt } }, &.{.{ .text = label, .scale = meta_scale }}),
    });
}

/// Appearance. Nothing here is adjustable yet, and the section says so by
/// showing where the app stands on each axis with the alternatives disabled: a
/// statement about the app rather than a row of dead controls.
fn appearanceCard(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return settingsCard(ui, .{
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            themeRadio(ui, "Dark", true),
            hgap(ui, 14),
            themeRadio(ui, "System", false),
            hgap(ui, 14),
            themeRadio(ui, "Light", false),
            ui.spacer(1),
        }),
        vgap(ui, 9),
        ui.paragraph(
            .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
            &.{.{ .text = "Plaza is dark only for now, at a comfortable density. Both are on the list.", .scale = mono_hint_scale }},
        ),
    });
}

/// One appearance choice. Only the selected one is live, and the others are
/// disabled rather than absent, so the axis is legible.
fn themeRadio(ui: *AppUi, label: []const u8, selected: bool) AppUi.Node {
    const p = theme.palette;
    return ui.row(.{ .cross = .center, .gap = 0 }, .{
        ui.el(.radio, .{
            .size = .sm,
            .selected = selected,
            // Even the selected one takes no press: there is nothing to switch
            // to. `disabled` also stops the control claiming a press it would
            // then drop, which is what a live-looking dead control does.
            .disabled = true,
            .opacity = if (selected) 1.0 else 0.55,
            .style = .{
                .border = if (selected) p.surface_control_solid else p.border_radio,
                .accent = p.surface_control_solid,
                .stroke_width = 1.5,
            },
            .semantics = .{ .label = label },
        }, .{}),
        hgap(ui, 6),
        ui.paragraph(
            .{ .style = .{ .foreground = if (selected) p.text_body_strong else p.text_muted_alt }, .opacity = if (selected) 1.0 else 0.55 },
            &.{.{ .text = label, .scale = menu_scale }},
        ),
    });
}

/// The feed section: what the app is allowed to fetch on the reader's behalf,
/// and where pictures are resized. Both are privacy settings before they are
/// anything else, which is why each keeps its sentence.
fn feedCard(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return settingsCard(ui, .{
        // A real checkbox: it owns its whole row, because a control nested in a
        // pressable row claims the press and drops it.
        ui.el(.checkbox, .{
            .size = .sm,
            .checked = model.previews_on(),
            .text = "Load media previews",
            .on_toggle = Msg.previews_toggle,
            .style = .{
                .accent = p.surface_control_solid,
                .accent_foreground = p.on_accent,
                .border = p.border_radio,
                .radius = 4,
                .stroke_width = 1.5,
            },
            .semantics = .{ .label = "Load media previews", .focusable = true },
        }, .{}),
        vgap(ui, 7),
        ui.paragraph(
            .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
            &.{.{ .text = model.previews_explainer(), .scale = mono_hint_scale }},
        ),
        cardDivider(ui),
        ui.el(.checkbox, .{
            .size = .sm,
            .checked = model.client_tag_on(),
            .text = "Say notes were written in Plaza",
            .on_toggle = Msg.client_tag_toggle,
            .style = .{
                .accent = p.surface_control_solid,
                .accent_foreground = p.on_accent,
                .border = p.border_radio,
                .radius = 4,
                .stroke_width = 1.5,
            },
            .semantics = .{ .label = "Say notes were written in Plaza", .focusable = true },
        }, .{}),
        vgap(ui, 7),
        ui.paragraph(
            .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
            &.{.{ .text = model.client_tag_explainer(), .scale = mono_hint_scale }},
        ),
        cardDivider(ui),
        ui.paragraph(.{ .style = .{ .foreground = p.text_body_soft } }, &.{.{ .text = "Media proxy", .scale = menu_scale }}),
        vgap(ui, 7),
        ui.paragraph(
            .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
            &.{.{ .text = "Pictures are resized through this service so they load fast and small. Point it at your own instance, or clear it to load originals straight from their host.", .scale = mono_hint_scale }},
        ),
        vgap(ui, 9),
        ui.inputGroup(
            .{ .semantics = .{ .label = "Media proxy" } },
            ui.el(.textarea, .{
                .text = model.proxy_draft(),
                .placeholder = "https://wsrv.nl/",
                .on_input = AppUi.inputMsg(.proxy_edit),
                .on_submit = Msg.proxy_save,
                .height = 30,
            }, .{}),
            ui.inputGroupActions(.{}, .{
                ui.paragraph(
                    .{ .wrap = true, .grow = 1, .style = .{ .foreground = p.text_dim } },
                    &.{.{ .text = model.proxy_status(), .scale = mono_hint_scale }},
                ),
                ui.button(.{ .size = .sm, .on_press = Msg.proxy_save }, "Save"),
            }),
        ),
    });
}

/// Signing out: one press to ask, one card to confirm. The card is the whole
/// section when it is up, because a confirmation that shares a row with other
/// controls is a confirmation nobody reads.
fn logoutSection(ui: *AppUi, model: *const Model) AppUi.Node {
    if (model.logout_idle()) {
        return ui.row(.{ .gap = 0 }, .{
            ui.button(.{ .variant = .destructive, .on_press = Msg.logout_request }, "Log out"),
            ui.spacer(1),
        });
    }
    return settingsCard(ui, .{
        ui.paragraph(.{ .wrap = true, .style = .{ .foreground = theme.palette.text_primary } }, &.{.{ .text = model.logout_warning(), .scale = menu_scale }}),
        vgap(ui, 12),
        ui.row(.{ .cross = .center, .gap = 8 }, .{
            ui.button(.{ .size = .sm, .variant = .ghost, .on_press = Msg.logout_cancel }, "Cancel"),
            ui.spacer(1),
            ui.button(.{ .size = .sm, .variant = .destructive, .on_press = Msg.logout_confirm }, "Log out"),
        }),
    });
}

/// Walks a relay through what it is for. Both, then read, then write, then both
/// again: three states, because a relay that is neither is a relay you have
/// removed, and there is a button for that.
fn cycleRelay(i: usize) void {
    if (i >= g_relays.len) return;
    const e = &g_relays[i];
    if (!e.used) return;
    if (e.read and e.write) {
        e.write = false;
    } else if (e.read) {
        e.read = false;
        e.write = true;
    } else {
        e.read = true;
        e.write = true;
    }
}

/// Drops a relay. The SLOT stays claimed and dormant: its index is a promise to
/// everything that recorded one, and its thread simply finds nothing to dial.
fn removeRelay(i: usize) void {
    if (i >= g_relays.len) return;
    // Recorded BEFORE the seat is wiped, because the publish splices onto the
    // list this account already published and "the pool has no seat for it" is
    // what decides a relay is carried forward. A removal looks exactly like
    // that from the outside.
    if (relayAt(i)) |e| noteRelayRemoved(e.url());
    lockRelayTable();
    g_relays[i] = .{};
    unlockRelayTable();
    // The seat keeps its index, but nothing about the relay that sat in it: a
    // status left at `.connected` would keep counting toward "4/6 relays", and a
    // latency left behind would be shown beside whoever takes the seat next.
    forgetRelaySlotState(i);
}

/// Drops everything recorded ABOUT a slot rather than about the pool: its
/// connection state, its latency samples, and the per-note marks saying this
/// slot was the one that carried a note.
fn forgetRelaySlotState(i: usize) void {
    if (i >= max_relays) return;
    setRelayStatus(i, .offline);
    clearRelayRtt(i);
    forgetRelaySeen(i);
}

/// The URLs currently in the slots, so a table swap can tell which seats
/// actually changed hands.
fn snapshotRelayUrls(out: *[max_relays][96]u8, lens: *[max_relays]u8) void {
    lockRelayTable();
    defer unlockRelayTable();
    for (&g_relays, 0..) |*e, i| {
        lens[i] = if (e.used) e.url_len else 0;
        if (e.used) @memcpy(out[i][0..e.url_len], e.url_buf[0..e.url_len]);
    }
}

/// Drops what was recorded against every slot whose OCCUPANT changed, and
/// leaves alone the slots still holding the same relay.
///
/// The whole-table version of this was `for (0..max_relays) |i|
/// forgetRelaySlotState(i)`, and it is why the pool read `0/5` forever after a
/// sign-out. Status, latency and seen-ness describe a LIVE CONNECTION, and the
/// thread that owns that connection is parked in a blocking read almost all of
/// the time: it cannot put a status back that somebody else cleared until its
/// relay next says something, and a quiet relay never does. So clearing the row
/// for a relay that is still perfectly connected does not go stale, it stays
/// wrong, and the bar reads nothing-is-working over a pool that is working.
///
/// The seat metaphor the per-slot state is built on still holds: it is about the
/// occupant, so it is dropped when the occupant changes and kept when it does
/// not. Signing out replaces a list with the bootstrap five, and most of the
/// time most of those seats do not change hands at all.
fn forgetChangedRelaySlotStates(before: *const [max_relays][96]u8, lens: *const [max_relays]u8) void {
    for (0..max_relays) |i| {
        const was: []const u8 = before[i][0..lens[i]];
        const now: []const u8 = if (relayAt(i)) |e| e.url() else "";
        // Same relay in the same seat: its connection, its latency and its
        // status all still describe something true.
        if (was.len != 0 and now.len != 0 and relayUrlEql(was, now)) continue;
        forgetRelaySlotState(i);
    }
}

/// The relay list: which relays this app talks to, and in which direction.
///
/// The badge is the control, not a label. Pressing it walks R and W, which is
/// the whole of NIP-65's vocabulary: a relay you read from, a relay you write
/// to, or both. Reads and writes actually follow it, so a relay set to R never
/// sees a note and a relay set to W is never asked a question.
fn relayCard(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const slots = relaySlots();
    const rows = ui.arena.alloc(AppUi.Node, slots + 4) catch return ui.spacer(0);
    var n: usize = 0;
    // No heading here: the section above the card already says RELAYS, and the
    // caption beside it already says what the markers do.
    rows[n] = ui.paragraph(
        .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
        &.{.{ .text = "Press a badge to change what a relay is for.", .scale = mono_hint_scale }},
    );
    n += 1;
    rows[n] = vgap(ui, 10);
    n += 1;
    for (0..slots) |i| {
        const e = relayAt(i) orelse continue;
        const state: Conn = @enumFromInt(g_relay_status[i].load(.monotonic));
        rows[n] = relayListRow(ui, e, i, state);
        n += 1;
    }
    rows[n] = relayAddRow(ui, model);
    n += 1;
    return settingsCard(ui, .{rows[0..n]});
}

/// One relay: how it is doing, where it is, what it is for, and a way out.
fn relayListRow(ui: *AppUi, e: *const RelayEntry, index: usize, state: Conn) AppUi.Node {
    const p = theme.palette;
    const dot: canvas.Color = switch (state) {
        .connected => p.status_success,
        // Amber, not green. The socket is open and nothing has failed, but the
        // last word from this relay is a minute old and a keepalive is out with
        // no answer. Green here is the lie this state exists to stop telling.
        .quiet => p.status_warning_text,
        .connecting => p.status_warning_text,
        .offline => p.status_offline,
    };
    const badge = relayBadgeText(e);
    return ui.column(.{ .gap = 0 }, .{
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            ui.el(.panel, .{ .width = 7, .height = 7, .padding = 0.01, .style = .{ .background = dot, .radius = 4, .stroke_width = 0 } }, .{}),
            hgap(ui, 9),
            ui.paragraph(.{ .style = .{ .foreground = p.text_secondary } }, &.{.{ .text = e.url(), .monospace = true, .scale = mono_row_scale }}),
            hgap(ui, 9),
            // Reconnecting is worth saying: an amber dot alone reads as a fault
            // rather than as the app already doing something about it.
            if (state == .connecting)
                ui.paragraph(.{ .style = .{ .foreground = p.status_warning_text } }, &.{.{ .text = "reconnecting", .monospace = true, .scale = mono_chip_scale }})
            else if (state == .quiet)
                ui.paragraph(.{ .style = .{ .foreground = p.status_warning_text } }, &.{.{ .text = "quiet", .monospace = true, .scale = mono_chip_scale }})
            else if (relayRttMs(index)) |ms|
                ui.paragraph(.{ .style = .{ .foreground = p.text_dim } }, &.{.{ .text = ui.fmt("{d} ms", .{ms}), .monospace = true, .scale = mono_chip_scale }})
            else
                ui.spacer(0),
            ui.spacer(1),
            ui.el(.list_item, .{
                .padding = 0.01,
                .height = 20,
                .cross = .center,
                .on_press = Msg{ .relay_cycle = @intCast(index) },
                .style = .{ .radius = 4, .border = p.border_chip, .stroke_width = 1 },
                .semantics = .{ .role = .button, .label = ui.fmt("Change what {s} is for", .{e.url()}), .focusable = true },
            }, .{
                hgap(ui, 5),
                ui.paragraph(.{ .style = .{ .foreground = p.text_muted_alt } }, &.{.{ .text = badge, .monospace = true, .scale = mono_badge_scale }}),
                hgap(ui, 5),
            }),
            hgap(ui, 8),
            ui.el(.list_item, .{
                .padding = 0.01,
                .height = 20,
                .cross = .center,
                .on_press = Msg{ .relay_remove = @intCast(index) },
                .style = .{ .radius = 4 },
                .semantics = .{ .role = .button, .label = ui.fmt("Remove {s}", .{e.url()}), .focusable = true },
            }, .{
                hgap(ui, 4),
                ui.icon(.{ .width = 11, .height = 11, .style = .{ .foreground = p.text_dim } }, "x"),
                hgap(ui, 4),
            }),
        }),
        vgap(ui, 9),
    });
}

/// The relays this reader's follows write to, offered as one press each. Empty
/// until a follow's kind:10002 has actually been read, because a suggestion the
/// app invented would just be another default wearing a recommendation's face.
///
/// The chips are packed into rows HERE rather than left to the layout, because
/// rows and columns in this engine never flow-wrap their children: `wrap` is a
/// line policy for text leaves and is silently inert on a container. This row
/// carried `.wrap = true` and a comment describing wrapping that never
/// happened, so six suggested relays ran to x=1372 in a 760 window, straight
/// off the right edge of the card and the window with it.
fn relaySuggestions(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const count = relaySuggestionCount();
    if (count == 0) return ui.spacer(0);
    const chips = ui.arena.alloc(AppUi.Node, count) catch return ui.spacer(0);
    const widths = ui.arena.alloc(f32, count) catch return ui.spacer(0);
    const tokens = theme.tokens(Model)(model);
    var n: usize = 0;
    for (0..count) |i| {
        var buf: [96]u8 = undefined;
        const url = relaySuggestionCopy(i, &buf) orelse continue;
        // The arena copy is what the frame renders: `buf` dies with this loop.
        var shown: []const u8 = ui.arena.dupe(u8, relayShortName(url)) catch continue;
        // Measured with the engine's own sizing, against the same tokens the
        // frame is laid out with, so the packing below agrees with what the
        // layout will actually do rather than with an estimate of it. A name too
        // long for a row of its own is shortened until it fits, rather than
        // allowed to hang off the card: the text is monospace, so cutting
        // characters cuts width in proportion, and each cut is re-measured so
        // the loop cannot talk itself into a width the engine disagrees with.
        var chip = suggestionChip(ui, i, shown, tokens);
        var attempts: usize = 0;
        while (chip.width > settings_content_width and shown.len > 8 and attempts < 8) : (attempts += 1) {
            const room: usize = @intFromFloat(@max(1, settings_content_width - relay_chip_chrome));
            const have: usize = @intFromFloat(@max(1, chip.width - relay_chip_chrome));
            const keep = @max(@as(usize, 7), (shown.len * room) / have -| 1);
            if (keep >= shown.len) break;
            shown = ui.fmt("{s}\u{2026}", .{shown[0..keep]});
            chip = suggestionChip(ui, i, shown, tokens);
        }
        chips[n] = chip.node;
        widths[n] = chip.width;
        n += 1;
    }
    if (n == 0) return ui.spacer(0);
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 10),
        ui.paragraph(
            .{ .style = .{ .foreground = p.text_dim } },
            &.{.{ .text = "Relays the people you read write to", .scale = mono_meta_scale }},
        ),
        vgap(ui, 6),
        chipRows(ui, chips[0..n], widths[0..n], settings_content_width, relay_chip_gap),
    });
}

/// A gap between suggestion chips, across and down.
const relay_chip_gap: f32 = 6;

/// Everything a chip is wider than its words: seven either side of the label
/// and the hairline border. Stated rather than measured, because the engine
/// does not measure a `.list_item` from its children at all: asking it for an
/// intrinsic size returns the chrome alone, which is how the first version of
/// this packing measured every chip at 24 points and put six of them on one
/// row. The label is measured for real; this is added to it, and the rule in
/// the suite holds the sum against a laid-out frame.
const relay_chip_chrome: f32 = 15;

/// One suggestion, as a chip, with the width it will actually take.
fn suggestionChip(ui: *AppUi, index: usize, shown: []const u8, tokens: canvas.DesignTokens) struct { node: AppUi.Node, width: f32 } {
    const p = theme.palette;
    const label = ui.paragraph(
        .{ .style = .{ .foreground = p.text_muted_alt } },
        &.{.{ .text = ui.fmt("+ {s}", .{shown}), .monospace = true, .scale = mono_chip_scale }},
    );
    const node = ui.el(.list_item, .{
        .padding = 0.01,
        .height = 22,
        .cross = .center,
        .on_press = Msg{ .relay_suggest = @intCast(index) },
        .style = .{ .radius = 5, .border = p.border_chip, .stroke_width = 1 },
        .semantics = .{ .role = .button, .label = ui.fmt("Add {s}", .{shown}), .focusable = true },
    }, .{
        hgap(ui, 7),
        label,
        hgap(ui, 7),
    });
    return .{ .node = node, .width = canvas.intrinsicWidgetSize(label.widget, tokens).width + relay_chip_chrome };
}

/// Packs pre-measured children into rows no wider than `limit`, greedily: the
/// flow layout the engine does not do. A child wider than the limit on its own
/// still gets a row to itself, because the alternative is dropping it.
fn chipRows(ui: *AppUi, chips: []const AppUi.Node, widths: []const f32, limit: f32, gap: f32) AppUi.Node {
    // At worst one chip per row, plus a gap row between each.
    const lines = ui.arena.alloc(AppUi.Node, chips.len * 2) catch return ui.spacer(0);
    var line_count: usize = 0;
    var first: usize = 0;
    var used: f32 = 0;
    var i: usize = 0;
    while (i < chips.len) {
        const next = if (i == first) widths[i] else used + gap + widths[i];
        if (i > first and next > limit) {
            if (line_count > 0) {
                lines[line_count] = vgap(ui, gap);
                line_count += 1;
            }
            lines[line_count] = ui.row(.{ .gap = gap }, .{chips[first..i]});
            line_count += 1;
            first = i;
            used = widths[i];
            i += 1;
            continue;
        }
        used = next;
        i += 1;
    }
    if (first < chips.len) {
        if (line_count > 0) {
            lines[line_count] = vgap(ui, gap);
            line_count += 1;
        }
        lines[line_count] = ui.row(.{ .gap = gap }, .{chips[first..chips.len]});
        line_count += 1;
    }
    return ui.column(.{ .gap = 0 }, .{lines[0..line_count]});
}

/// A relay URL with the scheme and any trailing slash taken off. The scheme is
/// the same on every row, so it is the part that carries no information.
pub fn relayShortName(url: []const u8) []const u8 {
    var out = url;
    if (std.mem.startsWith(u8, out, "wss://")) out = out["wss://".len..];
    return std.mem.trimEnd(u8, out, "/");
}

/// Where a relay is added, and where the ones your follows use are offered.
fn relayAddRow(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.inputGroup(
            .{ .semantics = .{ .label = "Add a relay" } },
            ui.el(.textarea, .{
                .text = model.relay_draft(),
                .placeholder = "wss://",
                .on_input = AppUi.inputMsg(.relay_edit),
                .on_submit = Msg.relay_add,
                .height = 30,
            }, .{}),
            ui.inputGroupActions(.{}, .{
                ui.paragraph(
                    .{ .wrap = true, .grow = 1, .style = .{ .foreground = p.text_dim } },
                    &.{.{ .text = model.relay_status(), .scale = mono_meta_scale }},
                ),
                ui.button(.{ .size = .sm, .on_press = Msg.relay_add }, "Add"),
            }),
        ),
        relaySuggestions(ui, model),
    });
}

/// The root view: one screen at a time, chosen by the stage, with an expanded
/// picture layered over it when one is open.
pub fn appView(ui: *AppUi, model: *const Model) AppUi.Node {
    const base = switch (model.stage) {
        .onboarding => OnboardingView.build(ui, model),
        // Settings layers OVER the feed rather than replacing it, like every
        // other sheet: the feed stays mounted and keeps its scroll offset, and
        // it is what the sheet's scrim has to blur to look like glass. Without
        // its thread levels, for the node-budget reason `feedView` states.
        .settings => feedView(ui, model, false),
        .ready => feedView(ui, model, true),
    };
    if (model.expanded_note) |note_id| {
        if (model.noteById(note_id)) |note| {
            // Layered OVER the feed rather than replacing it, so the scroll
            // region stays mounted and holds its offset. Swapping the tree out
            // unmounts it, and closing would drop the reader back at the top.
            return ui.stack(.{ .grow = 1 }, .{ base, imageViewer(ui, note) });
        }
    }
    if (model.stage == .ready and model.joining) {
        return ui.stack(.{ .grow = 1 }, .{ base, joinSheet(ui, model) });
    }
    if (model.stage == .ready and model.naming) {
        return ui.stack(.{ .grow = 1 }, .{ base, nameSheet(ui, model) });
    }
    if (model.notifications_open) {
        return ui.stack(.{ .grow = 1 }, .{ base, notificationsSheet(ui, model) });
    }
    if (model.stage == .settings) {
        // Both sheets, in order, when a profile is being edited: dropping the
        // one underneath would make Settings blink out and back as the reader
        // opens and closes the editor it was opened from.
        if (model.editing_profile) {
            return ui.stack(.{ .grow = 1 }, .{ base, settingsSheet(ui, model), profileSheet(ui, model) });
        }
        // The toast rides over Settings as well as over the feed. It was gated on
        // the feed alone, from when nothing in Settings could raise one; the
        // "Open Notary" control can, and its whole job on a refused press is to
        // say why nothing happened. A message that only appears on a screen the
        // reader is not looking at is the silent press it exists to prevent.
        if (model.toast_until != 0) {
            return ui.stack(.{ .grow = 1 }, .{ base, settingsSheet(ui, model), toastOverlay(ui, model) });
        }
        return ui.stack(.{ .grow = 1 }, .{ base, settingsSheet(ui, model) });
    }
    if (model.stage == .ready and model.composing) {
        return ui.stack(.{ .grow = 1 }, .{ base, composeSheet(ui, model) });
    }
    if (model.stage == .ready and model.toast_until != 0) {
        return ui.stack(.{ .grow = 1 }, .{ base, toastOverlay(ui, model) });
    }
    return base;
}

/// The name beat: one optional ask after creating an identity, so the account
/// is not blank. Fully skippable; the remembered intent replays either way.
fn nameSheet(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return ui.el(.dialog, .{
        .grow = 1,
        .padding = 16,
        .on_dismiss = .name_skip,
        .on_press = .name_skip,
        .style_tokens = .{ .background = .scrim },
        .semantics = .{ .label = "Name" },
    }, .{
        ui.row(.{ .grow = 1, .main = .center, .cross = .start }, .{
            modalCard(ui, name_card_width, ui.column(.{ .grow = 1, .gap = 10, .padding = 16 }, .{
                ui.paragraph(
                    .{ .style = .{ .foreground = p.text_primary } },
                    &.{.{ .text = "Want a name on it?", .weight = .bold, .scale = name_title_scale }},
                ),
                ui.paragraph(
                    .{ .wrap = true, .style = .{ .foreground = p.text_muted } },
                    &.{.{ .text = "Shown with your notes. Change it any time.", .scale = join_sub_scale }},
                ),
                ui.el(.textarea, .{
                    .text = model.name_draft(),
                    .placeholder = "A name people will see",
                    .on_input = AppUi.inputMsg(.name_edit),
                    .autofocus = true,
                    .on_submit = .name_save,
                    .height = 38,
                    .style = .{ .background = p.surface_input, .border = p.border_focus, .radius = 9, .stroke_width = 1.5 },
                }, .{}),
                ui.row(.{ .gap = 0, .cross = .center }, .{
                    // Never disabled. Blank is a valid answer to "want a name on
                    // it?", and it means the same thing as Skip, so Done takes it
                    // and moves on rather than sitting there greyed out while the
                    // reader wonders what is wrong with an empty field.
                    // Painted by a `.panel`, pressed by the row around it. A
                    // `.list_item` given a background draws none, so the first
                    // version of this button was white text on the card's own
                    // dark surface: present, pressable, and unreadable.
                    ui.row(.{
                        .grow = 1,
                        .gap = 0,
                        .on_press = Msg.name_save,
                        .semantics = .{ .role = .button, .label = "Done", .focusable = true },
                    }, .{
                        ui.el(.panel, .{
                            .grow = 1,
                            .padding = 0.01,
                            .style = .{ .background = p.accent, .radius = 8 },
                        }, .{
                            ui.row(.{ .height = 32, .cross = .center, .main = .center, .gap = 0 }, .{
                                ui.paragraph(
                                    .{ .style = .{ .foreground = p.on_accent } },
                                    &.{.{ .text = "Done", .weight = .medium, .scale = menu_scale }},
                                ),
                            }),
                        }),
                    }),
                    hgap(ui, 12),
                    ui.el(.list_item, .{
                        .padding = 0.01,
                        .on_press = Msg.name_skip,
                        .style = .{ .quiet_hover = true },
                        .semantics = .{ .role = .button, .label = "Skip", .focusable = true },
                    }, .{
                        ui.paragraph(
                            .{ .style = .{ .foreground = p.text_muted } },
                            &.{.{ .text = "Skip", .underline = true, .scale = menu_scale }},
                        ),
                    }),
                }),
            })),
        }),
    });
}

/// The Edit profile sheet. No mock draws it, so it is the modal-card recipe with
/// three fields; flagged in the PR for review.
///
/// The status line under the fields is the point of the sheet, not decoration: a
/// profile is REPLACEABLE, so saving rewrites the whole thing, and the sheet must
/// be able to say whether it actually has the reader's current profile to rewrite.
fn profileSheet(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const status = model.profile_status();
    return ui.el(.dialog, .{
        .grow = 1,
        .padding = 16,
        .on_dismiss = Msg.close_profile_edit,
        .on_press = Msg.close_profile_edit,
        .style_tokens = .{ .background = .scrim },
        .semantics = .{ .label = "Edit profile" },
    }, .{
        ui.row(.{ .grow = 1, .main = .center, .cross = .start }, .{
            modalCard(ui, 400, ui.column(.{ .grow = 1, .gap = 10, .padding = 20 }, .{
                ui.paragraph(
                    .{ .style = .{ .foreground = p.text_primary } },
                    &.{.{ .text = "Edit profile", .weight = .bold, .scale = 1.15 }},
                ),
                ui.paragraph(
                    .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
                    &.{.{ .text = "Your name, a line about you, and a picture. Anything else your other clients put in your profile is kept exactly as it is.", .scale = mono_hint_scale }},
                ),
                profileField(ui, "Name", model.profile_name(), "A name people will see", .profile_name_edit),
                profileField(ui, "About", model.profile_about(), "A line about you", .profile_about_edit),
                profileField(ui, "Picture", model.profile_picture(), "https://", .profile_picture_edit),
                if (status.len > 0)
                    ui.paragraph(
                        .{ .wrap = true, .style = .{ .foreground = if (model.profile_stage == .failed) p.status_warning_text else p.text_dim } },
                        &.{.{ .text = status, .scale = mono_hint_scale }},
                    )
                else
                    ui.spacer(0),
                ui.row(.{ .gap = 8, .cross = .center }, .{
                    ui.button(.{ .size = .sm, .variant = .ghost, .autofocus = true, .on_press = Msg.close_profile_edit }, "Close"),
                    ui.spacer(1),
                    if (model.profile_stage == .unread)
                        ui.button(.{ .size = .sm, .variant = .ghost, .on_press = Msg.profile_retry }, "Try again")
                    else
                        ui.spacer(0),
                    if (model.profile_stage == .unread) hgap(ui, 8) else ui.spacer(0),
                    ui.button(.{
                        .size = .sm,
                        .variant = .primary,
                        .disabled = !model.profile_can_save(),
                        .on_press = Msg.profile_save,
                    }, "Save"),
                }),
            })),
        }),
    });
}

/// One labelled field in the sheet.
fn profileField(ui: *AppUi, label: []const u8, value: []const u8, placeholder: []const u8, comptime tag: std.meta.Tag(Msg)) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.paragraph(.{ .style = .{ .foreground = p.text_label } }, &.{.{ .text = label, .monospace = true, .scale = mono_meta_scale }}),
        vgap(ui, 5),
        ui.el(.textarea, .{
            .text = value,
            .placeholder = placeholder,
            .on_input = AppUi.inputMsg(tag),
            // REQUIRED, and not decoration: a textarea with on_input but no
            // on_submit renders, focuses, advertises set_text, and accepts
            // nothing. It reads as a live field and is inert.
            .on_submit = Msg.profile_save,
            .height = 34,
            .semantics = .{ .label = label },
        }, .{}),
    });
}

/// What people did that was aimed at the reader.
///
/// A plain capped column, deliberately NOT a virtual list. The runtime tracks at
/// most eight virtual windows per build and the app already declares all eight
/// at a full back stack, so a ninth here would be dropped: the list would render
/// once and then stop rebuilding as the reader scrolled, which reads as content
/// that vanishes. A page is capped and replaced rather than appended, which is
/// the same answer the thread reached for the same reason.
fn notificationsSheet(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    var buf: [inbox_cap]InboxItem = undefined;
    resolveInboxBodies();
    const shown = inboxItems(&buf, !model.notifications_everyone);

    // A windowed list, not pages. Paging existed because every row was mounted
    // at once and the whole view is priced against a 1024-node ceiling that
    // refuses a frame WHOLE when crossed, so twenty rows was the arithmetic that
    // fit. A window mounts only what is on screen, which removes the ceiling as
    // a constraint and the pager with it: two hundred notifications are one
    // scroll rather than ten presses of a Next button.
    const options: AppUi.VirtualListOptions = .{
        .id = "notifications",
        .item_count = shown.len,
        .item_extent = 0,
        .extent_estimate = notificationExtentEstimate,
        .extent_context = &shown_ctx,
        .gap = 0,
        .padding = 0,
        .overscan = 3,
        .grow = 1,
        .viewport_fallback = window_height,
        .semantics = .{ .label = "Notifications list" },
    };
    shown_ctx = .{ .items = shown };
    const window = ui.virtualWindow(options);
    g_inbox_visible = .{
        .first = @intCast(window.first_visible_index),
        .last = @intCast(window.last_visible_index),
        .len = shown.len,
    };
    // After the window, because it asks on behalf of the rows the window chose.
    wantInboxProfiles(shown);
    const rows = ui.arena.alloc(AppUi.Node, window.itemCount()) catch return ui.spacer(0);
    // Centred ONCE, around the list, never per row. A spacer-column-spacer
    // wrapper on each row is four nodes apiece, and fourteen mounted rows of
    // that is fifty-six nodes spent on horizontal alignment: enough on its own
    // to push this view through the 1024 ceiling that refuses a frame whole.
    for (rows, 0..) |*row, offset| {
        const i = window.start_index + offset;
        row.* = if (i < shown.len) notificationRow(ui, &shown[i]) else ui.spacer(0);
    }

    return ui.column(.{
        .grow = 1,
        .style_tokens = .{ .background = .background },
        .semantics = .{ .label = "Notifications" },
    }, .{
        notificationsHeader(ui),
        ui.el(.separator, .{ .style = .{ .background = p.divider_chrome } }, .{}),
        notificationsTabs(ui, model),
        if (shown.len == 0) notificationsEmpty(ui, model) else ui.spacer(0),
        ui.row(.{ .grow = 1, .gap = 0 }, .{
            ui.spacer(1),
            // Width only, never grow. In a row, grow claims the remaining
            // horizontal space and beats the fixed width: 620 resolved to 853
            // and ran 153px past the edge of the narrowest allowed window.
            // The row's cross-axis stretch is what gives it its height.
            ui.column(.{ .width = notifications_column_width }, .{
                ui.virtualList(options, window, .{rows}),
            }),
            ui.spacer(1),
        }),
        notificationsFooter(ui, shown.len),
    });
}

/// The rows the notifications window is measuring, so the extent callback can
/// price one without the view handing it a closure.
const NotificationCtx = struct { items: []const InboxItem = &.{} };
var shown_ctx: NotificationCtx = .{};

/// A cheap height for the notification at `index`, from the item alone: the
/// row's chrome plus however many lines its body wraps to.
fn notificationExtentEstimate(context: ?*const anyopaque, index: u64) f32 {
    const ctx: *const NotificationCtx = @ptrCast(@alignCast(context orelse return 64));
    const i: usize = @intCast(index);
    if (i >= ctx.items.len) return 64;
    const item = &ctx.items[i];
    // 12 padding top and bottom, the name line, the time line, and the body.
    var extent: f32 = 12 * 2 + body_line_height + body_line_height + 6;
    if (item.body_len > 0) {
        const per_line: f32 = 58;
        const lines = @max(1.0, @ceil(@as(f32, @floatFromInt(item.body_len)) / per_line));
        extent += lines * body_line_height;
    }
    return extent;
}

/// The reading column for notifications, matching the feed's so a row is the
/// same width whichever screen it is on.
const notifications_column_width: f32 = feed_column_width;
pub const notifications_column_width_for_test = notifications_column_width;

/// How many rows the sheet draws at once.
///
/// This is a NODE budget, not a taste in page sizes. The sheet is stacked over
/// the feed rather than replacing it, because the feed's scroll offset lives in
/// its mounted list, so both trees are priced against the same 1024-node view
/// ceiling and a view past it is refused WHOLE: no frame at all, a window that
/// stops updating. The base costs about 413 nodes on the feed and about 573 over
/// a full back stack, the sheet's own chrome about 40, and a row eleven. Twenty
/// rows is 832 in the worst case, which leaves real margin rather than the nine
/// nodes the first arithmetic here left.
///
/// Pages REPLACE rather than accumulate, so this is the cost whether the reader
/// holds five notifications or two hundred, and all two hundred are reachable
/// instead of the first forty-eight.
///
/// Twenty, until the verb row under a note grew from four glyphs to six and the
/// base under this sheet grew with it. That is what this number IS: a budget,
/// not a taste in page sizes, and a budget whose inputs moved. Measured rather
/// than estimated this time, over every frame the app can draw: at twenty this
/// sheet over the deepest thread came to 922 of 1024, which is inside the
/// ceiling and outside the tenth of it the suite insists stays free.
pub const inbox_page = 16;

fn notificationsHeader(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.row(.{ .cross = .center, .gap = 10, .height = 38, .padding = 0.01 }, .{
            hgap(ui, 10),
            // A page needs a way out. As a sheet this had the scrim to press and
            // Escape to dismiss; an opaque level has neither, so closing it was
            // the bell in a rail the page was covering.
            ui.el(.list_item, .{
                .padding = 0.01,
                .cross = .center,
                .on_press = Msg.close_notifications,
                .style = .{ .radius = 6, .quiet_hover = true },
                .semantics = .{ .role = .button, .label = "Back", .focusable = true },
            }, .{
                ui.row(.{ .cross = .center, .gap = 0 }, .{
                    hgap(ui, 6),
                    ui.icon(.{ .width = 14, .height = 14, .style = .{ .foreground = p.text_muted } }, "chevron-left"),
                    hgap(ui, 4),
                    ui.paragraph(.{ .style = .{ .foreground = p.text_muted } }, &.{.{ .text = "Back", .scale = stat_scale }}),
                    hgap(ui, 8),
                    vgap(ui, 26),
                }),
            }),
            hgap(ui, 4),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_primary } },
                &.{.{ .text = "Notifications", .weight = .bold, .scale = settings_title_scale }},
            ),
            ui.spacer(1),
            ui.el(.list_item, .{
                .padding = 0.01,
                .height = 20,
                .cross = .center,
                .on_press = Msg.notifications_read_all,
                .style = .{ .radius = 4 },
                .semantics = .{ .role = .button, .label = "Mark all read", .focusable = true },
            }, .{
                ui.paragraph(.{ .style = .{ .foreground = p.text_muted_alt } }, &.{.{ .text = "Mark all read", .scale = status_scale }}),
            }),
            hgap(ui, 14),
        }),
        ui.el(.separator, .{ .style = .{ .background = p.divider_row } }, .{}),
    });
}

/// Two tabs, and the reason there are two: an inbox is the one surface where a
/// stranger decides what the reader sees, so the default holds only people they
/// already read.
fn notificationsTabs(ui: *AppUi, model: *const Model) AppUi.Node {
    return ui.row(.{ .cross = .center, .gap = 6, .padding = 0.01 }, .{
        hgap(ui, 14),
        vgap(ui, 42),
        profileTabFocused(ui, "Everyone", model.notifications_everyone, Msg{ .notifications_tab = 1 }, true),
        profileTab(ui, "People you follow", !model.notifications_everyone, Msg{ .notifications_tab = 0 }),
        ui.spacer(1),
    });
}

fn notificationsEmpty(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const text: []const u8 = if (model.notifications_everyone)
        "Nothing yet. When somebody replies, mentions, likes, reposts or zaps you, it lands here."
    else
        "Nothing from the people you follow yet. Everyone is in the other tab.";
    return ui.row(.{ .gap = 0, .padding = 14 }, .{
        ui.paragraph(.{ .wrap = true, .style = .{ .foreground = p.text_dim } }, &.{.{ .text = text, .scale = mono_hint_scale }}),
    });
}

fn notificationsFooter(ui: *AppUi, count: usize) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.el(.separator, .{ .style = .{ .background = p.divider_row } }, .{}),
        ui.row(.{ .cross = .center, .gap = 0, .height = 30, .padding = 0.01 }, .{
            hgap(ui, 14),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_dim } },
                &.{.{ .text = ui.fmt("{d} here", .{count}), .monospace = true, .scale = mono_meta_scale }},
            ),
            ui.spacer(1),
            // Said plainly, because it is a real limitation rather than a
            // detail: another client will not know what has been read here.
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_dim } },
                &.{.{ .text = "read state stays on this Mac", .monospace = true, .scale = mono_meta_scale }},
            ),
            hgap(ui, 14),
        }),
    });
}

/// How long ago this landed, in the app's one spelling of it.
fn inboxAge(ui: *AppUi, created_at: i64) []const u8 {
    var buf: [16]u8 = undefined;
    const written = Note.ageInto(&buf, created_at, nowSeconds()) catch return "";
    return ui.arena.dupe(u8, written) catch "";
}

/// One thing somebody did.
fn notificationRow(ui: *AppUi, item: *const InboxItem) AppUi.Node {
    const p = theme.palette;
    const read = item.created_at <= inboxReadThrough();
    const glyph: []const u8 = switch (item.verb) {
        .reply, .mention => "reply",
        .like => "like",
        .repost => "repeat",
        .zap => "zap",
    };
    const tint = switch (item.verb) {
        .zap => p.status_warning,
        .repost => p.status_success,
        .like => p.status_like,
        else => p.text_muted_alt,
    };
    // A reply says only the name. "replied to you" above a row that already
    // shows their reply is the same fact twice.
    const verb_text: []const u8 = switch (item.verb) {
        .reply => "",
        .mention => "mentioned you in a note",
        .like => "reacted to your note",
        .repost => "reposted your note",
        .zap => "zapped your note",
    };
    const body = item.body();
    const emoji = item.reactionGlyph();

    // Name, verb and amount are SPANS of one paragraph, not three paragraphs.
    // The row is priced in widget nodes against a per-view ceiling that refuses
    // the whole screen when crossed, and the first cut of this row spent five
    // extra nodes apiece on things that are only text: twenty rows of that put
    // the notifications view at 924 against a ceiling of 1024 with 102 that has
    // to stay free. Spans cost nothing.
    var head: [3]canvas.TextSpan = undefined;
    var head_len: usize = 0;
    head[head_len] = .{ .text = personName(ui, item.author), .weight = .medium, .scale = nested_meta_scale };
    head_len += 1;
    if (verb_text.len > 0) {
        head[head_len] = .{ .text = ui.fmt(" {s}", .{verb_text}), .scale = nested_meta_scale };
        head_len += 1;
    }
    if (item.verb == .zap and item.msat > 0) {
        head[head_len] = .{ .text = ui.fmt("  {d} sats", .{item.msat / 1000}), .weight = .medium, .scale = nested_meta_scale };
        head_len += 1;
    }

    // Built by hand rather than with an `else ui.spacer(0)` per optional child,
    // because an empty spacer is still a node and this row has three of them.
    var kids: [3]AppUi.Node = undefined;
    var kids_len: usize = 0;
    kids[kids_len] = ui.el(.list_item, .{
        .padding = 0.01,
        .on_press = Msg{ .open_person = item.author },
        .style = .{ .radius = 4, .quiet_hover = true },
        .semantics = .{ .role = .button, .label = "Open profile", .focusable = true },
    }, .{
        ui.paragraph(.{ .style = .{ .foreground = p.text_body_soft } }, head[0..head_len]),
    });
    kids_len += 1;
    if (body.len > 0) {
        // Theirs for a reply, yours for everything else, and dimmer when it is
        // yours: you wrote it, so the new fact is who did what to it.
        const own = item.verb != .reply and item.verb != .mention;
        // Two lines and stop, cut in the spans before layout because the SDK
        // has no multi-line clamp. The same rule an ancestor's body follows, so
        // a long note cannot turn one notification into half a screen.
        // Through the same renderer the feed uses, so a `nostr:npub…` reads as a
        // name and a `nostr:nevent…` does not dump sixty characters of bech32
        // into the preview. It was raw before, which is the one thing a preview
        // must not be.
        const spans = clampSpansToLines(ui, contentSpans(ui, body), notification_body_lines);
        kids[kids_len] = ui.paragraph(
            .{ .wrap = true, .style = .{ .foreground = if (own) p.text_muted_alt else p.text_body } },
            spans,
        );
        kids_len += 1;
    }
    kids[kids_len] = ui.paragraph(
        .{ .style = .{ .foreground = p.text_faint_alt } },
        &.{.{ .text = inboxAge(ui, item.created_at), .monospace = true, .scale = mono_meta_scale }},
    );
    kids_len += 1;

    return ui.column(.{ .gap = 0 }, .{
        ui.el(.data_row, .{
            .padding = 12,
            .gap = 10,
            // Top aligned: the row is several lines now, and a gutter glyph
            // floating beside the middle of a paragraph belongs to nothing.
            .cross = .start,
            // `open_event`, never `open_thread`. The thread route resolves an id
            // against the LOADED FEED, which is scoped to follows and holds at
            // most a few hundred notes; what a notification points at is almost
            // always an older note of the reader's own, or a stranger's note the
            // feed would never carry. So the obvious route made the common press
            // a silent no-op. This one asks the store by name.
            .on_press = if (item.hasTarget()) Msg{ .open_event = item.target_id } else Msg{ .open_person = item.author },
            .style = .{ .quiet_hover = true },
            .semantics = .{ .role = .button, .label = if (verb_text.len > 0) verb_text else "replied to you", .focusable = true },
        }, .{
            // The unread dot holds its width either way, so a row does not shift
            // sideways the moment it is read.
            ui.el(.panel, .{
                .width = 6,
                .height = 6,
                .padding = 0.01,
                .style = .{
                    .background = if (read) p.surface_window else p.accent,
                    .border = if (read) p.surface_window else p.accent,
                    .radius = 3,
                    .stroke_width = 0,
                },
            }, .{}),
            // Glyph and face together, centred against EACH OTHER, and that pair
            // top-aligned against the text. The row's own `.cross = .start` is
            // right for the avatar, which should hang beside the name and the
            // first line of the body, and wrong for a 14pt glyph, which then
            // floated at the very top with nothing beside it.
            ui.row(.{ .cross = .center, .gap = 10 }, .{
                // The reaction they actually sent, where a generic heart used to
                // be. A shortcode with no image would print as `:shakingeyes:`,
                // so only something short enough to read as a glyph is drawn.
                if (item.verb == .like and emoji.len > 0 and emoji.len <= 8)
                    ui.paragraph(.{ .style = .{ .foreground = p.text_body } }, &.{.{ .text = emoji, .scale = nested_meta_scale }})
                else
                    ui.appIcon(.{ .width = 14, .height = 14, .style = .{ .foreground = tint } }, glyph),
                // The face and the name go to the person, everything else goes
                // to the note. That is what the feed does and what Jumble does,
                // and without it the one thing a notification is most likely to
                // make you want (who IS this) was the one thing you could not
                // press.
                ui.el(.list_item, .{
                    .padding = 0.01,
                    .on_press = Msg{ .open_person = item.author },
                    .style = .{ .radius = 999, .quiet_hover = true },
                    .semantics = .{ .role = .button, .label = "Open profile", .focusable = true },
                }, .{
                    personAvatar(ui, item.author, nested_avatar_size),
                }),
            }),
            ui.column(.{ .gap = 3, .grow = 1 }, kids[0..kids_len]),
        }),
        ui.el(.separator, .{ .style = .{ .background = p.divider_row } }, .{}),
    });
}

/// A small confirming toast, bottom center, retired by the tick.
fn toastOverlay(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .grow = 1, .main = .end, .cross = .center, .padding = 24 }, .{
        ui.row(.{ .padding = 10, .style = .{ .background = p.surface_toast, .border = p.border_modal, .radius = 10, .stroke_width = 1 } }, .{
            ui.text(.{ .size = .sm, .style = .{ .foreground = p.text_body } }, model.toast_text()),
        }),
    });
}

/// The first-intent sheet: the join ladder over the dimmed feed. Three ways in,
/// most confident first, and always the way back to reading. When the guest
/// reached for the composer, the sheet says the note is waiting.
fn joinSheet(ui: *AppUi, model: *const Model) AppUi.Node {
    return ui.el(.dialog, .{
        .grow = 1,
        .padding = 16,
        .on_dismiss = .close_join,
        .on_press = .close_join,
        .style_tokens = .{ .background = .scrim },
        .semantics = .{ .label = "Join" },
    }, .{
        ui.row(.{ .grow = 1, .main = .center, .cross = .start }, .{
            // 40px down from the window, which is the design's offset: 16 of it is
            // the dialog's own padding, so this is the rest.
            ui.column(.{ .gap = 0 }, .{
                vgap(ui, 24),
                if (model.bunker_mode) bunkerCard(ui, model) else joinLadderCard(ui, model),
            }),
        }),
    });
}

/// Why the sheet appeared, in the reader's own terms: the thing they reached for
/// is waiting, and named where naming it is possible.
///
/// A note that has scrolled out of the loaded window falls back to the plain
/// sentence rather than guessing, and a person whose kind:0 has not arrived reads
/// as their short npub, which is what every other surface in the app calls them
/// until it knows better.
fn pendingText(ui: *AppUi, model: *const Model) []const u8 {
    return switch (model.pending) {
        .none => "",
        .post => "Your note is waiting.",
        .reply => "Your reply is waiting.",
        // Clipped, because a display name is a stranger's string with no length
        // in it and no alphabet either. The pill wraps as well (see intentPill):
        // a codepoint cap bounds COUNT, not WIDTH, and fourteen full-width CJK
        // characters are about twice fourteen Latin ones, so the clip alone still
        // overran the card in some scripts.
        .like => |id| if (model.noteById(id)) |note|
            std.fmt.allocPrint(ui.arena, "Your like on {s}'s note is waiting.", .{personLabel(ui, note.author())}) catch "Your like is waiting."
        else
            "Your like is waiting.",
        .follow => |pk| std.fmt.allocPrint(ui.arena, "Following {s} is waiting.", .{personLabel(ui, personName(ui, pk))}) catch "Your follow is waiting.",
    };
}

/// A person's name, short enough for one line of a pill.
///
/// The npub fallback is passed through UNCLIPPED. It is already an abbreviation,
/// `npub1abcdefghi…wxyz5`, and its whole job is the tail: clipping it to fourteen
/// codepoints ate three of the five identifying characters at the end and left
/// something that looks specific and is not.
fn personLabel(ui: *AppUi, name: []const u8) []const u8 {
    _ = ui;
    // The abbreviated npub carries an ellipsis, and it is the only thing in this
    // app that does. Substring, not scalar: the character is three bytes.
    if (std.mem.indexOf(u8, name, "…") != null) return name;
    return clipToChars(name, 14, 48);
}

/// The glyph for the verb that opened the sheet: the reader sees what they
/// reached for before they read a word.
///
/// A switch rather than a name looked up from a table, because both icon
/// builders take their name at COMPTIME (that is what compile-checks it), so a
/// glyph chosen at runtime has to be chosen as a whole node.
fn pendingGlyph(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const size = 11;
    return switch (model.pending) {
        .none, .post => ui.icon(.{ .width = size, .height = size, .style = .{ .foreground = p.text_muted } }, "edit"),
        .reply => ui.appIcon(.{ .width = size, .height = size, .style = .{ .foreground = p.text_muted } }, "reply"),
        .like => ui.appIcon(.{ .width = size, .height = size, .style = .{ .foreground = p.status_like } }, "like"),
        .follow => ui.icon(.{ .width = size, .height = size, .style = .{ .foreground = p.text_muted } }, "plus"),
    };
}

/// What the reader reached for, as a pill above the question.
fn intentPill(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return ui.row(.{ .gap = 0 }, .{
        ui.el(.panel, .{
            .grow = 1,
            .padding = 0.01,
            .style = .{ .background = p.surface_chip, .border = p.border_hairline, .radius = 999, .stroke_width = 1 },
        }, .{
            ui.row(.{ .cross = .center, .gap = 0 }, .{
                hgap(ui, 10),
                vgap(ui, 22),
                pendingGlyph(ui, model),
                hgap(ui, 6),
                // Bounded AND wrapping. `wrap` on its own does nothing to a
                // paragraph that is a plain flow child of a row (it takes its
                // intrinsic width and lays out past the card), and a clip on its
                // own bounds characters rather than pixels. Both, so no name in
                // any script can push this line out of the sheet.
                ui.column(.{ .grow = 1, .gap = 0 }, .{
                    ui.paragraph(
                        .{ .wrap = true, .style = .{ .foreground = p.text_muted_alt } },
                        &.{.{ .text = model.pending_text(ui), .scale = join_sub_scale }},
                    ),
                }),
                hgap(ui, 10),
            }),
        }),
        // The pill is as wide as its words and no wider, so the row it sits in
        // takes the slack rather than the pill stretching across the card.
        ui.spacer(1),
    });
}

/// One rung of the ladder: a glyph, what it is, and what it costs you.
///
/// `filled` is the recommended one, and there is exactly one. The other two are
/// outlines with a chevron, which is the shape this app uses everywhere else for
/// "this leads somewhere".
///
/// A null `press` is a rung this install cannot climb (see `keyholderMissing`).
/// It keeps the card's geometry so the ladder does not jump, and gives up
/// everything that says "press me": the accent fill, the chevron, the button
/// role, the focus stop. A rung that looks identical and does nothing is the
/// exact failure this whole change is about, so it must not merely stop working,
/// it has to stop LOOKING like it works.
fn joinCard(ui: *AppUi, comptime glyph: []const u8, comptime app: bool, title: []const u8, sub: []const u8, press: ?Msg, filled: bool) AppUi.Node {
    const p = theme.palette;
    const live = press != null;
    const ink = if (filled) p.on_accent else if (live) p.text_body_strong else p.text_muted;
    const sub_ink = if (filled) p.text_dim_on_light else p.text_muted;
    // The press is on the ROW and the paint is on a `.panel` inside it. A
    // `.list_item` carrying a background draws nothing at all (the same rule
    // `modalCard` is built around), so the first version of this card had the
    // recommended rung rendering as invisible white-on-black text.
    return ui.row(.{
        .gap = 0,
        .on_press = press,
        .semantics = .{ .role = if (live) .button else .text, .label = title, .focusable = live },
    }, .{
        ui.el(.panel, .{
            .grow = 1,
            .padding = 0.01,
            .style = .{
                .background = if (filled) p.accent else p.surface_card,
                .border = if (filled) p.accent else p.border_control,
                .radius = 11,
                .stroke_width = 1,
            },
        }, .{
            ui.row(.{ .cross = .center, .gap = 0 }, .{
                hgap(ui, 13),
                if (app)
                    ui.appIcon(.{ .width = 16, .height = 16, .style = .{ .foreground = ink } }, glyph)
                else
                    ui.icon(.{ .width = 16, .height = 16, .style = .{ .foreground = ink } }, glyph),
                hgap(ui, 11),
                ui.column(.{ .grow = 1, .gap = 0 }, .{
                    vgap(ui, 11),
                    ui.paragraph(
                        .{ .style = .{ .foreground = ink } },
                        &.{.{ .text = title, .weight = .medium, .scale = join_card_title_scale }},
                    ),
                    vgap(ui, 3),
                    ui.paragraph(
                        .{ .wrap = true, .style = .{ .foreground = sub_ink } },
                        &.{.{ .text = sub, .scale = join_card_sub_scale }},
                    ),
                    vgap(ui, 11),
                }),
                hgap(ui, 11),
                // Only on the rungs that lead to another step. The filled card
                // finishes here: pressing it makes a key. A dead rung leads
                // nowhere at all, so it gets no chevron either.
                if (filled or !live) ui.spacer(0) else ui.icon(.{ .width = 12, .height = 12, .style = .{ .foreground = p.text_faint_alt } }, "chevron-right"),
                hgap(ui, 13),
            }),
        }),
    });
}

/// The mono section labels over each half of the ladder.
fn joinLabel(ui: *AppUi, text: []const u8) AppUi.Node {
    const p = theme.palette;
    return ui.paragraph(
        .{ .style = .{ .foreground = p.text_faint_alt } },
        &.{.{ .text = text, .monospace = true, .weight = .medium, .scale = join_label_scale }},
    );
}

/// The shared modal card: the SDK `.card` element paints the rounded, bordered
/// surface (a plain column does not paint its background at all), holding a
/// single content column so the sheet reads as a raised, bordered panel.
///
/// The press it absorbs is load-bearing, not decoration: the sheet around it is
/// a full-window dialog that closes when pressed, and a `.card` claims no press
/// of its own, so without this a click on the sheet's own background walks past
/// the card to the dialog and closes the sheet mid-use. See `Msg.absorb_press`.
fn modalCard(ui: *AppUi, width: f32, inner: AppUi.Node) AppUi.Node {
    const p = theme.palette;
    return ui.el(.card, .{
        .width = width,
        .on_press = Msg.absorb_press,
        .style = .{ .background = p.surface_modal, .border = p.border_modal, .radius = 14, .stroke_width = 1 },
    }, .{inner});
}

/// The join ladder: three ways in, most confident first, always the way back.
fn joinLadderCard(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return modalCard(ui, join_sheet_width, ui.column(.{ .grow = 1, .gap = 0 }, .{
        vgap(ui, 16),
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, 16),
            ui.column(.{ .grow = 1, .gap = 0 }, .{
                if (model.pending.waiting()) intentPill(ui, model) else ui.spacer(0),
                if (model.pending.waiting()) vgap(ui, 11) else ui.spacer(0),
                ui.paragraph(
                    .{ .style = .{ .foreground = p.text_primary } },
                    &.{.{ .text = "How do you want to join?", .weight = .bold, .scale = join_title_scale }},
                ),
                vgap(ui, 6),
                ui.paragraph(
                    .{ .wrap = true, .style = .{ .foreground = p.text_muted } },
                    &.{.{ .text = "Everything here is signed with a key of your own, not an account someone holds for you.", .scale = join_sub_scale }},
                ),
                vgap(ui, 13),
                joinLabel(ui, "NEW HERE"),
                vgap(ui, 6),
                // Making a key means the keyholder daemon making it, so with no
                // keyholder installed there is no route to a new identity at
                // all: this rung is not degraded, it is impossible. Say that,
                // and say what fixes it, rather than leaving the app's primary
                // call to action sitting there swallowing presses.
                //
                // The WHY goes under the card, not in it. A rung's subtitle is
                // one line: the row that holds it centres a column it has
                // already been sized against, so a subtitle that wraps to three
                // lines runs 7px past the card's own bottom edge and paints the
                // last line half outside it. The tree cannot see that (the
                // string is all there, in one node, correctly nested) and every
                // structural assertion passed over it. Only the frames say so,
                // which is what "the ladder's rungs hold their own copy" now
                // asserts. Down here it is a plain flow child of the sheet's
                // column, where wrapping is bounded and behaves.
                if (keyholderMissing())
                    joinCard(ui, "plus", false, "Create your identity", "Not possible in this copy of Plaza.", null, false)
                else
                    joinCard(ui, "plus", false, "Create your identity", "Ready in seconds. Nothing to write down.", .join_create, true),
                if (keyholderMissing()) vgap(ui, 7) else ui.spacer(0),
                if (keyholderMissing())
                    ui.paragraph(
                        .{ .wrap = true, .style = .{ .foreground = p.text_muted } },
                        &.{.{ .text = "Notary, the part of Plaza that holds your key, is missing from this install, so Plaza cannot make one. Reinstalling Plaza fixes it.", .scale = join_card_sub_scale }},
                    )
                else
                    ui.spacer(0),
                vgap(ui, 13),
                joinLabel(ui, "ALREADY ON NOSTR"),
                vgap(ui, 6),
                // Bringing a key still works with no keyholder: the paste lands
                // in this process instead (see `.open_notary_import`). It is a
                // weaker promise than the one this line normally makes, so the
                // line changes with it. Selling Notary's isolation and then
                // taking the nsec into a Plaza text field would be the copy
                // lying about where the key went.
                if (keyholderMissing())
                    joinCard(ui, "download", false, "Bring your key", "Pasted here, and kept on this device.", .open_notary_import, false)
                else
                    joinCard(ui, "download", false, "Bring your key", "Goes into Notary. Plaza itself never sees it.", .open_notary_import, false),
                vgap(ui, 8),
                joinCard(ui, "notary", true, "Use your own signer", "Paste the bunker link it gives you.", .open_bunker, false),
                vgap(ui, 13),
                ui.row(.{ .cross = .center, .gap = 0 }, .{
                    ui.el(.list_item, .{
                        .padding = 0.01,
                        .on_press = Msg.close_join,
                        .style = .{ .quiet_hover = true },
                        .autofocus = true,
                        .semantics = .{ .role = .button, .label = "Keep browsing", .focusable = true },
                    }, .{
                        ui.paragraph(
                            .{ .style = .{ .foreground = p.text_secondary } },
                            &.{.{ .text = "Keep browsing", .weight = .medium, .underline = true, .scale = menu_scale }},
                        ),
                    }),
                    hgap(ui, 10),
                    ui.paragraph(
                        .{ .style = .{ .foreground = p.text_dim } },
                        &.{.{ .text = "reading never needs an identity", .monospace = true, .scale = mono_chip_scale }},
                    ),
                    ui.spacer(1),
                }),
            }),
            hgap(ui, 16),
        }),
        vgap(ui, 13),
    }));
}

/// The focused bunker step: the user already chose to use their own signer, so
/// this is one field, not the whole ladder again. Paste the link, connect.
fn bunkerCard(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return modalCard(ui, 372, ui.column(.{ .grow = 1, .gap = 12, .padding = 20 }, .{
        ui.row(.{ .cross = .center, .gap = 6 }, .{
            backControl(ui, "Back", .close_bunker),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_primary } },
                &.{.{ .text = "Connect your signer", .weight = .bold, .scale = 1.3 }},
            ),
        }),
        ui.text(.{ .size = .sm, .wrap = true, .style = .{ .foreground = p.text_muted } }, "Paste the bunker link your signer gave you. Your key stays in your signer, Plaza never sees it."),
        ui.el(.textarea, .{
            .text = model.login_draft(),
            .placeholder = "bunker://…",
            .on_input = AppUi.inputMsg(.login_edit),
            .autofocus = true,
            .on_submit = .login_submit,
            .height = 56,
        }, .{}),
        ui.text(.{ .size = .sm, .wrap = true, .style = .{ .foreground = p.text_muted } }, model.login_status()),
        ui.button(.{ .variant = .primary, .disabled = model.login_empty(), .on_press = .login_submit }, "Connect"),
    }));
}

/// The compose sheet: a modal over the feed with the note field and the actions.
/// On demand from the titlebar's "New note", so the feed is not sharing the
/// window with a permanent composer. Escape or a click outside closes it.
fn composeSheet(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    // A PAGE, shaped like settings: a bar across the top, then the content in a
    // card down the middle of the window.
    //
    // It is not a modal for the reason settings is not: a modal is a translucent
    // scrim over the whole window, so every frame repaints the window entire and
    // the cost grows with it. On a 1600x1000 window a frame cost 183ms as a
    // sheet and 8ms as a page, and the worst of it was the app sitting idle with
    // a caret blinking in it.
    //
    // It was a bare rounded card flush against the top of the window for a
    // while, which is what a sheet looks like when the sheet around it is taken
    // away and nothing is put in its place.
    return ui.column(.{
        .grow = 1,
        .style_tokens = .{ .background = .background },
        .semantics = .{ .label = "New note" },
    }, .{
        composeHeader(ui, model),
        ui.el(.separator, .{ .style = .{ .background = p.divider_chrome } }, .{}),
        ui.scroll(.{ .grow = 1 }, .{
            ui.row(.{ .gap = 0 }, .{
                ui.spacer(1),
                ui.column(.{ .gap = 0, .width = compose_sheet_width }, .{
                    vgap(ui, 16),
                    // The writer and their words, side by side: the disc says
                    // whose voice this is, which is the one thing a composer
                    // must not leave ambiguous when a signer can be swapped.
                    ui.el(.card, .{
                        .padding = 14,
                        .style = .{ .background = p.surface_settings_card, .border = p.border_chip, .radius = settings_card_radius, .stroke_width = 1 },
                    }, .{
                        ui.row(.{ .gap = 0, .cross = .start }, .{
                            meAvatar(ui, avatar_size),
                            hgap(ui, 12),
                            ui.column(.{ .grow = 1, .gap = 0 }, .{
                                ui.el(.textarea, .{
                                    .text = model.draft(),
                                    .placeholder = "What's on your mind?",
                                    .on_input = AppUi.inputMsg(.draft_edit),
                                    .on_submit = .post,
                                    .width = compose_editor_width,
                                    .height = compose_editor_height,
                                    // The caret starts here. A composer you have
                                    // to click into before you can type is a
                                    // composer that opened for no reason.
                                    // Edge-triggered on mount, so it never
                                    // re-steals the caret on a later rebuild.
                                    .autofocus = true,
                                    .style = .{ .background = p.surface_settings_card, .border = p.surface_settings_card, .stroke_width = 0 },
                                }, .{}),
                                // Under the field, because the caret cannot be
                                // located and a picker that floats elsewhere is
                                // a guess about where the reader is looking.
                                mentionPicker(ui, model),
                            }),
                        }),
                    }),
                    composeNotifyRow(ui, model),
                    vgap(ui, 10),
                    // What pressing Post will do, in the terms that matter: how
                    // far the note goes, and how much room is left when that
                    // starts to matter.
                    ui.row(.{ .cross = .center, .gap = 0 }, .{
                        hgap(ui, 2),
                        ui.paragraph(
                            .{ .style = .{ .foreground = p.text_dim } },
                            &.{.{ .text = composeReach(ui, model.draft().len), .monospace = true, .scale = mono_meta_scale }},
                        ),
                        ui.spacer(1),
                        ui.paragraph(
                            .{ .style = .{ .foreground = p.text_muted } },
                            &.{.{ .text = "Cmd + Enter", .monospace = true, .scale = mono_hint_scale }},
                        ),
                        hgap(ui, 2),
                    }),
                    vgap(ui, 18),
                }),
                ui.spacer(1),
            }),
        }),
    });
}

/// The composer's top bar: the way out on the left, what this is in the middle,
/// and the verb on the right. The same band settings wears, so the two full
/// screens in the app are not two different shapes.
fn composeHeader(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return ui.row(.{ .cross = .center, .gap = 0, .height = settings_header_height, .padding = 0.01 }, .{
        hgap(ui, 10),
        ui.button(.{ .size = .sm, .variant = .ghost, .on_press = .close_compose }, "Cancel"),
        ui.spacer(1),
        ui.paragraph(
            .{ .style = .{ .foreground = p.text_sheet_title } },
            &.{.{ .text = "New note", .weight = .medium, .scale = settings_title_scale }},
        ),
        ui.spacer(1),
        ui.button(.{ .size = .sm, .variant = .primary, .disabled = model.draft_empty(), .on_press = .post }, "Post"),
        hgap(ui, 10),
    });
}

/// Replaces the `@word` being typed with a real `nostr:npub…` reference.
///
/// A plain `@name` is a string; only the reference is a link that another
/// client can resolve to a person, and it is what the note's own renderer turns
/// back into a name when it is read. The picker exists to make that the easy
/// path rather than the knowledgeable one.
fn insertMention(model: *Model, pubkey: [32]u8) void {
    const text = model.draft();
    // Through the same reader the picker used, so the cut is the run being
    // typed and never, say, the domain of an address written earlier.
    const query = mentionQuery(text) orelse return;
    const at = text.len - query.len - 1;
    var scratch: [1024]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&scratch);
    const npub = nostr.nip19.encodeNpub(fba.allocator(), pubkey) catch return;
    // Sized to what the draft can actually hold, so an insert that will not fit
    // is REFUSED rather than written short: the buffer truncates in silence,
    // and half a bech32 reference is one no client can resolve, published
    // without a word of warning.
    var buf: [compose_capacity]u8 = undefined;
    const written = std.fmt.bufPrint(&buf, "{s}nostr:{s} ", .{ text[0..at], npub }) catch return;
    model.draft_buffer = @TypeOf(model.draft_buffer).init(written);
    g_draft_dirty = true;
}

pub fn insertMentionForTest(model: *Model, pubkey: [32]u8) void {
    insertMention(model, pubkey);
}

/// One candidate for a mention, and why it is where it is in the list.
const MentionCandidate = struct {
    pubkey: [32]u8,
    name: []const u8,
    handle: []const u8,
    verified: bool,
    /// Lower sorts first. The design's ranking is follows, then follows-you,
    /// then everyone the app has seen; the middle tier needs the follows' own
    /// contact lists, which a later milestone builds, so it is empty here and
    /// the code is shaped to take it.
    tier: u8,
};

const mention_tier_follows: u8 = 0;
const mention_tier_follows_you: u8 = 1;
const mention_tier_seen: u8 = 2;
/// How many names the picker offers at once. A list longer than this is a
/// search, which is a different surface.
const mention_rows_max = 6;

/// The word being typed after an `@`, or null when the caret is not in one.
/// Only ever the LAST such run in the draft, because that is the one being
/// written: an `@name` earlier in the note is already said.
pub fn mentionQuery(text: []const u8) ?[]const u8 {
    const at = std.mem.lastIndexOfScalar(u8, text, '@') orelse return null;
    // An `@` mid-word is an email or a handle already written, not a mention
    // being composed.
    if (at > 0) {
        const before = text[at - 1];
        if (!std.ascii.isWhitespace(before)) return null;
    }
    const word = text[at + 1 ..];
    // A space ends it: the reader has moved on and is no longer picking.
    for (word) |c| {
        if (std.ascii.isWhitespace(c)) return null;
    }
    return word;
}

/// The names to offer for `query`, best first. Matches on the display name and
/// on the handle, because a reader types whichever they remember.
fn mentionCandidates(ui: *AppUi, query: []const u8) []const MentionCandidate {
    const out = ui.arena.alloc(MentionCandidate, mention_rows_max) catch return &.{};
    var n: usize = 0;
    for (&g_profiles) |*pr| {
        if (!pr.used or n == out.len) continue;
        const name = pr.name();
        const user = pr.username();
        if (name.len == 0 and user.len == 0) continue;
        if (query.len > 0 and !startsWithFold(name, query) and !startsWithFold(user, query)) continue;
        out[n] = .{
            .pubkey = pr.pubkey,
            .name = if (name.len > 0) name else user,
            .handle = user,
            .verified = pr.nip05_state == .verified,
            // Everyone in the pack is someone the reader follows; anyone else
            // is someone the app has merely seen.
            .tier = if (inFollowGraph(pr.pubkey)) mention_tier_follows else mention_tier_seen,
        };
        n += 1;
    }
    std.mem.sort(MentionCandidate, out[0..n], {}, struct {
        fn lt(_: void, a: MentionCandidate, b: MentionCandidate) bool {
            if (a.tier != b.tier) return a.tier < b.tier;
            return a.name.len < b.name.len;
        }
    }.lt);
    return out[0..n];
}

/// Case-insensitive prefix match, which is how a reader types a name.
fn startsWithFold(haystack: []const u8, prefix: []const u8) bool {
    if (prefix.len > haystack.len) return false;
    return std.ascii.eqlIgnoreCase(haystack[0..prefix.len], prefix);
}

/// The picker: the names the reader might mean, under the field they are typing
/// in. Anchored to the field rather than the caret, which cannot be located
/// (0.5), so it hangs under the whole editor.
fn mentionPicker(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    if (model.mention_dismissed) return ui.spacer(0);
    const query = mentionQuery(model.draft()) orelse return ui.spacer(0);
    const names = mentionCandidates(ui, query);
    if (names.len == 0) return ui.spacer(0);
    const rows = ui.arena.alloc(AppUi.Node, names.len + 1) catch return ui.spacer(0);
    for (names, rows[0..names.len], 0..) |c, *row, i| {
        const tint = avatarTint(c.pubkey);
        const hexdigits = "0123456789abcdef";
        row.* = ui.el(.list_item, .{
            .padding = 0.01,
            .cross = .center,
            .on_press = Msg{ .insert_mention = c.pubkey },
            .style = .{ .radius = 6, .background = if (i == 0) p.surface_menu_selected else null },
            .semantics = .{ .role = .button, .label = c.name, .focusable = true },
        }, .{
            hgap(ui, 8),
            ui.avatar(.{
                .image = 0,
                .width = 24,
                .height = 24,
                .style = .{ .background = tint.bg, .border = tint.border, .foreground = tint.glyph, .stroke_width = 1 },
            }, ui.fmt("{c}{c}", .{ hexdigits[c.pubkey[0] >> 4], hexdigits[c.pubkey[0] & 0x0f] })),
            hgap(ui, 9),
            ui.paragraph(.{ .style = .{ .foreground = p.text_primary } }, &.{.{ .text = c.name, .weight = .medium, .scale = menu_scale }}),
            if (c.verified) hgap(ui, 5) else ui.spacer(0),
            if (c.verified)
                ui.icon(.{ .width = 11, .height = 11, .style = .{ .foreground = p.status_success } }, "check-circle")
            else
                ui.spacer(0),
            hgap(ui, 6),
            if (c.handle.len > 0)
                ui.paragraph(.{ .style = .{ .foreground = p.accent_identity } }, &.{.{ .text = ui.fmt("@{s}", .{c.handle}), .scale = mono_row_scale }})
            else
                ui.spacer(0),
            ui.spacer(1),
            hgap(ui, 8),
        });
    }
    // What pressing one does, said once at the foot rather than per row.
    rows[names.len] = ui.column(.{ .gap = 0 }, .{
        vgap(ui, 2),
        ui.separator(.{ .style = .{ .foreground = p.border_menu, .background = p.border_menu } }),
        vgap(ui, 5),
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, 8),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_dim } },
                &.{.{ .text = "inserts a nostr: link, not just a name", .monospace = true, .scale = mono_chip_scale }},
            ),
        }),
        vgap(ui, 3),
    });
    return menuSurfacePlacedDismissing(ui, 320, .below, .start, Msg.close_mentions, rows);
}

/// How far a note will go, said before it goes rather than after: the relays
/// that will take a write, and that Plaza imposes no length of its own.
/// Who this note will notify, as names you can switch off.
///
/// Nothing here is new information at publish time: it is the same set the
/// event carries, shown before it goes out. A reply can tag a dozen people who
/// were merely present in a thread, and the first anybody knew about it used to
/// be somebody answering a conversation they had left.
/// The composer's notify row, derived from the draft as it stands.
fn composeNotifyRow(ui: *AppUi, model: *const Model) AppUi.Node {
    var people: [max_mention_tags][32]u8 = undefined;
    const n = notifiedBy(model.draft(), &people);
    if (n == 0) return ui.spacer(0);
    return ui.column(.{ .gap = 0 }, .{ vgap(ui, 10), notifyChips(ui, model, people[0..n]) });
}

/// The reply's notify row: whoever the text names, plus everybody already in
/// the thread, which is the set that surprises people.
fn replyNotifyRow(ui: *AppUi, model: *const Model, root: *const Note) AppUi.Node {
    var people: [max_mention_tags][32]u8 = undefined;
    var n = notifiedBy(model.reply_draft(), &people);
    const me = activePubkey();
    var pool: [1 + thread_reply_cap][32]u8 = undefined;
    var pool_len: usize = 0;
    pool[0] = root.pubkey;
    pool_len = 1;
    for (model.thread_notes[0..model.thread_notes_len]) |note| {
        if (pool_len == pool.len) break;
        pool[pool_len] = note.pubkey;
        pool_len += 1;
    }
    for (pool[0..pool_len]) |pubkey| {
        if (n == people.len) break;
        if (me) |mine| {
            if (std.mem.eql(u8, &mine, &pubkey)) continue;
        }
        var dup = false;
        for (people[0..n]) |seen| {
            if (std.mem.eql(u8, &seen, &pubkey)) dup = true;
        }
        if (dup) continue;
        people[n] = pubkey;
        n += 1;
    }
    if (n == 0) return ui.spacer(0);
    return ui.column(.{ .gap = 0 }, .{ vgap(ui, 8), notifyChips(ui, model, people[0..n]) });
}

fn notifyChips(ui: *AppUi, model: *const Model, people: []const [32]u8) AppUi.Node {
    const p = theme.palette;
    if (people.len == 0) return ui.spacer(0);

    // Chunked into rows by hand, because `wrap` is a text property in this
    // toolkit and not a row one: a single row of a dozen chips would run off
    // the side of the composer rather than folding under itself.
    //
    // Two per row, and the name clipped. Three of them blew 35px past the right
    // edge of the narrowest window the app allows, which the layout guard
    // caught: a chip is only as wide as the name inside it, and a display name
    // has no length any of this controls.
    const per_row = 2;
    const row_count = (people.len + per_row - 1) / per_row;
    const rows = ui.arena.alloc(AppUi.Node, row_count + 1) catch return ui.spacer(0);
    rows[0] = ui.paragraph(
        .{ .style = .{ .foreground = p.text_dim } },
        &.{.{ .text = "Notifies", .scale = stat_scale }},
    );

    var placed: usize = 0;
    for (rows[1..]) |*row| {
        const take = @min(per_row, people.len - placed);
        const kids = ui.arena.alloc(AppUi.Node, take) catch return ui.spacer(0);
        for (people[placed..][0..take], kids) |pubkey, *kid| {
            const off = mentionExcluded(model.mentionsOff(), pubkey);
            // Switched off stays on screen, dimmed, rather than disappearing:
            // a chip that vanished when pressed would leave nothing to press
            // to bring the person back.
            kid.* = ui.el(.panel, .{
                .padding = 0.01,
                .on_press = Msg{ .toggle_mention_off = pubkey },
                .style = .{
                    .background = if (off) p.surface_rail_tile else p.surface_input,
                    .border = p.border_chip,
                    .radius = 999,
                    .stroke_width = 1,
                },
                .semantics = .{
                    .role = .button,
                    .label = if (off) "Not notifying, press to switch back on" else "Notifying, press to switch off",
                },
            }, .{
                ui.row(.{ .cross = .center, .gap = 0 }, .{
                    hgap(ui, 10),
                    ui.paragraph(
                        .{ .style = .{ .foreground = if (off) p.text_muted else p.text_secondary } },
                        &.{.{ .text = clipToChars(personName(ui, pubkey), 14, 42), .scale = stat_scale }},
                    ),
                    hgap(ui, 10),
                    vgap(ui, 24),
                }),
            });
        }
        placed += take;
        row.* = ui.row(.{ .cross = .center, .gap = 6 }, kids);
    }
    return ui.column(.{ .gap = 6 }, rows);
}

fn composeReach(ui: *AppUi, written: usize) []const u8 {
    // The room left, once there is little enough of it to matter. A composer
    // that silently stops accepting characters is the bug this replaces, and a
    // counter that is always on screen is a nag for the ninety-nine notes that
    // will never approach the limit.
    const left = compose_capacity -| written;
    if (left <= compose_capacity / 4) {
        const live_now = liveRelayCount();
        if (live_now == 0) return ui.fmt("{d} left · no relay is answering", .{left});
        return ui.fmt("posts to {d} {s} · {d} left", .{ live_now, if (live_now == 1) "relay" else "relays", left });
    }
    const live = liveRelayCount();
    if (live == 0) return "no relay is answering · it will wait in the outbox";
    return ui.fmt("posts to {d} {s}", .{ live, if (live == 1) "relay" else "relays" });
}

/// The expanded picture, filling the window over the feed. The registry decodes
/// at most 512 pixels on a side, so rather than upscale a small copy into a
/// blur, this shows it as large as it honestly goes and offers the
/// full-resolution original in the browser. Pressing the backdrop closes it,
/// which also stops presses reaching the feed underneath.
fn imageViewer(ui: *AppUi, note: *const Note) AppUi.Node {
    const image_id = note.media_id();
    // A dialog, not a bare column: modal surfaces paint their own opaque
    // surface and always claim their own input, so the feed underneath neither
    // shows through nor scrolls, and Escape or a click outside closes it.
    // Stacking kinds layer their children, so the contents go in a column.
    return ui.el(.dialog, .{
        .grow = 1,
        .padding = 16,
        .on_dismiss = .close_image,
        .on_press = .close_image,
        .style_tokens = .{ .background = .background },
        .semantics = .{ .label = "Expanded image" },
    }, .{
        ui.column(.{ .grow = 1, .gap = 12, .cross = .stretch }, .{
            // The picture needs a definite box: an image is a leaf with no
            // intrinsic size, so it draws nothing unless a stretching parent
            // hands it one (a centred column collapses its width to zero).
            ui.row(.{ .grow = 1, .cross = .stretch }, .{
                if (image_id != 0) blk: {
                    var node = ui.image(.{
                        .image = image_id,
                        .grow = 1,
                        .semantics = .{ .label = "Expanded image" },
                    });
                    node.widget.image_fit = .contain;
                    break :blk node;
                } else ui.text(.{ .style_tokens = .{ .foreground = .text_muted } }, "Still loading…"),
            }),
            ui.row(.{ .gap = 8, .cross = .center }, .{
                ui.button(.{ .size = .sm, .variant = .ghost, .autofocus = true, .on_press = .close_image }, "Close"),
                ui.spacer(1),
                ui.button(.{ .size = .sm, .on_press = Msg{ .open_url = note.imageUrl() } }, "Open original"),
            }),
        }),
    });
}

/// The one options value both `virtualWindow` and `virtualList` read. The MODEL
/// owns the notes; the runtime only ever sees how many there are, an estimate
/// per row, and the window it asked for.
fn feedOptions(model: *const Model) AppUi.VirtualListOptions {
    return .{
        .id = "feed",
        .item_count = model.notes_len,
        // Variable-extent mode: cards are as tall as their wrapped text and
        // their picture. The estimate prices unbuilt rows; the engine patches in
        // measured heights as rows mount, and anchors the viewport so those
        // corrections never move what the reader is looking at.
        .item_extent = 0,
        .extent_estimate = noteExtentEstimate,
        .extent_context = model,
        // No gap between rows: the hairline under each row is the separation,
        // so a border can mean something (a quote, a reply) and rows do not
        // float apart with the divider lost in the space.
        .gap = 0,
        // No list inset: the row inset was narrower than the reading column, so
        // the column overflowed it on the right (flush) while the left inset read
        // as a gap. At 0 the centered reading column sits symmetric in the feed.
        .padding = 0,
        .overscan = 3,
        .grow = 1,
        // Only bare builds (tests, previews) read this: under the app the
        // runtime supplies the real viewport. Without it a test resolves an
        // empty window and renders no rows at all.
        .viewport_fallback = window_height,
        .semantics = .{ .label = "Feed" },
        .on_reach_end = .load_older,
    };
}

/// A cheap height estimate for the note at `index`, from model facts only
/// (never layout): the card's chrome, its wrapped lines, and its picture.
fn noteExtentEstimate(context: ?*const anyopaque, index: u64) f32 {
    const model: *const Model = @ptrCast(@alignCast(context orelse return 96));
    const i: usize = @intCast(index);
    if (i >= model.notes_len) return feed_row_chrome;
    return noteRowEstimate(&model.notes[i], feed_row_chrome);
}

/// The shared card-height math behind the feed's and the thread's estimates.
/// `chrome` covers everything except the body's wrapped lines; the body wraps in
/// the 540px text column beside the 36px disc.
///
/// The line height is MEASURED, not the redesign's ratio. The mock sets the body
/// at 14.5/1.55 (22.475), but `widgetLineHeight` is `size * 1.25` with no token
/// and no per-element override anywhere in the SDK, so a body line is 18.125 here
/// and the feed reads tighter than the mock. Recorded as a wall in the plan.
fn noteRowEstimate(note: *const Note, chrome: f32) f32 {
    return noteRowEstimateWith(note, chrome, true);
}

/// The same, for a row that draws the body and NOTHING under it. A nested reply
/// is one: it builds an identity row and a body and stops, so pricing it for a
/// picture and a link card reported hundreds of pixels per reply it never drew.
fn noteRowEstimateBody(note: *const Note, chrome: f32) f32 {
    return noteRowEstimateWith(note, chrome, false);
}

fn noteRowEstimateWith(note: *const Note, chrome: f32, media: bool) f32 {
    const line_height: f32 = body_line_height;
    const chars_per_line: f32 = 70;
    // A collapsed long note shows only the fold, plus a line for "Show more".
    const collapsed = noteIsLong(note) and !isExpanded(note.id);
    const shown_chars: f32 = @floatFromInt(if (collapsed) collapsedLen(note.content(), note_collapse_chars) else note.content_len);
    const lines = @max(1, @ceil(shown_chars / chars_per_line));
    var extent = chrome + lines * line_height;
    if (collapsed) extent += line_height;
    if (!media) return extent;
    // A link card, once the page has answered; nothing before that.
    if (note.hasLink()) {
        if (linkFor(note.linkUrl())) |l| {
            if (l.state == .loaded) {
                extent += 3 + (if (l.description().len > 0) link_card_height else link_card_height_bare);
            }
        }
    }
    // A picture nobody asked for is one quiet chip, not a reserved box.
    if (note.hasImage()) {
        const shown = g_media_previews or isMediaAsked(note.id) or note.media_id() != 0;
        extent += (if (shown) pictureHeight(note) else picture_ask_height) + 8;
    }
    // The quote, which is only now a knowable height: the clamp is what makes it
    // one (the shot's own note beside 11f says quote rows clamp "so their height
    // is known at insert"). The bordered card it replaces was never priced at
    // all, so a feed of quoting notes reported less than it drew.
    // The card sits at its own byte span in the body, so a collapsed note shows
    // it only when the fold reaches past it, exactly as `noteBodyAt` decides.
    const quote_end = @as(usize, note.quote.off) + @as(usize, note.quote.len);
    const quote_shown = note.quote.kind == .event and
        (!collapsed or quote_end <= collapsedLen(note.content(), note_collapse_chars));
    if (quote_shown) {
        extent += quoteAsideExtent(note.quote.id);
    }
    return extent;
}

/// How tall a quote's aside draws: its margin, the identity block (the disc sets
/// it), and up to `quote_body_lines` lines of the quoted note. A quote still
/// resolving is priced at the skeleton it shows, so the row does not jump when
/// it lands.
fn quoteAsideExtent(id: [32]u8) f32 {
    const e = quoteFor(id) orelse return quote_quiet_chrome + quote_skeleton_height;
    return switch (e.state) {
        // The quiet states draw no identity block, so they do not carry its
        // chrome: only the 5 above, the sibling gap and the 2px pads. Pricing
        // them like the loaded aside over-charged every quoting row by nearly
        // three lines from first paint until its quote landed.
        .idle, .fetching => quote_quiet_chrome + quote_skeleton_height,
        .missing => quote_quiet_chrome + body_line_height,
        // The depth-1 pill, when the quoted note quotes something itself: it is
        // a row of its own under the body, and the row around it is priced.
        .loaded => quote_aside_chrome + quoteBodyLines(e) * body_line_height +
            (if (e.has_quote_of) quote_pill_height + 4 else 0) +
            (if (e.image_host_len > 0) quote_pill_height + 4 else 0),
    };
}

/// The lines a cached quote's body draws, counted the way the clamp cuts them.
fn quoteBodyLines(e: *const QuoteEntry) f32 {
    // No body, no line. A quoted note that is nothing but a picture draws no
    // body at all, and charging it one line reserved a blank row under the name
    // that nothing ever filled.
    if (e.text_len == 0) return 0;
    var lines: usize = 1;
    var column: usize = 0;
    for (e.text_buf[0..e.text_len]) |c| {
        if ((c & 0xc0) == 0x80) continue;
        if (c == '\n' or column >= ancestor_chars_per_line - 1) {
            lines += 1;
            column = 0;
            if (lines >= quote_body_lines) break;
        }
        if (c != '\n') column += 1;
    }
    return @floatFromInt(@min(lines, quote_body_lines));
}

/// One thread level's row plan: row 0 is the root note, rows 1..n the replies
/// in conversation order, with skeleton rows (first fetch still out) or the
/// quiet empty line appended. Arena-allocated per frame so the virtual list's
/// estimate callback can price unbuilt rows from model facts.
pub const ThreadRows = struct {
    /// The model, so the composer row can read the draft and the signer state.
    model: *const Model,
    root: *const Note,
    /// The chain above the focal note, oldest first, drawn as the rows before
    /// it. Empty for a thread opened at its own root.
    ancestors: []const Ancestor,
    /// Top-level replies with their own replies folded in, so ONE row is one
    /// conversation rather than one note.
    blocks: []const ThreadBlock,
    /// How many of the in-graph blocks this page shows, and how many wait behind
    /// the line. `hidden` counts CONVERSATIONS, which is the row arithmetic;
    /// `hidden_held` counts the replies inside them, which is what the line says.
    shown: usize,
    hidden: usize,
    hidden_held: usize,
    /// Replies from outside the follow graph, held below the rest. They are never
    /// dropped: the row says how many there are and opens them.
    outside: []const ThreadBlock,
    /// How many REPLIES those blocks hold, which is what the line says. A block
    /// is one conversation: its own note, the replies drawn under it, and
    /// whatever those collapse into.
    outside_held: usize,
    outside_open: bool,
    skeletons: bool,
    empty: bool,
    /// The line that says the subscription is still open. Absent in the empty
    /// state, which says it in its own words.
    footer: bool,

    /// What sits at `index`, for both the builder and the estimator. ONE function
    /// answers it, because two parallel index walks is how a row draws itself at
    /// another row's height: every earlier version of this list had the plan
    /// written out twice and had to keep the arithmetic in step by hand.
    pub const Row = union(enum) {
        ancestor: usize,
        focal,
        composer,
        block: usize,
        show_more,
        outside_line,
        outside_block: usize,
        skeleton,
        empty,
        footer,
    };

    /// The chain, then the focal note, then the reply field, then one row per
    /// shown conversation, the lines that hold what is not shown, and the footer.
    /// The field is a ROW rather than a pinned footer because the design puts it
    /// under the note being answered, where it scrolls with the conversation
    /// instead of hovering over it.
    pub fn rowAt(self: *const ThreadRows, index: usize) Row {
        if (index < self.ancestors.len) return .{ .ancestor = index };
        var i = index - self.ancestors.len;
        if (i == 0) return .focal;
        if (i == 1) return .composer;
        i -= 2;
        if (i < self.shown) return .{ .block = i };
        i -= self.shown;
        if (self.hidden > 0) {
            if (i == 0) return .show_more;
            i -= 1;
        }
        if (self.outside.len > 0) {
            if (i == 0) return .outside_line;
            i -= 1;
            if (self.outside_open) {
                if (i < self.outside.len) return .{ .outside_block = i };
                i -= self.outside.len;
            }
        }
        if (self.skeletons) {
            if (i < thread_skeleton_rows) return .skeleton;
            i -= thread_skeleton_rows;
        }
        if (self.empty) {
            if (i == 0) return .empty;
            i -= 1;
        }
        return .footer;
    }

    pub fn count(self: *const ThreadRows) usize {
        return self.ancestors.len + 2 + self.shown + @intFromBool(self.hidden > 0) +
            @intFromBool(self.outside.len > 0) + (if (self.outside_open) self.outside.len else 0) +
            (if (self.skeletons) thread_skeleton_rows else 0) + @intFromBool(self.empty) +
            @intFromBool(self.footer);
    }
};

/// How many top-level replies a page of a thread shows, and how many more each
/// press of the line reveals. No shot states a number; twenty is a long read
/// already, and the line says exactly how many are behind it.
const thread_page_size: usize = 20;
const thread_skeleton_rows: usize = 3;

/// A cheap height estimate for one thread row, sharing the feed's note math.
/// A level's row heights, precomputed at build time and read back by the SDK
/// whenever it wants them.
///
/// The SDK RETAINS `extent_context` and calls the estimator through it long
/// after the build that supplied it returned: in a post-layout measure pass, and
/// since 0.7.2 from inside `virtualWindow` on a LATER build. Both lists used to
/// hand it an arena-allocated view context full of slices, on the reasoning that
/// the arena outlives the build. It does not outlive two: the runtime rotates a
/// small set of arenas and resets the one it is about to build into, so a
/// context handed over on build N is read on build N+2 with its slices pointing
/// at whatever the new build has since allocated there. That is a segfault in
/// `noteRowEstimateWith`, reading a Note out of a reused index, and it is what
/// took the app down on a mouse-up over a person's page.
///
/// So the retained context holds NO POINTERS. It is a table of numbers with
/// process lifetime, filled from the real row structures while they are alive
/// and valid, and read afterwards by an estimator that cannot dereference
/// anything. There is nothing left in it that a later frame can invalidate.
const RowExtents = struct {
    /// A tag, because the other half of the pairing cannot be checked by the
    /// compiler: `extent_context` is `?*const anyopaque` and accepts any
    /// pointer, so wiring the estimator to a view context instead of a table
    /// would read one struct as the other and hand the list garbage heights,
    /// silently. This turns that into a fallback the suite can catch.
    magic: u64 = row_extents_magic,
    heights: [thread_reply_cap * 2]f32 = [_]f32{0} ** (thread_reply_cap * 2),
    len: usize = 0,

    fn reset(self: *RowExtents) void {
        self.len = 0;
    }

    fn push(self: *RowExtents, height: f32) void {
        if (self.len >= self.heights.len) return;
        self.heights[self.len] = height;
        self.len += 1;
    }

    fn at(self: *const RowExtents, index: usize) f32 {
        if (index >= self.len) return quiet_row_extent;
        return self.heights[index];
    }
};

const row_extents_magic: u64 = 0x524f57455854_4142;

/// Who and what is ON SCREEN in a level right now: the authors whose faces are
/// being drawn, and the notes whose pictures are.
///
/// The canvas registry holds SIXTEEN images for the whole window, split nine
/// faces, one banner and six pictures. That is ample, because only about a
/// screenful of rows is ever visible at once, and the feed has always spent it
/// that way: it marks and fetches `visibleRange()` and nothing else.
///
/// A thread and a person's page did not. They marked EVERY note in the level as
/// on screen, so in a long thread the first nine authors and the first six
/// pictures took every slot and held them: the allocator refuses to evict
/// anything marked wanted this pass, and everything was marked. Every other
/// author kept initials and every other picture stayed blank, for as long as the
/// level was open, and the bigger the thread the worse it got. This is what
/// "avatars and images do not load in big threads" was.
///
/// Filled during the build from the visible window, which is the only place that
/// knows which rows are on screen, and read on the next tick by the two passes
/// that lend slots. One frame stale, exactly like the feed's own range.
const VisibleSet = struct {
    authors: [visible_set_cap][32]u8 = undefined,
    author_count: usize = 0,
    notes: [visible_set_cap]i64 = undefined,
    note_count: usize = 0,

    fn reset(self: *VisibleSet) void {
        self.author_count = 0;
        self.note_count = 0;
    }

    fn pushAuthor(self: *VisibleSet, pubkey: [32]u8) void {
        if (self.author_count >= self.authors.len) return;
        for (self.authors[0..self.author_count]) |had| {
            if (std.mem.eql(u8, &had, &pubkey)) return;
        }
        self.authors[self.author_count] = pubkey;
        self.author_count += 1;
    }

    fn pushNote(self: *VisibleSet, id: i64) void {
        if (self.note_count >= self.notes.len) return;
        for (self.notes[0..self.note_count]) |had| {
            if (had == id) return;
        }
        self.notes[self.note_count] = id;
        self.note_count += 1;
    }
};

/// A screenful of rows, with the overscan the lists declare and a block's own
/// replies counted: comfortably more than can be on screen, and far fewer than a
/// long thread holds.
const visible_set_cap = 48;

/// One per mounted level. UI-thread only, like every other per-level cache here.
var g_level_visible: [thread_depth_max + 1]VisibleSet = [_]VisibleSet{.{}} ** (thread_depth_max + 1);
/// Which level is the one being READ, so the passes that lend slots spend them
/// on the level in front rather than on an occluded one underneath.
var g_visible_level: usize = 0;

/// One per mounted level, plus one for a person's page at that level. Levels are
/// UI-thread only, like every other per-level cache in this file.
var g_thread_extents: [thread_depth_max + 1]RowExtents = [_]RowExtents{.{}} ** (thread_depth_max + 1);
var g_profile_extents: [thread_depth_max + 1]RowExtents = [_]RowExtents{.{}} ** (thread_depth_max + 1);

/// Reads a precomputed height. The whole point is that this touches nothing but
/// its own numbers.
/// Records the authors and pictures on screen in a thread level.
///
/// A visible ROW is not one note: a block is a reply plus the replies drawn
/// under it, and all of them are on screen together. The overscan the list
/// declares is included, which is what makes a face arrive before the row
/// carrying it does.
fn recordThreadVisible(rows: *const ThreadRows, level: usize, first: usize, last: usize) void {
    const set = &g_level_visible[@min(level, g_level_visible.len - 1)];
    set.reset();
    g_visible_level = @min(level, g_level_visible.len - 1);
    var index = first;
    while (index <= last and index < rows.count()) : (index += 1) {
        switch (rows.rowAt(index)) {
            .ancestor => |ai| if (ai < rows.ancestors.len) {
                set.pushAuthor(rows.ancestors[ai].note.pubkey);
                set.pushNote(rows.ancestors[ai].note.id);
            },
            .focal => {
                set.pushAuthor(rows.root.pubkey);
                set.pushNote(rows.root.id);
            },
            .block => |bi| if (bi < rows.blocks.len) pushBlock(set, &rows.blocks[bi]),
            .outside_block => |oi| if (oi < rows.outside.len) pushBlock(set, &rows.outside[oi]),
            else => {},
        }
    }
}

fn pushBlock(set: *VisibleSet, block: *const ThreadBlock) void {
    set.pushAuthor(block.parent.pubkey);
    set.pushNote(block.parent.id);
    for (block.children) |*child| {
        set.pushAuthor(child.pubkey);
        set.pushNote(child.id);
    }
}

/// The same for a person's page: the subject owns a face first, then whichever
/// of their notes is on screen.
fn recordProfileVisible(rows: *const ProfileRows, level: usize, first: usize, last: usize) void {
    const set = &g_level_visible[@min(level, g_level_visible.len - 1)];
    set.reset();
    g_visible_level = @min(level, g_level_visible.len - 1);
    // The 72px face is the largest thing on the page, so the subject is first in
    // line whether or not their card is scrolled into view.
    set.pushAuthor(rows.pubkey);
    var index = first;
    while (index <= last and index < rows.count()) : (index += 1) {
        switch (rows.rowAt(index)) {
            .note => |ni| if (ni < rows.notes.len) {
                set.pushAuthor(rows.notes[ni].pubkey);
                set.pushNote(rows.notes[ni].id);
            },
            else => {},
        }
    }
}

/// Pretends a build put exactly these authors on screen in the front level.
pub fn recordVisibleAuthorsForTest(authors: []const [32]u8) void {
    const set = &g_level_visible[0];
    set.reset();
    g_visible_level = 0;
    for (authors) |pk| set.pushAuthor(pk);
}

fn rowExtentFromTable(context: ?*const anyopaque, index: u64) f32 {
    const table: *const RowExtents = @ptrCast(@alignCast(context orelse return quiet_row_extent));
    if (table.magic != row_extents_magic) return quiet_row_extent;
    return table.at(@intCast(index));
}

/// The retained tables, for a test that drops the build arena and then reads
/// them exactly as the SDK does.
pub fn threadExtentTableForTest(level: usize) *const anyopaque {
    return &g_thread_extents[@min(level, g_thread_extents.len - 1)];
}

pub fn profileExtentTableForTest(level: usize) *const anyopaque {
    return &g_profile_extents[@min(level, g_profile_extents.len - 1)];
}

pub fn rowExtentFromTableForTest(context: ?*const anyopaque, index: u64) f32 {
    return rowExtentFromTable(context, index);
}

pub fn extentTableLenForTest(context: ?*const anyopaque) usize {
    const table: *const RowExtents = @ptrCast(@alignCast(context orelse return 0));
    return table.len;
}

/// One thread row's height, measured from the live row structures.
///
/// TYPED, and deliberately: it takes a `*const ThreadRows` rather than the
/// SDK's `?*const anyopaque` callback shape, so it cannot be handed over as a
/// retained estimator. Only `rowExtentFromTable` has that shape now, and it
/// reads numbers. See `RowExtents` for what went wrong when this was the
/// callback.
fn threadRowHeight(rows: *const ThreadRows, i: usize) f32 {
    return switch (rows.rowAt(i)) {
        // An ancestor: the identity block pinned to its disc, a body clamped to
        // two lines, and the rail's segment down to the next disc.
        .ancestor => |ai| blk: {
            const a = &rows.ancestors[ai];
            const lead: f32 = if (ai == 0) ancestor_top_pad else 0;
            if (a.ghost != .none) break :blk lead + ghost_row_extent;
            break :blk lead + ancestor_row_chrome + @as(f32, @floatFromInt(a.lines)) * ancestor_line_height;
        },
        // The focal note carries the identity block, its exact-time line, the
        // stats row and the verb row on top of a body set one register up. Its
        // leading space belongs to the ancestor above it when there is one.
        .focal => noteRowEstimate(rows.root, focal_row_chrome) -
            (if (rows.ancestors.len > 0) focal_leading_pad else 0),
        // The reply field: a fixed shape whatever the thread holds.
        .composer => reply_row_extent,
        // A block is its top-level reply plus the level of conversation under it,
        // so it is priced as the sum: one reply's chrome and body, then each
        // child's.
        .block => |bi| blockExtent(&rows.blocks[bi]),
        .outside_block => |oi| blockExtent(&rows.outside[oi]),
        .show_more => show_more_extent,
        .outside_line => outside_row_extent,
        .footer => listening_row_extent,
        // A skeleton or the empty line: one fixed-shape row.
        .skeleton, .empty => thread_skeleton_extent,
    };
}

/// One conversation's height: the top-level reply, then each nested child, then
/// a line for whatever the branch continues into.
fn blockExtent(block: *const ThreadBlock) f32 {
    var extent = noteRowEstimate(block.parent, thread_reply_chrome);
    if (block.parent.parent_missing) extent += orphan_note_extent;
    for (block.children, block.deeper) |*child, deeper| {
        extent += noteRowEstimateBody(child, nested_reply_chrome) * nested_body_scale;
        if (deeper > 0) extent += branch_more_extent;
    }
    return extent;
}

/// How many lines an ancestor's clamped body wraps to: one or two, the clamp's
/// whole point.
fn ancestorBodyLines(note: *const Note) f32 {
    // No body, no line. An image-only reply is a common shape, and its content
    // is empty because the URL is lifted out of the text: pricing it at a line
    // the row never draws is space the level reports and does not fill.
    if (note.content_len == 0) return 0;
    var lines: usize = 1;
    var column: usize = 0;
    for (note.content()) |c| {
        if ((c & 0xc0) == 0x80) continue;
        if (c == '\n' or column >= ancestor_chars_per_line - 1) {
            lines += 1;
            column = 0;
            if (lines >= ancestor_body_lines) break;
        }
        if (c != '\n') column += 1;
    }
    return @floatFromInt(@min(lines, ancestor_body_lines));
}

/// One thread level's panel: header, the windowed root-and-replies list, and
/// the reply composer. Rendered for the open thread AND every ancestor still on
/// the back-stack (occluded beneath it), so each level's list stays mounted and
/// keeps its scroll offset. The list is a virtualList: only the rows in the
/// viewport are built, so a busy thread, or a stack of occluded ancestor
/// levels, stays far under the per-view widget budget (a plain scroll built
/// every reply of every level and blew straight through it). The list id is
/// the level key, so a level's scroll identity is stable as it moves between
/// current and ancestor.
fn threadPanel(ui: *AppUi, model: *const Model, root: *const Note, replies: []const Note, thread_loading: bool, level_key: u64, level: usize, occluded: bool) AppUi.Node {
    // While the first fetch is out with nothing in hand, a few skeleton rows say
    // "replies are coming"; once it has come back empty, a quiet line instead of
    // a lone root over blank space.
    const loading = replies.len == 0 and thread_loading;
    const empty = replies.len == 0 and !thread_loading;
    const rows_ctx = ui.arena.create(ThreadRows) catch return ui.column(.{}, .{});
    // Group first, then page: a page is twenty CONVERSATIONS, not twenty notes, so
    // a reply with a busy branch counts once.
    const grouped = groupThreadBlocks(ui, replies);
    // Replies from people the reader follows rank first; strangers are held below
    // one quiet line, never dropped. The partition is stable, so it preserves the
    // arrival and chronological order inside each tier.
    const split = splitByFollowGraph(ui, grouped, root.pubkey);
    const shown = @min(split.inside.len, model.thread_page[@min(level, model.thread_page.len - 1)] * thread_page_size);
    rows_ctx.* = .{
        .model = model,
        .root = root,
        .ancestors = ancestorsFor(ui, level, root, occluded),
        .blocks = split.inside,
        .shown = shown,
        .hidden = split.inside.len - shown,
        .hidden_held = heldReplies(split.inside[shown..]),
        .outside = split.outside,
        .outside_held = heldReplies(split.outside),
        .outside_open = model.thread_outside_open[@min(level, model.thread_outside_open.len - 1)],
        .skeletons = loading,
        .empty = empty,
        // The empty state says the same thing in its own words, so the footer
        // would only repeat it.
        .footer = !empty,
    };
    // Filled from the context while it is alive and valid, and handed to the
    // SDK in its place. See `RowExtents`.
    const table = &g_thread_extents[@min(level, g_thread_extents.len - 1)];
    table.reset();
    if (!occluded) {
        var row: usize = 0;
        const total = rows_ctx.count();
        while (row < total) : (row += 1) table.push(threadRowHeight(rows_ctx, row));
    }
    const options: AppUi.VirtualListOptions = .{
        .id = ui.fmt("thread-{d}", .{level_key}),
        // Nothing to cover when nothing is drawn. A list that declares items and
        // builds none is permanently "undercovered", so the runtime answers by
        // rebuilding and re-laying out the whole view a second time, every time.
        // The feed learned this; the levels stacked under it have the same shape,
        // and at a back stack two deep or more there is always one occluded.
        .item_count = if (occluded) 0 else rows_ctx.count(),
        .item_extent = 0,
        .extent_estimate = rowExtentFromTable,
        .extent_context = table,
        .gap = 0,
        .padding = 0,
        .overscan = 3,
        .grow = 1,
        .viewport_fallback = window_height,
        .semantics = .{ .label = "Thread" },
    };
    const window = ui.virtualWindow(options);
    // What is ACTUALLY on screen in this level, recorded where the row
    // structures are alive. The two passes that lend registry slots read it on
    // the next tick. See `VisibleSet`.
    if (!occluded) recordThreadVisible(rows_ctx, level, window.first_visible_index, window.last_visible_index);
    // An OCCLUDED level is behind an opaque panel: it is mounted to keep its
    // scroll offset, and nothing it builds can be seen. So it builds nothing.
    // The offset survives on the list's id and its content height, which comes
    // from the row COUNT and the estimates, not from the rows, so the walk back
    // still lands where the reader left. This is not only cheaper, it is what
    // keeps a deep back-stack inside the 1024-node ceiling: a view past it is
    // REFUSED whole, and six mounted levels of a busy thread crossed it.
    const rows = if (occluded)
        &[_]AppUi.Node{}
    else blk: {
        const built = ui.arena.alloc(AppUi.Node, window.itemCount()) catch return ui.column(.{}, .{});
        for (built, 0..) |*row, offset| row.* = threadRowAt(ui, rows_ctx, window.start_index + offset);
        break :blk built;
    };
    return ui.column(.{ .grow = 1, .style_tokens = .{ .background = .background } }, .{
        if (occluded) ui.spacer(0) else threadHeader(ui, model),
        ui.virtualList(options, window, .{rows}),
    });
}

/// Builds the thread row at `index` (see `ThreadRows` for the plan), centred
/// like a feed row. `grow` on the wrapper is safe here: the virtual list
/// positions rows absolutely, so a growing row spreads WIDTH, exactly like the
/// feed's cards (the old plain-scroll column grew rows VERTICALLY instead,
/// which is why these wrappers were once forbidden).
fn threadRowAt(ui: *AppUi, rows_ctx: *const ThreadRows, index: usize) AppUi.Node {
    const plan = rows_ctx.rowAt(index);
    const inner = switch (plan) {
        .ancestor => |ai| ancestorRow(ui, &rows_ctx.ancestors[ai], ai == 0),
        .focal => threadRoot(ui, rows_ctx.model, rows_ctx.root, rows_ctx.ancestors.len == 0),
        .composer => replyComposer(ui, rows_ctx.model, rows_ctx.root),
        // `first` draws the full-width rule under the note being answered, and
        // `last` suppresses the trailing one: a rule with nothing under it is a
        // dangling line, and its trailing space is what tips a thread that fits
        // into reporting more content than it draws. So the flags are about what
        // is ACTUALLY above and below the block, held replies included.
        .block => |bi| replyBlock(ui, rows_ctx.model, &rows_ctx.blocks[bi], rows_ctx.root.pubkey, bi == 0, bi + 1 == rows_ctx.shown and rows_ctx.hidden == 0 and rows_ctx.outside.len == 0),
        .outside_block => |oi| replyBlock(ui, rows_ctx.model, &rows_ctx.outside[oi], rows_ctx.root.pubkey, oi == 0 and rows_ctx.shown == 0, oi + 1 == rows_ctx.outside.len),
        .show_more => showMoreReplies(ui, rows_ctx.hidden_held),
        .outside_line => outsideGraphRow(ui, rows_ctx.outside_held, rows_ctx.outside_open),
        .footer => listeningFooter(ui),
        .empty => threadEmptyNote(ui),
        .skeleton => replySkeleton(ui),
    };
    var node = ui.row(.{ .grow = 1, .main = .center }, .{inner});
    // Stable row identity for the windowed reconciler: the note's own id, or a
    // synthetic high-bit key for the placeholder rows (their bit sits above the
    // masked 63-bit note-id space, so no collision).
    // A row with no note of its own is keyed by WHAT IT IS, not by where it sits:
    // a key folds into every descendant's identity, so keying the composer by
    // index would hand it a new identity, and drop the caret mid-typing, the
    // moment a missing ancestor resolves and every row below it shifts down.
    node.key = .{
        .int = switch (plan) {
            .focal => @intCast(rows_ctx.root.id),
            .block => |bi| @intCast(rows_ctx.blocks[bi].parent.id),
            .outside_block => |oi| @intCast(rows_ctx.outside[oi].parent.id),
            // A ghost row has no note behind it, so it takes a synthetic key like
            // the other placeholders, folding in its seat in the chain.
            .ancestor => |ai| if (rows_ctx.ancestors[ai].ghost == .none)
                @intCast(rows_ctx.ancestors[ai].note.id)
            else
                placeholderKey(@intFromEnum(std.meta.activeTag(plan)), ai),
            // Skeletons repeat, so they keep their position; every other
            // placeholder appears at most once in a level.
            .skeleton => placeholderKey(@intFromEnum(std.meta.activeTag(plan)), index),
            else => placeholderKey(@intFromEnum(std.meta.activeTag(plan)), 0),
        },
    };
    return node;
}

/// A key for a row with no note behind it: its kind, plus a discriminator for the
/// kinds that can repeat. The high bit sits above the masked 63-bit note-id
/// space, so it can never collide with a real note.
fn placeholderKey(kind: u64, nth: usize) u64 {
    return (@as(u64, 1) << 63) | (kind << 32) | @as(u64, @intCast(nth));
}

/// The open thread's replies read from the store at render time, into the arena,
/// oldest first. Used for the ANCESTOR levels (the current level reads its cached
/// `thread_notes` instead): they are occluded, so a per-frame read keeps their
/// scroll content stable without a second full reply cache. The `#e` closure
/// walk is the costly part, so its RESULT (the id set) is cached per level and
/// re-walked only when the store's event count moves; the notes themselves are
/// rebuilt into the frame arena from cheap point reads.
fn threadRepliesFromStore(ui: *AppUi, level: usize, root_event_id: [32]u8) []const Note {
    const store = g_store orelse return &.{};
    const cache = &g_level_replies[level];
    const stamp = store.eventCount() catch std.math.maxInt(usize);
    if (stamp == std.math.maxInt(usize) or cache.stamp != stamp or !std.mem.eql(u8, &cache.root, &root_event_id)) {
        cache.root = root_event_id;
        cache.stamp = stamp;
        cache.len = collectThreadIds(store, root_event_id, &cache.ids);
    }
    const now = nowSeconds();
    const notes = ui.arena.alloc(Note, cache.len) catch return &.{};
    var n: usize = 0;
    for (cache.ids[0..cache.len]) |id| {
        var se = (store.getEvent(std.heap.page_allocator, id) catch continue) orelse continue;
        defer se.deinit();
        notes[n] = noteFrom(se.event, now);
        n += 1;
    }
    // The SAME order the level had when it was the open thread, from the SAME
    // table: a level is mounted underneath precisely so the walk back lands where
    // the reader left it, and a second sort here would re-order the rows under an
    // offset restored for the first. This level is not fetching (its own fetch
    // finished before the reader moved on), so anything new here is genuinely
    // late and opens a batch.
    stampArrival(arrivalTableFor(level, root_event_id), notes[0..n], true);
    arrangeThread(notes[0..n], root_event_id);
    return notes[0..n];
}

/// The chain above the focal note, as rows: the ancestors in the store (oldest
/// first) with a ghost row on top when the chain does not reach the thread's
/// opening note. Built into the frame arena from the cached id list, like the
/// occluded levels' replies.
///
/// Every mounted level computes its own chain, INCLUDING the occluded ones: a
/// level's row plan has to be the same when it is beneath the current thread as
/// when it is the current thread, or its restored scroll offset would land
/// somewhere else on the way back.
fn ancestorsFor(ui: *AppUi, level: usize, focal: *const Note, occluded: bool) []const Ancestor {
    if (!focal.has_reply_parent) return &.{};
    const store = g_store orelse return &.{};
    if (level >= g_ancestor_chains.len) return &.{};
    const chain = &g_ancestor_chains[level];
    const stamp = store.eventCount() catch std.math.maxInt(usize);
    if (stamp == std.math.maxInt(usize)) return &.{};
    if (chain.stamp != stamp or !std.mem.eql(u8, &chain.focal, &focal.event_id)) {
        refreshAncestorChain(chain, store, focal, stamp);
    }

    const ghost = @intFromBool(chain.gap != .none);
    const rows = ui.arena.alloc(Ancestor, chain.len + ghost) catch return &.{};
    if (ghost == 1) rows[0] = .{ .ghost = chain.gap, .is_root = chain.gap_is_root };
    var n: usize = ghost;
    // An occluded level draws nothing, so it reads nothing: the row count and
    // the cached line counts are the whole of what its estimates need, and its
    // content height (which is what its restored scroll offset is measured
    // against) comes out identical either way.
    if (occluded) {
        for (chain.lines[0..chain.len]) |lines| {
            rows[n] = .{ .lines = lines };
            n += 1;
        }
        return rows[0..n];
    }
    const now = nowSeconds();
    for (chain.ids[0..chain.len], chain.lines[0..chain.len]) |id, lines| {
        var se = (store.getEvent(std.heap.page_allocator, id) catch continue) orelse continue;
        defer se.deinit();
        rows[n] = .{ .note = noteFrom(se.event, now), .lines = lines };
        n += 1;
    }
    return rows[0..n];
}

/// The quiet line under a note that has no replies, so an empty thread reads as
/// "nothing here yet" rather than a lone post over a wall of blank space.
fn threadEmptyNote(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .width = thread_column_width, .gap = 0 }, .{
        vgap(ui, 8),
        ui.row(.{ .main = .center }, .{
            ui.paragraph(.{ .style = .{ .foreground = p.text_muted } }, &.{.{ .text = "No replies yet. Yours would be the first.", .scale = stat_scale }}),
        }),
        vgap(ui, 12),
        // What the thread is doing about it, rather than a dead end: the
        // subscription is open and a reply will appear when one lands.
        ui.separator(.{ .width = thread_column_width, .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
        vgap(ui, 10),
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            hgap(ui, thread_inset),
            ui.el(.panel, .{ .width = 6, .height = 6, .padding = 0.01, .style = .{ .background = p.status_success, .radius = 3, .stroke_width = 0 } }, .{}),
            hgap(ui, 8),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_dim } },
                &.{.{ .text = pluralize(ui, liveRelayCount(), "listening on {d} relay", "listening on {d} relays"), .monospace = true, .scale = mono_meta_scale }},
            ),
        }),
    });
}

/// A back control: a chevron, where it goes, and a press.
///
/// `ui.row`, NOT `ui.el(.data_row, ...)`, and that is the whole point of this
/// function existing. A `.data_row` does not take its width from its children:
/// it lays out at ZERO wide while its chevron and label paint outside it. The
/// row containing it then places the next sibling at the back control's own x
/// plus the gap, so the screen's title is drawn ON TOP of the thing that goes
/// back. Three headers did this, and the thread's read as one unbroken smear of
/// "Starter pack", "Thread" and "3 replies" in the same place.
///
/// The zero width is invisible to the widget tree and to mouse input, which
/// hit-tests to the label and walks UP to whatever claims the press. Only a
/// laid-out frame shows it, which is why `no control that can be pressed is
/// laid out at nothing` measures rather than inspects.
fn backControl(ui: *AppUi, label: []const u8, press: Msg) AppUi.Node {
    const p = theme.palette;
    return ui.row(.{
        .cross = .center,
        .gap = 3,
        .padding = 4,
        .on_press = press,
        .style = .{ .quiet_hover = true },
        .semantics = .{ .role = .button, .label = "Back", .focusable = true },
    }, .{
        ui.icon(.{ .width = 16, .height = 16, .style = .{ .foreground = p.text_muted } }, "chevron-left"),
        ui.text(.{ .size = .sm, .style = .{ .foreground = p.text_muted } }, label),
    });
}

/// The thread header: a Back affordance (to the parent thread, or the feed), the
/// "Thread" label, and the reply count (known from the crowd count up front, so
/// it reads right before the replies are fetched).
fn threadHeader(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    // Back names WHERE it goes, never a bare "Thread" beside the "Thread" title:
    // the feed ("Following") at the root, else the parent post's author.
    const back_label = if (model.thread_stack_len > 0)
        model.thread_stack[model.thread_stack_len - 1].backLabel()
    else
        model.scope_name();
    const count = model.threadReplyCount();
    return ui.column(.{}, .{
        ui.row(.{ .cross = .center, .gap = 10, .padding = 12 }, .{
            backControl(ui, back_label, .close_thread),
            ui.paragraph(.{ .style = .{ .foreground = p.text_primary } }, &.{.{ .text = "Thread", .weight = .bold }}),
            // The count reads once replies are known; before then it says nothing
            // rather than a misleading "0 replies" on a note that has some.
            if (count > 0)
                ui.text(.{ .size = .sm, .style = .{ .foreground = p.text_faint_alt } }, ui.fmt("{d} {s}", .{ count, if (count == 1) "reply" else "replies" }))
            else
                ui.spacer(0),
            ui.spacer(1),
        }),
        ui.separator(.{ .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
    });
}

/// A placeholder reply row shown while the first fetch is still out: a skeleton
/// avatar and lines the same shape a real reply takes, so the thread reads as
/// "loading" rather than "empty".
fn replySkeleton(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .width = thread_column_width }, .{
        ui.row(.{ .gap = 12, .cross = .start, .padding = 14 }, .{
            ui.el(.skeleton, .{ .width = avatar_size, .height = avatar_size }, .{}),
            ui.column(.{ .gap = 8, .grow = 1, .padding = 3 }, .{
                ui.el(.skeleton, .{ .width = 130, .height = 10 }, .{}),
                ui.el(.skeleton, .{ .height = 10 }, .{}),
                ui.el(.skeleton, .{ .width = 220, .height = 10 }, .{}),
            }),
        }),
        ui.separator(.{ .width = thread_column_width, .style = .{ .foreground = p.divider_reply, .background = p.divider_reply } }),
    });
}

/// The @handle for a thread identity line: the same label and the same ink rule
/// the feed's identity block uses (violet for a NIP-05, muted for a kind:0 name
/// or a short npub), or a thin skeleton while the profile is still loading, so the
/// line does not visibly fill in a beat later. `fill` grows the element to hang
/// the time to the far right (reply rows); the root note puts the handle on its
/// own line, so it does not.
fn identityHandle(ui: *AppUi, note: *const Note, fill: bool) AppUi.Node {
    const p = theme.palette;
    const label = note.handleLabel(ui.arena);
    const h = label.text;
    const ink = if (label.nip05) p.accent_identity else p.text_faint;
    if (h.len > 0) {
        return if (fill)
            ui.text(.{ .grow = 1, .style = .{ .foreground = ink } }, h)
        else
            ui.text(.{ .size = .sm, .style = .{ .foreground = ink } }, h);
    }
    // Profile still being fetched: a placeholder rather than an empty gap. Once
    // it resolves (handle or none) or we give up, this stops showing.
    if (profileLoading(note.pubkey)) {
        const bar = ui.el(.skeleton, .{ .width = 72, .height = 9 }, .{});
        return if (fill) ui.row(.{ .grow = 1, .cross = .center }, .{bar}) else bar;
    }
    return if (fill) ui.spacer(1) else ui.spacer(0);
}

/// The focused root note: the same 40px avatar and 14px inset as the feed and
/// the replies (so every row's avatar and text share one left edge), set apart
/// by a slightly larger name, the name-over-handle stack, and the composer below.
fn threadRoot(ui: *AppUi, model: *const Model, note: *const Note, leads: bool) AppUi.Node {
    const c = engagementFor(note.id);
    // A fixed-width column, centred by the scroll column's `cross = .center`. No
    // outer growing row: a `grow` child in the scroll's column grows vertically
    // and would overlap the next row. Every block inside sits 4px in, which is
    // the focal note's own inset within the reading column.
    return ui.column(.{
        .width = thread_column_width,
        .gap = 0,
        // The focal note answers a right-click like every other post. `in_thread`
        // drops "Open thread" from the list, which from the note the thread is
        // ABOUT would be an offer to arrive where the reader already is.
        .context_menu = noteContextItems(ui, note, true),
    }, .{
        // The space above the focal note, unless an ancestor row is up there: its
        // own bottom pad is the rail's segment down to this disc, and adding both
        // would break the chain's rhythm exactly where the eye follows it.
        if (leads) vgap(ui, focal_leading_pad) else ui.spacer(0),
        // The identity line, at the disc's height, with the overflow menu at the
        // far end. No timestamp here: the focal note states its time in full
        // below, where there is room to be exact.
        ui.row(.{ .gap = 0, .cross = .center }, .{
            hgap(ui, thread_inset),
            noteAvatar(ui, note),
            hgap(ui, avatar_to_text_gap),
            identityBlock(ui, note),
            ui.spacer(1),
            // No overflow trigger up here any more. Every post carries its menu
            // as the last verb under it now, this note included, and two
            // triggers keyed on the same note opened two identical menus at
            // once: the state is per NOTE, not per control.
            hgap(ui, thread_inset),
        }),
        vgap(ui, 9),
        // One register up from a feed row: this is the note being read.
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, thread_inset),
            ui.column(.{ .grow = 1, .gap = 0 }, .{
                focalBody(ui, note),
                if (note.hasImage()) vgap(ui, 8) else ui.spacer(0),
                if (note.hasImage()) notePicture(ui, note) else ui.spacer(0),
                if (note.hasLink()) linkCard(ui, note) else ui.spacer(0),
                vgap(ui, 9),
                focalMeta(ui, note),
            }),
            hgap(ui, thread_inset),
        }),
        vgap(ui, 12),
        focalStats(ui, c),
        focalVerbs(ui, model, note),
    });
}

/// The focal note's body: the SAME builder every other note uses, one register up.
/// Writing a second paragraph path here cost the embedded quote card, which is
/// exactly the kind of quiet loss a parallel implementation buys.
fn focalBody(ui: *AppUi, note: *const Note) AppUi.Node {
    return noteBodyAt(ui, note, false, focal_body_scale, theme.palette.text_focal);
}

/// When the focal note was written and how widely it is held.
///
/// The note's address used to sit here as a copyable pill, sixty characters of
/// bech32 under every focal note. It is in the note's own menu now, under
/// "Copy note address", which is where a reader looks for a thing to copy and
/// is not where a reader looks while reading.
fn focalMeta(ui: *AppUi, note: *const Note) AppUi.Node {
    const p = theme.palette;
    const seen = relaysSeenFor(note.id);
    return ui.row(.{ .cross = .center, .gap = 0 }, .{
        ui.paragraph(
            .{ .style = .{ .foreground = p.text_faint_alt } },
            &.{.{
                .text = if (seen > 0)
                    ui.fmt("{s} · {s}{s}", .{
                        absoluteNoteTime(ui.arena, note.created_at),
                        pluralize(ui, seen, "seen on {d} relay", "seen on {d} relays"),
                        viaSuffix(ui, note),
                    })
                else
                    // Nothing delivered it this session (it came off disk), so the
                    // line says when it was written and what wrote it, and stops.
                    ui.fmt("{s}{s}", .{ absoluteNoteTime(ui.arena, note.created_at), viaSuffix(ui, note) }),
                .monospace = true,
                .scale = mono_hint_scale,
            }},
        ),
        ui.spacer(1),
    });
}

/// The focal note's tallies, as words rather than icons: the verbs below carry
/// the actions, so these are the numbers, stated plainly.
fn focalStats(ui: *AppUi, c: Counts) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.separator(.{ .width = thread_column_width, .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            hgap(ui, thread_inset + 2),
            vgap(ui, 33),
            statCount(ui, c.replies, "reply", "replies"),
            hgap(ui, 18),
            statCount(ui, c.reposts, "repost", "reposts"),
            hgap(ui, 18),
            statCount(ui, c.likes, "like", "likes"),
            hgap(ui, 18),
            statCount(ui, c.zap_msat / 1000, "sat", "sats"),
            ui.spacer(1),
        }),
        ui.separator(.{ .width = thread_column_width, .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
    });
}

fn statCount(ui: *AppUi, n: u64, singular: []const u8, plural: []const u8) AppUi.Node {
    const p = theme.palette;
    return ui.paragraph(.{ .style = .{ .foreground = p.text_muted_alt } }, &.{
        .{ .text = if (n == 0) "0" else formatCount(ui.arena, n), .weight = .medium, .color = .text, .scale = stat_scale },
        .{ .text = ui.fmt(" {s}", .{if (n == 1) singular else plural}), .scale = stat_scale },
    });
}

/// The focal note's verbs: the SAME row every other note carries.
///
/// It used to be two glyphs, a like and an open-on-the-web, shoved to opposite
/// ends of the column by a grow spacer. Two verbs is not the row a reader has
/// just scrolled past a screenful of, and forty pixels of nothing between them
/// reads as a row that lost its middle. The counts are left off, because the
/// stats line directly above states them in words: this is the same builder,
/// told not to repeat itself.
fn focalVerbs(ui: *AppUi, model: *const Model, note: *const Note) AppUi.Node {
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 2),
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            hgap(ui, thread_inset),
            engagementRowAt(ui, model, note, false),
        }),
        vgap(ui, 4),
    });
}

/// One top-level reply and what hangs off it. The redesign shows exactly one
/// level of nesting in place: a reply, the replies to THAT reply, and then a line
/// saying how much of the branch continues out of sight. Deeper than that is a
/// thread of its own, which is what pressing the line opens.
pub const ThreadBlock = struct {
    parent: *const Note,
    /// The parent's direct replies, contiguous in the arranged order.
    children: []const Note,
    /// Per child, how many of ITS descendants are not drawn. Parallel to
    /// `children`, so a branch says so under the reply it continues from.
    deeper: []const usize,
};

pub fn splitByFollowGraphForTest(ui: *AppUi, blocks: []const ThreadBlock, author: [32]u8) GraphSplit {
    return splitByFollowGraph(ui, blocks, author);
}

pub fn followSetForTest() []const [32]u8 {
    return followSet();
}

/// A profile's two tabs. "Notes" is what they wrote; "Replies" is what they
/// wrote at somebody else.
pub const ProfileTab = enum { notes, replies };

/// One level of the back stack: a thread, or a person.
///
/// Both are levels rather than layers because the SDK tracks at most 8 virtual
/// windows per build and an OCCLUDED level still registers one: the feed plus
/// six stacked levels plus the current is already exactly eight. A profile that
/// layered ON TOP of a full thread stack would be a ninth window, silently
/// dropped in a release build. Sharing the depth budget is what keeps that
/// impossible rather than merely unlikely.
pub const Screen = struct {
    /// The thread's root note. Unused when this level is a profile.
    note: Note = .{},
    /// Whose profile this level shows, when it is one.
    profile: ?[32]u8 = null,

    pub fn isProfile(self: Screen) bool {
        return self.profile != null;
    }

    /// What Back says it goes to: a person's name, or the author of the note
    /// underneath. Back names WHERE it lands, never what it leaves.
    pub fn backLabel(self: *const Screen) []const u8 {
        if (self.profile) |pk| {
            if (lookupProfile(pk)) |prof| {
                if (prof.name_len > 0) return prof.name();
            }
            return "Profile";
        }
        return self.note.author();
    }
};

/// The two tiers of a thread's replies, in their original order.
pub const GraphSplit = struct { inside: []const ThreadBlock, outside: []const ThreadBlock };

/// How many REPLIES a run of blocks holds, which is what the line above them
/// counts. A block is one conversation: the reply that opened it, the replies
/// drawn under it, and whatever those collapse into.
pub fn heldReplies(blocks: []const ThreadBlock) usize {
    var held: usize = 0;
    for (blocks) |block| {
        held += 1 + block.children.len;
        for (block.deeper) |deeper| held += deeper;
    }
    return held;
}

fn splitByFollowGraph(ui: *AppUi, blocks: []const ThreadBlock, author: [32]u8) GraphSplit {
    if (blocks.len == 0) return .{ .inside = &.{}, .outside = &.{} };
    const inside = ui.arena.alloc(ThreadBlock, blocks.len) catch return .{ .inside = blocks, .outside = &.{} };
    const outside = ui.arena.alloc(ThreadBlock, blocks.len) catch return .{ .inside = blocks, .outside = &.{} };
    var ni: usize = 0;
    var no: usize = 0;
    for (blocks) |block| {
        // The conversation is placed by whoever opened it: a stranger's reply is
        // held below even when someone followed answers inside it.
        // Whoever wrote the note being read is inside their own thread whether
        // or not the reader follows them: otherwise opening a stranger's reply
        // would hold their own continuation of it behind a collapsed line.
        if (std.mem.eql(u8, &block.parent.pubkey, &author) or inFollowGraph(block.parent.pubkey)) {
            inside[ni] = block;
            ni += 1;
        } else {
            outside[no] = block;
            no += 1;
        }
    }
    return .{ .inside = inside[0..ni], .outside = outside[0..no] };
}

/// NIP-02's kind. A contact list is replaceable: publishing one replaces who
/// this reader follows, everywhere, at once.
const contact_list_kind: u16 = 3;

/// How many follows are TRACKED, which is not how many the feed reads.
///
/// These are two different numbers and conflating them was a real bug: the feed
/// asks the store for notes by author, and the store opens one cursor per
/// author, so reading is what has to be capped. Membership is not: "do I follow
/// this person" has to be right for every name on the list, or the Follow button
/// offers to add somebody who is already there and the press does nothing.
const max_follows_tracked = 2048;
/// How many the FEED reads from: all of them.
///
/// This was 128 for two reasons and neither survived measurement.
///
/// The store cost was real and is fixed. Asking for one kind by many authors
/// used to be answered from the author index, so it walked everything those
/// people had ever written and discarded the wrong kinds after decoding them;
/// nostr v0.3.8 indexes the pair. A feed rebuild across 2048 follows now
/// measures inside one frame at 60Hz, and the curve that made 128 look like a
/// cliff turned out to have been recorded in a Debug build.
///
/// The REQ payload is real and is handled: a filter naming a few thousand
/// authors is past what several relays accept, so the subscription splits them
/// across filters of `follow_chunk` and sends the lot in ONE REQ, which is what
/// Damus does and what strfry's own limit is written against. A relay answers
/// every filter in a REQ, so this is a payload split, not a narrower question.
pub const max_follows = max_follows_tracked;

/// Authors per filter in the feed subscription.
///
/// strfry refuses a filter whose field items exceed 65535 bytes, which is 2047
/// hex pubkeys, and it is not the only relay with a ceiling. Damus splits at
/// 500 and has had years of contact with relays nobody here runs. Taking the
/// number that is already proven against the wild rather than the largest one
/// that fits the one implementation whose source states a limit.
const follow_chunk = 500;

/// How many chunks the author set can need, rounded up, with the reader's own
/// key counted. Sizes the filter buffer, so a follow list that grows past it is
/// a compile-time question rather than a truncated subscription.
const max_follows_divided = (max_follows + 1 + follow_chunk - 1) / follow_chunk;

/// How many filters the feed subscription can need: two per chunk, plus one for
/// the reader's own records.
pub const max_feed_filters = 2 * (max_follows_divided + 1) + 1;

/// The feed's notes.
const feed_filter_kinds = [_]u16{1};
/// What the feed needs about the people in it: kind:0 is who they are, 10002 is
/// where they are.
///
/// NOT kind:3. Somebody else's contact list is asked for in exactly one place,
/// the profile card's follow counts, and the worker that opens a profile
/// already fetches that person's kind:0 and kind:3 on its own. Asking for it
/// here asked every relay for the contact list of all two thousand follows at
/// dial: a list of two thousand `p` tags is well over a hundred kilobytes, so
/// this was megabytes per relay, per connection, to answer a question nobody
/// had asked, about people whose profile the reader may never open.
const profile_filter_kinds = [_]u16{ 0, relay_list_kind };

/// What the feed needs about the READER, which is the above plus their own
/// contact list.
///
/// Their own kind:3 is not optional and not a nicety: nothing may write over a
/// replaceable record that has not been read back first, and the follow list is
/// the one where getting that wrong empties somebody's account. It is one
/// author and three records, so it costs nothing to ask for separately, which
/// is the entire reason the bulk filter above can stop asking for it.
const self_filter_kinds = [_]u16{ 0, relay_list_kind, contact_list_kind };

/// Backing store for the reader's own author filter. A `Filter` borrows its
/// `authors` slice, so this cannot live on `buildFeedFilters`' stack. Written
/// only there, and only from the relay threads that build a subscription.
var g_self_filter_author: [1][32]u8 = undefined;

/// Splits `authors` across filters small enough for a relay to accept, two per
/// chunk, and returns the slice of `out` that was filled.
///
/// One REQ carries all of them. A relay answers every filter in a REQ, so this
/// asks exactly the question one enormous filter would have asked, in an
/// envelope that arrives. The per-chunk limit is NOT divided: each chunk names
/// different people, and splitting the limit would starve whoever landed in the
/// last one.
pub fn buildFeedFilters(authors: []const [32]u8, self: ?[32]u8, since: ?i64, out: []nostr.filter.Filter) []nostr.filter.Filter {
    var len: usize = 0;
    var start: usize = 0;
    while (start < authors.len) : (start += follow_chunk) {
        if (len + 2 > out.len) break;
        const chunk = authors[start..@min(start + follow_chunk, authors.len)];
        // The notes carry `since`; the metadata filter deliberately does not.
        // A profile or relay list edited while the app was closed has an older
        // `created_at` than the newest note held, so bounding that filter would
        // hide exactly the update the app most needs.
        out[len] = .{ .authors = chunk, .kinds = &feed_filter_kinds, .since = since, .limit = feed_request_limit };
        // One record per author per kind, which is what the filter can actually
        // return: these are all replaceable, so a relay holds at most one of
        // each. The old limit was `profile_cap`, a UI cache size, which for a
        // 500-author chunk across three kinds asked for 1500 records and
        // permitted 160. A relay obeying the limit answered a third of a chunk
        // and the rest of those authors stayed nameless until something else
        // happened to ask for them.
        out[len + 1] = .{
            .authors = chunk,
            .kinds = &profile_filter_kinds,
            .limit = @intCast(chunk.len * profile_filter_kinds.len),
        };
        len += 2;
    }
    // The reader's own three records, asked for once rather than folded into a
    // five-hundred-author filter. `self_storage` outlives the returned slice
    // because it is a module-level buffer: a filter borrows its authors, and a
    // local array here would dangle the moment this function returned.
    if (self) |pk| {
        if (len < out.len) {
            g_self_filter_author[0] = pk;
            out[len] = .{
                .authors = g_self_filter_author[0..1],
                .kinds = &self_filter_kinds,
                .limit = self_filter_kinds.len,
            };
            len += 1;
        }
    }
    return out[0..len];
}

var g_follows: [max_follows_tracked][32]u8 = undefined;
var g_follow_count: usize = 0;
/// Whose list is in `g_follows`, for the same reason the relay pool records it:
/// a list left behind by one account must never be read as another's.
var g_follow_owner: ?[32]u8 = null;
/// When the list in memory was signed, so an older one arriving from a slower
/// relay does not overwrite a newer one.
var g_follow_created_at: i64 = 0;
/// Bumped whenever the set changes, or the identity does. The ingest threads
/// snapshot it at dial and re-subscribe when it moves, so a follow shows new
/// notes, and a sign-in asks for the new account's own records, without waiting
/// for a socket to drop.
var g_follow_gen = std.atomic.Value(u32).init(0);

/// Bumped only when WHO IS SIGNED IN changes, never when the follow list moves.
///
/// The inbox REQ hung off the follow generation, so following one person
/// re-issued `plaza-inbox` on every read relay with a 200-event backfill. At
/// eight relays that is up to 1600 events re-delivered and re-verified for a
/// change the inbox does not depend on: its filter names one pubkey, the
/// reader's own. Amethyst keeps these on separate watchers for the same reason.
var g_identity_gen = std.atomic.Value(u32).init(0);

pub fn identityGeneration() u32 {
    return g_identity_gen.load(.acquire);
}

pub fn bumpIdentityGeneration() void {
    _ = g_identity_gen.fetchAdd(1, .monotonic);
}
/// Guards the table. The UI thread writes it; ingest threads read it to build
/// their filters.
var g_follow_lock = std.atomic.Value(bool).init(false);

fn lockFollows() void {
    while (g_follow_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockFollows() void {
    g_follow_lock.store(false, .release);
}

/// Whether the list in memory is THIS account's.
fn followsAreOwned() bool {
    const pk = activePubkey() orelse return false;
    const owner = g_follow_owner orelse return false;
    return std.mem.eql(u8, &owner, &pk);
}

/// Who the FEED reads: a bounded slice of the follow list, or the starter pack
/// until one is known.
pub fn followSet() []const [32]u8 {
    if (followsAreOwned()) return g_follows[0..@min(g_follow_count, max_follows)];
    return &starter_pack;
}

/// How many accounts this reader follows, all of them, whether or not the feed
/// reads them all.
pub fn followTotal() usize {
    if (followsAreOwned()) return g_follow_count;
    return starter_pack.len;
}

/// Copies the feed's author set for a caller on another thread. `followSet`
/// hands back a slice of a table the UI thread rewrites, and an ingest thread
/// holding one across a dial is the same hazard the relay pool already learned.
pub fn followSnapshot(out: *[max_follows][32]u8) usize {
    lockFollows();
    defer unlockFollows();
    if (!followsAreOwned()) {
        const n = @min(starter_pack.len, out.len);
        @memcpy(out[0..n], starter_pack[0..n]);
        return n;
    }
    const n = @min(g_follow_count, out.len);
    @memcpy(out[0..n], g_follows[0..n]);
    return n;
}

pub fn followGeneration() u32 {
    return g_follow_gen.load(.acquire);
}

/// Whether `pubkey` is inside the graph this reader is READING: their own follow
/// list once it is known, and the starter pack until then.
///
/// This is the ranking question, not the membership one. The inbox uses it to
/// tell somebody the reader reads from a stranger, and a thread uses it to split
/// replies into the conversation and the crowd outside it. For those, the pack
/// IS the graph while the pack is what fills the feed.
///
/// Not the same question as `isFollowedByMe`, and the difference is the whole
/// point of having both. Checked against EVERY follow, not the slice the feed
/// reads.
pub fn isInReadGraph(pubkey: [32]u8) bool {
    // A guest reads the pack, but the app has nothing to rank for them: no
    // inbox, no own-graph split.
    if (activePubkey() == null) return false;
    return inFollowedSet(pubkey);
}

/// Whether `pubkey` is in the set the feed is built from: the reader's whole
/// contact list, or the starter pack while the pack is what they are reading.
///
/// EVERY follow, never `followSet()`. That one is capped at `max_follows`
/// because it is the feed's author set and the feed pays a relay filter entry
/// and a store cursor per author, so being a slice is the point of it. Asking a
/// membership question of that slice told a reader with three hundred follows
/// that follows 129 and up were strangers, and a new follow is APPENDED, so the
/// people they had followed most recently were the ones most likely to be
/// misfiled.
fn inFollowedSet(pubkey: [32]u8) bool {
    lockFollows();
    defer unlockFollows();
    if (!followsAreOwned()) {
        for (starter_pack) |f| {
            if (std.mem.eql(u8, &f, &pubkey)) return true;
        }
        return false;
    }
    for (g_follows[0..g_follow_count]) |f| {
        if (std.mem.eql(u8, &f, &pubkey)) return true;
    }
    return false;
}

/// Whether this reader has actually FOLLOWED `pubkey`: their own kind:3 says so.
///
/// The starter pack is not a follow list. It is what the app reads on a new
/// account's behalf until that account has one, nothing is ever published to say
/// otherwise, and the feed's own header says as much ("Starter pack · hand-picked",
/// against "Following · yours"). But every control that asks about following
/// asked `isFollowing`, which counted the pack: a reader who had just made a key
/// was told they followed nine strangers, offered "Unfollow" on each, and got
/// nothing when they pressed it, because the write path correctly refuses to
/// remove somebody who is not on a list.
///
/// So the controls ask this instead. It says Follow for the pack, which is true,
/// and which is how a starter pack is supposed to turn into a list of your own.
pub fn isFollowedByMe(pubkey: [32]u8) bool {
    if (activePubkey() == null) return false;
    lockFollows();
    defer unlockFollows();
    if (!followsAreOwned()) return false;
    for (g_follows[0..g_follow_count]) |f| {
        if (std.mem.eql(u8, &f, &pubkey)) return true;
    }
    return false;
}

/// Installs a follow set as this account's. Returns whether anything changed.
fn setFollows(list: []const [32]u8, created_at: i64) bool {
    const pk = activePubkey() orelse return false;
    lockFollows();
    const same = blk: {
        if (!followsAreOwned()) break :blk false;
        if (g_follow_count != @min(list.len, max_follows_tracked)) break :blk false;
        for (list[0..@min(list.len, max_follows_tracked)], 0..) |f, i| {
            if (!std.mem.eql(u8, &f, &g_follows[i])) break :blk false;
        }
        break :blk true;
    };
    if (same) {
        unlockFollows();
        return false;
    }
    const n = @min(list.len, max_follows_tracked);
    @memcpy(g_follows[0..n], list[0..n]);
    g_follow_count = n;
    g_follow_owner = pk;
    g_follow_created_at = created_at;
    unlockFollows();
    // Everything scoped to the follow set is now stale: the feed's query, the
    // relay filters, the names being fetched.
    _ = g_follow_gen.fetchAdd(1, .monotonic);
    invalidateFeed();
    return true;
}

/// Forgets whose list this is. Called on any identity change, so one account's
/// follows are never read, published, or shown as another's.
fn forgetFollows() void {
    lockFollows();
    g_follow_owner = null;
    g_follow_count = 0;
    g_follow_created_at = 0;
    unlockFollows();
    // A list signed but not yet seen belongs to the account that signed it. Left
    // behind, it would be the base the NEXT account's first follow builds on.
    clearPendingFollowBase();
    forgetOwnListMemo();
    // The open subscriptions were built for the previous identity and are now
    // asking the wrong question. Without this a sign-in never gets its own
    // records requested on an already-open socket, and following stays disabled
    // for the whole session.
    _ = g_follow_gen.fetchAdd(1, .monotonic);
    // And this is the one thing the inbox DOES depend on: whose notifications
    // these are. It is the only place that bumps it, which is the point.
    bumpIdentityGeneration();
}

/// Seeds the follow set from the local store, at boot and at sign-in.
///
/// A local-first app that forgets who you follow every launch is not local
/// first. The store already holds the reader's newest kind:3 from last session,
/// so the feed is theirs from the first frame rather than after a round trip.
fn loadFollowsFromStore() void {
    const gpa = std.heap.page_allocator;
    const own = ownRecordJson(gpa, contact_list_kind) orelse return;
    defer freeOwnProfile(gpa, own);
    var list: [max_follows_tracked][32]u8 = undefined;
    const n = followsFromTags(own.tags, &list);
    if (n == 0) return;
    _ = setFollows(list[0..n], own.created_at);
}

/// Whether a follow write is safe to make right now.
///
/// The hard rule of this feature, and the one that took three attempts. A
/// contact list is REPLACEABLE: publishing one replaces who this reader follows,
/// on every relay, at once.
///
/// Attempt one gated on "some relay sent EOSE". Wrong, and dangerously so: EOSE
/// means "that is all *I* have", never "you have none". Attempt two required
/// EVERY readable relay to answer. Better, and still wrong, because it treats
/// relay silence as evidence: on a cold import the relays being asked are this
/// app's bootstrap five, chosen before the reader's own kind:10002 has been
/// read, so they can all answer cleanly while the real list sits on relays this
/// app has never dialed. Negative evidence is only ever as strong as the relay
/// set, and the relay set is the thing that is unresolved at exactly that
/// moment.
///
/// So the question is not "did the network answer" but "do we KNOW". Two ways:
///   - We HAVE their list. Splice onto it. Always safe, no relay condition, no
///     waiting: this is the branch that cannot destroy anything.
///   - The key was minted by this app, so it provably has no history. Creating
///     a list from nothing is safe with no relay condition either.
///
/// An IMPORTED identity gets neither. It has a past this app cannot see, and
/// nothing local can rule out a list of a thousand. The reader is told the app
/// is still looking rather than handed a button that would replace it.
/// (This is Damus's rule plus the explanation Damus does not give.)
pub fn canWriteFollows() bool {
    if (activePubkey() == null) return false;
    if (haveOwnContactList()) return true;
    return g_identity_minted_here;
}

/// Why the follow control is unavailable, in the reader's terms. An unexplained
/// dead button is the failure mode of every client that got the safety right and
/// the honesty wrong.
pub fn followBlockedReason() ?[]const u8 {
    if (activePubkey() == null) return null;
    if (canWriteFollows()) return null;
    return "Looking for your follow list…";
}

/// Whether this account's own kind:3 is in the local store, REMEMBERED.
///
/// This is asked from view code. `followBlockedReason` calls it, `noteContextItems`
/// calls that for the follow line in every post's menu, and the feed builds a card
/// for every note on screen, every frame. The honest answer used to be
/// `ownRecordJson`, which runs an LMDB query and then duplicates the whole record:
/// every tag, every field, each one its own `page_allocator` call, which is its own
/// `mmap`. Freeing it is an `munmap` apiece.
///
/// With three hundred follows that is roughly six hundred syscalls per card per
/// frame. A stack sample of a scroll put 1437 of 1462 app-side samples inside
/// `noteContextItems`, almost all of them here, and the frame rebuild measured 22.7
/// ms against an 8.3 ms frame: the feed scrolled at about nine frames a second, and
/// it got worse the more people you followed, which is exactly backwards.
///
/// The answer changes only when a kind:3 for this account reaches the store, and
/// `plazaIngest` is the one door for that, so it is recorded there instead of
/// re-derived sixty times a frame. Keyed by pubkey, so an identity change misses
/// rather than inherits.
const OwnListMemo = enum { unknown, absent, present };
var g_own_contact_list_memo: OwnListMemo = .unknown;
var g_own_contact_list_memo_for: ?[32]u8 = null;

fn haveOwnContactList() bool {
    const pk = activePubkey() orelse return false;
    if (g_own_contact_list_memo_for) |who| {
        if (std.mem.eql(u8, &who, &pk) and g_own_contact_list_memo != .unknown) {
            return g_own_contact_list_memo == .present;
        }
    }
    // The miss path asks whether a record EXISTS, which reads one row and copies
    // nothing. It is `ownRecordJson` that was expensive, not the query.
    const present = ownRecordExists(contact_list_kind);
    g_own_contact_list_memo_for = pk;
    g_own_contact_list_memo = if (present) .present else .absent;
    return present;
}

/// Records that this account's contact list is now in the store. Called from the
/// ingest door, which is the only way one gets there.
fn noteOwnContactListStored(pk: [32]u8) void {
    g_own_contact_list_memo_for = pk;
    g_own_contact_list_memo = .present;
}

/// Forgets what was remembered about this account's own lists. An identity change
/// misses on the pubkey anyway; this is for the paths that want it gone now.
fn forgetOwnListMemo() void {
    g_own_contact_list_memo = .unknown;
    g_own_contact_list_memo_for = null;
}

pub fn forgetOwnListMemoForTest() void {
    forgetOwnListMemo();
}

/// Whether EVERY relay this reader can read from has answered about this
/// account's contact list, and none of them had one.
///
/// This no longer authorizes anything. It drives the "still looking" line only,
/// because relay silence is not evidence about an account this app did not
/// create: see `canWriteFollows`.
fn contactsConfirmedAbsent() bool {
    const pk = activePubkey() orelse return false;
    lockOwnProfile();
    defer unlockOwnProfile();
    const asked = g_own_contacts_asked_for orelse return false;
    if (!std.mem.eql(u8, &asked, &pk)) return false;
    var answered: usize = 0;
    var readable: usize = 0;
    for (0..relaySlots()) |i| {
        const e = relayAt(i) orelse continue;
        if (!e.read) continue;
        readable += 1;
        if (g_contacts_answered_by[i]) answered += 1;
    }
    if (readable == 0 or answered == 0) return false;
    return answered >= readable;
}

/// Which relays have answered about this account's contact list.
var g_contacts_answered_by = [_]bool{false} ** max_relays;

/// Whether the signed-in key was MINTED by this app, as opposed to imported.
///
/// This is the fact that decides whether creating a contact list from nothing is
/// safe, and it is the one piece of evidence that is not a guess. A key this app
/// made moments ago provably has no history anywhere. A key the reader pasted in
/// has a past this app knows nothing about, and no amount of relay silence turns
/// that into knowledge: on a cold import the relays being asked are the app's
/// own bootstrap five, which may hold none of the reader's real relays, so five
/// clean answers can coexist with eight hundred follows sitting somewhere else.
var g_identity_minted_here = false;

/// What pressing "Create your identity" does to the sign-out latch: drops it
/// before any new key exists. The pubkey latch is what has to hold after this.
pub fn loggedOutForTest() bool {
    return g_logged_out;
}

pub fn clearLoggedOutLatchForTest() void {
    g_logged_out = false;
}

pub fn setIdentityMintedForTest(minted: bool) void {
    g_identity_minted_here = minted;
}

/// Records that relay `index` reached the end of what it holds for this account
/// without producing a contact list.
fn noteContactsAnsweredBy(index: usize, pk: [32]u8) void {
    if (index >= max_relays) return;
    lockOwnProfile();
    defer unlockOwnProfile();
    if (g_own_contacts_asked_for) |asked| {
        if (!std.mem.eql(u8, &asked, &pk)) {
            g_contacts_answered_by = [_]bool{false} ** max_relays;
        }
    }
    g_own_contacts_asked_for = pk;
    g_contacts_answered_by[index] = true;
}

pub fn noteContactsAnsweredByForTest(index: usize, pk: [32]u8) void {
    noteContactsAnsweredBy(index, pk);
}

pub fn contactsConfirmedAbsentForTest() bool {
    return contactsConfirmedAbsent();
}

pub fn haveOwnContactListForTest() bool {
    return haveOwnContactList();
}

/// Follows or unfollows `pubkey`, as newest-known-list plus the change.
///
/// Everything the reader's existing kind:3 carries comes forward untouched: the
/// petnames and relay hints on other people's `p` tags, tag types this app does
/// not model, and the content blob, which on older clients is a relay map and on
/// none of them is ours to discard.
/// What a follow write DID, rather than whether it worked.
///
/// It was a bool, and two of the three callers discarded it. A refusal is a
/// legitimate outcome here and there are four different ones, each with
/// something worth saying: pressing Follow in the first seconds after opening
/// the app is refused because the account's own list has not arrived yet, and
/// what the reader saw was a button that did not move and no reason given.
const FollowWrite = enum {
    published,
    /// Already in the state asked for, or the reader themselves.
    nothing_to_do,
    /// A signature is already out. One key signs one thing at a time.
    signer_busy,
    /// This account's contact list has not been read back yet, and writing one
    /// over a list nobody has seen is the thing this app refuses everywhere.
    no_list_yet,
    /// The shrink guard: the write would have dropped more names than the press
    /// asked for.
    would_shrink,
    failed,
};

fn writeFollow(fx: *Effects, pubkey: [32]u8, following: bool) FollowWrite {
    // Not while a signature is already out. Everything below moves state before
    // it signs, and a rejected sign is silent, so pressing Follow during another
    // sign used to leave the follow set carrying a name that was never published.
    if (!signerReady()) return .signer_busy;
    // No `canWriteFollows()` here on purpose, though it is the same question.
    // It runs its own store query, and this function then ran a SECOND one for
    // the list itself: a transient failure between the two answered "yes they
    // have a list" and then "here is nothing", and nothing is the branch that
    // publishes nine names over eight hundred. The gate below is decided from
    // the one read this function actually uses. `canWriteFollows` stays as what
    // the button asks, where being approximate costs nothing.
    const me = activePubkey() orelse return .failed;
    // Following yourself is not a thing, and an app that lets you is confusing
    // about whose feed it is.
    if (std.mem.eql(u8, &me, &pubkey)) return .nothing_to_do;
    const gpa = std.heap.page_allocator;

    var previous: ?OwnProfile = null;
    if (ownRecordJson(gpa, contact_list_kind)) |own| previous = own;
    defer if (previous) |prev| freeOwnProfile(gpa, prev);

    // A list this app signed moments ago and has not seen come back is newer
    // than anything in the store, so it is the base. Without this, two presses
    // inside one bunker round trip both build on the pre-press list and the
    // second undoes the first, on every relay, with both saying "Following".
    var base_tags: []const nostr.event.Tag = if (previous) |prev| prev.tags else &.{};
    var base_content: []const u8 = if (previous) |prev| prev.json else "";
    var have_base = previous != null;
    var base_created_at: i64 = if (previous) |prev| prev.created_at else 0;
    if (g_pending_follow_tags) |pending| {
        if (g_pending_follow_created_at > base_created_at) {
            base_tags = pending;
            base_content = g_pending_follow_content orelse "";
            base_created_at = g_pending_follow_created_at;
            have_base = true;
        }
    }

    // THE GATE, decided from the read above rather than from a second one.
    // `canWriteFollows` runs its own store query, so a transient failure between
    // the two turned "they have a list, splice onto it" into "they have none,
    // publish the nine names this app chose" over a real list. A key minted here
    // is the only case where having nothing is a fact rather than a read error.
    if (!have_base and !g_identity_minted_here) return .no_list_yet;

    var tags = std.ArrayList(nostr.event.Tag).empty;
    // Freed on every path that does not hand it to the write seam. Two of those
    // paths are the ordinary "already following" and "not following" no-ops, so
    // leaking here would leak a whole contact list per idle press.
    var handed_off = false;
    defer if (!handed_off) {
        for (tags.items) |tag| {
            for (tag) |field| gpa.free(field);
            gpa.free(tag);
        }
        tags.deinit(gpa);
    };
    var found = false;
    var hex: [64]u8 = undefined;
    hexLower(&hex, pubkey);

    if (have_base) {
        for (base_tags) |tag| {
            if (tag.len >= 2 and std.mem.eql(u8, tag[0], "p") and hexEqlIgnoreCase(tag[1], &hex)) {
                found = true;
                // Unfollowing drops the tag; following keeps the one already
                // there, petname, relay hint and all.
                if (!following) continue;
            }
            const copy = gpa.alloc([]const u8, tag.len) catch return .failed;
            for (tag, 0..) |field, i| copy[i] = gpa.dupe(u8, field) catch return .failed;
            tags.append(gpa, copy) catch return .failed;
        }
    } else {
        // No list of their own, and this app minted the key, so there provably
        // is none anywhere. The pack they have been reading becomes the list
        // they publish, so the feed they know travels with them to every other
        // client.
        //
        // This branch is the dangerous one, and the gate above is what makes it
        // safe: reaching here on a guess, or on a store read that merely
        // failed, would replace a real contact list with nine accounts this app
        // chose.
        for (followSet()) |f| {
            if (std.mem.eql(u8, &f, &pubkey)) found = true;
            if (!following and std.mem.eql(u8, &f, &pubkey)) continue;
            var fhex: [64]u8 = undefined;
            hexLower(&fhex, f);
            const copy = gpa.alloc([]const u8, 2) catch return .failed;
            copy[0] = gpa.dupe(u8, "p") catch return .failed;
            copy[1] = gpa.dupe(u8, &fhex) catch return .failed;
            tags.append(gpa, copy) catch return .failed;
        }
    }

    if (following) {
        if (found) return .nothing_to_do; // already followed: nothing to write
        const copy = gpa.alloc([]const u8, 2) catch return .failed;
        copy[0] = gpa.dupe(u8, "p") catch return .failed;
        copy[1] = gpa.dupe(u8, &hex) catch return .failed;
        tags.append(gpa, copy) catch return .failed;
    } else if (!found) {
        return .nothing_to_do; // not followed: nothing to write
    }

    // THE SHRINK GUARD. No client in the ecosystem has one, and it is the
    // cheapest protection here: a follow adds one name and an unfollow removes
    // exactly one, so any write that drops more than that is a bug in this code,
    // a stale base, or a rebase onto somebody else's truncation. It refuses
    // rather than publishing, because the alternative is losing follows to a
    // mistake this app made.
    // Measured against the base the write actually used, which for a signer that
    // has not answered yet is the list this app signed rather than the older one
    // still in the store.
    if (have_base) {
        if (!shrinkAllowed(countPeople(base_tags), countPeople(tags.items), following)) return .would_shrink;
    }

    const owned_tags = tags.toOwnedSlice(gpa) catch return .failed;
    handed_off = true;
    // The content is carried forward verbatim. On older clients it is a relay
    // map, and emptying it would delete a record this app does not even read.
    const content = gpa.dupe(u8, base_content) catch return .failed;
    // Past the base too, not just past the store: a second press inside one
    // signer round trip would otherwise stamp equal to the first, and NIP-01
    // breaks that tie on the id, which is a coin flip over the reader's follows.
    const created = @max(@max(nowSeconds(), ownRecordCreatedAt(contact_list_kind) + 1), base_created_at + 1);

    // The live list moves first, so the feed reflects the press immediately.
    // Tracked in full, not capped: membership has to be right for every name or
    // the next press on somebody past the cap does nothing.
    var next: [max_follows_tracked][32]u8 = undefined;
    const n = followsFromTags(owned_tags, &next);
    _ = setFollows(next[0..n], created);

    // Remembered as the base for the next press BEFORE the write seam is handed
    // the originals, since it owns them from here and the remote path frees them.
    setPendingFollowBase(owned_tags, content, created);
    signAndPublish(fx, gpa, created, contact_list_kind, owned_tags, content, false);
    return .published;
}

/// How many DISTINCT people a tag set names. Distinct on purpose: some clients
/// emit the same person twice, and an unfollow that removes both duplicates has
/// removed one person, not two.
fn countPeople(tags: []const nostr.event.Tag) usize {
    var seen: [max_follows_tracked][32]u8 = undefined;
    var n: usize = 0;
    for (tags) |tag| {
        if (n >= seen.len) break;
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "p")) continue;
        if (tag[1].len != 64) continue;
        var pk: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&pk, tag[1]) catch continue;
        var dup = false;
        for (seen[0..n]) |had| {
            if (std.mem.eql(u8, &had, &pk)) dup = true;
        }
        if (dup) continue;
        seen[n] = pk;
        n += 1;
    }
    return n;
}

// The contact list this app has SIGNED but has not seen come back yet.
//
// `writeFollow` takes its base from the store, and for a bunker or a Notary key
// the store is not written until the signer answers: one to five seconds, longer
// with an approval prompt in front of a human. Two follow presses inside that
// window both read the SAME pre-press list, so the second one publishes a list
// that does not contain the first, at an equal or newer stamp, and the first
// follow is undone on every relay. The reader saw both say "Following".
//
// So a signed list becomes the base for the next write until the real one
// arrives. It is a full copy of the tags, not the follow set: the follow set is
// pubkeys, and rebasing on it would drop every petname, relay hint and tag type
// this app does not model, which is the loss the splice exists to prevent.
var g_pending_follow_tags: ?[]const nostr.event.Tag = null;
var g_pending_follow_content: ?[]u8 = null;
var g_pending_follow_created_at: i64 = 0;

/// Frees the pending base. THE one place that does, so its lifetime is a rule
/// rather than a habit.
fn clearPendingFollowBase() void {
    const gpa = std.heap.page_allocator;
    if (g_pending_follow_tags) |tags| {
        for (tags) |t| {
            for (t) |field| gpa.free(field);
            gpa.free(t);
        }
        gpa.free(tags);
    }
    if (g_pending_follow_content) |c| gpa.free(c);
    g_pending_follow_tags = null;
    g_pending_follow_content = null;
    g_pending_follow_created_at = 0;
}

/// Remembers what was just signed, as the base the next press builds on. Takes
/// its own copy: the write seam owns what it was handed and frees it.
fn setPendingFollowBase(tags: []const nostr.event.Tag, content: []const u8, created_at: i64) void {
    const gpa = std.heap.page_allocator;
    clearPendingFollowBase();
    // No base beats a partial one: a partial one publishes a list with nobody
    // in it. `dupeTags` reports the difference now rather than returning an
    // empty set that reads as "this list was empty".
    const tag_copy = dupeTags(gpa, tags) orelse return;
    g_pending_follow_tags = tag_copy;
    g_pending_follow_content = gpa.dupe(u8, content) catch {
        clearPendingFollowBase();
        return;
    };
    g_pending_follow_created_at = created_at;
}

/// Drops the pending base once the store holds something at least as new, which
/// is the signer's answer having come back and been ingested.
fn releasePendingFollowBase(stored_at: i64) void {
    if (g_pending_follow_tags == null) return;
    if (stored_at < g_pending_follow_created_at) return;
    clearPendingFollowBase();
}

/// Puts the app in the state a bunker or a Notary key leaves it in: a contact
/// list signed, handed to the signer, and not yet in the store. That gap cannot
/// be driven from a test, because the async paths need a live `Effects`, so the
/// state they produce is set up directly and the write is then driven for real.
pub fn setPendingFollowBaseForTest(tags: []const nostr.event.Tag, content: []const u8, created_at: i64) void {
    setPendingFollowBase(tags, content, created_at);
}

pub fn clearPendingFollowBaseForTest() void {
    clearPendingFollowBase();
}

pub fn pendingFollowCountForTest() ?usize {
    const tags = g_pending_follow_tags orelse return null;
    return countPeople(tags);
}

/// Whether a write may shrink the list this much.
///
/// Following adds a name and never removes one; unfollowing removes exactly one.
/// Anything larger is this app's own bug, a stale base, or a rebase onto
/// somebody else's truncation, and refusing beats publishing and finding out
/// later. No client in the ecosystem has this guard.
///
/// It is defense in depth: no path in this file can currently trip it, which is
/// the point. It is here to catch the refactor that would.
fn shrinkAllowed(before: usize, after: usize, following: bool) bool {
    const allowed: usize = if (following) 0 else 1;
    return before <= after + allowed;
}

pub fn countPeopleForTest(tags: []const nostr.event.Tag) usize {
    return countPeople(tags);
}

pub fn shrinkAllowedForTest(before: usize, after: usize, following: bool) bool {
    return shrinkAllowed(before, after, following);
}

/// Two hex strings naming the same key. A `p` tag in the wild is not reliably
/// lower case, and treating `AB…` as a different person from `ab…` would let a
/// follow silently duplicate somebody already on the list.
fn hexEqlIgnoreCase(a: []const u8, b: []const u8) bool {
    return std.ascii.eqlIgnoreCase(a, b);
}

pub fn writeFollowForTest(fx: *Effects, pubkey: [32]u8, following: bool) bool {
    return writeFollow(fx, pubkey, following) == .published;
}

/// The reader's own kind:3, arriving from a relay. Adopted when it is NEWER than
/// what is held, so a slower relay's older copy never undoes a newer one, and
/// unless they have written one here since.
fn ingestContactList(ev: nostr.event.Event) void {
    const pk = activePubkey() orelse return;
    if (!std.mem.eql(u8, &pk, &ev.pubkey)) return;
    lockFollows();
    const owned = followsAreOwned();
    const held_at = g_follow_created_at;
    unlockFollows();
    // The signer answered and the list came back: the copy this app was holding
    // as a base has been superseded by the real one.
    releasePendingFollowBase(ev.created_at);
    // Their hands beat their history, and history beats older history.
    if (owned and ev.created_at <= held_at) return;
    var list: [max_follows_tracked][32]u8 = undefined;
    const n = followsFromTags(ev.tags, &list);
    // A contact list with no usable `p` tag is not a list. Adopting it would
    // empty the reader's feed on the word of one malformed event.
    if (n == 0) return;
    _ = setFollows(list[0..n], ev.created_at);
}

/// The pubkeys a kind:3's `p` tags name, in their published order, deduped.
fn followsFromTags(tags: []const nostr.event.Tag, out: [][32]u8) usize {
    var n: usize = 0;
    for (tags) |tag| {
        if (n >= out.len) break;
        if (tag.len < 2) continue;
        if (!std.mem.eql(u8, tag[0], "p")) continue;
        if (tag[1].len != 64) continue;
        var pk: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&pk, tag[1]) catch continue;
        var seen = false;
        for (out[0..n]) |had| {
            if (std.mem.eql(u8, &had, &pk)) seen = true;
        }
        if (seen) continue;
        out[n] = pk;
        n += 1;
    }
    return n;
}

pub fn followsFromTagsForTest(tags: []const nostr.event.Tag, out: [][32]u8) usize {
    return followsFromTags(tags, out);
}

pub fn setFollowsForTest(list: []const [32]u8, created_at: i64) bool {
    return setFollows(list, created_at);
}

pub fn forgetFollowsForTest() void {
    forgetFollows();
}

pub fn loadFollowsFromStoreForTest() void {
    loadFollowsFromStore();
}

pub fn ingestContactListForTest(ev: nostr.event.Event) void {
    ingestContactList(ev);
}

/// Whether a pubkey is inside the reader's follow graph: the accounts whose
/// replies rank first in a thread. That is the reader themself, plus EVERY
/// account on their contact list, plus the starter pack while the pack is what
/// the feed reads.
///
/// Asked of the whole list, never of `followSet()`. That one is capped at
/// `max_follows` because it is the FEED's author set, and the feed pays a relay
/// filter entry and a store cursor per author, so it is deliberately a slice.
/// Membership is a different question and has no reason to be capped: asking it
/// of the slice told a reader with three hundred follows that follows 129 and up
/// were strangers, in every thread, forever. Worse, a new follow is APPENDED, so
/// the people most recently followed were the ones most likely to be misfiled.
///
/// Two differences from `isInReadGraph`, both deliberate. Your OWN replies are
/// inside your conversation, though you do not follow yourself and the inbox
/// would be wrong if you did. And a GUEST still has a graph here: they are
/// reading the pack, so pack members are the conversation and everyone else is
/// the crowd, where for the inbox a guest has nothing to rank at all.
pub fn inFollowGraph(pubkey: [32]u8) bool {
    if (activePubkey()) |me| {
        if (std.mem.eql(u8, &me, &pubkey)) return true;
    }
    return inFollowedSet(pubkey);
}

/// Groups the arranged (depth-stamped, conversation-ordered) replies into blocks.
/// The arrangement is a DFS, so a parent's subtree is contiguous: everything at
/// depth 2 until the next top-level reply is a child, and anything deeper counts
/// against the child it hangs beneath.
pub fn groupThreadBlocks(ui: *AppUi, notes: []const Note) []const ThreadBlock {
    if (notes.len == 0) return &.{};
    const blocks = ui.arena.alloc(ThreadBlock, notes.len) catch return &.{};
    const deeper_pool = ui.arena.alloc(usize, notes.len) catch return &.{};
    var block_count: usize = 0;
    var pool_used: usize = 0;
    var i: usize = 0;
    while (i < notes.len) {
        const parent = &notes[i];
        i += 1;
        const child_start = i;
        var child_count: usize = 0;
        while (i < notes.len and notes[i].depth >= 2) {
            if (notes[i].depth == 2) {
                deeper_pool[pool_used + child_count] = 0;
                child_count += 1;
            } else if (child_count > 0) {
                // Deeper than the one level shown: counted against the child whose
                // branch it continues.
                deeper_pool[pool_used + child_count - 1] += 1;
            }
            i += 1;
        }
        blocks[block_count] = .{
            .parent = parent,
            .children = notes[child_start..][0..child_count],
            .deeper = deeper_pool[pool_used..][0..child_count],
        };
        block_count += 1;
        pool_used += child_count;
    }
    return blocks[0..block_count];
}

/// How many indent steps a reply at `depth` shows. Direct replies (depth 1)
/// sit flush; each further level steps in once, capped so a long back-and-forth
/// never squeezes the text to a sliver; past the cap, deeper replies share the
/// cap's inset (the convention every threaded reader settles on).
const thread_indent_cap = 3;
const thread_indent_step: f32 = 24;

pub fn threadIndentLevels(depth: u8) usize {
    if (depth <= 1) return 0;
    return @min(@as(usize, depth - 1), thread_indent_cap);
}

/// The nesting gutter to the left of an indented reply: one fixed-width cell
/// per ancestor level, each carrying a hairline rail, so siblings at a depth
/// visibly hang off the same line. Empty (and costless) at the top level.
fn threadGutter(ui: *AppUi, levels: usize) AppUi.Node {
    if (levels == 0) return ui.spacer(0);
    const p = theme.palette;
    const cells = ui.arena.alloc(AppUi.Node, levels) catch return ui.spacer(0);
    for (cells) |*cell| {
        // The rail fills the row's height on its own via cross-axis stretch.
        cell.* = ui.row(.{ .width = thread_indent_step, .main = .center }, .{
            ui.separator(.{ .width = 1, .style = .{ .foreground = p.border_hairline, .background = p.border_hairline } }),
        });
    }
    return ui.row(.{}, .{cells});
}

/// One top-level reply and the level of conversation under it. The block draws
/// the reply at note size against a rail, then each of its own replies at a
/// smaller register hanging off that rail, then a line for whatever the branch
/// continues into.
///
/// The reply itself is a feed-style row, with an "OP" chip when the replier is
/// the thread's original author, seated under the note it answers by the nesting
/// gutter. The WRAPPER row carries the press and the hover wash, so every
/// horizontal pixel of the row (gutter included) opens this reply as its own
/// thread and washes as one unit; the picture and the engagement controls keep
/// their own presses as the deeper hit targets. The bottom hairline lives INSIDE
/// the content column: it starts after the gutter (so it aligns with the content
/// it separates) and the gutter's rails span the wrapper's full height across it,
/// keeping a sibling run's rail continuous.
///
/// The rail replaces the round-4 indent gutter: the redesign nests ONE level in
/// place and sends the rest to their own thread, rather than stepping every reply
/// further right until the text runs out of room.
/// One line saying this reply answers something the app does not have.
///
/// The same words the ghost row uses at the top of an ancestor chain, for the
/// same reason: the note is not claimed to be gone, only absent from here. It
/// may arrive when a relay answers.
fn orphanNote(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            ui.appIcon(.{ .width = 11, .height = 11, .style = .{ .foreground = p.text_dim } }, "clock"),
            hgap(ui, 6),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_dim } },
                &.{.{ .text = "The note this answers is not on your relays yet", .scale = stat_scale }},
            ),
        }),
        vgap(ui, 6),
    });
}

fn replyBlock(ui: *AppUi, model: *const Model, block: *const ThreadBlock, root_author: [32]u8, first: bool, last: bool) AppUi.Node {
    const p = theme.palette;
    const note = block.parent;
    const kids = ui.arena.alloc(AppUi.Node, block.children.len * 2) catch return ui.spacer(0);
    var n: usize = 0;
    for (block.children, block.deeper) |*child, deeper| {
        kids[n] = nestedReply(ui, child, root_author);
        n += 1;
        if (deeper > 0) {
            kids[n] = branchMore(ui, child, deeper);
            n += 1;
        }
    }

    var node = ui.column(.{ .width = thread_column_width, .gap = 0 }, .{
        // The first block takes the full-width rule that separates the replies
        // from the note they answer; between blocks the rule is inset to the text,
        // so the rails run unbroken down the gutter.
        if (first)
            ui.separator(.{ .width = thread_column_width, .style = .{ .foreground = p.divider_reply, .background = p.divider_reply } })
        else
            ui.spacer(0),
        vgap(ui, 12),
        if (note.parent_missing)
            ui.row(.{ .gap = 0 }, .{ hgap(ui, thread_inset + avatar_size + avatar_to_text_gap), orphanNote(ui) })
        else
            ui.spacer(0),
        // No `cross` here: the default stretches the children, which is what
        // gives the rail a height to grow into. Pinned to the top, the disc's
        // column would be exactly as tall as the disc and the rail would draw
        // nothing at all, which is how it shipped invisible.
        // The reply's OWN row, and only it: the wash belongs to the row under the
        // pointer, and a band covering this reply plus everything nested under it
        // is one highlight over three rows.
        ui.el(.data_row, .{
            .width = thread_column_width,
            .padding = 0.01,
            .on_press = Msg{ .open_thread = note.id },
            .context_menu = noteContextItems(ui, note, false),
            .semantics = .{ .label = "Open thread" },
        }, .{
            hgap(ui, thread_inset),
            // The disc, with the rail below it: the line a reply's own replies
            // hang from. It runs to the bottom of this row and the children's
            // section picks it up from there, so the line reads as one.
            ui.column(.{ .cross = .center, .gap = 0 }, .{
                noteAvatar(ui, note),
                vgap(ui, 4),
                ui.separator(.{ .width = 2, .grow = 1, .style = .{ .foreground = p.border_hairline, .background = p.border_hairline } }),
            }),
            hgap(ui, avatar_to_text_gap),
            ui.column(.{ .grow = 1, .gap = 0 }, .{
                ui.row(.{ .gap = 6, .cross = .start }, .{
                    identityBlock(ui, note),
                    ui.spacer(1),
                    ui.paragraph(.{ .style = .{ .foreground = p.text_faint_alt } }, timeSpans(ui, note, meta_scale)),
                }),
                vgap(ui, 5),
                noteBody(ui, note, true),
                if (note.hasImage()) vgap(ui, 8) else ui.spacer(0),
                if (note.hasImage()) notePicture(ui, note) else ui.spacer(0),
                if (note.hasLink()) linkCard(ui, note) else ui.spacer(0),
                vgap(ui, 8),
                engagementRow(ui, model, note),
            }),
            hgap(ui, thread_inset),
        }),
        // What hangs off this reply: its own replies and the line into whatever
        // the branch continues into, in the same gutter so the rail runs on.
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, thread_inset),
            ui.row(.{ .width = avatar_size, .main = .center }, .{
                ui.separator(.{ .width = 2, .style = .{ .foreground = p.border_hairline, .background = p.border_hairline } }),
            }),
            hgap(ui, avatar_to_text_gap),
            ui.column(.{ .grow = 1, .gap = 0 }, .{
                ui.column(.{ .gap = 0 }, .{kids[0..n]}),
                vgap(ui, if (last) 4 else 12),
                // The rule between blocks starts at the text, not the window edge,
                // so the rail crosses it without a break. The last block draws
                // none: a rule with nothing under it is a dangling line, and its
                // trailing space is what tips a thread that fits into reporting
                // more content than it draws.
                if (last)
                    ui.spacer(0)
                else
                    ui.separator(.{ .style = .{ .foreground = p.divider_reply, .background = p.divider_reply } }),
            }),
            hgap(ui, thread_inset),
        }),
    });
    node.key = .{ .int = @intCast(note.id) };
    return node;
}

/// One note in the chain above the focal note: the same disc and identity block
/// as a reply, a body clamped to two lines, and the rail running down to the next
/// disc. Pressing it focuses that note, which is how a reader walks back up a
/// conversation without leaving the thread.
///
/// The chain is drawn INLINE rather than as the stack of panels it used to be:
/// one scroll, so the ancestors read as the run-up to the note being read instead
/// of as screens behind it. The panel stack stays mounted underneath purely to
/// hold each level's scroll offset for the walk back.
fn ancestorRow(ui: *AppUi, ancestor: *const Ancestor, first: bool) AppUi.Node {
    if (ancestor.ghost != .none) return ghostRow(ui, ancestor, first);
    const p = theme.palette;
    const note = &ancestor.note;
    return ui.column(.{ .width = thread_column_width, .gap = 0 }, .{
        if (first) vgap(ui, ancestor_top_pad) else ui.spacer(0),
        // The row stretches its children (the default cross alignment), which is
        // what gives the rail a height to grow into: pinned to the top instead,
        // the avatar column would be exactly as tall as the disc and the rail
        // would draw nothing.
        // A `list_item`, which is the kind the renderer washes on hover, given an
        // explicit width so it constrains the body instead of sizing to it.
        ui.el(.data_row, .{
            .width = thread_column_width,
            .padding = 0.01,
            // By EVENT id: an ancestor is neither in the feed nor in the open
            // thread's replies, so the render key `open_thread` resolves through
            // would find nothing and the press would quietly do nothing.
            .on_press = Msg{ .open_event = note.event_id },
            .semantics = .{ .role = .button, .label = "Focus this note" },
        }, .{
            hgap(ui, thread_inset),
            ui.column(.{ .cross = .center, .gap = 0 }, .{
                noteAvatar(ui, note),
                vgap(ui, 4),
                // The rail, filling whatever is left of the row: the line that
                // ties this note to the one it leads to.
                ui.separator(.{ .width = 2, .grow = 1, .style = .{ .foreground = p.border_hairline, .background = p.border_hairline } }),
            }),
            hgap(ui, avatar_to_text_gap),
            ui.column(.{ .grow = 1, .gap = 0 }, .{
                ui.row(.{ .gap = 6, .cross = .start }, .{
                    identityBlock(ui, note),
                    ui.spacer(1),
                    ui.paragraph(.{ .style = .{ .foreground = p.text_faint_alt } }, timeSpans(ui, note, meta_scale)),
                }),
                // The gap stays whatever the body is: it is a term of the row's
                // chrome, and dropping it would make the estimate wrong by 4px
                // for exactly the rows nothing measures.
                vgap(ui, ancestor_identity_gap),
                if (note.content_len == 0) ui.spacer(0) else ancestorBody(ui, note),
                vgap(ui, ancestor_bottom_pad),
            }),
            hgap(ui, thread_inset),
        }),
    });
}

/// An ancestor's body, cut to two lines. The SDK has no multi-line clamp, so the
/// cut is made in the SPANS: building them from the whole text first keeps a
/// mention reading as `@name` rather than as half of a bech32 token.
fn ancestorBody(ui: *AppUi, note: *const Note) AppUi.Node {
    const spans = clampSpansToLines(ui, contentSpans(ui, note.content()), ancestor_body_lines);
    return textParaAt(ui, spans, nested_body_scale, theme.palette.text_secondary_alt);
}

/// `spans` cut to at most `lines` lines, with an ellipsis where the cut falls.
///
/// Lines are counted the way the estimator counts them, by characters against a
/// column width, plus every newline the text writes for itself: a note that
/// breaks its own lines is the case a character budget alone gets wrong, and it
/// is a common shape (a note that ends in a `nostr:` reference on its own line).
fn clampSpansToLines(ui: *AppUi, spans: []const canvas.TextSpan, lines: usize) []const canvas.TextSpan {
    const out = ui.arena.alloc(canvas.TextSpan, spans.len) catch return spans;
    // One column of the last line belongs to the ellipsis. Cutting at the full
    // budget and THEN appending it wrapped one character onto a third line,
    // which is a line the estimator does not price and the design does not have.
    const budget = ancestor_chars_per_line - 1;
    var n: usize = 0;
    var line: usize = 1;
    var column: usize = 0;
    for (spans) |span| {
        var cut: ?usize = null;
        for (span.text, 0..) |c, i| {
            // A continuation byte is the middle of a character, not another one.
            if ((c & 0xc0) == 0x80) continue;
            if (c == '\n' or column >= budget) {
                line += 1;
                column = 0;
                if (line > lines) {
                    cut = i;
                    break;
                }
            }
            if (c != '\n') column += 1;
        }
        if (cut) |at| {
            // Back off to a word boundary, so the ellipsis follows a whole word.
            // The budget is the WHOLE span, not `at`: `collapsedLen` returns the
            // length unchanged when the text already fits, so cutting a slice at
            // its own length backs off nowhere.
            const end = collapsedLen(span.text, at);
            if (end > 0) {
                out[n] = span;
                out[n].text = ui.fmt("{s}…", .{std.mem.trimEnd(u8, span.text[0..end], " \n")});
                n += 1;
            } else if (n > 0) {
                out[n - 1].text = ui.fmt("{s}…", .{std.mem.trimEnd(u8, out[n - 1].text, " \n")});
            }
            return out[0..n];
        }
        out[n] = span;
        n += 1;
    }
    return out[0..n];
}

/// The ancestor row and one reply block, for a test that asserts what they PAINT
/// (the rail between two discs is a grown separator, so it only exists when the
/// row hands its avatar column a height, which is exactly what once went wrong).
pub fn ancestorRowForTest(ui: *AppUi, ancestor: *const Ancestor, first: bool) AppUi.Node {
    return ancestorRow(ui, ancestor, first);
}

pub fn replyBlockForTest(ui: *AppUi, model: *const Model, block: *const ThreadBlock, root_author: [32]u8, first: bool, last: bool) AppUi.Node {
    return replyBlock(ui, model, block, root_author, first, last);
}

/// The rows a level can hold whose height is a fixed constant, so a test can
/// measure each one and hold its estimate to what it actually draws. Every
/// constant here was hand-calibrated once and then drifted.
pub fn ghostRowForTest(ui: *AppUi, capped: bool) AppUi.Node {
    const ancestor: Ancestor = .{ .ghost = if (capped) .capped else .missing };
    return ghostRow(ui, &ancestor, true);
}

pub fn listeningFooterForTest(ui: *AppUi) AppUi.Node {
    return listeningFooter(ui);
}

pub fn outsideGraphRowForTest(ui: *AppUi, open: bool) AppUi.Node {
    return outsideGraphRow(ui, 2, open);
}

pub fn showMoreRepliesForTest(ui: *AppUi) AppUi.Node {
    return showMoreReplies(ui, 3);
}

pub const ghost_row_extent_for_test = ghost_row_extent;
pub const listening_row_extent_for_test = listening_row_extent;
pub const outside_row_extent_for_test = outside_row_extent;
pub const show_more_extent_for_test = show_more_extent;
pub const ancestor_row_chrome_for_test = ancestor_row_chrome;

pub fn ancestorBodyLinesForTest(note: *const Note) f32 {
    return ancestorBodyLines(note);
}

/// The gap at the top of the chain: a dashed seat where a note would be, saying
/// what is missing and what the app is doing about it. Never a spinner over the
/// thread, and never a claim that the note does not exist.
fn ghostRow(ui: *AppUi, ancestor: *const Ancestor, first: bool) AppUi.Node {
    const p = theme.palette;
    const capped = ancestor.ghost == .capped;
    const headline: []const u8 = if (capped)
        "Earlier notes in this thread are not shown"
    else if (ancestor.is_root)
        "Root note not on your relays yet"
    else
        "The note this answers is not on your relays yet";
    const detail: []const u8 = if (capped)
        ui.fmt("showing the {d} nearest below", .{thread_ancestor_max})
    else
        pluralize(ui, liveRelayCount(), "asking {d} relay · fills in when one answers", "asking {d} relays · fills in when one answers");
    return ui.column(.{ .width = thread_column_width, .gap = 0 }, .{
        if (first) vgap(ui, ancestor_top_pad) else ui.spacer(0),
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, thread_inset),
            ui.column(.{ .cross = .center, .gap = 0 }, .{
                // The empty seat: the canvas has no dashed strokes, so the ring is
                // an icon with its dashes baked into the geometry, with the glyph
                // stacked over it.
                ui.stack(.{ .width = avatar_size, .height = avatar_size }, .{
                    ui.appIcon(.{ .width = avatar_size, .height = avatar_size, .style = .{ .foreground = p.border_dashed } }, "dashed-ring"),
                    ui.column(.{ .width = avatar_size, .height = avatar_size, .main = .center, .cross = .center }, .{
                        // A runtime choice of glyph, so `appIcon` (which resolves
                        // the built-in names too) rather than comptime `icon`.
                        ui.appIcon(.{ .width = 13, .height = 13, .style = .{ .foreground = p.text_dim } }, if (capped) "chevron-up" else "clock"),
                    }),
                }),
                vgap(ui, 4),
                ui.separator(.{ .width = 2, .grow = 1, .style = .{ .foreground = p.border_hairline, .background = p.border_hairline } }),
            }),
            hgap(ui, avatar_to_text_gap),
            ui.column(.{ .grow = 1, .gap = 0 }, .{
                vgap(ui, 2),
                ui.paragraph(.{ .style = .{ .foreground = p.text_muted } }, &.{.{ .text = headline, .scale = nested_name_scale }}),
                vgap(ui, 3),
                ui.paragraph(.{ .style = .{ .foreground = p.text_dim } }, &.{.{ .text = detail, .monospace = true, .scale = mono_meta_scale }}),
                vgap(ui, ancestor_bottom_pad),
            }),
            hgap(ui, thread_inset),
        }),
    });
}

/// The line at the foot of a thread: the subscription is still open, and what
/// arrives is appended rather than shuffled into what has already been read,
/// which is the promise the reply order keeps.
fn listeningFooter(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    const live = liveRelayCount();
    return ui.column(.{ .width = thread_column_width, .gap = 0 }, .{
        // The last conversation above closes at 4px (it draws no rule of its
        // own, so nothing dangles), and this makes up the rest of the step.
        vgap(ui, 8),
        ui.separator(.{ .width = thread_column_width, .style = .{ .foreground = p.divider_row, .background = p.divider_row } }),
        vgap(ui, 10),
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            hgap(ui, thread_inset),
            ui.el(.panel, .{ .width = 6, .height = 6, .padding = 0.01, .style = .{ .background = if (live > 0) p.status_success else p.status_offline, .radius = 3, .stroke_width = 0 } }, .{}),
            hgap(ui, 8),
            ui.paragraph(.{ .style = .{ .foreground = p.text_dim } }, &.{.{
                .text = if (live > 0)
                    "listening · new replies land as relays answer, appended, never reordered"
                else
                    "no relay connected · replies land when one answers",
                .monospace = true,
                .scale = mono_meta_scale,
            }}),
        }),
        vgap(ui, 10),
    });
}

/// A reply to a reply: the one level of nesting the redesign draws in place, at a
/// smaller disc and a smaller register than the reply it answers.
fn nestedReply(ui: *AppUi, note: *const Note, root_author: [32]u8) AppUi.Node {
    const p = theme.palette;
    const is_author = std.mem.eql(u8, &note.pubkey, &root_author);
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 8),
        ui.el(.data_row, .{
            .grow = 1,
            .padding = 0.01,
            .cross = .start,
            .on_press = Msg{ .open_thread = note.id },
            .context_menu = noteContextItems(ui, note, false),
            .semantics = .{ .label = "Open thread" },
        }, .{
            avatarDisc(ui, note, nested_avatar_size),
            hgap(ui, 10),
            ui.column(.{ .grow = 1, .gap = 0 }, .{
                ui.row(.{ .gap = 6, .cross = .center }, .{
                    ui.paragraph(.{ .style = .{ .foreground = p.text_primary } }, &.{.{ .text = note.author(), .weight = .medium, .scale = nested_name_scale }}),
                    // The original poster, marked in their own thread. In the
                    // author's avatar tint, so the chip reads as them.
                    if (is_author) opChip(ui, note.pubkey) else ui.spacer(0),
                    if (note.verified())
                        ui.icon(.{ .width = 11, .height = 11, .style = .{ .foreground = p.status_success } }, "check-circle")
                    else
                        ui.spacer(0),
                    nestedHandle(ui, note),
                    ui.spacer(1),
                    ui.paragraph(.{ .style = .{ .foreground = p.text_faint_alt } }, timeSpans(ui, note, nested_meta_scale)),
                }),
                vgap(ui, 3),
                noteBodyAt(ui, note, true, nested_body_scale, p.text_nested),
            }),
        }),
    });
}

/// The OP chip: the thread's author, marked where they answer inside it.
fn opChip(ui: *AppUi, pubkey: [32]u8) AppUi.Node {
    const tint = avatarTint(pubkey);
    return ui.el(.panel, .{ .padding = 0.01, .style = .{ .background = tint.bg, .border = tint.border, .radius = 4, .stroke_width = 1 } }, .{
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            hgap(ui, 5),
            ui.paragraph(.{ .style = .{ .foreground = tint.glyph } }, &.{.{ .text = "OP", .weight = .medium, .monospace = true, .scale = op_chip_scale }}),
            hgap(ui, 5),
        }),
    });
}

/// A nested reply's handle, one register below the reply it answers.
///
/// The same ladder the row above it uses, not `Note.handle`. These sit on the
/// same screen, so an author whose NIP-05 reads `dergigi@primal.net` in one and
/// `@dergigi` in the other is the app spelling one identity two ways within a
/// thread.
fn nestedHandle(ui: *AppUi, note: *const Note) AppUi.Node {
    const handle = note.handleLabel(ui.arena).text;
    if (handle.len == 0) return ui.spacer(0);
    return ui.paragraph(
        .{ .style = .{ .foreground = theme.palette.accent_identity } },
        &.{.{ .text = handle, .scale = nested_meta_scale }},
    );
}

/// The line that holds the strangers: how many replies came from outside the
/// follow graph, and a press that shows them. They are never deleted, only held,
/// which is what the line says.
fn outsideGraphRow(ui: *AppUi, count: usize, open: bool) AppUi.Node {
    const p = theme.palette;
    // The row's own padding sits INSIDE it, so the wash covers the band the shot
    // pads rather than a stripe through the middle of it. The height is stated
    // because a `list_item` carries a 28px intrinsic row floor, and this line is
    // a single 18px text line: without it the quiet line grows ten pixels looser
    // than the shot.
    return ui.el(
        .data_row,
        .{
            .width = thread_column_width,
            .height = outside_row_extent,
            .padding = 0.01,
            .cross = .center,
            .on_press = .toggle_outside_replies,
            // The row is a disclosure, so it says which way it is pointing: the
            // glyph, the verb in the label, and the accessible expanded state.
            .expanded = open,
            .semantics = .{ .role = .button, .label = if (open) "Hide replies from outside your graph" else "Show replies from outside your graph", .focusable = true },
        },
        .{
            hgap(ui, 52),
            // The glyph is chosen at runtime, so `appIcon` (which resolves the
            // built-in names too) rather than the comptime-checked `icon`.
            ui.appIcon(.{ .width = 12, .height = 12, .style = .{ .foreground = p.text_dim } }, if (open) "chevron-up" else "eye"),
            hgap(ui, 7),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_muted } },
                &.{.{ .text = pluralize(ui, count, "{d} reply from outside your graph", "{d} replies from outside your graph"), .scale = meta_scale }},
            ),
            hgap(ui, 7),
            // What the line is doing right now: holding them, or having shown
            // them. Saying "held below" under replies that are on screen would
            // be the same kind of stale label the round keeps finding.
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_dim } },
                &.{.{ .text = if (open) "shown, below your graph" else "held below, never deleted", .monospace = true, .scale = mono_meta_scale }},
            ),
        },
    );
}

/// The line under a page of replies: how many conversations are still folded, and
/// a press that reveals the next page.
fn showMoreReplies(ui: *AppUi, hidden: usize) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .width = thread_column_width, .gap = 0 }, .{
        vgap(ui, 12),
        // Height stated for the same reason as the held line: a `list_item` (the
        // kind that washes) carries a 28px intrinsic floor.
        ui.el(.data_row, .{
            .width = thread_column_width,
            .height = show_more_extent - 12 - 10,
            .padding = 0.01,
            .cross = .center,
            .on_press = .show_more_replies,
            .semantics = .{ .role = .button, .label = "Show more replies", .focusable = true },
        }, .{
            hgap(ui, 52),
            ui.icon(.{ .width = 12, .height = 12, .style = .{ .foreground = p.text_muted } }, "chevron-down"),
            hgap(ui, 7),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_secondary } },
                &.{.{ .text = pluralize(ui, hidden, "Show {d} more reply", "Show {d} more replies"), .weight = .medium, .scale = stat_scale }},
            ),
        }),
        vgap(ui, 10),
    });
}

/// What a branch continues into: how many replies hang below the level shown, and
/// a press that opens that reply as its own thread, where they all fit.
fn branchMore(ui: *AppUi, child: *const Note, deeper: usize) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 6),
        ui.el(.data_row, .{
            .grow = 1,
            .height = branch_more_extent - 6,
            .padding = 0.01,
            .cross = .center,
            .on_press = Msg{ .open_thread = child.id },
            .semantics = .{ .role = .button, .label = "More in this branch", .focusable = true },
        }, .{
            // Indented to the nested rail, so the line reads as part of the branch
            // it belongs to.
            hgap(ui, nested_avatar_size + 10),
            ui.icon(.{ .width = 12, .height = 12, .style = .{ .foreground = p.text_muted } }, "arrow-right"),
            hgap(ui, 6),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_secondary } },
                &.{.{ .text = ui.fmt("More in this branch · {d}", .{deeper}), .weight = .medium, .scale = stat_scale }},
            ),
        }),
    });
}

/// The pinned reply composer at the bottom of a thread: type a reply and send it
/// to the root note. Pre-filled with whom you are answering.
fn replyComposer(ui: *AppUi, model: *const Model, root: *const Note) AppUi.Node {
    const p = theme.palette;
    const ready = !model.reply_empty();
    return ui.column(.{ .width = thread_column_width, .gap = 0 }, .{
        ui.separator(.{ .width = thread_column_width, .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
        vgap(ui, 10),
        // Top-aligned, because the field is taller than one line now: the avatar
        // belongs beside the first line of what you are writing, not floating in
        // the middle of a half-empty box.
        ui.row(.{ .cross = .start, .gap = 0 }, .{
            hgap(ui, thread_inset),
            meAvatar(ui, avatar_size),
            hgap(ui, avatar_to_text_gap),
            // A `textarea`, not a `text_field`: Enter inserts a newline here and
            // the primary chord submits, which is the whole point. A reply is
            // often the paragraph the note deserved, and a single line asked
            // people to write it somewhere else and paste it back.
            //
            // The pill had to go with it. A capsule only reads as one on a
            // single line; at three it becomes a lozenge with the text pushed
            // off its own corners, so the shape follows the content and matches
            // the cards everywhere else.
            ui.el(.textarea, .{
                .grow = 1,
                .height = reply_editor_height,
                .padding = 14,
                .text = model.reply_draft(),
                // By handle, as the shot addresses them: a reply is to an account,
                // and the name above already said who that is.
                .placeholder = ui.fmt("Reply to {s}…", .{replyTarget(ui, root)}),
                .on_input = AppUi.inputMsg(.reply_edit),
                .on_submit = .reply_submit,
                .style = .{ .background = p.surface_input, .border = p.border_chip, .radius = settings_card_radius, .stroke_width = 1 },
            }, .{}),
            hgap(ui, 10),
            // The verb sits beside the field, quiet until there is something to
            // send: an empty reply has nothing to confirm.
            ui.row(.{
                .cross = .center,
                .gap = 0,
                .on_press = if (ready) Msg.reply_submit else null,
                .style = .{ .quiet_hover = true },
                // A button that is currently unavailable, said in the words the
                // platform has for it. `disabled` empties the widget's advertised
                // actions at the source (`semanticActions` returns nothing for a
                // disabled widget), so it announces the true thing to a screen
                // reader, "Reply, dimmed", rather than a button that is silent
                // about why pressing it does nothing.
                .disabled = !ready,
                .semantics = .{ .role = .button, .label = "Reply", .focusable = ready },
            }, .{
                ui.el(.panel, .{ .padding = 0.01, .style = .{ .background = if (ready) p.accent else p.surface_rail_tile, .radius = 8, .stroke_width = 0 } }, .{
                    ui.row(.{ .cross = .center, .gap = 0 }, .{
                        hgap(ui, 14),
                        vgap(ui, 30),
                        ui.paragraph(
                            .{ .style = .{ .foreground = if (ready) p.on_accent else p.text_muted } },
                            &.{.{ .text = "Reply", .weight = .medium, .scale = stat_scale }},
                        ),
                        hgap(ui, 14),
                    }),
                }),
            }),
            hgap(ui, thread_inset),
        }),
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, thread_inset + avatar_size + avatar_to_text_gap),
            replyNotifyRow(ui, model, root),
        }),
        vgap(ui, 10),
    });
}

/// Wraps a thread level's panel in a full-bleed opaque panel that occludes
/// whatever is beneath it (a bare column does not reliably paint its background;
/// the `.card` element does). Keyed by the level's root id so the whole level
/// keeps its identity, and its scroll offset, as levels push and pop above it.
fn threadOccluder(ui: *AppUi, level_key: u64, panel: AppUi.Node) AppUi.Node {
    const p = theme.palette;
    // A bare `.card` injects the house 24px content padding whenever `padding`
    // is left at zero (zero IS the unset sentinel), which framed the whole
    // thread page in a margin the feed does not have. A hair above zero opts
    // out while staying invisibly small, so the thread sits flush like the feed.
    return ui.el(.card, .{ .grow = 1, .padding = 0.01, .global_key = .{ .int = level_key }, .style = .{ .background = p.surface_window, .border = p.surface_window, .radius = 0, .stroke_width = 0 } }, .{panel});
}

/// The band, drawn from the registered image. `cover` so a wide picture fills
/// the strip rather than letterboxing inside it.
fn bannerImage(ui: *AppUi) AppUi.Node {
    var node = ui.image(.{
        .image = banner_image_id,
        .height = profile_banner_height,
        .grow = 1,
        .semantics = .{ .label = "Profile banner" },
    });
    node.widget.image_fit = .cover;
    return node;
}

/// The banner currently registered, and for whom. One at a time, because one
/// screen shows one.
var g_banner_for: ?[32]u8 = null;
/// Who the in-flight fetch was started for, which is not always who is on
/// screen by the time it lands.
var g_banner_asked_for: ?[32]u8 = null;
var g_banner_state: enum { idle, fetching, loaded, failed } = .idle;
var g_banner_url_buf: [1024]u8 = undefined;
var g_banner_url_len: u16 = 0;

fn bannerUrl() []const u8 {
    return g_banner_url_buf[0..g_banner_url_len];
}

/// Whether a banner is registered for `pubkey` right now.
fn bannerReady(pubkey: [32]u8) bool {
    const who = g_banner_for orelse return false;
    return g_banner_state == .loaded and std.mem.eql(u8, &who, &pubkey);
}

/// Asks for the open profile's banner, once per person.
fn scanBannerFetch(fx: *Effects, model: *const Model) void {
    const pubkey = model.viewing_profile orelse {
        // Left the screen: the next person starts clean.
        g_banner_for = null;
        g_banner_state = .idle;
        return;
    };
    if (!g_media_previews) return;
    const changed = if (g_banner_for) |who| !std.mem.eql(u8, &who, &pubkey) else true;
    if (changed) {
        g_banner_for = pubkey;
        g_banner_state = .idle;
        g_banner_url_len = 0;
    }
    if (g_banner_state != .idle) return;

    const raw = personBanner(pubkey);
    if (raw.len == 0) return;
    var url_buf: [1024]u8 = undefined;
    const url = mediaUrl(&url_buf, raw, banner_target_px, .inside);
    const n = @min(url.len, g_banner_url_buf.len);
    @memcpy(g_banner_url_buf[0..n], url[0..n]);
    g_banner_url_len = @intCast(n);

    if (loadCachedImage(fx, banner_image_id, bannerUrl(), banner_target_px)) |_| {
        g_banner_state = .loaded;
        return;
    }
    g_banner_state = .fetching;
    g_banner_asked_for = pubkey;
    fx.fetch(.{
        .key = banner_fetch_key,
        .url = bannerUrl(),
        .on_response = Effects.responseMsg(.banner_fetched),
    });
}

/// Deliberately not 4000: that is `link_fetch_key_base + 0`, and the runtime
/// rejects a second fetch under a key already in flight, so a banner and the
/// first link preview would refuse each other.
const banner_fetch_key: u64 = 5000;

fn handleBannerFetched(fx: *Effects, response: native_sdk.EffectResponse) void {
    if (response.key != banner_fetch_key) return;
    // WHOSE banner this is. A fetch takes as long as it takes, and the reader
    // may have walked to somebody else meanwhile: without this the bytes paint
    // over the person now on screen AND are cached under their URL, so the wrong
    // face persists across restarts.
    const asked_for = g_banner_asked_for orelse return;
    const showing = g_banner_for orelse return;
    if (!std.mem.eql(u8, &asked_for, &showing)) {
        g_banner_state = .idle;
        return;
    }
    // Every effect slot was busy: ask again next tick.
    if (response.outcome == .rejected) {
        g_banner_state = .idle;
        return;
    }
    // Anything but a clean, whole, OK image body leaves the flat band, which is
    // a perfectly good banner.
    if (response.outcome != .ok or response.status != 200 or response.truncated or
        response.body.len == 0 or response.body.len > max_image_bytes)
    {
        g_banner_state = .failed;
        return;
    }
    if (decodeAndRegister(fx, banner_image_id, response.body, banner_target_px)) |_| {
        g_banner_state = .loaded;
        storeCachedImage(bannerUrl(), response.body);
    } else {
        g_banner_state = .failed;
    }
}

// ----------------------------------------------------------------- a person
//
// Everything the profile screen needs about somebody, read from the RAW kind:0
// rather than the name-and-face cache. The cache models four fields and drops
// the rest, which is right for a feed row and useless here: a profile is mostly
// the fields it does not keep.
//
// Cached per pubkey for the life of a level, because a virtual list rebuilds its
// visible rows every frame and a JSON parse per frame is not free.

const PersonCard = struct {
    used: bool = false,
    pubkey: [32]u8 = [_]u8{0} ** 32,
    /// The kind:0 these fields came from, so an unchanged event is parsed once.
    meta_id: [32]u8 = [_]u8{0} ** 32,
    /// The store's event count when this card was last filled. The store only
    /// grows, so an unchanged count means nothing this card reads can have
    /// changed either.
    stamp: usize = std.math.maxInt(usize),
    about_buf: [512]u8 = [_]u8{0} ** 512,
    about_len: u16 = 0,
    /// The about text with its NIP-27 mentions rewritten as `@name`, which is
    /// what the page shows. Kept beside the raw bytes rather than rewritten at
    /// draw time because the card's height is computed from the length of the
    /// string, so measuring the raw one and drawing the rewritten one would
    /// reserve space for a line that is not there.
    about_shown_buf: [512]u8 = [_]u8{0} ** 512,
    about_shown_len: u16 = 0,
    /// The names generation `about_shown_buf` was written under. A mention
    /// resolves to a short npub until that person's kind:0 arrives, and then it
    /// has a name, so this is rewritten when the cache learns one.
    about_shown_gen: u64 = std.math.maxInt(u64),
    website_buf: [128]u8 = [_]u8{0} ** 128,
    website_len: u8 = 0,
    lud16_buf: [128]u8 = [_]u8{0} ** 128,
    lud16_len: u8 = 0,
    banner_buf: [256]u8 = [_]u8{0} ** 256,
    banner_len: u16 = 0,
    /// How many their own contact list names, or null when none has arrived.
    following: ?usize = null,
    /// Whether their contact list names the reader.
    follows_me: bool = false,
};

/// One card per stack level, plus the one being looked at.
var g_person_cards = [_]PersonCard{.{}} ** (thread_depth_max + 2);

/// The card for `pubkey`, filled from the store when it is stale.
fn personCard(pubkey: [32]u8) *const PersonCard {
    var slot: ?*PersonCard = null;
    for (&g_person_cards) |*c| {
        if (c.used and std.mem.eql(u8, &c.pubkey, &pubkey)) {
            slot = c;
            break;
        }
    }
    if (slot == null) {
        // Oldest wins the seat: the levels below are what a reader walks back
        // through, so evicting the least recently looked at is wrong here.
        for (&g_person_cards) |*c| {
            if (!c.used) {
                slot = c;
                break;
            }
        }
        if (slot == null) slot = &g_person_cards[0];
        slot.?.* = .{ .used = true, .pubkey = pubkey };
    }
    const card = slot.?;
    // Only when the store has actually moved. This is called several times per
    // frame (once per field the header shows) and each refresh ran two LMDB
    // queries and deep-copied the subject's whole contact list, which for
    // somebody with two thousand follows is a few hundred allocations per field
    // per frame.
    const stamp = if (g_store) |store| store.eventCount() catch 0 else 0;
    if (card.stamp != stamp) {
        card.stamp = stamp;
        refreshPersonCard(card);
    }
    return card;
}

fn refreshPersonCard(card: *PersonCard) void {
    const gpa = std.heap.page_allocator;
    if (readRecord(gpa, card.pubkey, 0)) |own| {
        defer freeOwnProfile(gpa, own);
        if (!std.mem.eql(u8, &card.meta_id, &own.id)) {
            card.meta_id = own.id;
            parsePersonMetadata(card, own.json);
        }
    }
    // Their contact list: how many they follow, and whether the reader is in it.
    if (readRecord(gpa, card.pubkey, contact_list_kind)) |own| {
        defer freeOwnProfile(gpa, own);
        var mine = false;
        const me = activePubkey();
        for (own.tags) |tag| {
            if (tag.len < 2 or !std.mem.eql(u8, tag[0], "p")) continue;
            if (tag[1].len != 64) continue;
            if (me) |pk| {
                var hex: [64]u8 = undefined;
                hexLower(&hex, pk);
                if (std.ascii.eqlIgnoreCase(tag[1], &hex)) mine = true;
            }
        }
        // DISTINCT people. Some clients emit the same person twice, and this
        // file already has one function that knows that; counting raw tags here
        // would print a follow count nobody else shows.
        card.following = countPeople(own.tags);
        card.follows_me = mine;
    } else {
        card.following = null;
        card.follows_me = false;
    }

    // A bio is written the same way a note is, so it carries the same
    // `nostr:npub...` references, and printing one raw drops sixty-three
    // characters of base32 into the middle of a sentence about a person. The
    // feed has drawn these as `@name` since NIP-27 landed; this is the same pass
    // over the same cache.
    if (card.about_shown_gen != g_names_generation) {
        card.about_shown_gen = g_names_generation;
        card.about_shown_len = @intCast(renderContent(
            &card.about_shown_buf,
            card.about_buf[0..card.about_len],
            "",
        ));
    }
}

fn parsePersonMetadata(card: *PersonCard, json: []const u8) void {
    card.about_len = 0;
    card.website_len = 0;
    card.lud16_len = 0;
    card.banner_len = 0;
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const root = std.json.parseFromSliceLeaky(std.json.Value, a, json, .{
        .duplicate_field_behavior = .use_last,
        .allocate = .alloc_always,
    }) catch return;
    if (root != .object) return;
    const obj = root.object;
    if (stringField(obj, "about")) |v| {
        const n = utf8SafeLen(v, card.about_buf.len);
        @memcpy(card.about_buf[0..n], v[0..n]);
        card.about_len = @intCast(n);
    }
    if (stringField(obj, "website")) |v| {
        if (v.len <= card.website_buf.len) {
            @memcpy(card.website_buf[0..v.len], v);
            card.website_len = @intCast(v.len);
        }
    }
    if (stringField(obj, "lud16")) |v| {
        if (v.len <= card.lud16_buf.len) {
            @memcpy(card.lud16_buf[0..v.len], v);
            card.lud16_len = @intCast(v.len);
        }
    }
    if (stringField(obj, "banner")) |v| {
        // https only, and only what fits: a banner is a picture fetched
        // unattended from a host the subject named, so it goes through the same
        // gate every other unattended fetch does.
        if (v.len <= card.banner_buf.len and std.mem.startsWith(u8, v, "https://")) {
            @memcpy(card.banner_buf[0..v.len], v);
            card.banner_len = @intCast(v.len);
        }
    }
}

pub fn personBanner(pubkey: [32]u8) []const u8 {
    const c = personCard(pubkey);
    return c.banner_buf[0..c.banner_len];
}

/// Any pubkey's newest event of `kind`, raw. `ownRecordJson` is this for the
/// reader themselves; a profile needs it for somebody else.
fn readRecord(gpa: std.mem.Allocator, pubkey: [32]u8, kind: u16) ?OwnProfile {
    const store = g_store orelse return null;
    const kinds = [_]u16{kind};
    const authors = [_][32]u8{pubkey};
    var result = store.query(gpa, .{ .authors = &authors, .kinds = &kinds, .limit = 1 }) catch return null;
    defer result.deinit();
    if (result.events.len == 0) return null;
    const copy = gpa.dupe(u8, result.events[0].content) catch return null;
    // Whole or not at all. A partial base is what turns a splice into a delete.
    const tags = dupeTags(gpa, result.events[0].tags) orelse return null;
    return .{ .json = copy, .tags = tags, .created_at = result.events[0].created_at, .id = result.events[0].id };
}

pub fn personAbout(pubkey: [32]u8) []const u8 {
    const c = personCard(pubkey);
    // The rewritten one, so what the page measures and what it draws are the
    // same string.
    return c.about_shown_buf[0..c.about_shown_len];
}

pub fn personWebsite(pubkey: [32]u8) []const u8 {
    const c = personCard(pubkey);
    return c.website_buf[0..c.website_len];
}

pub fn personLud16(pubkey: [32]u8) []const u8 {
    const c = personCard(pubkey);
    return c.lud16_buf[0..c.lud16_len];
}

/// How many people they follow, or null when their list has not arrived. Null is
/// not zero, and the screen says so rather than printing a confident 0.
pub fn personFollowingCount(pubkey: [32]u8) ?usize {
    return personCard(pubkey).following;
}

/// Whether their contact list names the reader.
pub fn followsMe(pubkey: [32]u8) bool {
    if (activePubkey() == null) return false;
    return personCard(pubkey).follows_me;
}

/// Their display name, or a short npub until a kind:0 arrives. Never blank: a
/// nameless header reads as a broken screen rather than an unfetched one.
fn personName(ui: *AppUi, pubkey: [32]u8) []const u8 {
    if (lookupProfile(pubkey)) |prof| {
        if (prof.name_len > 0) return prof.name();
    }
    return personNpubShort(ui, pubkey);
}

/// Whether this person has a name of their own, as opposed to one this app made
/// up for them out of their key.
///
/// `personName` falls back to the short npub, which is the right thing on a row
/// that must say SOMETHING. On the profile it means the name line and the npub
/// line can end up holding the identical string, which reads as a rendering fault
/// rather than as an identity. The note row has guarded its handle against the
/// same shape since it was written; the profile card never did.
fn personIsNamed(pubkey: [32]u8) bool {
    const prof = lookupProfile(pubkey) orelse return false;
    return prof.name_len > 0;
}

fn personNpubShort(ui: *AppUi, pubkey: [32]u8) []const u8 {
    return npubShortOf(ui.arena, pubkey);
}

/// The abbreviated npub, allocating. ONE truncation rule, shared with the feed's
/// name line through `abbreviateNpub`.
///
/// There were two. The name line cut at twelve characters and this cut at ten,
/// so the same key rendered as two different strings depending on which line it
/// landed on, and any code comparing them to avoid saying it twice compared
/// unequal and said it twice, in two spellings. That is worse than the
/// duplication it was trying to prevent.
fn npubShortOf(arena: std.mem.Allocator, pubkey: [32]u8) []const u8 {
    var buf: [128]u8 = undefined;
    const s = abbreviateNpub(&buf, pubkey);
    return arena.dupe(u8, s) catch "npub…";
}

/// The abbreviated npub exactly as the view renders it, so a test can count how
/// many times a screen says it without hard-coding the truncation. For tests.
pub fn npubShortForTest(arena: std.mem.Allocator, pubkey: [32]u8) []const u8 {
    return npubShortOf(arena, pubkey);
}

/// A NIP-05 as an identity line shows it: whole (`someone@example.com`), or the
/// domain alone for the root `_@domain` form, which is what that form means.
/// Empty when it is malformed, so a broken one is shown as nothing rather than
/// as itself.
///
/// One rule, shared by the feed's handle line and the profile page, because two
/// spellings of the same identity on two screens is its own small dishonesty.
fn nip05Display(id: []const u8) []const u8 {
    const at = std.mem.indexOfScalar(u8, id, '@') orelse return "";
    const local = id[0..at];
    const domain = id[at + 1 ..];
    if (domain.len == 0) return "";
    return if (std.mem.eql(u8, local, "_")) domain else id;
}

/// Their NIP-05 for the profile page, and ONLY once the well-known lookup has
/// actually mapped it back to this key.
///
/// The page used to draw a bare check next to the name and no address at all, so
/// a verified profile said "verified" without ever saying verified as WHAT. The
/// domain is the half that names who vouched, and the profile page is the one
/// screen a reader opens specifically to decide whether this is the right person.
///
/// Unverified is shown as nothing rather than as plain text. An address the app
/// has not checked, printed under a name, is read as an endorsement by everyone
/// who has ever seen one anywhere else, and that is exactly the impersonation
/// this is supposed to guard against.
fn verifiedNip05(pubkey: [32]u8) []const u8 {
    const prof = lookupProfile(pubkey) orelse return "";
    if (prof.nip05_state != .verified) return "";
    return nip05Display(prof.nip05());
}

/// Puts a NIP-05 on a cached profile in a stated verification state, so a view
/// test can ask what the page shows without a well-known round trip.
pub fn setProfileNip05ForTest(pubkey: [32]u8, id: []const u8, verified: bool) void {
    const p = upsertProfile(pubkey) orelse return;
    const n = @min(id.len, p.nip05_buf.len);
    @memcpy(p.nip05_buf[0..n], id[0..n]);
    p.nip05_len = @intCast(n);
    p.nip05_state = if (verified) .verified else .failed;
}

/// Fills a cached profile's text fields to whatever length is asked for, so a
/// sweep can render the WORST case rather than a realistic one.
///
/// Every one of these is a stranger's string arriving over a relay, and the
/// only thing bounding it is the buffer it is copied into. A row that fits a
/// name is not the question; a row that fits a name of sixty-four characters
/// is, because that is what the buffer allows and therefore what will
/// eventually arrive.
pub fn fillProfileTextForTest(pubkey: [32]u8, name: []const u8, username: []const u8, website: []const u8) void {
    const p = upsertProfile(pubkey) orelse return;
    const n = @min(name.len, p.name_buf.len);
    @memcpy(p.name_buf[0..n], name[0..n]);
    p.name_len = @intCast(n);
    const u = @min(username.len, p.username_buf.len);
    @memcpy(p.username_buf[0..u], username[0..u]);
    p.username_len = @intCast(u);
    const w = @min(website.len, p.website_buf.len);
    @memcpy(p.website_buf[0..w], website[0..w]);
    p.website_len = @intCast(w);
}

pub fn verifiedNip05ForTest(pubkey: [32]u8) []const u8 {
    return verifiedNip05(pubkey);
}

/// The verified check, drawn only when their NIP-05 actually resolves to them.
fn personCheck(ui: *AppUi, pubkey: [32]u8) AppUi.Node {
    const prof = lookupProfile(pubkey) orelse return ui.spacer(0);
    if (prof.nip05_state != .verified) return ui.spacer(0);
    return ui.icon(.{ .width = 14, .height = 14, .style = .{ .foreground = theme.palette.status_success } }, "check");
}

/// Their face at a stated size.
fn personAvatar(ui: *AppUi, pubkey: [32]u8, size: f32) AppUi.Node {
    const tint = avatarTint(pubkey);
    const hexdigits = "0123456789abcdef";
    return ui.avatar(.{
        .width = size,
        .height = size,
        .image = if (lookupProfile(pubkey)) |prof| prof.image_id else 0,
        .style = .{ .background = tint.bg, .border = tint.border, .foreground = tint.glyph, .stroke_width = 3 },
    }, ui.fmt("{c}{c}", .{ hexdigits[pubkey[0] >> 4], hexdigits[pubkey[0] & 0x0f] }));
}

/// The 44px band above a person: Back, and who this is.
fn profileHeaderBand(ui: *AppUi, model: *const Model, pubkey: [32]u8) AppUi.Node {
    const p = theme.palette;
    const back_label = if (model.thread_stack_len > 0)
        model.thread_stack[model.thread_stack_len - 1].backLabel()
    else
        model.scope_name();
    return ui.column(.{}, .{
        ui.row(.{ .cross = .center, .gap = 10, .padding = 12 }, .{
            backControl(ui, back_label, Msg.close_thread),
            ui.spacer(1),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_primary } },
                &.{.{ .text = elide(ui, personName(ui, pubkey), profile_band_name_max), .weight = .medium, .scale = menu_scale }},
            ),
            ui.spacer(1),
            hgap(ui, 48),
        }),
        ui.el(.separator, .{ .style = .{ .background = p.divider_row } }, .{}),
    });
}

/// How tall the person card is. Measured, not guessed: a bio wraps and a links
/// row may be absent, and a virtual list that mis-measures its first row scrolls
/// to the wrong place for every row after it.
fn profileCardExtent(rows: *const ProfileRows) f32 {
    var h: f32 = profile_banner_height + profile_card_chrome;
    const about = personAbout(rows.pubkey);
    if (about.len > 0) {
        // Roughly 62 characters to a line at the body scale, over the 660 column.
        const lines: f32 = @floatFromInt(1 + about.len / 62);
        h += lines * profile_bio_line_height + 9;
    }
    if (personWebsite(rows.pubkey).len > 0 or personLud16(rows.pubkey).len > 0) h += profile_links_height;
    return h;
}

/// Whether this page belongs to the reader looking at it.
///
/// The profile was written for a stranger, because for a long time a stranger was
/// the only person it could be about: the way onto it was pressing somebody's face
/// in the feed. Now the rail's seat opens the reader's own, so every sentence that
/// says "they" has to say "you" here, and the first reader through that door is a
/// brand new account whose page is entirely empty states.
fn isMe(pubkey: [32]u8) bool {
    const me = activePubkey() orelse return false;
    return std.mem.eql(u8, &me, &pubkey);
}

/// The person: their banner, their face, what they say about themselves, and
/// what this app can honestly tell the reader about them.
fn profileCard(ui: *AppUi, model: *const Model, pubkey: [32]u8) AppUi.Node {
    const p = theme.palette;
    const about = personAbout(pubkey);
    const website = personWebsite(pubkey);
    const lud16 = personLud16(pubkey);
    const is_me = isMe(pubkey);
    const named = personIsNamed(pubkey);
    const follows_me = followsMe(pubkey);
    // Nothing to show and no room to leave for it: with neither the npub nor the
    // follows-you note, the row measures zero and its 5px lead-in would sit under
    // the name as dead space. That is the freshly minted key's own page.
    // Their NIP-05, once it has actually been checked. It goes ahead of the npub
    // because it is the identifier a person chose and can prove, where the npub
    // is the one the maths chose.
    const handle = verifiedNip05(pubkey);

    return ui.column(.{ .gap = 0 }, .{
        // The banner, with the face riding up over its lower edge. There is no
        // negative margin on this engine, so the two are STACKED: one child is
        // the banner plus the disc's overhang, the other is that same height
        // made of a gap and then the disc. Equal heights, so the stack is
        // exactly as tall as the band plus what hangs below it, and the name
        // row after it starts clear of both.
        ui.stack(.{}, .{
            ui.column(.{ .gap = 0 }, .{
                // A flat band until an image is afforded: an empty box that
                // holds its height beats a jump when one arrives.
                if (bannerReady(pubkey))
                    bannerImage(ui)
                else
                    ui.el(.panel, .{
                        .height = profile_banner_height,
                        .padding = 0.01,
                        .style = .{ .background = p.surface_stripe_a, .border = p.surface_stripe_a, .radius = 0, .stroke_width = 0 },
                    }, .{}),
                vgap(ui, profile_avatar_size - profile_avatar_lift),
            }),
            ui.column(.{ .gap = 0 }, .{
                vgap(ui, profile_banner_height - profile_avatar_lift),
                // Bottom-aligned, not top. The disc is the tallest thing here
                // and it deliberately overhangs the banner, so aligning the
                // cluster to the TOP of this row put it ON the band, over the
                // subject's own picture. Against the bottom it lands in the
                // overhang, clear of the banner and level with the face.
                ui.row(.{ .cross = .end, .gap = 0 }, .{
                    hgap(ui, 20),
                    personAvatar(ui, pubkey, profile_avatar_size),
                    ui.spacer(1),
                    profileActions(ui, model, pubkey, is_me),
                    hgap(ui, 20),
                }),
            }),
        }),
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, 20),
            ui.column(.{ .gap = 0, .grow = 1 }, .{
                vgap(ui, 8),
                ui.row(.{ .cross = .center, .gap = 7 }, .{
                    ui.paragraph(
                        .{ .style = .{ .foreground = p.text_primary } },
                        &.{.{ .text = elide(ui, personName(ui, pubkey), profile_name_max), .weight = .bold, .scale = profile_name_scale }},
                    ),
                    personCheck(ui, pubkey),
                }),
                // The npub is skipped when the name line IS that string. A key
                // with no kind:0 has no name, so `personName` hands back the
                // short npub, and printing it again directly underneath says
                // nothing twice. The reader most likely to see it is the one
                // whose key was minted a minute ago and has not named it yet,
                // which is the same reader the rail's seat now opens this page
                // for.
                //
                // `.gap = 0` with the 8 spelled out, NOT a gap of 8 with a
                // zero-width spacer standing in for the npub. A row gap is
                // charged for every flow child whatever its extent, so the
                // spacer would still push "follows you" 8px past the left rule
                // that the name, bio, links and counts all share. `handleLine`
                // documents this exact trap and I walked into it anyway.
                // One fact per line, in the order they are worth: the name,
                // the address that was verified, the key itself, then where to
                // pay them. They used to share a row, which read as one long
                // strip of identifiers and put the npub, the thing most likely
                // to be copied, in the middle of it.
                if (handle.len > 0) vgap(ui, 5) else ui.spacer(0),
                if (handle.len > 0)
                    ui.paragraph(
                        .{ .style = .{ .foreground = p.accent_identity } },
                        &.{.{ .text = elide(ui, handle, profile_handle_max), .scale = meta_scale }},
                    )
                else
                    ui.spacer(0),
                if (named) vgap(ui, 4) else ui.spacer(0),
                if (named)
                    ui.row(.{ .cross = .center, .gap = 8 }, .{
                        ui.paragraph(
                            .{ .style = .{ .foreground = p.text_muted } },
                            &.{.{ .text = personNpubShort(ui, pubkey), .monospace = true, .scale = mono_meta_scale }},
                        ),
                        // Kept beside the key rather than given a line of its
                        // own: it is a fact about the two of you, not another
                        // way to address them.
                        if (follows_me)
                            ui.paragraph(.{ .style = .{ .foreground = p.text_faint } }, &.{.{ .text = "follows you", .scale = meta_scale }})
                        else
                            ui.spacer(0),
                    })
                else
                    ui.spacer(0),
                // A key with no name of its own shows no npub either, because
                // the name line already IS that string. The badge still has to
                // appear: hanging it off the npub's branch made it vanish for
                // exactly the readers whose page has least on it, and a test
                // written for the old layout caught that.
                if (follows_me and !named) vgap(ui, 4) else ui.spacer(0),
                if (follows_me and !named)
                    ui.paragraph(.{ .style = .{ .foreground = p.text_faint } }, &.{.{ .text = "follows you", .scale = meta_scale }})
                else
                    ui.spacer(0),
                if (lud16.len > 0) vgap(ui, 4) else ui.spacer(0),
                if (lud16.len > 0)
                    ui.paragraph(
                        .{ .style = .{ .foreground = p.text_muted_alt } },
                        &.{.{ .text = elide(ui, lud16, profile_handle_max), .monospace = true, .scale = mono_hint_scale }},
                    )
                else
                    ui.spacer(0),
                if (about.len > 0) vgap(ui, 9) else ui.spacer(0),
                if (about.len > 0)
                    ui.paragraph(
                        .{ .wrap = true, .style = .{ .foreground = p.text_body_soft } },
                        &.{.{ .text = about, .scale = nested_body_scale }},
                    )
                else
                    ui.spacer(0),
                if (website.len > 0) profileLinks(ui, website) else ui.spacer(0),
                vgap(ui, 9),
                profileCounts(ui, pubkey, is_me),
                if (!is_me and followBlockedReason() != null)
                    ui.column(.{ .gap = 0 }, .{
                        vgap(ui, 7),
                        ui.paragraph(
                            .{ .wrap = true, .style = .{ .foreground = p.text_dim } },
                            &.{.{ .text = "Still reading your own follow list. Following is off until it arrives, because writing before then would replace it.", .scale = mono_hint_scale }},
                        ),
                    })
                else
                    ui.spacer(0),
                vgap(ui, 14),
                profileTabs(ui, model),
            }),
            hgap(ui, 20),
        }),
    });
}

/// The action cluster: zap (inert), the overflow menu, and Follow.
fn profileActions(ui: *AppUi, model: *const Model, pubkey: [32]u8, is_me: bool) AppUi.Node {
    _ = model;
    if (is_me) {
        const p = theme.palette;
        // Your own page. Editing lives in Settings, and a second door to it here
        // would be a second thing to keep true.
        return ui.paragraph(.{ .style = .{ .foreground = p.text_faint } }, &.{.{ .text = "This is you", .scale = meta_scale }});
    }
    const following = isFollowedByMe(pubkey);
    return ui.row(.{ .cross = .center, .gap = 8 }, .{
        // Disabled rather than absent while the app is still reading the
        // reader's own list: a control that vanishes is a control they will
        // wonder about, and one that silently no-ops is worse. The sentence
        // explaining it sits under the counts, where there is room for it.
        if (followBlockedReason() != null)
            ui.button(.{ .size = .sm, .variant = .primary, .disabled = true, .on_press = Msg{ .follow_person = 1 } }, "Follow")
        else if (following)
            ui.button(.{ .size = .sm, .variant = .ghost, .on_press = Msg{ .follow_person = 2 } }, "Following")
        else
            ui.button(.{ .size = .sm, .variant = .primary, .on_press = Msg{ .follow_person = 1 } }, "Follow"),
    });
}

/// Where they point people, when they point anywhere.
/// The website line. The lightning address used to share this row and now sits
/// with the other ways to address someone, directly under the key.
///
/// Shortened rather than bounded: a stranger's `website` is printed whole, up to
/// the 128 bytes of the buffer that holds it, and the profile page is the one
/// screen that never picks up the fixed reading column, so nothing above this
/// leaf would have stopped it at the window's edge.
fn profileLinks(ui: *AppUi, website: []const u8) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 8),
        ui.row(.{ .cross = .center, .gap = 14 }, .{
            ui.paragraph(
                .{ .style = .{ .foreground = p.accent_identity } },
                &.{.{ .text = elide(ui, website, profile_handle_max), .scale = meta_scale }},
            ),
            ui.spacer(1),
        }),
    });
}

/// What this app can honestly count.
///
/// Following is theirs to state: it is the length of their own contact list.
/// FOLLOWERS is not. Nothing in a local store can know who follows somebody,
/// and the honest options are an indexer's number or none. This app does not
/// state numbers it cannot verify, so it says nothing rather than a figure the
/// reader would reasonably believe.
fn profileCounts(ui: *AppUi, pubkey: [32]u8, is_me: bool) AppUi.Node {
    const p = theme.palette;
    const following = personFollowingCount(pubkey);
    return ui.row(.{ .cross = .center, .gap = 16 }, .{
        if (following) |n|
            ui.row(.{ .cross = .center, .gap = 5 }, .{
                ui.paragraph(.{ .style = .{ .foreground = p.text_body_strong } }, &.{.{ .text = ui.fmt("{d}", .{n}), .weight = .medium, .scale = menu_scale }}),
                ui.paragraph(.{ .style = .{ .foreground = p.text_muted_alt } }, &.{.{ .text = "following", .scale = menu_scale }}),
            })
        else
            ui.paragraph(.{ .style = .{ .foreground = p.text_dim } }, &.{.{
                .text = if (is_me) "Your follow list has not arrived yet" else "Their follow list has not arrived yet",
                .scale = mono_hint_scale,
            }}),
        ui.spacer(1),
    });
}

/// Notes, or replies. Two tabs that mean exactly what they say.
fn profileTabs(ui: *AppUi, model: *const Model) AppUi.Node {
    return ui.row(.{ .cross = .center, .gap = 6 }, .{
        profileTab(ui, "Notes", model.profile_tab == .notes, Msg{ .profile_tab = 0 }),
        profileTab(ui, "Replies", model.profile_tab == .replies, Msg{ .profile_tab = 1 }),
        ui.spacer(1),
    });
}

fn profileTab(ui: *AppUi, label: []const u8, active: bool, msg: Msg) AppUi.Node {
    return profileTabFocused(ui, label, active, msg, false);
}

/// The same tab, optionally taking the keyboard when it mounts. The
/// notifications sheet has no way-out control of its own, so its first tab is
/// what gives Escape a focused widget to resolve from; switching tabs is the
/// worst an accidental Return can do from there.
fn profileTabFocused(ui: *AppUi, label: []const u8, active: bool, msg: Msg, focus: bool) AppUi.Node {
    const p = theme.palette;
    return ui.el(.list_item, .{
        .padding = 0.01,
        .height = 26,
        .cross = .center,
        .autofocus = focus,
        .on_press = msg,
        .style = .{
            .background = if (active) p.surface_settings_card else p.surface_window,
            .border = if (active) p.border_chip else p.surface_window,
            .radius = 8,
            .stroke_width = 1,
        },
        .semantics = .{ .role = .tab, .label = label, .focusable = true },
    }, .{
        hgap(ui, 11),
        ui.paragraph(
            .{ .style = .{ .foreground = if (active) p.text_primary else p.text_muted_alt } },
            // One weight for both. The active tab already has its own fill,
            // border and text colour, and changing the weight as well moved the
            // glyph metrics, so the two labels sat on different baselines inside
            // boxes that were centred correctly. The tabs looked misaligned and
            // the row was never the problem.
            &.{.{ .text = label, .scale = menu_scale }},
        ),
        hgap(ui, 11),
    });
}

/// The quiet line under an empty tab.
fn profileEmptyRow(ui: *AppUi, rows: *const ProfileRows) AppUi.Node {
    const p = theme.palette;
    // A key minted a minute ago has written nothing, so this is the ONE screen a
    // new reader is most likely to see first, and "Nothing they have written" is
    // the app talking about them behind their back on their own page.
    const mine = isMe(rows.pubkey);
    const text: []const u8 = if (rows.loading)
        if (mine) "Looking for what you have written…" else "Looking for what they have written…"
    else if (rows.model.profile_tab == .replies)
        if (mine) "Nothing you have written at anyone is here yet." else "Nothing they have written at anyone is here yet."
    else if (mine) "Nothing you have written is here yet." else "Nothing they have written is here yet.";
    return ui.row(.{ .cross = .center, .gap = 0, .height = quiet_row_extent }, .{
        hgap(ui, 20),
        ui.paragraph(.{ .wrap = true, .style = .{ .foreground = p.text_dim } }, &.{.{ .text = text, .scale = mono_hint_scale }}),
        hgap(ui, 20),
    });
}

/// A profile level's key, in the same space as a thread's so the two never
/// collide when they sit in one stack. The top bit marks it a person.
fn profileLevelKey(level: usize, pubkey: [32]u8) u64 {
    const hi = @as(u64, level) << 59;
    const lo = std.mem.readInt(u64, pubkey[0..8], .big) & ((@as(u64, 1) << 58) - 1);
    return hi | lo | (@as(u64, 1) << 58);
}

/// What a profile level draws: the person, then what they have written.
///
/// One virtual list, with the whole profile header as row 0. The header is tall
/// and variable (a bio wraps, a links row may be absent) and it scrolls away
/// with the notes, which is what the design asks for and what a column above a
/// list cannot do. This is the same heterogeneous-row shape the thread already
/// uses for its ancestors.
fn profilePanel(
    ui: *AppUi,
    model: *const Model,
    pubkey: [32]u8,
    notes: []const Note,
    loading: bool,
    level_key: u64,
    level: usize,
    occluded: bool,
) AppUi.Node {
    const rows_ctx = ui.arena.create(ProfileRows) catch return ui.column(.{}, .{});
    // From the ARENA, never the stack. The SDK RETAINS `extent_context` and calls
    // the estimator again in a post-layout measure pass, long after this function
    // has returned: a slice of a local here is read back out of a reclaimed frame,
    // and the index it yields then indexes `notes` with whatever layout left on
    // that word. The arena survives to the top of the next build, which is
    // exactly as long as the retained table needs it.
    const indices = ui.arena.alloc(usize, thread_reply_cap) catch return ui.column(.{}, .{});
    // An occluded level still reports its REAL row count: the retained list keeps
    // its scroll offset from the count and the extents, so claiming two rows here
    // would collapse the person's scroll and Back would land at the top.
    const shown = model.profileNotesFor(indices, pubkey);
    rows_ctx.* = .{
        .model = model,
        .pubkey = pubkey,
        .notes = notes,
        .shown = shown,
        .loading = loading,
    };
    const table = &g_profile_extents[@min(level, g_profile_extents.len - 1)];
    table.reset();
    if (!occluded) {
        var row: usize = 0;
        const total = rows_ctx.count();
        while (row < total) : (row += 1) table.push(profileRowHeight(rows_ctx, row));
    }
    const options: AppUi.VirtualListOptions = .{
        .id = ui.fmt("person-{d}", .{level_key}),
        // Nothing to cover when nothing is drawn, for the same reason the thread
        // list above says so: a list that declares items and builds none is
        // permanently "undercovered", and the runtime answers that by rebuilding
        // and re-laying out the whole view a second time, every time.
        .item_count = if (occluded) 0 else rows_ctx.count(),
        .item_extent = 0,
        .extent_estimate = rowExtentFromTable,
        .extent_context = table,
        .gap = 0,
        .padding = 0,
        .overscan = 3,
        .grow = 1,
        .viewport_fallback = window_height,
        .semantics = .{ .label = "Profile" },
    };
    const window = ui.virtualWindow(options);
    if (!occluded) recordProfileVisible(rows_ctx, level, window.first_visible_index, window.last_visible_index);
    // An occluded level builds no rows, for the same reason a thread's does not:
    // the offset survives on the list's id and its content height, and six built
    // levels of anything cross the 1024-node ceiling that refuses a view whole.
    const rows = if (occluded)
        &[_]AppUi.Node{}
    else blk: {
        const built = ui.arena.alloc(AppUi.Node, window.itemCount()) catch return ui.column(.{}, .{});
        for (built, 0..) |*row, offset| row.* = profileRowAt(ui, rows_ctx, window.start_index + offset);
        break :blk built;
    };
    return ui.column(.{ .grow = 1, .style_tokens = .{ .background = .background } }, .{
        if (occluded) ui.spacer(0) else profileHeaderBand(ui, model, pubkey),
        ui.virtualList(options, window, .{rows}),
    });
}

/// The rows a profile level holds: the person, then their notes.
const ProfileRows = struct {
    model: *const Model,
    pubkey: [32]u8,
    notes: []const Note,
    shown: []const usize,
    loading: bool,

    const Row = union(enum) { person, note: usize, empty };

    fn count(self: *const ProfileRows) usize {
        // The person, then a row per note, or one quiet line when there are none.
        return 1 + if (self.shown.len == 0) @as(usize, 1) else self.shown.len;
    }

    fn rowAt(self: *const ProfileRows, index: usize) Row {
        if (index == 0) return .person;
        if (self.shown.len == 0) return .empty;
        const i = index - 1;
        if (i >= self.shown.len) return .empty;
        return .{ .note = self.shown[i] };
    }
};

/// One person-page row's height, from the live rows. Typed for the same reason
/// `threadRowHeight` is.
fn profileRowHeight(rows: *const ProfileRows, index: usize) f32 {
    return switch (rows.rowAt(index)) {
        .person => profileCardExtent(rows),
        .note => |ni| noteRowEstimate(&rows.notes[ni], feed_row_chrome),
        .empty => quiet_row_extent,
    };
}

fn profileRowAt(ui: *AppUi, rows: *const ProfileRows, index: usize) AppUi.Node {
    return switch (rows.rowAt(index)) {
        .person => profileCard(ui, rows.model, rows.pubkey),
        .note => |ni| noteCard(ui, rows.model, &rows.notes[ni]),
        .empty => profileEmptyRow(ui, rows),
    };
}

/// A stable, collision-free scroll identity for a thread level: the level index
/// in the high bits (distinct per position, so an ancestor keeps its key and
/// offset while deeper levels push and pop, and two levels never collide even if
/// the same note appears twice) and the root note id in the low bits (so when
/// the stack is saturated at `thread_depth_max` and `enterThread` replaces the
/// top root in place, the new level gets a fresh key and opens at the top rather
/// than inheriting the dropped thread's offset).
fn threadLevelKey(level: usize, root_id: i64) u64 {
    const hi = @as(u64, level) << 59;
    const lo = @as(u64, @intCast(root_id)) & ((@as(u64, 1) << 59) - 1);
    return hi | lo;
}

/// The feed screen, and everything layered on it.
///
/// `levels` is what the Settings sheet passes false: see `settingsSheet`. The
/// thread stack is the most expensive thing this app builds, and a view past
/// `max_canvas_widget_nodes_per_view` is refused WHOLE, so the deepest stack
/// under the largest sheet is the frame that decides whether the window can
/// draw at all. Settings used to REPLACE this tree, which unmounted every level
/// and lost its scroll offset anyway, so not building them behind the sheet
/// costs nothing that was not already gone and buys back most of the ceiling.
/// Every other sheet keeps its levels, because for those the offsets survive
/// today and dropping them would be a real loss.
fn feedView(ui: *AppUi, model: *const Model, levels: bool) AppUi.Node {
    const p = theme.palette;
    // The feed is always built (so it is always mounted): a thread is layered
    // OVER it, not swapped in, so the feed's scroll offset survives and closing
    // a thread returns the reader to where they were, not the top. EACH open
    // thread level is layered too (occluded ancestors under the current one), so
    // every level keeps its own scroll offset and Back never lands a parent
    // thread at the top.
    const feed = feedContent(ui, model);
    const content = if (levels and (model.viewing_thread != 0 or model.viewing_profile != null)) blk: {
        // feed + one panel per level: the back-stacked levels (oldest first),
        // then the current one on top. A level is a thread or a person; both
        // spend one virtual window either way, which is why they share a stack.
        const kids = ui.arena.alloc(AppUi.Node, 2 + model.thread_stack_len) catch break :blk feed;
        kids[0] = feed;
        for (0..model.thread_stack_len) |d| {
            const screen = &model.thread_stack[d];
            if (screen.profile) |pk| {
                const lk = profileLevelKey(d, pk);
                kids[1 + d] = threadOccluder(ui, lk, profilePanel(ui, model, pk, &.{}, false, lk, d, true));
                continue;
            }
            const root = &screen.note;
            const lk = threadLevelKey(d, root.id);
            kids[1 + d] = threadOccluder(ui, lk, threadPanel(ui, model, root, threadRepliesFromStore(ui, d, root.event_id), false, lk, d, true));
        }
        if (model.viewing_profile) |pk| {
            const lk = profileLevelKey(model.thread_stack_len, pk);
            kids[kids.len - 1] = threadOccluder(ui, lk, profilePanel(ui, model, pk, model.thread_notes[0..model.thread_notes_len], model.thread_loading, lk, model.thread_stack_len, false));
            break :blk ui.stack(.{ .grow = 1 }, .{kids});
        }
        const lk = threadLevelKey(model.thread_stack_len, model.thread_root.id);
        kids[kids.len - 1] = threadOccluder(ui, lk, threadPanel(ui, model, &model.thread_root, model.thread_notes[0..model.thread_notes_len], model.thread_loading, lk, model.thread_stack_len, false));
        break :blk ui.stack(.{ .grow = 1 }, .{kids});
    } else feed;

    // The window is the rail plus the content. The old titlebar of buttons is
    // gone: home, compose, settings, and the account seat live on the rail, so
    // the feed owns the full width below the OS titlebar.
    return ui.row(.{ .grow = 1, .style_tokens = .{ .background = .background } }, .{
        railView(ui, model),
        // A 1px vertical rule between the rail and the content. No `grow`: in a
        // row that would stretch it along the WIDTH and eat the feed's space; it
        // fills the height on its own via the row's cross-axis stretch.
        ui.separator(.{ .width = 1, .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
        // The bar sits BESIDE the rail and BELOW everything else, which is the
        // only place it is always visible. It used to be the last row of the
        // feed's own column, so every level layered over the feed (a thread, a
        // person) covered it: the pool's health, the outbox and the signer
        // vanished the moment a reader opened a note, which is not a moment to
        // stop telling them whether their notes can go out.
        ui.column(.{ .grow = 1, .gap = 0 }, .{
            content,
            statusBar(ui, model),
        }),
    });
}

/// The feed content column: the guest banner, the scope line, the note list, and
/// the status bar.
fn feedContent(ui: *AppUi, model: *const Model) AppUi.Node {
    // The data-window seam: the runtime resolves scroll offset and viewport
    // into a visible index range, and only those rows are built. A feed of any
    // length then costs what the handful on screen costs.
    var options = feedOptions(model);
    // Nothing to cover when nothing is drawn. The runtime re-runs the WHOLE build
    // and layout a second time whenever a declared window reports fewer built
    // rows than its item count and viewport imply, which an occluded list does by
    // construction: it declares two hundred items and builds none, so it is
    // permanently "undercovered" and every rebuild costs two. That is the exact
    // opposite of what occluding it was for, and it lands on the most ordinary
    // state in the app: one thread open over the feed, rebuilt on every tick,
    // every scroll and every keystroke.
    //
    // A count of zero is the runtime's own early-out (`item_count == 0` skips the
    // coverage check). The retained scroll offset rides on the list's ID and the
    // extent table behind it, neither of which this touches, so the feed is still
    // where the reader left it on the way back.
    const window = ui.virtualWindow(options);
    // A SHEET counts too, and for a long time it did not. Settings, the
    // composer, the notifications panel and the join ladder all sit over the
    // feed on a scrim, and the feed underneath was being built in full on every
    // frame of scrolling one of them.
    //
    // Measured on a real 105 MB store: scrolling settings cost 1775us to rebuild
    // and 6806us to lay out, with 747 nodes mounted. Without the feed beneath
    // it: 142us, 933us, 240 nodes. Seven times the layout work, for rows behind
    // a 55% scrim and a blur.
    //
    // The trade is visible and worth naming: those bands either side of a sheet
    // now show the app's background rather than a blurred, dimmed feed.
    const occluded = model.viewing_thread != 0 or model.viewing_profile != null or
        model.stage == .settings or model.composing or model.notifications_open or model.joining;
    if (occluded) options.item_count = 0;
    // A level drawn opaquely over the feed hides every one of these rows, and
    // building them anyway spent about a third of the whole 1024-node view
    // budget on things nobody can see. The thread and the profile have taken an
    // `occluded` parameter since they were written; the feed never did, because
    // for a long time it was the only list there was.
    //
    // The list stays MOUNTED, so its scroll offset survives exactly as an occluded
    // level's does: the offset rides on the id and the retained extents, not on
    // the rows built this frame.
    const rows = if (occluded)
        &[_]AppUi.Node{}
    else blk: {
        const built = ui.arena.alloc(AppUi.Node, window.itemCount()) catch {
            ui.failed = true;
            return ui.column(.{}, .{});
        };
        for (built, 0..) |*row, offset| row.* = noteCard(ui, model, &model.notes[window.start_index + offset]);
        break :blk built;
    };

    // Exactly which rows are on screen, which is what decides where the image
    // budget goes. Recorded here because the runtime resolves it during the
    // build, while the fetch pass runs later, in `update`. Left alone while
    // occluded: the picture passes have their own branches for the level that
    // is actually being read, and zeroing this would make the feed reload every
    // face on the way back.
    if (!occluded) {
        g_visible_first = window.first_visible_index;
        g_visible_last = window.last_visible_index;
    }

    return ui.column(.{ .grow = 1, .style_tokens = .{ .background = .background } }, .{
        if (model.show_guest_strip()) guestBanner(ui, model) else ui.spacer(0),
        // Under the guest strip, because being signed out is the bigger fact.
        offlineBanner(ui, model),
        scopeHeader(ui, model),
        if (model.notes_len == 0)
            ui.column(.{ .gap = 12, .main = .center, .cross = .center, .grow = 1, .padding = 24 }, .{
                ui.text(.{ .style_tokens = .{ .foreground = .text_muted } }, model.empty_text()),
            })
        else
            // The list owns its scroll state, keyed by the id in `feedOptions`,
            // so the offset survives every rebuild (and the image viewer
            // opening over it) without the model mirroring it.
            ui.virtualList(options, window, .{rows}),
        if (model.backup_nudge) backupNudge(ui) else ui.spacer(0),
    });
}

/// The 56px navigation rail: Home (the mark) up top, then the compose verb, the
/// Settings gear, and the "you" seat pinned to the bottom. This replaces the old
/// titlebar of buttons: destinations on the edge, the feed owns the width. A
/// guest's gated tiles (compose, settings, you) route to the join sheet. Search
/// is not shown until the feature exists.
fn railView(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const guest = model.is_guest();
    const compose_press: Msg = if (guest) .open_join else .open_compose;
    const settings_press: Msg = if (guest) .open_join else .open_settings;
    // Gap 0 with explicit steps: the rail insets are 10 above and 12 below, which
    // one uniform padding cannot state. The 10 on each side is exactly what
    // centring a 36px tile in the 56px rail leaves, so it stays as padding.
    return ui.column(.{ .width = 56, .cross = .center, .gap = 0, .padding = 10, .style_tokens = .{ .background = .background } }, .{
        // Home: the mark on a raised plate, and the way back to the feed from
        // wherever the reader has got to. It looked like the app's own button
        // for a long time and did nothing when pressed, which is the one thing
        // a mark in that position should never be.
        ui.row(.{
            .on_press = Msg.go_home,
            .style = .{ .quiet_hover = true },
            .semantics = .{ .role = .button, .label = "Home", .focusable = true },
        }, .{
            tilePlate(ui, .{ .background = p.surface_rail_tile, .border = p.border_hairline, .radius = 9, .stroke_width = 1 }, "", ui.appIcon(.{ .width = 21, .height = 21, .style = .{ .foreground = p.text_primary } }, "mark")),
        }),
        // The bottom cluster hangs off the floor of the rail: verbs, then meta.
        ui.spacer(1),
        // Compose: the one bright tile.
        railTile(ui, "edit", 15, compose_press, "New note", true),
        vgap(ui, rail_gap),
        // The bell, with what is waiting on it. Signed out there is no inbox to
        // have, so there is no bell: a tile that could only ever say zero is a
        // tile that says nothing.
        if (guest) ui.spacer(0) else railBell(ui),
        if (guest) ui.spacer(0) else vgap(ui, rail_gap),
        // Settings.
        railTile(ui, "settings", 16, settings_press, "Settings", false),
        vgap(ui, rail_gap),
        // The account seat: a dashed "you" as a guest, the account once signed in.
        railYou(ui, guest),
        vgap(ui, 2),
    });
}

/// A 36px rail plate with one centered glyph.
///
/// The plate is a `.panel`, not a styled column. The renderer draws NOTHING for
/// the layout kinds (stack, row, column and friends), which is why every rail tile
/// had been painting as bare window, the bright compose tile included. A `.card`
/// paints but carries a 240x120 intrinsic size that blew the rail apart; `.panel`
/// paints AND sizes to its children. It layers its children, so the sizing column
/// inside does the centring, and the 0.01 padding is belt and braces: the house
/// padding substitution only reaches kinds that declare a default layout, which a
/// panel does not, so the plate sits flush either way.
fn tilePlate(ui: *AppUi, style: canvas.WidgetStyle, label: []const u8, glyph: AppUi.Node) AppUi.Node {
    // An empty label leaves the plate anonymous, which is what a plate inside a
    // named pressable row wants: two nodes with one name read as two controls.
    // Every caller is inside one now, so every caller passes "".
    return ui.el(.panel, .{ .padding = 0.01, .style = style, .semantics = .{ .label = label } }, .{
        ui.column(.{ .width = 36, .height = 36, .main = .center, .cross = .center }, .{glyph}),
    });
}

/// The bell tile, with its count.
///
/// No mock draws the badge anywhere, so this is the smallest thing that reads as
/// one: a small light pill on the tile's top-right corner, absent at zero,
/// capped at "9+". Flagged in the PR.
fn railBell(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    const unread = inboxUnread();
    return ui.el(.data_row, .{
        .width = 36,
        .height = 36,
        .main = .center,
        .cross = .center,
        .padding = 0,
        .on_press = Msg.toggle_notifications,
        .style = .{ .quiet_hover = true },
        .semantics = .{
            .role = .button,
            .label = if (unread == 0) "Notifications" else ui.fmt("Notifications, {d} unread", .{unread}),
            .focusable = true,
        },
    }, .{
        ui.stack(.{ .width = 36, .height = 36 }, .{
            ui.column(.{ .width = 36, .height = 36, .main = .center, .cross = .center }, .{
                ui.appIcon(.{ .width = 17, .height = 17, .style = .{ .foreground = p.text_muted } }, "bell"),
            }),
            if (unread == 0) ui.spacer(0) else badgePill(ui, unread),
        }),
    });
}

/// The count itself, pinned to the tile's top-right.
fn badgePill(ui: *AppUi, count: usize) AppUi.Node {
    const p = theme.palette;
    const label = if (count > 9) "9+" else ui.fmt("{d}", .{count});
    return ui.column(.{ .width = 36, .height = 36, .main = .start, .cross = .end }, .{
        // The digit sits in a ROW inside the panel, not in the panel.
        //
        // `.panel` is a stacking kind: it hands every child the whole content box
        // and takes the MAX of them for its own size rather than the sum. The two
        // four-pixel spacers were therefore layered behind the digit instead of
        // inset either side of it, and contributed nothing at all. The pill's
        // width was the glyph advance, about five and a half points, so the
        // declared radius of 7 clamped to half of that and the "pill" painted as
        // a narrow lozenge with the number running edge to edge.
        ui.el(.panel, .{
            .padding = 0.01,
            .height = 13,
            // A floor, so one digit and two are the same shape rather than the
            // badge changing width with the count. It sets only the minimum, so a
            // wider label still grows: "9+" hugs to about nineteen, and anything
            // longer has room inside the 36-point rail column.
            .min_width = 19,
            .style = .{ .background = p.accent, .border = p.accent, .radius = 7, .stroke_width = 1 },
        }, .{
            // Centred on purpose: the stack gives this row the panel's whole
            // width, so once `min_width` exceeds what the digit needs, the row is
            // what keeps the number in the middle instead of against the left
            // edge.
            ui.row(.{ .main = .center, .cross = .center, .gap = 0 }, .{
                hgap(ui, 4),
                ui.paragraph(
                    .{ .style = .{ .foreground = p.on_accent } },
                    &.{.{ .text = label, .monospace = true, .weight = .medium, .scale = 9.0 / 14.5 }},
                ),
                hgap(ui, 4),
            }),
        }),
    });
}

/// One pressable rail tile: a 36px plate with a centered icon. `bright` paints
/// the accent fill (the compose verb); the rest are quiet with a muted glyph.
fn railTile(ui: *AppUi, comptime icon: []const u8, size: f32, press: Msg, label: []const u8, bright: bool) AppUi.Node {
    const p = theme.palette;
    const tint = if (bright) p.on_accent else p.text_muted;
    const glyph = ui.icon(.{ .width = size, .height = size, .style = .{ .foreground = tint } }, icon);
    return ui.row(.{
        .on_press = press,
        .style = .{ .quiet_hover = true },
        .semantics = .{ .role = .button, .label = label, .focusable = true },
    }, .{
        // Only the compose tile carries a plate. The quiet tiles are a glyph on
        // the rail itself, so they take no panel at all: a panel with no stated
        // background falls back to the house card fill and would draw a plate the
        // redesign does not have.
        if (bright)
            tilePlate(ui, .{ .background = p.accent, .radius = 9, .stroke_width = 0 }, "", glyph)
        else
            ui.column(.{ .width = 36, .height = 36, .main = .center, .cross = .center }, .{glyph}),
    });
}

/// The account seat at the bottom of the rail. A guest gets a dashed circle
/// marked "you" that opens the join sheet; a signed-in user gets a small tinted
/// initials avatar that opens their own page.
fn railYou(ui: *AppUi, guest: bool) AppUi.Node {
    const p = theme.palette;
    // The seat is the reader's own face, so it goes where every other face in
    // the app goes: that person's page. It pointed at Settings for as long as
    // there was no profile screen to point at, which quietly taught that "you"
    // means "your preferences". Settings keeps its own tile one row up, and
    // editing still lives there, which is what the profile's own "This is you"
    // says instead of standing up a second door to it.
    //
    // The key comes from `activePubkey` rather than from the `guest` flag so the
    // branch and the payload cannot disagree: with no identity there is no
    // `.open_person` carrying thirty-two bytes that belong to nobody.
    const press: Msg = if (activePubkey()) |me| Msg{ .open_person = me } else .open_join;
    return ui.el(.data_row, .{
        .on_press = press,
        // The tile's own box, stated. Left unsized, this row measured ZERO wide
        // (a `data_row` hugs its content and the seat inside it is centred, not
        // stretched), so the account seat floated free of the rail's column
        // while every glyph tile sat squarely in its 36. It was the one tile on
        // the rail that did not line up.
        .width = 36,
        .height = 36,
        .main = .center,
        .cross = .center,
        .padding = 0,
        .style = .{ .quiet_hover = true },
        .semantics = .{ .label = "You" },
    }, .{
        // The same 36x36 centring box every other rail tile uses. Without it the
        // 28px seat sat at the row's natural position while the 36px glyph tiles
        // sat centred in theirs, so the account avatar hung 4px off the rail's
        // shared centre line: the one tile on the rail that did not line up.
        ui.column(.{ .width = 36, .height = 36, .main = .center, .cross = .center }, .{
            if (guest)
                // The seat reads as an outline waiting to be filled, so its ring
                // is dashed. The canvas has no dashed strokes, so the ring is an
                // icon whose dashes are baked into its geometry, with the label
                // stacked over it.
                ui.stack(.{ .width = 28, .height = 28 }, .{
                    ui.appIcon(.{ .width = 28, .height = 28, .style = .{ .foreground = p.border_dashed } }, "dashed-ring"),
                    ui.column(.{ .width = 28, .height = 28, .main = .center, .cross = .center }, .{
                        ui.paragraph(.{ .style = .{ .foreground = p.text_muted } }, &.{.{ .text = "you", .monospace = true, .scale = 8.5 / 14.5 }}),
                    }),
                })
            else
                youAvatar(ui),
        }),
    });
}

/// The signed-in account avatar for the rail: a 28px tinted circle with the
/// pubkey's initials (the same warm tint the feed uses for that key).
fn youAvatar(ui: *AppUi) AppUi.Node {
    return meAvatar(ui, 28);
}

/// The registered avatar image id for `pubkey`, or 0 to draw initials.
///
/// The `.loaded` gate is load-bearing rather than cautious. The renderer takes
/// the image branch for ANY non-zero id and draws the initials only in the else,
/// so an id that has been lent but whose bytes have not arrived paints an EMPTY
/// disc instead of falling back. A slot is claimed before the fetch and survives
/// a failed one, so both of those states have to report zero.
fn avatarImageId(pubkey: [32]u8) u64 {
    const p = lookupProfile(pubkey) orelse return 0;
    if (p.avatar_state != .loaded) return 0;
    return p.image_id;
}

/// The signed-in reader's own disc at a stated size: the rail seats a 28, the
/// thread's reply row a 36 to match the note it answers.
///
/// It drew initials and only initials, because it never passed an image. Every
/// other link already worked: the reader's own kind:0 is asked for by the feed
/// subscription and by `ownProfileWorker`, `refreshProfiles` puts their pubkey
/// in the author list explicitly, and `assignAvatarSlots` pushes them FIRST so
/// they get one of the scarce ids ahead of any feed author. All of that ran, and
/// then the widget was built without the id it had earned.
fn meAvatar(ui: *AppUi, size: f32) AppUi.Node {
    const pk = activePubkey() orelse return ui.spacer(0);
    const tint = avatarTint(pk);
    const hexdigits = "0123456789abcdef";
    return ui.avatar(.{
        .width = size,
        .height = size,
        .image = avatarImageId(pk),
        .style = .{ .background = tint.bg, .border = tint.border, .foreground = tint.glyph, .stroke_width = 1 },
    }, ui.fmt("{c}{c}", .{ hexdigits[pk[0] >> 4], hexdigits[pk[0] & 0x0f] }));
}

/// The backup nudge: calm, dismissible, the stakes stated plainly. Rises once,
/// after the first local-key post of a session.
fn backupNudge(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .style = .{ .background = p.surface_subbar } }, .{
        ui.column(.{ .height = 1, .style = .{ .background = p.divider_chrome } }, .{}),
        ui.row(.{ .cross = .center, .gap = 10, .padding = 10 }, .{
            ui.text(
                .{ .size = .sm, .wrap = true, .grow = 1, .style = .{ .foreground = p.text_muted_alt } },
                "Right now this key lives on one Mac. Back it up so losing the Mac is not losing the account.",
            ),
            ui.button(.{ .size = .sm, .variant = .primary, .on_press = .backup_now }, "Back up"),
            ui.button(.{ .size = .sm, .variant = .ghost, .on_press = .backup_later }, "Not now"),
        }),
    });
}

/// The guest banner: a full-width top bar over the feed with the invitation and
/// the two join CTAs, always present here so sign-in is never more than one bar
/// away. Dismissible, and safely so: the rail's compose and account tiles and
/// the status bar's Guest chip all keep a way in after it is closed.
fn guestBanner(ui: *AppUi, model: *const Model) AppUi.Node {
    _ = model;
    const p = theme.palette;
    // On a `.panel`, not a column: a column paints no background at all, so the
    // banner had been reading as plain window behind its own copy.
    return ui.el(.panel, .{ .padding = 0.01, .style = .{ .background = p.surface_subbar, .stroke_width = 0, .radius = 0 } }, .{
        ui.column(.{ .gap = 0 }, .{
            vgap(ui, 8),
            ui.row(.{ .cross = .center, .gap = 0 }, .{
                hgap(ui, chrome_inset),
                ui.paragraph(
                    .{ .wrap = true, .grow = 1, .style = .{ .foreground = p.text_muted_alt } },
                    &.{.{ .text = "Browsing as a guest. Reading is yours forever. Join in when something moves you.", .scale = meta_scale }},
                ),
                hgap(ui, 10),
                pillButton(ui, "Create identity", .open_join, true, p.surface_subbar),
                hgap(ui, 10),
                pillButton(ui, "Sign in", .open_join, false, p.surface_subbar),
                hgap(ui, 10),
                // An icon press, not a text button: the built-in x glyph (the
                // U+2715 codepoint is outside Geist's coverage, rendered tofu).
                // Padded well past the 12px glyph: the target is the press, not the
                // drawing.
                ui.row(.{
                    .padding = 6,
                    .on_press = .dismiss_guest_strip,
                    .style = .{ .quiet_hover = true },
                    .semantics = .{ .role = .button, .label = "Dismiss" },
                }, .{
                    ui.icon(.{ .width = 12, .height = 12, .style = .{ .foreground = p.text_faint_alt } }, "x"),
                }),
                hgap(ui, chrome_inset),
            }),
            vgap(ui, 8),
            ui.separator(.{ .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
        }),
    });
}

/// The feed's scope line: which feed this is (the starter pack) and how wide it
/// reaches. A property of the feed, not a destination to choose between.
fn scopeHeader(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    // The scope name and the pack's size, on one line with the redesign's 11/16/9
    // insets. The label and the meta sit at opposite ends, so they are separate
    // runs rather than the single paragraph they shared when they were adjacent.
    //
    // No action lives here any more. Compose is the rail's bright tile, and a
    // guest reaches the join sheet from the banner or the rail's seat, so the
    // scope line is what it says it is: a label.
    // Centred WITHOUT grow: a row that is a child of a column grows on the
    // column's axis, so `.grow` here would stretch the header down the window and
    // shove the feed with it. A row already stretches across, which is all the
    // centring needs.
    return ui.row(.{ .main = .center }, .{ui.column(.{ .width = feed_column_width, .gap = 0 }, .{
        vgap(ui, 11),
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            hgap(ui, chrome_inset),
            // The name AND its chevron are the trigger, so the menu opens under
            // the word it names rather than off a 11px glyph.
            ui.stack(.{}, .{
                ui.row(.{
                    .cross = .center,
                    .gap = 7,
                    .on_press = Msg{ .toggle_menu = .scope },
                    .style = .{ .quiet_hover = true },
                    .semantics = .{ .role = .button, .label = "Choose feed", .focusable = true },
                }, .{
                    ui.paragraph(
                        .{ .style = .{ .foreground = p.text_primary } },
                        &.{.{ .text = model.scope_name(), .weight = .bold, .scale = scope_title_scale }},
                    ),
                    ui.icon(.{ .width = 11, .height = 11, .style = .{ .foreground = p.text_muted } }, "chevron-down"),
                }),
                if (model.menu == .scope) scopeMenu(ui, model.scope_name()) else ui.spacer(0),
            }),
            ui.spacer(1),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_faint_alt } },
                &.{.{ .text = model.scope_voices(ui.arena), .monospace = true, .scale = mono_meta_scale }},
            ),
            hgap(ui, chrome_inset),
        }),
        vgap(ui, 9),
        ui.separator(.{ .width = feed_column_width, .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
    })});
}

/// The status bar: the caught-up line on the left (there is no spinner, the feed
/// renders from disk), relay health on the right after an online dot.
fn statusBar(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        ui.separator(.{ .style = .{ .foreground = p.divider_chrome, .background = p.divider_chrome } }),
        // Four zones, every one pressable, and colour only where something needs
        // the reader. The chip row's own inset is 8, and the chips space at 4.
        ui.row(.{ .height = 30, .cross = .center, .gap = 0 }, .{
            hgap(ui, 8),
            // Feed state. Pressing it brings the newest note back to the top.
            statusChip(ui, .{
                .press = .jump_to_newest,
                .label = model.caught_up(ui.arena),
                .semantics = "Refresh the feed",
            }),
            ui.spacer(1),
            outboxZone(ui, model),
            relayZone(ui, model),
            hgap(ui, 4),
            signerZone(ui, model),
            hgap(ui, 8),
        }),
    });
}

/// The scope menu. One entry today, and it is the current one, so this exists to
/// say what the chevron means rather than to offer a choice: the reader learns
/// where scopes live before there is a second one to pick.
fn scopeMenu(ui: *AppUi, scope: []const u8) AppUi.Node {
    const rows = ui.arena.alloc(AppUi.Node, 1) catch return ui.spacer(0);
    rows[0] = menuRow(ui, scope, "check", null, .close_menu);
    // The scope line sits at the top of the window, so its menu drops down.
    return menuSurfacePlaced(ui, 200, .below, .start, rows);
}

/// A scope name as it reads mid-sentence.
fn lowerScope(scope: []const u8) []const u8 {
    if (std.mem.eql(u8, scope, "Following")) return "following";
    return "starter pack";
}

/// What a note offers beyond its verbs: where it is, what it says, and what to
/// do about whoever wrote it.
///
/// The same items back the right-click menu (`noteContextItems`), because two
/// lists would be two lists to keep in step and the reader would find different
/// actions depending on which way they reached for them.
fn noteMenu(ui: *AppUi, note: *const Note) AppUi.Node {
    const rows = ui.arena.alloc(AppUi.Node, 7) catch return ui.spacer(0);
    var n: usize = 0;
    // No glyphs. Two of these four had one and two did not, which reads as two
    // items with something extra rather than as one list: a menu's items are
    // alike, and a glyph on some of them is a difference that means nothing.
    rows[n] = menuRow(ui, "Copy note address", null, null, Msg{ .copy_nevent = note.id });
    n += 1;
    rows[n] = menuRow(ui, "Quote", null, null, Msg{ .quote_note = note.id });
    n += 1;
    rows[n] = menuRow(ui, "Copy text", null, null, Msg{ .copy_note_text = note.id });
    n += 1;
    rows[n] = menuRow(ui, "Open on the web", null, null, Msg{ .open_web = note.id });
    n += 1;
    rows[n] = menuSeparatorRow(ui);
    n += 1;
    rows[n] = followMenuRow(ui, note.pubkey);
    n += 1;
    // Its OWN dismiss, not the chrome's. `menuSurfacePlaced` sends `close_menu`,
    // which clears `model.menu`, and this menu's open state is `model.note_menu`:
    // Escape and a press outside hid it for one frame and the next rebuild put
    // it straight back, because nothing had told the model. The helper that takes
    // a dismiss message exists for exactly this, and says so.
    return menuSurfacePlacedDismissing(ui, 220, .below, .end, Msg.close_note_menu, rows[0..n]);
}

/// The same actions as the note's menu, for a right-click anywhere on the row.
///
/// One list, not two. A right-click that offered a different set from the `...`
/// beside it would be two menus to keep in step, and the reader would find
/// different actions depending on which way they reached for them. The runtime
/// presents these as the platform's own menu where there is one, and as the same
/// anchored surface everything else uses where there is not.
fn noteContextItems(ui: *AppUi, note: *const Note, in_thread: bool) []const AppUi.ContextMenuItem {
    const items = ui.arena.alloc(AppUi.ContextMenuItem, 7) catch return &.{};
    var n: usize = 0;
    if (!in_thread) {
        items[n] = .{ .label = "Open thread", .msg = Msg{ .open_thread = note.id } };
        n += 1;
    }
    items[n] = .{ .label = "Copy note address", .msg = Msg{ .copy_nevent = note.id } };
    n += 1;
    items[n] = .{ .label = "Quote", .msg = Msg{ .quote_note = note.id } };
    n += 1;
    items[n] = .{ .label = "Copy text", .msg = Msg{ .copy_note_text = note.id } };
    n += 1;
    items[n] = .{ .label = "Open on the web", .msg = Msg{ .open_web = note.id } };
    n += 1;
    items[n] = .{ .separator = true };
    n += 1;
    items[n] = followContextItem(note.pubkey);
    n += 1;
    return items[0..n];
}

/// The follow entry for a right-click, in the same states the menu row has.
/// Disabled rather than absent where it cannot act, so the reason is visible
/// instead of the action silently missing.
fn followContextItem(author: [32]u8) AppUi.ContextMenuItem {
    const me = activePubkey();
    if (me) |pk| {
        if (std.mem.eql(u8, &pk, &author)) return .{ .label = "This is you", .enabled = false };
    } else return .{ .label = "Follow", .msg = Msg{ .follow_author = 0 } };
    if (followBlockedReason()) |reason| return .{ .label = reason, .enabled = false };
    if (isFollowedByMe(author)) return .{ .label = "Unfollow", .msg = Msg{ .follow_author = 2 } };
    return .{ .label = "Follow", .msg = Msg{ .follow_author = 1 } };
}

/// The follow line, in whatever state it is honestly in.
fn followMenuRow(ui: *AppUi, author: [32]u8) AppUi.Node {
    const me = activePubkey();
    const is_me = if (me) |pk| std.mem.eql(u8, &pk, &author) else false;
    if (is_me) return menuRow(ui, "This is you", null, null, null);
    if (me == null) return menuRow(ui, "Follow", null, null, Msg{ .follow_author = 0 });
    // Not "Follow", greyed. The reason is worth saying: the app is still
    // looking for a list it must not write over. A silently dead Follow
    // button is what every client that got this safety right got wrong.
    if (followBlockedReason()) |reason| return menuRow(ui, reason, null, null, null);
    if (isFollowedByMe(author)) return menuRow(ui, "Unfollow", null, null, Msg{ .follow_author = 2 });
    return menuRow(ui, "Follow", null, null, Msg{ .follow_author = 1 });
}

/// A rule between groups of menu items.
fn menuSeparatorRow(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 4),
        ui.el(.panel, .{ .height = 1, .padding = 0.01, .style = .{ .background = p.divider_card, .radius = 0, .stroke_width = 0 } }, .{}),
        vgap(ui, 4),
    });
}

/// The chrome's floating surface: a menu anchored to the trigger it hangs off.
///
/// Anchoring makes the surface leave its parent's flow entirely: it takes no
/// space in the row, paints in a late window-level pass above everything, and
/// escapes every ancestor clip, which is what lets a 30px status bar open a
/// 340px panel. It opens ABOVE, since the bar sits on the floor of the window,
/// and the runtime flips it if there is no room.
///
/// `on_dismiss` is what makes Escape and a press outside close it, so the model
/// never needs to hear about the click that landed elsewhere.
fn menuSurface(ui: *AppUi, width: f32, children: []const AppUi.Node) AppUi.Node {
    // A status-bar menu hangs off the right end of its chip, above the bar.
    return menuSurfacePlaced(ui, width, .above, .end, children);
}

/// The same surface with its placement stated, for a trigger that is not on the
/// floor of the window.
fn menuSurfacePlaced(ui: *AppUi, width: f32, placement: canvas.WidgetAnchorPlacement, alignment: canvas.WidgetAnchorAlignment, children: []const AppUi.Node) AppUi.Node {
    return menuSurfacePlacedDismissing(ui, width, placement, alignment, Msg.close_menu, children);
}

/// The same surface, told what to send when the reader clicks away. A menu whose
/// dismiss clears somebody else's state stays open and flickers back.
fn menuSurfacePlacedDismissing(ui: *AppUi, width: f32, placement: canvas.WidgetAnchorPlacement, alignment: canvas.WidgetAnchorAlignment, dismiss: Msg, children: []const AppUi.Node) AppUi.Node {
    const p = theme.palette;
    return ui.el(.dropdown_menu, .{
        .width = width,
        .anchor = placement,
        .anchor_alignment = alignment,
        .anchor_offset = 6,
        .padding = 5,
        .on_dismiss = dismiss,
        .style = .{ .background = p.surface_menu, .border = p.border_menu, .radius = 9, .stroke_width = 1 },
    }, .{
        ui.column(.{ .gap = 0 }, .{children}),
    });
}

/// One row in a chrome menu: a label, an optional glyph and an optional trailing
/// hint, at the redesign's 6 by 9 padding.
fn menuRow(ui: *AppUi, label: []const u8, glyph: ?[]const u8, hint: ?[]const u8, press: ?Msg) AppUi.Node {
    const p = theme.palette;
    // A plain row, deliberately: the `menu_item` kind is what the renderer would
    // wash on hover, but it lays its children out and then draws none of them
    // (the rows measured 330x32 and painted nothing at all). So a menu row has
    // no hover state until that is understood; the design specifies a SELECTED
    // row surface, which is a different state and is drawn.
    return ui.row(.{
        .cross = .center,
        .gap = 0,
        .on_press = press,
        // Some rows in this menu are statements, not choices: "This is you", and
        // the line explaining why following is not offered yet. Those carry no
        // press, so they are not buttons and must not say they are.
        .semantics = .{
            .role = if (press != null) .button else .none,
            .label = label,
            .focusable = press != null,
        },
    }, .{
        hgap(ui, 9),
        vgap(ui, 25),
        if (glyph) |name| ui.appIcon(.{ .width = 13, .height = 13, .style = .{ .foreground = p.text_secondary } }, name) else ui.spacer(0),
        if (glyph != null) hgap(ui, 9) else ui.spacer(0),
        ui.paragraph(.{ .style = .{ .foreground = p.text_body } }, &.{.{ .text = label, .scale = menu_scale }}),
        ui.spacer(1),
        if (hint) |text|
            ui.paragraph(.{ .style = .{ .foreground = p.text_label } }, &.{.{ .text = text, .monospace = true, .scale = mono_hint_scale }})
        else
            ui.spacer(0),
        hgap(ui, 9),
    });
}

/// A rule between groups of menu rows.
fn menuSeparator(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 4),
        ui.row(.{ .gap = 0 }, .{ hgap(ui, 7), ui.separator(.{ .grow = 1, .style = .{ .foreground = p.border_menu, .background = p.border_menu } }), hgap(ui, 7) }),
        vgap(ui, 4),
    });
}

/// The relay popover: every relay in the pool, what it is doing, and how fast it
/// answers, then the two things a reader can do about it.
fn relayPopover(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const slots = relaySlots();
    const rows = ui.arena.alloc(AppUi.Node, slots + 4) catch return ui.spacer(0);
    // The header says what the list means, so nobody reads it as a picker.
    rows[0] = ui.row(.{ .cross = .center, .gap = 0 }, .{
        hgap(ui, 9),
        vgap(ui, 24),
        ui.paragraph(.{ .style = .{ .foreground = p.text_primary } }, &.{.{ .text = "Relays", .weight = .medium, .scale = menu_scale }}),
        hgap(ui, 8),
        ui.paragraph(.{ .style = .{ .foreground = p.text_muted_alt } }, &.{.{ .text = "reads & writes route automatically", .monospace = true, .scale = mono_meta_scale }}),
        ui.spacer(1),
        hgap(ui, 9),
    });
    // Compacted, NEVER indexed by slot: a dormant slot in the middle would
    // otherwise leave a row nobody wrote, and the arena hands out uninitialised
    // memory that the widget walker would then follow.
    var n: usize = 1;
    for (0..slots) |i| {
        const entry = relayAt(i) orelse continue;
        // Every relay the reader has, marked with what it is for. Hiding the
        // read-only ones would make this list disagree with both the chip
        // counting them and the Settings card listing them.
        rows[n] = relayRow(ui, entry.url(), i, relayBadgeText(entry), model);
        n += 1;
    }
    rows[n] = menuSeparator(ui);
    rows[n + 1] = menuRow(ui, if (model.relays_paused) "Resume Relays" else "Pause Relays", null, null, .toggle_relays_paused);
    rows[n + 2] = menuRow(ui, "Relay Settings…", null, "Cmd+,", .open_settings);
    return menuSurface(ui, 340, rows[0 .. n + 3]);
}

/// One relay in the popover: its state as a dot, its host, what it is for, and
/// how long it took to answer.
fn relayRow(ui: *AppUi, url: []const u8, index: usize, badge: []const u8, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const state: Conn = @enumFromInt(g_relay_status[index].load(.monotonic));
    // A relay leaves at its next message, so during a pause some rows are still
    // genuinely connected. Each row reports ITSELF: claiming the whole list is
    // paused while notes are still arriving on it is the dishonesty this is for.
    // Holding a socket, whichever way. The row still reads as a working relay
    // (its round trip is real, its badge means something), and only the dot and
    // the word say that the last evidence of life is a minute old.
    const connected = connHolds(state);
    const paused = model.relays_paused and !connected;
    const dot = if (paused)
        p.text_faint_alt
    else if (state == .connected)
        p.status_success
    else if (state == .connecting or state == .quiet)
        p.status_warning
    else
        p.status_offline;
    // The host alone: the scheme is the same on every row and carries no news.
    const host = if (std.mem.startsWith(u8, url, "wss://")) url["wss://".len..] else url;
    return ui.row(.{ .cross = .center, .gap = 0 }, .{
        hgap(ui, 9),
        vgap(ui, 21),
        ui.el(.panel, .{ .width = 6, .height = 6, .padding = 0.01, .style = .{ .background = dot, .radius = 3, .stroke_width = 0 } }, .{}),
        hgap(ui, 8),
        ui.paragraph(.{ .style = .{ .foreground = if (connected) p.text_body else p.text_muted_alt } }, &.{.{ .text = host, .monospace = true, .scale = mono_row_scale }}),
        ui.spacer(1),
        // What the relay is for is true whether or not it is answering, so the
        // badge stays put when it drops. A row that loses its marker while
        // offline would read as a relay whose purpose changed.
        relayBadge(ui, badge),
        hgap(ui, 8),
        // A connected relay reports its round trip; one that is still dialling or
        // has dropped says so in words instead of showing a stale number.
        ui.paragraph(
            .{ .style = .{ .foreground = if (connected) p.text_muted_alt else p.status_warning_text } },
            &.{.{
                .text = if (paused)
                    "paused"
                else if (state == .quiet)
                    "quiet"
                else if (connected)
                    (if (relayRttMs(index)) |ms| ui.fmt("{d}ms", .{ms}) else "…")
                else if (state == .connecting)
                    "connecting"
                else
                    "offline",
                .monospace = true,
                .scale = mono_meta_scale,
            }},
        ),
        hgap(ui, 9),
    });
}

/// What a relay is for, in NIP-65's own two letters.
fn relayBadgeText(e: *const RelayEntry) []const u8 {
    if (e.read and e.write) return "R·W";
    if (e.read) return "R";
    if (e.write) return "W";
    // A relay that is neither is not reachable in the UI (the badge cycles
    // through three live states), but a list read from disk or from a
    // kind:10002 with an unknown marker can land here. Saying so beats
    // claiming a direction it does not have.
    return "off";
}

/// The R·W chip on a relay row: what the relay is used for.
fn relayBadge(ui: *AppUi, text: []const u8) AppUi.Node {
    const p = theme.palette;
    return ui.el(.panel, .{ .padding = 0.01, .style = .{ .background = p.surface_menu, .border = p.border_dashed, .radius = 4, .stroke_width = 1 } }, .{
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            hgap(ui, 5),
            ui.paragraph(.{ .style = .{ .foreground = p.text_muted_alt } }, &.{.{ .text = text, .monospace = true, .scale = mono_badge_scale }}),
            hgap(ui, 5),
        }),
    });
}

/// The signed-in account's display name, or its npub until a kind:0 arrives.
fn accountName() []const u8 {
    if (activePubkey()) |pk| {
        if (lookupProfile(pk)) |profile| {
            if (profile.name_len > 0) return profile.name();
        }
    }
    return npubShort();
}

/// Whether a kind:0 name is known, so the npub is worth showing beneath it.
fn accountHasName() bool {
    if (activePubkey()) |pk| {
        if (lookupProfile(pk)) |profile| return profile.name_len > 0;
    }
    return false;
}

fn npubShort() []const u8 {
    return g_identity_npub_buf[0..g_identity_npub_len];
}

/// The account menu: who you are, and the two things to do about it. No mock
/// draws this, so it is the menu recipe with the identity row on top; flagged in
/// the PR for review.
fn accountMenu(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    const rows = ui.arena.alloc(AppUi.Node, 5) catch return ui.spacer(0);
    rows[0] = ui.row(.{ .cross = .center, .gap = 0 }, .{
        hgap(ui, 9),
        vgap(ui, 34),
        youAvatar(ui),
        hgap(ui, 9),
        ui.column(.{ .gap = 0 }, .{
            ui.paragraph(.{ .style = .{ .foreground = p.text_primary } }, &.{.{ .text = accountName(), .weight = .medium, .scale = menu_scale }}),
            // The npub only when it is not already the name above it: an account
            // with no kind:0 yet would otherwise read its own key twice.
            if (accountHasName())
                ui.paragraph(.{ .style = .{ .foreground = p.text_label } }, &.{.{ .text = npubShort(), .monospace = true, .scale = mono_meta_scale }})
            else
                ui.spacer(0),
        }),
        ui.spacer(1),
        hgap(ui, 9),
    });
    rows[1] = menuSeparator(ui);
    var n: usize = 2;
    // The chip this menu hangs off says "Notary ready", so the way to Notary
    // belongs here as well as in Settings: this is where a reader looks when
    // they are wondering about their signer, because it is the thing that just
    // told them about it.
    if (openNotaryAvailable()) {
        rows[n] = menuRow(ui, "Open Notary", null, null, .open_notary_window);
        n += 1;
    }
    // No glyph. "Open Notary" and "Sign out" carry none, and one icon among
    // three reads as a mistake rather than as emphasis.
    rows[n] = menuRow(ui, "Settings…", null, "Cmd+,", .open_settings);
    n += 1;
    rows[n] = menuRow(ui, "Sign out", null, null, .open_settings_logout);
    n += 1;
    return menuSurface(ui, 240, rows[0..n]);
}

/// The banner 11p draws when no relay is answering. It says what still works,
/// which is nearly everything: the store is the app, so reading continues, and a
/// note written now is queued rather than refused. A spinner would say the
/// opposite.
fn offlineBanner(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    if (liveRelayCount() > 0) return ui.spacer(0);
    const queued = model.outbox_pending;
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 8),
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, chrome_inset),
            ui.el(.panel, .{
                .grow = 1,
                .padding = 0.01,
                .style = .{ .background = p.surface_offline, .border = p.border_offline, .radius = 8, .stroke_width = 1 },
            }, .{
                ui.row(.{ .cross = .center, .gap = 0 }, .{
                    hgap(ui, 11),
                    ui.column(.{ .gap = 0 }, .{
                        vgap(ui, 8),
                        ui.row(.{ .cross = .center, .gap = 0 }, .{
                            ui.icon(.{ .width = 13, .height = 13, .style = .{ .foreground = p.status_warning } }, "alert"),
                            hgap(ui, 8),
                            ui.paragraph(
                                .{ .wrap = true, .grow = 1, .style = .{ .foreground = p.status_warning_text } },
                                &.{.{ .text = offlineBannerText(ui, queued), .scale = meta_scale }},
                            ),
                        }),
                        vgap(ui, 8),
                    }),
                    hgap(ui, 11),
                }),
            }),
            hgap(ui, chrome_inset),
        }),
    });
}

/// What the banner says, which depends on whether anything is owed.
fn offlineBannerText(ui: *AppUi, queued: usize) []const u8 {
    if (queued == 0) return "No relay is answering. Reading continues from this machine; anything you write is kept until one does.";
    return ui.fmt("No relay is answering. Reading continues from this machine, and {d} {s} waiting to go out.", .{ queued, if (queued == 1) "note is" else "notes are" });
}

pub fn offlineBannerTextForTest(arena: std.mem.Allocator, queued: usize) []const u8 {
    var ui = AppUi.init(arena);
    return offlineBannerText(&ui, queued);
}

/// What the app still owes the reader. Absent when nothing is queued, which is
/// most of the time: a zone that is always there teaches nothing, and an empty
/// popover under it would be worse.
///
/// Amber, because this is work in progress rather than a warning: a note on its
/// way is the ordinary case. The glyph takes the text's own hex, not the
/// brighter alert amber.
fn outboxZone(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    if (model.outbox_pending == 0 and model.outbox_stuck == 0 and !model.outbox_overflowed) return ui.spacer(0);
    const stuck = model.outbox_overflowed or (model.outbox_pending == 0 and model.outbox_stuck > 0);
    return ui.row(.{ .cross = .center, .gap = 0 }, .{
        ui.el(.list_item, .{
            .padding = 0.01,
            .height = 22,
            .cross = .center,
            .on_press = Msg{ .toggle_menu = .outbox },
            .style = .{ .radius = 6, .background = if (model.menu == .outbox) p.surface_chip else null },
            .semantics = .{ .role = .button, .label = "Notes on their way", .focusable = true },
        }, .{
            hgap(ui, 7),
            // A runtime choice of glyph, so `appIcon` rather than the
            // comptime-checked `icon`.
            ui.appIcon(.{ .width = 11, .height = 11, .style = .{ .foreground = if (stuck) p.status_offline else p.status_warning_text } }, if (stuck) "alert" else "arrow-up"),
            hgap(ui, 6),
            ui.paragraph(
                .{ .style = .{ .foreground = if (stuck) p.status_offline else p.status_warning_text } },
                &.{.{ .text = model.outbox_label(ui.arena), .scale = status_scale }},
            ),
            hgap(ui, 7),
        }),
        if (model.menu == .outbox) outboxMenu(ui) else ui.spacer(0),
        hgap(ui, 4),
    });
}

/// One card per note on its way, newest first. No mock exists for this surface;
/// it is the smallest thing that answers the question the zone raises, which is
/// "which note, and how far did it get".
fn outboxMenu(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    var entries: [outbox_cap]OutboxEntry = undefined;
    const n = outboxSnapshot(&entries);
    if (n == 0) return ui.spacer(0);
    const rows = ui.arena.alloc(AppUi.Node, n) catch return ui.spacer(0);
    for (rows, entries[0..n]) |*row, e| {
        const title = switch (e.state()) {
            .queued => "Waiting for a relay",
            .sending => "Sending",
            .sent => "Sent",
            .stuck => "No relay took it",
        };
        row.* = ui.column(.{ .gap = 0 }, .{
            vgap(ui, 6),
            ui.row(.{ .cross = .center, .gap = 0 }, .{
                hgap(ui, 9),
                ui.el(.panel, .{ .width = 6, .height = 6, .padding = 0.01, .style = .{
                    .background = switch (e.state()) {
                        .queued => p.status_offline,
                        .sending => p.status_warning_text,
                        .sent => p.status_success,
                        .stuck => p.status_offline,
                    },
                    .radius = 3,
                    .stroke_width = 0,
                } }, .{}),
                hgap(ui, 8),
                ui.paragraph(.{ .style = .{ .foreground = p.text_secondary } }, &.{.{ .text = title, .weight = .medium, .scale = menu_scale }}),
                ui.spacer(1),
                ui.paragraph(
                    .{ .style = .{ .foreground = p.text_dim } },
                    &.{.{ .text = ui.fmt("{d}/{d} relays", .{ e.ackCount(), writeRelayCount() }), .monospace = true, .scale = mono_hint_scale }},
                ),
                hgap(ui, 9),
            }),
            vgap(ui, 6),
        });
    }
    return menuSurface(ui, 240, rows);
}

/// The relay zone: the pool's health, and the popover that explains it. The chip
/// is highlighted while the pool is healthy, because that is when the number is
/// worth reading at a glance; a degraded pool speaks through its dot instead.
fn relayZone(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const paused = model.relays_paused;
    // Both halves of the ratio come from the SAME sample. `model.live_relays`
    // and `model.relay_count` are read together once a second in `refresh`;
    // pairing that numerator with a live `relayCount()` reads "5/3 relays" for a
    // second after a removal, because the count drops the instant they press and
    // the live tally waits for the next tick.
    const total = model.relay_count;
    const live = @min(model.live_relays, total);
    // A paused pool that still has a socket open is PAUSING, not paused: a relay
    // leaves at its next message, and the bar refuses to claim otherwise.
    const settling = paused and live > 0;
    const dot = if (paused)
        p.text_faint_alt
    else if (live == 0)
        p.status_offline
    else if (!poolIsHealthyOf(live, total))
        p.status_warning
    else
        p.status_success;
    // No latency on the bar. A round-trip figure that swings with whichever
    // relay answered last is a number nobody acts on, and it sat where the
    // reader looks for whether the pool is up. The per-relay pings are still in
    // the card this chip opens, next to the relay each one belongs to, which is
    // the only place the number means anything.
    const label = if (settling)
        ui.fmt("pausing · {d}/{d} relays", .{ live, total })
    else if (paused)
        ui.fmt("paused · 0/{d} relays", .{total})
    else
        ui.fmt("{d}/{d} relays", .{ live, total });
    // And no plate. The dot already carries the pool's health, so the surface
    // behind it was a second voice saying the same thing, in the busiest corner
    // of the window.
    const plated = false;
    // The trigger and its floating surface are siblings in a stack: that is the
    // sanctioned shape, and the anchored surface takes no space in the row.
    return ui.stack(.{}, .{
        statusChip(ui, .{
            .press = Msg{ .toggle_menu = .relays },
            .label = label,
            .semantics = "Relays",
            .dot = dot,
            .chevron = true,
            .highlighted = plated,
            .ink = if (plated) p.text_secondary else p.text_muted,
        }),
        if (model.menu == .relays) relayPopover(ui, model) else ui.spacer(0),
    });
}

/// The signer zone: whether Plaza can sign right now, and the account menu.
fn signerZone(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const guest = model.is_guest();
    // Name the signer that is actually in use, and say whether it can sign right
    // now. Claiming "Notary ready" for a local key or an unreachable bunker would
    // be a chip that lies about where the reader's key lives.
    const signer = signerStatus();
    return ui.stack(.{}, .{
        statusChip(ui, .{
            .press = if (guest) .open_join else Msg{ .toggle_menu = .account },
            .label = if (guest) "Guest" else signer.label,
            .semantics = if (guest) "Join" else "Account",
            .glyph = if (guest) "plus" else signer.glyph,
            .glyph_color = if (guest) p.text_faint_alt else signer.color,
        }),
        if (model.menu == .account) accountMenu(ui) else ui.spacer(0),
    });
}

/// Whether the pool counts as healthy: MOST of it answering, not all of it. The
/// redesign's at-rest bar reads "4/5 relays" in green while its working bar reads
/// "3/5" in amber, so the line sits at four fifths. A relay pool always has a
/// straggler, and a bar that goes amber for one is a bar nobody reads.
pub fn poolIsHealthyForTest(live: usize) bool {
    return poolIsHealthy(live);
}

fn poolIsHealthy(live: usize) bool {
    return poolIsHealthyOf(live, relayCount());
}

/// The same line, against a total the caller already has, so a chip judges its
/// health on the pair of numbers it is about to print.
///
/// Stated as "one straggler is fine", which is what the rule above says it means,
/// rather than as four fifths. Those agree for a pool of five or more and part
/// company below it: at four relays, four fifths demands FOUR of four, so one
/// relay down turns the dot amber and leaves it there. That went unnoticed when
/// the bootstrap list dropped from five to four in this same change, and the
/// four-fifths test kept passing while asserting the opposite of its own name,
/// because the arithmetic had moved under it.
///
/// The second clause is not decoration. Without it a ONE relay pool with nothing
/// connected reads healthy, since `0 + 1 >= 1`.
fn poolIsHealthyOf(live: usize, total: usize) bool {
    if (total == 0) return false;
    return live + 1 >= total and live * 2 >= total;
}

/// What the status bar says about signing: which signer holds the key, and
/// whether it can be reached.
const SignerStatus = struct { label: []const u8, glyph: []const u8, color: canvas.Color };

/// Whether the thing that signs is actually able to sign right now. The chrome
/// carries this as a colour; the identity card needs it as a fact.
pub fn signerIsHealthy() bool {
    return switch (g_signer_kind) {
        .helper => g_helper_state.load(.monotonic) == 2,
        .remote => !g_remote_sign_notice.load(.acquire),
        .local => true,
    };
}

fn signerStatus() SignerStatus {
    const p = theme.palette;
    return switch (g_signer_kind) {
        // Notary: a separate process, so its health is a real question.
        //
        // Not installed is its own answer, ahead of the state machine. A session
        // restored onto an install with no Notary in it signs back in before the
        // probe has even run, and "unreachable" would send that reader looking
        // for a daemon that has crashed or a port that is busy. Nothing is
        // coming up; the install is short a file.
        .helper => if (keyholderMissing())
            .{ .label = "Notary is not installed", .glyph = "notary", .color = p.status_warning }
        else switch (g_helper_state.load(.monotonic)) {
            2 => .{ .label = "Notary ready", .glyph = "notary", .color = p.status_success },
            1 => .{ .label = "Notary has no key", .glyph = "notary", .color = p.status_warning },
            3 => .{ .label = "Notary unreachable", .glyph = "notary", .color = p.text_faint_alt },
            else => .{ .label = "Notary starting", .glyph = "notary", .color = p.status_warning },
        },
        // A remote bunker: reachable is the whole question, and the remote path
        // already tracks a failed round trip.
        .remote => if (g_remote_sign_notice.load(.acquire))
            .{ .label = "Signer unreachable", .glyph = "notary", .color = p.status_warning }
        else
            .{ .label = "Signer connected", .glyph = "notary", .color = p.status_success },
        // A key in this process: always able to sign, and honest about being local.
        .local => .{ .label = "Local key", .glyph = "notary", .color = p.status_success },
    };
}

/// One status-bar zone: a quiet pressable chip, highlighted only when it is
/// carrying live state the reader should look at.
const StatusChip = struct {
    press: Msg,
    label: []const u8,
    semantics: []const u8,
    /// A leading dot, for the relay zone's health.
    dot: ?canvas.Color = null,
    /// A leading glyph, for the signer zone and the offline warning.
    glyph: ?[]const u8 = null,
    glyph_color: canvas.Color = theme.palette.text_muted,
    /// A trailing chevron, for a chip that opens a menu.
    chevron: bool = false,
    highlighted: bool = false,
    ink: canvas.Color = theme.palette.text_muted,
};

fn statusChip(ui: *AppUi, chip: StatusChip) AppUi.Node {
    const p = theme.palette;
    // Gap 0 and explicit steps: a `gap` would space around the absent parts too,
    // so a chip with no dot and no chevron would carry their spacing anyway.
    const body = ui.row(.{ .cross = .center, .gap = 0 }, .{
        if (chip.dot) |color|
            ui.el(.panel, .{ .width = 6, .height = 6, .padding = 0.01, .style = .{ .background = color, .radius = 3, .stroke_width = 0 } }, .{})
        else
            ui.spacer(0),
        if (chip.dot != null) hgap(ui, 6) else ui.spacer(0),
        if (chip.glyph) |name|
            // `appIcon` takes a RUNTIME name and resolves built-ins first, then
            // the app table, so one call serves both vocabularies.
            ui.appIcon(.{ .width = 12, .height = 12, .style = .{ .foreground = chip.glyph_color } }, name)
        else
            ui.spacer(0),
        if (chip.glyph != null) hgap(ui, 6) else ui.spacer(0),
        ui.paragraph(.{ .style = .{ .foreground = chip.ink } }, &.{.{ .text = chip.label, .scale = status_scale }}),
        if (chip.chevron) hgap(ui, 6) else ui.spacer(0),
        if (chip.chevron)
            ui.icon(.{ .width = 10, .height = 10, .style = .{ .foreground = p.text_muted } }, "chevron-up")
        else
            ui.spacer(0),
    });
    // A highlighted chip carries a plate, so it needs a surface that paints; a
    // quiet one is text on the bar.
    const inner = if (chip.highlighted)
        ui.el(.panel, .{ .padding = 0.01, .style = .{ .background = p.surface_chip, .radius = 6, .stroke_width = 0 } }, .{
            ui.row(.{ .cross = .center, .gap = 0 }, .{ hgap(ui, 8), vgap(ui, 22), body, hgap(ui, 8) }),
        })
    else
        ui.row(.{ .cross = .center, .gap = 0 }, .{ hgap(ui, 8), body, hgap(ui, 8) });
    return ui.row(.{
        .cross = .center,
        .on_press = chip.press,
        .style = .{ .quiet_hover = true },
        .semantics = .{ .role = .button, .label = chip.semantics, .focusable = true },
    }, .{inner});
}

/// The warm avatar tint for an author, chosen deterministically from the
/// pubkey so a face keeps the same color across sessions. Neutral graphite is
/// the last entry and the natural fallback for an all-zero key.
fn avatarTint(pubkey: [32]u8) theme.palette.Tint {
    const key = @as(usize, pubkey[0]) +% pubkey[15] +% pubkey[31];
    return theme.palette.avatar_tints[key % theme.palette.avatar_tints.len];
}

/// A chrome pill: the redesign's 26px-high button, filled for the primary verb
/// and outlined for the quiet one. The house button is a different shape (28 high
/// on its own scale), so the chrome states its own.
fn pillButton(ui: *AppUi, label: []const u8, press: Msg, filled: bool, on_surface: canvas.Color) AppUi.Node {
    const p = theme.palette;
    // The outlined variant paints the surface it sits on, not "nothing": a panel
    // with no stated background falls back to the house card fill, which would
    // draw a plate the redesign's ghost button does not have.
    const style: canvas.WidgetStyle = if (filled)
        .{ .background = p.accent, .radius = 7, .stroke_width = 0 }
    else
        .{ .background = on_surface, .border = p.border_control, .radius = 7, .stroke_width = 1 };
    const ink = if (filled) p.on_accent else p.text_secondary;
    // The shot sets the filled label at 600 and the ghost at 500; the bundled
    // family steps 400 / 500 / 700, so both land on medium.
    const weight: canvas.TextSpanWeight = .medium;
    // The fill and the outline live on a `.panel`: a row paints no background at
    // all (the renderer draws nothing for the layout kinds), which is why the
    // filled pill was reading as dark-on-dark text with no button under it.
    return ui.row(.{
        .on_press = press,
        .style = .{ .quiet_hover = true },
        .semantics = .{ .role = .button, .label = label, .focusable = true },
    }, .{
        ui.el(.panel, .{ .padding = 0.01, .style = style }, .{
            ui.row(.{ .height = 26, .cross = .center, .gap = 0 }, .{
                hgap(ui, 11),
                ui.paragraph(.{ .style = .{ .foreground = ink } }, &.{.{ .text = label, .weight = weight, .scale = meta_scale }}),
                hgap(ui, 11),
            }),
        }),
    });
}

/// A metadata run: the 12px register, in the ink the caller names.
fn metaText(ui: *AppUi, text: []const u8, color: canvas.Color) AppUi.Node {
    return ui.paragraph(.{ .style = .{ .foreground = color } }, &.{.{ .text = text, .scale = meta_scale }});
}

/// The same, in a box it is not allowed to outgrow.
///
/// The width goes on the TEXT ELEMENT, not on an ancestor, and that distinction
/// is the whole fix. A definite width on the containing column does nothing: a
/// text leaf with no `wrap` measures as one line at its natural width whatever
/// its parents are, and `overflow = .ellipsis` cannot elide anything, because
/// an ellipsis needs a box to be too small for. I bounded the column, then the
/// column's parent, and the offending run measured exactly as wide both times.
/// Cuts `text` to at most `max` bytes and marks the cut with an ellipsis.
///
/// Because the engine has no max-width. `width` is a DEFINITE size: it bounds
/// the text, and it also makes the box exactly that wide whatever is in it. For
/// a leaf that owns its whole line that is precisely right. For one with a
/// neighbour it is wrong in a way that looks like a different bug: bounding a
/// profile's name that way put the verified check on the far side of the page,
/// and bounding the handle put a hand's width of nothing between it and the
/// npub. So where something sits beside the text, the string is shortened
/// instead and the box goes on hugging it.
///
/// Cuts on a UTF-8 boundary, so a name ending in an emoji or any non-Latin
/// script loses the character rather than being left as half of one.
fn elide(ui: *AppUi, text: []const u8, max: usize) []const u8 {
    if (text.len <= max) return text;
    var end = max;
    while (end > 0 and (text[end] & 0xc0) == 0x80) end -= 1;
    return ui.fmt("{s}\u{2026}", .{text[0..end]});
}

fn metaTextIn(ui: *AppUi, text: []const u8, color: canvas.Color, width: f32) AppUi.Node {
    return ui.paragraph(.{ .width = width, .style = .{ .foreground = color } }, &.{.{ .text = text, .scale = meta_scale }});
}

/// How much of a note's identity row belongs to the name and the handle.
///
/// The row is the identity block, a 6px gap, then the time. The time is the
/// app's own string ("4h via Amethyst" at its longest), so it is the part that
/// can be budgeted; the name and the handle are a stranger's, so they get what
/// is left and are held to it. Sixty-four characters of display name and a
/// hundred and twenty-eight of NIP-05 both fit the buffers that receive them,
/// which is to say both will arrive eventually.
const time_column_width: f32 = 124;
const identity_text_width: f32 = picture_column_width - 6 - time_column_width;

/// How long a stranger's string may be where something sits BESIDE it.
///
/// Lengths, not widths, and that is the engine's doing rather than a
/// preference: `width` is definite, so it would fix the box at that size and
/// send the verified check, the npub and "follows you" off to the right of a
/// three-letter name. See `elide`.
///
/// Chosen against the column each one lives in and then measured: the sweep
/// renders these at the capacity of the buffers that hold them, so a budget
/// that is too generous fails rather than shipping.
const profile_name_max: usize = 28;
const profile_band_name_max: usize = 32;
const profile_handle_max: usize = 34;

/// Fixed empty space along ONE axis. `ui.spacer(n)` takes a GROW factor, not a
/// size, so it cannot express an inset; these are the sized counterparts, used
/// wherever the redesign asks for a step that a uniform `padding` or `gap` cannot
/// state (a row inset of 12 top, 16 sides and 14 bottom; a column whose steps are
/// 5, 8 and 10). One axis each, so a spacer in a row never claims height and one
/// in a column never claims width.
fn hgap(ui: *AppUi, size: f32) AppUi.Node {
    return ui.el(.stack, .{ .width = size }, .{});
}

fn vgap(ui: *AppUi, size: f32) AppUi.Node {
    return ui.el(.stack, .{ .height = size }, .{});
}

/// The author disc: 36px, the tint keyed off the pubkey, initials when no
/// picture has been registered. The size is the redesign's, and it is what the
/// identity block beside it is pinned to.
fn noteAvatar(ui: *AppUi, note: *const Note) AppUi.Node {
    // The face is the way to the person. An `avatar` is not a hit target, so the
    // press needs a box around it, and that box is sized to the disc EXACTLY:
    // the reply rail hangs on the disc's centre line, computed as
    // `thread_inset + avatar_size / 2`, so a wrapper even a pixel wider moves
    // the rail off the avatars it is supposed to connect.
    return ui.el(.list_item, .{
        .width = avatar_size,
        .height = avatar_size,
        .padding = 0.01,
        .on_press = Msg{ .open_person = note.pubkey },
        .style = .{ .radius = avatar_size / 2, .quiet_hover = true },
        .semantics = .{ .role = .button, .label = "Open profile", .focusable = true },
    }, .{
        avatarDisc(ui, note, avatar_size),
    });
}

/// The same disc at an explicit size, for the surfaces that draw a smaller or
/// larger one (a nested thread child, a quote pill, a profile header).
fn avatarDisc(ui: *AppUi, note: *const Note, size: f32) AppUi.Node {
    const tint = avatarTint(note.pubkey);
    return ui.avatar(.{
        .image = note.avatar_id(),
        .width = size,
        .height = size,
        .style = .{ .background = tint.bg, .border = tint.border, .foreground = tint.glyph, .stroke_width = 1 },
    }, note.initials());
}

/// The identity block: the name over the handle, in a box pinned to the avatar's
/// height so the two lines sit against the disc's top and bottom edges. The
/// second line carries the verified check only when the author's NIP-05 actually
/// resolves to their pubkey; without a handle at all the block is just the name,
/// and the box still holds its height so a row never changes shape.
///
/// The redesign insets the two lines by 1px top and bottom. Padding is uniform
/// on this engine, and a 1px horizontal inset would push the name off the body's
/// left edge, so the box takes no padding: the name sits 1px higher and the
/// handle 1px lower than the mock, and every text run stays on one rail.
fn identityBlock(ui: *AppUi, note: *const Note) AppUi.Node {
    const p = theme.palette;
    // DEFINITE, and definite on the LEAF as well as the box.
    //
    // This used to say `grow`, reasoning that the block would take the width
    // left after the timestamp and a long display name would ellipsize inside
    // it. That is not what `grow` does: it hands out SPARE space and never
    // takes any back, so a name wider than the row keeps its full width and
    // takes the handle, the time and the card's right edge with it. Sixty-four
    // characters of display name reached 354px past the window.
    return ui.column(.{ .height = avatar_size, .width = identity_text_width, .main = .space_between }, .{
        ui.paragraph(
            .{ .width = identity_text_width, .style = .{ .foreground = p.text_primary } },
            &.{.{ .text = note.author(), .weight = .medium, .scale = name_scale }},
        ),
        handleLine(ui, note),
    });
}

/// The identity block's second line: the verified check, then the handle. The
/// check appears only when the author's NIP-05 resolved back to their pubkey, so
/// a claimed identity never wears a mark it has not earned.
fn handleLine(ui: *AppUi, note: *const Note) AppUi.Node {
    const p = theme.palette;
    // Checked BEFORE the label: a profile in flight shows the bar, never a
    // placeholder handle that swaps a beat later.
    if (profileLoading(note.pubkey)) return ui.el(.skeleton, .{ .width = 72, .height = 9 }, .{});
    const label = note.handleLabel(ui.arena);
    if (label.text.len == 0) return ui.spacer(0);
    // Bounded, and bounded by LESS when a check sits in front of it, so the two
    // together fit the block rather than the handle alone fitting it.
    const room = if (note.verified()) identity_text_width - 12 - 5 else identity_text_width;
    const handle = metaTextIn(ui, label.text, if (label.nip05) p.accent_identity else p.text_faint, room);
    // The check and its 5px gap exist only when there IS a check. A row gap is
    // charged for every flow child, so substituting a zero-width spacer for the
    // glyph would still indent the handle 5px past the name's rail.
    if (!note.verified()) return handle;
    return ui.row(.{ .gap = 5, .cross = .center }, .{
        ui.icon(.{ .width = 12, .height = 12, .style = .{ .foreground = p.status_success } }, "check-circle"),
        handle,
    });
}

/// How wide one verb's slot is, and how big its glyph is.
///
/// A SLOT, not a gap, and that is the whole point. The verbs used to sit in a
/// row with a 30px gap and a count beside each glyph, so the width of every
/// count pushed everything after it along: the heart landed at a different x on
/// every note in the feed, and a column of notes read as a column of rows that
/// could not agree where anything went. A fixed slot per verb puts every glyph
/// in the same column down the whole feed, whatever the counts do inside it.
///
/// 64 holds the glyph, its gap and the widest count `formatCount` can produce
/// (`999.9k`) without the next slot moving.
const verb_slot_width: f32 = 64;
/// And how tall. The row used to be exactly as tall as its glyphs measured
/// (18.125), so the verbs sat hard against the rule above them and the row
/// below: a strip of icons rather than a row of controls. This is the same
/// height the chrome gives its own pressable rows.
const verb_slot_height: f32 = 30;
const verb_icon_size: f32 = 15;

/// The engagement row: reply, repost, like, zap, bookmark, more, in that fixed
/// order, each an icon and its crowd count (the count omitted at zero).
///
/// Every icon people expect is drawn, including the ones with nothing behind
/// them yet: this is a deliberate call for the first release, so the row reads
/// as the row every other client has rather than as a shorter one that has lost
/// something. Reply and like work. Repost and zap carry REAL counts and no
/// action, so they keep the full tint (dimming them would misreport the crowd
/// to say something about the app). Bookmark and more carry nothing at all and
/// are drawn quieter to say so. None of the four takes hover, focus or a press,
/// so nothing here answers a click with silence.
fn engagementRow(ui: *AppUi, model: *const Model, note: *const Note) AppUi.Node {
    return engagementRowAt(ui, model, note, true);
}

/// The same row, told whether to carry its counts. The focal note in a thread
/// does not: the stats line above it already states every one of them in words,
/// and a number said twice in two registers is the second one looking like a
/// control.
fn engagementRowAt(ui: *AppUi, model: *const Model, note: *const Note, counts: bool) AppUi.Node {
    const p = theme.palette;
    const glyph = AppUi.ElementOptions{ .width = verb_icon_size, .height = verb_icon_size, .style = .{ .foreground = p.text_metric } };
    const quiet = AppUi.ElementOptions{ .width = verb_icon_size, .height = verb_icon_size, .style = .{ .foreground = p.text_dim } };
    const c = engagementFor(note.id);
    return ui.row(.{ .gap = 0, .cross = .center }, .{
        // Reply opens the note's thread, where the pinned composer answers it.
        // A plain pressable row, never a `.list_item`: that kind carries a 28px
        // intrinsic height floor and its padding walks the cluster off the rail
        // the disc, name and body share.
        verbSlot(ui, verbWithCount(ui, ui.appIcon(glyph, "reply"), if (counts) c.replies else 0, p.text_metric, .{
            .on_press = Msg{ .open_thread = note.id },
            .style = .{ .quiet_hover = true },
            .semantics = .{ .role = .button, .label = "Reply" },
        })),
        verbSlot(ui, verbWithCount(ui, ui.icon(glyph, "repeat"), if (counts) c.reposts else 0, p.text_metric, .{})),
        verbSlot(ui, likeAction(ui, note, counts)),
        // The zap count is summed sats (msat / 1000); the action itself waits
        // on a wallet.
        verbSlot(ui, verbWithCount(ui, ui.appIcon(glyph, "zap"), if (counts) c.zap_msat / 1000 else 0, p.text_metric, .{})),
        verbSlot(ui, ui.appIcon(quiet, "bookmark")),
        // The one unfinished-looking glyph that is not unfinished: it opens the
        // note's menu, the same one the thread's header has always had, with the
        // note's address, its words and its author behind it.
        //
        // The press sits on the SLOT rather than inside it, which is the one
        // place in this row that is safe: it is the last slot, so a target the
        // full 64 wide can only reach into the inert bookmark beside it, and a
        // wrapper of its own cost a node on every row in the feed and put the
        // app's worst frame over its node budget.
        ui.row(.{
            .width = verb_slot_width,
            .cross = .center,
            .gap = 0,
            .on_press = Msg{ .toggle_note_menu = note.id },
            .style = .{ .quiet_hover = true },
            .semantics = .{ .role = .button, .label = "More", .focusable = true },
        }, .{moreSlotChildren(ui, model, note, glyph)}),
    });
}

/// The more-slot's children: the glyph, and the menu only when it is THIS note's
/// menu that is open.
///
/// A slice rather than `if (open) menu else spacer(0)`, because a placeholder is
/// charged a widget node on every row whether or not it draws, and one per feed
/// row was enough to put the app's worst frame over the budget the suite holds.
fn moreSlotChildren(ui: *AppUi, model: *const Model, note: *const Note, glyph: AppUi.ElementOptions) []const AppUi.Node {
    const kids = ui.arena.alloc(AppUi.Node, 2) catch return &.{};
    kids[0] = ui.icon(glyph, "ellipsis");
    if (model.note_menu != note.id) return kids[0..1];
    kids[1] = noteMenu(ui, note);
    return kids[0..2];
}

/// One verb in its slot: the control at the left, the rest of the slot empty.
///
/// The slot is a fixed-width container rather than a fixed-width CONTROL, so a
/// press still has to land on the glyph and its count. A 64-wide hit target
/// would reach across the space between two verbs and answer for its neighbour,
/// and the neighbour of the heart is a glyph that does nothing yet: aiming at
/// the inert one and landing on the live one would publish a reaction.
fn verbSlot(ui: *AppUi, inner: AppUi.Node) AppUi.Node {
    return ui.row(.{ .width = verb_slot_width, .height = verb_slot_height, .cross = .center, .gap = 0 }, .{inner});
}

/// A verb's glyph and its count, as one control.
///
/// The count is left OUT of the children rather than substituted with an empty
/// node when it is zero. Both a row gap and a widget node are charged per flow
/// child whether or not it draws anything, and most notes in a feed carry zero
/// on most of these: a placeholder per empty count came to a tenth of the
/// window's whole widget budget across a screen of rows.
fn verbWithCount(ui: *AppUi, glyph: AppUi.Node, count: u64, color: canvas.Color, options: AppUi.ElementOptions) AppUi.Node {
    var kids: [2]AppUi.Node = undefined;
    kids[0] = glyph;
    var n: usize = 1;
    if (count > 0) {
        kids[1] = metaText(ui, formatCount(ui.arena, count), color);
        n = 2;
    }
    var opts = options;
    opts.gap = 6;
    opts.cross = .center;
    return ui.row(opts, .{kids[0..n]});
}

/// A count beside an action icon, or nothing at zero (so the icon stands alone
/// rather than showing a "0").
fn countLabel(ui: *AppUi, n: u64, color: canvas.Color) AppUi.Node {
    // `ui.spacer(0)` would still be charged the row's 6px gap, leaving a hole
    // where the count is not, so a zero count collapses the gap too.
    if (n == 0) return ui.el(.stack, .{ .width = 0, .height = 0 }, .{});
    return metaText(ui, formatCount(ui.arena, n), color);
}

/// The like control: a pressable heart and its count. Liked is never colour
/// alone (spec): the glyph fills red AND the count turns red together. The count
/// is the crowd's likes plus this session's own optimistic +1, which is dropped
/// once our own reaction comes back through the subscription (so it is not
/// counted twice).
fn likeAction(ui: *AppUi, note: *const Note, counts: bool) AppUi.Node {
    // Our own reaction id (if we liked this note), so the count can retire the
    // optimistic +1 once the reaction is folded into the crowd total.
    const my_reaction: ?[32]u8 = if (likeEntry(note.id)) |e| e.reaction_id else null;
    const liked = my_reaction != null;
    const count = likeCountFor(note.id, my_reaction);
    const tint = if (liked) theme.palette.status_like else theme.palette.text_metric;
    return verbWithCount(ui, ui.appIcon(.{ .width = verb_icon_size, .height = verb_icon_size, .style = .{ .foreground = tint } }, "like"), if (counts) count else 0, tint, .{
        .style = .{ .quiet_hover = true },
        .on_press = Msg{ .like = note.id },
        .semantics = .{ .role = .button, .label = if (liked) "Unlike" else "Like", .focusable = true },
    });
}

/// Formats an engagement count: the integer below 1000, one-decimal `k` above,
/// and empty at zero so the caller draws the icon alone rather than a "0".
pub fn formatCount(arena: std.mem.Allocator, n: u64) []const u8 {
    if (n == 0) return "";
    if (n < 1000) return std.fmt.allocPrint(arena, "{d}", .{n}) catch "";
    const k = @as(f64, @floatFromInt(n)) / 1000.0;
    return std.fmt.allocPrint(arena, "{d:.1}k", .{k}) catch "";
}

// Which long notes the reader has expanded past the "Show more" fold, by note
// id. Session-only and small: few notes are open at once, so a linear set with
// LRU-ish eviction is plenty. Id 0 marks an empty slot (a note's id is masked
// non-negative and never 0 in practice, the same sentinel `viewing_thread` uses).
const expanded_cap = 64;
/// The pictures the reader has asked for while previews are off. A per-note UI
/// fact, so it lives beside the reader rather than on the Note, which is rebuilt
/// from the store on every refresh. Oldest asked is dropped when it fills, the
/// same shape as the expanded-notes ring.
const asked_cap = 32;
var g_media_asked = [_]i64{0} ** asked_cap;

pub fn isMediaAsked(note_id: i64) bool {
    for (g_media_asked) |a| {
        if (a == note_id) return true;
    }
    return false;
}

fn askForMedia(note_id: i64) void {
    if (isMediaAsked(note_id)) return;
    for (&g_media_asked) |*a| {
        if (a.* == 0) {
            a.* = note_id;
            return;
        }
    }
    std.mem.copyForwards(i64, g_media_asked[0 .. asked_cap - 1], g_media_asked[1..]);
    g_media_asked[asked_cap - 1] = note_id;
}

pub fn askForMediaForTest(note_id: i64) void {
    askForMedia(note_id);
}

pub fn forgetAskedMediaForTest() void {
    g_media_asked = [_]i64{0} ** asked_cap;
}

var g_expanded = [_]i64{0} ** expanded_cap;

fn isExpanded(note_id: i64) bool {
    for (g_expanded) |e| {
        if (e == note_id) return true;
    }
    return false;
}

/// Toggles whether `note_id`'s long body is expanded. Evicts the oldest slot
/// when the (generous) set is full rather than refusing to expand.
fn toggleExpanded(note_id: i64) void {
    for (&g_expanded) |*e| {
        if (e.* == note_id) {
            e.* = 0;
            return;
        }
    }
    for (&g_expanded) |*e| {
        if (e.* == 0) {
            e.* = note_id;
            return;
        }
    }
    g_expanded[0] = note_id;
}

/// The byte length of `text` to show collapsed: the whole thing when it is not
/// long, else a prefix near `max` that ends on a codepoint boundary and, when
/// one is close, a word boundary, so the fold never cuts mid-word or mid-glyph.
fn collapsedLen(text: []const u8, max: usize) usize {
    if (text.len <= max) return text.len;
    var end = max;
    // Back to the start of a codepoint (never mid-sequence).
    while (end > 0 and (text[end] & 0xc0) == 0x80) end -= 1;
    // Prefer the last space/newline in the final quarter, so a word stays whole.
    const floor = (max * 3) / 4;
    var w = end;
    while (w > floor and text[w - 1] != ' ' and text[w - 1] != '\n') w -= 1;
    if (w > floor) end = w;
    return end;
}

/// Whether a note is long enough to collapse: comfortably past the fold, so a
/// note only a line or two over is shown whole rather than hiding a few words.
fn noteIsLong(note: *const Note) bool {
    return note.content_len > note_collapse_chars + 80;
}

/// A styled body paragraph, the same shape everywhere text is rendered.
fn textPara(ui: *AppUi, spans: []const canvas.TextSpan) AppUi.Node {
    return textParaAt(ui, spans, 1, theme.palette.text_body);
}

/// The same paragraph at a stated register and ink: the thread's focal note reads
/// one step up from a feed row, and a shade brighter.
fn textParaAt(ui: *AppUi, spans: []const canvas.TextSpan, scale: f32, ink: canvas.Color) AppUi.Node {
    const sized = if (scale == 1) spans else blk: {
        const out = ui.arena.alloc(canvas.TextSpan, spans.len) catch break :blk spans;
        for (spans, out) |src, *dst| {
            dst.* = src;
            // A span that already states its own scale keeps its ratio to the
            // body around it.
            dst.scale = (if (src.scale == 0) 1 else src.scale) * scale;
        }
        break :blk out;
    };
    return ui.paragraph(.{ .wrap = true, .on_link = AppUi.linkMsg(.open_url), .style = .{ .foreground = ink } }, sized);
}

/// A note's body: the styled text, an embedded quote card where the note quotes
/// another event, and a "Show more" affordance when it is long (unless the reader
/// has expanded it, or `collapsible` is false, as for a thread's focused root).
/// The body splits around the quoted event's raw token (its byte span), never
/// cutting the card; a quote at or past the fold appears only once expanded.
fn noteBody(ui: *AppUi, note: *const Note, collapsible: bool) AppUi.Node {
    return noteBodyAt(ui, note, collapsible, 1, theme.palette.text_body);
}

/// The body at a stated register: everything above, one step larger, for the note
/// a thread is about.
fn noteBodyAt(ui: *AppUi, note: *const Note, collapsible: bool, scale: f32, ink: canvas.Color) AppUi.Node {
    const p = theme.palette;
    const full = note.content();
    const long = collapsible and noteIsLong(note);
    const expanded = long and isExpanded(note.id);
    const cut: usize = if (long and !expanded) collapsedLen(full, note_collapse_chars) else full.len;
    const q = note.quote;
    const card_end = @as(usize, q.off) + @as(usize, q.len);
    const has_card = q.kind == .event and card_end <= cut;

    // Fast path unchanged: a plain note with no fold is exactly one paragraph.
    if (!has_card and !long) return textParaAt(ui, contentSpans(ui, full[0..cut]), scale, ink);

    var kids: [5]AppUi.Node = undefined;
    var n: usize = 0;
    if (has_card) {
        const head = std.mem.trim(u8, full[0..q.off], " \t\r\n");
        if (head.len > 0) {
            kids[n] = textParaAt(ui, contentSpans(ui, head), scale, ink);
            n += 1;
        }
        kids[n] = quoteRule(ui, q.id);
        n += 1;
        const tail = std.mem.trim(u8, full[card_end..cut], " \t\r\n");
        if (tail.len > 0) {
            kids[n] = textParaAt(ui, contentSpans(ui, tail), scale, ink);
            n += 1;
        }
    } else {
        kids[n] = textParaAt(ui, contentSpans(ui, full[0..cut]), scale, ink);
        n += 1;
    }
    if (long) {
        // A deeper hit target than the row's open-thread press, so tapping it
        // toggles the fold rather than opening the thread.
        kids[n] = ui.el(.data_row, .{ .on_press = Msg{ .toggle_expand = note.id }, .padding = 2, .style = .{ .quiet_hover = true }, .semantics = .{ .role = .button, .label = if (expanded) "Show less" else "Show more" } }, .{
            ui.text(.{ .size = .sm, .style = .{ .foreground = p.text_secondary } }, if (expanded) "Show less" else "Show more"),
        });
        n += 1;
    }
    return ui.column(.{ .gap = 8 }, .{kids[0..n]});
}

/// An embedded quote card for a quoted event `id`: a bordered inset showing the
/// quoted author and a truncated body, tappable to open it. Loading and
/// unavailable states are non-pressable and hold the same height, so the feed
/// never reflows as the quote resolves. The author is drawn as initials-on-tint
/// (`image = 0`), so a quote card never competes for the scarce avatar ids.
fn quoteRule(ui: *AppUi, id: [32]u8) AppUi.Node {
    const p = theme.palette;
    const e = quoteFor(id);
    if (e == null or e.?.state == .idle or e.?.state == .fetching) {
        // A reused feed note (never re-parsed) whose quote slot was reclaimed by
        // a newer quote lands here with no cache entry; re-queue it so the next
        // tick resolves it again instead of showing a skeleton forever.
        if (e == null) wantQuote(id);
        return quoteAside(ui, null, quoteSkeleton(ui));
    }
    const q = e.?;
    if (q.state == .missing) {
        // "Yet", because that is now true. This card said "unavailable" from
        // when three unanswered tries ended the search for good; the search does
        // not end any more, so the card must not say it does. It is the same
        // sentence the ancestor row above a thread has always used for the same
        // situation, which is the other reason to use it.
        return quoteAside(ui, null, ui.paragraph(
            .{ .style = .{ .foreground = p.text_muted } },
            &.{.{ .text = "Not on your relays yet", .scale = nested_body_scale }},
        ));
    }

    // A synthetic note, so the quote wears the SAME identity recipe as every
    // other row instead of a second one built from the cache's parts. Writing a
    // parallel builder is what cost the focal note its quote card once already.
    const note = ui.arena.create(Note) catch return ui.spacer(0);
    note.* = .{ .pubkey = q.pubkey, .created_at = q.created_at };
    const hexdigits = "0123456789abcdef";
    note.initials_buf = .{ hexdigits[q.pubkey[0] >> 4], hexdigits[q.pubkey[0] & 0x0f] };
    setAuthor(note, q.pubkey);
    note.setTime(nowSeconds());
    const text = q.text_buf[0..q.text_len];
    @memcpy(note.content_buf[0..text.len], text);
    note.content_len = @intCast(text.len);
    // The quoted note's OWN reference is drawn as the pill below, so it comes
    // out of the body: left in, it is a hundred characters of bech32 that no
    // line break can split, which runs straight out of the reading column.
    findQuoteRef(note);
    if (note.quote.kind == .event) {
        const cut_start = @as(usize, note.quote.off);
        const cut_end = cut_start + @as(usize, note.quote.len);
        if (cut_end <= note.content_len) {
            const tail = note.content_buf[cut_end..note.content_len];
            std.mem.copyForwards(u8, note.content_buf[cut_start..], tail);
            note.content_len = @intCast(cut_start + tail.len);
            const trimmed = std.mem.trimEnd(u8, note.content_buf[0..note.content_len], " \n\r\t");
            note.content_len = @intCast(trimmed.len);
        }
    }

    // `grow` so the quote fills the column beside the rule: hugging its content,
    // the body wrapped at about half the width the shot gives it.
    return quoteAside(ui, id, ui.column(.{ .grow = 1, .gap = 4 }, .{
        ui.row(.{ .gap = 10, .cross = .start }, .{
            avatarDisc(ui, note, avatar_size),
            identityBlock(ui, note),
            ui.paragraph(.{ .style = .{ .foreground = p.text_faint_alt } }, &.{.{ .text = note.time(), .scale = meta_scale }}),
        }),
        // Four lines of the quoted note, and no more: a quote is an aside, and
        // its height has to be known where the outer row is priced.
        if (q.text_len > 0) quoteBody(ui, note) else ui.spacer(0),
        // What the card cannot draw, said rather than left blank.
        if (q.image_host_len > 0) quoteMediaChip(ui, q.image_host_buf[0..q.image_host_len]) else ui.spacer(0),
        // A quote of a quote stops here. One more body would be a third voice in
        // a row, so the second hop is a pill that says where it goes.
        if (q.has_quote_of) quotingPill(ui, q.quote_of) else ui.spacer(0),
    }));
}

/// The quoted note's own words, four lines of them. Labelled, because the one
/// thing worth asserting about it is how WIDE it is: hugging its content instead
/// of filling the column beside the rule, it wrapped at about half the width the
/// shot gives it and read as a column of its own rather than an aside.
fn quoteBody(ui: *AppUi, note: *const Note) AppUi.Node {
    const spans = clampSpansToLines(ui, contentSpans(ui, note.content()), quote_body_lines);
    var node = textParaAt(ui, spans, nested_body_scale, theme.palette.text_secondary_alt);
    node.widget.semantics.label = "Quoted note body";
    return node;
}

/// A picture the quote card cannot draw, named instead of left out.
///
/// Not a control: pressing the CARD already opens the quoted note, and that is
/// where the picture renders with a registry slot of its own. A second press
/// target here would offer a shorter way to the same place and take a slot to
/// do it.
fn quoteMediaChip(ui: *AppUi, host: []const u8) AppUi.Node {
    const p = theme.palette;
    return ui.row(.{ .gap = 0 }, .{
        ui.el(.panel, .{
            .height = quote_pill_height,
            .padding = 0.01,
            .style = .{ .background = p.surface_pill, .border = p.border_pill, .radius = 999, .stroke_width = 1 },
        }, .{
            ui.row(.{ .cross = .center, .gap = 0 }, .{
                hgap(ui, 8),
                ui.appIcon(.{ .width = 12, .height = 12, .style = .{ .foreground = p.text_faint_alt } }, "image"),
                hgap(ui, 6),
                ui.paragraph(
                    .{ .style = .{ .foreground = p.text_faint_alt } },
                    &.{.{ .text = ui.fmt("Picture from {s}", .{host}), .scale = meta_scale }},
                ),
                hgap(ui, 8),
            }),
        }),
        ui.spacer(1),
    });
}

/// 11g's pill: where the quoted note's own quote goes, one hop, as a line rather
/// than a third nested body. Pressing it walks that hop.
fn quotingPill(ui: *AppUi, id: [32]u8) AppUi.Node {
    const p = theme.palette;
    const tint = avatarTint(quotingPillAuthor(id));
    const hexdigits = "0123456789abcdef";
    const author = quotingPillAuthor(id);
    return ui.row(.{ .gap = 0 }, .{
        ui.el(.list_item, .{
            .padding = 0.01,
            .height = quote_pill_height,
            .cross = .center,
            .on_press = Msg{ .open_event = id },
            .style = .{ .background = p.surface_pill, .border = p.border_pill, .radius = 999, .stroke_width = 1 },
            .semantics = .{ .role = .button, .label = "Quoted note inside it", .focusable = true },
        }, .{
            hgap(ui, 4),
            ui.avatar(.{
                .image = 0,
                .width = 14,
                .height = 14,
                .style = .{ .background = tint.bg, .border = tint.border, .foreground = tint.glyph, .stroke_width = 1 },
            }, ui.fmt("{c}{c}", .{ hexdigits[author[0] >> 4], hexdigits[author[0] & 0x0f] })),
            hgap(ui, 6),
            // ONE line, elided at the tail: the pill says where the hop goes and
            // begins what it says, and a long note may not push the row wider.
            // `wrap = false` is what makes the single-line overflow policy apply.
            ui.text(.{
                .width = quote_pill_label_width,
                .wrap = false,
                .overflow = .ellipsis,
                .size = .sm,
                .style = .{ .foreground = p.text_muted_alt },
            }, quotingPillLabel(ui, id)),
            hgap(ui, 9),
        }),
        // Hugging its content, so the pill is a pill and not a bar.
        ui.spacer(1),
    });
}

/// `text` with its line breaks folded into spaces, for a control that is one
/// line by construction. A widget that measures single-line still PAINTS the
/// newlines its text carries, so an unfolded label draws its second line over
/// whatever is under the row.
fn oneLine(ui: *AppUi, text: []const u8) []const u8 {
    if (std.mem.indexOfAny(u8, text, "\r\n") == null) return text;
    const out = ui.arena.alloc(u8, text.len) catch return text;
    var n: usize = 0;
    var last_space = false;
    for (text) |c| {
        const space = c == '\n' or c == '\r' or c == ' ' or c == '\t';
        if (space) {
            if (last_space or n == 0) continue;
            out[n] = ' ';
        } else {
            out[n] = c;
        }
        last_space = space;
        n += 1;
    }
    return out[0..n];
}

pub fn oneLineForTest(ui: *AppUi, text: []const u8) []const u8 {
    return oneLine(ui, text);
}

/// Whose note the pill walks to, once that note is resolved; a zero key until
/// then, which tints the disc neutrally rather than guessing.
fn quotingPillAuthor(id: [32]u8) [32]u8 {
    const e = quoteFor(id) orelse return [_]u8{0} ** 32;
    if (e.state != .loaded) return [_]u8{0} ** 32;
    return e.pubkey;
}

/// What the pill says. It names the author once that note has arrived, and says
/// plainly that it is still coming until then, rather than showing a name it
/// does not have.
fn quotingPillLabel(ui: *AppUi, id: [32]u8) []const u8 {
    // Re-queued when the entry is gone, the same way the aside itself does it:
    // the pill's target is asked for once, when the note holding it is filled,
    // and the 64-entry cache can evict it while the pill is still on screen. Then
    // nothing would ever ask again, because the note holding it is loaded and a
    // loaded entry is never revisited.
    const e = quoteFor(id) orelse {
        wantQuote(id);
        return "Quoting a note";
    };
    return switch (e.state) {
        // Whose note, and the start of what it says: the shot's own pill reads
        // "Quoting @edith · Shipping it: the feed renders…", so the reader can
        // tell whether the hop is worth taking before taking it.
        .loaded => ui.fmt("Quoting {s} · {s}", .{ quotePillHandle(ui, e.pubkey), oneLine(ui, e.text_buf[0..e.text_len]) }),
        .missing => "Quotes a note no relay has",
        else => "Quoting a note",
    };
}

/// The handle for a pill: `@name` when the author has one, else their display
/// name, else a short npub. The pill is one line, so it names them the shortest
/// true way rather than the fullest.
fn quotePillHandle(ui: *AppUi, pubkey: [32]u8) []const u8 {
    if (lookupProfile(pubkey)) |pr| {
        if (pr.nip05_len > 0) {
            const nip05 = pr.nip05();
            if (std.mem.indexOfScalar(u8, nip05, '@')) |at| {
                const local = nip05[0..at];
                const shown = if (std.mem.eql(u8, local, "_")) nip05[at + 1 ..] else local;
                if (shown.len > 0) return std.fmt.allocPrint(ui.arena, "@{s}", .{shown}) catch "";
            }
        }
        const user = pr.username();
        if (user.len > 0) return std.fmt.allocPrint(ui.arena, "@{s}", .{user}) catch "";
    }
    return quoteAuthorName(ui, pubkey);
}

/// The rule down the left of a quote, and whatever sits beside it. The redesign
/// replaces the bordered card with this: a card inside a row reads as a second
/// surface competing with the note, where the rule reads as an aside, which is
/// what a quote is.
///
/// `id` non-null makes the block open that note. The rule brightening on hover
/// (11f) is not expressible: hover is a background wash on one widget, and a
/// wash here would be a state the design does not draw.
fn quoteAside(ui: *AppUi, id: ?[32]u8, body: AppUi.Node) AppUi.Node {
    const p = theme.palette;
    // `grow` on the row, so the aside is as wide as the column it sits in. Its
    // parent is a column, where grow is the vertical axis for the WRAPPER but the
    // width for this row's own sizing: without it the row took its intrinsic
    // width, which for a long quote measured three times the window.
    const inner = ui.row(.{ .grow = 1, .gap = 0 }, .{
        // The rule takes the row's height from the default cross STRETCH. It must
        // not `grow`: grow in a row is the horizontal axis, so a growing 2px rule
        // and the growing content column split the width between them, and the
        // quote wrapped at half the space the shot gives it. The thread's rail
        // uses the same construct correctly because it sits in a COLUMN, where
        // grow is the axis it wants.
        ui.separator(.{ .width = 2, .style = .{ .foreground = p.divider_reply, .background = p.divider_reply } }),
        hgap(ui, 12),
        ui.column(.{ .grow = 1, .gap = 0 }, .{
            vgap(ui, 2),
            body,
            vgap(ui, 2),
        }),
    });
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 5),
        if (id) |event_id|
            // A plain row: it paints nothing, which is right, because 11f gives a
            // quote no hover state (its rule brightening is not expressible) and
            // a wash here would invent one. It also MEASURES, which `list_item`
            // does not: the width-aware measurer has no case for that kind, so a
            // wrapping quote body would measure one line tall and draw over the
            // verbs under it.
            ui.row(.{
                .grow = 1,
                // By EVENT id, read straight from the store: a quoted note is in
                // neither the feed nor the open thread's replies.
                .on_press = Msg{ .open_event = event_id },
                .semantics = .{ .role = .button, .label = "Quoted note" },
            }, .{inner})
        else
            inner,
    });
}

/// Seeds a resolved quote, so a test can render the aside and price it without a
/// relay. Returns the id it was filed under.
pub fn seedQuoteForTest(id: [32]u8, pubkey: [32]u8, created_at: i64, text: []const u8) void {
    wantQuote(id);
    const e = quoteFor(id) orelse return;
    e.pubkey = pubkey;
    e.created_at = created_at;
    const keep = @min(text.len, e.text_buf.len);
    @memcpy(e.text_buf[0..keep], text[0..keep]);
    e.text_len = @intCast(keep);
    e.state = .loaded;
}

pub fn wantQuoteForTest(id: [32]u8) void {
    wantQuote(id);
}

/// The real fill path, over a real store: what a quote card knows about the
/// note it draws comes from here and nowhere else.
pub fn refreshQuotesForTest(store: *nostr.store.Store) void {
    refreshQuotes(store);
}

pub fn requeueMissingQuotesForTest() void {
    requeueMissingQuotes();
}

pub fn requestWantedQuotesForTest() void {
    requestWantedQuotes();
}

pub fn advanceQuoteRoundForTest(rounds: u64) void {
    g_quote_round +%= rounds;
}

pub fn rearmWantedQuotesForTest() void {
    rearmWantedQuotes();
}

pub fn quoteBackoffRoundsForTest(attempts: u8) u64 {
    return quoteBackoffRounds(attempts);
}

pub fn quoteForTest(id: [32]u8) ?*QuoteEntry {
    return quoteFor(id);
}

pub fn dropQuoteForTest(id: [32]u8) void {
    for (&g_quotes) |*q| {
        if (q.used and std.mem.eql(u8, &q.id, &id)) q.* = .{};
    }
}

pub fn quotingPillLabelForTest(ui: *AppUi, id: [32]u8) []const u8 {
    return quotingPillLabel(ui, id);
}

pub fn quoteBodyLinesForTest(e: *const QuoteEntry) f32 {
    return quoteBodyLines(e);
}

pub fn noteRowEstimateForTest(note: *const Note, chrome: f32) f32 {
    return noteRowEstimate(note, chrome);
}

/// The quoted author's display name (from the profile cache) or a short npub.
fn quoteAuthorName(ui: *AppUi, pubkey: [32]u8) []const u8 {
    if (lookupProfile(pubkey)) |pr| {
        if (pr.name_len > 0) return pr.name();
    }
    const buf = ui.arena.alloc(u8, 24) catch return "";
    return abbreviateNpub(buf, pubkey);
}

/// The focal note's timestamp in full: the time and the date, since a note being
/// read deserves to say exactly when it was written rather than "3h".
fn absoluteNoteTime(arena: std.mem.Allocator, created_at: i64) []const u8 {
    // LOCAL time, because a reader reads a clock, not an offset. Neither the SDK
    // nor the standard library carries a timezone database, so the offset comes
    // from libc, which knows the zone and the daylight rule. Off macOS (the
    // portability build) there is no such call wired, and the line says UTC
    // rather than pretending.
    const shifted = created_at + localOffsetSeconds(created_at);
    const secs: u64 = @intCast(@max(shifted, 0));
    const days = secs / 86_400;
    const day_secs = secs % 86_400;
    const hour24 = day_secs / 3600;
    const minute = (day_secs % 3600) / 60;
    const pm = hour24 >= 12;
    const hour12 = if (hour24 % 12 == 0) 12 else hour24 % 12;
    // Civil date from the Unix epoch, by Howard Hinnant's algorithm: exact, and
    // no dependency on a timezone database the app does not carry.
    const z = @as(i64, @intCast(days)) + 719_468;
    const era = @divFloor(z, 146_097);
    const doe = z - era * 146_097;
    const yoe = @divTrunc(doe - @divTrunc(doe, 1460) + @divTrunc(doe, 36_524) - @divTrunc(doe, 146_096), 365);
    const y = yoe + era * 400;
    const doy = doe - (365 * yoe + @divTrunc(yoe, 4) - @divTrunc(yoe, 100));
    const mp = @divTrunc(5 * doy + 2, 153);
    const d = doy - @divTrunc(153 * mp + 2, 5) + 1;
    const m = if (mp < 10) mp + 3 else mp - 9;
    const year = if (m <= 2) y + 1 else y;
    const months = [_][]const u8{ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
    const month_name = months[@intCast(@min(@max(m - 1, 0), 11))];
    return std.fmt.allocPrint(arena, "{d}:{d:0>2} {s}{s} · {s} {d}, {d}", .{
        hour12, minute, if (pm) "PM" else "AM", if (comptime builtin.os.tag == .macos) "" else " UTC", month_name, d, year,
    }) catch "";
}

/// Seconds to add to a Unix timestamp to get local wall-clock time, from libc's
/// own zone handling (so daylight saving is right, and right for the DATE in
/// question rather than for today).
fn localOffsetSeconds(unix_seconds: i64) i64 {
    if (comptime builtin.os.tag != .macos) return 0;
    var tm: c_tm = std.mem.zeroes(c_tm);
    const t: i64 = unix_seconds;
    if (localtime_r(&t, &tm) == null) return 0;
    return tm.tm_gmtoff;
}

/// The fields of `struct tm` this needs, in libc's order. Only `tm_gmtoff` is
/// read; the rest are here so the struct is the right size for libc to fill.
const c_tm = extern struct {
    tm_sec: c_int = 0,
    tm_min: c_int = 0,
    tm_hour: c_int = 0,
    tm_mday: c_int = 0,
    tm_mon: c_int = 0,
    tm_year: c_int = 0,
    tm_wday: c_int = 0,
    tm_yday: c_int = 0,
    tm_isdst: c_int = 0,
    tm_gmtoff: c_long = 0,
    tm_zone: ?[*:0]const u8 = null,
};

extern "c" fn localtime_r(timer: *const i64, result: *c_tm) ?*c_tm;

/// Who a reply is addressed to: the handle when one is known, else the display
/// name, which is all a profile without a nip05 offers.
fn replyTarget(ui: *AppUi, note: *const Note) []const u8 {
    const handle = note.handle(ui.arena);
    return if (handle.len > 0) handle else note.author();
}

/// One phrase or the other, by count. English, and the only two shapes the
/// chrome needs.
fn pluralize(ui: *AppUi, n: usize, comptime one: []const u8, comptime many: []const u8) []const u8 {
    return if (n == 1) ui.fmt(one, .{n}) else ui.fmt(many, .{n});
}

/// How many relays are connected right now.
fn liveRelayCount() usize {
    var n: usize = 0;
    for (0..relaySlots()) |i| {
        // A dormant seat is not a live relay whatever its last status said.
        if (relayAt(i) == null) continue;
        const state: Conn = @enumFromInt(g_relay_status[i].load(.monotonic));
        // Quiet counts. It holds a socket, its subscriptions are still open on
        // the relay, and a note published now goes out on it.
        if (connHolds(state)) n += 1;
    }
    return n;
}

/// The quoted note's relative timestamp, computed for the frame.
fn quoteTime(ui: *AppUi, created_at: i64) []const u8 {
    const dt = nowSeconds() - created_at;
    if (dt < 60) return "now";
    if (dt < 3600) return ui.fmt("{d}m", .{@divTrunc(dt, 60)});
    if (dt < 86_400) return ui.fmt("{d}h", .{@divTrunc(dt, 3600)});
    if (dt < 604_800) return ui.fmt("{d}d", .{@divTrunc(dt, 86_400)});
    return ui.fmt("{d}w", .{@divTrunc(dt, 604_800)});
}

/// One feed note: a bare row on the window, no card. Avatar column, then an
/// identity line (name, and the time hung to the right), the body, any image,
/// and the engagement row. The content is a fixed reading column centered in
/// the window, with a hairline under each row as the only separation. Keyed by
/// the note id so the list diff holds scroll position across reconciles.
fn noteCard(ui: *AppUi, model: *const Model, note: *const Note) AppUi.Node {
    var node = ui.row(.{ .grow = 1, .main = .center }, .{
        ui.column(.{ .width = feed_column_width }, .{
            // A `list_item`, because that is the kind the renderer washes on
            // hover, and the row wash is the redesign's one hover state. It has
            // to be given an explicit WIDTH: a list_item sizes to its content,
            // and without one the body paragraph ran to its unwrapped width and
            // overflowed the reading column. Its children lay out on the
            // horizontal axis, so the single column below is what holds the
            // vertical stack. The inner controls (like, reply, links, the
            // picture) keep their own presses as the deeper hit targets.
            //
            // Every inset is stated once, on the axis that owns it: this column
            // carries the redesign's 12 above and 14 below, the row inside it
            // carries 16 on each side and the 12 between disc and text, and the
            // content column's own steps are 5, 8 and 10. A uniform `padding`
            // cannot express any of that, and a `gap` on the row would also apply
            // around each inset box, which is what threw the first attempt 12px
            // off the reading rail.
            ui.el(.data_row, .{ .width = feed_column_width, .padding = 0.01, .on_press = Msg{ .open_thread = note.id }, .context_menu = noteContextItems(ui, note, false), .semantics = .{ .label = "Open thread" } }, .{ui.column(.{ .gap = 0, .width = feed_column_width }, .{
                vgap(ui, row_pad_top),
                ui.row(.{ .gap = 0, .cross = .start }, .{
                    hgap(ui, row_pad_side),
                    noteAvatar(ui, note),
                    hgap(ui, avatar_to_text_gap),
                    // DEFINITE, not `grow`. `grow` hands out SPARE space and
                    // never takes any back, so a column whose widest child is
                    // already wider than the row keeps that width and pushes
                    // everything to its right off the card. This is the same
                    // width the picture and the link card already use, and it
                    // is what makes an ellipsis on anything inside possible:
                    // an ellipsis needs a box to be too small for.
                    ui.column(.{ .gap = 0, .width = picture_column_width }, .{
                        // The identity header: the name over the handle in a box
                        // the avatar's height, with the time hung top-right.
                        ui.row(.{ .gap = 6, .cross = .start }, .{
                            identityBlock(ui, note),
                            // Right-aligned in a stated column, so it ends at
                            // the card's edge whatever it says. Left to hug its
                            // text it began at a fixed x (the identity block
                            // beside it is a definite width) and stopped
                            // wherever it ran out, leaving a ragged gap after
                            // "6m via Damus" that grew as the string got
                            // shorter.
                            ui.paragraph(
                                .{
                                    .width = time_column_width,
                                    .text_alignment = .end,
                                    .style = .{ .foreground = theme.palette.text_faint_alt },
                                },
                                timeSpans(ui, note, meta_scale),
                            ),
                        }),
                        vgap(ui, 5),
                        noteBody(ui, note, true),
                        // The picture. The space is reserved at the picture's own
                        // shape whether or not it has loaded, so the feed never
                        // shifts as images arrive.
                        if (note.hasImage()) vgap(ui, 8) else ui.spacer(0),
                        if (note.hasImage()) notePicture(ui, note) else ui.spacer(0),
                        if (note.hasLink()) linkCard(ui, note) else ui.spacer(0),
                        vgap(ui, 10),
                        engagementRow(ui, model, note),
                    }),
                    hgap(ui, row_pad_side),
                }),
                vgap(ui, row_pad_bottom),
            })}),
            // The only separation between rows: a hairline. The `.separator`
            // element paints a real line (an empty column with a background does
            // not, which is why every divider was invisible before).
            ui.separator(.{ .width = feed_column_width, .style = .{ .foreground = theme.palette.divider_row, .background = theme.palette.divider_row } }),
        }),
    });
    // The note id is masked non-negative at build time, so this cast is safe.
    node.key = .{ .int = @intCast(note.id) };
    return node;
}

/// Splits rendered note text into styled runs so a note reads like a note.
/// Every interactive run takes the identity violet, because each one names a
/// person or something they wrote: an `@mention` (one weight up, the way a name
/// is set), a `#hashtag`, a bare `nostr:` event reference, and a web link, which
/// alone carries a pressable payload. The design shows no hashtag, so their
/// color follows the redesign's stated rule ("violet for identity and content")
/// rather than a shot.
/// Every span's text is a subslice of the note's own content, so nothing is
/// copied. A paragraph holds at most 32 runs, so a link-heavy note keeps its
/// tail as one plain run rather than losing it.
pub fn contentSpans(ui: *AppUi, text: []const u8) []const canvas.TextSpan {
    const max_spans = 32;
    if (text.len == 0) return &.{};
    const spans = ui.arena.alloc(canvas.TextSpan, max_spans) catch return &.{};

    var n: usize = 0;
    var i: usize = 0;
    var plain_start: usize = 0;
    while (i < text.len) {
        const is_url = std.mem.startsWith(u8, text[i..], "https://") or std.mem.startsWith(u8, text[i..], "http://");
        const is_mention = text[i] == '@' and i + 1 < text.len and !std.ascii.isWhitespace(text[i + 1]);
        // A hashtag is `#` + word characters at a word boundary, so `C#` and a
        // URL fragment (`…#section`) are left as plain text.
        const is_hashtag = text[i] == '#' and i + 1 < text.len and isHashtagChar(text[i + 1]) and (i == 0 or !std.ascii.isAlphanumeric(text[i - 1]));
        // A `nostr:nevent`/`note`/`naddr` reference (the first is usually lifted
        // into a quote card upstream; a second one, or one inside a quoted body,
        // still reads as a reference here). No link: there is no in-app target
        // for a bare extra ref yet.
        const is_eventref = isEventRefStart(text, i);
        if (!is_url and !is_mention and !is_hashtag and !is_eventref) {
            i += 1;
            continue;
        }
        // Two slots for this run plus the trailing plain run.
        if (n + 3 > max_spans) break;
        if (i > plain_start) {
            spans[n] = .{ .text = text[plain_start..i] };
            n += 1;
        }
        var j = i;
        if (is_hashtag) {
            // Just the tag word: trailing punctuation (`#nostr!`) stays plain.
            j = i + 1;
            while (j < text.len and isHashtagChar(text[j])) j += 1;
        } else {
            while (j < text.len and !std.ascii.isWhitespace(text[j])) j += 1;
        }
        const run = text[i..j];
        // Content color is the identity violet, reached through the `info`
        // token (a span names a token field, not a Color). A @mention
        // additionally sits one weight up, the way a name does.
        //
        // The redesign draws an in-text URL colored and NOTHING more, but the
        // renderer underlines every span that carries a link payload
        // (`span.underline or is_link`), so a clickable URL is always underlined.
        // Clickability wins over the hairline: `underline` stays unset here to
        // say what we asked for, and the extra rule is the renderer's.
        spans[n] = if (is_url)
            .{ .text = run, .color = .info, .link = run }
        else if (is_mention)
            .{ .text = run, .color = .info, .weight = .medium }
        else
            .{ .text = run, .color = .info };
        n += 1;
        i = j;
        plain_start = j;
    }
    if (plain_start < text.len and n < max_spans) {
        spans[n] = .{ .text = text[plain_start..] };
        n += 1;
    }
    return spans[0..n];
}

/// The height a note's picture occupies, whether or not it has loaded. Taken
/// from the note's declared `imeta` shape, else the shape it turned out to be
/// last time it was decoded, else a gentle default. Clamped so one very tall
/// image cannot take over the feed.
pub fn pictureHeight(note: *const Note) f32 {
    // The picture spans the reading column, which is what 11o draws, and takes
    // exactly the height the note's own `imeta` implies at that width. It was
    // based on a 300px box and clamped at 320px, so a tall picture was reserved
    // at a height it never drew and the row shifted when the bytes arrived, which
    // is the whole thing a declared shape exists to prevent.
    //
    // The cap is on the ASPECT, not the pixels: a very tall picture is contained
    // rather than allowed to take over the feed, and contained at a height the
    // estimate can state exactly.
    return picture_column_width * @min(pictureAspect(note), picture_max_aspect);
}

/// The shape to draw at: what the note declares, else what this picture measured
/// when it was last decoded (remembered past its slot, so an evicted picture does
/// not shrink and shift the feed), else a landscape guess.
fn pictureAspect(note: *const Note) f32 {
    if (note.image_aspect > 0) return note.image_aspect;
    return recalledAspect(note.id) orelse picture_default_aspect;
}

/// A note's picture: the image once registered, or a placeholder holding the
/// exact same space while it loads. Drawn with `contain` at its own aspect, so
/// it is never stretched and stays undistorted as the window resizes. Pressing
/// it opens the viewer.
fn notePicture(ui: *AppUi, note: *const Note) AppUi.Node {
    const height = pictureHeight(note);
    const image_id = note.media_id();
    // Previews off and this one not asked for: a quiet line saying what is there
    // and what pressing it costs, not a box of reserved space for a picture that
    // is not coming.
    if (!g_media_previews and !isMediaAsked(note.id) and image_id == 0) return pictureAskChip(ui, note);
    // Asked for and not had. The striped box below means "still coming", and it
    // meant that for a 404 too: the view only asked whether the picture was
    // LOADED, so every state that is not loaded drew the same waiting frame and
    // a picture that was never going to arrive waited forever.
    if (image_id == 0 and mediaFailed(note.id)) return pictureFailedBox(ui, note, height);
    if (image_id == 0) {
        // The same box the picture will fill, striped: reserved space, not an
        // empty frame, and not a skeleton either, which reads as a row of text
        // still loading rather than as a photograph.
        return pictureBox(ui, note, height, pictureBlur(ui, note, height));
    }
    var picture = ui.image(.{ .image = image_id, .grow = 1 });
    // `ui.image` leaves the fit at `stretch`, which distorts the picture into
    // whatever box it is given (and worse as the window resizes).
    picture.widget.image_fit = .contain;
    // The picture sits in a pressable row rather than carrying the press
    // itself: an image is a leaf, and the hit target belongs on a container.
    // `quiet_hover` keeps it from washing over on hover like a list row, and the
    // box is sized to the drawn picture so only the picture itself is pressable,
    // not the empty width beside a narrow one.
    //
    // The link role is what puts the pointing hand over it: the engine follows
    // the native convention, where the hand marks a link and ordinary controls
    // keep the arrow, so this is the one role that advertises "clickable".
    return pictureBox(ui, note, height, picture);
}

/// A quoted note on its way: the SHAPE of the card that will replace it.
///
/// It used to be one 34px bar, which says "something is loading" and nothing
/// about what. A quote card is a face, a name and a line or two of somebody
/// else's words, so the wait looks like that: a disc, a short bar where the
/// name goes, and two body lines, the second one short the way a last line is.
/// Same height as the bar it replaces, so nothing about the row's pricing moves.
fn quoteSkeleton(ui: *AppUi) AppUi.Node {
    const p = theme.palette;
    return ui.row(.{ .gap = 0, .cross = .start }, .{
        ui.el(.skeleton, .{ .width = 18, .height = 18, .style = .{ .radius = 999, .background = p.surface_inset } }, .{}),
        hgap(ui, 8),
        ui.column(.{ .grow = 1, .gap = 0 }, .{
            ui.el(.skeleton, .{ .width = 96, .height = 8, .style = .{ .radius = 4, .background = p.surface_inset } }, .{}),
            vgap(ui, 7),
            ui.el(.skeleton, .{ .height = 7, .style = .{ .radius = 4, .background = p.surface_inset } }, .{}),
            vgap(ui, 5),
            ui.el(.skeleton, .{ .width = 148, .height = 7, .style = .{ .radius = 4, .background = p.surface_inset } }, .{}),
        }),
    });
}

/// A picture that could not be had, in the space it would have taken.
///
/// The same box at the same height, because the row is priced for it and a
/// picture failing must not make the feed jump. What is IN it is different: the
/// picture glyph, a plain sentence, and the host it came from, because "this
/// one host is not answering" is the useful half and it is often the whole
/// story. Pressing opens the original, which is the one thing left that might
/// work, rather than an expanded view of nothing.
fn pictureFailedBox(ui: *AppUi, note: *const Note, height: f32) AppUi.Node {
    const p = theme.palette;
    const host = urlHost(note.imageUrl());
    return ui.el(.data_row, .{
        .width = pictureWidth(note),
        .height = height,
        .padding = 0,
        .style = .{ .quiet_hover = true, .background = p.surface_inset, .radius = picture_radius, .border = p.border_hairline, .stroke_width = 1 },
        .on_press = Msg{ .open_url = note.imageUrl() },
        .semantics = .{ .role = .link, .label = "This picture could not be loaded, press to open the original", .focusable = true },
    }, .{
        ui.column(.{ .grow = 1, .main = .center, .cross = .center, .gap = 0 }, .{
            ui.appIcon(.{ .width = 18, .height = 18, .style = .{ .foreground = p.text_dim } }, "image"),
            vgap(ui, 8),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_muted } },
                &.{.{ .text = "This picture would not load", .scale = mono_hint_scale }},
            ),
            if (host.len > 0) vgap(ui, 4) else ui.spacer(0),
            if (host.len > 0)
                ui.paragraph(
                    .{ .style = .{ .foreground = p.text_dim } },
                    &.{.{ .text = ui.fmt("{s} · press to open it", .{host}), .monospace = true, .scale = mono_meta_scale }},
                )
            else
                ui.spacer(0),
        }),
    });
}

/// The picture's frame: the reading column at the declared height, with the
/// radius and hairline 11o gives it, whatever is inside it, and the chips laid
/// over the corners. A `data_row` lays children out horizontally, so the chips
/// ride a stack: there is no way to place a child at a point.
fn pictureBox(ui: *AppUi, note: *const Note, height: f32, content: AppUi.Node) AppUi.Node {
    return ui.el(.data_row, .{
        .width = pictureWidth(note),
        .height = height,
        .padding = 0,
        .style = .{ .quiet_hover = true, .radius = picture_radius, .border = theme.palette.border_hairline, .stroke_width = 1 },
        .on_press = Msg{ .expand_image = note.id },
        .semantics = .{ .role = .link, .label = "Attached image, press to enlarge", .focusable = true },
    }, .{
        ui.stack(.{ .grow = 1 }, .{
            content,
            pictureChips(ui, note),
        }),
    });
}

/// What a picture is while previews are off: one quiet chip naming it and its
/// weight, which loads that one when pressed. The weight is the note's own claim
/// and may be missing, in which case the chip does not invent one.
fn pictureAskChip(ui: *AppUi, note: *const Note) AppUi.Node {
    const p = theme.palette;
    const label = if (note.image_bytes > 0)
        ui.fmt("image · {s} · load", .{byteSize(ui.arena, note.image_bytes)})
    else
        "image · load";
    return ui.row(.{ .gap = 0 }, .{
        ui.el(.list_item, .{
            .padding = 0.01,
            .height = picture_ask_height,
            .cross = .center,
            .on_press = Msg{ .load_image = note.id },
            .style = .{ .background = p.surface_inset, .border = p.border_chip, .radius = 6, .stroke_width = 1 },
            .semantics = .{ .role = .button, .label = "Load this image", .focusable = true },
        }, .{
            hgap(ui, 9),
            ui.paragraph(
                .{ .style = .{ .foreground = p.text_muted } },
                &.{.{ .text = label, .monospace = true, .scale = mono_meta_scale }},
            ),
            hgap(ui, 9),
        }),
        ui.spacer(1),
    });
}

/// A decoded blurhash: the low-frequency colour of a picture, which is all a
/// blurhash carries. Drawn as a grid of flat cells rather than an image, because
/// every one of the runtime's sixteen image slots is already spent on faces and
/// photographs, and a placeholder must not evict the thing it is standing in for.
pub const Blur = struct {
    /// Row-major, `cells_x * cells_y` colours.
    cells: [blur_cells_x * blur_cells_y]canvas.Color = undefined,
    ok: bool = false,
};

/// Deliberately coarse. Every cell is a widget node, and a view past 1024 nodes
/// is REFUSED WHOLE, not degraded: six loading pictures at 8x6 came to 797 nodes
/// on their own, and a wider window mounting nine rows crossed the ceiling and
/// blanked the feed. A blurhash carries only low frequencies, so 4x3 shows what
/// it has for 19 nodes instead of 55.
const blur_cells_x = 4;
const blur_cells_y = 3;

/// blurhash's own alphabet.
fn base83(c: u8) ?f32 {
    const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz#$%*+,-.:;=?@[]^_{|}~";
    const i = std.mem.indexOfScalar(u8, alphabet, c) orelse return null;
    return @floatFromInt(i);
}

fn base83Value(hash: []const u8, from: usize, len: usize) ?f32 {
    if (from + len > hash.len) return null;
    var value: f32 = 0;
    for (hash[from .. from + len]) |c| {
        const digit = base83(c) orelse return null;
        value = value * 83 + digit;
    }
    return value;
}

/// sRGB companding, the two halves of it the format needs.
fn srgbToLinear(v: f32) f32 {
    return if (v <= 0.04045) v / 12.92 else std.math.pow(f32, (v + 0.055) / 1.055, 2.4);
}

fn linearToSrgb(v: f32) f32 {
    const c = std.math.clamp(v, 0, 1);
    return if (c <= 0.0031308) c * 12.92 else 1.055 * std.math.pow(f32, c, 1.0 / 2.4) - 0.055;
}

/// Decodes a blurhash into a small grid of colours. The format is a handful of
/// cosine components; sampling them at each cell's centre is the same sum the
/// reference decoder runs per pixel, at the resolution the eye gets from a
/// placeholder anyway.
pub fn decodeBlurhash(hash: []const u8) Blur {
    var out: Blur = .{};
    if (hash.len < 6) return out;
    const size_flag = base83Value(hash, 0, 1) orelse return out;
    const comp_x: usize = @intFromFloat(@mod(size_flag, 9) + 1);
    const comp_y: usize = @intFromFloat(@floor(size_flag / 9) + 1);
    if (hash.len != 4 + 2 * comp_x * comp_y) return out;

    const quant_max = base83Value(hash, 1, 1) orelse return out;
    const max_ac = (quant_max + 1) / 166.0;

    // The DC term is the average colour, straight sRGB bytes.
    const dc = base83Value(hash, 2, 4) orelse return out;
    const dc_int: u32 = @intFromFloat(dc);
    var colours: [9 * 9][3]f32 = undefined;
    colours[0] = .{
        srgbToLinear(@as(f32, @floatFromInt((dc_int >> 16) & 255)) / 255.0),
        srgbToLinear(@as(f32, @floatFromInt((dc_int >> 8) & 255)) / 255.0),
        srgbToLinear(@as(f32, @floatFromInt(dc_int & 255)) / 255.0),
    };

    var i: usize = 1;
    while (i < comp_x * comp_y) : (i += 1) {
        const ac = base83Value(hash, 4 + i * 2, 2) orelse return out;
        const ac_int: u32 = @intFromFloat(ac);
        colours[i] = .{
            signPow((@as(f32, @floatFromInt(ac_int / (19 * 19))) - 9) / 9, 2.0) * max_ac,
            signPow((@as(f32, @floatFromInt((ac_int / 19) % 19)) - 9) / 9, 2.0) * max_ac,
            signPow((@as(f32, @floatFromInt(ac_int % 19)) - 9) / 9, 2.0) * max_ac,
        };
    }

    for (0..blur_cells_y) |cy| {
        for (0..blur_cells_x) |cx| {
            // The centre of the cell, in the 0..1 the basis is defined over.
            const x = (@as(f32, @floatFromInt(cx)) + 0.5) / @as(f32, @floatFromInt(blur_cells_x));
            const y = (@as(f32, @floatFromInt(cy)) + 0.5) / @as(f32, @floatFromInt(blur_cells_y));
            var r: f32 = 0;
            var g: f32 = 0;
            var b: f32 = 0;
            for (0..comp_y) |j| {
                for (0..comp_x) |k| {
                    const basis = @cos(std.math.pi * x * @as(f32, @floatFromInt(k))) *
                        @cos(std.math.pi * y * @as(f32, @floatFromInt(j)));
                    const c = colours[j * comp_x + k];
                    r += c[0] * basis;
                    g += c[1] * basis;
                    b += c[2] * basis;
                }
            }
            out.cells[cy * blur_cells_x + cx] = canvas.Color.rgba8(
                @intFromFloat(linearToSrgb(r) * 255 + 0.5),
                @intFromFloat(linearToSrgb(g) * 255 + 0.5),
                @intFromFloat(linearToSrgb(b) * 255 + 0.5),
                255,
            );
        }
    }
    out.ok = true;
    return out;
}

fn signPow(value: f32, exp: f32) f32 {
    const magnitude = std.math.pow(f32, @abs(value), exp);
    return if (value < 0) -magnitude else magnitude;
}

/// What a picture that has not arrived looks like: its own colours when the note
/// carries a blurhash, stripes when it does not.
fn pictureBlur(ui: *AppUi, note: *const Note, height: f32) AppUi.Node {
    const hash = note.imageBlurhash();
    if (hash.len == 0) return pictureStripes(ui, height);
    const blur = decodeBlurhash(hash);
    if (!blur.ok) return pictureStripes(ui, height);

    // Flat cells, not an image: the runtime has sixteen image slots and they are
    // all spent on faces and photographs, so a placeholder must not evict the
    // thing it stands in for. A blurhash carries only low frequencies anyway,
    // which is what a grid of them shows.
    const rows = ui.arena.alloc(AppUi.Node, blur_cells_y) catch return pictureStripes(ui, height);
    for (rows, 0..) |*row, y| {
        const cells = ui.arena.alloc(AppUi.Node, blur_cells_x) catch return pictureStripes(ui, height);
        for (cells, 0..) |*cell, x| {
            cell.* = ui.el(.panel, .{
                .grow = 1,
                .padding = 0.01,
                .style = .{ .background = blur.cells[y * blur_cells_x + x], .radius = 0, .stroke_width = 0 },
            }, .{});
        }
        row.* = ui.row(.{ .grow = 1, .gap = 0 }, .{cells});
    }
    return ui.column(.{ .grow = 1, .gap = 0 }, .{rows});
}

/// The fill under a picture that has not arrived. The shot draws 45 degree
/// stripes; the canvas has no gradients at the widget level and no rotation, so
/// they run flat, which keeps what the stripes are FOR (this is a photograph
/// arriving, not a paragraph) without pretending to an angle.
fn pictureStripes(ui: *AppUi, height: f32) AppUi.Node {
    const p = theme.palette;
    // The band count is capped, so the BANDS grow instead: a stated height that
    // stopped at the cap left the bottom of a tall box as bare window inside its
    // own border.
    const count: usize = @min(@max(1, @as(usize, @intFromFloat(@ceil(height / 14)))), picture_stripe_cap);
    const bands = ui.arena.alloc(AppUi.Node, count) catch return ui.spacer(0);
    for (bands, 0..) |*b, i| {
        b.* = ui.el(.panel, .{
            .grow = 1,
            .padding = 0.01,
            .style = .{ .background = if (i % 2 == 0) p.surface_stripe_a else p.surface_stripe_b, .radius = 0, .stroke_width = 0 },
        }, .{});
    }
    return ui.column(.{ .grow = 1, .gap = 0 }, .{bands});
}

/// 11o's link preview: what the page on the other end says it is. One per note,
/// under the body, and the URL stays in the text as well, because the card is a
/// courtesy and the address is the fact.
///
/// The tile is a letter, never a favicon: a favicon would want one of the
/// sixteen image slots the whole runtime has, and those belong to faces and
/// photographs.
/// How wide the text beside a link preview's tile may be.
///
/// Spelled out from the parts rather than left to `grow`, because the row's
/// other children are all fixed: the gap before the tile, the tile, the gap
/// after it, and the gap at the end. What is left is what the title and the
/// description have to live inside, and a test measures the result rather than
/// trusting this arithmetic.
const link_card_tile_size: f32 = 30;
const link_card_text_width: f32 = picture_column_width - 12 - link_card_tile_size - 10 - 12;
/// And how many characters of description fit that width at its scale. A length
/// rather than a width because the engine will not elide this one: see the call.
const link_desc_max: usize = 78;

fn linkCard(ui: *AppUi, note: *const Note) AppUi.Node {
    const p = theme.palette;
    const url = note.linkUrl();
    const entry = linkFor(url);
    // Nothing to show until the page has answered. No skeleton: a card that
    // might never come is worse than a link that reads as a link.
    if (entry == null or entry.?.state != .loaded) return ui.spacer(0);
    const link = entry.?;
    const initial = std.ascii.toUpper(if (link.domain().len > 0) link.domain()[0] else '?');

    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, 3),
        ui.el(.list_item, .{
            .width = picture_column_width,
            .padding = 0.01,
            // The URL slice lives in the note, which lives in the model, and the
            // opener copies it before it runs.
            .on_press = Msg{ .open_url = url },
            .style = .{ .background = p.surface_link_card, .border = p.border_chip_alt, .radius = 10, .stroke_width = 1 },
            .semantics = .{ .role = .link, .label = "Open link", .focusable = true },
        }, .{
            hgap(ui, 12),
            ui.column(.{ .gap = 0 }, .{
                vgap(ui, 10),
                ui.el(.panel, .{
                    .width = 30,
                    .height = 30,
                    .padding = 0.01,
                    .style = .{ .background = p.surface_link_tile, .radius = 7, .stroke_width = 0 },
                }, .{
                    ui.column(.{ .width = 30, .height = 30, .main = .center, .cross = .center }, .{
                        ui.paragraph(
                            .{ .style = .{ .foreground = p.text_muted } },
                            &.{.{ .text = ui.fmt("{c}", .{initial}), .monospace = true, .weight = .medium, .scale = meta_scale }},
                        ),
                    }),
                }),
            }),
            hgap(ui, 10),
            // A STATED width, not `grow`. `grow` hands out SPARE space and never
            // takes any back, so a child whose natural size already exceeds the
            // row has nothing to grow into and is simply left at its natural
            // size. A page title and description with `wrap = false` are as wide
            // as the sentence, which for a link preview is far wider than the
            // card, so the row overflowed the card, the card overflowed the
            // column, and the description ran off the right of the window. The
            // ellipsis never fired because ellipsis needs a box to be too small
            // FOR, and the leaf was never given one.
            ui.column(.{ .width = link_card_text_width, .gap = 0 }, .{
                vgap(ui, 10),
                ui.paragraph(
                    .{ .width = link_card_text_width, .style = .{ .foreground = p.text_dim } },
                    &.{.{ .text = link.domain(), .monospace = true, .scale = mono_chip_scale }},
                ),
                vgap(ui, 2),
                // The width is on THESE, not only on the column around them.
                // That is what the first attempt got wrong: it stated the
                // width one level up and asserted the geometry against the
                // card, which passed, while a title still ran to the window's
                // right edge and was cut off there with no ellipsis. A text
                // leaf with no wrap measures as one line at its natural width
                // whatever its ancestors say, so `.overflow = .ellipsis` had
                // nothing to elide against. Safe to state here because nothing
                // sits beside these in the column: a definite width on a leaf
                // with a neighbour would push the neighbour away instead.
                ui.text(.{
                    .width = link_card_text_width,
                    .wrap = false,
                    .overflow = .ellipsis,
                    .size = .sm,
                    .style = .{ .foreground = p.text_link_title },
                }, link.title()),
                if (link.description().len == 0) ui.spacer(0) else vgap(ui, 2),
                // Shortened here rather than left to `.overflow`, unlike the
                // title directly above it. The engine's ellipsis works on a
                // plain `ui.text` and not on a paragraph built from SPANS: the
                // title came back correctly elided while this line, with the
                // same width and the same overflow setting, ran flat off the
                // end of the card. The span is kept because it carries the
                // smaller scale a description wants.
                if (link.description().len == 0) ui.spacer(0) else ui.paragraph(.{
                    .width = link_card_text_width,
                    .wrap = false,
                    .overflow = .ellipsis,
                    .style = .{ .foreground = p.text_muted },
                }, &.{.{ .text = elide(ui, link.description(), link_desc_max), .scale = mono_row_scale }}),
                vgap(ui, 10),
            }),
            hgap(ui, 12),
        }),
    });
}

/// The two chips 11o lays over a picture: its declared size at the top right and
/// its alt text at the bottom left. Both read at rest, because hover cannot
/// restyle or reveal a child.
fn pictureChips(ui: *AppUi, note: *const Note) AppUi.Node {
    const dims = note.imageChipLabel(ui.arena);
    const alt = note.image_has_alt;
    if (dims.len == 0 and !alt) return ui.spacer(0);
    return ui.column(.{ .grow = 1, .gap = 0 }, .{
        ui.row(.{ .grow = 1, .main = .end, .cross = .start, .gap = 0 }, .{
            if (dims.len == 0) ui.spacer(0) else pictureChip(ui, dims, false),
            hgap(ui, picture_chip_inset),
        }),
        ui.row(.{ .gap = 0 }, .{
            hgap(ui, picture_chip_inset),
            if (!alt) ui.spacer(0) else pictureChip(ui, "ALT", true),
            ui.spacer(1),
        }),
        vgap(ui, picture_chip_inset),
    });
}

/// One chip over a picture: mono, small, on a scrim dark enough to read against
/// any photograph.
fn pictureChip(ui: *AppUi, label: []const u8, emphatic: bool) AppUi.Node {
    const p = theme.palette;
    return ui.column(.{ .gap = 0 }, .{
        vgap(ui, picture_chip_inset),
        ui.el(.panel, .{
            .padding = 0.01,
            .height = picture_chip_height,
            .style = .{ .background = p.scrim_chip, .border = p.border_chip_alt, .radius = 5, .stroke_width = 1 },
        }, .{
            ui.row(.{ .cross = .center, .gap = 0 }, .{
                hgap(ui, 7),
                // A scaled span, because the 10px mono register has no size enum
                // rung. No stated width: 11o draws both of these as pills hugging
                // their text, and a fixed one made "ALT" a 194px bar across the
                // bottom of every described picture. Both labels are bounded by
                // construction, the longest being `1600×900 · 240 KB`.
                ui.paragraph(.{
                    .wrap = false,
                    .style = .{ .foreground = if (emphatic) p.text_secondary else p.text_muted_alt },
                }, &.{.{
                    .text = label,
                    .monospace = true,
                    .weight = if (emphatic) .medium else .regular,
                    .scale = mono_chip_scale,
                }}),
                hgap(ui, 7),
            }),
        }),
    });
}

/// How wide the drawn picture is: its own shape at the reserved height, never
/// wider than the card. `contain` centres a narrow picture in its box, so
/// matching the box to the picture is what keeps the press on the picture.
pub fn pictureWidth(note: *const Note) f32 {
    // The TRUE aspect, not the capped one: a picture taller than the cap is
    // drawn `contain`ed at the reserved height, so its drawn width is what the
    // shape says, and the box must be that or the gutters either side are bare
    // window inside the border, and pressable.
    const aspect = pictureAspect(note);
    if (aspect <= 0) return picture_column_width;
    // The box IS the picture: a portrait photo drawn `contain`ed inside a
    // column-wide box would leave bare window either side, inside the border,
    // and all of it pressable. Matching the box to what is drawn keeps the press
    // on the picture and the chips on its corners.
    return @min(picture_column_width, pictureHeight(note) / aspect);
}

const PlazaApp = native_sdk.UiApp(Model, Msg);

/// The keyboard, as the shell delivers it: a shortcut declared in the manifest
/// arrives here by id and becomes an ordinary message, so a key does exactly
/// what the control it stands for does, and never a second implementation of it.
///
/// What each one means depends on what is open, and that is decided in `update`
/// where the model is, not here: this only names the intent.
fn onCommand(name: []const u8) ?Msg {
    if (std.mem.eql(u8, name, "new-note")) return .open_compose;
    if (std.mem.eql(u8, name, "settings")) return .open_settings;
    return null;
}
const Effects = PlazaApp.Effects;
/// The effects type, exported so tests can exercise the fx-free slot paths.
pub const EffectsForTest = Effects;

/// Boot: seed the feed once, register whatever images are already cached, then
/// arm the repeating timers.
pub fn boot(model: *Model, fx: *Effects) void {
    model.refresh(nowSeconds());
    // What was written but not sent when the app last closed, back in the
    // composer where it was left.
    var draft_buf: [note_content_cap]u8 = undefined;
    const stashed = loadDraft(&draft_buf);
    if (stashed.len > 0) model.draft_buffer = @TypeOf(model.draft_buffer).init(stashed);
    // What was owed when the app last closed. Read before the first frame, so a
    // note written offline yesterday is visible as owed rather than lost, and
    // offered again as soon as a relay answers. Whose queue that is comes from
    // the session that was just restored; a guest starts with empty slots.
    syncOutboxOwner();
    // Local-first, all the way to the first frame: cached avatars and pictures
    // are registered here, so a returning user gets faces WITH the notes rather
    // than a tick later. Only what is on disk resolves now; the rest is fetched
    // from the first tick onward.
    wantProfilesAhead(model);
    assignAvatarSlots(fx, model);
    scanAvatarFetches(fx);
    scanMediaFetches(fx, model);
    warmAhead(fx, model);
    scanLinkFetches(fx, model);
    scanNip05Fetches(fx);
    fx.startTimer(.{
        .key = refresh_timer_key,
        .interval_ms = refresh_interval_ms,
        .mode = .repeating,
        .on_fire = Effects.timerMsg(.tick),
    });
    // One timer drives every playing GIF; a timer each would exhaust the table.
    fx.startTimer(.{
        .key = animation_timer_key,
        .interval_ms = animation_interval_ms,
        .mode = .repeating,
        .on_fire = Effects.timerMsg(.animate),
    });
    // Bring up the isolated signer; the tick health-checks it until it answers.
    spawnHelper(fx);
    // Background metadata fetching on its own cadence, off the view refresh.
    fx.startTimer(.{
        .key = profile_timer_key,
        .interval_ms = profile_interval_ms,
        .mode = .repeating,
        .on_fire = Effects.timerMsg(.profiles),
    });
}

pub fn update(model: *Model, msg: Msg, fx: *Effects) void {
    switch (msg) {
        .tick => |t| {
            if (t.outcome == .fired) {
                const now = nowSeconds();
                model.refresh(now);
                // Keep the open thread's replies current: late replies appear and
                // relative times stay fresh, the same cadence as the feed.
                //
                // Only when the store actually moved, which is the guard the
                // feed rebuild ten lines up has always had and these two never
                // did. Unconditional, they were a full `store.query`, a
                // `collectThreadIds` closure walk that queries again per level,
                // and a re-parse of every reply into a fresh `Note` — once a
                // second, on the render thread, for as long as a thread or a
                // profile stayed open, almost always to produce exactly the
                // list that was already on screen.
                //
                // The open paths call these directly, so a thread still fills
                // the moment it is opened; this only skips the repeat.
                const level_count = if (g_store) |st| (st.eventCount() catch g_last_level_count) else g_last_level_count;
                if (level_count != g_last_level_count) {
                    g_last_level_count = level_count;
                    model.refreshThreadNotes(now);
                    // And the open person's notes, for the same reason and with
                    // the same consequence if it is missed: without this the
                    // backfill this screen fires never appears, and the quiet
                    // line saying they have written nothing stays up over a
                    // store that has since filled with their notes.
                    model.refreshProfileNotes(now);
                }
                // Relative times were a side effect of the rebuild, so they have
                // to be kept up now that the rebuild is conditional. "2m" going
                // stale is exactly the sort of thing a guard like this breaks
                // quietly.
                for (model.thread_notes[0..model.thread_notes_len]) |*note| note.setTime(now);
                if (model.viewing_profile != null) {
                    model.thread_loading = model.thread_notes_len == 0 and
                        g_thread_done_seq.load(.acquire) < model.thread_seq;
                }
                // Anything still owed goes back out whenever a relay is up: this
                // is the drain, and it is idempotent, since an entry already in
                // flight is skipped.
                // The Edit profile sheet waits on a real answer before it lets
                // anything be published over a profile it has not read.
                if (model.editing_profile and model.profile_stage == .fetching) {
                    const gpa = std.heap.page_allocator;
                    if (ownProfileJson(gpa)) |own| {
                        defer freeOwnProfile(gpa, own);
                        // A profile arriving a few seconds late must not replace
                        // the sentence the reader is in the middle of typing,
                        // which is what the second argument protects. It used to
                        // be all or nothing: one typed character skipped the
                        // seeding of ALL THREE fields, and the flip to `.have`
                        // below ran anyway, so Save lit up over two empty fields
                        // that had never been read and the merge deleted them.
                        if (!model.profile_seeded) seedProfileFields(model, own.json, true);
                        model.profile_stage = .have;
                    } else if (ownProfileAnswered()) {
                        model.profile_stage = .absent;
                    } else if (now - model.profile_asked_at > own_profile_wait_s) {
                        model.profile_stage = .unread;
                    }
                }
                // A logout's reset that never reached the daemon, re-sent. Left
                // undone, the daemon keeps the key the reader just left and the
                // health-check would sign them back into it.
                if (g_logout_reset_due) {
                    g_logout_reset_due = false;
                    helperReset(fx);
                }
                // Their published relay list, taken on this thread so no ingest
                // thread ever swaps the pool out from under the others.
                _ = adoptRelayList();
                flushRelayList(fx, now);
                // At most one write a second, and only when something changed.
                if (inboxNeedsSave()) saveInbox();
                // Before anything reads or walks the queue: the slots belong
                // to whoever is signed in now, and a sign-in or a logout since
                // the last tick means they change hands here.
                syncOutboxOwner();
                if (liveRelayCount() > 0) drainOutbox(std.heap.page_allocator);
                sweepOutbox(now);
                // At most one write a second, and only when something changed.
                if (g_draft_dirty) {
                    g_draft_dirty = false;
                    saveDraft(model.draft());
                }
                const counts = outboxCounts();
                model.outbox_pending = counts.trying;
                model.outbox_stuck = counts.stuck;
                // The banner is about a note that was dropped, and a note can
                // still be dropped by the paths that reach `ingestAndPublish`
                // without going through the composer. It used to latch for the
                // life of the process: the queue drained, later posts landed,
                // and the status bar went on saying a note could not be queued
                // for the rest of the run. It retires when there is room again,
                // which is the condition it was reporting the absence of.
                if (g_outbox_overflow.load(.monotonic) and outboxHasRoom()) {
                    g_outbox_overflow.store(false, .monotonic);
                }
                model.outbox_overflowed = g_outbox_overflow.load(.monotonic);
                if (g_outbox_rev.load(.monotonic) != g_outbox_saved_rev) {
                    g_outbox_saved_rev = g_outbox_rev.load(.monotonic);
                    saveOutbox();
                }
                // Start any pending image fetches (needs effects, so here, not
                // in refresh). The feed reads loaded images at render time.
                wantProfilesAhead(model);
                assignAvatarSlots(fx, model);
                scanAvatarFetches(fx);
                scanBannerFetch(fx, model);
                scanMediaFetches(fx, model);
                warmAhead(fx, model);
                scanLinkFetches(fx, model);
                scanNip05Fetches(fx);
                // Complete a like a guest reached for, now that they have signed
                // in and the feed above has rebuilt.
                drivePendingIntent(model, fx);
                // Retire timed-out or refused signer requests, restoring a lost
                // draft to the composer (this thread owns it).
                if (g_signer_kind == .remote) scanPendingRemote(model);
                // The same question for the built-in signer, which had no
                // answer to it at all: a sign that failed simply ended.
                if (g_signer_kind == .helper) scanHelperSign(model);
                // Health-check the signer daemon until the loopback IPC answers,
                // then fire any queued key setup.
                pollHelper(fx);
                driveHelperSetup(fx);
                // A toast lives a few seconds, then the tick retires it.
                if (model.toast_until != 0 and nowSeconds() >= model.toast_until) {
                    model.toast_until = 0;
                    model.toast_len = 0;
                }
            }
        },
        .animate => |t| {
            if (t.outcome == .fired) advanceAnimations(fx, model);
        },
        .profiles => |t| {
            if (t.outcome == .fired) {
                // Quotes still re-arm on a round counter. Profiles no longer
                // need to: each pubkey carries its own last-tried stamp and
                // backs off on its own, so asking every tick costs nothing for
                // the ones that are waiting and retries the rest when due.
                g_profile_round +%= 1;
                g_quote_round +%= 1;
                if (g_quote_round % quote_rearm_rounds == 0) rearmWantedQuotes();
                requestWantedProfiles();
                requestWantedQuotes();
            }
        },
        .helper_exited => |e| {
            if (e.reason != .exited) std.debug.print("plaza: [helper] exited\n", .{});
        },
        .notary_exited => |e| handleNotaryExited(model, e),
        .helper_pubkey => |response| {
            handleHelperPubkey(model, response);
            // A queued setup fires the moment the daemon is reachable.
            driveHelperSetup(fx);
        },
        .helper_setup => |response| handleHelperSetup(model, response),
        .helper_signed => |response| handleHelperSigned(response),
        .avatar_fetched => |response| handleAvatarFetched(fx, response),
        .avatar_warmed => |response| handleAvatarWarmed(response),
        .media_warmed => |response| handleMediaWarmed(response),
        .banner_fetched => |response| handleBannerFetched(fx, response),
        .draft_edit => |edit| {
            model.draft_buffer.apply(edit);
            // A new query is a new question, so a dismissal only covers the one
            // the reader dismissed. Without this, putting the picker away once
            // would put it away for the rest of the note.
            model.mention_dismissed = false;
            // Marked, not written: the tick flushes it. Saving on CLOSE alone
            // was the wrong half, because the state a writer is in when the
            // machine sleeps or the app is killed is the sheet OPEN.
            g_draft_dirty = true;
            // The user is composing again: retire a stale "signer didn't respond".
            g_remote_sign_notice.store(false, .release);
            g_helper_sign_notice.store(false, .release);
        },
        .post => {
            // Every precondition, before anything is signed or said. A message
            // is reachable from more places than the button that names it: the
            // field's own submit chord, a future menu entry, a key. Publishing
            // is not something to do on a model that was not showing a
            // composer, and a draft restored from disk must never leave the
            // machine without the reader seeing it in one.
            if (!model.composing or model.stage != .ready or model.is_guest()) return;
            if (model.draft_empty()) return;
            // Nothing after this runs unless the note actually went to a
            // signer. It used to run regardless: the composer emptied, the draft
            // file was deleted and the toast said "Posted" for a sign that had
            // been refused before it left the process.
            if (!submitPost(model, fx)) {
                setToast(model, if (!outboxHasRoom())
                    "Still trying to send your last notes. This one is kept here."
                else
                    "Notary is busy for a moment. Try again.");
                return;
            }
            // The slot is emptied the moment its contents go to a signer.
            // Leaving it would restore an already-published note into the next
            // launch's composer, one keystroke from being posted twice.
            saveDraft("");
            // Posting closes the sheet; the note is already local and will
            // appear on the next tick.
            model.composing = false;
            setToast(model, if (g_signer_kind == .remote) "Sent to your signer" else "Posted");
            // The first local post is the calm moment to suggest a backup.
            if (g_signer_kind == .local and !model.backup_nudge_dismissed)
                model.backup_nudge = true;
        },
        .open_compose => {
            // The keyboard reaches past the sheet: this is a declared shortcut,
            // so the shell delivers it whatever is on screen, and `appView` draws
            // the sheet ABOVE the composer. Without this the composer arms itself
            // unseen and appears unbidden the moment the sheet is dismissed.
            model.notifications_open = false;
            // The gate is on press, not on sight: a guest reaching for the
            // composer is exactly first intent, so the sheet rises and
            // remembers what was reached for.
            if (model.is_guest()) {
                model.joining = true;
                model.pending = .post;
            } else model.composing = true;
        },
        .open_person => |pk| {
            model.notifications_return = model.notifications_open;
            model.notifications_open = false;
            enterProfile(model, pk);
        },
        .follow_person => |direction| {
            if (model.is_guest()) {
                // REMEMBERED, not merely gated. This press used to open the sheet
                // and forget what it was for, so signing in landed the reader on
                // the feed still not following the person they had just asked to
                // follow, with nothing to say why.
                if (model.viewing_profile) |who| model.pending = .{ .follow = who };
                model.joining = true;
                return;
            }
            const who = model.viewing_profile orelse return;
            sayFollowWrite(model, writeFollow(fx, who, direction == 1), direction == 1);
        },
        .profile_tab => |which| model.profile_tab = if (which == 1) .replies else .notes,
        .toggle_notifications => {
            model.notifications_open = !model.notifications_open;
            // Opening IS reading: the reader is looking at them. The mark moves
            // to the newest item held, never to the wall clock, so a backfill
            // arriving later with older stamps is not born already read.
            if (model.notifications_open) {
                inboxMarkAllRead();
                markInboxDirty();
            }
        },
        .close_notifications => model.notifications_open = false,
        .notifications_tab => |which| {
            model.notifications_everyone = which == 1;
            // The other tab holds a different set, so page four of this one is
            // not page four of that one.
        },
        .notifications_read_all => {
            inboxMarkAllRead();
            markInboxDirty();
        },
        .toggle_note_menu => |id| model.note_menu = if (model.note_menu == id) 0 else id,
        .close_note_menu => model.note_menu = 0,
        .follow_author => |direction| {
            model.note_menu = 0;
            // A guest reaching for Follow is first intent, the same as reaching
            // for the composer: the sheet rises rather than the press failing.
            if (direction == 0 or model.is_guest()) {
                if (model.is_guest() and model.viewing_thread != 0)
                    model.pending = .{ .follow = model.thread_root.pubkey };
                model.joining = true;
                return;
            }
            // The menu hangs off the focal note, so its author is the thread's
            // root: the person whose note is being read.
            if (model.viewing_thread == 0) return;
            sayFollowWrite(model, writeFollow(fx, model.thread_root.pubkey, direction == 1), direction == 1);
        },
        .open_profile_edit => openProfileEdit(model),
        .close_profile_edit => model.editing_profile = false,
        .profile_name_edit => |edit| model.profile_name_buffer.apply(edit),
        .profile_about_edit => |edit| model.profile_about_buffer.apply(edit),
        .profile_picture_edit => |edit| model.profile_picture_buffer.apply(edit),
        .profile_save => saveProfile(model, fx),
        .profile_retry => {
            forgetOwnProfileAnswer();
            model.profile_asked_at = nowSeconds();
            model.profile_stage = .fetching;
            startOwnProfileFetch();
        },
        .relay_cycle => |i| {
            cycleRelay(i);
            // The ack bits name slots, and this slot's direction just changed.
            relayListEdited();
        },
        .relay_remove => |i| {
            removeRelay(i);
            // They just did what the full-pool message asked for.
            model.relay_full = false;
            relayListEdited();
        },
        .relay_edit => |edit| {
            model.relay_buffer.apply(edit);
            // Typing is the reader answering what the field asked. Keeping the
            // old complaint under a field they are fixing makes the app look
            // like it is not watching.
            model.relay_error = false;
            model.relay_full = false;
        },
        .relay_add => {
            const typed = std.mem.trim(u8, model.relay_buffer.text(), " \t\r\n");
            // Both flags answer THIS press. A full-pool message left standing
            // after the reader removed a relay would hide the real reason the
            // next add failed.
            model.relay_full = false;
            model.relay_error = false;
            if (!isRelayUrl(typed)) {
                model.relay_error = true;
                return;
            }
            if (addRelay(typed, true, true) == null) {
                model.relay_full = true;
                return;
            }
            model.relay_full = false;
            model.relay_buffer.clear();
            relayListEdited();
        },
        .relay_suggest => |i| {
            var buf: [96]u8 = undefined;
            const url = relaySuggestionCopy(i, &buf) orelse return;
            if (addRelay(url, true, true) == null) {
                // A silent press is the app refusing without saying so.
                model.relay_full = true;
                return;
            }
            model.relay_full = false;
            forgetRelaySuggestion(i);
            relayListEdited();
        },
        .insert_mention => |pubkey| insertMention(model, pubkey),
        .close_compose => {
            model.composing = false;
            // Closing the sheet stashes what is in it. The words survived a
            // closed sheet already; this is what carries them past a quit.
            saveDraft(model.draft());
        },
        .open_join => model.joining = true,
        .close_join => {
            model.joining = false;
            model.bunker_mode = false;
            // Dismissing the sheet is an answer: they chose not to sign in, so
            // the verb they reached for is dropped rather than lying in wait to
            // fire at some later sign-in they made for another reason.
            model.pending = .none;
        },
        .join_create => {
            model.joining = false;
            // `g_identity_minted_here` is NOT set here. It says the key provably
            // has no history, which is what lets a contact list be published
            // without reading one back first, and at this point there is no key
            // at all: the ceremony can still fail, and the reader can still go
            // and import an account with eight hundred follows instead. It is set
            // when a mint is CONFIRMED, in handleNotaryExited and in
            // handleHelperSetup's create branch.
            beginCreate(fx);
        },
        .open_notary_import => {
            // Key material never enters Plaza: the Notary window takes the
            // paste and hands it to the daemon; Plaza signs in when the key
            // appears (handleHelperPubkey). If the window binary is missing,
            // fall back to the in-Plaza field rather than a dead button.
            model.joining = false;
            // Whatever a previous press left behind, this is not a mint. Both
            // flags are the reader's answer to "where does this key come from",
            // and they just answered differently.
            g_ceremony = .none;
            g_ceremony_adopted = false;
            g_identity_minted_here = false;
            // And a sign-out earlier in this run latched adopt-on-appear off.
            //
            // The ceremony happens in the other process and exits 0 for an
            // import, so `handleNotaryExited` classifies it as "not a mint" and
            // signs nobody in: the health check is the ONLY thing that carries
            // the result back. A latch left over swallows the whole import. The
            // key lands in the daemon, the poll refuses it once a second, and the
            // reader sits in guest mode until they quit and reopen.
            //
            // `beginCreate` drops it for the create ceremony with a comment
            // saying it has to do by hand what `queueHelperSetup` would have
            // done. This is the third spawn site and it never got that line, so
            // "Create your identity" after a sign-out worked and "Bring your key"
            // was dead, which is what made it look intermittent: the latch is
            // false at launch, so it only bites on a run where something signed
            // out first. The pubkey latch below it is what still keeps the key
            // that just LEFT from walking back in.
            g_logged_out = false;
            if (ceremonyCanTakeKey()) spawnNotaryWindow(fx, .import_key) else model.stage = .onboarding;
        },
        .keep_browsing => {
            model.stage = .ready;
            model.pending = .none;
        },
        .open_bunker => {
            model.bunker_mode = true;
            g_ceremony = .none;
            g_ceremony_adopted = false;
            g_identity_minted_here = false;
        },
        .close_bunker => {
            model.bunker_mode = false;
            model.login_buffer.clear();
            g_login_error.store(@intFromEnum(LoginError.none), .release);
        },
        .dismiss_guest_strip => model.guest_strip_dismissed = true,
        // A trigger toggles its own menu and replaces any other, so the chrome
        // never shows two floating surfaces at once.
        .toggle_menu => |which| model.menu = if (model.menu == which) .none else which,
        .close_menu => model.menu = .none,
        .toggle_relays_paused => {
            model.relays_paused = !model.relays_paused;
            setRelaysPaused(model.relays_paused);
            model.menu = .none;
        },
        // The feed's own list holds the scroll, and there is no API to set an
        // offset, so "newest" is the reconcile that puts the newest note back at
        // the top: the same thing the tick does, asked for on purpose.
        // There is no API to set a list's scroll offset, so this cannot scroll
        // the feed. What it CAN do is make sure nothing is stale before the
        // reader looks: force the next tick to rebuild from the store.
        .show_more_replies => model.thread_page[model.currentLevel()] += 1,
        .toggle_outside_replies => {
            const level = model.currentLevel();
            model.thread_outside_open[level] = !model.thread_outside_open[level];
        },
        .jump_to_newest => {
            invalidateFeed();
            model.menu = .none;
        },
        .copy_nevent => |id| {
            model.note_menu = 0;
            const note = model.noteById(id) orelse return;
            var scratch: [1024]u8 = undefined;
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            const addr = nostr.nip19.encodeNevent(fba.allocator(), note.event_id, &.{}, note.pubkey, 1) catch return;
            fx.writeClipboard(.{ .key = copy_nevent_key, .text = addr });
            setToast(model, "Address copied");
        },
        // njump renders any nostr event as a web page, which is how a note is
        // shared with someone who is not on nostr yet.
        .open_web => |id| {
            model.note_menu = 0;
            const note = model.noteById(id) orelse return;
            var scratch: [1024]u8 = undefined;
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            const addr = nostr.nip19.encodeNevent(fba.allocator(), note.event_id, &.{}, note.pubkey, 1) catch return;
            var url_buf: [256]u8 = undefined;
            const url = std.fmt.bufPrint(&url_buf, "https://njump.me/{s}", .{addr}) catch return;
            openExternally(fx, url);
        },
        // Quoting is composing with the note already referenced. The composer
        // opens holding a `nostr:nevent…`, which `contentTags` turns into the
        // `q` tag at publish, so the reference in the text and the tag on the
        // event can never disagree: they are derived from the same bytes.
        .quote_note => |id| {
            model.note_menu = 0;
            if (model.is_guest()) {
                model.joining = true;
                model.pending = .post;
                return;
            }
            const note = model.noteById(id) orelse return;
            var scratch: [1024]u8 = undefined;
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            const addr = nostr.nip19.encodeNevent(fba.allocator(), note.event_id, &.{}, note.pubkey, 1) catch return;
            // Appended, not overwritten. Something half-written in the composer
            // is the reader's, and a quote arriving on top of it would be this
            // app deciding their draft was worth less than its own convenience.
            const existing = model.draft_buffer.text();
            var line: [256]u8 = undefined;
            const sep: []const u8 = if (existing.len == 0) "" else "\n\n";
            const text = std.fmt.bufPrint(&line, "{s}{s}nostr:{s}", .{ existing, sep, addr }) catch return;
            model.draft_buffer.set(text);
            model.viewing_thread = 0;
            model.composing = true;
        },
        // Switching somebody off, or back on. Keyed on the pubkey rather than a
        // position, because the list is re-derived from the text every frame
        // and an index would point at somebody else the moment the draft is
        // edited above it.
        .toggle_mention_off => |pubkey| {
            for (model.mentions_off[0..model.mentions_off_len], 0..) |off, i| {
                if (!std.mem.eql(u8, &off, &pubkey)) continue;
                model.mentions_off[i] = model.mentions_off[model.mentions_off_len - 1];
                model.mentions_off_len -= 1;
                return;
            }
            if (model.mentions_off_len < model.mentions_off.len) {
                model.mentions_off[model.mentions_off_len] = pubkey;
                model.mentions_off_len += 1;
            }
        },
        .close_mentions => model.mention_dismissed = true,
        .copy_note_text => |id| {
            model.note_menu = 0;
            // The words as the note wrote them, not as the feed renders them:
            // a paste that came back with `@name` where the author typed a
            // `nostr:` reference is not the note, it is a screenshot of one.
            const note = model.noteById(id) orelse return;
            fx.writeClipboard(.{ .key = copy_note_text_key, .text = note.content() });
            setToast(model, "Copied");
        },
        .open_settings_logout => {
            model.menu = .none;
            model.logout_pending = true;
            update(model, .open_settings, fx);
        },
        .name_edit => |edit| model.name_buffer.apply(edit),
        .name_save => {
            model.naming = false;
            // Nothing typed means nothing to publish. Writing an empty kind:0
            // would replace whatever profile the key already has with a blank
            // one, which is the replaceable-event footgun in miniature.
            if (model.name_empty()) {
                replayPending(model);
                return;
            }
            publishName(model, fx);
            setToast(model, "Name set");
            replayPending(model);
        },
        .name_skip => {
            model.naming = false;
            // Skipping is a decision not to publish this name, so the text goes
            // with it. Kept, it came back in the sheet the next time the beat
            // armed, on a DIFFERENT key, where Enter alone would publish it: the
            // Done button is deliberately never disabled.
            model.name_buffer.clear();
            replayPending(model);
        },
        .backup_now => {
            model.backup_nudge = false;
            model.backup_nudge_dismissed = true;
            enterSettings(model);
        },
        .backup_later => {
            model.backup_nudge = false;
            model.backup_nudge_dismissed = true;
        },
        .create_identity => beginCreate(fx),
        .login_edit => |edit| model.login_buffer.apply(edit),
        .login_submit => {
            g_login_error.store(@intFromEnum(LoginError.none), .release);
            const raw = std.mem.trim(u8, model.login_buffer.text(), " \t\r\n");
            switch (classifyLogin(raw)) {
                // Import an existing key: it lands on disk (0600) as the local
                // identity. A bad nsec keeps us on onboarding with an error.
                .nsec => {
                    if (!importNsec(raw)) return;
                    persistSession();
                    // Tolerate an nsec pasted into the bunker step: close the
                    // sheet the same way the bunker success path does.
                    model.joining = false;
                    model.bunker_mode = false;
                    enterFeed(model);
                    replayPending(model);
                },
                // Pair with the external signer from the bunker URL; on success
                // the feed comes up and posts route through it. A bad URL keeps
                // us on onboarding with an error (see `login_status`).
                .bunker => {
                    if (!connectRemoteSigner(raw)) return;
                    persistSession();
                    // The connection is optimistic: land in the feed at once
                    // (the composer line shows reaching/connected), close the
                    // sheet, and reset the bunker step.
                    model.joining = false;
                    model.bunker_mode = false;
                    enterFeed(model);
                    replayPending(model);
                },
                .invalid => g_login_error.store(@intFromEnum(LoginError.format), .release),
            }
        },
        .open_settings => enterSettings(model),
        .proxy_edit => |edit| {
            model.proxy_buffer.apply(edit);
            model.proxy_saved = false;
        },
        .proxy_save => {
            setMediaProxy(model.proxy_buffer.text());
            saveSettings();
            model.proxy_saved = true;
            // Retry anything that failed to load under the previous setting.
            retryFailedImages();
        },
        .client_tag_toggle => {
            setClientTag(!clientTag());
            saveSettings();
        },
        .previews_toggle => {
            setMediaPreviews(!mediaPreviews());
            saveSettings();
            // Turning it back on should fill the feed in without a restart.
            if (mediaPreviews()) {
                retryFailedImages();
                scanAvatarFetches(fx);
                scanMediaFetches(fx, model);
                warmAhead(fx, model);
                scanLinkFetches(fx, model);
            }
        },
        .media_fetched => |response| handleMediaFetched(fx, response),
        .nip05_verified => |response| handleNip05Fetched(response),
        .link_fetched => |response| handleLinkFetched(response),
        .open_url => |url| openExternally(fx, url),
        .expand_image => |note_id| model.expanded_note = note_id,
        .load_image => |note_id| {
            askForMedia(note_id);
            scanMediaFetches(fx, model);
        },
        .close_image => model.expanded_note = null,
        .open_notary_window => spawnNotaryWindow(fx, .status),
        // Deliberately empty: see `Msg.absorb_press`. The press has already done
        // its work by the time it arrives here, which was to stop somewhere.
        .absorb_press => {},
        .like => |note_id| toggleLike(model, fx, note_id),
        .open_thread => |note_id| openThread(model, note_id),
        .open_event => |id| {
            // The sheet closes on the PRESS, before the navigation is attempted,
            // never on arrival. Every route out of here has an early return in
            // front of it (a store miss for a note nobody fetched, an identity
            // check for a person already on screen), and each one returns BEFORE
            // anything that could close the sheet. Closing on arrival therefore
            // left it up in exactly the cases where the reader has least idea why
            // nothing moved.
            model.notifications_return = model.notifications_open;
            model.notifications_open = false;
            openEvent(model, id);
        },
        .close_thread => {
            // A menu left open would reopen over whatever the reader lands on.
            model.note_menu = 0;
            closeThread(model);
        },
        .go_home => goHome(model),
        .reply_edit => |edit| model.reply_buffer.apply(edit),
        .reply_submit => {
            // The one verb that was gated nowhere: a guest could type a reply and
            // press send, and `publishReply` would reach for a signer that does
            // not exist and return, losing nothing but doing nothing and saying
            // nothing either.
            if (model.is_guest()) {
                if (model.viewing_thread != 0) model.pending = .{ .reply = model.viewing_thread };
                model.joining = true;
                return;
            }
            publishReply(model, fx);
        },
        .toggle_expand => |note_id| toggleExpanded(note_id),
        .feed_scrolled => |scroll| {
            model.feed_scroll = scroll;
            // Load what just came into view without waiting for the next tick:
            // hand avatar ids to the newly-visible authors, then their faces and
            // pictures.
            wantProfilesAhead(model);
            assignAvatarSlots(fx, model);
            scanAvatarFetches(fx);
            scanMediaFetches(fx, model);
            // The band beyond the new viewport, which is the whole point of
            // running this on a scroll rather than only on the tick.
            warmAhead(fx, model);
            scanLinkFetches(fx, model);
        },
        .load_older => {
            // One more page from the store, up to what the feed can hold.
            // No ceiling to stop at. The store answers with what it has, and
            // `notes_len` lands wherever that is; asking for more than exists
            // simply returns the same feed and the reader has reached the end
            // of what this app has been told about.
            const held = model.notes_len;
            model.feed_limit += feed_page;
            invalidateFeed();
            model.refresh(nowSeconds());
            // The store had no more to give, so ask the relays for what came
            // before the oldest note in hand. Store first, network second.
            if (model.notes_len == held and model.notes_len > 0 and !feedEndReached()) {
                fetchOlderNotes(model.notes[model.notes_len - 1].created_at - 1);
            }
        },
        .close_settings => {
            model.logout_pending = false;
            model.reveal_nsec = false;
            model.stage = .ready;
        },
        .toggle_nsec => model.reveal_nsec = !model.reveal_nsec,
        .copy_npub => {
            const pk = activePubkey() orelse return;
            var scratch: [1024]u8 = undefined;
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            const npub = nostr.nip19.encodeNpub(fba.allocator(), pk) catch return;
            fx.writeClipboard(.{ .key = copy_npub_key, .text = npub });
        },
        .copy_nsec => {
            if (g_signer_kind != .local) return;
            const kp = g_identity_kp orelse return;
            var scratch: [1024]u8 = undefined;
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            const nsec = nostr.nip19.encodeNsec(fba.allocator(), kp.secret_key) catch return;
            fx.writeClipboard(.{ .key = copy_nsec_key, .text = nsec });
        },
        .logout_request => model.logout_pending = true,
        .logout_cancel => model.logout_pending = false,
        .logout_confirm => performLogout(model, fx),
    }
}

/// Shows a small confirming toast for a few seconds (the tick retires it).
/// Says what a follow press did, when it did not do the obvious thing.
///
/// Silent on success, because the button moving IS the answer and a toast on
/// every press would be noise. Not silent on a refusal: `writeFollow` has four
/// of those, all reachable, and the reader used to get a button that stayed
/// where it was and no reason at all. The most ordinary one is pressing Follow
/// in the first seconds after opening the app, before this account's own list
/// has come back from the relays.
fn sayFollowWrite(model: *Model, outcome: FollowWrite, following: bool) void {
    switch (outcome) {
        .published => if (following) setToast(model, "Following"),
        // Nothing changed because nothing needed to. Saying so would be noise.
        .nothing_to_do => {},
        .signer_busy => setToast(model, "Your signer is busy. Try that again in a moment."),
        .no_list_yet => setToast(model, "Still fetching your follow list. Try again in a moment."),
        // The guard fired, which means the list this app was about to publish
        // was not the list it meant to. Saying "try again" would be wrong: the
        // right move is to leave it alone until the real list is back.
        .would_shrink => setToast(model, "That would have changed more than one name, so nothing was published."),
        .failed => setToast(model, "That did not save, and nothing was published."),
    }
}

fn setToast(model: *Model, text: []const u8) void {
    const n = @min(text.len, model.toast_buf.len);
    @memcpy(model.toast_buf[0..n], text[0..n]);
    model.toast_len = n;
    model.toast_until = nowSeconds() + 3;
}

/// The one door into Settings. Every field on the screen that edits a live
/// setting is seeded here, because an arm that sets `stage = .settings` on its
/// own leaves those fields EMPTY, and an empty field over a Save button is an
/// invitation to erase the setting it was supposed to show. The backup nudge did
/// exactly that to the media proxy.
fn enterSettings(model: *Model) void {
    model.menu = .none;
    // One sheet at a time: Settings is a sheet now, and the notifications sheet
    // is checked FIRST in the view, so leaving it open would open Settings into
    // a window that never shows it.
    model.notifications_open = false;
    model.proxy_buffer.set(mediaProxy());
    model.proxy_saved = false;
    model.editing_profile = false;
    model.stage = .settings;
}

/// What the Edit profile sheet knows about the profile it is editing.
///
/// The distinction that matters is `fetching` versus `absent`. "The store has no
/// kind:0 for me" means either that this account has never had a profile or that
/// nobody has answered yet, and those two look identical from here. Publishing
/// under the second reading REPLACES a real profile with whatever three fields
/// this app models, which is how somebody's lightning address disappears. So the
/// sheet asks every read relay first, and only calls it `absent` once they have
/// all answered.
pub const ProfileStage = enum { fetching, absent, unread, have, saving, sent, failed };

/// How long the sheet waits for a relay before saying it could not read the
/// profile. `relay.receive()` has no deadline, so a relay that accepts the
/// subscription and then says nothing would otherwise hold the round open for
/// the rest of the session.
const own_profile_wait_s: i64 = 12;

/// Which key in the profile object the sheet's one Name field stands for. NIP-01
/// has `name` (a handle) and `display_name` (a fuller name), and some clients
/// still write the legacy `displayName`. The sheet edits whichever one the
/// reader's profile actually uses.
pub const ProfileNameKey = enum { display_name, display_name_legacy, name };

/// WHO has been asked about, and whether a relay actually answered.
///
/// Two things a bool got wrong. It survived a sign-out, so the round run for one
/// account decided that the NEXT account had no profile, and Save then published
/// an empty object over a real one. And it was set even when every relay was
/// offline, unreachable or write-only, so "nobody answered" and "they answered,
/// you have no profile" were the same state. Both readings end in a wipe, so the
/// answer records the pubkey it is about and is only set when a relay reached
/// the end of its answer.
var g_own_profile_asked_for: ?[32]u8 = null;
/// And the same for the CONTACT list, where getting it wrong is worse: a write
/// made before hearing back replaces everyone this reader follows with a
/// handful of accounts the app chose for them.
var g_own_contacts_asked_for: ?[32]u8 = null;
var g_own_contacts_answered = std.atomic.Value(bool).init(false);

/// Whether a relay has told THIS account who they follow (including telling us
/// they follow nobody).
pub fn ownContactsAnswered() bool {
    const pk = activePubkey() orelse return false;
    lockOwnProfile();
    defer unlockOwnProfile();
    const asked = g_own_contacts_asked_for orelse return false;
    if (!std.mem.eql(u8, &asked, &pk)) return false;
    return g_own_contacts_answered.load(.acquire);
}

fn noteOwnContactsAnswered(pk: [32]u8) void {
    lockOwnProfile();
    defer unlockOwnProfile();
    g_own_contacts_asked_for = pk;
    g_own_contacts_answered.store(true, .release);
}

pub fn noteOwnContactsAnsweredForTest(pk: [32]u8) void {
    noteOwnContactsAnswered(pk);
}

// There was a `g_own_relays_answered` here, set by the first EOSE from any relay
// and read as permission to publish a kind:10002. It is GONE rather than merely
// unused: an inference that wrong, left sitting in the file under a reassuring
// name, is one grep away from becoming a gate again. `canWriteRelayList` is the
// rule now, and the reason is written there.

/// Forgets every conclusion about this account's own records. Called on any
/// identity change, so nothing decided about one account is read as a fact about
/// the next.
fn forgetOwnRecordAnswers() void {
    forgetOwnProfileAnswer();
    lockOwnProfile();
    defer unlockOwnProfile();
    g_own_contacts_asked_for = null;
    g_own_contacts_answered.store(false, .release);
    // And WHICH relays answered. Leaving these set would let the next account
    // inherit the previous one's answers and reach the write gate without any
    // relay having said a word about them.
    g_contacts_answered_by = [_]bool{false} ** max_relays;
}
var g_own_profile_asking = std.atomic.Value(bool).init(false);
/// Set by the worker when at least one relay ANSWERED (EOSE), paired with the
/// pubkey it asked about. Read on the UI thread through `ownProfileAnswered`.
var g_own_profile_answered = std.atomic.Value(bool).init(false);
var g_own_profile_lock = std.atomic.Value(bool).init(false);

fn lockOwnProfile() void {
    while (g_own_profile_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockOwnProfile() void {
    g_own_profile_lock.store(false, .release);
}

/// Whether a relay has answered about THIS account. Anything else, including a
/// round for a previous account and a round where nothing connected, is not an
/// answer about this one.
fn ownProfileAnswered() bool {
    const pk = activePubkey() orelse return false;
    lockOwnProfile();
    defer unlockOwnProfile();
    const asked = g_own_profile_asked_for orelse return false;
    if (!std.mem.eql(u8, &asked, &pk)) return false;
    return g_own_profile_answered.load(.acquire);
}

/// Forgets what was asked. Called whenever the identity changes, so no
/// conclusion about one account is ever read as a fact about another.
fn forgetOwnProfileAnswer() void {
    lockOwnProfile();
    defer unlockOwnProfile();
    g_own_profile_asked_for = null;
    g_own_profile_answered.store(false, .release);
}

/// A profile as it was published: its content AND its tags. NIP-39 puts identity
/// proofs (a GitHub account, a Mastodon handle) in kind:0's TAGS, so republishing
/// with `&.{}` deletes them exactly as silently as dropping a JSON key would.
const OwnProfile = struct {
    json: []u8,
    tags: []const nostr.event.Tag,
    created_at: i64,
    /// The event these came from, so a caller can tell an unchanged record from
    /// a new one without re-parsing it.
    id: [32]u8 = [_]u8{0} ** 32,
};

/// The reader's own newest kind:0, raw. The RAW content is the source of truth,
/// never the `Profile` cache: the cache models four fields and drops everything
/// else, so rebuilding from it would publish a profile with the rest deleted.
///
/// The returned slice is owned by the caller's allocator.
fn ownProfileJson(gpa: std.mem.Allocator) ?OwnProfile {
    return ownRecordJson(gpa, 0);
}

/// The reader's own newest event of `kind`, content and tags. The RAW record is
/// the source of truth for every write this app makes over one of its own
/// lists: the caches model a few fields and drop the rest, so rebuilding from
/// one would publish a record with everything else deleted.
fn ownRecordJson(gpa: std.mem.Allocator, kind: u16) ?OwnProfile {
    // Counted so a test can assert the SHAPE of the fix rather than its timing:
    // the property is that building a feed does not read this account's whole
    // contact list once per card, and a stopwatch on a CI runner is a poor way
    // to say that. Comptime, so the shipped binary has no counter.
    if (builtin.is_test) g_own_record_reads += 1;
    const store = g_store orelse return null;
    const pk = activePubkey() orelse return null;
    const kinds = [_]u16{kind};
    const authors = [_][32]u8{pk};
    var result = store.query(gpa, .{ .authors = &authors, .kinds = &kinds, .limit = 1 }) catch return null;
    defer result.deinit();
    if (result.events.len == 0) return null;
    // Copied out before `result.deinit()`: the query owns its events through an
    // arena, and the write seam holds what it is given past this frame.
    const copy = gpa.dupe(u8, result.events[0].content) catch return null;
    // Whole or not at all. A partial base is what turns a splice into a delete.
    const tags = dupeTags(gpa, result.events[0].tags) orelse return null;
    return .{ .json = copy, .tags = tags, .created_at = result.events[0].created_at, .id = result.events[0].id };
}

/// This account's newest stored event of `kind`, its tags flattened to one
/// string. For tests that need to see what a publish actually WROTE rather than
/// whether it returned true: a splice that quietly drops half the list still
/// publishes, so the return value proves nothing about what went out.
pub fn ownRecordTagsJoinedForTest(gpa: std.mem.Allocator, kind: u16) ?[]u8 {
    const own = ownRecordJson(gpa, kind) orelse return null;
    defer freeOwnProfile(gpa, own);
    var out = std.ArrayList(u8).empty;
    for (own.tags) |tag| {
        for (tag) |field| {
            out.appendSlice(gpa, field) catch return null;
            out.append(gpa, ' ') catch return null;
        }
        out.append(gpa, '\n') catch return null;
    }
    return out.toOwnedSlice(gpa) catch null;
}

/// Frees what `ownProfileJson` handed back.
fn freeOwnProfile(gpa: std.mem.Allocator, own: OwnProfile) void {
    gpa.free(own.json);
    for (own.tags) |t| {
        for (t) |field| gpa.free(field);
        gpa.free(t);
    }
    gpa.free(own.tags);
}

/// Opens the sheet, seeded from the reader's own kind:0 if the app has it.
fn openProfileEdit(model: *Model) void {
    // A guest has no key, so there is nothing to read and nothing that could
    // sign an edit. The sheet would sit on "Reading your current profile" for
    // the rest of the session.
    if (model.is_guest()) {
        model.joining = true;
        return;
    }
    model.editing_profile = true;
    model.profile_name_buffer.clear();
    model.profile_about_buffer.clear();
    model.profile_picture_buffer.clear();
    const gpa = std.heap.page_allocator;
    if (ownProfileJson(gpa)) |own| {
        // The whole record, not just its content: freeing only `json` left every
        // tag it carried behind on each open of the sheet.
        defer freeOwnProfile(gpa, own);
        // The three buffers were cleared two lines up, so there is nothing typed
        // to preserve here.
        seedProfileFields(model, own.json, false);
        model.profile_stage = .have;
        return;
    }
    // Nothing here yet. Ask before concluding anything.
    model.profile_seeded = false;
    model.profile_asked_at = nowSeconds();
    model.profile_stage = if (ownProfileAnswered()) .absent else .fetching;
    if (model.profile_stage == .fetching) startOwnProfileFetch();
}

/// Fills the sheet's fields from the RAW blob, so what the reader sees is what
/// is about to be rewritten.
///
/// A value too long for its field is NOT shown truncated. A bio that runs past
/// the buffer would otherwise appear cut off, and saving without touching it
/// would write the cut-off version back over the real one: silent data loss from
/// merely opening a sheet. Such a field is left empty and marked, and the merge
/// then leaves that key exactly as it was.
fn seedProfileFields(model: *Model, json: []const u8, keep_typed: bool) void {
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const root = std.json.parseFromSliceLeaky(std.json.Value, a, json, .{
        // A real profile out there has repeated keys sometimes, and refusing to
        // parse it would refuse to edit it.
        .duplicate_field_behavior = .use_last,
        .allocate = .alloc_always,
    }) catch return;
    if (root != .object) return;
    const obj = root.object;
    // Which key the name came from, so the edit REWRITES that key. Seeding from
    // `name` and writing `display_name` leaves the value the reader edited
    // exactly where it was, and the rename silently does nothing.
    model.profile_name_key = .display_name;
    var name: ?[]const u8 = null;
    if (stringField(obj, "display_name")) |v| {
        name = v;
    } else if (stringField(obj, "displayName")) |v| {
        name = v;
        model.profile_name_key = .display_name_legacy;
    } else if (stringField(obj, "name")) |v| {
        name = v;
        model.profile_name_key = .name;
    }
    // A field the reader has already typed into keeps their text; every other
    // field is filled from the profile that just arrived.
    //
    // It used to be all or nothing, and the tick flipped the stage to `.have`
    // whether or not the seeding ran. So a reader who typed a display name while
    // the fetch was still out got a savable sheet over two fields that had never
    // been seeded and were still empty, and the merge REMOVES a key whose field
    // is empty: pressing Save deleted their bio and their avatar from a profile
    // the app had by then read correctly. Per field, every field is now either
    // known or deliberately typed, which is the same rule the too-long-to-show
    // fields already followed.
    if (!(keep_typed and model.profile_name_buffer.text().len > 0)) {
        model.profile_name_long = seedField(&model.profile_name_buffer, name);
    }
    if (!(keep_typed and model.profile_about_buffer.text().len > 0)) {
        model.profile_about_long = seedField(&model.profile_about_buffer, stringField(obj, "about"));
    }
    if (!(keep_typed and model.profile_picture_buffer.text().len > 0)) {
        model.profile_picture_long = seedField(&model.profile_picture_buffer, stringField(obj, "picture"));
    }
    model.profile_seeded = true;
}

/// Seeds one field. Returns whether the value was too long to hold, in which
/// case the field is left EMPTY rather than truncated: an empty field the merge
/// leaves alone is honest, a truncated one that gets written back is not.
fn seedField(buffer: anytype, value: ?[]const u8) bool {
    const v = value orelse return false;
    if (v.len > buffer.storage.len) {
        buffer.clear();
        return true;
    }
    buffer.set(v);
    return false;
}

fn stringField(obj: std.json.ObjectMap, key: []const u8) ?[]const u8 {
    const v = obj.get(key) orelse return null;
    return switch (v) {
        .string => |str| if (str.len == 0) null else str,
        else => null,
    };
}

/// Publishes the sheet's fields, MERGED into the reader's existing kind:0.
///
/// kind:0 is replaceable: what is published replaces the whole profile. Real
/// profiles carry `about`, `banner`, `website`, `lud16` (the lightning address
/// that is how somebody gets paid), and whatever else their other clients wrote.
/// This app models three of those, so it edits three keys of the object it read
/// and leaves every other key exactly where it was.
fn saveProfile(model: *Model, fx: *Effects) void {
    if (!model.profile_can_save()) return;
    if (activePubkey() == null) return;
    // The sheet reports `.sent` as soon as it has handed the merge over, so a
    // rejected sign would show a saved profile that was never signed. Refusing
    // leaves the sheet exactly as it was, with Save still live.
    if (!signerReady()) return;
    const gpa = std.heap.page_allocator;

    var prev_created_at: i64 = 0;
    var prev_tags: []const nostr.event.Tag = &.{};
    var existing: ?OwnProfile = null;
    if (ownProfileJson(gpa)) |own| {
        existing = own;
        prev_created_at = own.created_at;
        prev_tags = own.tags;
    } else if (model.profile_stage != .absent) {
        // It arrived as `have` and is gone now, or the round never finished.
        // Either way there is nothing safe to merge into.
        model.profile_stage = .fetching;
        startOwnProfileFetch();
        return;
    }
    defer if (existing) |e| freeOwnProfile(gpa, e);

    const merged = mergeProfileJson(gpa, if (existing) |e| e.json else "{}", model) orelse {
        model.profile_stage = .failed;
        return;
    };
    // The cache is seeded from a COPY, and BEFORE the write seam takes the
    // original: `signAndPublish` owns what it is handed and the remote path
    // frees it, so reading `merged` afterwards is a use-after-free.
    if (activePubkey()) |pk| {
        if (upsertProfile(pk)) |prof| parseMetadataInto(prof, merged);
        // A cleared picture has to leave the cache too, or the old avatar keeps
        // being drawn from a slot nothing will overwrite.
        if (trimmedField(model.profile_picture()).len == 0) clearProfilePicture(pk);
    }
    // A replaceable event with a stamp that does not beat the one already stored
    // is DROPPED, by this store and by every relay. A second edit inside one
    // second, or a clock that was ahead when the last client wrote, would make
    // the edit vanish while the app claimed success.
    const created = @max(nowSeconds(), prev_created_at + 1);
    // The TAGS come forward too. NIP-39 identity proofs (a GitHub account, a
    // Mastodon handle) live in kind:0's tags, and republishing with none would
    // delete them as silently as dropping a JSON key.
    const tags = dupeTags(gpa, prev_tags) orelse return;
    signAndPublish(fx, gpa, created, 0, tags, merged, false);
    // NOT "published": nothing here can know that yet. `signAndPublish` returns
    // no verdict, the remote and helper paths have not even signed, and a kind:0
    // that reaches no relay is not retried. What IS true is that the edit is
    // saved here and is on its way out.
    model.profile_stage = .sent;
}

/// Parses `existing`, replaces the three keys this app models, and serialises the
/// whole object back. Key order survives the round trip, so a profile this app
/// did not change comes back byte-similar rather than reshuffled.
/// The object a kind:0 edit merges into, or null when a record that IS there
/// could not be read.
///
/// Falling back to an empty object on a parse failure is the merge failing
/// open, and this object is the base every field is written into. A profile
/// that did not parse would be republished as nothing but the fields the screen
/// happened to hold, so the reader's lightning address, NIP-05, banner and
/// website would be gone from every relay and from every other client. That is
/// the same shape as writing a contact list over one that was never read, and
/// the answer is the same: a record that cannot be read whole reads as "not
/// read", which every caller already handles.
///
/// Not a hypothetical failure, either. Zig's JSON parser is stricter than the
/// ones the rest of the ecosystem uses: it rejects an unpaired surrogate half
/// in a `\u` escape, and it validates raw UTF-8. Profiles that came through
/// bridges, or were written by clients that never checked, carry both, and
/// those readers would be the ones who lost the most.
///
/// Only a caller saying there is nothing there may start from nothing, which is
/// the literal `{}` passed when no record was found.
fn profileMergeBase(a: std.mem.Allocator, existing: []const u8) ?std.json.ObjectMap {
    const nothing_to_lose = existing.len == 0 or
        std.mem.eql(u8, std.mem.trim(u8, existing, " \t\r\n"), "{}");
    const root = std.json.parseFromSliceLeaky(std.json.Value, a, existing, .{
        .duplicate_field_behavior = .use_last,
        .allocate = .alloc_always,
    }) catch return if (nothing_to_lose) std.json.ObjectMap.empty else null;
    if (root != .object) return if (nothing_to_lose) std.json.ObjectMap.empty else null;
    return root.object;
}

fn mergeProfileJson(gpa: std.mem.Allocator, existing: []const u8, model: *const Model) ?[]u8 {
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const a = arena_state.allocator();

    var obj = profileMergeBase(a, existing) orelse return null;

    // An emptied field REMOVES its key rather than writing "": a profile with
    // `"about": ""` reads to other clients as a bio the reader deliberately
    // blanked, which is a different statement from not having one.
    // A field whose real value did not fit its buffer was never SHOWN, so it is
    // never written: the key keeps exactly what it had.
    if (!model.profile_name_long) {
        // Whichever key the name was read from is the key the edit rewrites.
        // Seeding from `name` and writing `display_name` would leave the value
        // the reader edited untouched, so the rename would silently do nothing.
        const key: []const u8 = switch (model.profile_name_key) {
            .display_name => "display_name",
            .display_name_legacy => "displayName",
            .name => "name",
        };
        setOrRemove(&obj, a, key, trimmedField(model.profile_name())) catch return null;
        // A profile with no handle at all gets one, so clients that read only
        // `name` have something to show. One that has a handle keeps it: a
        // display name is not a handle, and renaming yourself must not rename
        // the @handle everyone mentions you by.
        if (stringField(obj, "name") == null) {
            setOrRemove(&obj, a, "name", trimmedField(model.profile_name())) catch return null;
        }
    }
    if (!model.profile_about_long) {
        setOrRemove(&obj, a, "about", trimmedField(model.profile_about())) catch return null;
    }
    if (!model.profile_picture_long) {
        setOrRemove(&obj, a, "picture", trimmedField(model.profile_picture())) catch return null;
    }

    // Straight onto the caller's allocator: the write seam holds this for the
    // life of the process, and the arena above dies with this function.
    return std.json.Stringify.valueAlloc(gpa, std.json.Value{ .object = obj }, .{}) catch null;
}

pub fn activePubkeyForTest() ?[32]u8 {
    return activePubkey();
}

pub fn forgetOwnProfileAnswerForTest() void {
    forgetOwnProfileAnswer();
}

/// Records an answer the way the worker's `defer` does.
pub fn recordOwnProfileAnswerForTest(pk: [32]u8, answered: bool) void {
    lockOwnProfile();
    g_own_profile_asked_for = pk;
    g_own_profile_answered.store(answered, .release);
    unlockOwnProfile();
}

pub fn ownProfileAnsweredForTest() bool {
    return ownProfileAnswered();
}

pub fn seedProfileFieldsForTest(model: *Model, json: []const u8, keep_typed: bool) void {
    seedProfileFields(model, json, keep_typed);
}

/// The merge, exposed so a test can prove what survives it. This is the whole
/// safety argument of the Edit profile sheet in one function.
pub fn mergeProfileJsonForTest(gpa: std.mem.Allocator, existing: []const u8, model: *const Model) ?[]u8 {
    return mergeProfileJson(gpa, existing, model);
}

/// Drives the name beat's whole write, not just its merge. The tags it forwards
/// are invisible to `mergeNameJsonForTest`, which only sees the content.
pub fn publishNameForTest(model: *Model, fx: *Effects) void {
    publishName(model, fx);
}

pub fn mergeNameJsonForTest(gpa: std.mem.Allocator, existing: []const u8, name: []const u8) ?[]u8 {
    return mergeNameJson(gpa, existing, name);
}

/// A field's text with the whitespace a reader leaves behind taken off.
fn trimmedField(s: []const u8) []const u8 {
    return std.mem.trim(u8, s, " \t\r\n");
}

fn setOrRemove(obj: *std.json.ObjectMap, a: std.mem.Allocator, key: []const u8, value: []const u8) !void {
    if (value.len == 0) {
        _ = obj.orderedRemove(key);
        return;
    }
    try obj.put(a, key, .{ .string = try a.dupe(u8, value) });
}

/// Asks every read relay for our own kind:0, once. Until this has finished, "the
/// store has no profile for me" is not a fact about the account.
fn startOwnProfileFetch() void {
    if (g_own_profile_asking.swap(true, .acq_rel)) return;
    const pk = activePubkey() orelse {
        g_own_profile_asking.store(false, .release);
        return;
    };
    const thread = std.Thread.spawn(.{}, ownProfileWorker, .{pk}) catch {
        g_own_profile_asking.store(false, .release);
        return;
    };
    thread.detach();
}

fn ownProfileWorker(pk: [32]u8) void {
    var answered = false;
    defer {
        // ANSWERED, not merely attempted. A round where every relay was offline,
        // write-only, or refused the dial proves nothing about the account, and
        // reading it as "you have no profile" is how a profile gets replaced
        // with an empty one.
        lockOwnProfile();
        g_own_profile_asked_for = pk;
        g_own_profile_answered.store(answered, .release);
        unlockOwnProfile();
        g_own_profile_asking.store(false, .release);
    }
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    const kinds = [_]u16{0};
    const authors = [_][32]u8{pk};
    const filters = [_]nostr.filter.Filter{.{ .authors = &authors, .kinds = &kinds, .limit = 1 }};
    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();
        relay.subscribe("plaza-me", &filters) catch continue;
        var seen: usize = 0;
        while (seen < 32) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    const result = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch continue;
                    // A relay can send ANY event down any subscription, so the
                    // event has to be the thing that was asked for before it can
                    // count as an answer about it. Verified was not enough: a
                    // valid note from a stranger, pushed down "plaza-me", used to
                    // decide that this account had no profile.
                    if (result == .invalid) continue;
                    if (e.event.kind != 0) continue;
                    if (!std.mem.eql(u8, &e.event.pubkey, &pk)) continue;
                    answered = true;
                },
                // A relay that says "that is all I have" has answered, and so
                // has one that closes the subscription: both are a reply.
                .eose, .closed => {
                    answered = true;
                    break;
                },
                else => continue,
            }
        }
    }
}

/// Publishes the name beat's text as the account's kind:0 metadata, and seeds
/// the local profile cache so the app shows the name at once.
///
/// The beat runs right after a key is created, when there is nothing to merge
/// into, but it goes through the same merge as the Edit profile sheet anyway:
/// the destructive shape is the one where a name is published as the WHOLE
/// profile, and having exactly one path here means that shape cannot come back
/// the next time somebody reaches for this function.
fn publishName(model: *Model, fx: *Effects) void {
    const raw = trimmedField(model.name_buffer.text());
    if (raw.len == 0) return;
    const gpa = std.heap.page_allocator;

    var prev_created_at: i64 = 0;
    var prev_tags: []const nostr.event.Tag = &.{};
    var existing: ?OwnProfile = null;
    if (ownProfileJson(gpa)) |own| {
        existing = own;
        prev_created_at = own.created_at;
        prev_tags = own.tags;
    }
    defer if (existing) |e| freeOwnProfile(gpa, e);

    // Quotes and backslashes are ESCAPED, not dropped: a name is prose, and the
    // serializer knows how to carry prose. (Dropping them was a fixed 64-byte
    // buffer away from a longer field overflowing it.)
    const json = mergeNameJson(gpa, if (existing) |e| e.json else "{}", raw) orelse return;
    // The TAGS come forward, the same as the sheet's save. The beat only arms on
    // a key this app just minted, which has no kind:0 and therefore no NIP-39
    // proofs to lose, so this is not a bug being fixed: it is the one line that
    // stopped the doc comment above from being true, and the read of the stored
    // profile two lines up says plainly that somebody already expected one.
    const tags = dupeTags(gpa, prev_tags) orelse return;
    signAndPublish(fx, gpa, @max(nowSeconds(), prev_created_at + 1), 0, tags, json, false);
    // Seed the cache: the composer line and the feed show the name at once.
    if (activePubkey()) |pk| {
        if (upsertProfile(pk)) |prof| parseMetadataInto(prof, json);
    }
    model.name_buffer.clear();
}

/// The name beat's one-field merge: the same read-modify-write as the sheet's,
/// with only the name touched.
fn mergeNameJson(gpa: std.mem.Allocator, existing: []const u8, name: []const u8) ?[]u8 {
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var obj = profileMergeBase(a, existing) orelse return null;
    setOrRemove(&obj, a, "name", name) catch return null;
    setOrRemove(&obj, a, "display_name", name) catch return null;
    return std.json.Stringify.valueAlloc(gpa, std.json.Value{ .object = obj }, .{}) catch null;
}

/// Completes the remembered first intent once an identity exists: the guest
/// reached for the composer, so it opens by itself. The welcome-in moment.
fn replayPending(model: *Model) void {
    if (model.pending == .post) {
        model.pending = .none;
        model.composing = true;
    }
}

/// The replay seam, exercised without disk or relays. For tests.
pub fn replayPendingForTest(model: *Model) void {
    replayPending(model);
}

/// Restores a helper identity from a session pubkey hex. For tests.
pub fn restoreHelperForTest(pubkey_hex: []const u8) bool {
    return restoreHelperIdentity(pubkey_hex);
}

/// Sets what the create ceremony has reported, which is the only thing that
/// tells an appearing key apart from any other. For tests.
pub fn setCeremonyForTest(state: enum { none, running, created }) void {
    g_ceremony = switch (state) {
        .none => .none,
        .running => .running,
        .created => .created,
    };
    g_ceremony_adopted = false;
}

/// Parks the daemon health flag at "unreachable", so a queued setup stays queued
/// instead of reaching for an effects layer a unit test does not have. For tests.
pub fn setHelperUnreachableForTest() void {
    g_helper_state.store(0, .release);
    g_helper_setup = .none;
    g_helper_pending_in_flight = .none;
}

pub fn ceremonyOwesNameForTest() bool {
    return g_ceremony_adopted;
}

pub fn identityMintedForTest() bool {
    return g_identity_minted_here;
}

/// Delivers the ceremony window's exit, which is how Plaza learns what it did.
/// For tests.
pub fn handleNotaryExitedForTest(model: *Model, e: native_sdk.EffectExit) void {
    handleNotaryExited(model, e);
}

/// Delivers a daemon /pubkey answer, which is how a key made or imported in the
/// other process reaches Plaza. For tests.
pub fn handleHelperPubkeyForTest(model: *Model, response: native_sdk.EffectResponse) void {
    handleHelperPubkey(model, response);
}

/// Drives the remote-signer connection state (0 idle, 1 reaching, 2 connected,
/// 3 unreachable) plus a remote identity, so the presentation is testable
/// without a live bunker. For tests.
pub fn setRemoteStateForTest(status: u8, npub_len: usize) void {
    g_signer_kind = if (status == 0) .local else .remote;
    g_remote_status.store(status, .release);
    g_remote_sign_notice.store(false, .release);
    if (npub_len > 0) {
        const stub = "npub1testsigner";
        const n = @min(stub.len, g_identity_npub_buf.len);
        @memcpy(g_identity_npub_buf[0..n], stub[0..n]);
        g_identity_npub_len = n;
    } else g_identity_npub_len = 0;
}

/// Switches to the feed and brings the store + ingest pool up if they are not
/// already running. Shared by all sign-in paths (create, import, remote signer).
/// A fresh identity means the feed's author filter changed, so force a rebuild
/// on the next tick by invalidating the change guard.
fn enterFeed(model: *Model) void {
    model.stage = .ready;
    invalidateFeed();
    if (g_store == null) {
        if (g_io) |io| if (g_environ) |env| startFeed(io, env);
    }
    // Whoever was signed in before, their follows leave with them. Then this
    // account's own list is read back out of the store, so a local-first app
    // does not forget who you follow every time you open it. Both bump the
    // generation, which is what makes the open sockets re-ask for the records
    // of the account that is actually signed in.
    forgetFollows();
    loadFollowsFromStore();
    // And what people sent this account while it was away.
    loadInbox();
}

pub fn initialModel() Model {
    var model = Model{};
    attachFeedStorage(&model);
    return model;
}

// -------------------------------------------------------------- compose & post
//
// Posting is local-first: a composed note is signed, written to the local store
// straight away (so it shows in the feed on the next tick), and published to the
// pool on a detached thread. The feed dedupes by event id, so when a relay later
// echoes our own note back through the ingest subscriptions it collapses onto
// the local copy.

/// Posts the current draft: sign a kind:1 note, store it locally at once, and
/// publish it to the pool in the background. A blank draft or a not-yet-ready
/// identity is a no-op.
fn submitPost(model: *Model, fx: *Effects) bool {
    const text = std.mem.trim(u8, model.draft_buffer.text(), " \t\r\n");
    if (text.len == 0) return false;
    // The composer is cleared and the draft file deleted right after this
    // returns, so a sign that never went out has to be reported rather than
    // assumed. The one shape that reaches here is a relay-list flush on the same
    // tick, which the SDK would reject and nothing would notice.
    if (!signerReady()) return false;
    // And a queue with room to track it. Refusing here keeps the note in the
    // composer; refusing after the sign, which is where it used to happen,
    // dropped it with no row, no retry and no way back.
    if (!outboxHasRoom()) return false;
    const gpa = std.heap.page_allocator;

    // A process-lifetime copy of the content: `event.create` references its
    // content slice rather than copying it, and the store write and either the
    // publisher or the NIP-46 round-trip read it after the draft is cleared.
    // Canonicalised BEFORE the copy, so the published content and the imeta tag
    // built from it name the same URL. NIP-92 pairs a tag with a URL in the
    // content, and a tag pointing at a string that is not there is one a reader
    // is entitled to ignore.
    const canonical = canonicalMediaUrls(gpa, text);
    const owned = gpa.dupe(u8, canonical) catch return false;
    // Read off `owned`, not off the draft buffer: that is cleared two lines
    // below, and the tags hold slices of whatever they were built from.
    const tags = contentTags(gpa, owned, &.{}, model.mentionsOff());
    // A composer draft: kind:1 carrying whatever its own text implies,
    // restorable to the composer if a remote signer never answers.
    signAndPublish(fx, gpa, nowSeconds(), 1, tags, owned, true);
    model.draft_buffer.clear();
    return true;
}

/// Signs `content_owned` as an event of `kind` with `tags`, stamped `created`,
/// through whichever signer is active, then stores and publishes it. Takes
/// ownership of `content_owned` and `tags` (process-lifetime: the local and
/// remote paths reference them after this returns, and the write seam intends
/// them to outlive the detached publish). `restorable` marks a composer draft,
/// so only a lost post is put back in the composer, never a reaction.
fn signAndPublish(fx: *Effects, gpa: std.mem.Allocator, created: i64, kind: u16, tags_in: []const nostr.event.Tag, content_owned: []const u8, restorable: bool) void {
    // Here, rather than at each call site, because this is the ONE door every
    // published event goes through: a switch the reader turned on has to hold for
    // the note they write, the note they repost and the note they quote, and a
    // per-caller version of it is a switch that holds for whichever paths someone
    // remembered.
    const tags = withClientTag(gpa, kind, tags_in);
    // The finished tag set, recorded where a test can read it. A parser that is
    // correct and never called is the regression worth guarding against here,
    // and every other seam in this file stops short of the event itself.
    g_last_published_tags = tags;
    switch (g_signer_kind) {
        .local => {
            const signer = g_identity_signer orelse return;
            const kp = g_identity_kp orelse return;
            const ev = nostr.event.create(gpa, signer, kp, created, kind, tags, content_owned, null) catch return;
            ingestAndPublish(gpa, ev, null);
        },
        .remote => requestRemoteSign(gpa, created, kind, tags, content_owned, restorable),
        .helper => requestHelperSign(fx, gpa, created, kind, tags, content_owned, restorable),
    }
}

/// Appends NIP-89's `client` tag when the reader has asked for it.
///
/// Only to the kinds that ARE the reader's writing. A reaction, a deletion and a
/// contact list are machinery; stamping those would broadcast the same fact more
/// widely for no reader-visible benefit, which is the opposite of what an opt-in
/// privacy switch is for.
pub fn withClientTag(gpa: std.mem.Allocator, kind: u16, tags: []const nostr.event.Tag) []const nostr.event.Tag {
    if (!g_client_tag) return tags;
    if (kind != 1 and kind != 6) return tags;
    const tag = gpa.dupe([]const u8, &.{ "client", client_tag_name }) catch return tags;
    const out = gpa.alloc(nostr.event.Tag, tags.len + 1) catch return tags;
    @memcpy(out[0..tags.len], tags);
    out[tags.len] = tag;
    return out;
}

/// The time, and what the note was written with when it says so.
///
/// Returned as SPANS of the paragraph the time already occupies, not as a node of
/// its own. A feed row is priced in widget nodes against a per-view ceiling that
/// refuses the whole screen when crossed, and "a quiet second line of metadata"
/// is precisely the sort of thing that costs ten rows' worth of budget without
/// looking like it costs anything.
///
/// The name is drawn in the meta register and prefixed, so it can never be read
/// as the note's own words. It is somebody else's claim about their software.
fn timeSpans(ui: *AppUi, note: *const Note, scale: f32) []const canvas.TextSpan {
    const name = note.client();
    if (name.len == 0) {
        const one = ui.arena.alloc(canvas.TextSpan, 1) catch return &.{};
        one[0] = .{ .text = note.time(), .scale = scale };
        return one;
    }
    const two = ui.arena.alloc(canvas.TextSpan, 2) catch return &.{};
    two[0] = .{ .text = note.time(), .scale = scale };
    // Same faint register as the time it follows: inherited from the paragraph,
    // so it cannot drift into looking like the note's own words.
    two[1] = .{ .text = ui.fmt(" via {s}", .{name}), .scale = scale };
    return two;
}

/// " · via X" for a line that is already a single string, empty when the note
/// says nothing. The span form above is for the rows that draw the time on its
/// own; the focal note builds one sentence, so it needs the text form.
fn viaSuffix(ui: *AppUi, note: *const Note) []const u8 {
    const name = note.client();
    if (name.len == 0) return "";
    return ui.fmt(" · via {s}", .{name});
}

/// What a note says it was written with, if it says anything.
///
/// Foreign text from a stranger's event, so it is treated as such: a name longer
/// than a label is not a label, and control characters in a meta row are how a
/// row stops looking like a row. An absent or unusable tag draws nothing at all,
/// never "via unknown", because what a note does not say is not a fact about it.
/// In BYTES, which is what the buffer holds, and in CHARACTERS, which is what a
/// reader sees. Both are needed: a byte cap alone is about eight characters of
/// Japanese and twenty-four of English, so it silently refuses a legitimate name
/// in one script and accepts a much wider one in another.
/// 48 so that the CHARACTER cap is the one that binds in every script that
/// matters here: fourteen three-byte characters fit, which is what makes the
/// Japanese case behave like the English one rather than being cut a third
/// shorter for no reason a reader could see.
const client_name_bytes = 48;
const client_name_chars = 14;

pub fn clientOf(ev: nostr.event.Event) ?[]const u8 {
    for (ev.tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "client")) continue;
        const name = std.mem.trim(u8, tag[1], " \t\r\n");
        if (name.len == 0) return null;
        for (name) |c| {
            if (c < 0x20 or c == 0x7f) return null;
        }
        // TRUNCATED, not refused. A name too long for the row is still evidence
        // about the note; refusing it outright threw away the whole fact, and
        // did so unevenly by script.
        return clipToChars(name, client_name_chars, client_name_bytes);
    }
    return null;
}

/// The longest prefix of `s` that is at most `max_chars` codepoints and
/// `max_bytes` bytes, cut on a UTF-8 boundary.
///
/// Codepoints rather than bytes because the cap exists to bound WIDTH, and a
/// three-byte character is not three characters wide. Cutting mid-sequence would
/// hand the renderer an invalid string, which is a different bug.
fn clipToChars(s: []const u8, max_chars: usize, max_bytes: usize) []const u8 {
    var i: usize = 0;
    var chars: usize = 0;
    while (i < s.len and chars < max_chars) {
        const len = std.unicode.utf8ByteSequenceLength(s[i]) catch return s[0..i];
        if (i + len > s.len or i + len > max_bytes) break;
        _ = std.unicode.utf8Decode(s[i .. i + len]) catch return s[0..i];
        i += len;
        chars += 1;
    }
    return s[0..i];
}

/// Publishes the reply composer's text as a NIP-10 reply to the open thread's
/// note: a kind:1 e-tagging the root (marked "root") and p-tagging its author,
/// signed and stored local-first so it joins the thread at once. A guest cannot
/// sign, so a reply attempt routes to the join sheet.
fn publishReply(model: *Model, fx: *Effects) void {
    if (model.viewing_thread == 0) return;
    if (model.is_guest()) {
        model.joining = true;
        return;
    }
    const root = model.noteById(model.viewing_thread) orelse return;
    const text = std.mem.trim(u8, model.reply_buffer.text(), " \t\r\n");
    if (text.len == 0) return;
    const gpa = std.heap.page_allocator;
    const content = gpa.dupe(u8, text) catch return;
    const id_hex = hexAlloc(gpa, root.event_id) orelse return;
    const author_hex = hexAlloc(gpa, root.pubkey) orelse return;
    const e_tag = gpa.dupe([]const u8, &.{ "e", id_hex, "", "root" }) catch return;
    const p_tag = gpa.dupe([]const u8, &.{ "p", author_hex }) catch return;

    // Everybody already in the conversation, not only the person being answered.
    // A reply that tags one author is a reply the rest of the thread never hears
    // about, so they answer into a conversation that has moved on without them.
    // Both reference clients do this: Amethyst p-tags every author in the thread
    // plus the parent's own mentions, Jumble the parent author plus the parent's
    // p tags. Plaza does not retain a note's raw tags, so this is the authors,
    // which is the part that carries the conversation.
    var participants: [max_thread_participant_tags][32]u8 = undefined;
    var participants_len: usize = 0;
    const me = activePubkey();
    for (model.thread_notes[0..model.thread_notes_len]) |n| {
        if (participants_len == participants.len) break;
        // Not the root author, who already has a tag, and never yourself.
        if (std.mem.eql(u8, &n.pubkey, &root.pubkey)) continue;
        if (me) |mine| {
            if (std.mem.eql(u8, &mine, &n.pubkey)) continue;
        }
        if (mentionExcluded(model.mentionsOff(), n.pubkey)) continue;
        var dup = false;
        for (participants[0..participants_len]) |seen| {
            if (std.mem.eql(u8, &seen, &n.pubkey)) dup = true;
        }
        if (dup) continue;
        participants[participants_len] = n.pubkey;
        participants_len += 1;
    }

    const thread = gpa.alloc(nostr.event.Tag, 2 + participants_len) catch return;
    thread[0] = e_tag;
    thread[1] = p_tag;
    var filled: usize = 2;
    for (participants[0..participants_len]) |pubkey| {
        const hex = hexAlloc(gpa, pubkey) orelse break;
        thread[filled] = gpa.dupe([]const u8, &.{ "p", hex }) catch break;
        filled += 1;
    }
    // The threading tags first, then whatever the reply's own text implies. A
    // reply can carry a hashtag, a mention or a picture exactly like a note can,
    // and it used to carry none of them.
    const tags = contentTags(gpa, content, thread[0..filled], model.mentionsOff());
    signAndPublish(fx, gpa, nowSeconds(), 1, tags, content, false);
    model.reply_buffer.clear();
}

// ------------------------------------------------------------------------ likes
//
// A like is a NIP-25 kind:7 reaction with content "+", e/p/k-tagging the note.
// It rides the same three sign paths as a post and is local-first and optimistic:
// the heart fills the instant it is pressed (read from `g_my_likes` at render),
// and the reaction publishes in the background. Un-like is a NIP-09 kind:5
// deletion e-tagging our own reaction, since NIP-25 has no un-react. A guest
// press cannot sign, so it is remembered and completed after sign-in.

/// Lowercase-hex-encodes a 32-byte value into a fresh process-lifetime slice.
fn hexAlloc(gpa: std.mem.Allocator, bytes: [32]u8) ?[]const u8 {
    const out = gpa.alloc(u8, 64) catch return null;
    const digits = "0123456789abcdef";
    for (bytes, 0..) |b, i| {
        out[i * 2] = digits[b >> 4];
        out[i * 2 + 1] = digits[b & 0x0f];
    }
    return out;
}

// How many of each derived tag one note may carry. Caps rather than limits: a
// pasted C header emits a topic per `#include`, a pasted thread emits a mention
// per npub, and neither should be allowed to turn one note into a hundred-tag
// event that relays reject wholesale.
const max_topic_tags = 10;
const max_mention_tags = 8;
const max_quote_tags = 4;
const max_imeta_tags = 4;
// A long thread should not turn one reply into a mass notification, and some
// relays cap tag counts outright.
const max_thread_participant_tags = 12;
const max_topic_bytes = 64;

/// Rewrites `github.com/<owner>/<repo>/raw/<rest>` to
/// `raw.githubusercontent.com/<owner>/<repo>/<rest>`, returning `text` unchanged
/// when there is nothing to rewrite (and on OOM).
///
/// The first form is a 302 whose own response is `content-type: text/html`, so a
/// client that checks the type before inlining refuses to draw the picture and
/// the note arrives as a wall of text with a link in it. The second form is the
/// same bytes with `image/jpeg` on the first response.
///
/// Narrow on purpose: one host, one path shape, both ends serving the identical
/// file. This is the only place Plaza edits what somebody typed, and widening it
/// into a general URL cleaner would make that a habit instead of a fix.
fn canonicalMediaUrls(gpa: std.mem.Allocator, text: []const u8) []const u8 {
    const marker = "https://github.com/";
    if (std.mem.indexOf(u8, text, marker) == null) return text;

    var out = std.ArrayList(u8).initCapacity(gpa, text.len) catch return text;
    var i: usize = 0;
    while (i < text.len) {
        if (!std.mem.startsWith(u8, text[i..], marker)) {
            out.append(gpa, text[i]) catch return text;
            i += 1;
            continue;
        }
        var end = i;
        while (end < text.len and !std.ascii.isWhitespace(text[end])) end += 1;
        const url = text[i..end];
        const tail = url[marker.len..];
        // owner/repo/raw/<rest>, and nothing shorter.
        var parts = std.mem.splitScalar(u8, tail, '/');
        const owner = parts.next() orelse "";
        const repo = parts.next() orelse "";
        const raw = parts.next() orelse "";
        const rest = parts.rest();
        if (owner.len > 0 and repo.len > 0 and std.mem.eql(u8, raw, "raw") and rest.len > 0) {
            out.print(gpa, "https://raw.githubusercontent.com/{s}/{s}/{s}", .{ owner, repo, rest }) catch return text;
        } else {
            out.appendSlice(gpa, url) catch return text;
        }
        i = end;
    }
    return out.toOwnedSlice(gpa) catch text;
}

/// The MIME type an image URL's extension implies, or "" when it implies none.
fn imageMimeForUrl(url: []const u8) []const u8 {
    const path_end = std.mem.indexOfScalar(u8, url, '?') orelse url.len;
    const path = url[0..path_end];
    const table = [_]struct { ext: []const u8, mime: []const u8 }{
        .{ .ext = ".jpg", .mime = "image/jpeg" },
        .{ .ext = ".jpeg", .mime = "image/jpeg" },
        .{ .ext = ".png", .mime = "image/png" },
        .{ .ext = ".gif", .mime = "image/gif" },
        .{ .ext = ".webp", .mime = "image/webp" },
        .{ .ext = ".avif", .mime = "image/avif" },
        .{ .ext = ".bmp", .mime = "image/bmp" },
    };
    for (table) |row| {
        if (std.ascii.endsWithIgnoreCase(path, row.ext)) return row.mime;
    }
    return "";
}

/// The tags a note's own text implies: `t` per hashtag, `p` per mention, `q` per
/// quoted event, and `imeta` per image URL.
///
/// Everything here is derived from the text being published, at the moment it is
/// published, never from a list assembled while typing. Deleting a mention has
/// to delete its tag, and a side list built when the mention was picked goes
/// stale the moment the text is edited around it.
///
/// Not folded into `signAndPublish` alongside `withClientTag`, though that is the
/// one door every event passes through. A kind:0's content is a JSON blob whose
/// display name may contain a `#`, and a kind:3's content is machinery; scanning
/// those would put garbage on the network. The single-door pattern is right for a
/// tag that describes the client and wrong for tags derived from prose.
///
/// Process-lifetime, like the other builders here: the local write and the
/// detached publish both read these after this returns. Degrades to fewer tags on
/// OOM rather than refusing to post.
/// Everyone `content` would notify: each mention it names, and the author of
/// each event it quotes. Self-filtered and deduped, in the order they appear.
///
/// The composer's chips and the publish path both call this. Two functions that
/// each derived the set would be two functions that could disagree, and the one
/// promise the chips make is that they name exactly who gets tagged.
fn notifiedBy(content: []const u8, out: *[max_mention_tags][32]u8) usize {
    var n: usize = 0;
    const me = activePubkey();
    var scratch: [16 * 1024]u8 = undefined;
    var i: usize = 0;
    while (i < content.len and n < out.len) {
        // URLs whole, so a token inside one is never read as a reference.
        if (std.mem.startsWith(u8, content[i..], "http://") or std.mem.startsWith(u8, content[i..], "https://")) {
            while (i < content.len and !std.ascii.isWhitespace(content[i])) i += 1;
            continue;
        }
        var found: ?[32]u8 = null;
        var next = i + 1;
        var fba = std.heap.FixedBufferAllocator.init(&scratch);
        const arena = fba.allocator();
        if (parseMentionAt(arena, content, i)) |m| {
            found = m.pubkey;
            next = m.end;
        } else if (refPrecededByBoundary(content, i)) {
            var body_start = i;
            if (std.mem.startsWith(u8, content[i..], "nostr:")) body_start = i + "nostr:".len;
            const rest = content[body_start..];
            if (std.mem.startsWith(u8, rest, "nevent1")) {
                var j: usize = 0;
                while (j < rest.len and isBech32Char(rest[j])) j += 1;
                if (nostr.nip19.decodeNevent(arena, rest[0..j])) |ptr| {
                    // Only an author the pointer itself carries. A note1 has
                    // none, and this list must not name somebody on a guess.
                    if (ptr.author) |author| found = author;
                    next = body_start + j;
                } else |_| {}
            }
        }
        if (found) |pubkey| {
            const is_me = if (me) |mine| std.mem.eql(u8, &mine, &pubkey) else false;
            var dup = false;
            for (out[0..n]) |seen| {
                if (std.mem.eql(u8, &seen, &pubkey)) dup = true;
            }
            if (!is_me and !dup) {
                out[n] = pubkey;
                n += 1;
            }
            i = @max(next, i + 1);
            continue;
        }
        i += 1;
    }
    return n;
}

/// Whether `content` names `who`: as a NIP-27 mention, or as the author of an
/// event it quotes.
///
/// The reading half of what `notifiedBy` does for writing. Same scan, same
/// tokens, one difference: this one is asked about a specific person and so
/// cannot filter the reader out, which is the only thing it is ever asked
/// about.
pub fn contentNames(content: []const u8, who: [32]u8) bool {
    var scratch: [16 * 1024]u8 = undefined;
    var i: usize = 0;
    while (i < content.len) {
        // URLs whole, so a token inside one is never read as a reference.
        if (std.mem.startsWith(u8, content[i..], "http://") or std.mem.startsWith(u8, content[i..], "https://")) {
            while (i < content.len and !std.ascii.isWhitespace(content[i])) i += 1;
            continue;
        }
        var fba = std.heap.FixedBufferAllocator.init(&scratch);
        const arena = fba.allocator();
        if (parseMentionAt(arena, content, i)) |m| {
            if (std.mem.eql(u8, &m.pubkey, &who)) return true;
            i = @max(m.end, i + 1);
            continue;
        }
        if (refPrecededByBoundary(content, i)) {
            var body_start = i;
            if (std.mem.startsWith(u8, content[i..], "nostr:")) body_start = i + "nostr:".len;
            const rest = content[body_start..];
            if (std.mem.startsWith(u8, rest, "nevent1")) {
                var j: usize = 0;
                while (j < rest.len and isBech32Char(rest[j])) j += 1;
                if (nostr.nip19.decodeNevent(arena, rest[0..j])) |ptr| {
                    // Quoting somebody's note is telling them about it, so the
                    // author the pointer carries counts. A `note1` carries none,
                    // and nobody is named on a guess.
                    if (ptr.author) |author| {
                        if (std.mem.eql(u8, &author, &who)) return true;
                    }
                    i = @max(body_start + j, i + 1);
                    continue;
                } else |_| {}
            }
        }
        i += 1;
    }
    return false;
}

pub fn notifiedByForTest(content: []const u8, out: *[max_mention_tags][32]u8) usize {
    return notifiedBy(content, out);
}

/// Whether `pubkey` is in `excluded`, the set the reader has switched off for
/// this draft.
fn mentionExcluded(excluded: []const [32]u8, pubkey: [32]u8) bool {
    for (excluded) |e| {
        if (std.mem.eql(u8, &e, &pubkey)) return true;
    }
    return false;
}

fn contentTags(gpa: std.mem.Allocator, content: []const u8, base: []const nostr.event.Tag, excluded: []const [32]u8) []const nostr.event.Tag {
    var topics: [max_topic_tags][]const u8 = undefined;
    var topics_len: usize = 0;
    var mentions: [max_mention_tags][32]u8 = undefined;
    var mentions_len: usize = 0;
    var quotes: [max_quote_tags]struct { id: [32]u8, author: ?[32]u8 } = undefined;
    var quotes_len: usize = 0;
    var images: [max_imeta_tags][]const u8 = undefined;
    var images_len: usize = 0;

    const me = activePubkey();
    var scratch: [16 * 1024]u8 = undefined;

    var i: usize = 0;
    scan: while (i < content.len) {
        // A URL is consumed WHOLE, before anything else looks at this byte. That
        // single ordering is what keeps `https://example.com/page#section` from
        // publishing a topic called "section", and it is the guard the reference
        // clients are missing.
        if (std.mem.startsWith(u8, content[i..], "http://") or std.mem.startsWith(u8, content[i..], "https://")) {
            var j = i;
            while (j < content.len and !std.ascii.isWhitespace(content[j])) j += 1;
            const url = content[i..j];
            if (images_len < images.len and looksLikeImageUrl(url)) {
                var dup = false;
                for (images[0..images_len]) |seen| {
                    if (std.mem.eql(u8, seen, url)) dup = true;
                }
                // One tag per distinct URL: NIP-92 pairs a tag with a URL in the
                // content, and the same picture twice is still one picture.
                if (!dup) {
                    images[images_len] = url;
                    images_len += 1;
                }
            }
            i = j;
            continue :scan;
        }

        // A mention, by the same parser the renderer uses, so what is tagged is
        // exactly what is drawn as a name.
        {
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            if (parseMentionAt(fba.allocator(), content, i)) |m| {
                const is_me = if (me) |mine| std.mem.eql(u8, &mine, &m.pubkey) else false;
                var dup = false;
                for (mentions[0..mentions_len]) |seen| {
                    if (std.mem.eql(u8, &seen, &m.pubkey)) dup = true;
                }
                // Never tag yourself: your own inbox lighting up for your own
                // note is a bug the reader would report as one.
                const off = mentionExcluded(excluded, m.pubkey);
                if (!is_me and !dup and !off and mentions_len < mentions.len) {
                    mentions[mentions_len] = m.pubkey;
                    mentions_len += 1;
                }
                i = m.end;
                continue :scan;
            }
        }

        // A quoted event.
        if (quotes_len < quotes.len) {
            var body_start = i;
            var is_ref = false;
            if (std.mem.startsWith(u8, content[i..], "nostr:")) {
                if (refPrecededByBoundary(content, i)) {
                    body_start = i + "nostr:".len;
                    is_ref = true;
                }
            } else if (std.mem.startsWith(u8, content[i..], "nevent1") or std.mem.startsWith(u8, content[i..], "note1")) {
                is_ref = refPrecededByBoundary(content, i);
            }
            if (is_ref) {
                const rest = content[body_start..];
                if (std.mem.startsWith(u8, rest, "nevent1") or std.mem.startsWith(u8, rest, "note1")) {
                    var j: usize = 0;
                    while (j < rest.len and isBech32Char(rest[j])) j += 1;
                    const token = rest[0..j];
                    var fba = std.heap.FixedBufferAllocator.init(&scratch);
                    const arena = fba.allocator();
                    var id: ?[32]u8 = null;
                    var author: ?[32]u8 = null;
                    if (std.mem.startsWith(u8, token, "nevent1")) {
                        if (nostr.nip19.decodeNevent(arena, token)) |ptr| {
                            id = ptr.id;
                            author = ptr.author;
                        } else |_| {}
                    } else if (nostr.nip19.decodeNote(arena, token)) |note_id| {
                        id = note_id;
                    } else |_| {}
                    if (id) |event_id| {
                        var dup = false;
                        for (quotes[0..quotes_len]) |seen| {
                            if (std.mem.eql(u8, &seen.id, &event_id)) dup = true;
                        }
                        if (!dup) {
                            // Only the author the pointer itself carries. A
                            // `note1` carries none, and slot 4 is a notification
                            // target, so a guess there tells the wrong person
                            // they were quoted. Absent beats wrong.
                            quotes[quotes_len] = .{ .id = event_id, .author = author };
                            quotes_len += 1;
                        }
                        i = body_start + j;
                        continue :scan;
                    }
                }
            }
        }

        // A hashtag, last, because everything above can begin with a character
        // this would otherwise swallow.
        if (content[i] == '#' and i + 1 < content.len and isHashtagChar(content[i + 1]) and
            (i == 0 or !isHashtagChar(content[i - 1])))
        {
            var j = i + 1;
            while (j < content.len and isHashtagChar(content[j])) j += 1;
            const raw = content[i + 1 .. j];
            if (raw.len <= max_topic_bytes and std.unicode.utf8ValidateSlice(raw) and topics_len < topics.len) {
                // NIP-24 is a MUST on the value being lowercase. ASCII folding
                // only: a full Unicode fold would need a casing table, and the
                // tags this misses are ones no relay filter is asking for.
                const folded = gpa.alloc(u8, raw.len) catch {
                    i = j;
                    continue :scan;
                };
                _ = std.ascii.lowerString(folded, raw);
                var dup = false;
                for (topics[0..topics_len]) |seen| {
                    if (std.mem.eql(u8, seen, folded)) dup = true;
                }
                // Folded first, THEN deduped, so `#Nostr #nostr` is one topic.
                if (dup) {
                    gpa.free(folded);
                } else {
                    topics[topics_len] = folded;
                    topics_len += 1;
                }
            }
            i = j;
            continue :scan;
        }

        i += 1;
    }

    // Every quoted author is also a mention: NIP-10 asks for it, and without it
    // the person you quoted never learns you did.
    for (quotes[0..quotes_len]) |q| {
        const author = q.author orelse continue;
        if (mentions_len >= mentions.len) break;
        const is_me = if (me) |mine| std.mem.eql(u8, &mine, &author) else false;
        if (is_me or mentionExcluded(excluded, author)) continue;
        var dup = false;
        for (mentions[0..mentions_len]) |seen| {
            if (std.mem.eql(u8, &seen, &author)) dup = true;
        }
        if (dup) continue;
        mentions[mentions_len] = author;
        mentions_len += 1;
    }

    const derived = topics_len + mentions_len + quotes_len + images_len;
    if (derived == 0) return base;

    var out = std.ArrayList(nostr.event.Tag).initCapacity(gpa, base.len + derived) catch return base;
    out.appendSliceAssumeCapacity(base);

    for (topics[0..topics_len]) |topic| {
        const tag = gpa.dupe([]const u8, &.{ "t", topic }) catch break;
        out.appendAssumeCapacity(tag);
    }
    for (mentions[0..mentions_len]) |pubkey| {
        const hex = hexAlloc(gpa, pubkey) orelse break;
        const tag = gpa.dupe([]const u8, &.{ "p", hex }) catch break;
        out.appendAssumeCapacity(tag);
    }
    for (quotes[0..quotes_len]) |q| {
        const id_hex = hexAlloc(gpa, q.id) orelse break;
        // Positional, so an author can only be read out of slot 4. With no
        // author the tag stops at the id rather than shipping empty slots.
        const tag = if (q.author) |author| blk: {
            const author_hex = hexAlloc(gpa, author) orelse break :blk gpa.dupe([]const u8, &.{ "q", id_hex }) catch break;
            break :blk gpa.dupe([]const u8, &.{ "q", id_hex, "", author_hex }) catch break;
        } else gpa.dupe([]const u8, &.{ "q", id_hex }) catch break;
        out.appendAssumeCapacity(tag);
    }
    for (images[0..images_len]) |url| {
        // NIP-92's fields are one space-joined "key value" string each, and a
        // value may itself contain spaces, so a reader splits on the FIRST space
        // only. Plaza's own reader already does; this writes what that reads.
        const url_field = std.fmt.allocPrint(gpa, "url {s}", .{url}) catch break;
        const mime = imageMimeForUrl(url);
        const tag = if (mime.len == 0)
            gpa.dupe([]const u8, &.{ "imeta", url_field }) catch break
        else blk: {
            const mime_field = std.fmt.allocPrint(gpa, "m {s}", .{mime}) catch break;
            break :blk gpa.dupe([]const u8, &.{ "imeta", url_field, mime_field }) catch break;
        };
        out.appendAssumeCapacity(tag);
    }

    return out.toOwnedSlice(gpa) catch base;
}

/// The NIP-25 like tags for a note: `["e", id]`, `["p", author]`, `["k", "1"]`.
/// Process-lifetime (the sign paths reference them); null on OOM.
fn buildLikeTags(gpa: std.mem.Allocator, note: *const Note) ?[]const nostr.event.Tag {
    const id_hex = hexAlloc(gpa, note.event_id) orelse return null;
    const author_hex = hexAlloc(gpa, note.pubkey) orelse return null;
    const e = gpa.dupe([]const u8, &.{ "e", id_hex }) catch return null;
    const p = gpa.dupe([]const u8, &.{ "p", author_hex }) catch return null;
    const k = gpa.dupe([]const u8, &.{ "k", "1" }) catch return null;
    const tags = gpa.alloc(nostr.event.Tag, 3) catch return null;
    tags[0] = e;
    tags[1] = p;
    tags[2] = k;
    return tags;
}

/// The NIP-09 deletion tags to un-like: `["e", reaction_id]`, `["k", "7"]`.
fn buildUnlikeTags(gpa: std.mem.Allocator, reaction_id: [32]u8) ?[]const nostr.event.Tag {
    const id_hex = hexAlloc(gpa, reaction_id) orelse return null;
    const e = gpa.dupe([]const u8, &.{ "e", id_hex }) catch return null;
    const k = gpa.dupe([]const u8, &.{ "k", "7" }) catch return null;
    const tags = gpa.alloc(nostr.event.Tag, 2) catch return null;
    tags[0] = e;
    tags[1] = k;
    return tags;
}

/// Toggles a like on `note_id`. A guest cannot sign, so the like is remembered
/// and the join sheet opens; it completes after sign-in (`drivePendingIntent`).
fn toggleLike(model: *Model, fx: *Effects, note_id: i64) void {
    if (model.is_guest()) {
        model.pending = .{ .like = note_id };
        model.joining = true;
        return;
    }
    // A like and an un-like both move `g_my_likes` before they sign, and an
    // un-like's kind:5 is a deletion. A rejected sign there would leave the heart
    // empty and the reaction still standing on every relay.
    if (!signerReady()) return;
    if (isLiked(note_id)) unlike(fx, note_id) else like(model, fx, note_id);
}

/// Publishes a kind:7 like and fills the heart at once. The reaction id is
/// deterministic in the unsigned fields, so it is computed here (with the same
/// created/tags/content the sign path will use) and remembered, so an un-like
/// can delete exactly this reaction.
fn like(model: *const Model, fx: *Effects, note_id: i64) void {
    const note = model.noteById(note_id) orelse return;
    const gpa = std.heap.page_allocator;
    const pk = activePubkey() orelse return;
    const created = nowSeconds();
    const tags = buildLikeTags(gpa, note) orelse return;
    const content = gpa.dupe(u8, "+") catch return;
    const id = nostr.event.computeId(gpa, pk, created, 7, tags, content) catch return;
    rememberLike(note_id, id);
    signAndPublish(fx, gpa, created, 7, tags, content, false);
}

/// Publishes a kind:5 deletion of our own reaction and empties the heart at once.
fn unlike(fx: *Effects, note_id: i64) void {
    const gpa = std.heap.page_allocator;
    const reaction_id = forgetLike(note_id) orelse return;
    const tags = buildUnlikeTags(gpa, reaction_id) orelse return;
    const content = gpa.dupe(u8, "") catch return;
    signAndPublish(fx, gpa, nowSeconds(), 5, tags, content, false);
}

/// After sign-in, completes a like a guest reached for: the welcome-in moment.
/// Driven from the tick, where `fx` is in hand and the feed has just rebuilt.
fn drivePendingIntent(model: *Model, fx: *Effects) void {
    if (!model.pending.waiting() or model.is_guest()) return;
    const intent = model.pending;
    // Cleared FIRST, whatever happens next. A verb that cannot be completed (the
    // note scrolled away, the follow list has not loaded) must not be retried on
    // every tick for the rest of the session.
    model.pending = .none;
    switch (intent) {
        .none => {},
        .post => model.composing = true,
        .reply => |id| {
            // Back to the conversation they were in, with what they wrote still
            // in the box: `reply_buffer` survived the sheet.
            if (model.viewing_thread != id) openEvent(model, noteEventId(model, id) orelse return);
        },
        .like => |id| {
            if (isLiked(id)) return;
            like(model, fx, id);
            setToast(model, "Liked");
        },
        .follow => |pk| {
            // The follow-safety gate still applies: this publishes a replaceable
            // list, and nothing may be written over a contact list that has not
            // been read back. When it is not yet safe the intent is dropped rather
            // than queued, because a write that lands minutes later, silently, is
            // exactly the shape this app refuses everywhere else.
            if (!canWriteFollows()) {
                setToast(model, "Still fetching your follow list. Try again in a moment.");
                return;
            }
            sayFollowWrite(model, writeFollow(fx, pk, true), true);
        },
    }
}

pub fn drivePendingIntentForTest(model: *Model, fx: *Effects) void {
    drivePendingIntent(model, fx);
}

/// The full event id of a loaded note, for reopening what a guest was reading.
fn noteEventId(model: *const Model, note_id: i64) ?[32]u8 {
    if (model.noteById(note_id)) |note| return note.event_id;
    return null;
}

/// Deep-copies `tags` into process-lifetime memory so the detached publisher can
/// read them after the parse arena is freed. Returns an empty set on OOM (posts
/// are tagless, so nothing is lost there; a reaction that OOMs simply drops).
/// Copies a record's tags, or reports that it could not.
///
/// Null, never an empty slice. This is the splice base for every replaceable
/// write (kind 0, 3 and 10002), and those writes decide how much to keep by
/// counting what is in here. An empty slice says "this record had no tags",
/// which is a true statement about a record with no tags and a catastrophic one
/// about a copy that ran out of memory: the follow list's own shrink guard
/// compares against this same slice, so 0 to 1 reads as growth and passes.
///
/// A base that could not be copied whole must read as "not read". Every caller
/// already handles that safely, because it is the same path as a store miss.
fn dupeTags(gpa: std.mem.Allocator, tags: []const nostr.event.Tag) ?[]const nostr.event.Tag {
    if (tags.len == 0) return &.{};
    const out = gpa.alloc(nostr.event.Tag, tags.len) catch return null;
    for (tags, 0..) |tag, i| {
        const fields = gpa.alloc([]const u8, tag.len) catch return null;
        for (tag, 0..) |field, j| {
            fields[j] = gpa.dupe(u8, field) catch return null;
        }
        out[i] = fields;
    }
    return out;
}

/// The engine write seam: a note this process now holds, whether locally signed
/// or returned signed from the remote signer, enters the local store and is
/// published to the pool. The store is the single-writer data plane, only ever
/// written from this process. `verify` re-checks a signature we did not produce
/// ourselves and gates such a note out of both the store and the pool on
/// failure; a note we just signed skips the check and publishes even if the
/// store rejects the write (a duplicate). `ev.content` must be a
/// process-lifetime allocation, since the detached publisher reads it after
/// this returns.
fn ingestAndPublish(gpa: std.mem.Allocator, ev: nostr.event.Event, verify: ?nostr.keys.Signer) void {
    if (g_store == null) return;
    if (verify) |signer| {
        // A note we did not produce: verification is the gate into the store
        // AND the pool, so a bad signature is dropped rather than propagated.
        _ = plazaIngest(gpa, ev, .{ .verify_with = signer }) catch return;
    } else {
        // A note we just signed: a store failure (e.g. a duplicate id) must not
        // stop it reaching the pool.
        _ = plazaIngest(gpa, ev, .{}) catch {};
    }
    // Queued BEFORE the walk, so a note that never reaches a relay is still a
    // note the app knows it owes the reader. A queue with no room says so:
    // publishing anyway would be a note nobody is tracking while the banner
    // promises that anything written is kept.
    if (isReaderNote(ev.kind) and !enqueueOutbox(ev.id, ev.pubkey, nowSeconds())) {
        g_outbox_overflow.store(true, .monotonic);
        return;
    }
    // A test drives the write path, not the network. Its pool names hosts that
    // do not resolve, and a detached dial thread for one of those outlives the
    // test that started it and can take the process down on the way out, which
    // reads as a failing suite with no failing assertion. Comptime, so the
    // shipped binary has no branch here at all.
    if (builtin.is_test) return;
    const thread = std.Thread.spawn(.{}, publishWorker, .{ gpa, ev }) catch {
        // No thread: the note stays queued and the next drain will carry it.
        return;
    };
    thread.detach();
}

/// One publish walk for `ev`, with the queue updated around it.
fn publishWorker(gpa: std.mem.Allocator, ev: nostr.event.Event) void {
    markOutboxSending(ev.id, true);
    publishEvent(gpa, ev);
    markOutboxSending(ev.id, false);
}

fn markOutboxSending(id: [32]u8, sending: bool) void {
    outboxLock();
    defer outboxUnlock();
    const e = outboxEntryFor(id) orelse return;
    e.sending = sending;
    if (!sending) e.rounds +|= 1;
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

// -------------------------------------------------------------------- the outbox
//
// What happens to a note between pressing Post and knowing it is somewhere else.
//
// Publishing used to be fire-and-forget: a detached thread dialled every relay,
// wrote the frame, read one message to flush it, and dropped the verdict. The
// note was in the local store, so the feed showed it, and whether it ever
// reached anyone was not a question the app could answer.
//
// Now every publish goes through a queue. Each entry names an event that is
// already in the store's own tables (we ingest what we sign) and carries one bit
// per relay: did that relay say OK. The queue is the app's answer to "is my note
// out there", the status bar reads it, and it survives a quit, because a note
// written on a train and lost on landing is the worst thing a client can do.
//
// The queue is small on purpose. It is not a retry engine for a broken network;
// it is a record of what has not been acknowledged yet, drained whenever a relay
// comes back.

/// One note on its way out.
pub const OutboxEntry = struct {
    used: bool = false,
    id: [32]u8 = [_]u8{0} ** 32,
    /// Who signed the note this entry owes. A queue entry is a promise to ONE
    /// account, and the publisher, the counts and the popover all filter on it.
    ///
    /// Not persisted, and it does not need to be: `loadOutbox` already reads the
    /// event back out of the store to check it still exists, and the event
    /// carries its own author. Deriving it there keeps the on-disk format
    /// unchanged, so a queue written by an older build still loads.
    author: [32]u8 = [_]u8{0} ** 32,
    /// When it was queued, so the popover can say how long it has been waiting
    /// and the oldest entry can be dropped when the queue is full.
    queued_at: i64 = 0,
    /// One bit per pool relay: this relay answered OK.
    acked: u8 = 0,
    /// One bit per pool relay: this relay answered, and said no.
    refused: u8 = 0,
    /// How many times the publisher has walked the relays for this entry, so a
    /// note nobody will take stops asking rather than hammering forever.
    rounds: u8 = 0,
    /// Whether a publish walk is in flight for this entry right now.
    sending: bool = false,
    /// When the last walk started, so the next one waits.
    last_try_at: i64 = 0,

    /// How many relays have taken it.
    pub fn ackCount(self: OutboxEntry) usize {
        return @popCount(self.acked);
    }

    /// Where this note is, in the words the popover uses.
    pub fn state(self: OutboxEntry) OutboxState {
        if (self.acked != 0) return .sent;
        if (self.sending) return .sending;
        // A LABEL, not a verdict. The queue keeps offering this note; the word
        // only tells the reader it has been a while. It used to mean the app
        // had given up, which is the one thing a queue must not do silently.
        if (self.rounds >= rounds_before_stuck) return .stuck;
        return .queued;
    }
};

pub const OutboxState = enum { queued, sending, sent, stuck };

/// How long to wait before offering a note again, widening with each attempt so
/// a relay that is down is asked minutes apart rather than every second.
fn outboxRetryDelay(rounds: u8) i64 {
    return switch (rounds) {
        0 => 0,
        1 => 5,
        2 => 20,
        3 => 60,
        4 => 300,
        5 => 900,
        // Once an hour, forever. A relay that has been unreachable for an hour
        // may well come back tomorrow, and asking it hourly costs one dial.
        else => 3600,
    };
}

/// Set when a note could not be queued at all, so the reader is told rather than
/// left with a promise the app did not keep.
var g_outbox_overflow = std.atomic.Value(bool).init(false);

/// Room for a burst of posting without becoming a store of its own. A reader who
/// writes more than this while offline is past what a status bar can explain.
const outbox_cap = 16;
/// After how many failed rounds the popover starts calling a note stuck.
///
/// This used to be the point at which the queue GAVE UP. Six rounds on the old
/// ladder is about eleven and a half minutes, so closing a laptop lid for
/// twelve, or spending that long on a captive portal where TCP connects and TLS
/// does not, permanently abandoned every queued note. It was never offered
/// again for the life of the install, the count survived a restart, and sixteen
/// of them filled the queue so the account could never post from that install
/// again. The only escape was editing the relay list, which nobody would guess.
///
/// Now it only changes the word on the row. The note keeps being offered, on a
/// widening delay, for as long as the app is running.
const rounds_before_stuck = 6;

var g_outbox = [_]OutboxEntry{.{}} ** outbox_cap;
/// Bumped whenever the queue changes, so the UI thread can tell that the
/// publisher touched something without locking.
var g_outbox_rev = std.atomic.Value(u32).init(0);
/// The same tiny spinlock the pending-signature table uses, and for the same
/// reason: every critical section here is a handful of field writes or a
/// 16-slot scan and never touches IO, while `std.Io.Mutex` would drag a
/// per-thread `io` across threads that deliberately never share one.
var g_outbox_lock = std.atomic.Value(bool).init(false);

fn outboxLock() void {
    while (g_outbox_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
}
fn outboxUnlock() void {
    g_outbox_lock.store(false, .release);
}

/// Whether this entry belongs to whoever is signed in right now.
///
/// The three places that ACT on the reader's behalf ask this: what the publisher
/// sends, what the status bar counts, and what the popover lists. The bookkeeping
/// that runs over the whole array (`sweepOutbox`, `forgetOutboxAcks`,
/// `recordOutboxAck`, `markOutboxSending`) deliberately does not, because by the
/// time any of it runs the array holds one account's entries and nobody else's:
/// `syncOutboxOwner` hands the slots over when the account changes.
///
/// A queued note is a promise made to ONE account. Logging out does not empty
/// the queue, deliberately: `sweepOutbox` refuses to erase a note nobody has
/// taken, because that is the app destroying something the reader wrote, and a
/// logout is not a reason to break that promise. So the note stays, and stops
/// being walkable instead. Sign back in as its author and it resumes; sign in as
/// somebody else and it is not theirs to send, not theirs to be counted, and not
/// theirs to see.
///
/// Signed out, nothing is anybody's, which is why a null active key is false
/// rather than a wildcard.
fn outboxEntryIsMine(e: OutboxEntry) bool {
    const me = activePubkey() orelse return false;
    return std.mem.eql(u8, &me, &e.author);
}

/// Puts `id` in the queue, or returns the entry already there. The caller holds
/// the lock.
fn outboxEntryFor(id: [32]u8) ?*OutboxEntry {
    for (&g_outbox) |*e| {
        if (e.used and std.mem.eql(u8, &e.id, &id)) return e;
    }
    return null;
}

/// Queues a note we have just signed and stored. Returns false when the queue is
/// full of notes that have not been acknowledged, which is a state the reader can
/// see rather than one the app hides.
fn enqueueOutbox(id: [32]u8, author: [32]u8, now_s: i64) bool {
    outboxLock();
    defer outboxUnlock();
    if (outboxEntryFor(id) != null) return true;
    for (&g_outbox) |*e| {
        if (!e.used) {
            e.* = .{ .used = true, .id = id, .author = author, .queued_at = now_s };
            _ = g_outbox_rev.fetchAdd(1, .monotonic);
            return true;
        }
    }
    // Full: drop the oldest note that has already reached somebody, since its
    // record is the least useful thing here.
    var victim: ?*OutboxEntry = null;
    for (&g_outbox) |*e| {
        if (e.acked == 0) continue;
        if (victim == null or e.queued_at < victim.?.queued_at) victim = e;
    }
    const slot = victim orelse return false;
    slot.* = .{ .used = true, .id = id, .author = author, .queued_at = now_s };
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
    return true;
}

/// Whether the queue could take another note right now.
///
/// Asked BEFORE the composer is emptied, which is the difference between a note
/// the reader still has and one that is gone. `ingestAndPublish` refuses to
/// publish what it cannot track, and it is right to: a note nobody is counting
/// under a banner promising that anything written is kept is the lie the queue
/// exists to stop telling. But the refusal happened after `.post` had cleared
/// the composer and deleted the draft file, so the note was simply lost, with no
/// queue row, no retry and no way back.
///
/// Sixteen slots, and eviction only takes a note that has already reached
/// somebody. Sixteen unacked notes therefore wedge the queue for as long as the
/// failure lasts, which for a pool that all requires NIP-42 AUTH, or a laptop on
/// a plane, is a real state and not a corner.
fn outboxHasRoom() bool {
    outboxLock();
    defer outboxUnlock();
    for (&g_outbox) |*e| {
        if (!e.used) return true;
        if (e.acked != 0) return true;
    }
    return false;
}

pub fn outboxHasRoomForTest() bool {
    return outboxHasRoom();
}

/// Records what one relay said about one note.
fn recordOutboxAck(id: [32]u8, relay_index: usize, accepted: bool) void {
    if (relay_index >= max_relays) return;
    outboxLock();
    defer outboxUnlock();
    const e = outboxEntryFor(id) orelse return;
    const bit = @as(u8, 1) << @intCast(relay_index);
    if (accepted) e.acked |= bit else e.refused |= bit;
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// A snapshot of the queue for the view, newest first. The view never reads the
/// queue directly: the publisher writes it from its own thread.
pub fn outboxSnapshot(out: []OutboxEntry) usize {
    outboxLock();
    defer outboxUnlock();
    var n: usize = 0;
    for (&g_outbox) |*e| {
        if (!e.used or n == out.len) continue;
        // The same rule `outboxCounts` applies: the popover explains the count,
        // so it has to be a list of the same notes.
        if (!outboxEntryIsMine(e.*)) continue;
        out[n] = e.*;
        n += 1;
    }
    std.mem.sort(OutboxEntry, out[0..n], {}, struct {
        fn lt(_: void, a: OutboxEntry, b: OutboxEntry) bool {
            return a.queued_at > b.queued_at;
        }
    }.lt);
    return n;
}

/// How many notes are still trying, and how many have given up. They are
/// counted apart because they say different things: one is work in progress,
/// the other is a note the reader wrote that never left.
pub const OutboxCounts = struct { trying: usize = 0, stuck: usize = 0 };

pub fn outboxCounts() OutboxCounts {
    outboxLock();
    defer outboxUnlock();
    var counts: OutboxCounts = .{};
    for (&g_outbox) |*e| {
        if (!e.used or e.acked != 0) continue;
        // The status bar speaks for the reader who is here now. Counting a note
        // they did not write would have the app owe them something that is not
        // theirs, and offer no way to act on it.
        if (!outboxEntryIsMine(e.*)) continue;
        if (e.state() == .stuck) counts.stuck += 1 else counts.trying += 1;
    }
    return counts;
}

/// How many notes are still waiting for their first relay, trying or not.
pub fn outboxPending() usize {
    const c = outboxCounts();
    return c.trying + c.stuck;
}

/// Forgets the notes that are done: acknowledged by somebody, or refused by
/// everyone that answered after enough rounds. Called once the reader has had a
/// chance to see them, so the zone does not blink out mid-glance.
fn sweepOutbox(now_s: i64) void {
    outboxLock();
    defer outboxUnlock();
    var changed = false;
    for (&g_outbox) |*e| {
        if (!e.used or e.sending) continue;
        // A note that LANDED is let go once it has been on screen long enough to
        // read. A note that did not is KEPT: erasing it would be the app quietly
        // dropping something the reader wrote, which is the one thing this queue
        // exists to prevent. It stops asking, and it stays visible as stuck.
        if (e.acked != 0 and now_s - e.queued_at > outbox_sent_linger_s) {
            e.* = .{};
            changed = true;
        }
    }
    if (changed) _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// How long a sent note stays in the queue so the reader can see that it landed.
const outbox_sent_linger_s: i64 = 20;
/// The revision last written to disk, so the queue is saved when it changes and
/// not on every tick.
var g_outbox_saved_rev: u32 = 0;

/// The queue's own seams, so a test drives the real state machine rather than a
/// copy of it.
pub fn resetOutboxForTest() void {
    outboxLock();
    defer outboxUnlock();
    for (&g_outbox) |*e| e.* = .{};
    g_outbox_woke_at.store(0, .monotonic);
    g_outbox_woke_ever.store(false, .monotonic);
}

pub fn outboxStateForTest(id: [32]u8) ?OutboxState {
    outboxLock();
    defer outboxUnlock();
    const e = outboxEntryFor(id) orelse return null;
    return e.state();
}

pub fn outboxRoundsForTest(id: [32]u8) ?u8 {
    outboxLock();
    defer outboxUnlock();
    const e = outboxEntryFor(id) orelse return null;
    return e.rounds;
}

pub fn enqueueOutboxForTest(id: [32]u8, author: [32]u8, now_s: i64) bool {
    return enqueueOutbox(id, author, now_s);
}

pub fn recordOutboxAckForTest(id: [32]u8, relay_index: usize, accepted: bool) void {
    recordOutboxAck(id, relay_index, accepted);
}

pub fn countOutboxRoundForTest(id: [32]u8) void {
    markOutboxSending(id, true);
    markOutboxSending(id, false);
}

pub fn sweepOutboxForTest(now_s: i64) void {
    sweepOutbox(now_s);
}

pub fn outboxRetryDelayForTest(rounds: u8) i64 {
    return outboxRetryDelay(rounds);
}

pub const rounds_before_stuck_for_test = rounds_before_stuck;
pub const outbox_sent_linger_for_test = outbox_sent_linger_s;

/// A fingerprint of the pool, in slot order. The outbox records which relay took
/// a note as a BIT PER SLOT, so those bits only mean anything against the list
/// they were written for: after an edit, bit 2 may be a relay that never saw the
/// note. The fingerprint travels with the queue so a changed list is noticed
/// rather than silently misread.
fn relayListFingerprint() u64 {
    var h = std.hash.Wyhash.init(0);
    for (0..relaySlots()) |i| {
        const e = relayAt(i) orelse {
            h.update("-");
            continue;
        };
        h.update(e.url());
        h.update(if (e.write) "w" else ".");
    }
    return h.final();
}

/// Forgets which relays took what, keeping the notes themselves. Called when the
/// list changes: a note that was delivered will simply be offered again, and a
/// relay that already has it will say so, which is cheaper than remembering a
/// claim that may now name the wrong relay.
fn forgetOutboxAcks() void {
    outboxLock();
    defer outboxUnlock();
    var changed = false;
    for (&g_outbox) |*e| {
        // EVERY owed note, including one that gave up with no verdict at all.
        // Skipping those would skip exactly the notes an edit is meant to
        // rescue: a note is stuck because `rounds` ran out, and a note whose
        // relays all went silent has `acked == 0 and refused == 0`. Adding a
        // relay for a note that never went out has to give that note its rounds
        // back, or the new relay is never asked.
        if (!e.used) continue;
        if (e.acked == 0 and e.refused == 0 and e.rounds == 0) continue;
        e.acked = 0;
        e.refused = 0;
        e.rounds = 0;
        changed = true;
    }
    if (changed) _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// The queue's key in the store's generic table, one record PER ACCOUNT. The
/// events themselves are in the store's own event tables (we ingest what we
/// sign), so this holds only the index: which ids are owed, and what each relay
/// said.
///
/// Per account, because the sixteen slots in `g_outbox` are a scarce resource
/// and they belong to whoever is signed in. An account that logs out has its
/// queue written to its own record and its slots handed back; signing in reads
/// that record and nothing else. The alternative, leaving another account's
/// entries sitting in the array where they can never be sent, never acked and
/// therefore never reclaimed, wedges the queue: sixteen of them and the person
/// at the keyboard cannot publish at all, in silence.
const outbox_key_prefix = "outbox:";

/// The pre-account record, kept readable so a queue written by an older build is
/// not stranded. Each account claims its own share of it the first time it signs
/// in; whatever is left belongs to somebody else and stays put.
const legacy_outbox_key = "outbox";

fn outboxKeyFor(out: *[outbox_key_prefix.len + 64]u8, owner: [32]u8) []const u8 {
    @memcpy(out[0..outbox_key_prefix.len], outbox_key_prefix);
    var hex: [64]u8 = undefined;
    writeHexId(&hex, owner);
    @memcpy(out[outbox_key_prefix.len..][0..64], &hex);
    return out[0 .. outbox_key_prefix.len + 64];
}

/// Whose entries are in `g_outbox` right now. Null while signed out, when the
/// array is empty.
var g_outbox_owner: ?[32]u8 = null;

/// Writes the queue where a restart can find it. A note written on a train and
/// lost on landing is the worst thing a client can do, so this runs on every
/// change rather than at exit, which may never come.
fn saveOutbox() void {
    const store = g_store orelse return;
    // Nobody signed in means nothing of anybody's in the array, so there is no
    // record to write and nowhere to write it.
    const owner = g_outbox_owner orelse return;
    // Snapshotted under the lock, written outside it. `store.put` opens a write
    // transaction and commits it, which fsyncs and waits on LMDB's writer mutex
    // that the ingest threads hold: holding a SPINLOCK across that would burn a
    // core in every publisher and stall the frame that reads the queue. The lock
    // is only justified while it is what it claims to be, a few field writes.
    var entries: [outbox_cap]OutboxEntry = undefined;
    var n: usize = 0;
    outboxLock();
    for (&g_outbox) |*e| {
        if (!e.used) continue;
        entries[n] = e.*;
        n += 1;
    }
    outboxUnlock();

    // Room for every entry at its longest: 64 hex, four separators, a ten-digit
    // second, three small numbers and a newline. Sized at the worst case rather
    // than the typical one, because a short buffer would drop the LAST entries,
    // which is exactly when the queue matters most.
    var buf: [outbox_cap * 100 + 32]u8 = undefined;
    var w = std.Io.Writer.fixed(&buf);
    // The list those ack bits were recorded against, first.
    w.print("pool {d}\n", .{relayListFingerprint()}) catch return;
    for (entries[0..n]) |e| {
        var hex: [64]u8 = undefined;
        writeHexId(&hex, e.id);
        // A short write means the buffer was mis-sized, so nothing is written at
        // all: a truncated index would silently lose notes on the next start.
        w.print("{s}:{d}:{d}:{d}:{d}\n", .{ hex[0..], e.queued_at, e.acked, e.refused, e.rounds }) catch return;
    }
    var key_buf: [outbox_key_prefix.len + 64]u8 = undefined;
    store.put(outboxKeyFor(&key_buf, owner), w.buffered()) catch {};
}

fn writeHexId(out: *[64]u8, id: [32]u8) void {
    const hexdigits = "0123456789abcdef";
    for (id, 0..) |b, i| {
        out[i * 2] = hexdigits[b >> 4];
        out[i * 2 + 1] = hexdigits[b & 0x0f];
    }
}

/// Reads `owner`'s queue into the array, replacing whatever was there.
///
/// Anything whose event is no longer in the store is dropped: the index points
/// at events, and an index without its event is not something the reader can be
/// shown or the app can publish. Anything signed by somebody else is dropped
/// too, which only matters for the legacy record, and is the whole point of
/// reading it: each account takes its own share and leaves the rest.
fn loadOutbox(owner: [32]u8) void {
    const store = g_store orelse return;
    var key_buf: [outbox_key_prefix.len + 64]u8 = undefined;
    const raw = blk: {
        if (store.get(std.heap.page_allocator, outboxKeyFor(&key_buf, owner)) catch null) |own| break :blk own;
        if (store.get(std.heap.page_allocator, legacy_outbox_key) catch null) |legacy| break :blk legacy;
        // No record at all is an ANSWER, not a reason to leave the array alone:
        // this account's queue is empty, and whatever is in the slots belongs to
        // somebody else. Returning here without clearing is how the previous
        // account's notes stay in the next account's queue.
        clearOutboxSlots();
        return;
    };
    defer std.heap.page_allocator.free(raw);
    // Parsed and resolved first, installed second: every `getEvent` below opens a
    // read transaction, and the lock may not span IO.
    var parsed: [outbox_cap]OutboxEntry = undefined;
    var lines = std.mem.tokenizeScalar(u8, raw, '\n');
    // Whether the ack bits still refer to the relays they were written for.
    var same_pool = false;
    var n: usize = 0;
    while (lines.next()) |line| {
        if (std.mem.startsWith(u8, line, "pool ")) {
            const saved = std.fmt.parseInt(u64, line["pool ".len..], 10) catch 0;
            same_pool = saved == relayListFingerprint();
            continue;
        }
        if (n == parsed.len) break;
        var parts = std.mem.splitScalar(u8, line, ':');
        const hex = parts.next() orelse continue;
        if (hex.len != 64) continue;
        var id: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&id, hex) catch continue;
        const queued_at = std.fmt.parseInt(i64, parts.next() orelse "0", 10) catch continue;
        const acked = std.fmt.parseInt(u8, parts.next() orelse "0", 10) catch 0;
        const refused = std.fmt.parseInt(u8, parts.next() orelse "0", 10) catch 0;
        const rounds = std.fmt.parseInt(u8, parts.next() orelse "0", 10) catch 0;
        // The event has to still be there, or there is nothing to publish.
        const se = (store.getEvent(std.heap.page_allocator, id) catch continue) orelse continue;
        var owned = se;
        // The author comes from the event, which is why it is not in the file.
        const author = owned.event.pubkey;
        owned.deinit();
        // Somebody else's, which the legacy record can hold. Theirs to keep, so
        // it is left in that record rather than taken or dropped.
        if (!std.mem.eql(u8, &author, &owner)) continue;
        // A note is kept whatever the list did; only the CLAIMS about who has it
        // are dropped, so it is offered again rather than assumed delivered.
        parsed[n] = if (same_pool)
            .{ .used = true, .id = id, .author = author, .queued_at = queued_at, .acked = acked, .refused = refused, .rounds = rounds }
        else
            .{ .used = true, .id = id, .author = author, .queued_at = queued_at };
        n += 1;
    }
    outboxLock();
    defer outboxUnlock();
    // The WHOLE array, not the first n. This replaces one account's queue with
    // another's, so anything past the new entries has to go, or the tail of the
    // previous account's queue survives in the slots nobody overwrote.
    g_outbox = [_]OutboxEntry{.{}} ** outbox_cap;
    for (parsed[0..n], g_outbox[0..n]) |src, *dst| dst.* = src;
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// Empties the sixteen slots. The notes themselves are events in the store and
/// their index is in a per-account record, so this hands slots back rather than
/// destroying anything.
fn clearOutboxSlots() void {
    outboxLock();
    g_outbox = [_]OutboxEntry{.{}} ** outbox_cap;
    outboxUnlock();
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// Which queued notes the next drain will actually send, stamping each one's
/// attempt as it goes.
///
/// Split out of `drainOutbox` so the choice can be tested without a store and
/// without spawning publishers. The choice IS the safety property: the drain
/// itself is a loop that reads events and hands them to threads, and every
/// question worth asking about who may publish what is answered here.
fn collectOutboxDue(ids: *[outbox_cap][32]u8, now_s: i64) usize {
    var n: usize = 0;
    outboxLock();
    defer outboxUnlock();
    for (&g_outbox) |*e| {
        if (!e.used or e.sending or e.acked != 0) continue;
        // Somebody else's note. This is the line that stops the previous
        // account's unsent writing going out over the next account's relays,
        // and signed out it stops everything, because a queued note is a promise
        // to one account and there is nobody here to keep it for.
        if (!outboxEntryIsMine(e.*)) continue;
        // Spaced out, and widening: the drain runs every tick, so without this a
        // transient failure (a captive portal, a TLS error, a relay that takes
        // the socket and refuses the publish) would burn every round in seconds
        // and leave the note stuck a moment after it was written.
        if (e.last_try_at != 0 and now_s - e.last_try_at < outboxRetryDelay(e.rounds)) continue;
        if (n == ids.len) break;
        e.last_try_at = now_s;
        ids[n] = e.id;
        n += 1;
    }
    return n;
}

pub fn collectOutboxDueForTest(ids: *[outbox_cap][32]u8, now_s: i64) usize {
    return collectOutboxDue(ids, now_s);
}

pub fn syncOutboxOwnerForTest() void {
    syncOutboxOwner();
}

pub fn loadOutboxForTest(owner: [32]u8) void {
    loadOutbox(owner);
}

pub fn saveOutboxForTest() void {
    saveOutbox();
}

pub fn outboxOwnerForTest() ?[32]u8 {
    return g_outbox_owner;
}

pub fn clearOutboxOwnerForTest() void {
    g_outbox_owner = null;
}

pub fn outboxAuthorAtForTest(i: usize) ?[32]u8 {
    outboxLock();
    defer outboxUnlock();
    if (!g_outbox[i].used) return null;
    return g_outbox[i].author;
}

pub fn outboxUsedSlotsForTest() usize {
    outboxLock();
    defer outboxUnlock();
    var n: usize = 0;
    for (&g_outbox) |*e| {
        if (e.used) n += 1;
    }
    return n;
}

pub const outbox_cap_for_test = outbox_cap;

/// Hands the sixteen slots to whoever is signed in, whenever that changes.
///
/// ONE place, called from the tick before anything reads the queue, because
/// getting it wrong in two places is how the previous account's notes end up in
/// the next account's queue. The leaving account's entries are written to their
/// own record first and only then cleared, so nothing is dropped: they are
/// parked, not deleted, and reading them back is what signing in again does.
///
/// This is what keeps `outboxEntryIsMine` an invariant rather than a load-
/// bearing filter. Leaving foreign entries in the array and merely refusing to
/// send them looks safe and is not: nothing can ever ack them, so nothing can
/// ever sweep or evict them either, and sixteen of them stop the person at the
/// keyboard publishing anything at all, with no counter, no popover row and no
/// banner to say why.
fn syncOutboxOwner() void {
    const now_owner = activePubkey();
    if (g_outbox_owner) |had| {
        if (now_owner) |now| if (std.mem.eql(u8, &had, &now)) return;
    } else if (now_owner == null) return;

    // Park the leaving account's queue before the slots are handed over.
    if (g_outbox_owner != null) {
        saveOutbox();
        clearOutboxSlots();
    }
    g_outbox_owner = now_owner;
    if (now_owner) |owner| loadOutbox(owner) else clearOutboxSlots();
    // The queue on disk is already current for both accounts, so the tick's
    // save-on-change is told not to write the freshly loaded one straight back.
    g_outbox_saved_rev = g_outbox_rev.load(.monotonic);
}

/// Offers every note that nobody has taken to the relays again. Called when a
/// relay comes back, which is the moment the answer might have changed.
fn drainOutbox(gpa: std.mem.Allocator) void {
    const store = g_store orelse return;
    var ids: [outbox_cap][32]u8 = undefined;
    const n = collectOutboxDue(&ids, nowSeconds());
    for (ids[0..n]) |id| {
        var se = (store.getEvent(gpa, id) catch continue) orelse continue;
        defer se.deinit();
        // COPIED, not borrowed. `StoredEvent.deinit` tears down the arena that
        // backs the content and the tags, and it would fire at the end of this
        // iteration, while the detached publisher is still serialising them.
        // `ingestAndPublish` states the same rule for its own path: what the
        // publisher reads has to outlive the call that spawned it.
        const owned = dupeEventForPublish(se.event) orelse continue;
        const thread = std.Thread.spawn(.{}, publishOwnedWorker, .{ gpa, owned }) catch {
            freePublishedEvent(owned);
            continue;
        };
        thread.detach();
    }
}

/// A process-lifetime copy of an event, for handing to a detached publisher.
/// Returns null when the copy cannot be made, in which case nothing is spawned.
fn dupeEventForPublish(ev: nostr.event.Event) ?nostr.event.Event {
    const gpa = std.heap.page_allocator;
    var out = ev;
    out.content = gpa.dupe(u8, ev.content) catch return null;
    const tags = gpa.alloc(nostr.event.Tag, ev.tags.len) catch {
        gpa.free(out.content);
        return null;
    };
    var filled: usize = 0;
    errdefer {
        for (tags[0..filled]) |t| {
            for (t) |field| gpa.free(field);
            gpa.free(t);
        }
        gpa.free(tags);
        gpa.free(out.content);
    }
    for (ev.tags, tags) |src, *dst| {
        const fields = gpa.alloc([]const u8, src.len) catch return null;
        var wrote: usize = 0;
        for (src, fields) |field, *slot| {
            slot.* = gpa.dupe(u8, field) catch {
                for (fields[0..wrote]) |f| gpa.free(f);
                gpa.free(fields);
                return null;
            };
            wrote += 1;
        }
        dst.* = fields;
        filled += 1;
    }
    out.tags = tags;
    return out;
}

/// Frees what `dupeEventForPublish` allocated.
fn freePublishedEvent(ev: nostr.event.Event) void {
    const gpa = std.heap.page_allocator;
    for (ev.tags) |t| {
        for (t) |field| gpa.free(field);
        gpa.free(t);
    }
    gpa.free(ev.tags);
    gpa.free(ev.content);
}

/// The drain's worker: publishes a copy it owns, and frees it when the walk is
/// over rather than leaving it to a caller that has already moved on.
fn publishOwnedWorker(gpa: std.mem.Allocator, ev: nostr.event.Event) void {
    defer freePublishedEvent(ev);
    publishWorker(gpa, ev);
}

/// Publishes `ev` to every relay in the pool, each on a throwaway connection,
/// best-effort. Posting is a rare, human-paced action, so a fresh dial per post
/// keeps the ingest loops untouched; the note is already in the local store, so
/// the feed shows it regardless of publish latency. Runs on a detached thread
/// with its own io backend, never the UI thread's.
/// At most this many of one recipient's read relays are added for a publish.
///
/// Jumble takes five, welshman's default scenario limit is three. Three is the
/// smaller of the two and still means a person has to have lost three relays at
/// once to miss a reply.
const inbox_relays_per_recipient = 3;
/// A ceiling on the whole extra set, so a note naming a dozen people does not
/// turn one Post into thirty dials.
const max_extra_inbox_relays = 8;

/// Publishes `ev` to the relays the people it names actually READ from.
///
/// Plaza sent every note to the reader's own write relays and nowhere else. If
/// the person being replied to does not read those relays, their client never
/// sees the reply and never tells them: a thread started from Plaza reads
/// one-sided to everybody else in it. Plaza's own inbox subscription is the
/// mirror of this and is correct, so the app was receiving what others routed
/// to it and not reciprocating.
///
/// Best effort, and deliberately not recorded in the outbox. An acknowledgement
/// there is a bit in a per-slot bitmap and these relays hold no slot; more to
/// the point, "did my note go out" is a question about the reader's own relays,
/// and a stranger's inbox relay refusing an unknown pubkey is normal rather
/// than a delivery failure worth alarming them about.
fn publishToRecipientInboxes(gpa: std.mem.Allocator, io: std.Io, ev: nostr.event.Event) void {
    const store = g_store orelse return;

    // Who the note names. The author is skipped: a reply to yourself does not
    // need routing, and the pool already carries it.
    var recipients: [max_extra_inbox_relays * 2][32]u8 = undefined;
    var n: usize = 0;
    for (ev.tags) |tag| {
        if (n == recipients.len) break;
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "p") or tag[1].len != 64) continue;
        var pk: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&pk, tag[1]) catch continue;
        if (std.mem.eql(u8, &pk, &ev.pubkey)) continue;
        var dupe = false;
        for (recipients[0..n]) |seen| {
            if (std.mem.eql(u8, &seen, &pk)) dupe = true;
        }
        if (dupe) continue;
        recipients[n] = pk;
        n += 1;
    }
    if (n == 0) return;

    const kinds = [_]u16{relay_list_kind};
    var result = store.query(gpa, .{ .authors = recipients[0..n], .kinds = &kinds, .limit = @intCast(n) }) catch return;
    defer result.deinit();

    var urls: [max_extra_inbox_relays][96]u8 = undefined;
    var url_len: [max_extra_inbox_relays]usize = undefined;
    var urls_n: usize = 0;

    for (result.events) |list_ev| {
        var parsed = nostr.nip65.parseRelayList(gpa, list_ev) catch continue;
        defer parsed.deinit();
        var taken: usize = 0;
        for (parsed.list.entries) |entry| {
            if (taken == inbox_relays_per_recipient or urls_n == urls.len) break;
            // Where they READ. A relay they only write to will never show them
            // anything, so a reply left there is a reply nobody receives.
            if (!entry.read) continue;
            const trimmed = std.mem.trim(u8, entry.url, " \t\r\n");
            if (trimmed.len == 0 or trimmed.len > 96) continue;
            // Already covered by the pool walk, so dialling it again would only
            // publish the same note twice to the same host.
            if (poolHasRelay(trimmed)) continue;
            var already = false;
            for (0..urls_n) |i| {
                if (std.mem.eql(u8, urls[i][0..url_len[i]], trimmed)) already = true;
            }
            if (already) continue;
            @memcpy(urls[urls_n][0..trimmed.len], trimmed);
            url_len[urls_n] = trimmed.len;
            urls_n += 1;
            taken += 1;
        }
    }

    for (0..urls_n) |i| {
        const url = urls[i][0..url_len[i]];
        var relay = nostr.relay.dial(gpa, io, url) catch continue;
        defer relay.deinit();
        relay.publish(ev) catch continue;
        // One read, to give the frame somewhere to flush to. The verdict is not
        // recorded, so there is nothing to wait around for.
        var msg = (relay.receive() catch continue) orelse continue;
        msg.deinit();
    }
}

/// Whether `url` is already one of the reader's own relays.
pub fn poolHasRelayForTest(url: []const u8) bool {
    return poolHasRelay(url);
}

fn poolHasRelay(url: []const u8) bool {
    for (0..relaySlots()) |i| {
        var buf: [96]u8 = undefined;
        const entry = relaySnapshot(i, &buf) orelse continue;
        // The pool's own comparison, which knows that a trailing slash and a
        // difference of case are the same relay. Two spellings here would mean
        // publishing the same note to the same host twice.
        if (relayUrlEql(entry.url, url)) return true;
    }
    return false;
}

fn publishEvent(gpa: std.mem.Allocator, ev: nostr.event.Event) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();

    for (0..relaySlots()) |i| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(i, &url_buf) orelse continue;
        // Only where the reader asked to be published. The slot index is what
        // the outbox records an acknowledgement against, which is why a slot is
        // never reused for a different relay while the process lives.
        if (!entry.write) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();
        relay.publish(ev) catch continue;
        // The relay's OK is the answer to "is my note out there", so it is READ
        // rather than merely waited for: which relay took it, and which refused,
        // is the whole content of the outbox. A relay may say other things
        // first (a NOTICE, an EVENT for an open subscription), so this reads
        // until it sees a verdict for THIS id or runs out of patience.
        var seen: usize = 0;
        while (seen < max_publish_messages) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .ok => |ok| {
                    if (!std.mem.eql(u8, &ok.event_id, &ev.id)) continue;
                    // An ack is recorded against a SLOT, and this walk has been
                    // blocked on a socket long enough for the reader to have
                    // removed the relay or put another one in its seat. Record
                    // it only if the seat still holds the relay that answered,
                    // or the note would be reported as delivered to a relay that
                    // never saw it.
                    var still_buf: [96]u8 = undefined;
                    const still = relaySnapshot(i, &still_buf) orelse break;
                    if (!relayUrlEql(still.url, entry.url)) break;
                    recordOutboxAck(ev.id, i, ok.accepted);
                    break;
                },
                else => continue,
            }
        }
    }

    // And where the people it names actually read, which the reader's own
    // relays say nothing about.
    publishToRecipientInboxes(gpa, io, ev);
}

/// How many frames to read from one relay while waiting for its verdict. A relay
/// with a busy subscription can have several in front of the OK; past this it is
/// not answering about this note.
const max_publish_messages = 8;

// ------------------------------------------------------------------------ threads
//
// A thread is the focused note plus the kind:1 replies that e-tag it. It is
// layered OVER the feed, which stays mounted so its scroll offset survives.
// Opening one snapshots the root, reads any replies already in the store, and
// fires a one-shot fetch of the rest (with their engagement) into the store; the
// replies are cached in the model so they are pressable (open as a sub-thread)
// and get their pictures fetched, the same local-first path the feed uses.

/// Opens `note_id` as a thread. The target may live in the feed or the current
/// thread; it is snapshotted as the new root so it survives store rebuilds. When
/// a thread is already open, the current root is pushed so Back returns to it.
fn openThread(model: *Model, note_id: i64) void {
    const target = model.noteById(note_id) orelse return;
    enterThread(model, target.*);
}

/// Focuses `root` as the open thread: pushes the current thread (if any) onto
/// the back-stack, snapshots the new root, and fires its reply fetch. Shared by
/// open-a-feed-note, open-a-reply, and open-a-quoted-note.
fn enterThread(model: *Model, root: Note) void {
    pushCurrentScreen(model);
    model.viewing_profile = null;
    model.viewing_thread = root.id;
    model.thread_root = root;
    model.thread_notes_len = 0;
    model.reply_buffer.clear();
    // The level being opened starts at its first page with its held section
    // closed. Only this level: the ones underneath keep what the reader left
    // them holding. The arrival table needs no reset either, since it is keyed
    // by the level's root and discards itself when it finds another thread.
    model.thread_page[model.currentLevel()] = 1;
    model.thread_outside_open[model.currentLevel()] = false;
    wantProfile(root.pubkey);
    // The fetch is claimed BEFORE the first build, because that build asks
    // whether this level's fetch has settled: against the previous level's
    // sequence it would answer yes, mark the table settled before a single
    // reply had landed, and put the whole opening read back into relay-answer
    // order, which is the thing arrival batching exists to prevent.
    const now = nowSeconds();
    const seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
    model.thread_seq = seq;
    model.thread_open_at = now;
    model.refreshThreadNotes(now);
    model.thread_loading = model.thread_notes_len == 0;
    fetchThreadReplies(root.event_id, seq);
}

/// The level bookkeeping, for a test that walks a stack up and down. Both take
/// the same paths the app does, so what they assert is what a reader gets.
pub fn enterThreadForTest(model: *Model, root: Note) void {
    enterThread(model, root);
}

pub fn closeThreadForTest(model: *Model) void {
    closeThread(model);
}

/// Pushes whatever level is open, so Back returns to it. A no-op at the feed,
/// and a no-op at the depth cap, which is the same rule threads always had.
fn pushCurrentScreen(model: *Model) void {
    if (model.thread_stack_len >= model.thread_stack.len) return;
    if (model.viewing_profile) |pk| {
        model.thread_stack[model.thread_stack_len] = .{ .profile = pk };
        model.thread_stack_len += 1;
        return;
    }
    if (model.viewing_thread != 0) {
        model.thread_stack[model.thread_stack_len] = .{ .note = model.thread_root };
        model.thread_stack_len += 1;
    }
}

/// The filters that ask for notes older than `until`.
///
/// Chunked exactly like the live subscription, and for the same reason: a relay
/// refuses a filter whose field items exceed its size cap. Separate from
/// `buildFeedFilters` because this asks for notes and nothing else: profiles
/// and relay lists are replaceable, so there is no older copy to page back to.
pub fn buildOlderFilters(
    authors: []const [32]u8,
    until: i64,
    out: []nostr.filter.Filter,
) []nostr.filter.Filter {
    var len: usize = 0;
    var start: usize = 0;
    while (start < authors.len and len < out.len) : (start += follow_chunk) {
        const chunk = authors[start..@min(start + follow_chunk, authors.len)];
        out[len] = .{
            .authors = chunk,
            .kinds = &feed_filter_kinds,
            .until = until,
            .limit = feed_page,
        };
        len += 1;
    }
    return out[0..len];
}

/// Whether an older-notes fetch is already in flight, so a reader who keeps
/// scrolling does not stack one request per frame.
var g_older_busy = std.atomic.Value(bool).init(false);
/// Set when a network round for older notes came back with nothing new, which
/// is the only honest way to know the feed has an end.
var g_feed_end_reached = std.atomic.Value(bool).init(false);

pub fn feedEndReached() bool {
    return g_feed_end_reached.load(.monotonic);
}

pub fn resetFeedEndForTest() void {
    g_feed_end_reached.store(false, .monotonic);
    g_older_busy.store(false, .monotonic);
}

/// Asks the relays for notes older than `until`.
///
/// Reaching the end of the loaded feed used to raise the store's query limit
/// and nothing else. The store answers with what it has, so once the initial
/// backfill was exhausted the list simply stopped growing: no older history, no
/// end-of-feed state, and no way to reach anything from before the app was
/// opened. A reader coming back after a week saw the last few hundred notes and
/// could not scroll past them. Grepping this file for `.until` returned nothing
/// at all, which is the whole bug: no filter Plaza ever sent carried one.
///
/// Store first, network second, which is Jumble's ordering: `_loadMoreTimeline`
/// serves from its cached list and only then asks with `{ ...filter, until }`.
fn fetchOlderNotes(until: i64) void {
    if (g_store == null) return;
    // One at a time. Sitting at the bottom of the list fires this on every
    // frame, and each round is a dial per relay.
    if (g_older_busy.swap(true, .acq_rel)) return;
    const thread = std.Thread.spawn(.{}, fetchOlderWorker, .{until}) catch {
        g_older_busy.store(false, .release);
        return;
    };
    thread.detach();
}

fn fetchOlderWorker(until: i64) void {
    const gpa = std.heap.page_allocator;
    defer g_older_busy.store(false, .release);
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    var authors: [max_follows + 1][32]u8 = undefined;
    var authors_len: usize = 0;
    if (activePubkey()) |pk| {
        authors[authors_len] = pk;
        authors_len += 1;
    }
    for (followSet()) |pk| {
        if (authors_len == authors.len) break;
        authors[authors_len] = pk;
        authors_len += 1;
    }
    if (authors_len == 0) return;

    var filters: [max_feed_filters]nostr.filter.Filter = undefined;
    const built = buildOlderFilters(authors[0..authors_len], until, &filters);
    const flen = built.len;

    var added: usize = 0;
    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();
        relay.subscribe("plaza-older", filters[0..flen]) catch continue;
        var seen: usize = 0;
        // Bounded: `receive` has no deadline, and a relay that takes the
        // subscription and then goes quiet would hold this thread forever.
        while (seen < profile_fetch_messages) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    const result = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch continue;
                    if (result == .added) added += 1;
                },
                .eose => break,
                .closed => break,
                else => {},
            }
        }
        relay.unsubscribe("plaza-older") catch {};
    }

    // Nothing anywhere had anything older. That is an end, and saying so is
    // better than a spinner that never resolves.
    if (added == 0) g_feed_end_reached.store(true, .monotonic);
}

/// Opens a person as a level of their own.
fn enterProfile(model: *Model, pubkey: [32]u8) void {
    // Already here. Pressing a face on somebody's own page would otherwise push
    // a second copy of the same person and cost a Back to undo.
    if (model.viewing_profile) |current| {
        if (std.mem.eql(u8, &current, &pubkey)) return;
    }
    pushCurrentScreen(model);
    model.viewing_profile = pubkey;
    model.viewing_thread = 0;
    model.thread_notes_len = 0;
    model.note_menu = 0;
    model.reply_buffer.clear();
    wantProfile(pubkey);
    model.profile_tab = .notes;
    const now = nowSeconds();
    const seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
    model.thread_seq = seq;
    model.thread_open_at = now;
    model.refreshProfileNotes(now);
    model.thread_loading = model.thread_notes_len == 0;
    fetchProfileNotes(pubkey, seq);
}

pub fn enterProfileForTest(model: *Model, pubkey: [32]u8) void {
    enterProfile(model, pubkey);
}

/// Opens an event (by its full id) as a thread, reading it straight from the
/// store. `openThread` cannot: it resolves the render key through the feed and
/// the open thread, and a quoted note or an ANCESTOR is in neither. Both press
/// this instead, and both only ever fire for an event already ingested (an
/// unresolved quote card is not pressable, and an ancestor row exists because
/// the walk found the event).
fn openEvent(model: *Model, id: [32]u8) void {
    if (g_store) |store| {
        if (store.getEvent(std.heap.page_allocator, id) catch null) |found| {
            var se = found;
            defer se.deinit();
            enterThread(model, noteFrom(se.event, nowSeconds()));
            return;
        }
    }
    // Not held. This is reachable from a notification, whose target is whatever
    // note the thing was about, and that note is often one nobody asked any relay
    // for: a stranger's parent in a thread the reader was named in, or the
    // reader's own note from before this install. Silence here is the worst
    // answer, because the row looks alive and is not. So ask for it, and say so.
    wantQuote(id);
    setToast(model, "Fetching that note");
}

/// Back to the feed from wherever the reader has got to, in one press.
///
/// Not a Back: it drops the whole stack rather than one level, because the mark
/// in the corner of the rail is a destination and not a step. Settings is left,
/// any open person or thread is closed, and the overlays that live above the
/// feed go with them, since landing on the feed behind a panel is not landing
/// on the feed.
///
/// The sheets that ask the reader something (signing in, naming a fresh key)
/// are deliberately NOT touched here. They are questions with an answer owed,
/// and dismissing one as a side effect of navigating is how a remembered intent
/// gets dropped.
fn goHome(model: *Model) void {
    model.thread_stack_len = 0;
    model.viewing_profile = null;
    model.viewing_thread = 0;
    model.thread_loading = false;
    model.thread_notes_len = 0;
    model.reply_buffer.clear();
    model.note_menu = 0;
    model.menu = .none;
    model.notifications_open = false;
    model.stage = .ready;
}

pub fn goHomeForTest(model: *Model) void {
    goHome(model);
}

/// Closes the open thread: pops the back-stack to the thread it was opened from,
/// or returns to the feed (which kept its scroll offset) when the stack is empty.
fn closeThread(model: *Model) void {
    // The level being left is the one that resets: the level underneath keeps
    // its pages, its held section and its arrival order, which is what makes the
    // walk back land where the reader left it.
    model.thread_page[model.currentLevel()] = 1;
    model.thread_outside_open[model.currentLevel()] = false;
    model.reply_buffer.clear();
    model.thread_notes_len = 0;
    model.note_menu = 0;
    if (model.thread_stack_len > 0) {
        model.thread_stack_len -= 1;
        const prev = model.thread_stack[model.thread_stack_len];
        // Same ordering as `enterThread`, and for the same reason.
        const now = nowSeconds();
        const seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
        model.thread_seq = seq;
        model.thread_open_at = now;
        if (prev.profile) |pk| {
            model.viewing_profile = pk;
            model.viewing_thread = 0;
            model.refreshProfileNotes(now);
            model.thread_loading = model.thread_notes_len == 0;
            fetchProfileNotes(pk, seq);
        } else {
            model.viewing_profile = null;
            model.viewing_thread = prev.note.id;
            model.thread_root = prev.note;
            model.refreshThreadNotes(now);
            model.thread_loading = model.thread_notes_len == 0;
            fetchThreadReplies(prev.note.event_id, seq);
        }
    } else {
        model.viewing_profile = null;
        model.viewing_thread = 0;
        model.thread_loading = false;
        // Back to where the reader actually came from. The list is rebuilt from
        // the same inbox and the window keeps its offset on the list's own id,
        // so this lands on the row they pressed rather than at the top.
        if (model.notifications_return) {
            model.notifications_return = false;
            model.notifications_open = true;
        }
    }
}

// The open-thread generation, so a reply fetch can report completion for the
// thread it was launched for and not a later one. `g_thread_seq` is bumped on
// each open; the worker copies its seq and, when it has asked every relay,
// stores it into `g_thread_done_seq`. The UI thread clears the loading skeletons
// only when the CURRENT thread's fetch is the one that finished (so a genuinely
// empty thread stops loading, but a stale late worker never clears a new thread).
var g_thread_seq = std.atomic.Value(u64).init(0);
var g_thread_done_seq = std.atomic.Value(u64).init(0);

/// Fetches a person's recent notes (and their engagement) into the store, on a
/// detached thread. Mirrors the thread's two-phase backfill exactly: one dial per
/// read relay, their kind:1s, then on EOSE a second subscription for what those
/// notes collected, folding into the same engagement table the feed and threads
/// use. Without the second phase every row on a profile shows zero counts.
fn fetchProfileNotes(pubkey: [32]u8, seq: u64) void {
    if (g_store == null) {
        g_thread_done_seq.store(seq, .release);
        return;
    }
    const thread = std.Thread.spawn(.{}, fetchProfileWorker, .{ pubkey, seq }) catch {
        g_thread_done_seq.store(seq, .release);
        return;
    };
    thread.detach();
}

fn fetchProfileWorker(pubkey: [32]u8, seq: u64) void {
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    defer g_thread_done_seq.store(seq, .release);

    const kinds = [_]u16{1};
    const authors = [_][32]u8{pubkey};
    // Their profile too: the screen needs an about, a banner and a lud16, none
    // of which the name-and-face cache models.
    const meta_kinds = [_]u16{ 0, contact_list_kind };
    const filters = [_]nostr.filter.Filter{
        .{ .authors = &authors, .kinds = &kinds, .limit = thread_reply_cap },
        .{ .authors = &authors, .kinds = &meta_kinds, .limit = 2 },
    };

    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();
        relay.subscribe("plaza-person", &filters) catch continue;

        var ids: [engagement_watch_cap][64]u8 = undefined;
        var watch: [engagement_watch_cap]i64 = undefined;
        var watch_len: usize = 0;
        var id_count: usize = 0;
        var engagement_open = false;
        var seen: usize = 0;
        // Bounded, because `relay.receive()` has no deadline and a relay that
        // accepts a subscription and then goes quiet would hold this thread for
        // the life of the process.
        while (seen < profile_fetch_messages) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    // Phase 2's answers are REACTIONS, and a reaction that is
                    // only stored changes no count on any row: the table the
                    // rows read is filled by `countEngagement`, which is the
                    // whole reason phase 2 exists.
                    if (engagement_open) {
                        if (nostr.event.verify(gpa, signer, e.event) catch false)
                            countEngagement(e.event, watch[0..watch_len]);
                        continue;
                    }
                    const result = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch continue;
                    if (result == .invalid) continue;
                    if (e.event.kind == 1 and id_count < ids.len) {
                        hexLower(&ids[id_count], e.event.id);
                        watch[watch_len] = noteIdOf(e.event);
                        watch_len += 1;
                        id_count += 1;
                    }
                },
                .eose => {
                    if (engagement_open or id_count == 0) break;
                    engagement_open = true;
                    var evals: [engagement_watch_cap][]const u8 = undefined;
                    for (0..id_count) |i| evals[i] = &ids[i];
                    const eng_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = evals[0..id_count] }};
                    const eng_filters = [_]nostr.filter.Filter{engagementFilter(&eng_tags)};
                    relay.subscribe("plaza-person-engagement", &eng_filters) catch break;
                },
                .closed => break,
                else => continue,
            }
        }
    }
}

/// How many frames one relay gets to answer a profile's backfill before this
/// thread moves on. See the comment in `fetchProfileWorker`.
const profile_fetch_messages = 400;

/// One engagement query over prepared `#e` values.
///
/// Three screens ask this same question, and each used to write it out again.
/// They drifted: the thread and the profile capped the answer, and the feed's,
/// which is the one re-issued on every reconnect, carried no cap at all, so a
/// busy relay decided how much of four kinds across 128 note ids to send back.
/// One function now, so there is nothing left to drift.
pub fn engagementFilter(tags: []const nostr.filter.TagFilter) nostr.filter.Filter {
    return .{ .kinds = &engagement_kinds, .tags = tags, .limit = engagement_request_limit };
}

/// Fetches a note's replies (and their engagement) into the store, on a detached
/// thread. One dial per relay: opening a thread is a rare, human-paced action, so
/// a throwaway connection keeps the ingest loops untouched, exactly like
/// publishing. `seq` tags the fetch so its completion is attributable.
fn fetchThreadReplies(root_id: [32]u8, seq: u64) void {
    // Nowhere to put the replies without a store; the guard also keeps tests,
    // which have no store, from dialing relays. Mark it done at once so the UI
    // does not wait on a fetch that never ran.
    if (g_store == null) {
        g_thread_done_seq.store(seq, .release);
        return;
    }
    const thread = std.Thread.spawn(.{}, fetchRepliesWorker, .{ root_id, seq }) catch {
        g_thread_done_seq.store(seq, .release);
        return;
    };
    thread.detach();
}

fn fetchRepliesWorker(root_id: [32]u8, seq: u64) void {
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    // The note the reader pressed, and the ROOT of the conversation it sits in.
    //
    // Usually the same note, and when they are not, asking only about the note
    // pressed asks a question almost nothing answers. NIP-10 says a reply
    // carries an `e` tag for the ROOT and one for its immediate parent, so a
    // grandchild of the note in the reader's hand names its own parent and the
    // root, and never the note in between. Opening a reply from the feed
    // therefore fetched that note's direct children and nothing else: no
    // siblings, no parent, no root post, and nothing under those children. The
    // ancestors then trickled in one hop at a time through the quote fetcher,
    // which is why an old conversation took several seconds to assemble.
    //
    // Both ids go into ONE filter. Keeping the pressed note in it is what makes
    // this safe when a root tag is missing, wrong, or points somewhere else:
    // that note's own children still match.
    var thread_ids: [2][32]u8 = undefined;
    var thread_count: usize = 1;
    thread_ids[0] = root_id;
    if (g_store) |store| {
        if (store.getEvent(gpa, root_id) catch null) |se| {
            var owned = se;
            defer owned.deinit();
            thread_count = threadQueryIds(root_id, owned.event.tags, &thread_ids);
        }
    }
    var thread_hex: [2][64]u8 = undefined;
    var thread_evals: [2][]const u8 = undefined;
    var thread_watch: [2]i64 = undefined;
    for (0..thread_count) |i| {
        hexLower(&thread_hex[i], thread_ids[i]);
        thread_evals[i] = &thread_hex[i];
        thread_watch[i] = @intCast(std.mem.readInt(u64, thread_ids[i][0..8], .big) & std.math.maxInt(i64));
    }

    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        // A read-only or read-write relay. Asking a write-only relay to answer
        // a filter is asking the wrong question of it.
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();

        // Phase 1: the replies themselves (kind:1 e-tagging the root). Collect
        // their ids as they arrive so phase 2 can watch their engagement too.
        var id_hex: [thread_reply_cap][64]u8 = undefined;
        var watch_ids: [thread_reply_cap + 2]i64 = undefined;
        var id_count: usize = 0;
        // The note pressed, and the conversation's root when that is a
        // different note, are both watched from the start so their own counts
        // refresh alongside the replies'.
        var watch_len: usize = 0;
        while (watch_len < thread_count) : (watch_len += 1) watch_ids[watch_len] = thread_watch[watch_len];

        const reply_kinds = [_]u16{1};
        const reply_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = thread_evals[0..thread_count] }};
        const reply_filters = [_]nostr.filter.Filter{.{ .kinds = &reply_kinds, .tags = &reply_tags, .limit = thread_reply_cap }};
        relay.subscribe("plaza-thread", &reply_filters) catch continue;
        while (true) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    _ = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch {};
                    // Queue the replier's profile so a name and face resolve.
                    wantProfile(e.event.pubkey);
                    if (id_count < thread_reply_cap) {
                        hexLower(&id_hex[id_count], e.event.id);
                        id_count += 1;
                        watch_ids[watch_len] = noteIdOf(e.event);
                        watch_len += 1;
                    }
                },
                .eose => break,
                else => {},
            }
        }

        // Phase 2: engagement on the root and every reply (replies, reposts,
        // likes, zaps), folded into the shared table so the thread shows real
        // metrics on each row, the same counts the feed shows.
        var evals: [thread_reply_cap + 2][]const u8 = undefined;
        var eval_len: usize = 0;
        while (eval_len < thread_count) : (eval_len += 1) evals[eval_len] = thread_evals[eval_len];
        for (0..id_count) |i| {
            evals[eval_len] = &id_hex[i];
            eval_len += 1;
        }
        const eng_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = evals[0..eval_len] }};
        const eng_filters = [_]nostr.filter.Filter{engagementFilter(&eng_tags)};
        relay.subscribe("plaza-thread-eng", &eng_filters) catch continue;
        while (true) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    if (nostr.event.verify(gpa, signer, e.event) catch false)
                        countEngagement(e.event, watch_ids[0..watch_len]);
                },
                .eose => break,
                else => {},
            }
        }
    }
    // Every relay has been asked: the reply set is as complete as it will get, so
    // the UI can stop showing loading skeletons even if nothing came back.
    g_thread_done_seq.store(seq, .release);
}

// ------------------------------------------------------- remote signer (NIP-46)
//
// Signing can be routed to an external signer (Notary) over NIP-46 so the user's
// secret key never enters Plaza. Plaza is the CLIENT: it holds an ephemeral
// transport keypair, and the user's identity is the bunker's own pubkey. The
// wire is kind:24133 events whose content is a NIP-44-encrypted request/response
// `p`-tagged to the recipient. A persistent listener thread holds the bunker
// relay and processes responses; each request (connect, then one per post) goes
// out on its own short-lived connection, so a blocked receive never stalls a
// send. A signed note returns as a response `result`, stored and published to
// the feed pool exactly like a locally signed one.

/// Pairs with an external signer from a `bunker://` URL: parses it, mints an
/// ephemeral client key, starts the response listener, and sends the connect
/// request. Returns false (and marks the status failed) on a bad URL.
fn connectRemoteSigner(url_raw: []const u8) bool {
    const url = std.mem.trim(u8, url_raw, " \t\r\n");
    const io = g_io orelse return false;
    const gpa = std.heap.page_allocator;

    var parsed = nostr.nip46.parseBunkerUri(gpa, url) catch {
        g_remote_status.store(3, .release);
        return false;
    };
    defer parsed.deinit();
    const bunker = parsed.value;
    if (bunker.relays.len == 0 or bunker.relays[0].len > g_remote_relay_buf.len) {
        g_remote_status.store(3, .release);
        return false;
    }
    const relay_url = bunker.relays[0];

    // Mint the ephemeral transport key (never the user's key).
    var signer = nostr.keys.Signer.init();
    const client_kp = signer.generateKeyPair(io) catch {
        signer.deinit();
        g_remote_status.store(3, .release);
        return false;
    };
    signer.deinit();

    // Stash the connection details for the worker threads.
    g_remote_pubkey = bunker.remote_signer_pubkey;
    @memcpy(g_remote_relay_buf[0..relay_url.len], relay_url);
    g_remote_relay_len = relay_url.len;
    if (bunker.secret) |s| {
        const n = @min(s.len, g_remote_secret_buf.len);
        @memcpy(g_remote_secret_buf[0..n], s[0..n]);
        g_remote_secret_len = n;
    } else g_remote_secret_len = 0;
    g_remote_client_kp = client_kp;

    // The user's identity is the bunker's pubkey.
    const npub = abbreviateNpub(&g_identity_npub_buf, g_remote_pubkey);
    g_identity_npub_len = npub.len;
    g_signer_kind = .remote;
    g_remote_status.store(1, .release);
    g_remote_sign_notice.store(false, .release);

    // A fresh generation: any prior listener (a reconnect to a second bunker)
    // stops processing, and every request registered from here carries it.
    const generation = g_remote_generation.fetchAdd(1, .monotonic) + 1;

    const thread = std.Thread.spawn(.{}, nip46ReceiveLoop, .{ gpa, generation }) catch {
        g_remote_status.store(3, .release);
        return false;
    };
    thread.detach();

    sendConnect(gpa);
    return true;
}

/// A request id nobody watching the relay can guess.
///
/// These were `req-0`, `req-1`, and so on, from a counter that starts at zero
/// on every launch. Our client pubkey is not a secret: it is the `p` tag on
/// every request we publish. Anyone reading the bunker's relay could therefore
/// address an answer to us and guess which request was in flight. They still
/// cannot read the request, and after the sender check above they cannot be
/// heard at all, but a request id should not be a countdown either.
///
/// Sixteen hex characters from the system CSPRNG, the same source the ephemeral
/// client key comes from.
fn newRequestId(out: *[24]u8) ?[]const u8 {
    const io = g_io orelse return null;
    var raw: [8]u8 = undefined;
    io.randomSecure(&raw) catch return null;
    return std.fmt.bufPrint(out, "{x}", .{raw}) catch null;
}

/// Sends the NIP-46 `connect` request (remote pubkey + optional secret).
fn sendConnect(gpa: std.mem.Allocator) void {
    var hexbuf: [64]u8 = undefined;
    hexLower(&hexbuf, g_remote_pubkey);
    var idbuf: [24]u8 = undefined;
    const req_id = newRequestId(&idbuf) orelse return;
    if (!registerPending(req_id, .connect, null, false)) return;
    const params = [_][]const u8{ &hexbuf, g_remote_secret_buf[0..g_remote_secret_len] };
    sendRequest(gpa, .{ .id = req_id, .method = "connect", .params = &params });
}

/// Remote path: build the unsigned event of `kind` (with `tags`, stamped
/// `created_at`) and send a `sign_event` request. The signed event returns to
/// the listener, which stores and publishes it. `restorable` is true only for a
/// composer draft, so a failed reaction never lands "+"-text in the composer.
fn requestRemoteSign(gpa: std.mem.Allocator, created_at: i64, kind: u16, tags: []const nostr.event.Tag, content_owned: []const u8, restorable: bool) void {
    // `content_owned` is handed to the pending slot (so a timeout can restore
    // it to the composer); it is freed here only on an early return.
    // A canonical unsigned event (the bunker fills in the signature). The id is
    // computed against the user's pubkey so the bunker's result matches it.
    const id = nostr.event.computeId(gpa, g_remote_pubkey, created_at, kind, tags, content_owned) catch {
        gpa.free(content_owned);
        return;
    };
    const unsigned = nostr.event.Event{
        .id = id,
        .pubkey = g_remote_pubkey,
        .created_at = created_at,
        .kind = kind,
        .tags = tags,
        .content = content_owned,
        .sig = [_]u8{0} ** 64,
    };
    const unsigned_json = nostr.event.toJson(gpa, unsigned) catch {
        gpa.free(content_owned);
        return;
    };
    defer gpa.free(unsigned_json);

    var idbuf: [24]u8 = undefined;
    const req_id = newRequestId(&idbuf) orelse {
        gpa.free(content_owned);
        return;
    };
    // Track before sending: the response can arrive on the listener thread the
    // instant the send lands, and it must find the pending slot already there.
    if (!registerPending(req_id, .sign_event, content_owned, restorable)) {
        gpa.free(content_owned);
        return;
    }
    const params = [_][]const u8{unsigned_json};
    sendRequest(gpa, .{ .id = req_id, .method = "sign_event", .params = &params });
}

/// Serializes `request` and spawns a one-shot thread to seal and publish it.
fn sendRequest(gpa: std.mem.Allocator, request: nostr.nip46.Request) void {
    const req_json = request.toJson(gpa) catch return;
    const thread = std.Thread.spawn(.{}, nip46Send, .{ gpa, req_json }) catch {
        gpa.free(req_json);
        return;
    };
    thread.detach();
}

/// Seals `req_json` to the remote signer and publishes it on a throwaway
/// connection to the bunker relay. Owns `req_json`. Its own io and signer.
fn nip46Send(gpa: std.mem.Allocator, req_json: []const u8) void {
    defer gpa.free(req_json);
    const client_kp = g_remote_client_kp orelse return;

    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    const created_at = std.Io.Timestamp.now(io, .real).toSeconds();
    var sealed = nostr.nip46.seal(gpa, io, signer, client_kp, g_remote_pubkey, req_json, created_at) catch return;
    defer sealed.deinit();

    var relay = nostr.relay.dial(gpa, io, g_remote_relay_buf[0..g_remote_relay_len]) catch return;
    defer relay.deinit();
    relay.publish(sealed.event) catch return;
    // Read the relay's OK so the frame flushes before we close; best-effort.
    var msg = (relay.receive() catch return) orelse return;
    msg.deinit();
}

/// The response listener: holds the bunker relay and processes responses,
/// reconnecting until its `generation` is superseded (a logout or a reconnect
/// bumps `g_remote_generation`). Its own io backend and signer, never the UI
/// thread's.
fn nip46ReceiveLoop(gpa: std.mem.Allocator, generation: u64) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const client_kp = g_remote_client_kp orelse return;

    while (generation == g_remote_generation.load(.acquire)) {
        nip46ReceiveOnce(gpa, io, signer, client_kp, generation) catch |err| {
            std.debug.print("plaza: [signer] {s}\n", .{@errorName(err)});
        };
        if (generation != g_remote_generation.load(.acquire)) break;
        io.sleep(std.Io.Duration.fromSeconds(3), .awake) catch {};
    }
}

/// Dials the bunker relay, subscribes for responses addressed to our client key
/// (`#p` = the ephemeral pubkey, which only our bunker knows), and handles each
/// until the connection drops or this listener's `generation` is superseded.
fn nip46ReceiveOnce(gpa: std.mem.Allocator, io: std.Io, signer: nostr.keys.Signer, client_kp: nostr.keys.KeyPair, generation: u64) !void {
    var relay = try nostr.relay.dial(gpa, io, g_remote_relay_buf[0..g_remote_relay_len]);
    defer relay.deinit();

    var client_hex: [64]u8 = undefined;
    hexLower(&client_hex, client_kp.public_key);
    const pvals = [_][]const u8{&client_hex};
    const tag_filters = [_]nostr.filter.TagFilter{.{ .letter = 'p', .values = &pvals }};
    const kinds = [_]u16{nostr.nip46.kind};
    // FROM THE SIGNER, addressed to us. The `p` tag alone is not a restriction:
    // our client pubkey is on every request we publish, so anyone reading the
    // relay can address an event to it. Naming the author is what makes this
    // subscription about a conversation with one party.
    //
    // `limit = 0` asks for nothing stored. Kind 24133 is ephemeral and a relay
    // should not be keeping it, but one that does would otherwise replay a
    // previous session's answers into this one.
    const authors = [_][32]u8{g_remote_pubkey};
    const filters = [_]nostr.filter.Filter{.{
        .authors = &authors,
        .kinds = &kinds,
        .tags = &tag_filters,
        .limit = 0,
    }};
    try relay.subscribe("plaza-nip46", &filters);

    while (generation == g_remote_generation.load(.acquire)) {
        var msg = (try relay.receive()) orelse break;
        defer msg.deinit();
        switch (msg.value) {
            .event => |e| handleNip46Response(gpa, signer, client_kp, e.event, generation),
            else => {},
        }
    }
}

/// Decrypts, parses, and correlates a NIP-46 response to the request that asked
/// for it. An error response flags its request so the UI restores the draft; a
/// `sign_event` result is verified, stored, and published to the feed pool (the
/// remote equivalent of the local post path); a `connect` ack marks connected.
/// An unknown or already-handled id is dropped, so a duplicate never publishes
/// twice and a stale session's response never lands.
fn handleNip46Response(gpa: std.mem.Allocator, signer: nostr.keys.Signer, client_kp: nostr.keys.KeyPair, ev: nostr.event.Event, generation: u64) void {
    if (generation != g_remote_generation.load(.acquire)) return;
    // Only the signer this session connected to.
    //
    // A relay filter is a request, not a guarantee, and this one has to hold on
    // its own because of how NIP-44 works: the conversation key is derived from
    // the SENDER's key, so an event from anybody decrypts successfully as long
    // as they encrypted it to our client key. That key is public. Without this
    // line, a stranger who guesses the id of a request in flight can answer it,
    // and the answer is either an event we then publish from the reader's
    // machine to the reader's relays, or a failure that discards their note.
    if (!std.mem.eql(u8, &ev.pubkey, &g_remote_pubkey)) return;
    const plaintext = nostr.nip46.open(gpa, signer, client_kp.secret_key, ev) catch return;
    defer gpa.free(plaintext);
    var resp = nostr.nip46.parseResponse(gpa, plaintext) catch return;
    defer resp.deinit();

    if (resp.value.err.len != 0) {
        std.debug.print("plaza: [signer] {s}\n", .{resp.value.err});
        // Leave the slot in the table, flagged: the UI tick owns the composer,
        // so it restores the draft (sign) or fails the status (connect).
        _ = failPending(resp.value.id);
        return;
    }

    // Correlate to the request that asked. A missing slot means an unknown id
    // or one already handled: drop it (no double publish, no stray "connected").
    const pending = takePending(resp.value.id) orelse return;
    defer if (pending.content) |c| gpa.free(c);

    g_remote_status.store(2, .release);
    g_remote_sign_notice.store(false, .release);

    switch (pending.method) {
        // The connect ack is a plain "ack" string; the status above is the point.
        .connect => {},
        .sign_event => {
            var parsed = nostr.event.fromJson(gpa, resp.value.result) catch return;
            defer parsed.deinit();
            // Signed as the account we asked it to sign as. The verify further
            // down the write path checks that an event's signature matches its
            // OWN pubkey, which a stranger's event also satisfies, so this is
            // the check that says the note is this reader's.
            if (!std.mem.eql(u8, &parsed.value.pubkey, &g_remote_pubkey)) return;
            // A process-lifetime copy of the content: `parsed` is freed on
            // return, but the detached publisher reads it afterwards. Our
            // composer produces tagless kind:1 notes, so an empty tag set still
            // matches the signed id, and the write seam verifies that before
            // trusting it into the feed.
            const owned = gpa.dupe(u8, parsed.value.content) catch return;
            var out = parsed.value;
            out.content = owned;
            // Preserve the signed tags (a reaction carries e/p/k); forcing them
            // empty would make the id not match, and the verify below would drop
            // it. Deep-copied because `parsed` is freed on return.
            // Whole, or not published: the id is computed over these tags, so
            // a partial copy is an event the verify below would drop anyway.
            out.tags = dupeTags(gpa, parsed.value.tags) orelse return;
            ingestAndPublish(gpa, out, signer);
        },
    }
}

/// UI-thread sweep of the pending table (called each tick): a request that
/// failed or ran past its deadline is retired here, where the composer can be
/// touched. A timed-out or refused `sign_event` restores its draft (only into
/// an empty composer, so a newer draft is never clobbered) and shows a notice;
/// a `connect` that never returned fails the connection status. A slot from a
/// superseded generation (logout/reconnect) is dropped silently.
fn scanPendingRemote(model: *Model) void {
    const now = nowSeconds();
    const gpa = std.heap.page_allocator;
    const generation = g_remote_generation.load(.acquire);
    var restore: ?[]const u8 = null;
    var sign_failed = false;
    var connect_failed = false;

    pendingLock();
    for (&g_pending) |*slot| {
        if (!slot.active) continue;
        const stale = slot.generation != generation;
        const due = slot.failed or now >= slot.deadline_s;
        if (!stale and !due) continue;
        const method = slot.method;
        const content = slot.content;
        const slot_restorable = slot.restorable;
        slot.* = .{};
        if (stale) {
            if (content) |c| gpa.free(c);
            continue;
        }
        switch (method) {
            .sign_event => {
                // The composer holds one draft: keep the first restorable one,
                // free the rest. A reaction's content is not restorable, so it
                // is freed and its failure stays silent.
                if (content) |c| {
                    if (slot_restorable and restore == null) restore = c else gpa.free(c);
                }
                if (slot_restorable) sign_failed = true;
            },
            .connect => {
                if (content) |c| gpa.free(c);
                connect_failed = true;
            },
        }
    }
    pendingUnlock();

    if (restore) |c| {
        if (model.draft_empty()) model.draft_buffer.set(c);
        gpa.free(c);
    }
    if (sign_failed) g_remote_sign_notice.store(true, .release);
    if (connect_failed and g_remote_status.load(.acquire) == 1) g_remote_status.store(3, .release);
}

/// Lowercase-hex-encodes a 32-byte key into `out`.
fn hexLower(out: *[64]u8, bytes: [32]u8) void {
    const digits = "0123456789abcdef";
    for (bytes, 0..) |b, i| {
        out[i * 2] = digits[b >> 4];
        out[i * 2 + 1] = digits[b & 0x0f];
    }
}

// -------------------------------------------------------------------- app run

// CoreText/CoreGraphics, for registering the bundled faces process-wide by
// PostScript name. Already linked: the SDK's AppKit host uses CTFontManager.
const ct = if (builtin.os.tag == .macos) struct {
    const CGDataProviderRef = ?*anyopaque;
    const CGFontRef = ?*anyopaque;
    const CFTypeRef = ?*anyopaque;
    extern "c" fn CGDataProviderCreateWithData(info: ?*anyopaque, data: [*]const u8, size: usize, release: ?*anyopaque) CGDataProviderRef;
    extern "c" fn CGDataProviderRelease(provider: CGDataProviderRef) void;
    extern "c" fn CGFontCreateWithDataProvider(provider: CGDataProviderRef) CGFontRef;
    extern "c" fn CGFontRelease(font: CGFontRef) void;
    extern "c" fn CTFontManagerRegisterGraphicsFont(font: CGFontRef, err: ?*CFTypeRef) bool;
    extern "c" fn CFRelease(ref: CFTypeRef) void;
} else struct {};

/// Installs Plaza's own vector icons (plaza_icons.zig) so `ui.appIcon` names
/// resolve like built-ins. Idempotent: it just publishes a static table. The
/// tests call it too, so a view built in a test draws the real glyphs instead of
/// the missing-icon fallback (and an icon regression can actually fail a test).
pub fn registerIcons() void {
    canvas.icons.registerAppIcons(&plaza_icons.app_icons);
}

/// Registers the bundled Geist faces (theme.zig) with CoreText from the
/// binary's own bytes, process scope, so the host's by-name resolution of the
/// default sans/mono ids (and the reserved medium/bold span ids) finds them
/// on EVERY launch path: the live window, a dev run from any working
/// directory, and headless session replay. Best-effort per face: a face that
/// is already registered (a system-installed Geist, a second call) fails
/// quietly, and by-name lookup still resolves; either copy is the same OFL
/// family.
fn registerFontFaces() void {
    if (comptime builtin.os.tag != .macos) return;
    const faces = [_][]const u8{ theme.geist_ttf, theme.geist_medium_ttf, theme.geist_bold_ttf, theme.geist_mono_ttf };
    for (faces) |ttf| {
        const provider = ct.CGDataProviderCreateWithData(null, ttf.ptr, ttf.len, null) orelse continue;
        defer ct.CGDataProviderRelease(provider);
        const font = ct.CGFontCreateWithDataProvider(provider) orelse continue;
        defer ct.CGFontRelease(font);
        var err: ct.CFTypeRef = null;
        _ = ct.CTFontManagerRegisterGraphicsFont(font, &err);
        if (err) |e| ct.CFRelease(e);
    }
}

pub fn main(init: std.process.Init) !void {
    g_io = init.io;
    g_environ = init.environ_map;

    // The bundled Geist faces, registered with CoreText before the platform
    // host exists, so every later font lookup resolves them (see theme.zig).
    registerFontFaces();

    // The glyphs the built-in set does not carry. Registered before the first
    // view build.
    registerIcons();

    // A returning user has a persisted session: restore it (load the local key,
    // or silently reconnect the bunker) so they are signed straight back in.
    // Best-effort: on failure the app still runs, as a guest.
    loadSettings(init.io, init.environ_map);
    _ = restoreSession(init.io, init.environ_map);
    // Resolve the keyholder daemon (its path and a fresh bearer token); boot
    // spawns it. Non-fatal, but not free either: Plaza has not minted a key in
    // this process since the key moved out of it, so an install that arrived
    // without the daemon cannot make one, and `keyholderMissing` is how the join
    // screens say so instead of offering a button that swallows the press.
    resolveHelper(init);
    resolveNotaryWindow(init);

    const app_state = try PlazaApp.create(std.heap.page_allocator, .{
        .name = "plaza",
        .scene = shell_scene,
        .canvas_label = canvas_label,
        .init_fx = boot,
        .update_fx = update,
        .view = appView,
        .on_command = onCommand,
        // No canvas-registered fonts: the typography tokens sit on the
        // BUILT-IN ids (the SDK's default sans IS Geist), which is the only
        // routing that gives span weights real medium/bold faces; a
        // custom-registered id pins every span to its one face. The faces are
        // registered with CoreText in `registerFontFaces` instead (theme.zig).
        // The dark, cool-grey, white-accent look (see theme.zig).
        .tokens_fn = theme.tokens(Model),
    });
    defer app_state.destroy();
    app_state.model = initialModel();
    // Guest-first: the app opens INTO the feed, never a welcome wall. A
    // restored session is signed straight back in; a newcomer browses as a
    // guest (the feed reads fine without an identity) and is asked for one at
    // first intent, not at launch. Either way the store and the pool start
    // before the window appears, so the first frame renders from disk.
    app_state.model.stage = .ready;
    startFeed(init.io, init.environ_map);

    try runner.runWithOptions(app_state.app(), .{
        .app_name = "plaza",
        .window_title = "Plaza",
        .bundle_id = "com.zig-nostr.plaza",
        .icon_path = "assets/icon.png",
        .default_frame = geometry.RectF.init(0, 0, window_width, window_height),
        .restore_state = false,
        .js_window_api = false,
        .security = .{
            .permissions = &app_permissions,
            .navigation = .{ .allowed_origins = &.{ "zero://inline", "zero://app" } },
        },
    }, init);
}

/// Opens the local-first store and spawns the background ingest thread. The
/// store is heap-allocated and the thread detached, both living for the whole
/// process: LMDB commits each event durably, and the ingest thread can be
/// blocked in a relay read at quit, so we deliberately never tear them down,
/// process exit reclaims them without racing the detached thread. A failure
/// here is non-fatal: the app runs with an empty feed that reads "offline".
fn startFeed(io: std.Io, environ: *const std.process.Environ.Map) void {
    if (g_store != null) return; // already running
    const gpa = std.heap.page_allocator;
    const store = gpa.create(nostr.store.Store) catch return;
    store.* = openFeedStore(io, environ) catch |err| {
        std.debug.print("plaza: local store unavailable: {s}\n", .{@errorName(err)});
        gpa.destroy(store);
        return;
    };
    g_store = store;
    seedFeedNewest(store);
    // The reader's own follow list is already on disk from last session. Read it
    // before the first frame, so a local-first app opens on THEIR feed rather
    // than on nine strangers while it waits for a relay.
    loadFollowsFromStore();
    loadInbox();

    // The reader's own list, or the one the app was born with. Read before the
    // threads start, so the first dial goes where they asked.
    loadRelays(io, environ);

    // One ingest thread per SLOT, not per relay: a slot's thread outlives the
    // relay in it, so adding one later is a slot claim rather than a thread
    // spawn from the UI, and removing one leaves a thread that finds the slot
    // dormant and waits. Each dials independently, so a slow or down relay never
    // holds up the others, and all write into the one shared store (LMDB
    // serialises the concurrent writers).
    for (0..max_relays) |i| {
        const thread = std.Thread.spawn(.{}, ingestRelay, .{ gpa, i }) catch |err| {
            std.debug.print("plaza: [{s}] could not start: {s}\n", .{ relayUrlAt(i), @errorName(err) });
            setRelayStatus(i, .offline);
            continue;
        };
        thread.detach();
    }

    // One more, watching all of them. It has to be a separate thread and not
    // work folded into the eight: each of those is blocked inside `receive`
    // exactly when there is something to notice, and a thread waiting on a dead
    // peer is the last thing that can tell it has stopped answering.
    if (std.Thread.spawn(.{}, relayKeeper, .{gpa})) |keeper| {
        keeper.detach();
    } else |err| {
        // Not fatal. Without it the pool behaves the way it did before: a
        // half-open socket sits there. Said out loud rather than swallowed,
        // because "the feed silently stopped updating" is the symptom and it
        // looks nothing like its cause.
        std.debug.print("plaza: relay keepalive did not start ({s}); a dropped connection will not be noticed\n", .{@errorName(err)});
    }
}

/// How much address space the store may grow into.
///
/// LMDB never grows past its map size, and the library's default is 1 GiB. There
/// is no pruning here and no retention window: the store only grows, at a
/// measured 2.4 MB a day on a development machine with a modest follow set and
/// the app not even running continuously. A reader on eight relays all day with
/// a real follow list, taking kind:6 and kind:7 engagement as well, gets there
/// materially faster.
///
/// Arriving is silent and it is the reader's own notes that pay. `plazaIngest`
/// is `catch {}` at the write of a note this app just signed, deliberately, so a
/// duplicate id cannot stop it reaching the pool, and a full map takes the same
/// branch. `saveOutbox` fails the same way, so the queue index never lands, and
/// `loadOutbox` drops on the next launch every entry whose event is not in the
/// store. The banner goes on saying the app is posting them.
///
/// A map size is address space, not a file: LMDB reserves it and the file stays
/// sparse. So the cheapest honest answer is to reserve far more of it than this
/// app can plausibly use, which moves the wall from a few years out to further
/// away than the format. Detecting MDB_MAP_FULL properly needs the library to
/// tell it apart from every other LMDB error, and pruning is a feature; both are
/// worth having and neither is a reason to leave the wall where it is.
const feed_store_map_size: usize = 32 << 30;

/// Opens (creating if needed) the feed store at `$HOME/.plaza/feed.mdb`.
fn openFeedStore(io: std.Io, environ: *const std.process.Environ.Map) !nostr.store.Store {
    const home = environ.get("HOME") orelse ".";
    var dir_buf: [512]u8 = undefined;
    const dir_path = try std.fmt.bufPrint(&dir_buf, "{s}/.plaza", .{home});
    // mkdir -p (idempotent); an absolute sub-path ignores the cwd handle.
    var dir = try std.Io.Dir.cwd().createDirPathOpen(io, dir_path, .{});
    dir.close(io);

    var path_buf: [512]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&path_buf, "{s}/feed.mdb", .{dir_path});
    return nostr.store.Store.open(db_path, .{ .map_size = feed_store_map_size });
}

// ----------------------------------------------------------------- identity
//
// Plaza's local signing identity lives beside the feed store, at
// `$HOME/.plaza/identity.key` (the raw 32-byte secret, mode 0600). It is created
// on the user's onboarding action, not silently: a first run with no key file
// opens the welcome screen, and "Create your identity" generates and persists
// it. This is the zero-config local signer; connecting an external signer
// (Notary, over NIP-46) so the key never touches the client is the next
// onboarding option, and swaps in at `signAndPublish`.

/// Opens (creating if needed) `$HOME/.plaza`, returning the directory handle.
fn plazaDir(io: std.Io, environ: *const std.process.Environ.Map) !std.Io.Dir {
    const home = environ.get("HOME") orelse ".";
    var dir_buf: [512]u8 = undefined;
    const dir_path = try std.fmt.bufPrint(&dir_buf, "{s}/.plaza", .{home});
    // mkdir -p (idempotent); an absolute sub-path ignores the cwd handle.
    return std.Io.Dir.cwd().createDirPathOpen(io, dir_path, .{});
}

/// Loads the identity from `identity.key` if present, adopting it and returning
/// true. Never generates a key, that is the onboarding action's job.
fn loadIdentityIfPresent(io: std.Io, environ: *const std.process.Environ.Map) bool {
    var dir = plazaDir(io, environ) catch return false;
    defer dir.close(io);

    const gpa = std.heap.page_allocator;
    const raw = dir.readFileAlloc(io, "identity.key", gpa, std.Io.Limit.limited(64)) catch return false;
    defer gpa.free(raw);
    if (raw.len != 32) return false;

    var signer = nostr.keys.Signer.init();
    var secret: [32]u8 = undefined;
    @memcpy(&secret, raw[0..32]);
    const kp = signer.keyPairFromSecretKey(secret) catch {
        signer.deinit();
        return false;
    };
    g_signer_kind = .local;
    setIdentity(signer, kp);
    // Queue a silent, background upgrade: move this in-process key into the
    // isolated daemon. The tick fires it once the daemon is reachable; on
    // success the identity becomes helper-held and identity.key is deleted. If
    // it never lands, the key keeps working in-process, no loss.
    g_helper_setup_secret = secret;
    g_helper_setup = .migrate;
    return true;
}

/// Generates a fresh identity, persists it (mode 0600), and adopts it. Backs the
/// onboarding "create identity" action, using the io and environment stashed in
/// `main`. Returns true on success.
fn createLocalIdentity() bool {
    const io = g_io orelse return false;
    const environ = g_environ orelse return false;

    var signer = nostr.keys.Signer.init();
    const kp = signer.generateKeyPair(io) catch {
        signer.deinit();
        return false;
    };

    persistIdentityKey(io, environ, kp.secret_key);
    g_signer_kind = .local;
    setIdentity(signer, kp);
    return true;
}

/// Imports an existing key from a bech32 `nsec`, persists it (mode 0600), and
/// adopts it as the local identity. Backs the onboarding "paste your nsec" path.
/// On a malformed key sets the login error and returns false.
fn importNsec(nsec: []const u8) bool {
    const io = g_io orelse return false;
    const environ = g_environ orelse return false;
    const gpa = std.heap.page_allocator;

    const secret = nostr.nip19.decodeNsec(gpa, nsec) catch {
        g_login_error.store(@intFromEnum(LoginError.bad_key), .release);
        return false;
    };
    var signer = nostr.keys.Signer.init();
    const kp = signer.keyPairFromSecretKey(secret) catch {
        signer.deinit();
        g_login_error.store(@intFromEnum(LoginError.bad_key), .release);
        return false;
    };

    persistIdentityKey(io, environ, secret);
    g_signer_kind = .local;
    setIdentity(signer, kp);
    return true;
}

/// Writes the raw 32-byte secret to `$HOME/.plaza/identity.key` at mode 0600,
/// replacing any existing file. A failure to persist is non-fatal: the session
/// still runs with the in-memory key (it just will not survive a relaunch).
fn persistIdentityKey(io: std.Io, environ: *const std.process.Environ.Map, secret: [32]u8) void {
    var dir = plazaDir(io, environ) catch |err| {
        std.debug.print("plaza: could not open key dir: {s}\n", .{@errorName(err)});
        return;
    };
    defer dir.close(io);
    // Replace any prior key (a logout deletes it, so normally there is none).
    dir.deleteFile(io, "identity.key") catch {};
    dir.writeFile(io, .{
        .sub_path = "identity.key",
        .data = &secret,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch |err| std.debug.print("plaza: could not persist identity: {s}\n", .{@errorName(err)});
}

/// Sets the identity globals: the signer, the keypair, and the abbreviated npub
/// the composer shows. The signer's secp256k1 context is used only on the UI
/// thread.
fn setIdentity(signer: nostr.keys.Signer, kp: nostr.keys.KeyPair) void {
    g_identity_signer = signer;
    g_identity_kp = kp;
    const npub = abbreviateNpub(&g_identity_npub_buf, kp.public_key);
    g_identity_npub_len = npub.len;
}

// ------------------------------------------------------------------- session
//
// The active identity is persisted as a small session file at
// `$HOME/.plaza/session` (mode 0600), a line-based `key=value` record, so a
// returning user is signed straight back in without re-entering anything. A
// local session points at `identity.key` (the raw secret already on disk); a
// remote session carries everything needed to silently reconnect the NIP-46
// bunker (the signer's pubkey, its relay, our ephemeral transport secret, and
// the connect secret), never the user's own key, which lives only in the signer.

/// Writes the session file for the current identity kind. Best-effort: a failure
/// to persist just means this identity will not auto-restore next launch.
fn persistSession() void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);

    var buf: [1024]u8 = undefined;
    const data = switch (g_signer_kind) {
        .local => std.fmt.bufPrint(&buf, "kind=local\nminted={d}\n", .{@intFromBool(g_identity_minted_here)}) catch return,
        .helper => blk: {
            if (!g_helper_has_identity) return;
            var pk_hex: [64]u8 = undefined;
            hexLower(&pk_hex, g_helper_identity_pk);
            break :blk std.fmt.bufPrint(&buf, "kind=helper\npubkey={s}\nminted={d}\n", .{ &pk_hex, @intFromBool(g_identity_minted_here) }) catch return;
        },
        .remote => blk: {
            const kp = g_remote_client_kp orelse return;
            var pk_hex: [64]u8 = undefined;
            hexLower(&pk_hex, g_remote_pubkey);
            var cs_hex: [64]u8 = undefined;
            hexLower(&cs_hex, kp.secret_key);
            break :blk std.fmt.bufPrint(&buf, "kind=remote\nremote_pubkey={s}\nrelay={s}\nclient_secret={s}\nsecret={s}\n", .{
                &pk_hex,
                g_remote_relay_buf[0..g_remote_relay_len],
                &cs_hex,
                g_remote_secret_buf[0..g_remote_secret_len],
            }) catch return;
        },
    };
    dir.writeFile(io, .{
        .sub_path = "session",
        .data = data,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch |err| std.debug.print("plaza: could not persist session: {s}\n", .{@errorName(err)});
}

/// Restores the persisted identity at boot. Returns whether a session was
/// restored (so the feed should start). Reads `$HOME/.plaza/session`; falls back
/// to migrating a legacy `identity.key` (pre-session installs) into a local
/// session. Any missing or malformed data returns false, landing on onboarding.
fn restoreSession(io: std.Io, environ: *const std.process.Environ.Map) bool {
    var dir = plazaDir(io, environ) catch return false;
    defer dir.close(io);
    const gpa = std.heap.page_allocator;

    const raw = dir.readFileAlloc(io, "session", gpa, std.Io.Limit.limited(2048)) catch {
        // No session file: adopt a legacy local key if one is on disk.
        if (loadIdentityIfPresent(io, environ)) {
            persistSession();
            return true;
        }
        return false;
    };
    defer gpa.free(raw);

    var kind: []const u8 = "";
    var f_pubkey: []const u8 = "";
    var f_relay: []const u8 = "";
    var f_client_secret: []const u8 = "";
    var f_secret: []const u8 = "";
    var lines = std.mem.splitScalar(u8, raw, '\n');
    while (lines.next()) |line| {
        const eq = std.mem.indexOfScalar(u8, line, '=') orelse continue;
        const key = line[0..eq];
        const val = line[eq + 1 ..];
        if (std.mem.eql(u8, key, "kind")) kind = val;
        // Whether this key was minted here. Absent means an older session file,
        // and absent has to read as "imported": assuming a key is ours when we
        // do not know is exactly the assumption that loses a contact list.
        if (std.mem.eql(u8, key, "minted")) g_identity_minted_here = std.mem.eql(u8, val, "1");
        if (std.mem.eql(u8, key, "remote_pubkey")) f_pubkey = val;
        if (std.mem.eql(u8, key, "pubkey")) f_pubkey = val;
        if (std.mem.eql(u8, key, "relay")) f_relay = val;
        if (std.mem.eql(u8, key, "client_secret")) f_client_secret = val;
        if (std.mem.eql(u8, key, "secret")) f_secret = val;
    }

    if (std.mem.eql(u8, kind, "helper")) return restoreHelperIdentity(f_pubkey);
    if (std.mem.eql(u8, kind, "local")) return loadIdentityIfPresent(io, environ);
    if (std.mem.eql(u8, kind, "remote")) return restoreRemoteSigner(gpa, f_pubkey, f_relay, f_client_secret, f_secret);
    return false;
}

/// Rebuilds the remote-signer connection from a persisted session and reconnects
/// silently: adopts the bunker pubkey as the identity, reconstructs the ephemeral
/// transport key, starts the response listener, and re-sends `connect`.
fn restoreRemoteSigner(gpa: std.mem.Allocator, pubkey_hex: []const u8, relay: []const u8, client_secret_hex: []const u8, secret: []const u8) bool {
    if (pubkey_hex.len != 64 or client_secret_hex.len != 64) return false;
    if (relay.len == 0 or relay.len > g_remote_relay_buf.len) return false;
    if (secret.len > g_remote_secret_buf.len) return false;

    var pubkey: [32]u8 = undefined;
    _ = std.fmt.hexToBytes(&pubkey, pubkey_hex) catch return false;
    var client_secret: [32]u8 = undefined;
    _ = std.fmt.hexToBytes(&client_secret, client_secret_hex) catch return false;

    var signer = nostr.keys.Signer.init();
    const client_kp = signer.keyPairFromSecretKey(client_secret) catch {
        signer.deinit();
        return false;
    };
    signer.deinit();

    g_remote_pubkey = pubkey;
    @memcpy(g_remote_relay_buf[0..relay.len], relay);
    g_remote_relay_len = relay.len;
    @memcpy(g_remote_secret_buf[0..secret.len], secret);
    g_remote_secret_len = secret.len;
    g_remote_client_kp = client_kp;

    const npub = abbreviateNpub(&g_identity_npub_buf, pubkey);
    g_identity_npub_len = npub.len;
    g_signer_kind = .remote;
    g_remote_status.store(1, .release);
    g_remote_sign_notice.store(false, .release);

    // A fresh generation for this reconnected session (see `connectRemoteSigner`).
    const generation = g_remote_generation.fetchAdd(1, .monotonic) + 1;
    const thread = std.Thread.spawn(.{}, nip46ReceiveLoop, .{ gpa, generation }) catch return false;
    thread.detach();
    sendConnect(gpa);
    return true;
}

/// Loads app-wide settings (the media proxy) from `$HOME/.plaza/settings`,
/// starting from the default so a fresh install proxies out of the box.
fn loadSettings(io: std.Io, environ: *const std.process.Environ.Map) void {
    setMediaProxy(default_media_proxy);
    g_media_previews = true;
    g_client_tag = false;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    const gpa = std.heap.page_allocator;
    const raw = dir.readFileAlloc(io, "settings", gpa, std.Io.Limit.limited(1024)) catch return;
    defer gpa.free(raw);
    var lines = std.mem.splitScalar(u8, raw, '\n');
    while (lines.next()) |line| {
        const eq = std.mem.indexOfScalar(u8, line, '=') orelse continue;
        // An empty value is meaningful: the user chose to load originals.
        if (std.mem.eql(u8, line[0..eq], "media_proxy")) setMediaProxy(line[eq + 1 ..]);
        if (std.mem.eql(u8, line[0..eq], "media_previews")) g_media_previews = std.mem.eql(u8, line[eq + 1 ..], "on");
        if (std.mem.eql(u8, line[0..eq], "client_tag")) g_client_tag = std.mem.eql(u8, line[eq + 1 ..], "on");
    }
}

/// Persists app-wide settings. Best-effort, like the session file.
fn saveSettings() void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    var buf: [512]u8 = undefined;
    const data = std.fmt.bufPrint(&buf, "media_proxy={s}\nmedia_previews={s}\nclient_tag={s}\n", .{
        mediaProxy(),
        if (g_media_previews) "on" else "off",
        if (g_client_tag) "on" else "off",
    }) catch return;
    dir.writeFile(io, .{
        .sub_path = "settings",
        .data = data,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch |err| std.debug.print("plaza: could not persist settings: {s}\n", .{@errorName(err)});
}

/// Where an unsent draft waits between launches. One slot, because the composer
/// is one sheet: a list of drafts is a different feature and the plan says so.
const draft_file = "draft";
/// Set by an edit, cleared by the tick that writes it: a keystroke must not
/// carry a file write, and a file write must not wait for the sheet to close.
var g_draft_dirty = false;

/// Keeps what was written but not sent. The composer already survives being
/// closed within a session; this is what makes it survive the app quitting,
/// which is the case that actually loses words: a machine that sleeps, an
/// update, a crash.
///
/// Written with the same restrictive permissions as the rest of ~/.plaza,
/// because an unsent note is as private as a sent one and rather more likely
/// to be unfinished thinking.
fn saveDraft(text: []const u8) void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    if (text.len == 0) {
        // Nothing to keep: the slot is removed rather than left holding a stale
        // draft that would reappear over the next empty composer.
        dir.deleteFile(io, draft_file) catch {};
        return;
    }
    dir.writeFile(io, .{
        .sub_path = draft_file,
        .data = text,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch {};
}

/// Reads the stashed draft back, or an empty slice when there is none.
fn loadDraft(out: []u8) []const u8 {
    const io = g_io orelse return "";
    const environ = g_environ orelse return "";
    var dir = plazaDir(io, environ) catch return "";
    defer dir.close(io);
    const n = dir.readFile(io, draft_file, out) catch return "";
    return out[0..n.len];
}

/// Logs out: deletes the session (and, for a local key, the key file itself),
/// resets the identity globals, and returns to onboarding. The feed store and
/// its ingest threads keep running (they serve the starter pack regardless of
/// who is signed in); a subsequent sign-in reuses them. The user is never locked
/// in, a local key can always be copied from Settings first, and a remote
/// signer keeps the user's key throughout.
/// Drives the whole sign-out, so a test can assert what does NOT survive it. The
/// list of things it clears is the interesting part, and every one of them was
/// added after something of the previous account's turned up under the next
/// account's key.
pub fn performLogoutForTest(model: *Model, fx: *Effects) void {
    performLogout(model, fx);
}

pub fn loggedOutPubkeyForTest() ?[32]u8 {
    return g_logged_out_pk;
}

fn performLogout(model: *Model, fx: *Effects) void {
    // Forget the key in the daemon's MEMORY, not just on disk: without this the
    // health-check reads /pubkey, still sees the key, and re-adopts within a
    // tick. The latch holds until the async reset lands.
    if (g_signer_kind == .helper) helperReset(fx);
    g_logged_out = true;
    // WHICH key left, so the health-check can refuse to hand it back even after
    // an explicit sign-in drops the latch above.
    g_logged_out_pk = activePubkey();
    g_logout_reset_tries = 0;
    g_logout_reset_due = false;
    if (g_io) |io| if (g_environ) |environ| {
        if (plazaDir(io, environ)) |dir_const| {
            var dir = dir_const;
            defer dir.close(io);
            dir.deleteFile(io, "session") catch {};
            if (g_signer_kind == .local) dir.deleteFile(io, "identity.key") catch {};
            // The helper's key lives in the daemon's file; remove it too, so a
            // logout leaves no key on disk. (The running daemon keeps its copy
            // in memory until it exits with Plaza; recreating an identity in the
            // same session needs a restart.)
            if (g_signer_kind == .helper) dir.deleteFile(io, "signer.key") catch {};
        } else |_| {}
    };

    // Tear down the NIP-46 session: bumping the generation stops the detached
    // listener from processing into the next session, and the pending table is
    // emptied so no in-flight request survives the logout.
    _ = g_remote_generation.fetchAdd(1, .monotonic);
    clearPending();
    g_remote_sign_notice.store(false, .release);
    // And the built-in signer's slot, for the same reason: it holds the leaving
    // account's writing, and the confirmation said what that costs.
    releaseHelperSign();
    g_helper_sign_notice.store(false, .release);

    if (g_identity_signer) |*s| s.deinit();
    g_identity_signer = null;
    g_identity_kp = null;
    g_identity_npub_len = 0;
    g_helper_has_identity = false;
    g_signer_kind = .local;
    g_remote_client_kp = null;
    g_remote_relay_len = 0;
    g_remote_secret_len = 0;
    g_remote_status.store(0, .release);
    g_login_error.store(@intFromEnum(LoginError.none), .release);
    invalidateFeed();

    // The relay list belongs to the ACCOUNT, not the machine: it came from their
    // kind:10002 and it names where they read and write. Carrying it into the
    // next account would route a stranger's notes through the previous reader's
    // relays, and hand the new account a list they never chose. Back to the
    // relays the app was born with, ready to adopt the next account's own.
    resetRelaysToBootstrap();
    // And what was concluded about the leaving account's own records. Carrying
    // any of it would let the next account be judged without being asked, and a
    // write would then go out over a list nobody has read.
    forgetOwnRecordAnswers();
    // And who the leaving account followed, so the next reader is not shown a
    // feed built from a stranger's list.
    forgetFollows();
    resetInbox();
    model.notifications_open = false;
    model.editing_profile = false;
    model.profile_seeded = false;

    // And this key was not made here, whoever comes next. The flag is the ONE
    // piece of evidence that authorizes building a contact list, a relay list or
    // a profile from nothing, and it is persisted to the session file, so left
    // set it outlived the account it was true about: mint here, log out, and an
    // identity imported afterwards inherited permission to publish nine
    // starter-pack names over a real eight-hundred-follow list.
    g_identity_minted_here = false;

    model.login_buffer.clear();
    model.draft_buffer.clear();
    // Every other thing the previous reader typed, for the same reason the draft
    // is cleared: it is their private thinking, and it is one press from being
    // published under the NEXT account's key.
    //
    // The reply box survived because logout performs no navigation, so the next
    // account landed inside the previous reader's open thread with their unsent
    // sentence still in the composer. The name field survived Skip as well as
    // logout, so a freshly minted key could be given a permanent kind:0 carrying
    // the previous person's typed name.
    model.reply_buffer.clear();
    model.name_buffer.clear();
    model.viewing_thread = 0;
    model.thread_stack_len = 0;
    model.viewing_profile = null;
    // And off the disk. An unfinished note is the previous account's private
    // thinking; leaving it would hand it to whoever signs in next, in their
    // composer, one keystroke from being published under THEIR key.
    saveDraft("");
    // The OUTBOX is deliberately left alone, and that is not an oversight.
    //
    // A queued note is one the reader wrote and the app has not managed to
    // deliver yet. Emptying the queue here would destroy it, and `sweepOutbox`
    // already refuses to do that for exactly this reason. So it stays, and
    // `syncOutboxOwner` is what makes staying safe: on the next tick the slots
    // are handed to whoever is signed in, and these entries are parked in this
    // account's own record. Sign back in as its author and it is read back and
    // goes out. For a LOCAL key that is only possible if the reader kept a copy,
    // because this function deletes the key file; the note is still theirs, and
    // still here, which is the most an app can honestly promise at that point.
    //
    // Getting this wrong is how the previous account's unsent note would ride
    // out over the next account's relays, counted in their status bar as
    // something the app owed THEM.
    model.logout_pending = false;
    model.reveal_nsec = false;
    model.notes_len = 0;
    // Never a locked door: signing out lands on the guest feed, reading
    // uninterrupted (the pool and store keep running), not a welcome wall.
    model.stage = .ready;
}

// ----------------------------------------------------------- background ingest
//
// Each relay's ingest loop runs on its own thread with its own `std.Io.Threaded`
// and its own secp256k1 context, the io backend and the signer are not shared
// across threads, the exact shape the Notary daemon uses per relay. It dials,
// subscribes for recent kind:1, verifies each event, and writes it into the
// shared store; the UI thread reads it back through `Model.refresh`.

/// The first wait before redialling a relay whose connection ended, and the
/// ceiling that wait grows to.
///
/// This used to be a flat three seconds, forever, with no counter. A relay that
/// is down, that has stopped taking this reader, or that accepts the handshake
/// and then drops the socket was dialled twelve hundred times an hour for as
/// long as the app stayed open, from eight threads with no jitter between them,
/// and every one of those dials re-asked for the whole backlog.
const reconnect_base_ms: u64 = 3_000;
const reconnect_max_ms: u64 = 300_000;

/// How long a connection has to last before it counts as having worked.
///
/// The reason for the rule is not obvious: a successful handshake is NOT
/// evidence that a relay is healthy. A relay that accepts the socket and
/// immediately closes it would reset the ladder on every open, and the widening
/// delay would never widen. Only a connection that stayed up clears the count.
const stable_connection_ms: i64 = 60_000;

/// The wait before redialling, after `attempts` connections in a row that did
/// not last. Doubling, capped.
pub fn reconnectDelayMs(attempts: u6) u64 {
    const shift: u6 = @min(attempts, 7);
    return @min(reconnect_base_ms << shift, reconnect_max_ms);
}

/// The attempt count after a connection that stayed up for `lasted_ms`.
///
/// Separate from the loop so the rule can be asserted rather than described: a
/// connection only clears the ladder by LASTING, never by opening.
pub fn nextReconnectAttempts(attempts: u6, lasted_ms: i64) u6 {
    return if (lasted_ms >= stable_connection_ms) 0 else attempts +| 1;
}

/// Extra delay for slot `index`, so the pool does not redial in lockstep.
///
/// Spread rather than randomness, because the thing being avoided is specific:
/// eight threads that dropped together on one network blip coming back together,
/// and then staying in step for the rest of the session. Walking the offset by
/// the attempt as well as the slot separates two relays that happened to start
/// aligned. Never more than a quarter of the wait, and it is a function, so what
/// it promises can be asserted.
pub fn reconnectJitterMs(wait: u64, index: usize, attempts: u6) u64 {
    const slice = wait / 64;
    const step = (index *% 5 +% @as(usize, attempts) *% 3) % 16;
    return slice * step;
}

/// Opens, or replaces, the engagement subscription over the first `count`
/// watched notes.
///
/// A REQ under an existing id IS a replacement, so widening the watched set
/// costs one message and no CLOSE.
fn subscribeEngagement(relay: *nostr.relay.Relay, hex: *const [engagement_watch_cap][64]u8, count: usize) void {
    if (count == 0) return;
    var evals: [engagement_watch_cap][]const u8 = undefined;
    for (0..count) |i| evals[i] = &hex[i];
    const eng_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = evals[0..count] }};
    const eng_filters = [_]nostr.filter.Filter{engagementFilter(&eng_tags)};
    relay.subscribe("plaza-engagement", &eng_filters) catch {};
}

/// One relay's ingest loop: dial, serve, and reconnect after a widening delay,
/// forever.
fn ingestRelay(gpa: std.mem.Allocator, index: usize) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    // Connections in a row that did not last `stable_connection_ms`.
    var attempts: u6 = 0;
    // The address last dialled, so re-pointing a slot starts a clean ladder
    // instead of inheriting the previous relay's failures. Fixing a typo in a
    // relay URL should take effect now, not in five minutes.
    var tried_buf: [96]u8 = undefined;
    var tried_len: usize = 0;

    while (true) {
        // An empty slot is not an error: it is a seat kept for a relay the
        // reader may add. It costs a sleeping thread and nothing else.
        if (relayAt(index) == null) {
            setRelayStatus(index, .offline);
            attempts = 0;
            tried_len = 0;
            io.sleep(std.Io.Duration.fromSeconds(1), .awake) catch {};
            continue;
        }
        // A paused pool never dials. The reader still has the whole store, so
        // pausing costs them nothing but the live tail.
        if (relaysPaused()) {
            setRelayStatus(index, .offline);
            attempts = 0;
            io.sleep(std.Io.Duration.fromSeconds(1), .awake) catch {};
            continue;
        }
        var url_buf: [96]u8 = undefined;
        if (relaySnapshot(index, &url_buf)) |now| {
            if (!relayUrlEql(now.url, tried_buf[0..tried_len])) {
                attempts = 0;
                tried_len = now.url.len;
                @memcpy(tried_buf[0..tried_len], now.url);
            }
        }
        setRelayStatus(index, .connecting);
        const opened_at = std.Io.Timestamp.now(io, .awake).toMilliseconds();
        ingestOnce(gpa, io, signer, index) catch |err| {
            std.debug.print("plaza: [{s}] {s}\n", .{ relayUrlAt(index), @errorName(err) });
        };
        setRelayStatus(index, .offline);
        clearRelayRtt(index);
        const lasted = std.Io.Timestamp.now(io, .awake).toMilliseconds() - opened_at;
        attempts = nextReconnectAttempts(attempts, lasted);
        const wait = reconnectDelayMs(attempts);
        const spread = reconnectJitterMs(wait, index, attempts);
        io.sleep(std.Io.Duration.fromMilliseconds(@intCast(wait + spread)), .awake) catch {};
    }
}

/// Dials relay `index`, subscribes for recent kind:1, and ingests each event
/// into the shared store until the connection closes.
fn ingestOnce(gpa: std.mem.Allocator, io: std.Io, signer: nostr.keys.Signer, index: usize) !void {
    // Read fresh each time round: the reader may have changed this slot's URL,
    // or emptied it, since the last dial.
    var url_buf: [96]u8 = undefined;
    const entry = relaySnapshot(index, &url_buf) orelse return error.RelayRemoved;
    const url = entry.url;
    const reads = entry.read;
    var relay = try nostr.relay.dial(gpa, io, url);
    // Withdrawn BEFORE the connection is freed, and the defers unwind in
    // reverse, so this one is declared second and runs first. The other order
    // hands the keeper a pointer to a `Relay` that is already gone.
    defer relay.deinit();
    publishLiveRelay(index, relay);
    defer publishLiveRelay(index, null);
    setRelayStatus(index, .connected);

    // Follow-scoped: the starter pack's recent notes for the feed, plus their
    // kind:0 metadata (and the user's own) so the feed can show real names and
    // avatars. Two filters share one subscription.
    var authors: [max_follows + 1][32]u8 = undefined;
    // Snapshotted, not borrowed: `followSet` hands back a slice of a table the
    // UI thread rewrites when a follow lands, and this filter outlives the frame.
    var authors_len: usize = followSnapshot(@ptrCast(&authors));
    // The generation this subscription was built for. When it moves, this
    // connection is asking the wrong question and re-asks below.
    var subscribed_gen = followGeneration();
    // Set to the generation already served by `subscribeInbox` at dial below,
    // so the loop does not immediately re-issue what was just sent.
    var inbox_gen = identityGeneration();
    // Whether this subscription asked about the reader themselves. A connection
    // dialed while signed out did not, and its EOSE is not an answer about them.
    var asked_about_me = activePubkey() != null;
    if (activePubkey()) |pk| {
        authors[authors_len] = pk;
        authors_len += 1;
    }
    // Two filters per chunk of authors, all in ONE REQ.
    //
    // `authors_len` INCLUDES the reader. An earlier version took the snapshot
    // BEFORE appending the reader's own key, so a note written anywhere but this
    // install was never fetched from any relay: the feed reads your own notes
    // from the store and the store never had them. Signing in with an existing
    // key showed a feed with none of your own writing in it, and every
    // notification about those notes pressed into nothing, because the note it
    // pointed at was not held.
    //
    // The chunking is a payload split and nothing more. A relay answers every
    // filter in a REQ, so five filters of five hundred authors ask the same
    // question as one filter of two and a half thousand, in an envelope relays
    // actually accept. The per-chunk limit stays whole for the same reason:
    // dividing it would starve whoever landed in the last chunk.
    var filter_buf: [max_feed_filters]nostr.filter.Filter = undefined;
    const filters = buildFeedFilters(authors[0..authors_len], activePubkey(), feedSince(), &filter_buf);
    // What other people aimed at this reader. Its own subscription, never folded
    // into the feed's: a relay that is handed two differently-scoped filters in
    // one REQ may answer the stored query and then go quiet, which is the worst
    // failure mode to notice.
    if (reads) subscribeInbox(relay);

    // A relay marked write-only is not asked anything. It keeps its socket, so a
    // note goes out the moment it is written, but no filter of this reader's
    // ever reaches it: that is the whole difference the badge promises.
    if (reads) try relay.subscribe("plaza-feed", filters);

    // Latency is measured with a PROBE, never with the subscriptions above: the
    // feed REQ asks for a 300-note backlog plus profiles, so timing it measures
    // how much this relay had to send, not how fast it answers. The probe asks
    // for an id that cannot exist, so the answer is an empty EOSE and the number
    // is the round trip and nothing else. Re-sent periodically so it stays live,
    // and CLOSED as soon as it answers. The AWAKE clock, so a system clock step
    // cannot swing a reading.
    var probe_at: i64 = 0;
    var probed_at: i64 = 0;

    // The loaded notes' ids (and their hex), collected from the feed as it
    // arrives. On the feed's EOSE a second subscription opens for their
    // engagement, so counts fold in alongside the feed on the same connection,
    // and it is widened as more notes load.
    var feed_ids: [engagement_watch_cap]i64 = undefined;
    var feed_id_hex: [engagement_watch_cap][64]u8 = undefined;
    var feed_ids_len: usize = 0;
    // How many of those ids the engagement subscription currently names, and
    // when it was last (re)issued.
    var engagement_watching: usize = 0;
    var engagement_at: i64 = 0;

    while (true) {
        // A pause takes effect at the next message this relay sends: the thread
        // returns, `defer relay.deinit()` closes the socket, and the reconnect
        // loop parks. A silent relay therefore holds its socket until it speaks,
        // which is why the chip says "pausing" until every thread has actually
        // left rather than claiming a pause it has not achieved.
        if (relaysPaused()) return;
        // The same for an edit. Removing a relay, or clearing its read marker,
        // must end THIS connection: leaving the socket up until the next
        // reconnect would keep a relay the reader dropped feeding the store, and
        // keep a relay they set write-only answering their filters. Checked
        // against the address dialed, so a slot that changed hands also drops.
        var now_buf: [96]u8 = undefined;
        const now_entry = relaySnapshot(index, &now_buf) orelse return;
        if (!relayUrlEql(now_entry.url, url)) return;
        if (now_entry.read != reads) return;
        // Following someone changes what this connection should be asking for.
        // NIP-01 makes a REQ under an existing id a replacement, so the same
        // subscription is simply re-issued: without this a follow shows nothing
        // new until the socket happens to drop, which reads as a broken button.
        // A follow OR an identity change: `forgetFollows` bumps the same
        // counter on sign-out and sign-in, because a connection built for a
        // guest never asks for the account's own records and would otherwise
        // leave following disabled for the whole session.
        if (reads and followGeneration() != subscribed_gen) {
            subscribed_gen = followGeneration();
            authors_len = followSnapshot(@ptrCast(&authors));
            var next_authors_len = authors_len;
            asked_about_me = false;
            if (activePubkey()) |pk| {
                if (next_authors_len < authors.len) {
                    authors[next_authors_len] = pk;
                    next_authors_len += 1;
                    asked_about_me = true;
                }
            }
            // Built by the SAME function the dial-time subscription uses.
            //
            // This path used to hand-roll its own pair of filters, and both of
            // the things `buildFeedFilters` exists to prevent came back with it:
            // every author named in ONE filter, which is past the size several
            // relays accept once a real follow list is loaded, and a metadata
            // limit taken from `profile_cap`, which is the size of a screen
            // cache and has nothing to do with how many records to ask for.
            //
            // It mattered more here than anywhere, because this is the path
            // every reader takes: Plaza dials before anyone has signed in, so
            // the subscription that carries the actual account is always the
            // re-issued one, never the one built at dial.
            const next_filters = buildFeedFilters(authors[0..next_authors_len], activePubkey(), feedSince(), &filter_buf);
            relay.subscribe("plaza-feed", next_filters) catch {};
            // The inbox rides the SAME signal, and for a reason the feed's own
            // comment above already explains: this counter moves on sign-in.
            // Asking only at dial was the whole feature's undoing, because Plaza
            // opens as a guest and dials every relay BEFORE anyone has signed in.
            // The bell then read zero for the entire session, on a healthy
            // connection, no matter who replied. Re-issuing here is also what
            // heals a REQ that failed to send, and what stops a socket carrying
            // the previous account's filter after a switch.
        }
        // The inbox rides its own generation: its filter names ONE pubkey, the
        // reader's, so a contact-list change has nothing to do with it.
        if (reads and identityGeneration() != inbox_gen) {
            inbox_gen = identityGeneration();
            subscribeInbox(relay);
        }
        var msg = (try relay.receive()) orelse break;
        defer msg.deinit();

        // Time to re-probe? `receive()` blocks with no deadline, so the probe
        // rides the next message rather than a timer; a relay too quiet to carry
        // one is also a relay whose latency nobody is waiting on.
        //
        // A write-only relay is probed too: a question about one id that does
        // not exist, which says nothing about who this reader follows or reads,
        // and its answer is the latency shown beside a relay they do use.
        const now_ms = std.Io.Timestamp.now(io, .awake).toMilliseconds();
        if (probe_at == 0 and (probed_at == 0 or now_ms - probed_at > probe_interval_ms)) {
            const probe_filters = probeFilters();
            if (relay.subscribe(probe_sub, &probe_filters)) |_| {
                probe_at = now_ms;
                probed_at = now_ms;
            } else |_| {}
        }
        // Widen the engagement subscription as more of the feed loads. It used
        // to be opened once per connection over whatever had arrived by the
        // feed's EOSE and never touched again, so every note past that point
        // read zero likes, zero replies and zero zaps for the whole session, and
        // so did every note that arrived live.
        if (engagement_watching > 0 and feed_ids_len > engagement_watching and
            now_ms - engagement_at > engagement_widen_ms)
        {
            subscribeEngagement(relay, &feed_id_hex, feed_ids_len);
            engagement_watching = feed_ids_len;
            engagement_at = now_ms;
        }
        switch (msg.value) {
            .event => |e| {
                if (std.mem.eql(u8, e.subscription_id, "plaza-inbox")) {
                    // Verified before it counts: a relay can send anything down
                    // any subscription, and an inbox is the one surface where a
                    // stranger chooses what the reader sees.
                    const result = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch continue;
                    if (result == .invalid) continue;
                    if (inboxAdd(e.event, nowSeconds())) markInboxDirty();
                    continue;
                }
                if (std.mem.eql(u8, e.subscription_id, "plaza-feed")) {
                    // Verify (secp256k1) before storing; silently drop a bad event.
                    // `.invalid` is a RETURNED VALUE here, not an error: a
                    // forged event does not throw, it comes back saying it did
                    // not verify. Reading only the error channel let a relay
                    // hand this reader a relay list signed by nobody.
                    const result = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch continue;
                    if (result == .invalid) continue;
                    // Note which relay carried it, so a thread can say how widely
                    // a note is held rather than guess.
                    if (e.event.kind == 1) {
                        markRelaySeen(noteIdOf(e.event), index);
                        // What the next subscription will start from.
                        noteFeedNewest(e.event.created_at);
                    }
                    if (e.event.kind == relay_list_kind) ingestRelayList(e.event);
                    if (e.event.kind == contact_list_kind) ingestContactList(e.event);
                    // Note this feed post so its engagement can be watched. Bounded
                    // to keep the `#e` filter a size relays accept.
                    if (e.event.kind == 1 and feed_ids_len < engagement_watch_cap) {
                        const nid = noteIdOf(e.event);
                        var known = false;
                        for (feed_ids[0..feed_ids_len]) |fid| {
                            if (fid == nid) {
                                known = true;
                                break;
                            }
                        }
                        if (!known) {
                            feed_ids[feed_ids_len] = nid;
                            hexLower(&feed_id_hex[feed_ids_len], e.event.id);
                            feed_ids_len += 1;
                        }
                    }
                } else {
                    // The engagement subscription: fold into the counts, verified
                    // so a forged reaction cannot inflate a tally.
                    if (nostr.event.verify(gpa, signer, e.event) catch false) countEngagement(e.event, feed_ids[0..feed_ids_len]);
                }
            },
            .eose => |eo| {
                if (std.mem.eql(u8, eo.subscription_id, probe_sub) and probe_at != 0) {
                    const elapsed = std.Io.Timestamp.now(io, .awake).toMilliseconds() - probe_at;
                    if (elapsed >= 0) recordRelayRtt(index, @intCast(@min(elapsed, std.math.maxInt(u16))));
                    probe_at = 0;
                    // Answered, so close it. A REQ stays live past EOSE, and the
                    // question has been answered: leaving it open is how the
                    // probe became a standing subscription on every relay.
                    relay.unsubscribe(probe_sub) catch {};
                }
                if (std.mem.eql(u8, eo.subscription_id, "plaza-feed")) {
                    // Only when THIS subscription actually asked about the
                    // reader. A guest-era filter names nine strangers, and its
                    // EOSE says nothing at all about the account that signed in
                    // afterwards.
                    if (asked_about_me) {
                        if (activePubkey()) |me| {
                            // Who they follow, recorded against THIS relay.
                            // EOSE means "that is all I have", never "you have
                            // none": one relay that does not carry this list
                            // must not be able to authorize replacing it.
                            noteContactsAnsweredBy(index, me);
                        }
                    }
                }
                // Stored feed drained: now watch those notes' engagement.
                if (engagement_watching == 0 and feed_ids_len > 0 and std.mem.eql(u8, eo.subscription_id, "plaza-feed")) {
                    subscribeEngagement(relay, &feed_id_hex, feed_ids_len);
                    engagement_watching = feed_ids_len;
                    engagement_at = now_ms;
                }
            },
            .closed => |c| {
                // A relay saying no. NIP-01's CLOSED carries a reason, and
                // dropping it on the floor is what made a refused subscription
                // indistinguishable from a quiet one: a green chip, "Live", and
                // nothing arriving, for the rest of the connection, with no
                // retry and nothing written down.
                std.debug.print("plaza: [{s}] closed {s}: {s}\n", .{ url, c.subscription_id, c.message });
                if (std.mem.eql(u8, c.subscription_id, probe_sub)) {
                    // Only the latency reading is lost. Clear the pending sample
                    // so the next message asks again rather than waiting forever
                    // for an EOSE that is not coming.
                    probe_at = 0;
                } else if (std.mem.eql(u8, c.subscription_id, "plaza-feed")) {
                    // The feed is what this connection is FOR, so end it and let
                    // the reconnect ladder decide when to ask again. A relay that
                    // refuses this filter now will usually refuse it in three
                    // seconds too, which is exactly why that delay widens.
                    return error.FeedSubscriptionClosed;
                }
                // The inbox and the engagement subscription are refused on their
                // own terms. Either one is worth reporting and neither is worth
                // tearing down a working feed for.
            },
            else => {},
        }
    }
}

test {
    _ = @import("tests.zig");
}
